COLLDATA("abudawud","ur",[[4475,"اس سند سے بھی محمد بن اسحاق سے یہی حدیث مروی ہے اس میں انہوں نے عائشہ رضی اللہ عنہا کا ذکر نہیں کیا ہے اس میں ہے: آپ نے دو مردوں اور ایک عورت کو جنہوں نے بری بات منہ سے نکالی تھی (کوڑے لگانے کا) حکم دیا، وہ حسان بن ثابت رضی اللہ عنہ اور مسطح بن اثاثہ رضی اللہ عنہ تھے نفیل کہتے ہیں: اور لوگ کہتے ہیں کہ عورت حمنہ بنت جحش رضی اللہ عنہا تھیں۔","حسن",{"u2":"محمد بن اسحاق نے یہ روایت بیان کی اور اس میں سیدہ عائشہ رضی اللہ عنہا ا کا ذکر نہیں کیا، بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے دو مردوں اور ایک عورت کو جو اس تہمت میں شریک تھے ‘ کے متعلق (حد لگانے کا) حکم دیا۔ یعنی حسان بن ثابت اور مسطح بن اثاثہ۔ نفیلی نے کہا کہ عورتوں میں حمنہ بنت حجش کا ذکر کرتے ہیں۔","f2":"تہمت کی حداسی درے(کوڑے) ہیں۔\nصحابہ کرام رضی اللہ عنہ معصوم عن الخطانہ تھےاور ہمارے کئے ضروری ہے کہ ان کے لئے ہمیشہ دعا کیا کریں۔(ربنااغفرلنا ولل خوانناالذين سبقونا بالا يمان ولا تجعل في قلو بنا غلا للذين امنوا ربناانك رءوف رحيم)"}],[4476,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے شراب کے حد کی تعیین نہیں فرمائی، ابن عباس رضی اللہ عنہما کہتے ہیں کہ ایک شخص نے شراب پی اور بدمست ہو کر جھومتے ہوئے راستے میں لوگوں کو چلتے ملا تو اسے پکڑ کر وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس لے کر آئے جب وہ عباس رضی اللہ عنہ کے گھر کے سامنے ہوا تو چھڑا کر بھاگا اور عباس رضی اللہ عنہ کے مکان میں جا گھسا، اور ان سے چمٹ گیا، پھر یہ قصہ نبی اکرم صلی اللہ علیہ وسلم سے ذکر کیا گیا تو آپ ہنسے، اور صرف اتنا فرمایا: \"کیا اس نے ایسا کیا ہے؟\" آپ نے اس کے بارے میں کوئی اور حکم نہیں دیا۔ ابوداؤد کہتے ہیں: حسن بن علی کی اس حدیث کی روایت میں اہل مدینہ منفرد ہیں۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے شراب نوشی کی حد متعین نہیں کی تھی۔ ابن عباس رضی اللہ عنہ کہتے ہیں کہ ایک آدمی نے شراب پی لی، اس سے اسے نشہ ہو گیا اور گلی میں لہرا لہرا کر چلنے لگا۔ پھر اسے نبی کریم صلی اللہ علیہ وسلم کے ہاں لے چلے۔ جب وہ سیدنا عباس رضی اللہ عنہ کے گھر کے سامنے آیا تو وہ گھوم کر ان کے گھر میں چلا گیا اور ان سے جا چمٹا۔ نبی کریم صلی اللہ علیہ وسلم کو یہ بتایا گیا تو آپ ہنس پڑے اور پوچھا ” کیا واقعی اس نے اس طرح کیا ہے؟ “ اور پھر اس کے بارے میں کچھ نہیں فرمایا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ حسن بن علی کی اس حدیث کی روایت میں اہل مدینہ متفرو ہیں۔"}],[4477,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا جس نے شراب پی رکھی تھی، تو آپ نے فرمایا: \"اسے مارو\" ابوہریرہ رضی اللہ عنہ کہتے ہیں: تو ہم میں سے کسی نے ہاتھ سے، کسی نے جوتے سے، اور کسی نے کپڑے سے، اسے مارا، پھر جب فارغ ہوئے تو کسی نے کہا: اللہ تجھے رسوا کرے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا نہ کہو اس کے خلاف شیطان کی مدد نہ کرو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک آدمی لایا گیا جس نے شراب پی تھی، تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اسے مارو۔ “ سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں: ہم میں سے کسی نے اسے ہاتھ سے مارا، کسی نے جوتے سے مارا اور کسی نے کپڑے سے مارا۔ جب وہ آدمی وہاں سے چلا تو قوم میں سے کسی نے کہہ دیا اللہ تجھے رسوا کرے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اس طرح مت کہو۔ اس کے خلاف شیطان کی مدد مت کرو۔ “","f2":"انسان خطا کا پتلا ہے چاہئے کہ خطاکار کواحسن انداز سے نصیحت کی جائے۔ اس انداز کی ڈانٹ ڈپٹ کہ اس کے منفی جذبات کوابھارے مناسب نہیں، اس سے گویا شیطان کی مدد ہوتی ہے۔"}],[4478,"ابن الہاد سے اسی سند سے اسی مفہوم کی روایت آئی ہے اس میں ہے کہ اسے مار چکنے کے بعد رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب سے فرمایا: \"تم لوگ اسے زبانی عار دلاؤ\"، تو لوگ اس کی طرف یہ کہتے ہوئے متوجہ ہوئے: \"نہ تو تو اللہ سے ڈرا، نہ اس سے خوف کھایا نہ رسول اللہ صلی اللہ علیہ وسلم سے شرمایا\" پھر لوگوں نے اسے چھوڑ دیا، اور اس کے آخر میں ہے: \"لیکن یوں کہو: اے اللہ اس کو بخش دے، اس پر ر حم فرما\" کچھ لوگوں نے اس سیاق میں کچھ کمی بیشی کی ہے۔","صحیح",{"u2":"یحییٰ بن ایوب، حیوہ بن شریح اور ابن لہیعہ نے ابن ہاد سے اس کی سند سے مذکورہ بالا حدیث کے ہم معنی بیان کیا۔ اس روایت میں مارنے کے ذکر کے بعد یوں ہے کہ پھر رسول اللہ صلی اللہ علیہ وسلم نے صحابہ سے فرمایا ” اسے ذرا شرم دلاؤ، تنبیہ کرو۔ “ چنانچہ وہ اسے اس طرح کہنے لگے۔ تجھے اللہ کا خوف نہ آیا۔ تو اللہ سے ڈرا نہیں۔ تجھے اللہ کے رسول صلی اللہ علیہ وسلم سے حیاء نہ آئی۔ پھر اس کو چھوڑ دیا اور روایت کے آخر میں ہے۔ ” لیکن یوں کہو: اے اللہ! اس کو معاف کر دے۔ اے اللہ! اس پر رحم فر۔ “ اور بعض راویوں نے اسی قسم کے الفاظ زیادہ کیے ہیں۔","f2":"حد شرعی لگ جانے کے بعد ایسےشخص کےلئےاستغفار اور رحمت کی دعا کرنی چاہئے۔ برے انداز میں تزلیل کے الفاظ بولنا جائز نہیں، کیونکہ اس سے بعض اوقات منفی ردعمل کی نفسیات کوانگیخت ملتی ہےاور پھر کئی لوگ اپنی برائی سے باز آنے کی بجائے اس پر اور ڈھیٹ ہو جاتے ہیں۔ اسی مفہوم کو شیطان کی مدد سے تعبیر کیا گیا ہے۔"}],[4479,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے شراب پینے پر کھجور کی ٹہنیوں اور جوتوں سے مارا، اور ابوبکر رضی اللہ عنہ نے چالیس کوڑے لگائے، پھر جب عمر رضی اللہ عنہ خلیفہ ہوئے تو آپ نے لوگوں کو بلایا، اور ان سے کہا: لوگ گاؤں سے قریب ہو گئے ہیں (اور مسدد کی روایت میں ہے) بستیوں اور گاؤں سے قریب ہو گئے ہیں (یعنی شراب زیادہ پینے لگے ہیں) تو اب شراب کی حد کے بارے میں تمہاری کیا رائے ہے؟ تو عبدالرحمٰن بن عوف نے ان سے کہا: ہماری رائے یہ ہے کہ سب سے ہلکی جو حد ہے وہی آپ اس میں مقرر کر دیں، چنانچہ اسی (۸۰) کوڑے مارنے کا حکم ہوا (کیونکہ سب سے ہلکی حد یہی حدقذف تھی) ۔ ابوداؤد کہتے ہیں: اسے ابن ابی عروبہ نے قتادہ سے، قتادہ نے نبی اکرم صلی اللہ علیہ وسلم سے مرفوعاً روایت کیا ہے کہ آپ صلی اللہ علیہ وسلم نے کھجور کی ٹہنیوں اور جوتوں سے چالیس مار ماریں۔ اور اسے شعبہ نے قتادہ سے، قتادہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کیا ہے کہ آپ نے کھجور کی دو ٹہنیوں سے چالیس کے قریب مار ماریں۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے شراب نوشی کی حد میں کھجور کی چھڑیوں اور جوتوں سے مارا ہے۔ اور سیدنا ابوبکر رضی اللہ عنہ نے چالیس درے (کوڑے) لگائے۔ جب سیدنا عمر رضی اللہ عنہ خلیفہ ہوئے تو انہوں نے صحابہ کو بلایا اور ان سے مشورہ چاہا کہ لوگ اپنے کھیتوں اور زمینوں میں چلے گئے ہیں۔ (یعنی جہاں کھجوریں اور انگور وغیرہ کی فراوانی ہے اور وہ شراب پینے لگے ہیں)۔ مسدد کے الفاظ میں ہے کہ لوگ بستیوں اور زمینوں میں چلے گئے ہیں۔ تو تم لوگ شراب کی حد کے بارے میں کیا کہتے ہو؟ تو سیدنا عبدالرحمٰن بن عوف رضی اللہ عنہ نے کہا: ہم سمجھتے ہیں کہ آپ اسے سب سے ہلکی حد کی مانند کر دیں۔ چنانچہ انہوں نے اس میں اسی درے (کوڑے) لگائے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ابن ابی عروبہ نے بواسطہ قتادہ نبی کریم صلی اللہ علیہ وسلم سے یہ حدیث بیان کی کہ آپ صلی اللہ علیہ وسلم نے کھجور کی چھڑیوں اور جوتوں سے چالیس ضربیں لگائیں۔ جبکہ شعبہ نے قتادہ سے بواسطہ سیدنا انس رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے روایت کیا تو کہا کہ آپ صلی اللہ علیہ وسلم نے کھجور کی دو شاخوں سے تقریباً چالیس ضربیں لگائیں۔","f2":"فقہاء کے نزدیک حضرت عمر رجی اللہ عنہ کے اس عمل یں پہلی چالیس ضربوں کو حداورمزید چالیس کوتعزیر پر محمول کیا گیا ہے اور علمائے حق وفقہائے عظام امور شرعیہ میں اپنی مرضی سے کچھ نہیں کہتے ہیں بلکہ اجتہادی امورمیں اصحاب علم ورائےسے گہرامشورہ کرنے کے بعد کوئی فیصلہ کرتے ہیں۔"}],[4480,"حضین بن منذر رقاشی ابوساسان کہتے ہیں کہ میں عثمان بن عفان رضی اللہ عنہ کے پاس موجود تھا کہ ولید بن عقبہ کو ان کے پاس لایا گیا، اور حمران اور ایک اور شخص نے اس کے خلاف گواہی دی، ان میں سے ایک نے گواہی دی کہ اس نے شراب پی ہے، اور دوسرے نے گواہی دی کہ میں نے اسے (شراب) قے کرتے دیکھا ہے، تو عثمان نے کہا: جب تک پیئے گا نہیں قے نہیں کر سکتا، پھر انہوں نے علی رضی اللہ عنہ سے کہا: تم اس پر حد قائم کرو، تو علی نے حسن رضی اللہ عنہ سے کہا: تم اس پر حد قائم کرو، تو حسن نے کہا: جو خلافت کی آسانیوں اور خیرات کا ذمہ دار رہا ہے وہی اس کی سختیوں اور برائیوں کا بھی ذمہ دار ہے، پھر علی رضی اللہ عنہ نے عبداللہ بن جعفر سے کہا: تم اس پر حد قائم کرو، تو انہوں نے کوڑا لے کر اسے مارنا شروع کیا، اور علی رضی اللہ عنہ گننے لگے، تو جب چالیس کوڑے ہوئے تو علی رضی اللہ عنہ نے کہا: بس کافی ہے، اس لیے کہ رسول اللہ صلی اللہ علیہ وسلم نے چالیس کوڑے ہی مارے ہیں، اور میرا خیال ہے انہوں نے یہ بھی کہا کہ ابوبکر رضی اللہ عنہ نے بھی چالیس کوڑے مارے ہیں، اور عمر رضی اللہ عنہ نے اسی، اور سب سنت ہے، اور یہ چالیس کوڑے مجھے زیادہ پسند ہیں۔","صحیح",{"u2":"حضین بن منذر رقاشی ابو ساسان کہتے ہیں کہ میں سیدنا عثمان رضی اللہ عنہ کے ہاں حاضر تھا کہ ولید بن عقبہ کو لایا گیا۔ تو حمران اور ایک دوسرے آدمی نے اس پر گواہی دی۔ ایک نے کہا کہ میں نے اس کو شراب پیتے دیکھا ہے اور دوسرے نے کہا کہ میں نے اس کو قے کرتے دیکھا ہے۔ تو سیدنا عثمان رضی اللہ عنہ نے کہا: اس نے شراب پی تبھی قے کی۔ پھر سیدنا علی رضی اللہ عنہ سے کہا کہ اس کو حد لگاؤ۔ سیدنا علی رضی اللہ عنہ نے سیدنا حسن رضی اللہ عنہ سے کہا کہ اس کو حد لگاؤ۔ تو سیدنا حسن رضی اللہ عنہ نے کہا کہ اس کی حرارت اسی کے حوالے کریں جو اس کی ٹھنڈک سے لطف اندوز ہوتا ہے۔ (اشارہ تھا کہ سیدنا عثمان رضی اللہ عنہ ہی کو یہ کڑوا کسیلا کام کرنا چاہیئے)۔ پھر سیدنا علی رضی اللہ عنہ نے عبداللہ بن جعفر سے کہا کہ اس کو حد لگاؤ۔ تو اس نے کوڑا لیا اور مارنے لگے اور سیدنا علی رضی اللہ عنہ گنتے جاتے تھے۔ جب چالیس کو پہنچے تو کہا کہ بس، کافی ہے۔ نبی کریم صلی اللہ علیہ وسلم نے چالیس ضربیں ماری تھیں۔ (حضین نے کہا) میرا خیال ہے کہ یوں کہا: ابوبکر رضی اللہ عنہ نے چالیس اور عمر رضی اللہ عنہ نے اسی ضربیں ماریں اور سب ہی سنت ہے اور یہ مجھے زیادہ محبوب ہے۔"}],[4481,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ نے شراب میں چالیس کوڑے ہی مارے، اور عمر رضی اللہ عنہ نے اسی کوڑے پورے کئے، اور یہ سب سنت ہے۔ ابوداؤد کہتے ہیں: اصمعی کہتے ہیں: «من تولى قارها ول شديدها من تولى هينها» کے معنی یہ ہیں جو خلافت کی آسانیوں کا ذمہ دار رہا ہے اسی کو اس کی دشواریوں کا ذمہ دار رہنا چاہیئے۔ ابوداؤد کہتے ہیں: یہ اپنی قوم کے سردار تھے یعنی حضین بن منذر ابوساسان۔","صحیح",{"u2":"حضین بن منذر، سیدنا علی رضی اللہ عنہ سے روایت کرتے ہیں کہ شراب کی حد میں رسول اللہ صلی اللہ علیہ وسلم اور سیدنا ابوبکر رضی اللہ عنہ نے چالیس ضربیں ماریں اور سیدنا عمر رضی اللہ عنہ نے ان کو اسی (80) سے پورا کیا، اور سب ہی سنت ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اصمعی نے «ول حارها *** الخ» کا مفہوم یہ بیان کیا کہ اس معاملے کی سختی اور شدت اسی کے سپرد ہونی چاہیئے جو اس کی نرمی اور راحت سے مستفید ہوتا ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ حضین بن منذر ابوساسان اپنی قوم کا سردار تھا۔"}],[4482,"معاویہ بن ابی سفیان رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب وہ شراب پئیں تو انہیں کوڑے لگاؤ، پھر پئیں تو پھر کوڑے لگاؤ، پھر پئیں تو پھر کوڑے لگاؤ، پھر پئیں تو انہیں قتل کر دو\"۔","حسن صحیح",{"u2":"سیدنا معاویہ بن ابوسفیان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” (شرابی) جب شراب پئیں تو انہیں درے لگاؤ، پھر اگر پئیں تو درے لگاؤ، پھر اگر پئیں تو درے لگاؤ پھر اگر پئیں تو قتل کر دو۔ “","f2":"امام ترمذی رحمتہ اللہ کتاب العلل میں لکھتے ہیں کہاس حدیث کے ترک یعنی منسوخ ہونے پر علماء کا احماع ہے۔اور اس حدیث کی تاویل یہ ہے کہ اس سے مراد سخت مار ہے۔ اور اگلی حدیث(4485) کو اس کا نا سخ سمجھا جاتا ہے۔ علامہ زیلعی رحمۃاللہ علیہ نے بحوالہ ابن حبان لکھا ہے کہ قتل کاحکم اس کے لیے ہے جو اس کی حلت کا قائل ہو اور حرمت کوقبول نہ کرتا ہو۔ (عون المعبود)"}],[4483,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایسے ہی فرمایا ہے، اس میں یہ ہے کہ میرا خیال ہے کہ پانچویں بار میں فرمایا: \"پھر اگر وہ پئے تو اسے قتل کر دو\"۔ ابوداؤد کہتے ہیں: اسی طرح ابوغطیف کی روایت میں پانچویں بار کا ذکر ہے۔","ضعیف الإسناد",{"u2":"جناب نافع نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، اور مذکورہ بالا کے ہم معنی روایت کیا۔ انہوں نے کہا: میرا خیال ہے کہ پانچویں بار آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر پیے تو اسے قتل کر دو۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ابوغطیف کی روایت میں بھی پانچویں بار کا ذکر ہے۔"}],[4484,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"شرابی جب نشہ سے مست ہو جائے تو اسے کوڑے مارو، پھر اگر نشہ سے مست ہو جائے تو اسے پھر کوڑے مارو، پھر اگر نشہ سے مست ہو جائے تو اسے پھر کوڑے مارو، اور اگر چوتھی بار پھر ایسا ہی کرے تو اسے قتل کر دو\"۔ ابوداؤد کہتے ہیں: اسی طرح عمر بن ابی سلمہ کی روایت ہے جسے وہ اپنے والد سے اور ابوسلمہ ابوہریرہ سے اور ابوہریرہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ کوئی شراب پئے تو اسے کوڑے لگاؤ، اور اگر چوتھی بار پھر ویسے ہی کرے تو اسے قتل کر دو۔ ابوداؤد کہتے ہیں: اسی طرح سہیل کی حدیث ہے جسے وہ ابوصالح سے اور ابوصالح ابوہریرہ سے اور ابوہریرہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ اگر وہ چوتھی دفعہ پئے تو اسے قتل کر دو\"۔ اور اسی طرح ابن ابی نعم کی روایت بھی ہے جسے وہ ابن عمر رضی اللہ عنہما سے اور ابن عمر نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ اور اسی طرح عبداللہ بن عمرو رضی اللہ عنہما اور شرید رضی اللہ عنہ کی مرفوع روایت بھی ہے، اور جدلی کی روایت میں ہے جسے وہ معاویہ رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ تیسری یا چوتھی بار پھر کرے تو اسے قتل کر دو\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب وہ نشے سے مست ہو تو اسے درے لگاؤ، پھر اگر مست ہو تو درے لگاؤ، پھر اگر مست ہو تو درے لگاؤ، اگر چوتھی بار اعادہ کرے، تو اسے قتل کر دو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ عمر بن ابی سلمہ کی روایت میں بھی ایسے ہی ہے جو وہ اپنے والد سے، وہ سیدنا ابوہریرہ رضی اللہ عنہ سے اور وہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں ” جب وہ شراب پیے تو اسے کوڑے لگاؤ اگر چوتھی بار پیے تو اسے قتل کر دو۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ «سهيل عن أبي صالح عن أبي هريرة عن النبي صلى الله عليه وسلم» کی سند سے بھی یہ مروی ہے ” اگر چوتھی بار پییں تو انہیں قتل کر دو۔ “ ایسے ہی ابن ابی نعم کی روایت میں ہے جو بواسطہ ابن عمر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے نقل ہوئی ہے۔ اسی طرح عبداللہ بن عمرو رضی اللہ عنہ اور شرید نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے۔ اور جدلی (عبد بن عبد) کی روایت جو بواسطہ سیدنا معاویہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے منقول ہے اس میں ہے ” اگر تیسری یا چوتھی بار پیے تو اسے قتل کر دو۔ “","f2":"مست ہونے سے مراد شراب پینا ہے۔ فی الواقع مست ہوناشرط نہیں ہے جیسےکہ دیگر بہت سی احادیث میں آتا ہے۔ صرف شراب پینا ثابت ہو جائے تو اس پر حد لگے گی علمائے احناف اس مسئلے میں منفرد ہیں بقول ان کے انگور کی شراب تھوڑی پیے یا زیادہ تو حرام اور قابل حد ہے۔ لیکن انگور کے علاوہ دیگر اشیائ کی بنی ہوئی شرابوں میں اس قدر پیے کہ مست ہو جائے تو حرام ہے تو حد لگےگی البتہ ان کا اتنی مقدار میں پینا جائز ہے جس نے نشہ پیدا نہ ہو۔ دیگرائمہ میں سے کسی نے ان کی تائید نہیں کی ہے، بلکہ نشہ آور خواہ کسی نوع سے ہو اس کا قلیل یاکثیر سب حرام ہے اور قابل حد ہے۔ نشے سے مست ہونا شرط نہیں، علاوہ ازیں احادیث میں اس کی بابت رسول اللہ صلی اللہ علیہ وسلم نے فرمایاہے(ما اسكر كثيره فقليله حرام) جس چیز کی کثیر مقدارنشہ آور ہو اسکی قلیل مقدار بھی حرام ہے (سنن ابی داور الا شربة حديث:٣٦٨١) لہذا ہر نشہ آور چیز اس کی نوعیت خواہ کچھ ہو وہ مقدار میں تھوڑی ہو یا زیادہ حرام ہی ہے اور یہ کہنا یہ سمجھنا کہ انگورکی ہوتوحرام ہے اور دوسری قسم سے ہو تو اسےاتنی مقدار میں پینا حلال ہے جس سےنشہ پیدا نہ ہو فرمان رسول کے خلاف ہے۔"}],[4485,"قبیصہ بن ذؤیب رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شراب پئے تو اسے کوڑے لگاؤ، اگر پھر پئے تو پھر کوڑے لگاؤ، اگر پھر پئے تو پھر کوڑے لگاؤ، پھر اگر وہ تیسری یا چوتھی دفعہ پئے تو اسے قتل کر دو\" تو ایک شخص لایا گیا جس نے شراب پی رکھی تھی، تو آپ نے اسے کوڑے لگائے، پھر اسے لایا گیا، آپ نے پھر اسے کوڑے لگائے، پھر اسے لایا گیا، تو آپ نے اسے کوڑے لگائے، پھر لایا گیا تو پھر آپ نے کوڑے ہی لگائے، اور قتل کا حکم اٹھا دیا اور رخصت ہو گئی۔ سفیان کہتے ہیں: زہری نے اس حدیث کو بیان کیا اور ان کے پاس منصور بن معتمر اور مخول بن راشد موجود تھے تو انہوں نے ان دونوں سے کہا: تم دونوں اہل عراق کے لیے یہ حدیث یہاں سے تحفے میں لیتے جانا۔ ابوداؤد کہتے ہیں: اس حدیث کو شرید بن سوید، شرحبیل بن اوس، عبداللہ بن عمرو، عبداللہ بن عمر، ابوغطیف کندی اور ابوسلمہ بن عبدالرحمٰن نے ابوہریرہ سے روایت کیا ہے۔","ضعیف",{"u2":"سیدنا قبیصہ بن ذویب رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شراب پیے تو اسے کوڑے لگاؤ، اگر پھر پیے تو کوڑے لگاؤ، اگر پھر تیسری یا چوتھی بار پیے تو اسے قتل کر دو۔ “ پھر آپ کے پاس ایک آدمی لایا گیا جس نے شراب پی تھی تو آپ نے اسے کوڑے لگائے۔ پھر دوبارہ لایا گیا تو کوڑے لگائے، پھر لایا گیا تو کوڑے لگائے، پھر لایا گیا تو کوڑے لگائے اور قتل چھوڑ دیا تو اس طرح قتل سے رخصت مل گئی۔ سفیان کہتے ہیں کہ زہری نے یہ روایت اس وقت بیان کی جب منصور بن معتمر اور مخول بن راشد ان کے پاس بیٹھے تھے۔ زہری نے ان سے کہا کہ اہل عراق کے پاس یہ حدیث تحفہ لے جانا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو شرید بن سوید، شرحبیل بن اوس، عبداللہ بن عمرو، عبداللہ بن عمر، ابو غطیف کندی اور ابوسلمہ بن عبدالرحمٰن نے سیدنا ابوہریرہ رضی اللہ عنہ کے واسطے سے نقل کیا ہے۔"}],[4486,"علی رضی اللہ عنہ کہتے ہیں کہ میں جس پر حد قائم کروں اور وہ مر جائے تو میں اس کی دیت نہیں دوں گا، یا میں اس کی دیت دینے والا نہیں سوائے شراب پینے والے کے، کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے شراب پینے والے کی کوئی حد مقرر نہیں کی ہے، یہ تو ایک ایسی چیز ہے جسے ہم نے خود مقرر کی ہے۔","صحیح",{"u2":"امیرالمؤمنین سیدنا علی رضی اللہ عنہ کہتے ہیں کہ میں کسی پر حد قائم کروں (اور وہ مر جائے) تو کسی کی دیت نہ دوں سوائے شراب نوش کے۔ بلاشبہ رسول اللہ صلی اللہ علیہ وسلم نے اس میں کوئی حد متعین نہیں فرمائی تھی۔ یہ حد ہم نے (مشورے سے) طے کی ہے۔","f2":"اس مسئلے میں پچھلا باب لاخطہ ہو۔ صحابہ کرام رضی اللہ عنہ اسبات سے بالاتر تھے کہ شریعت میں کوئی چیز محض اپنی رائے سے ناٖفذ کریں۔ انہوں نے شرعی اصولوں کے تحت اجتہاد اور مشورے سے یہ حد متعین کی ہے۔ اور یہ اصولبالکل حق ہے کہ حد لگانے میں مجرم کی صحت اور برداشت کا خیال رکھا جانا ضروری ہے۔"}],[4487,"عبدالرحمٰن بن ازہر رضی اللہ عنہ کہتے ہیں کہ گویا میں اس وقت رسول اللہ صلی اللہ علیہ وسلم کو دیکھ رہا ہوں آپ کجاؤں کے درمیان میں کھڑے تھے، خالد بن ولید رضی اللہ عنہ کا کجاوہ ڈھونڈ رہے تھے، آپ اسی حالت میں تھے کہ اتنے میں ایک شخص لایا گیا جس نے شراب پی رکھی تھی، تو آپ صلی اللہ علیہ وسلم نے لوگوں سے کہا: \"اسے مارو\"، تو کسی نے جوتے سے، کسی نے چھڑی سے، اور کسی نے کھجور کی ٹہنی سے اسے مارا (ابن وہب کہتے ہیں) «ميتخة» کے معنی کھجور کی تر ٹہنی کے ہیں پھر رسول اللہ صلی اللہ علیہ وسلم نے زمین سے مٹی لی اور اس کے چہرے پر ڈال دی۔","حسن صحیح",{"u2":"سیدنا عبدالرحمٰن بن ازہر رضی اللہ عنہ سے روایت ہے وہ کہتے ہیں گویا کہ میں اب بھی رسول اللہ صلی اللہ علیہ وسلم کو دیکھ رہا ہوں، آپ پالانوں میں کھڑے سیدنا خالد بن ولید رضی اللہ عنہ کا پالان تلاش کر رہے تھے کہ اچانک آپ صلی اللہ علیہ وسلم کے پاس ایک آدمی لایا گیا جس نے شراب پی رکھی تھی۔ آپ صلی اللہ علیہ وسلم نے لوگوں سے کہا ” اس کو مارو۔ “ چنانچہ بعض نے اس کو جوتوں سے مارا، بعض نے لاٹھی سے اور بعض نے «ميتخة» سے۔ ابن وہب نے وضاحت کی کہ اس سے مراد کھجور کی تروتازہ چھڑی ہے۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے زمین سے کچھ مٹی لی اور اس کے منہ پر ماری۔"}],[4488,"عبدالرحمٰن بن ازہر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک شرابی لایا گیا، اور آپ حنین میں تھے، آپ نے اس کے منہ پر خاک ڈال دی، پھر اپنے اصحاب کو حکم دیا تو انہوں نے اسے اپنے جوتوں سے، اور جو چیزیں ان کے ہاتھوں میں تھیں ان سے مارا، یہاں تک کہ آپ فرمانے لگے: \"بس کرو، بس کرو\" تب لوگوں نے اسے چھوڑا، پھر رسول اللہ صلی اللہ علیہ وسلم وفات پا گئے تو آپ کے بعد ابوبکر رضی اللہ عنہ بھی شراب کی حد میں چالیس کوڑے مارتے رہے، پھر عمر رضی اللہ عنہ نے بھی اپنی خلافت کے شروع میں چالیس کوڑے ہی مارے، پھر خلافت کے اخیر میں انہوں نے اسی کوڑے مارے، پھر عثمان رضی اللہ عنہ نے کبھی اسی کوڑے اور کبھی چالیس کوڑے مارے، پھر معاویہ رضی اللہ عنہ نے اسی کوڑوں کی تعیین کر دی۔","صحیح",{"u2":"جناب عبداللہ بن عبدالرحمٰن بن ازہر اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک شرابی لایا گیا جبکہ آپ صلی اللہ علیہ وسلم حنین میں تھے تو آپ صلی اللہ علیہ وسلم نے اس کے منہ پر مٹی ماری۔ پھر آپ نے اپنے صحابہ سے فرمایا تو انہوں نے اس کو جوتوں سے اور جو ان کے ہاتھ میں تھا اس سے مارا، حتیٰ کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” بس کرو۔ “ تو وہ رک گئے۔ پھر رسول اللہ صلی اللہ علیہ وسلم کی وفات ہو گئی تو سیدنا ابوبکر رضی اللہ عنہ نے شراب پینے پر چالیس ضربیں لگائیں۔ پھر سیدنا عمر رضی اللہ عنہ نے بھی اپنے ابتدائی دور میں چالیس ضربیں ہی لگائیں اور آخری دور میں اسی لگانے لگے۔ پھر سیدنا عثمان رضی اللہ عنہ نے دونوں طرح عمل کیا، اسی بھی اور چالیس بھی۔ پھر سیدنا معاویہ رضی اللہ عنہ نے یہ حد اسی (80) دروں پر پختہ کر دی۔"}],[4489,"عبدالرحمٰن بن ازہر کہتے ہیں کہ میں نے فتح مکہ کے دوسرے دن صبح کو رسول اللہ صلی اللہ علیہ وسلم کو دیکھا میں ایک کمسن لڑکا تھا، لوگوں میں گھس کر آیا جایا کرتا تھا، آپ خالد بن ولید رضی اللہ عنہ کی قیام گاہ ڈھونڈ رہے تھے کہ اتنے میں ایک شرابی لایا گیا، آپ نے اسے مارنے کا حکم دیا، تو لوگوں کے ہاتھوں میں جو چیز بھی تھی اسی سے انہوں نے اس کی پٹائی کی، کسی نے اسے کوڑے سے، کسی نے لاٹھی سے، کسی نے جوتے سے پیٹا، اور رسول اللہ صلی اللہ علیہ وسلم نے اس کے منہ پر مٹی ڈال دی، پھر جب ابوبکر رضی اللہ عنہ کا زمانہ آیا تو ان کے پاس ایک شرابی لایا گیا تو انہوں نے لوگوں سے نبی اکرم صلی اللہ علیہ وسلم کی اس مار کے متعلق دریافت کیا جسے آپ نے مارا تھا تو لوگوں نے اس کا اندازہ لگایا کہ یہ چالیس کوڑے رہے ہوں گے، تو ابوبکر رضی اللہ عنہ نے اس کی حد چالیس کوڑے مقرر کر دی، پھر جب عمر رضی اللہ عنہ کا زمانہ آیا تو خالد بن ولید نے انہیں لکھا کہ لوگ کثرت سے شراب پینے لگے ہیں اور اس کی حد اور سزا کو کوئی اہمیت نہیں دیتے اور لکھا کہ لوگ آپ کے پاس ہیں ان سے پوچھ لیں، اس وقت ان کے پاس مہاجرین اولین موجود تھے، آپ نے ان سے پوچھا تو سب کا اس بات پر اتفاق ہو گیا کہ اسی کوڑے مارے جائیں، علی رضی اللہ عنہ نے کہا: آدمی جب شراب پیتا ہے تو بہتان باندھتا ہے اس لیے میری رائے یہ ہے کہ اس کی حد بہتان کی حد کر دی جائے۔","حسن",{"u2":"سیدنا عبدالرحمٰن بن ازہر رضی اللہ عنہ سے روایت ہے انہوں نے فرمایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فتح مکہ کی صبح کو دیکھا، میں اس موقع پر خوب جوان تھا، آپ صلی اللہ علیہ وسلم لوگوں کے درمیان میں سے جا رہے تھے اور سیدنا خالد بن ولید رضی اللہ عنہ کا پڑاؤ دریافت فر رہے تھے کہ ایک شرابی آپ صلی اللہ علیہ وسلم کے پاس لایا گیا۔ تو آپ نے لوگوں کو حکم دیا تو انہوں نے اس کو جو ان کے ہاتھ میں تھا، مارا۔ بعض نے کوڑا مارا، بعض نے لاٹھی ماری، بعض نے اپنا جوتا مارا اور رسول اللہ صلی اللہ علیہ وسلم نے اس پر مٹی پھینکی۔ پھر جب سیدنا ابوبکر رضی اللہ عنہ کا دور آیا تو ایک شراب نوش لایا گیا، تو انہوں نے صحابہ سے نبی کریم صلی اللہ علیہ وسلم کا عمل دریافت فرمایا کہ انہوں نے کس قدر مارا تھا۔ تو انہوں نے اس کا اندازہ چالیس ضربوں کا لگایا۔ چنانچہ سیدنا ابوبکر رضی اللہ عنہ نے چالیس ضربیں لگائیں۔ پھر جب سیدنا عمر رضی اللہ عنہ کا دور آیا تو سیدنا خالد بن ولید رضی اللہ عنہ نے ان کو لکھا کہ لوگ شراب پینے میں منہمک ہو گئے ہیں اور اس حد اور سزا کو وہ معمولی سمجھتے ہیں۔ انہوں نے کہا: صحابہ کرام آپ کے پاس ہیں ان سے دریافت کیجئیے۔ اور آپ کے پاس دور اول کے مہاجر صحابہ موجود تھے، تو آپ نے ان سے مشورہ کیا۔ انہوں نے اتفاق کیا کہ ایسے لوگوں کو اسی (80) ضربیں لگائی جائیں۔ سیدنا علی رضی اللہ عنہ نے کہا: تحقیق شرابی جب شراب پیتا ہے تو جھوٹ بولتا اور تہمت لگاتا ہے، سو میں سمجھتا ہوں کہ اس حد کو تہمت کی حد کی مانند کر دیا جائے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ عقیل بن خالد نے اس روایت کی سند میں زہری اور عبدالرحمٰن بن ازہر کے مابین عبداللہ بن عبدالرحمٰن بن ازہر عن ابیہ کا اضافہ کر دیا ہے۔"}],[4490,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مسجد میں قصاص لینے، اشعار پڑھنے اور حد قائم کرنے سے منع فرمایا ہے۔\n§وضاحت\nW","حسن",{"u2":"سیدنا حکیم بن حزام رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مسجد میں قصاص لینے، اشعار پڑھنے اور حدیں لگانے سے منع فرمایا ہے۔","f2":"1) یہ روایات سندا ضعیف ہے لیکن دیگر شواہد کی بنا پر حسن درجہ تک پہنچ جاتی ہے۔ ان شواہد کی وضاحت ہمارے فاضل محقق نے تخریج وتحقیق میں کی ہے علاوہ ازیں شیخ البانی رحمتہ اللہ نے اسے حسن کہا ہے۔\n2) مساجد اس غرض سے بنائی جاتی ہیں کہ ان میں نماز پڑھی جائے تلاوت قرآن ہواور اللہ کا ذکر کیا جائے۔ قصاص یا حدود اگرچہ شرعی امور ہیں مگران سےمسجدکا ادب قائم نہیں رہتا ہے۔ ای طرھ لغو اور بے ہودہ اشعار پڑھنا بھی ناجائز ہے۔ البتہ اللہ کی حمدوثناء رسول اللہ صلی اللہ علیہ وسلم کی نعت اور شرعی مضامین پر مشتمل اشعار پرھے اور سنے جاسکتے ہیں۔"}],[4491,"ابوبردہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوڑے دس سے زیادہ نہ مارے جائیں سوائے اللہ کی حدود میں سے کسی حد میں ۱؎\"۔\n§وضاحت\n۱؎ : تعزیر ایسی سزا کو کہتے ہیں جو حد سے کم ہو۔","صحیح",{"u2":"سیدنا ابوبردہ (ہانی بن دینار انصاری رضی اللہ عنہ) سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے ” اللہ کی متعینہ حدود کے علاوہ کسی جرم میں دس کوڑوں سے زیادہ نہ مارے جائیں۔ “"}],[4492,"جابر رضی اللہ عنہ بیان کرتے ہیں کہ انہوں نے ابوبردہ انصاری سے سنا ہے وہ کہہ رہے تھے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے پھر انہوں نے اسی مفہوم کی حدیث ذکر کی۔","صحیح",{"u2":"سیدنا ابوبردہ انصاری رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، اور مذکورہ بالا روایت کے ہم معنی بیان کیا۔","f2":"امام ابن قیم رحمتہ اللہ فرماتے ہیں کہ اس حدیث میں حدود اللہ سے مرادوہ اوامرد نواہی ہیں جن کا تعلق آداب سے ہوجیسے کہ باپ اپنے بچے کی تادیب کرتا ہے۔ امام مالک ابویوسف اور ابو ثور رحمتہ اللہ وگیرہ کہتے ہیں کہ تعزیز جرم کے مطابق ہوا کرتی ہے اور یہ کہ مجرم اسے کس حد تک برداشت کرسکتاہے۔ اور اس میں اصل چیز مصلحت کو پیش نظررکھنا ہوتا ہے اس لئے معروف حدود کی مقدار سے زیادہ مارنا جائز ہے۔ تفصیل کے لئے دیکھیے(تيسير العلام شرض عمدة الا حكام)"}],[4493,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب کوئی کسی کو مارے تو چہرے پر مارنے سے بچے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا &rdquo; جب تم میں سے کوئی شخص مارے تو چہرے پر نہ مارے۔ &ldquo;","f2":"اس حديث كو اس باب میں دوباره لانے سے یہ بتلانا مقصود ہے کہ جس طرح حج میں چہرے پر نہیں مارنا اسی طرح تعزیری سزا میں چہرہ زدکوب سے محفوظ رہنا چاہیے۔ واللہ اعلم"}],[4494,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ قریظہ اور نضیر دو (یہودی) قبیلے تھے، نضیر قریظہ سے زیادہ باعزت تھے، جب قریظہ کا کوئی آدمی نضیر کے کسی آدمی کو قتل کر دیتا تو اسے اس کے بدلے قتل کر دیا جاتا، اور جب نضیر کا کوئی آدمی قریظہ کے کسی آدمی کو قتل کر دیتا تو سو وسق کھجور فدیہ دے کر اسے چھڑا لیا جاتا، جب رسول اللہ صلی اللہ علیہ وسلم کی بعثت ہوئی تو نضیر کے ایک آدمی نے قریظہ کے ایک آدمی کو قتل کر دیا، تو انہوں نے مطالبہ کیا کہ اسے ہمارے حوالے کرو، ہم اسے قتل کریں گے، نضیر نے کہا: ہمارے اور تمہارے درمیان نبی اکرم صلی اللہ علیہ وسلم فیصلہ کریں گے، چنانچہ وہ لوگ آپ کے پاس آئے تو آیت «وإن حكمت فاحكم بينهم بالقسط» \"اگر تم ان کے درمیان فیصلہ کرو تو انصاف سے فیصلہ کرو\" اتری، اور انصاف کی بات یہ تھی کہ جان کے بدلے جان لی جائے، پھر آیت «أفحكم الجاهلية يبغون» \"کیا یہ لوگ جاہلیت کے فیصلہ کو پسند کرتے ہیں؟\" نازل ہوئی۔ ابوداؤد کہتے ہیں: قریظہ اور نضیر دونوں ہارون علیہ السلام کی اولاد ہیں۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ قریظہ اور نضیر (یہود کے دو قبیلے تھے) اور نضیر قریظہ کی بہ نسبت زیادہ معزز تھا۔ تو جب قریظہ کا کوئی آدمی نضیر کے کسی آدمی کو قتل کر دیتا تو اسے اس کے بدلے میں قتل کر دیا جاتا تھا۔ اور جب نضیر کا کوئی آدمی قریظہ کے آدمی کو قتل کر دیتا تو (مقتول کے ورثاء کو) ایک سو وسق کھجور دیت دیتا تھا۔ پھر جب نبی کریم صلی اللہ علیہ وسلم مبعوث ہوئے تو نضیر کے آدمی نے قریظہ کے ایک آدمی کو قتل کر دیا۔ تو قریظہ نے کہا: قاتل ہمارے حوالے کرو ہم اسے قتل کریں گے۔ نضیر نے کہا: ہمارے تمہارے درمیان نبی کریم صلی اللہ علیہ وسلم قاضی اور حکم ہیں۔ تو وہ لوگ آپ صلی اللہ علیہ وسلم کے پاس آئے۔ تو یہ آیات نازل ہوئیں &laquo;وإن حكمت فاحكم بينهم بالقسط&raquo; &rdquo; آپ اگر فیصلہ فرمائیں تو ان میں انصاف سے فیصلہ فرمائیں۔ &ldquo; اس میں &laquo;القسط&raquo; &rdquo; انصاف &ldquo; کا مفہوم &rdquo; جان کے بدلے جان &ldquo; ہے۔ پھر دوسری آیت نازل ہوئی &laquo;أفحكم الجاهلية يبغون&raquo; &rdquo; کیا بھلا یہ جاہلیت کا فیصلہ چاہتے ہیں؟ &ldquo; امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ قریظہ اور نضیر دونوں سیدنا ہارون علیہ السلام کی نسل سے ہیں۔","f2":"قصاص کا نظام بنو اسرائیل میں بھی موجود تھا اور انسانی جانیں سب برابر ہیں کسی قوم یاقبیلے کو کسی پر کوئی فضیلت نہیں۔ اسلام نے قبیلے اور برادری کی بنیاد پر برتری کےتصور کو ختم کردیااور ایمان وتقوی کو فضلیت کا معیار قرار دیا۔ نیز یہ روایت ہمارے فاضل محقق کے نزدیک سند صعیف،تاہم دیگرت محقیقن نے اسے صحیح کہا ہے۔"}],[4495,"ابورمثہ رضی اللہ عنہ کہتے ہیں کہ میں اپنے والد کے ساتھ نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا، آپ نے میرے والد سے پوچھا: \"یہ تمہارا بیٹا ہے؟\" میرے والد نے کہا: ہاں رب کعبہ کی قسم! آپ صلی اللہ علیہ وسلم نے فرمایا: \"سچ مچ؟\" انہوں نے کہا: میں اس کی گواہی دیتا ہوں تو رسول اللہ صلی اللہ علیہ وسلم مسکرائے، کیونکہ میں اپنے والد کے مشابہ تھا، اور میرے والد نے قسم کھائی تھی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"سنو! نہ یہ تمہارے جرم میں پکڑا جائے گا، اور نہ تم اس کے جرم میں\" اور پھر رسول اللہ صلی اللہ علیہ وسلم نے یہ آیت پڑھی «ولا تزر وازرة وزر أخرى» \"کوئی جان کسی دوسری جان کا بوجھ نہ اٹھائے گی\" (الانعام: ۱۶۴، الاسراء: ۱۵، الفاطر: ۱۸) ۔","صحیح",{"u2":"سیدنا ابورمثہ (رفاعہ بن یثربی) رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ میں اپنے والد کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے ہاں حاضر ہوا۔ آپ صلی اللہ علیہ وسلم نے میرے والد سے پوچھا ” یہ تمہارا بیٹا ہے؟ “ (والد نے) کہا: ہاں، رب کعبہ کی قسم! آپ نے فرمایا ” سچ؟ “ میرے باپ نے کہا: میں اس کی گواہی دیتا ہوں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے ہنستے ہوئے تبسم فرمایا، کیونکہ میری مشابہت میرے باپ میں نمایاں تھی اور باپ نے میرے بارے میں قسم کھائی تھی۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” خبردار! نہ یہ تیرے کسی قصور میں پکڑا جائے گا اور نہ تو اس کے بدلے میں۔“ پھر آپ صلی اللہ علیہ وسلم نے یہ آیت پڑھی «ولا تزر وازرة وزر أخرى» ” کوئی جان کسی جان کا بوجھ نہ اٹھائے گی۔“","f2":"کوئی مجرم جرم کرکے بھاگ جائے اور حکومت اس کو پکڑ نہ سکے اس کے والدین یا عزیز واقارب کو پکڑ لینا صریح ظلم ہے،الا یہ کہ وہ اس کے جرم میں شریک ہوں یا اسے بھگانے یا چھپانے والے ہوں اور یہ بات اسلامی معاشرے اور اسلامی قانون کی ہے جب لوگ شریعت کے پابند ہوں تو شریعت بھی ان کی پابند نہیں ہو سکتی۔"}],[4496,"ابوشریح خزاعی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کو (اپنے کسی رشتہ دار کے) قتل ہونے، یا زخمی ہونے کی تکلیف پہنچی ہو اسے تین میں سے ایک چیز کا اختیار ہو گا: یا تو قصاص لے لے، یا معاف کر دے، یا دیت لے لے، اگر وہ ان کے علاوہ کوئی چوتھی بات کرنا چاہے تو اس کا ہاتھ پکڑ لو، اور جس نے ان (اختیارات) میں زیادتی کی تو اس کے لیے درد ناک عذاب ہے\"۔","ضعیف",{"u2":"سیدنا ابوشریح خزاعی روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کسی کا کوئی قتل ہو گیا ہو یا اس کا کوئی عضو کٹ گیا ہو تو اسے تین میں سے ایک کا اختیار ہے یا تو قصاص (بدلہ) لے یا معاف کر دے یا دیت لے لے، اور جو کوئی چوتھی بات چاہے تو اس کے ہاتھ پکڑ لو، اور جو کوئی اس کے بعد زیادتی کرے تو اس کے لیے درد ناک عذاب ہے۔“"}],[4497,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ جب بھی نبی اکرم صلی اللہ علیہ وسلم کے پاس کوئی ایسا مقدمہ لایا جاتا جس میں قصاص لازم ہوتا تو میں نے آپ کو یہی دیکھا کہ (پہلے) آپ اس میں معاف کر دینے کا حکم دیتے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ کہتے ہیں، میں نے دیکھا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جب بھی کوئی ایسا مقدمہ لایا جاتا جس میں قصاص ہوتا تو آپ صلی اللہ علیہ وسلم معاف کرنے کا فرماتے۔","f2":"قاضی اورحاکم صاحب کا معاملہ کو معاف کرنےکی ترغیب دے سکتے ہیں ازخود معاف کرنے کا کوئی حق نہیں رکھتے۔ اگر معاف کریں تو بہت بڑا ظلم ہے جیسے کہ ہمارے حکومتوں کا معمول ہے۔"}],[4498,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے زمانے میں ایک شخص قتل کر دیا گیا تو یہ مقدمہ نبی اکرم صلی اللہ علیہ وسلم کی عدالت میں پیش کیا گیا، آپ نے اس (قاتل) کو مقتول کے وارث کے حوالے کر دیا، قاتل کہنے لگا: اللہ کے رسول! اللہ کی قسم! میرا ارادہ اسے قتل کرنے کا نہ تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے وارث سے فرمایا: \"سنو! اگر یہ سچا ہے اور تم نے اسے قتل کر دیا، تو تم جہنم میں جاؤ گے\" یہ سن کر اس نے قاتل کو چھوڑ دیا، اس کے دونوں ہاتھ ایک تسمے سے بندھے ہوئے تھے، وہ اپنا تسمہ گھسیٹتا ہوا نکلا، تو اس کا نام ذوالنسعۃ یعنی تسمہ والا پڑ گیا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ایک آدمی قتل ہو گیا اور اس کا مقدمہ نبی کریم صلی اللہ علیہ وسلم کے سامنے پیش گیا گیا تو آپ نے قاتل کو مقتول کے وارث کے حوالے کر دیا۔ قاتل نے کہا: اے اللہ کے رسول! اللہ کی قسم! میں نے اس کے قتل کا ارادہ نہیں کیا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے وارث سے فرمایا ” خبردار! اگر یہ سچا ہوا پھر تو نے اس کو قتل کر دیا تو، تو جہنم میں جائے گا۔ “ چنانچہ اس نے اس کو چھوڑ دیا۔ راوی نے بتایا کہ وہ قاتل چمڑے کی ایک لمبی پٹی سے بندھا ہوا تھا، چنانچہ وہ اپنی پٹی کو گھسیٹتا ہوا چلا گیا اور پھر اس کا نام ہی «ذوالنسعة» (پٹی والا) پڑ گیا۔"}],[4499,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس تھا کہ اتنے میں ایک قاتل لایا گیا، اس کی گردن میں تسمہ تھا آپ نے مقتول کے وارث کو بلوایا، اور اس سے پوچھا: \"کیا تم معاف کرو گے؟\" اس نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو کیا دیت لو گے؟\" اس نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو کیا تم قتل کرو گے؟\" اس نے کہا: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اچھا لے جاؤ اسے\" چنانچہ جب وہ (اسے لے کر) چلا تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"کیا تم اسے معاف کرو گے؟\" اس نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم دیت لو گے؟\" اس نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم قتل کرو گے؟\" اس نے کہا: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے لے جاؤ\" چوتھی بار میں آپ صلی اللہ علیہ وسلم نے فرمایا: \"سنو! اگر تم اسے معاف کر دو گے تو یہ اپنا اور مقتول دونوں کا گناہ اپنے سر پر اٹھائے گا\" یہ سن کر اس نے اسے معاف کر دیا۔ وائل کہتے ہیں: میں نے اسے دیکھا وہ اپنے گلے میں پڑا تسمہ گھسیٹ رہا تھا۔","صحیح",{"u2":"سیدنا وائل بن حجر رضی اللہ عنہ کا بیان ہے کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر تھا کہ ایک قاتل لایا گیا اس کی گردن میں چمڑے کی ایک پٹی (بندھی ہوئی) تھی۔ آپ صلی اللہ علیہ وسلم نے مقتول کے ولی کو بلایا اور اس سے کہا &rdquo; کیا تم معاف کرتے ہو؟ &ldquo; اس نے کہا: نہیں۔ آپ نے پوچھا &rdquo; کیا تم دیت لینا قبول کرتے ہو؟ &ldquo; اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا &rdquo; کیا قتل کرو گے؟ &ldquo; اس نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا &rdquo; جاؤ اسے لے جاؤ۔ &ldquo; پس جب اس نے پشت پھیری تو آپ صلی اللہ علیہ وسلم نے (پھر) پوچھا &rdquo; کیا معاف کرتے ہو؟ &ldquo; اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا &rdquo; کیا دیت لیتے ہو؟ &ldquo; اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے کہا &rdquo; کیا قتل کرو گے؟ &ldquo; اس نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا &rdquo; جاؤ لے جاؤ۔ &ldquo; پھر چوتھی بار فرمایا &rdquo; اگر تم اس کو معاف کر دو تو یہ اپنے اور اپنے مقتول دونوں کے گناہ اپنے سر لے گا۔ &ldquo; راوی نے کہا: چنانچہ اس نے اس کو معاف کر دیا۔ وائل کہتے ہیں کہ میں نے قاتل کو دیکھا کہ وہ اپنی پٹی گھسیٹے جا رہا تھا۔","f2":"1: اگر مجرم کے بھاگ جانے کا اندیشہ ہو تو اس کو باندھنا جائز ہے۔ 2: مقتول کے ولی کو تین باتوں میں سے صرف ایک اختیار ہے کہ معاف کردے یا دیت قبول کرلے قصاص لے۔ 3: حاکم اور قاضی کو جائز ہے کہ معاف کرنھ کی ترغیب دے 4: اگر قاتل قصاص میں قتل کیا جائے تو امید ہے کہ یہ اس کے لئے کفارہ بن جائے گا،بصورت دیگر اس کا معاملہ اللہ کے ہاتھ میں ہے۔"}],[4500,"اس سند سے بھی علقمہ بن وائل سے اسی مفہوم کی روایت مروی ہے۔","",{"u2":"جناب علقمہ بن وائل نے یہ روایت اپنی سند سے اور مذکورہ بالا کے ہم معنی روایت کی۔"}],[4501,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ ایک شخص ایک حبشی کو لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور کہنے لگا: اس نے میرے بھتیجے کو قتل کیا ہے، آپ نے اس سے پوچھا: \"تم نے اسے کیسے قتل کر دیا؟\" وہ بولا: میں نے اس کے سر پر کلہاڑی ماری اور وہ مر گیا، میرا ارادہ اس کے قتل کا نہیں تھا، آپ نے پوچھا: \"کیا تمہارے پاس مال ہے کہ تم اس کی دیت ادا کر سکو\" اس نے کہا: نہیں، آپ نے فرمایا: \"بتاؤ اگر میں تمہیں چھوڑ دوں تو کیا تم لوگوں سے مانگ کر اس کی دیت اکٹھی کر سکتے ہو؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"کیا تمہارے مالکان اس کی دیت ادا کر دیں گے؟\" اس نے کہا: نہیں، تب آپ نے اس شخص (مقتول کے وارث) سے فرمایا:\"اسے لے جاؤ\" جب وہ اسے قتل کرنے کے لیے لے کر چلا تو آپ نے فرمایا: \"اگر یہ اس کو قتل کر دے گا تو اسی کی طرح ہو جائے گا\" وہ آپ کی بات سن رہا تھا جب اس کے کان میں یہ بات پہنچی تو اس نے کہا: وہ یہ ہے، آپ جو چاہیں اس کے سلسلے میں حکم فرمائیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے چھوڑ دو، وہ اپنا اور تمہارے بھتیجے کا گناہ لے کر لوٹے گا اور جہنمیوں میں سے ہو گا\" چنانچہ اس نے اسے چھوڑ دیا۔","صحیح",{"u2":"جناب علقمہ بن وائل اپنے والد سے روایت کرتے ہیں کہ ایک شخص ایک حبشی کو پکڑے نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہا: اس نے میرے بھتیجے کو قتل کر ڈالا ہے۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” تو نے اس کو کس طرح قتل کیا تھا؟ “ اس نے بتایا کہ میں نے اس کے سر پر کلہاڑا مارا تھا، لیکن اسے میرا قتل کرنے کا ارادہ نہیں تھا۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا تیرے پاس مال ہے کہ تو اس کی دیت دے سکے؟ “ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا اگر میں تجھے چھوڑ دوں، اور تو لوگوں سے مانگے اور اس کی دیت جمع کر لے (تو کیا ایسے کر سکتا ہے؟) “ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا تیرے مالک (یا تیری قوم والے) تجھے اس کی دیت دے سکتے ہیں؟ “ اس نے کہا: نہیں۔ تو آپ صلی اللہ علیہ وسلم نے مقتول کے ولی سے کہا ” اس کو پکڑ لے۔ “ چنانچہ وہ اسے قتل کرنے کے لیے لے چلا ‘ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” خبردار! اگر اس نے اس کو قتل کر دیا تو اسی کی مانند ہو جائے گا۔ “ تو وہ (مقتول کا ولی) قاتل کو لے کر اس جگہ پہنچ گیا جہاں سے اس نے آپ صلی اللہ علیہ وسلم کی بات سنی تھی اور بولا: لیجئیے! یہ رہا اور جو چاہیں اس کے متعلق حکم فرمائیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اس کو چھوڑ دو ‘ یہ اپنے اور اپنے مقتول کے گناہ اپنے سر لے کر جہنمیوں میں سے ہو گا۔ “ سیدنا وائل نے کہا: چنانچہ اس نے اس کو چھوڑ دیا۔","f2":"1: قتل کی یہ نوعیت خطاشبہ العمد تھی اوراس میں دیت آتی ہے،قصاص نہیں\n2:اگر قاتل یااس کے اولیا دیت دینے سے قاصرہوں تو امام (امیر) قاتل کو مقتول کے اولیا کے حوالے کرسکتا ہے۔\n3:مسلمان کا قتل کبیرہ گناہ ہے اور اس کی سزا ابدہ جہنم ہے اللہ معاف فرمادے تو الگ بات ہے۔"}],[4502,"ابوامامہ بن سہل کہتے ہیں کہ ہم عثمان رضی اللہ عنہ کے ساتھ تھے، آپ گھر میں محصور تھے، گھر میں داخل ہونے کا ایک راستہ ایسا تھا کہ جو اس میں داخل ہو جاتا وہ باہر سطح زمین پر کھڑے لوگوں کی گفتگو سن سکتا تھا، عثمان اس میں داخل ہوئے اور ہمارے پاس لوٹے تو ان کا رنگ متغیر تھا، کہنے لگے: ان لوگوں نے ابھی ابھی مجھے قتل کرنے کی دھمکی دی ہے، تو ہم نے عرض کیا: امیر المؤمنین! آپ کی ان سے حفاظت کے لیے اللہ کافی ہے، اس پر انہوں نے کہا: آخر یہ مجھے کیوں قتل کرنا چاہتے ہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"تین باتوں کے بغیر کسی مسلمان شخص کا خون حلال نہیں: ایک یہ کہ اسلام لانے کے بعد وہ کفر کا ارتکاب کرے، دوسرے یہ کہ شادی شدہ ہو کر زنا کرے، اور تیسرے یہ کہ ناحق کسی کو قتل کر دے\" تو اللہ کی قسم! میں نے نہ تو جاہلیت میں، اور نہ اسلام لانے کے بعد کبھی زنا کیا، اور جب سے اللہ نے مجھے ہدایت بخشی ہے میں نے کبھی نہیں چاہا کہ میرا دین اس کے بجائے کوئی اور ہو، اور نہ ہی میں نے کسی کو قتل کیا ہے، تو آخر کس بنیاد پر مجھے یہ قتل کریں گے؟ ۔ ابوداؤد کہتے ہیں: عثمان اور ابوبکر رضی اللہ عنہما نے تو جاہلیت میں بھی شراب سے کنارہ کشی اختیار کر رکھی تھی۔","صحیح",{"u2":"جناب ابوامامہ بن سہل بیان کرتے ہیں کہ ہم سیدنا عثمان رضی اللہ عنہ کے ہاں گئے جبکہ وہ اپنے گھر میں محصور تھے۔ گھر میں ایک ایسی جگہ تھی کہ جو وہاں داخل ہوتا مقام بلاط پر بیٹھے لوگوں کی باتیں سن سکتا تھا۔ چنانچہ سیدنا عثمان رضی اللہ عنہ اس جگہ میں گئے اور پھر ہمارے پاس واپس آئے تو ان کا رنگ اڑا ہوا تھا۔ انہوں نے بتایا کہ یہ (بلوائی) اب مجھے قتل کے دینے کی دھمکیاں دینے لگے ہیں۔ ہم نے کہا: امیر المؤمنین! اللہ عزوجل ان کی جانب سے آپ کی کفایت کرے گا۔ انہوں نے کہا: یہ مجھے کیوں قتل کرنا چاہتے ہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے ” کسی مسلمان کا خون حلال نہیں، سوائے اس کے کہ اس سے تین باتوں میں سے کوئی ایک صادر ہو: اسلام کے بعد کفر ‘ شادی شدہ ہونے کے بعد زنا ‘ یا قصاص کے بغیر کسی کو قتل کر دینا۔ “ اور اللہ کی قسم! میں نے کبھی زنا نہیں کیا ‘ جاہلیت میں نہ اسلام لانے کے بعد۔ اور جب سے اللہ نے مجھے ہدایت نصیب فرمائی ہے میں نے کبھی نہیں چاہا کہ میرا اس (اسلام) کے بدلے کوئی اور دین ہوتا ‘ اور میں نے کسی کو قتل بھی نہیں کیا ہے ‘ تو پھر یہ میرے قتل کے درپے کیوں ہیں؟ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: سیدنا عثمان رضی اللہ عنہ اور سیدنا ابوبکر رضی اللہ عنہما نے دور جاہلیت ہی سے شراب چھوڑ دی تھی۔","f2":"سیدنا ابو بکر اور سیدنا عثمان رضی اللہ اسلام سے پہلے ہی پاک طینت تھے اسلام نے ان کی صالحیت کو اور بھی صیقل کردیا تھا۔"}],[4503,"زبیر بن عوام اور ان والد عوام رضی اللہ عنہما (یہ دونوں جنگ حنین میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ شریک تھے) سے روایت ہے کہ محلم بن جثامہ لیثی نے اسلام کے زمانے میں قبیلہ اشجع کے ایک شخص کو قتل کر دیا، اور یہی پہلی دیت ہے جس کا فیصلہ رسول اللہ صلی اللہ علیہ وسلم نے کیا، تو عیینہ نے اشجعی کے قتل کے متعلق گفتگو کی اس لیے کہ وہ قبیلہ عطفان سے تھا، اور اقرع بن حابس نے محلم کی جانب سے گفتگو کی اس لیے کہ وہ قبیلہ خندف سے تھا تو آوازیں بلند ہوئیں، اور شور و غل بڑھ گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عیینہ! کیا تم دیت قبول نہیں کر سکتے؟\" عیینہ نے کہا: نہیں، اللہ کی قسم، اس وقت تک نہیں جب تک میں اس کی عورتوں کو وہی رنج و غم نہ پہنچا دوں جو اس نے میری عورتوں کو پہنچایا ہے، پھر آوازیں بلند ہوئیں اور شور و غل بڑھ گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عیینہ! کیا تم دیت قبول نہیں کر سکتے؟\" عیینہ نے پھر اسی طرح کی بات کہی یہاں تک کہ بنی لیث کا ایک شخص کھڑا ہوا جسے مکیتل کہا جاتا تھا، وہ ہتھیار باندھے تھا اور ہاتھ میں سپر لیے ہوئے تھا، اس نے عرض کیا: اللہ کے رسول! شروع اسلام میں اس نے جو غلطی کی ہے، اسے میں یوں سمجھتا ہوں جیسے چند بکریاں چشمے پر آئیں اور ان پر تیر پھینکے جائیں تو پہلے پہل آنے والیوں کو تیر لگے، اور پچھلی انہیں دیکھ کر ہی بھاگ جائیں، آج ایک طریقہ نکالئے اور کل اسے بدل دیجئیے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پچاس اونٹ ابھی فوراً دے دو، اور پچاس مدینے لوٹ کر دینا\"۔ اور یہ واقعہ ایک سفر کے دوران پیش آیا تھا، محلم لمبا گندمی رنگ کا ایک شخص تھا، وہ لوگوں کے کنارے بیٹھا تھا، آخر کار جب وہ چھوٹ گیا تو رسول اللہ صلی اللہ علیہ وسلم کے سامنے آ بیٹھا، اور اس کی آنکھیں اشک بار تھیں اس نے عرض کیا: اللہ کے رسول! میں نے گناہ کیا ہے جس کی خبر آپ کو پہنچی ہے، اب میں توبہ کرتا ہوں، آپ اللہ سے میری مغفرت کی دعا فرمائیے، اللہ کے رسول! تو رسول اللہ صلی اللہ علیہ وسلم نے بہ آواز بلند فرمایا: \"کیا تم نے اسے ابتداء اسلام میں اپنے ہتھیار سے قتل کیا ہے، اے اللہ! محلم کو نہ بخشنا\" ابوسلمہ نے اتنا اضافہ کیا ہے کہ یہ سن کر محلم کھڑا ہوا، وہ اپنی چادر کے کونے سے اپنے آنسو پونچھ رہا تھا، ابن اسحاق کہتے ہیں: محلم کی قوم کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس کے بعد اس کے لیے مغفرت کی دعا فرمائی۔ ابوداؤد کہتے ہیں: نضر بن شمیل کا کہنا ہے کہ «غير» کے معنی دیت کے ہیں۔","ضعیف",{"u2":"زیاد بن سعد بن ضمیرہ سلمی سے منقول ہے اور یہ وہب بن بیان کی روایت ہے اور زیادہ کامل ہے۔ وہ (زیاد بن سعد) عروہ بن زبیر سے اپنے والد کے واسطہ سے روایت بیان کرتے ہیں، اور موسیٰ بن اسماعیل کی سند میں ہے کہ زیاد نے اپنے والد سے اور اپنے دادا (ضمیرہ) سے روایت کیا اور یہ دونوں (سعد اور ضمیرہ) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ معرکہ حنین میں حاضر تھے ہم وہب بن بیان کی طرف لوٹتے ہیں کہ، محلم بن جثامہ لیثی نے قبول اسلام کے بعد قبیلہ اشجع کے ایک آدمی کو قتل کر دیا۔ اور یہ دیت کا پہلا مقدمہ تھا جس کا رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا۔ چنانچہ عیینہ نے مقتول اشجعی کے بارے میں بات شروع کی کیونکہ اس کا تعلق قبیلہ غطفان سے تھا اور اقرع بن حابس نے محلم کی جانب سے بات کی کیونکہ وہ قبیلہ خندف سے تھا۔ ان لوگوں کی آوازیں اونچی ہو گئیں اور بہت شوروغل اور جھگڑا ہوا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اے عیینہ! کیا تم دیت قبول نہیں کرتے ہو؟ “ عیینہ نے کہا: نہیں ‘ اللہ کی قسم! جب تک میں اس کی عورتوں کو بھی وہی دکھ اور اذیت نہ پہنچا لوں جو اس نے میری عورتوں کو پہنچایا ہے۔ پھر آوازیں اونچی ہو گئیں ‘ بڑا شوروغل اور جھگڑا ہوا ‘ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اے عیینہ! کیا تم دیت قبول نہیں کرتے ہو؟ “ تو عیینہ نے پہلے کی طرح جواب دیا۔ حتیٰ کہ بنو لیث کا ایک آدمی کھڑا ہوا جس کا نام مکیتل تھا۔ وہ ہتھیار بند تھا اور ڈھال اس کے ہاتھ میں تھی۔ اس نے کہا: اے اللہ کے رسول! مجھے اس واقعے میں جو ابتدائے اسلام میں رون ہوا ہے، اور کوئی مثال نہیں ملتی کہ گھاٹ پر آتی بکریوں میں پہلی کو پتھر مار دیا جائے تو آخری بھی بھاگ جاتی ہے۔ اور (دوسری مثال) آج ایک طریقہ اختیار کرو تو کل اسے بدل دو۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” پچاس اونٹ تو فوری طور پر ابھی ادا ہوں اور پچاس جب ہم مدینہ لوٹیں۔ “ اور یہ واقعہ آپ صلی اللہ علیہ وسلم کے سفر کا ہے۔ (صاحب معاملہ) محلم ایک دراز قد گندم گوں آدمی تھا ‘ وہ لوگوں کی ایک جانب میں بیٹھا ہوا تھا۔ لوگ اسی حالت پر تھے کہ وہ جگہ بناتا ہوا رسول اللہ صلی اللہ علیہ وسلم کے سامنے آ بیٹھا ‘ جبکہ اس کی آنکھوں سے آنسو جاری تھے۔ اس نے کہا: اے اللہ کے رسول! مجھ سے یہ کام ہو گیا جس کی آپ صلی اللہ علیہ وسلم کو خبر ملی ہے، میں اللہ کے حضور توبہ کرتا ہوں۔ اللہ کے رسول! میرے لیے اللہ سے استغفار فرمائیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تو نے اسلام لاتے ہی اپنے ہتھیار سے قتل کر ڈالا۔ اے اللہ! محلم کی بخشش نہ فر۔ “ یہ آپ صلی اللہ علیہ وسلم نے بلند آواز سے کہا۔ ابوسلمہ نے مزید کہا: پھر وہ اٹھ کھڑا ہوا اور اپنی چادر کے پلو سے اپنے آنسو پونچھ رہا تھا۔ ابن اسحاق رضی اللہ عنہ کہتے ہیں: اس کی قوم کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بعد میں اس کے لیے استغفار فرمایا تھا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ نضر بن شمیل نے «الغير» کا مفہوم ” دیت “ بتایا ہے۔","f2":"مذکورہ بالا مثالوں سے اپنے مخاطب کو اپنے مطلب کی بات پر لانے کے لئے بڑانگیختہ کرنا مطلوب تھا۔ پہلی مثال میں یہ ہے کہ اگر آج اس پہلے قاتل سے قصاصلے لیا جائے تو دوسروں کو عبرت اور نصیحت ہو جائے گی۔ اور کو ئی کسی کو قتل کرنے کی جرات نہیں کرے گا اوراگر قصاص نہ لیا جائے تو دوسری مثال ہے کہ یہ بات حکمت کے خلاف ہو گی کہ آج ایک اصول بنائیں اور کل اسے بدل دیں چاہیے کہ اٹل موقف اپنایا جائے اگر آج آپ نے قصاص نہ لیا اور دیت ہی راضی ہو گئے تو لوگ آئندہ دیت پر راضی نہ ہوں گے قصاص ہی لیا کریں گے۔"}],[4504,"ابوشریح کعبی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سنو خزاعہ کے لوگو! تم نے ہذیل کے اس شخص کو قتل کیا ہے، اور میں اس کی دیت دلاؤں گا، میری اس گفتگو کے بعد کوئی قتل کیا گیا تو مقتول کے لوگوں کو دو باتوں کا اختیار ہو گا یا وہ دیت لے لیں یا قتل کر ڈالیں\"۔","صحیح",{"u2":"جناب ابوشریح کعبی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اے بنو خزاعہ! تم نے ہذیل کا یہ آدمی قتل کیا ہے ‘ میں اس کی دیت ادا کرتا ہوں، میری اس بات کے بعد جس کسی کا کوئی آدمی قتل کیا گیا تو اس کے وارثوں کو دو باتوں میں سے ایک کا اختیار ہو گا کہ یا تو دیت لے لیں یا (قصاص میں) قتل کریں۔ “","f2":"ایک تیسرا اختیار بھی ہے کہ معاف کردیں جبکہ بعض فقہا نے دیت لینے کو بھی معاف کرنے کی ایک صورت بیان کیا ہے۔"}],[4505,"ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ جب مکہ فتح ہوا تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے اور آپ نے فرمایا: \"جس کا کوئی قتل کیا گیا تو اسے اختیار ہے یا تو دیت لے لے، یا قصاص میں قتل کرے\" یہ سن کر یمن کا ایک شخص کھڑا ہوا جسے ابوشاہ کہا جاتا تھا اور اس نے عرض کیا: اللہ کے رسول! مجھے یہ لکھ دیجئیے (عباس بن ولید کی روایت «اکتب لی» کے بجائے «اکتبوا لی» یہ صیغۂ جمع ہے) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابو شاہ کے لیے لکھ دو\"۔ ابوداؤد کہتے ہیں: «اکتبوا لی» سے مراد نبی اکرم صلی اللہ علیہ وسلم کا خطبہ ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ جب مکہ فتح ہوا تو رسول اللہ صلی اللہ علیہ وسلم نے کھڑے ہو کر خطبہ ارشاد فرمایا ” جس کسی کا کوئی آدمی قتل کیا گیا ہو تو اسے دو باتوں میں سے ایک کا اختیار ہے کہ یا تو دیت دیا جائے یا قصاص۔ “ تب اہل یمن میں سے ایک آدمی کھڑا ہوا اس کا نام ابو شاہ تھا، اس نے کہا: اے اللہ کے رسول! مجھے یہ لکھ دیجئیے۔ (عباس بن ولید کے الفاظ ہیں «اكتبوا لي») تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ابو شاہ کو لکھ دو۔ “ حدیث کے یہ الفاظ احمد بن ابراہیم کے ہیں۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس سے مراد نبی کریم صلی اللہ علیہ وسلم کے خطبہ کا لکھنا ہے۔","f2":"1: قتل عمد میں قاتل سے قصاص ہوتا ہے یا پھر اگر مقتول کے وارث رضا مند ہوں تو دیت بھی لے سکتے ہیں۔\n2:رسول صلی اللہ علیہ وسلم کے دور میں احادیث رسول لکھی بھی گئی ہیں تاہم ان کا دائرہ بہت محدود تھا اورصحابہ کرام رضی اللہ بجا طور پر یہ سمجھتے اور عقیدہ رکھتے تھے کہ فرامین رسول صلی اللہ علیہ وسلم ہی ہمارے لئے معیار عمل ہیں۔"}],[4506,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کسی کافر کے بدلے مومن کو قتل نہیں کیا جائے گا، اور جو کسی مومن کو دانستہ طور پر قتل کرے گا، وہ مقتول کے وارثین کے حوالے کر دیا جائے گا، وہ چاہیں تو اسے قتل کریں اور چاہیں تو دیت لے لیں\"۔","حسن صحیح",{"u2":"جناب عمرو بن شعیب اپنے والد سے ‘ وہ اپنے دادا سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کسی مومن کو کافر کے بدلے قتل نہ کیا جائے اور جس نے کسی مومن کو جان بوجھ کر قتل کیا تو قاتل کو مقتول کے وارثوں کے حوالہ کیا جائے ‘ وہ چاہیں تو اسے (قصاص میں) قتل کر دیں اور اگر چاہیں تو دیت لے لیں۔ “","f2":"مومن کو کافر کے بدلے قتل نہیں کیا جاسکتا یہ مسئلہ آگے حدیث4530 میں آرہا ہے۔"}],[4507,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں اسے ہرگز نہیں معاف کروں گا ۱؎ جو دیت لینے کے بعد بھی (قاتل کو) قتل کر دے\"۔\n§وضاحت\n۱؎ : یعنی اس سے قصاص لے کر رہوں گا۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے دیت لینے کے بعد قتل کیا میں اسے نہیں چھوڑوں گا۔ “","f2":": یہ بات واضح ہے کہ یہ بہت بڑا جرم ہے کہ وارث پہلےدیت قبول کرلے پھر موقع پا کر قاتل کو یا کسی دوسرے کو قتل کر ڈالے اور ابو داودطیالسی کی روایت مذکورہ بالا شاہد اور موہد ہے کہ ایسے مجرم سے قصاص لیا جائے گا۔"}],[4508,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ایک یہودی عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک زہر آلود بکری لے کر آئی، آپ نے اس میں سے کچھ کھا لیا، تو اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ نے اس سلسلے میں اس سے پوچھا، تو اس نے کہا: میرا ارادہ آپ کو مار ڈالنے کا تھا، آپ نے فرمایا: \"اللہ تجھے کبھی مجھ پر مسلط نہیں کرے گا\" صحابہ نے عرض کیا: کیا ہم اسے قتل نہ کر دیں، آپ نے فرمایا: \"نہیں\" چنانچہ میں اس کا اثر برابر رسول اللہ صلی اللہ علیہ وسلم کے مسوڑھوں میں دیکھا کرتا تھا۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ایک یہودی عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس زہر آلود بکری (کا گوشت) لائی تو آپ صلی اللہ علیہ وسلم نے اس سے کھایا۔ پھر اس عورت کو رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا ‘ آپ صلی اللہ علیہ وسلم نے اس سے اس کے متعلق پوچھا تو اس نے کہا: میں نے آپ کو قتل کرنا چاہا تھا۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اللہ تجھے یہ کام نہ کرنے دے گا۔ “ یا فرمایا ” اللہ تجھے مجھ پر مسلط نہ ہونے دے گا۔ “ صحابہ نے کہا: کیا ہم اسے قتل نہ کر دیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں۔ “ سیدنا انس رضی اللہ عنہ کہتے ہیں کہ میں اس زہر کا اثر رسول اللہ صلی اللہ علیہ وسلم کے حلق میں کوے پر دیکھتا رہا۔"}],[4509,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک یہودی عورت نے نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک زہر آلود بکری بھیجی، لیکن آپ نے اس عورت سے کوئی تعرض نہیں کیا۔ ابوداؤد کہتے ہیں: یہ مرحب کی ایک یہودی بہن تھی جس نے نبی اکرم صلی اللہ علیہ وسلم کو زہر دیا تھا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک یہودی عورت نے نبی کریم صلی اللہ علیہ وسلم کو زہر آلود بکری ہدیہ کی۔ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: پھر نبی کریم صلی اللہ علیہ وسلم نے اس سے کوئی تعرض نہیں کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ یہودی عورت مرحب کی بہن تھی جس نے نبی کریم صلی اللہ علیہ وسلم کو زہر دینے کی کوشش کی تھی۔"}],[4510,"جابر بن عبداللہ رضی اللہ عنہما بیان کرتے تھے کہ خیبر کی ایک یہودی عورت نے بھنی ہوئی بکری میں زہر ملایا، پھر اسے رسول اللہ صلی اللہ علیہ وسلم کو تحفہ میں بھیجا، آپ نے دست کا گوشت لے کر اس میں سے کچھ کھایا، آپ کے ساتھ صحابہ کی ایک جماعت نے بھی کھایا، پھر ان سے آپ نے فرمایا: \"اپنے ہاتھ روک لو\" اور آپ نے اس یہودیہ کو بلا بھیجا، اور اس سے سوال کیا: \"کیا تم نے اس بکری میں زہر ملایا تھا؟\" یہودیہ بولی: آپ کو کس نے بتایا؟ آپ نے فرمایا: \"دست کے اسی گوشت نے مجھے بتایا جو میرے ہاتھ میں ہے\" وہ بولی: ہاں (میں نے ملایا تھا)، آپ نے پوچھا: \"اس سے تیرا کیا ارادہ تھا؟\" وہ بولی: میں نے سوچا: اگر نبی ہوں گے تو زہر نقصان نہیں پہنچائے گا، اور اگر نہیں ہوں گے تو ہم کو ان سے نجات مل جائے گی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اسے معاف کر دیا، کوئی سزا نہیں دی، اور آپ کے بعض صحابہ جنہوں نے بکری کا گوشت کھایا تھا انتقال کر گئے، رسول اللہ صلی اللہ علیہ وسلم نے بکری کے گوشت کھانے کی وجہ سے اپنے شانوں کے درمیان پچھنے لگوائے، جسے ابوہند نے آپ کو سینگ اور چھری سے لگایا، ابوہند انصار کے قبیلہ بنی بیاضہ کے غلام تھے۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے تھے کہ اہل خیبر کی ایک یہودی عورت نے ایک بکری کو آگ پر بھون کر زہر آلود کیا اور پھر اسے رسول اللہ صلی اللہ علیہ وسلم کو ہدیہ دے دیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کی دستی کا حصہ لیا اور کھانے لگے اور آپ صلی اللہ علیہ وسلم کے ساتھ آپ کے صحابہ کرام کی ایک جماعت بھی اس سے کھانے لگی۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا &rdquo; اپنے ہاتھ کھینچ لو۔ &ldquo; اور اس عورت کو بلوایا اور اسے پوچھا &rdquo; کیا تو نے اس بکری کو زہر آلود کیا ہے؟ &ldquo; وہ یہودن بولی: آپ کو کس نے بتایا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا &rdquo; مجھے اس دستی نے بتایا ہے جو میرے ہاتھ میں ہے۔ عورت نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے پوچھا &rdquo; تیرا اس سے کیا ارادہ تھا؟ &ldquo; کہنے لگی &lsquo; میں نے کہا: اگر یہ نبی ہوا تو اسے یہ ہرگز نقصان نہیں دے گی اور اگر نبی نہ ہوا تو ہم اس سے راحت پا جائیں گے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کو معاف کر دیا اور کوئی سزا نہ دی۔ اور آپ صلی اللہ علیہ وسلم کے وہ صحابہ جنہوں نے اس بکری میں سے کھایا تھا ان میں سے ایک (بشر بن براء بن معرور) وفات پا گئے اور (خود) رسول اللہ صلی اللہ علیہ وسلم نے اس کے کھانے کی وجہ سے اپنے کندھوں کے درمیان میں پچھنے لگوائے۔ یہ پچھنے آپ صلی اللہ علیہ وسلم کو ابوہند نے گائے کے سینگ اور چھری کے ساتھ لگائے۔ اور ابوہند انصار کے قبیلہ بنی بیاضہ کا غلام تھا۔"}],[4511,"ابوسلمہ رضی اللہ عنہ کہتے ہیں کہ خیبر کی ایک یہودی عورت نے رسول اللہ صلی اللہ علیہ وسلم کو بھنی ہوئی بکری تحفہ میں بھیجی، پھر راوی نے ویسے ہی بیان کیا جیسے جابر کی حدیث میں ہے، ابوسلمہ کہتے ہیں: پھر بشر بن براء بن معرور انصاری فوت ہو گئے، تو آپ نے اس یہودی عورت کو بلا بھیجا اور فرمایا: \"تجھے ایسا کرنے پر کس چیز نے آمادہ کیا تھا؟\" پھر راوی نے اسی طرح ذکر کیا جیسے جابر کی حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم نے اس کے سلسلہ میں حکم دیا: تو وہ قتل کر دی گئی، اور انہوں نے پچھنا لگوانے کا ذکر نہیں کیا ہے ۱؎۔\n§وضاحت\n۱؎ : اس سے پہلی والی حدیث میں معاف کر دیئے جانے کا ذکر ہے، جبکہ اس حدیث میں قتل کئے جانے کا ذکر ہے، قاضی عیاض فرماتے ہیں کہ روایات میں تطبیق کی صورت یہ ہے کہ شروع میں جب زہر کھلانے کا علم ہوا، اور کہا گیا کہ اسے قتل کر دیا جائے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں، لیکن جب اس زہر کی وجہ سے بشر بن البراء بن معرور انتقال کرگئے تب آپ نے اس یہودیہ کو ان کے ورثہ کے حوالے کر دیا، پھر وہ بطور قصاص قتل کی گئی۔ (عون المعبود ۱۲؍ ۱۴۹)","حسن صحیح",{"u2":"سیدنا ابوسلمہ رضی اللہ عنہ سے روایت ہے کہ خیبر میں ایک یہودی عورت نے رسول اللہ صلی اللہ علیہ وسلم کو ایک بھنی ہوئی بکری ہدیہ کی. اور سیدنا جابر رضی اللہ عنہ کی روایت کی مانند روایت کیا، کہا کہ پھر سیدنا بشر بن براء بن معرور انصاری (اس کی وجہ سے) فوت ہو گئے۔ تو آپ صلی اللہ علیہ وسلم نے اس یہودن کو بلوایا (اور اس سے پوچھا) تجھے اس کام پر کس چیز نے آمادہ کیا تھا؟ “ تو حدیث جابر کی مانند ذکر کیا، تب رسول اللہ صلی اللہ علیہ وسلم نے اس کے متعلق حکم دیا تو اسے قتل کر دیا گیا۔ اور پچھنے لگوانے کا معاملہ اس میں ذکر نہیں کیا۔","f2":"1: اگر کوئی شخص کسی کو زہر کھلا کر مارڈالے تو اس قصاص لیا جائےگا\n2:اہل کتاب کا کھانا مسلمانوں کو حلال ہے اور اسی طرح ان سے ہدیہ لیا جاسکتا ہے\n3: یہ رسول صلی اللہ علیہ وسلم کا معجزہ تھا کہ گوشت کے ایک ٹکڑے نے اپنے زہر آلود ہونے کی خبر دے دی۔"}],[4512,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہدیہ قبول فرماتے تھے، اور صدقہ نہیں کھاتے تھے، نیز اسی سند سے ایک اور مقام پر ابوہریرہ کے ذکر کے بغیر صرف ابوسلمہ سے روایت ہے، وہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم ہدیہ قبول فرماتے تھے اور صدقہ نہیں کھاتے تھے، اس میں اتنا اضافہ ہے کہ آپ کو خیبر کی ایک یہودی عورت نے ایک بھنی ہوئی بکری تحفہ میں بھیجی جس میں اس نے زہر ملا رکھا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اس میں سے کھایا اور لوگوں نے بھی کھایا، پھر آپ نے لوگوں سے فرمایا: \"اپنے ہاتھ روک لو، اس (گوشت) نے مجھے بتایا ہے کہ وہ زہر آلود ہے\" چنانچہ بشر بن براء بن معرور انصاری مر گئے، تو آپ نے اس یہودی عورت کو بلا کر فرمایا: \"ایسا کرنے پر تجھے کس چیز نے آمادہ کیا؟\" وہ بولی: اگر آپ نبی ہیں تو جو میں نے کیا ہے وہ آپ کو نقصان نہیں پہنچا سکتا، اور اگر آپ بادشاہ ہیں تو میں نے لوگوں کو آپ سے نجات دلا دی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تو وہ قتل کر دی گئی، پھر آپ نے اپنی اس تکلیف کے بارے میں فرمایا: جس میں آپ نے وفات پائی کہ میں برابر خیبر کے اس کھانے کے اثر کو محسوس کرتا رہا یہاں تک کہ اب وہ وقت آ گیا کہ اس نے میری شہ رگ کاٹ دی۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہدیہ قبول فر لیتے تھے اور صدقہ نہ کھایا کرتے تھے۔ سیدنا ابوسلمہ سے روایت ہے اور ابوہریرہ رضی اللہ عنہ کا واسطہ ذکر نہیں کیا. کہا کہ رسول اللہ صلی اللہ علیہ وسلم ہدیہ قبول فر لیتے اور صدقہ نہیں کھایا کرتے تھے۔\nمزید کہا کہ ایک یہودی عورت نے خیبر میں آپ صلی اللہ علیہ وسلم کو ایک بکری ہدیہ کی جو بھونی گئی تھی اور اس نے اسے زہر آلود کر دیا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ لوگوں (صحابہ کرام) نے بھی اس سے کھایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اپنے ہاتھ کھینچ لو ‘ اس نے مجھے بتایا ہے کہ یہ زہر آلود ہے۔ “ پھر (اس کی وجہ سے) بشر بن براء بن معرور انصاری رضی اللہ عنہ فوت ہو گئے۔ تو آپ صلی اللہ علیہ وسلم نے اس یہودن کو بلوایا (اور پوچھا) ” تجھے اس کارستانی پر کس چیز نے آمادہ کیا تھا؟ “ اس نے کہا: اگر آپ نبی ہیں تو میرے اس کام سے آپ کا کوئی نقصان نہیں ہو گا۔ اور اگر آپ بادشاہ ہیں تو میں لوگوں کو آپ سے راحت پہنچا سکوں گی۔ تب رسول اللہ صلی اللہ علیہ وسلم نے اس کے معتلق حکم دیا تو اسے قتل کر دیا گیا۔ پھر آپ صلی اللہ علیہ وسلم نے اپنی اس تکلیف کے متعلق بتایا جس میں آپ صلی اللہ علیہ وسلم کی وفات ہوئی تھی ” میں ان لقموں کو وجہ سے جو میں نے خیبر میں کھائے تھے ہمیشہ تکلیف میں رہا ہوں ‘ اور اب یہ وقت آ گیا ہے کہ اس نے میری شاہ رگ کاٹ دی ہے۔ “"}],[4513,"کعب بن مالک روایت کرتے ہیں کہ ام مبشر رضی اللہ عنہا نے نبی اکرم صلی اللہ علیہ وسلم سے اس مرض میں جس میں آپ نے وفات پائی کہا: اللہ کے رسول! آپ کا شک کس چیز پر ہے؟ میرے بیٹے کے سلسلہ میں میرا شک تو اس زہر آلود بکری پر ہے جو اس نے آپ کے ساتھ خیبر میں کھائی تھی، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اپنے سلسلہ میں بھی میرا شک اسی پر ہے، اور اب یہ وقت آ چکا ہے کہ اس نے میری شہ رگ کاٹ دی ہے\"۔ ابوداؤد کہتے ہیں: عبدالرزاق نے کبھی اس حدیث کو معمر سے، معمر نے زہری سے، زہری نے نبی اکرم صلی اللہ علیہ وسلم سے مرسلاً روایت کیا ہے اور کبھی معمر نے اسے زہری سے اور، زہری نے عبدالرحمٰن بن کعب بن مالک کے واسطہ سے بیان کیا ہے۔ اور عبدالرزاق نے ذکر کیا ہے کہ معمر اس حدیث کو ان سے کبھی مرسلاً روایت کرتے تو وہ اسے لکھ لیتے اور کبھی مسنداً روایت کرتے تو بھی وہ اسے بھی لکھ لیتے، اور ہمارے نزدیک دونوں صحیح ہے۔ عبدالرزاق کہتے ہیں: جب ابن مبارک معمر کے پاس آئے تو معمر نے وہ تمام حدیثیں جنہیں وہ موقوفاً روایت کرتے تھے ان سے متصلًا روایت کیں۔","صحیح",{"u2":"جناب عبدالرحمٰن اپنے والد سیدنا کعب بن مالک رضی اللہ عنہ سے روایت کرتے ہیں کہ جس بیماری میں رسول اللہ صلی اللہ علیہ وسلم کی وفات ہوئی ان دنوں میں ام مبشر (زوجہ زید بن حارثہ) نے نبی کریم صلی اللہ علیہ وسلم سے پوچھا کہ اے اللہ کے رسول! آپ کیا گمان کرتے ہیں؟ میں اپنے بیٹے کے متعلق یہی سمجھتی ہوں کہ وہ زہر آلود بکری جو اس نے آپ کے ساتھ خیبر میں کھائی تھی وہ اسی سے متاثر ہوا تھا۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا &rdquo; مجھے بھی اپنے متعلق اسی کا گمان ہے اور یہ وقت آ گیا ہے کہ میری شاہ رگیں کٹ رہی ہیں۔ &ldquo; امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ امام عبدالرزاق رضی اللہ عنہ نے یہ روایت کئی بار بسند معمر بواسطہ زہری &lsquo; نبی کریم صلی اللہ علیہ وسلم سے مرسل &lsquo; اور کئی بار &laquo;الزهري عن عبد الرحمن بن كعب بن مالك &raquo; کے واسطے سے موصول روایت کی ہے۔ عبدالرزاق رضی اللہ عنہ نے کہا کہ معمر جب یہ روایت مرسل بیان کرتے تو ہم اسی طرح لکھ لیتے تھے اور جب مسند روایت کرتے تو ہم اسی طرح لکھ لیتے اور ہمارے نزدیک یہ سب صحیح ہیں۔ عبدالرزق رضی اللہ عنہ نے بتایا کہ جب ابن مبارک رضی اللہ عنہ معمر کے ہاں گئے تو انہوں نے وہ تمام احادیث جو وہ موقوف بیان کیا کرتے تھے ابن مبارک رضی اللہ عنہ کو مسند روایت کیں۔"}],[4514,"ام مبشر رضی اللہ عنہا سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئیں پھر راوی نے مخلد بن خالد کی حدیث کا مفہوم اسی طرح ذکر کیا جیسے جابر کی روایت میں ہے، اس میں ہے کہ بشر بن براء بن معرور مر گئے، تو آپ نے یہودی عورت کو بلا بھیجا اور پوچھا: \"یہ تجھے ایسا کرنے پر کس چیز نے آمادہ کیا تھا؟\" پھر راوی نے وہی باتیں ذکر کیں جو جابر کی حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا اور وہ قتل کر دی گئی لیکن انہوں نے پچھنا لگوانے کا ذکر نہیں کیا۔","صحیح",{"u2":"سیدنا سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شخص اپنے غلام کو قتل کرے گا ہم اسے قتل کریں گے اور جو اپنے غلام کی ناک کاٹے گا ہم اس کی ناک کاٹیں گے۔ “"}],[4515,"سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے غلام کو قتل کرے گا ہم اسے قتل کریں گے، اور جو اس کے اعضاء کاٹے گا ہم اس کے اعضاء کاٹیں گے\"۔","ضعیف",{"u2":"سیدنا سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا &rdquo; جو شخص اپنے غلام کو قتل کرے گا ہم اسے قتل کریں گے اور جو اپنے غلام کی ناک کاٹے گا ہم اس کی ناک کاٹیں گے۔ &ldquo;","f2":"بعض ائمہ کے نزدیک مذکورہ دونوں روایات ضعیف ہیں اس لئے بعد کی روایات صحیح ہیں اور مسئلہ وہی ہے جوان سے ثابت ہو رہا ہے کہ غلام کے بدلے میں مالک کو قصاصا قتل نہیں کیا جائے گا۔ لیکن جن کے نزدیک مذکورہ روایات صحیح کاحسن ہیں ان کے نزدیک اس کا مطلب صرف زجروتوبیح اور تنبیہ ہے نہ کہ قصاص لیا جانا یا پھر یہ روایات منسوخ ہیں۔"}],[4516,"اس سند سے بھی قتادہ سے بھی اسی کے مثل حدیث مروی ہے اس میں ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنے غلام کو خصی کرے گا ہم اسے خصی کریں گے\" اس کے بعد راوی نے اسی طرح ذکر کیا جیسے شعبہ اور حماد کی حدیث میں ہے۔ ابوداؤد کہتے ہیں: اسے ابوداؤد طیالسی نے ہشام سے معاذ کی حدیث کی طرح نقل کیا ہے۔","ضعیف",{"u2":"جناب قتادہ رضی اللہ عنہ نے اپنی سند سے مذکورہ بالا روایت کی مثل روایت کیا، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا &rdquo; جس نے اپنے غلام کو خصی کیا ہم اسے خصی کر دیں گے۔ &lsquo; اور پھر شعبہ اور حماد کی حدیث کی مثل روایت کیا۔ (یعنی جو اوپر مذکورہ ہوئی ہے)۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اسے ابوداود طیالسی نے بواسطہ ہشام روایت کیا اور حدیث معاذ کی طرح بیان کیا۔","f2":"بعض ائمہ کے نزدیک مذکورہ دونوں روایات ضعیف ہیں اس لئے بعد کی روایات صحیح ہیں اور مسئلہ وہی ہے جوان سے ثابت ہو رہا ہے کہ غلام کے بدلے میں مالک کو قصاصا قتل نہیں کیا جائے گا۔ لیکن جن کے نزدیک مذکورہ روایات صحیح کاحسن ہیں ان کے نزدیک اس کا مطلب صرف زجروتوبیح اور تنبیہ ہے نہ کہ قصاص لیا جانا یا پھر یہ روایات منسوخ ہیں۔"}],[4517,"اس سند سے بھی قتادہ سے شعبہ کی سند والی روایت کے مثل مروی ہے اس میں اضافہ ہے کہ پھر حسن (راوی حدیث) اس حدیث کو بھول گئے چنانچہ وہ کہتے تھے: آزاد غلام کے بدلے قتل نہیں کیا جائے گا۔","صحیح",{"u2":"جناب قتادہ نے بسند شعبہ مذکورہ بالا روایت کی مثل روایت کیا۔ مزید کہا کہ پھر حسن یہ حدیث بھول گئے اور کہا کرتے تھے کہ کسی آزاد کو کسی غلام کے بدلے میں قتل نہیں کیا جائے گا۔"}],[4518,"حسن بصری کہتے ہیں آزاد غلام کے بدلے قتل نہیں کیا جائے گا۔","صحیح",{"u2":"ہشام نے بواسطہ قتادہ، حسن سے روایت کیا، انہوں نے کہا کہ آزاد سے غلام کا قصاص نہیں لیا جاتا۔"}],[4519,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ ایک شخص چیختا چلاتا نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور کہنے لگا: اللہ کے رسول! اس کی ایک لونڈی تھی، آپ نے فرمایا: \"ستیاناس ہو تمہارا، بتاؤ کیا ہوا؟\" اس نے کہا: برا ہوا، میرے آقا کی ایک لونڈی تھی اسے میں نے دیکھ لیا، تو اسے غیرت آئی، اس نے میرا ذکر کٹوا دیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس شخص کو میرے پاس لاؤ\" تو اسے بلایا گیا، مگر کوئی اسے نہ لا سکا تب آپ نے (اس غلام سے) فرمایا: \"جاؤ تم آزاد ہو\" اس نے کہا: اللہ کے رسول! میری مدد کون کرے گا؟ آپ نے فرمایا: \"ہر مومن پر\" یا کہا: \"ہر مسلمان پر تیری مدد لازم ہے\"۔ ابوداؤد کہتے ہیں: جو آزاد ہوا اس کا نام روح بن دینار تھا، اور جس نے ذکر کاٹا تھا وہ زنباع تھا، یہ زنباع ابوروح ہیں جو غلام کے آقا تھے۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے ‘ وہ اپنے دادا سے روایت کرتے ہیں کہ ایک آدمی چلاتا ہوا نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اس کی لونڈی تھی ‘ اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا ” افسوس تجھ پر ‘ تجھے کیا ہوا ہے؟ “ اس نے کہا: بہت برا ہوا ہے۔ میں نے اپنے مالک کی لونڈی کو دیکھ لیا ‘ تو اسے غیرت آئی اور پھر اس نے میرا ذکر کاٹ ڈلا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اس آدمی کو میرے پاس لاؤ۔ “ اسے ڈھونڈا گیا مگر نہ لا سکے۔ تو آپ صلی اللہ علیہ وسلم نے غلام سے فرمایا ” جاؤ تم آزاد ہو۔ “ اس نے کہا: اے اللہ کے رسول! (اگر وہ مجھے دوبارہ غلام بنانے کی کوشش کرے تو) میری مدد کون کرے گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہر مسلمان۔ “ یا فرمایا ” ہر مومن “۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ آزاد کیے جانے والے کا نام روح بن دینار تھا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں جس نے اس کا ذکر کاٹا اس کا نام زنباع تھا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ زنباع ابوروح ہے۔ یہ اس غلام (روح بن دینار) کا آقا تھا۔","f2":"اگر کوئی مالک اپنے غلام پر ظلم کرے اور اس اعضاء کاٹ ڈالے تو غلام آزاد کردیا جائے گا۔ اور مالک سے قصاص لینے میں فقہاء کا اختلاف ہے جیسا کہ اس کی مختصر تفصیل گزری۔"}],[4520,"سہل بن ابی حثمہ اور رافع بن خدیج رضی اللہ عنہما سے روایت ہے کہ محیصہ بن مسعود اور عبداللہ بن سہل دونوں خیبر کی طرف چلے اور کھجور کے درختوں میں (چلتے چلتے) دونوں ایک دوسرے سے علیحدہ ہو گئے، پھر عبداللہ بن سہل قتل کر دیے گئے، تو ان لوگوں نے یہودیوں پر تہمت لگائی، ان کے بھائی عبدالرحمٰن بن سہل اور ان کے چچازاد بھائی حویصہ اور محیصہ اکٹھا ہوئے اور وہ سب نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، عبدالرحمٰن بن سہل جو ان میں سب سے چھوٹے تھے اپنے بھائی کے معاملے میں بولنے چلے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑوں کا لحاظ کرو\" (اور انہیں گفتگو کا موقع دو) یا یوں فرمایا: \"بڑے کو پہلے بولنے دو\" چنانچہ ان دونوں (حویصہ اور محیصہ) نے اپنے عزیز کے سلسلے میں گفتگو کی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے پچاس آدمی یہودیوں کے کسی آدمی پر قسم کھائیں تو اسے رسی سے باندھ کر تمہارے حوالے کر دیا جائے\" ان لوگوں نے کہا: یہ ایسا معاملہ ہے جسے ہم نے دیکھا نہیں ہے، پھر ہم کیسے قسم کھا لیں؟ آپ نے فرمایا: \"پھر یہود اپنے پچاس آدمیوں کی قسم کے ذریعہ خود کو تم سے بچا لیں گے\" وہ بولے: اللہ کے رسول! یہ کافر لوگ ہیں (ان کی قسموں کا کیا اعتبار؟) چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اپنی طرف سے دیت دے دی، سہل کہتے ہیں: ایک دن میں ان کے شتر خانے میں گیا، تو ان اونٹوں میں سے ایک اونٹنی نے مجھے لات مار دی، حماد نے یہی کہا یا اس جیسی کوئی بات کہی۔ ابوداؤد کہتے ہیں: اسے بشر بن مفضل اور مالک نے یحیی بن سعید سے روایت کیا ہے اس میں ہے: \"کیا تم پچاس قسمیں کھا کر اپنے ساتھی کے خون، یا اپنے قاتل کے مستحق ہوتے ہو؟\" البتہ بشر نے لفظ دم یعنی خون کا ذکر نہیں کیا ہے، اور عبدہ نے یحیی سے اسی طرح روایت کی ہے جیسے حماد نے کی ہے، اور اسے ابن عیینہ نے یحیی سے روایت کیا ہے، تو انہوں نے ابتداء «تبرئكم يهود بخمسين يمينا يحلفون» سے کی ہے اور استحقاق کا ذکر انہوں نے نہیں کیا ہے۔ ابوداؤد کہتے ہیں: یہ ابن عیینہ کا وہم ہے۔\n§وضاحت\n۱؎ : قسامہ یہ ہے کہ جب مقتول کی نعش کسی بستی یا محلہ میں ملے اور اس کا قاتل معلوم نہ ہو تو مقتول کے ورثہ کا جس پر گمان ہو اس پر پچاس قسمیں کھائیں کہ اس نے قتل کیا ہے اگر مقتول کے ورثہ قسم کھانے سے انکار کریں تو اہل محلہ میں سے جنہیں وہ اختیار کریں ان سے قسم لی جائے گی، اگر قسم کھا لیں تو ان پر کچھ مواخذہ نہیں ، اور قسم نہ کھانے کی صورت میں وہ دیت دیں، اور اگر نہ مقتول کے ولی قسم کھائیں، اور نہ ہی بستی یا محلہ والے تو سرکاری خزانہ سے اس مقتول کی دیت ادا کی جائے گی، جیسا کہ آپ صلی اللہ علیہ وسلم نے ادا کیا۔","صحیح",{"u2":"سیدنا سہل بن ابو حثمہ اور رافع بن خدیج رضی اللہ عنہ سے روایت ہے کہ محیصہ بن مسعود اور عبداللہ بن سہل خیبر کی جانب روانہ ہوئے اور کھجوروں کے باغات میں جدا جدا ہو گئے۔ پس عبداللہ بن سہل کو قتل کر دیا گیا۔ سو انہوں نے (وہاں کے) یہودیوں پر الزام لگایا۔ پھر اس (مقتول) کا بھائی عبدالرحمٰن بن سہل اور اس کے چچا زاد حویصہ اور محیصہ نبی کریم صلی اللہ علیہ وسلم کے پاس حاضر ہوئے۔ عبدالرحمٰن اپنے بھائی کے معاملے میں بات کرنے لگا جبکہ وہ ان سب سے چھوٹا تھا ‘ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بڑے کو بات کرنے دو۔ “ یا فرمایا ” پہلے بڑا بات شروع کرے۔ “ پھر ان دونوں نے اپنے بھائی کے بارے میں بات کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے پچاس آدمی ان کے کسی کے خلاف پچاس قسمیں کھائیں تو اس ملزم کی رسی تمہارے حوالے کر دی جائے گی۔ “ انہوں نے کہا: یہ ایسا معاملہ ہے جو ہم نے اپنی آنکھوں سے نہیں دیکھا تو ہم قسمیں کیسے کھائیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” پھر یہودی پچاس قسمیں دے کر تم سے بری ہو جائیں گے۔ “ انہوں نے کہا: اے اللہ کے رسول! یہ کافر لوگ ہیں۔ (ان کی قسموں کا کیا اعتبار؟) الغرض رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے اس کی دیت ادا فرمائی۔ سہل کہتے ہیں: میں ایک دن ان کے باڑے میں چلا گیا تو ان اونٹنیوں میں سے ایک نے مجھے لات دے ماری۔ حماد بن زید نے یہی یا اس کے قریب قریب بیان کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو بشر بن مفضل اور مالک نے یحییٰ بن سعید سے نقل کیا اور کہا: ” کیا تم لوگ پچاس قسمیں کھاؤ گے کہ اپنے عزیز کے خون کے حقدار بن سکو؟ یا قاتل کے حقدار بن سکو؟ “ بشر نے ” خون کے حقدار بننے “ کا ذکر نہیں کیا۔ اور عبدہ نے بواسطہ یحییٰ وہی کہا ہے جیسے کہ حماد نے کہا۔ اور ابن عیینہ کی روایت جو یحییٰ سے ہے اس میں اس نے ابتدائی طور پر یوں کہا ہے ” یہودی پچاس قسمیں کھا کر تم سے بری ہو جائیں گے۔ “ اور ” حقدار بننے “ کا ذکر نہیں کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ ابن عیینہ کا وہم ہے۔","f2":"قسامہ قسم سے ماخوذہے اور تکرار کے ساتھ قسمیں اٹھانے کے معنی میں ہے اس کی تفصیل یہ ہے کہ جب کہیں کوئی قتل ہو جائے اور اس قاتل کا علم نہ ہو اور نہ کوئی گواہی موجود ہو مگر مقتول کے وارث کسی شخص یا اشخاص پر قتل کا دعوی رکھتے ہوں اور اس کے کچھ قرائن بھی قرائن موجود ہوں مثلا ان لوگوں کے مابین دشمنی ہو یا ان کے علاقے میں قتل ہواہو یاکسی کے پاس سے مقتول کا سامان ملے یا اس قسم کی دیگر علامات موجود ہوں تو مدعی لوگ پہلے پچاس قسمیں کھائیں فلاں شخص یا افراد ہمارے آدمی کے قاتل ہیں۔ اس طرح ان کا دعوی ثابت ہو گا اگر مدعی لوگ قسمیں نہ کھائیں تو مدعاعلیہ پچاس قسمیں کھا کر برمی ہو جائیں گے۔ اگر معاملہ واضح نہ ہو سکے تو بیت المال سے اس مقتول کی دیت ادا کی جائےگی"}],[4521,"سہل بن ابی حثمہ انصاری رضی اللہ عنہ اور ان کے قبیلہ کے کچھ بڑوں سے روایت ہے کہ عبداللہ بن سہل اور محیصہ رضی اللہ عنہما کسی پریشانی کی وجہ سے جس سے وہ دو چار ہوئے خیبر کی طرف نکلے پھر کسی نے آ کر محیصہ کو خبر دی کہ عبداللہ بن سہل مار ڈالے گئے اور انہیں کسی کنویں یا چشمے میں ڈال دیا گیا، وہ (محیصہ) یہود کے پاس آئے اور کہنے لگے: قسم اللہ کی! تم نے ہی انہیں قتل کیا ہے، وہ بولے: اللہ کی قسم ہم نے انہیں قتل نہیں کیا ہے، پھر وہ اپنی قوم کے پاس آئے اور ان سے اس کا ذکر کیا، پھر وہ، ان کے بڑے بھائی حویصہ اور عبدالرحمٰن بن سہل تینوں (رسول اللہ صلی اللہ علیہ وسلم کے پاس) آئے، محیصہ نے واقعہ بیان کرنا شروع کیا کیونکہ وہی خیبر میں ساتھ تھے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑوں کو بڑائی دو\" آپ کی مراد عمر میں بڑائی سے تھی چنانچہ حویصہ نے گفتگو کی، پھر محیصہ نے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یا تو یہ لوگ تمہارے آدمی کی دیت دیں، یا لڑائی کے لیے تیار ہو جائیں\" پھر آپ نے اس سلسلے میں انہیں خط لکھا تو انہوں نے اس کا جواب لکھا کہ اللہ کی قسم! ہم نے انہیں قتل نہیں کیا ہے، تو آپ نے حویصہ، محیصہ اور عبدالرحمٰن سے پوچھا: \"کیا تم قسم کھاؤ گے کہ اپنے بھائی کے خون کا مستحق بن سکو؟\" انہوں نے کہا: نہیں، اس پر آپ نے فرمایا: \"تو پھر یہود تمہارے لیے قسم کھائیں گے\" اس پر وہ کہنے لگے: وہ تو مسلمان نہیں ہیں، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے خود اپنے پاس سے ان کی دیت ادا کر دی، اور سو اونٹ بھیج دیے گئے یہاں تک کہ وہ ان کے مکان میں داخل کر دیے گئے، سہل کہتے ہیں: انہیں میں سے ایک سرخ اونٹنی نے مجھے لات ماری ہے۔","صحیح",{"u2":"سیدنا سہل بن ابو حثمہ رضی اللہ عنہ اور ان کی قوم کے بڑوں نے خبر دی کہ عبداللہ بن سہل اور محیصہ لوگوں کو مالی مشکلات کا سامنا تھا تو وہ دونوں (محنت مزدوری کی تلاش میں) خیبر کی طرف نکل گئے۔ پھر محیصہ کو خبر دی گئی کہ عبداللہ بن سہل کو قتل کر کے ایک کنویں یا چشمے میں پھینک دیا گیا ہے۔ تو وہ یہودیوں کے پاس گیا اور کہا: اللہ کی قسم! تم لوگوں ہی نے اس کو قتل کیا ہے۔ انہوں نے جواب دیا: اللہ کی قسم! ہم نے اس کو قتل نہیں کیا۔ پھر وہ چلا آیا اور اپنی قوم کے پاس پہنچا اور ان کو سب بتایا۔ تو وہ اور اس کا بڑا بھائی حویصہ اور عبدالرحمٰن بن سہل (رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں) حاضر ہوئے۔ تو محیصہ بات کرنے لگا اور یہی تھا جو خیبر میں گیا تھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بڑے کا خیال کر۔ “ یعنی جو عمر میں بڑا ہے۔ پھر حویصہ نے بات کی۔ پھر محیصہ نے کی۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” وہ لوگ تمہارے آدمی کی یا تو دیت دیں گے ورنہ جنگ کے تیار رہیں۔ “ پھر رسول اللہ صلی اللہ علیہ وسلم نے انہیں یہ تفصیل لکھ بھیجی۔ انہوں نے جواباً لکھا: اللہ کی قسم! ہم نے اسے قتل نہیں کیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے حویصہ، محیصہ اور عبدالرحمٰن سے فرمایا ” کیا تم لوگ قسمیں کھاؤ گے کہ اپنے آدمی کے خون کے حقدار بن سکو۔ “ انہوں نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” پھر تمہارے مقابلے میں یہودی قسمیں کھائیں گے۔ “ ان لوگوں نے کہا: وہ تو مسلمان نہیں ہیں۔ (یعنی ان کی قسموں کا کیونکر اعتبار کریں؟) چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے اس کی دیت ادا فرمائی اور سو اونٹنیاں ان کی طرف بھیج دیں حتیٰ کہ ان کے احاطے میں داخل کر دی گئیں۔ سہل کہتے ہیں کہ ان میں سے ایک سرخ اونٹنی نے مجھے لات دے ماری تھی۔","f2":"1: قتل یادیگر امور میں تصفیہ کے لئے کفار سے بھی قسمیں لی جائیں۔ اللہ کے نام قسمیں بشرطیکہ فریق ثانی ان کا اعتبار کرے۔\n2:حکومت اسلامیہ میں کسی بھی شخص کا خون ضائع نہیں کیا جاسکتا۔\n3:اگر مدعاعلیہ متعین نہ ہوسکے اور معاملہ مشتبہ ہو تو بیت المال سے دیت ادا کی جائے گی۔\n4:کفار کے ہاں محنت مزدوری اور ملازمت کرنے میں حرج نہیں،بشرطیکہ انسان اپنا دین اسلام محفوظ رکھ سکے۔\n5: مجلس میں با ت پیش کرنی ہو تو چھوٹے کو چاہیے کہ بڑے ادب کرتے ہوئے پہلے اسے بات کرنے دے۔\n6:قسامت سے قتل کا دعوی ثابت ہوجانے کی صورت میں مدعاعلیہ کو قصاص میں قتل فقہاء کا اختلاف ہے البتہ دیت لازم ہونے پر اتفاق ہے۔"}],[4522,"عمرو بن شعیب رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے قسامہ سے بنی نصر بن مالک کے ایک آدمی کو بحرۃالرغاء ۱؎میں لیۃالبحرہ ۲؎ کے کنارے پر قتل کیا، راوی کہتے ہیں: قاتل اور مقتول دونوں بنی نصر کے تھے، «ببحرة الرغاء على شطر لية البحر»کے یہ الفاظ محمود کے ہیں اور محمود اس حدیث کے سلسلہ میں سب سے زیادہ درست آدمی ہیں۔\n§وضاحت\n۱؎ : ایک جگہ کا نام ہے۔ ۲؎ : ایک وادی کا نام ہے۔","ضعیف",{"u2":"جناب عمرو بن شعیب روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو نصر بن مالک کے ایک آدمی کو قسامت کے فیصلے کی بنا پر (قصاص میں) قتل کیا تھا۔ یہ قبیلہ (طائف کے مضافات میں) لیہ شہر کے کنارے بحرۃ الرغاء کے مقام پر سکونت پذیر تھا۔ راوی نے کہا کہ قاتل اور مقتول ان میں سے تھے۔ یہ الفاظ محمود بن خالد کے ہیں۔ جس نے وضاحت سے ” بحرۃ الرغاء “ اور ” شط لیہ “ کے الفاظ بیان کیے ہیں۔"}],[4523,"بشیر بن یسار سے روایت ہے کہ سہل بن ابی حثمہ نامی ایک انصاری ان سے بیان کیا کہ ان کی قوم کے چند آدمی خیبر گئے، وہاں پہنچ کر وہ جدا ہو گئے، پھر اپنے میں سے ایک شخص کو مقتول پایا تو جن کے پاس اسے پایا ان سے ان لوگوں نے کہا: تم لوگوں نے ہی ہمارے ساتھی کو قتل کیا ہے، وہ کہنے لگے: ہم نے قتل نہیں کیا ہے اور نہ ہی ہمیں قاتل کا پتا ہے چنانچہ ہم لوگ اللہ کے نبی اکرم صلی اللہ علیہ وسلم کے پاس گئے، تو آپ نے ان سے فرمایا: \"تم اس پر گواہ لے کر آؤ کہ کس نے اسے مارا ہے؟\" انہوں نے کہا: ہمارے پاس گواہ نہیں ہے، اس پر آپ نے فرمایا: \"پھر وہ یعنی یہود تمہارے لیے قسم کھائیں گے\" وہ کہنے لگے: ہم یہودیوں کی قسموں پر راضی نہیں ہوں گے، پھر آپ کو یہ بات اچھی نہیں لگی کہ اس کا خون ضائع ہو جائے چنانچہ آپ نے اس کی دیت زکوٰۃ کے اونٹوں میں سے سو اونٹ خود دے دی۔","صحیح",{"u2":"جناب سہل بن ابو حثمہ رضی اللہ عنہ نے بیان کیا کہ ان کی قوم کے کچھ لوگ خیبر گئے اور وہاں جا کر علیحدہ علیحدہ ہو گئے۔ پھر انہوں نے اپنے میں سے ایک کو پایا کہ اسے قتل کر دیا گیا تھا ‘ تو انہوں نے وہاں کے لوگوں سے کہا جہاں قتل ہوا تھا کہ تم نے ہمارے ساتھی کو قتل کیا ہے۔ انہوں نے کہا: ہم نے اس کو قتل نہیں کیا اور نہ ہمیں اس کے قاتل کی خبر ہے۔ چنانچہ ہم اللہ کے نبی صلی اللہ علیہ وسلم کی خدمت میں آ گئے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تم لوگ اس کے قاتل کے متعلق گواہ پیش کرو۔ “ انہوں نے کہا: ہمارے پاس کوئی گواہ نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تب وہ تمہارے جواب میں قسمیں کھائیں گے؟ “ انہوں نے کہا: ہم یہودیوں کی قسموں پر راضی نہیں ہیں۔ تب رسول اللہ صلی اللہ علیہ وسلم نے ناپسند کیا کہ اس مقتول کا خون ضائع جائے تو صدقہ کے اونٹوں میں سے اس کی دیت سو اونٹنیاں ادا فر دی۔","f2":"صحیح اورراجح یہ ہے کہ پہلےمدعی لوگوں میں سے بچاس آدمی قسمیں کھا کر اپنا دعوی ثابت کریں گے تب فریق مخالف سے قسمیں وغیرہ لی جائیں گی۔"}],[4524,"رافع بن خدیج رضی اللہ عنہ کہتے ہیں کہ انصار کا ایک آدمی خیبر میں قتل کر دیا گیا، تو اس کے وارثین نبی اکرم صلی اللہ علیہ وسلم کے پاس گئے اور آپ سے اس کا ذکر کیا، آپ نے پوچھا: \"کیا تمہارے پاس دو گواہ ہیں جو تمہارے ساتھی کے مقتول ہو جانے کی گواہی دیں؟\" انہوں نے عرض کیا: اللہ کے رسول! وہاں پر تو مسلمانوں میں سے کوئی نہیں تھا، وہ تو سب کے سب یہودی ہیں اور وہ اس سے بڑے جرم کی بھی جرات کر لیتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو ان میں پچاس افراد منتخب کر کے ان سے قسم لے لو\" لیکن وہ اس پر راضی نہیں ہوئے، تو آپ نے اپنے پاس سے اس کی دیت ادا کی۔","صحیح",{"u2":"سیدنا رافع بن خدیج رضی اللہ عنہ نے بیان کیا کہ انصاریوں کا ایک آدمی خیبر میں قتل ہو گیا۔ تو اس کے وارث نبی کریم صلی اللہ علیہ وسلم کے ہاں گئے اور اس مقتول کا ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تمہارے پاس دو گواہ ہیں جو تمہارے اس ساتھی کے قتل کے متعلق گواہی دیں؟ “ انہوں نے کہا: اے اللہ کے رسول! وہاں مسلمانوں میں سے کوئی بھی نہ تھا ‘ اور وہ لوگ یہودی ہیں ‘ وہ اس سے بھی بڑی باتوں کی جرا\u0004ت کر سکتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تو ان میں سے پچاس آدمیوں کو منتخب کر لو اور ان سے قسمیں لے لو۔ “ مگر انہوں نے انکار کر دیا۔ تب رسول اللہ صلی اللہ علیہ وسلم نے اپنی طرف سے اس کی دیت ادا فرمائی۔","f2":"صحیح اورراجح یہ ہے کہ پہلےمدعی لوگوں میں سے بچاس آدمی قسمیں کھا کر اپنا دعوی ثابت کریں گے تب فریق مخالف سے قسمیں وغیرہ لی جائیں گی۔"}],[4525,"عبدالرحمٰن بن بجید کہتے ہیں کہ اللہ کی قسم، سہل کو اس حدیث میں وہم ہو گیا ہے، واقعہ یوں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یہود کو لکھا کہ تمہارے بیچ ایک مقتول ملا ہے تو تم اس کی دیت ادا کرو، تو انہوں نے جواب میں لکھا: ہم اللہ کی پچاس قسمیں کھا کر کہتے ہیں کہ ہم نے اسے قتل نہیں کیا، اور نہ ہمیں اس کے قاتل کا پتا ہے، وہ کہتے ہیں: اس پر اس کی دیت رسول اللہ صلی اللہ علیہ وسلم نے اپنے پاس سے سو اونٹ (خود) ادا کی۔","منکر",{"u2":"سیدنا عبدالرحمٰن بن بجید رضی اللہ عنہ نے کہا اللہ کی قسم! بیشک سہل کو اس حدیث (کے بیان کرنے) میں وہم ہوا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے یہود کو یہ لکھا تھا کہ بلاشبہ تم میں مقتول پایا گیا ہے ‘ لہذٰا اس کی دیت ادا کرو۔ تو انہوں نے لکھا اور (اپنی تحریر میں) اللہ کے نام کی پچاس قسمیں کھائیں کہ ہم نے اس کو قتل نہیں کیا اور نہ ہمیں قاتل کا کوئی علم ہے۔ انہوں نے کہا: پس رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت ایک سو اونٹنیاں اپنی طرف سے ادا فر دی۔"}],[4526,"انصار کے کچھ لوگوں سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پہلے یہود سے کہا: \"تم میں سے پچاس لوگ قسم کھائیں\" تو انہوں نے انکار کیا، پھر رسول اللہ صلی اللہ علیہ وسلم نے انصار سے کہا: \"تم اپنا حق ثابت کرو\" انہوں نے کہا: اللہ کے رسول! ہم ایسی بات پر قسم کھائیں جسے ہم نے دیکھا نہیں ہے؟ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ان کی دیت یہود سے دلوائی اس لیے کہ وہ انہیں کے درمیان پایا گیا تھا۔","شاذ",{"u2":"جناب ابوسلمہ بن عبدالرحمٰن اور سلیمان بن یسار، انصار کے کئی لوگوں سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے یہودیوں سے کہا اور ان ہی سے ابتداء کی ” تم میں سے پچاس آدمی قسمیں کھائیں۔ “ مگر انہوں نے انکار کر دیا۔ تو آپ صلی اللہ علیہ وسلم نے انصاریوں سے کہا کہ اپنا حق (قسمیں کھا کر) ثابت کرو۔ تو انہوں نے کہا: اے اللہ کے رسول! ہم ان دیکھی بات پر کیسے قسمیں کھائیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت یہودیوں پر ڈال دی کیونکہ وہ مقتول ان ہی کے ہاں پایا گیا تھا۔","f2":"یہ روایت ضعیفہ ہے اس مقتول کی دیت رسول صلی اللہ علیہ وسلم نے بیت المال سے ادا فرمائی تھی۔جیسےکہ گزشتہ احادیث میں بیان ہواہے۔"}],[4527,"انس رضی اللہ عنہ سے روایت ہے کہ ایک لونڈی ملی جس کا سر دو پتھروں کے درمیان کچل دیا گیا تھا، اس سے پوچھا گیا: کس نے تیرے ساتھ یہ کیا ہے؟ کیا فلاں نے؟ کیا فلاں نے؟ یہاں تک کہ ایک یہودی کا نام لیا گیا تو اس نے اپنے سر کے اشارہ سے کہا: ہاں، اس پر اس یہودی کو پکڑا گیا، تو اس نے اعتراف کیا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ اس کا سر بھی پتھر سے کچل دیا جائے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک لڑکی پائی گئی کہ اس کا سر دو پتھروں میں رکھ کر کچل دیا گیا تھا (اور ابھی اس میں زندگی کی رمق باقی تھی) تو اس سے پوچھا گیا: یہ تیرے ساتھ کس نے کیا ہے؟ کیا فلاں نے؟ کیا فلاں نے؟ حتیٰ کہ ایک یہودی کا نام لیا گیا تو اس نے اپنے سر سے اشارہ کیا۔ (ہاں) تو اس یہودی کو پکڑا گیا اور پھر اس نے اعتراف کر لیا تو نبی کریم صلی اللہ علیہ وسلم نے حکم دیا کہ اس کا سر بھی پتھروں سے کچلا جائے۔"}],[4528,"انس رضی اللہ عنہ سے روایت ہے کہ ایک یہودی نے انصار کی ایک لونڈی کو اس کے زیور کی وجہ سے قتل کر دیا، پھر اسے ایک کنوئیں میں ڈال کر اس کا سر پتھر سے کچل دیا، تو اسے پکڑ کر نبی اکرم صلی اللہ علیہ وسلم کے پاس لایا گیا تو آپ نے اس کے متعلق حکم دیا کہ اسے رجم کر دیا جائے یہاں تک کہ وہ مر جائے تو اسے رجم کر دیا گیا یہاں تک کہ وہ مر گیا۔ ابوداؤد کہتے ہیں: اسے ابن جریج نے ایوب سے اسی طرح روایت کیا ہے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک یہودی نے ایک انصاری لڑکی کو قتل کر دیا جو کچھ زیور پہنے ہوئے تھی، اور پھر ایک کنویں میں پھینک دیا اور اس کا سر پتھر سے کچل دیا۔ پھر اسے پکڑ لیا گیا تو اسے نبی کریم صلی اللہ علیہ وسلم کے پاس لایا گیا تو آپ صلی اللہ علیہ وسلم نے اس کے متعلق حکم دیا کہ اسے سنگسار کیا جائے حتیٰ کہ مر جائے۔ چنانچہ اسے سنگسار کیا گیا، حتیٰ کہ وہ مر گیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو ابن جریح نے ایوب سے اسی کی مانند روایت کیا ہے۔","f2":"اس حدیث میں رجم (سنگسار) کا مفہوم دیگر روایات کی روشنی میں یہ ہے کہ قصاص میں مجرم کا سر پتھروںمیں رکھ کر کچلا گیا تھا"}],[4529,"انس رضی اللہ عنہ سے روایت ہے کہ ایک لونڈی اپنے زیور پہنے ہوئی تھی اس کے سر کو ایک یہودی نے پتھر سے کچل دیا تو رسول اللہ صلی اللہ علیہ وسلم اس کے پاس تشریف لائے، ابھی اس میں جان باقی تھی، آپ نے اس سے پوچھا: \"تجھے کس نے قتل کیا ہے؟ فلاں نے تجھے قتل کیا ہے؟\" اس نے اپنے سر کے اشارے سے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے پھر پوچھا: \"تجھے کس نے قتل کیا؟ فلاں نے قتل کیا ہے؟\" اس نے پھر سر کے اشارے سے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے پھر پوچھا: \"کیا فلاں نے کیا ہے؟\" اس نے سر کے اشارہ سے کہا: ہاں، اس پر رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا، تو اسے دو پتھروں کے درمیان (کچل کر) مار ڈالا گیا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک لڑکی اپنے چاندی کے زیور پہنے ہوئے تھی کہ ایک یہودی نے پتھر سے اس کا سر کچل دیا۔ تو رسول اللہ صلی اللہ علیہ وسلم اس لڑکی کے پاس آئے جب کہ (ابھی) اس میں زندگی کی رمق باقی تھی۔ آپ صلی اللہ علیہ وسلم نے اس سے پوچھا ” تجھے کس نے قتل کیا ہے؟ کیا فلاں نے قتل کیا ہے؟ “ اس نے اپنے سر سے اشارہ کیا نہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” تجھے کس نے قتل کیا ہے، کیا فلاں نے قتل کیا ہے؟ “ اس نے اپنے سر سے اشارہ کیا نہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا فلاں نے تجھے قتل کیا ہے؟ “ اس نے اپنے سر سے اشارہ کیا ہاں۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کے متعلق حکم دیا تو اسے دو پتھروں میں رکھ کر قتل کیا گیا۔","f2":"اس سے معلوم ہوا کہ قصاص میں قاتل ہی کو قتل کیا جائے گا،چاہے وہ کسی مردکا قاتل ہو یا عورت کا یہاں عورت کے قصاص میں مر دکو قتل کیا گیا،کیونکہ وہ اس عورت کا قاتل تھا۔"}],[4530,"قیس بن عباد سے کہتے ہیں کہ میں اور اشتر دونوں علی رضی اللہ عنہ کے پاس آئے اور ہم نے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم نے آپ کو کوئی خاص بات بتائی ہے جو عام لوگوں کو نہ بتائی ہو؟ وہ بولے: نہیں، سوائے اس چیز کے جو میری اس کتاب میں ہے۔ مسدد کہتے ہیں: پھر انہوں نے ایک کتاب نکالی، احمد کے الفاظ یوں ہیں اپنی تلوار کے غلاف سے ایک کتاب (نکالی) اس میں یہ لکھا تھا: سب مسلمانوں کا خون برابر ہے اور وہ غیروں کے مقابل (باہمی نصرت و معاونت میں) گویا ایک ہاتھ ہیں، اور ان میں کا ایک ادنی بھی ان کے امان کا پاس و لحاظ رکھے گا ۱؎، آگاہ رہو! کہ کوئی مومن کسی کافر کے بدلے قتل نہیں کیا جائے گا، اور نہ ہی کوئی ذمی معاہد جب تک وہ معاہد ہے قتل کیا جائے گا، اور جو شخص کوئی نئی بات نکالے گا تو اس کی ذمے داری اسی کے اوپر ہو گی، اور جو نئی بات نکالے گا، یا نئی بات نکالنے والے کسی شخص (بدعتی) کو پناہ دے گا تو اس پر اللہ کی فرشتوں کی اور تمام لوگوں کی لعنت ہے۔ مسدد کہتے ہیں: ابن ابی عروبہ سے منقول ہے کہ انہوں نے ایک کتاب نکالی۔\n§وضاحت\n۱؎ : یعنی کوئی ادنی مسلمان بھی کسی کافر کو پناہ دے دے تو کوئی مسلمان اسے توڑ نہیں سکتا۔","صحیح",{"u2":"سیدنا قیس بن عباد سے روایت ہے، انہوں نے کہا کہ میں اور اشتر سیدنا علی رضی اللہ عنہ کے ہاں گئے اور ان سے پوچھا کیا رسول اللہ صلی اللہ علیہ وسلم نے آپ کو کوئی خاص وصیت فرمائی ہے جو عام لوگوں سے نہ کہی ہو؟ انہوں نے فرمایا نہیں۔ سوائے اس کے جو میرے پاس اس مکتوب میں ہے۔ مسدد کہتے ہیں کہ پھر انہوں نے وہ تحریر نکالی۔ امام احمد بن حنبل نے کہا: انہوں نے اپنی تلوار کی میان میں سے وہ تحریر نکالی۔ تو اس میں تھا ” تمام اہل ایمان کے خون برابر ہیں اور وہ اپنے علاوہ کے مقابلے میں ایک ہاتھ ہیں (ایک دوسرے کی مدد کرنے کے پابند ہیں)۔ ان کے ذمے اور امان کا ان کا ادنیٰ سے ادنیٰ آدمی بھی پابند ہے۔ خبردار! کسی مومن کو کسی کافر کے بدلے میں اور کسی امان والے کو اس کے ایام امان میں قتل نہ کیا جائے، جس نے دین میں کوئی نیا کام کیا (بدعت ایجاد کی) تو اس کا وبال اس کی اپنی جان پر ہے، جس نے کوئی بدعت ایجاد کی یا کسی بدعتی کو جگہ دی تو اس پر اللہ کی، فرشتوں کی اور تمام لوگوں کی لعنت ہو۔ “ مسدد نے بواسطہ، ابن ابوعروبہ (یوں) روایت کیا: پھر سیدنا علی رضی اللہ عنہ نے وہ تحریر نکالی۔","f2":"1: حضرت علی رضی اللہ کے لئے کوئی خا ص انفرادی وصیت نہیں کی گئی تھی اس کی کوئی ضرورت تھی نہ اس کا کوئی ثبوت ہی ہے۔ نخلاف اس دعوی کے جس کے روافض مدعی ہیں۔ روافض کا دعوی سراسرغلط اور بے اصل ہے۔\n2:کسی مسلمان عربی،عجمی یاکالے گورے مسلمان پر کوئی فضیلت نہیں۔ خون سب کے برابر ہیں، صرف تقوے کی بنا پر فضیلت حاصل ہے،مگر اس کا علم اور فیصلہ اللہ کے پاس محفوظ ہے۔\n3:کافر کے مقابلے میں مسلمان کی مدد کرنا ہر مسلمان پر فرض ہے بشرطیکہ وہ حق پر ہوں۔\n4: کسی مسلمان کو کافر کے بدلے میں قتل نہیں کیا جا سکتا،البتہ دیت ضروری جائے گی۔\n5: دین میں بدعت (نئی ایجاد) کی قطعا کوئی گنجائش نہیں۔ دین ہر اعتبار سے کامل اور مکمل ہے۔ بدعتی آدمی اللہ کی مخلوق میں ملعون ہے۔ ایسے آدمی کو عزت دینا حرام ہے۔ معاملات کی دنیا میں مروت اور رواداری ایک الگ مسئلہ ہے۔"}],[4531,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: … پھر راوی نے علی رضی اللہ عنہ کی حدیث کی طرح ذکر کیا البتہ اس میں اتنا اضافہ ہے کہ ان کا ادنی شخص بھی امان دے سکتا ہے اور مال غنیمت میں عمدہ جانور اور کمزور جانور والے دونوں برابر ہیں، جو لشکر سے باہر نکلے اور لڑے اور وہ جو لشکر میں بیٹھا رے دونوں برابر ہیں۔","حسن صحیح",{"u2":"جناب عمرو بن شعیب اپنے والد سے، وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور مذکورہ بالا روایت علی کی مانند ذکر دیا۔ اس میں اضافہ ہے ” ان کا (مسلمانوں کا) بعید ترین فرد بھی امان دے سکتا ہے۔ اور ان کا تنومند اور قوی رفتار اپنے ضعیف اور سست رفتار کو بھی ساتھ ملائے (مال غنیمت میں اس کو شریک کرے) اور چھوٹے دستے میں جانے والا بڑے لشکر میں رہ جانے والوں کو بھی شریک سمجھے۔ “","f2":"آخری جملے کا مطلب یہ ہے کہ جہاد میں شریک ہونے والے تمام مجاہد مال غنیمت میں حصے دار ہوں گے،حتی کہ اگر ایک چھوٹا دستہ،بڑے لشکر سے الگ ہو کر کوئی جہاد معرکہ سر کرے اور وہاں سے مال غنیمت حاصل کرے تو اس میں بڑے لشکر والے بھی جو اپنے امیر کے ساتھ بیٹھے رہے،شریک ہوں گے۔"}],[4532,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ سعد بن عبادہ رضی اللہ عنہ نے کہا: اللہ کے رسول! اگر کوئی شخص اپنی بیوی کے ساتھ کسی مرد کو پائے تو کیا اسے قتل کر دے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں\" سعد نے کہا: کیوں نہیں، اللہ کے رسول! قسم ہے اس ذات کی جس نے آپ کو حق کے ساتھ عزت دی (میں تو اسے قتل کر دوں گا) نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سنو! جو تمہارے سردار کہہ رہے ہیں\" (عبدالوہاب کے الفاظ ہیں، (سنو) جو سعد کہہ رہے ہیں) ۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ سیدنا سعد بن عبادہ رضی اللہ عنہ نے کہا: اے اللہ کے رسول! اگر کوئی شخص اپنی بیوی کے ساتھ کسی غیر مرد کو دیکھے تو کیا اسے قتل کر ڈالے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” نہیں۔ “ سیدنا سعد رضی اللہ عنہ بولے: کیوں نہیں، قسم اس ذات کی جس نے آپ کو حق کے ساتھ عزت دی! نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اپنے سردار کی بات سنو، کیا کہہ رہا ہے۔ “ عبدالوہاب کی روایت میں ہے ” سنو سعد کیا کہہ رہا ہے۔ “ (یعنی بہت ہی غیرت مند ہیں۔)"}],[4533,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: بتائیے اگر میں اپنی بیوی کے ساتھ کسی مرد کو پاؤں تو کیا چار گواہ لانے تک اسے مہلت دوں؟ آپ نے فرمایا: \"ہاں\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ سیدنا سعد بن عبادہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے کہا: فرمائیے کہ اگر میں اپنی بیوی کے ساتھ کسی غیر آدمی کو پاؤں تو کیا اسے چھوڑ دوں حتیٰ کہ چار گواہ لاؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہاں۔“","f2":"دوسری احادیث میں ہے،رسول اللہ صلی اللہ علیہ وسلم نے فرمایا دیکھو سعد کس قدر غیرت مندہے اور میں اس سے زیادی غیرت مند ہوں اور اللہ سب سے بڑھ کر غیرت والا ہے۔\n2: اس حدیث میں یہ بیان ہوا ہے کہ صاحب ایمان کو اللہ کی حدود پر ٹھہرنے والا ہونا چاہیے نہ ان سے تجاوز کرنے والا۔ اسلام میں انسانی جان کی بہت زیادہ قدراہمیت ہے اور اس قسم کے حادثے میں بھی کسی کو قتل کرنے کی اجازت نہیں بلکہ چار گواہوں یا اقرر ہو تو تن رجم ہو گا۔ اگر گواہ ہوں،نہ عورت کا اقراربلکہ صرف خاوند کا دعوی ہو تو اس صورت میں رجم نہیں ہو گا،بلکہ لعان ہو گا۔"}],[4534,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں نبی اکرم صلی اللہ علیہ وسلم نے ابوجہم بن حذیفہ کو زکاۃ وصول کرنے کے لیے بھیجا، ایک شخص نے اپنی زکاۃ کے سلسلہ میں ان سے جھگڑا کر لیا، ابوجہم نے اسے مارا تو اس کا سر زخمی ہو گیا، تو لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اللہ کے رسول! قصاص دلوائیے، اس پر آپ نے ان سے فرمایا: \"تم اتنا اور اتنا لے لو\" لیکن وہ لوگ راضی نہیں ہوئے، تو آپ نے فرمایا: \"اچھا اتنا اور اتنا لے لو\" وہ اس پر بھی راضی نہیں ہوئے تو آپ نے فرمایا: \"اچھا اتنا اور اتنا لے لو\" اس پر وہ رضامند ہو گئے پھر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آج شام کو میں لوگوں کے سامنے خطبہ دوں گا اور انہیں تمہاری رضا مندی کی خبر دوں گا\" لوگوں نے کہا: ٹھیک ہے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا، اور فرمایا: \"قبیلہ لیث کے یہ لوگ قصاص کے ارادے سے میرے پاس آئے ہیں تو میں نے ان کو اتنا اور اتنا مال پیش کیا اس پر یہ راضی ہو گئے ہیں (پھر آپ نے انہیں مخاطب کر کے پوچھا:)بتاؤ کیا تم لوگ راضی ہو؟\" انہوں نے کہا: نہیں، تو مہاجرین ان پر جھپٹے تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں ان سے باز رہنے کا حکم دیا، چنانچہ وہ رک گئے، پھر آپ نے انہیں بلایا، اور کچھ اضافہ کیا پھر پوچھا: \"کیا اب تم راضی ہو؟\" انہوں نے کہا: ہاں، آپ نے فرمایا: \"میں لوگوں کو خطاب کروں گا، اور انہیں تمہاری رضا مندی کے بارے میں بتاؤں گا\" لوگوں نے کہا: ٹھیک ہے، چنانچہ نبی اکرم صلی اللہ علیہ وسلم نے خطاب کیا، اور پوچھا: \"کیا تم راضی ہو؟\" وہ بولے: ہاں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ابوجہم بن حذیفہ رضی اللہ عنہ کو زکوٰۃ کا عامل بنا کر بھیجا۔ صدقے (کے حساب) میں ان کا ایک آدمی سے جھگڑا ہو گیا تو ابوجہم رضی اللہ عنہ نے اس کو مارا اور زخمی کر دیا۔ تو وہ لوگ نبی کریم صلی اللہ علیہ وسلم کے پاس چلے آئے اور کہنے لگے: اے اللہ کے رسول! ہم بدلہ لیں گے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہم تمہیں اس اس قدر مال دیتے ہیں۔ “ مگر وہ راضی نہ ہوئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” چلو اس اس قدر لے لو۔ “ وہ راضی نہ ہوئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس اس قدر لے لو۔ “ تو وہ راضی ہو گئے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” آج شام میں خطبہ دوں گا اور لوگوں کو بتاؤں گا کہ تم لوگ راضی ہو گئے ہو۔ “ انہوں نے کہا: ٹھیک ہے۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا اور فرمایا ” بنو لیث کے یہ لوگ میرے پاس قصاص کا مطالبہ لے کر آئے تھے تو میں نے انہیں اس اس قدر مال کی پیش کش کی ہے تو وہ راضی ہو گئے ہیں۔ (پھر آپ بنو لیث سے مخاطب ہوئے) کیا تم رضامند ہو؟ “ انہوں نے کہا: نہیں۔ اس پر مہاجرین بھنا اٹھے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں ان سے باز رکھا تو وہ رک گئے۔ آپ نے ان لوگوں کو پھر بلایا اور مزید مال کی پیشکش کی اور ان سے پوچھا ” کیا تم راضی ہو؟ “ انہوں نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں لوگوں کو خطبہ دوں گا اور انہیں تمہاری رضا مندی کا بتاؤں گا۔ “ انہوں نے کہا: ٹھیک ہے۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا اور (ان سے) پوچھا ” کیا تم راضی ہو؟ “ انہوں نے کہا: ہاں (ہم راضی ہیں)۔","f2":": بعض حضرات نے اس حدیث کی صحت تسلیم کی ہے لیکن صحیح تر بات یہ ہے کہ روایت ضعیف ہے۔"}],[4535,"انس رضی اللہ عنہ کہتے ہیں کہ ایک لڑکی ملی جس کا سر دو پتھروں کے درمیان کچل دیا گیا تھا، اس سے پوچھا گیا: تمہارے ساتھ یہ کس نے کیا؟ کیا فلاں نے؟ کیا فلاں نے؟ یہاں تک کہ ایک یہودی کا نام لیا گیا، تو اس نے اپنے سر کے اشارہ سے کہا: ہاں، چنانچہ اس یہودی کو پکڑا گیا، اس نے اقبال جرم کر لیا تو نبی اکرم صلی اللہ علیہ وسلم نے حکم دیا کہ اس کا سر پتھر سے کچل دیا جائے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک لڑکی پائی گئی جس کا سر دو پتھروں میں رکھ کر کچل دیا گیا تھا۔ تو اس سے پوچھا گیا: تیرے ساتھ یہ کس نے کیا ہے؟ کیا فلاں نے، کیا فلاں نے؟ حتیٰ کہ ایک یہودی کا نام لیا گیا تو اس نے اپنے سر کے ساتھ اشارہ کیا (کہ ہاں)۔ وہ یہودی پکڑ لیا گیا تو اس نے اقرار کر لیا۔ پھر نبی کریم صلی اللہ علیہ وسلم نے حکم دیا کہ اس کا سر بھی پتھر سے کچلا جائے۔","f2":"مجرم سے قصاص لینے کی ایک صورت یہ بھی ہے کہ جس انداز سے اس نے قتل کیا ہو اسی اندازسے اسے قتل کیا جائے جیسے اس واقعہ میں ہے اور عکل اور عرینہ کے لوگوں کے ساتھ بھی اسی طرح کیا گیا تھا۔"}],[4536,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کچھ تقسیم کر رہے تھے کہ اسی دوران ایک شخص آیا اور آپ کے اوپر جھک گیا تو اس کے چہرے پر خراش آ گئی تو آپ نے ایک لکڑی جو آپ کے پاس تھی اسے چبھو دی، رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"آؤ قصاص لے لو ۱؎\" وہ بولا: اللہ کے رسول! میں نے معاف کر دیا۔\n§وضاحت\n۱؎ : سبحان اللہ ! رسول اکرم صلی اللہ علیہ وسلم کس قدر عادل تھے کہ جو تکلیف کسی کو غلطی سے پہنچ جاتی اس سے بھی قصاص لینے کو کہتے اور اپنی عظمت کا خیال نہ کرتے۔","ضعیف",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ ایک بار رسول اللہ صلی اللہ علیہ وسلم کچھ تقسیم کر رہے تھے کہ ایک آدمی آیا اور آپ صلی اللہ علیہ وسلم کے اوپر جھک گیا، تو آپ صلی اللہ علیہ وسلم نے اپنی کھجور کی لاٹھی سے جو آپ کے پاس تھی اسے کچوکا دیا، پس اس سے اس کا چہرہ زخمی ہو گیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا ” آؤ اور اپنا بدلہ لے لو۔ “ اس نے جواب دیا اے اللہ کے رسول! میں نے معاف کیا۔","f2":"یہ روایت سندا ضعیف ہے مگر باب بالکل صحیح ہے کہ نبی صلی اللہ علیہ وسلم اپنے آپ کو بدلہ دینے کےلئے پیش فرما دیا کرتے تھے جیسے کہ آئندہ حدیث 5224 میں آرہا ہے۔"}],[4537,"ابوفراس کہتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے ہم سے خطاب کیا اور کہا: \"میں نے اپنے گورنر اس لیے نہیں بھیجے کہ وہ تمہاری کھالوں پہ ماریں، اور نہ اس لیے کہ وہ تمہارے مال لیں، لہٰذا اگر کسی کے ساتھ ایسا سلوک ہو تو وہ اسے مجھ تک پہنچائے، میں اس سے اسے قصاص دلواؤں گا\" عمرو بن العاص رضی اللہ عنہ نے کہا: اگر کوئی شخص اپنی رعیت کو تادیباً سزا دے تو اس پر بھی آپ اس سے قصاص لیں گے، وہ بولے: \"ہاں، قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! میں اس سے قصاص لوں گا\" میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے اپنی ذات سے قصاص دلایا۔","ضعیف",{"u2":"جناب ابوفراس (ربیع بن زیاد بن انس حارثی) سے روایت ہے، وہ کہتے ہیں کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے ہمیں خطبہ دیا اور کہا: میں اپنے عمال اس لیے نہیں بھیجتا کہ تمہارے جسموں پر ماریں یا تمہارے مال تم سے چھین لیں۔ اگر کسی کے ساتھ ایسا ہو تو اسے چاہیئے کہ اپنا مقدمہ میرے پاس لائے تاکہ میں اس سے قصاص لوں۔ تو سیدنا عمرو بن العاص رضی اللہ عنہ نے کہا: اگر کسی نے اپنی رعایا میں سے کسی کی تادیب کی ہو (اسے سزا دی ہو) تو کیا آپ اس کا بدلہ لیں گے؟ فرمایا: ہاں، قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! میں اس سے بدلہ لوں گا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے کہ وہ اپنی ذات سے بدلہ دلواتے تھے۔"}],[4538,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لڑنے والوں پر لازم ہے کہ وہ قصاص لینے سے باز رہیں، پہلے جو سب سے قریبی ہے وہ معاف کرے، پھر اس کے بعد والے خواہ وہ عورت ہی ہو\"۔ ابوداؤد کہتے ہیں: مجھے یہ بات معلوم ہوئی ہے کہ عورتوں کا قتل کے سلسلے میں قصاص معاف کر دینا جائز ہے جب وہ مقتول کے اولیاء میں سے ہوں، اور مجھے ابو عبید کے واسطے سے یہ بات پہنچی ہے کہ آپ کے قول «ينحجزوا» کے معنی قصاص سے باز رہنے کے ہیں۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” لڑائی کرنے (قصاص کا مطالبہ کرنے) والے بدلہ لینے میں حوصلے سے کام لیں (جلدی نہ کریں)۔ وارثوں میں سے معاف کرنے کا حق درجہ بدرجہ ہے، خواہ کوئی عورت ہی ہو۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا: «ينحجزوا» کے معنی ہیں ” قصاص لینے سے رک جانا۔ “ مزید فرماتے ہیں کہ مجھے یہ بات پہنچی ہے کہ قتل کے معاملے میں وارثوں میں اگر کوئی عورت بھی ہو تو وہ بھی معاف کر سکتی ہے۔ اور «أن ينحجزوا» کے معنی کے سلسلے میں ابوعبیدہ سے مجھے یہ بیان کیا گیا ہے کہ اس کا مفہوم ہے ” قصاص لینے سے باز رہیں۔“"}],[4539,"طاؤس کہتے ہیں کہ جو مارا جائے، اور ابن عبید کی روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی کسی لڑائی یا دنگے میں جو لوگوں میں چھڑ گئی ہو غیر معروف پتھر، کوڑے، یا لاٹھی سے مارا جائے ۱؎ تو وہ قتل خطا ہے، اور اس کی دیت قتل خطا کی دیت ہو گی، اور جو قصداً مارا جائے تو اس میں قصاص ہے\" (البتہ ابن عبید کی روایت میں ہے کہ) اس میں ہاتھ کا قصاص ہے، ۲؎ (پھر دونوں کی روایت ایک ہے کہ) جو کوئی اس کے بیچ بچاؤ میں پڑے ۳؎ تو اس پر اللہ کی لعنت، اور اس کا غضب ہو، اس کی نہ توبہ قبول ہو گی اور نہ فدیہ، یا اس کے فرض قبول ہوں گے نہ نفل اور سفیان کی حدیث زیادہ کامل ہے۔\n§وضاحت\n۱؎ : یعنی اس کے قاتل کا پتہ نہ چل سکے۔ ۲؎ : یعنی جان کا قصاص ہے جان کی تعبیر ہاتھ سے کی گئی ہے۔ ۳؎ : یعنی قصاص نہ لینے دے۔","صحیح",{"u2":"جناب طاؤس رضی اللہ عنہ سے روایت ہے کہ جو کوئی کسی بلوے میں مارا گیا ہو۔ اور ابن عبید کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا &rdquo; جو شخص کسی بلوے میں مارا گیا ہو (کہ اس کا قاتل دیکھا نہ گیا ہو) سنگباری ہوئی ہو یا ڈنڈے بازی یا کسی لاٹھی سے مرا ہو تو یہ قتل خطا ہے، اس کی دیت قتل خطا والی ہو گی۔ البتہ جو شخص (جان بوجھ کر) عمداً قتل کیا گیا ہو تو اس میں قصاص ہے۔ &ldquo; ابن عبید کے لفظ ہیں &laquo;قود يد&raquo; (قاتل کی جان سے قصاص لیا جائے گا) اور جو اس (قصاص لینے) میں رکاوٹ بنے تو اس پر اللہ کی لعنت اور غضب ہو، اس کا کوئی نفل یا فرض مقبول نہیں۔ &ldquo; سفیان کی حدیث زیادہ کامل ہے۔"}],[4540,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، آگے راوی نے سفیان کی حدیث کے ہم معنی حدیث ذکر کی۔","صحیح",{"u2":"جناب طاؤس نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کیا، کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور مذکورہ بالا روایت سفیان کی مانند بیان کیا۔"}],[4541,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا: \"جو غلطی سے مارا گیا تو اس کی دیت سو اونٹ ہے تیس بنت مخاض ۱؎ تیس بنت لبون ۲؎ تیس حقے ۳؎ اور دس نر اونٹ جو دو برس کے ہو چکے ہوں\"۔\n§وضاحت\n۱؎ : ایسی اونٹنی جو ایک برس کی ہو چکی ہو۔ ۲؎ : ایسی اونٹنی جو دو برس کی ہو چکی ہو۔ ۳؎ : ایسی اونٹنی جو تین برس کی ہو چکی ہو۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ جو شخص غلطی سے قتل کیا گیا ہو تو اس کی دیت ایک سو اونٹ ہے۔ تیس اونٹنیاں مؤنث ایک سالہ، تیس اونٹنیاں مؤنث دو سالہ، تیس اونٹنیاں مؤنث تین سالہ اور دس عدد اونٹ مذکر دو سالہ۔"}],[4542,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں دیت کی قیمت ۱؎ آٹھ سو دینار، یا آٹھ ہزار درہم تھی، اور اہل کتاب کی دیت اس وقت مسلمانوں کی دیت کی آدھی تھی، پھر اسی طرح حکم چلتا رہا، یہاں تک کہ عمر رضی اللہ عنہ خلیفہ ہوئے تو آپ نے کھڑے ہو کر خطبہ دیا، اور فرمایا: سنو، اونٹوں کی قیمت بڑھ گئی ہے، تو عمر رضی اللہ عنہ نے سونے والوں پر ایک ہزار دینار، اور چاندی والوں پر بارہ ہزار (درہم) دیت ٹھہرائی، اور گائے بیل والوں پر دو سو گائیں، اور بکری والوں پر دو ہزار بکریاں، اور کپڑے والوں پر دو سو جوڑوں کی دیت مقرر کی، اور ذمیوں کی دیت چھوڑ دی، ان کی دیت میں (مسلمانوں کی دیت کی طرح) اضافہ نہیں کیا۔\n§وضاحت\n۱؎ : یعنی دیت کے اونٹوں کی قیمت۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں دیت کی قیمت آٹھ سو دینار (سونے کے) یا آٹھ ہزار درہم (چاندی کے) تھی اور ان دنوں اہل کتاب کی دیت مسلمانوں کی دیت کے مقابلے میں آدھی ہوتی تھی۔ چنانچہ معاملہ ایسے ہی رہا حتیٰ کہ سیدنا عمر رضی اللہ عنہ خلیفہ بنے۔ تو انہوں نے خطبہ دیا اور کہا: بلاشبہ اونٹ مہنگے ہو گئے ہیں، پھر آپ نے یہ دیت سونے والوں پر ایک ہزار دینار اور چاندی والوں پر بارہ ہزار دینار کر دی، گائے والوں کے لیے دو سو گائے اور بکریوں والوں کے لیے دو ہزار بکریاں، حلے (خاص قسم کے کپڑے) تیار کرنے والوں کے لیے دو سو حلے مقرر کی، اور ذمی لوگوں کی دیت ویسے ہی رہنے دی اور اسے نہیں بڑھایا۔","f2":"حکومت اسلامیہ کے اصحاب حل وعقد پر لازم ہے کہ دیت جیسے شرعی واجبات میں بازار کے بھاوکے مطابق عوام میں اعلان عام کرتے رہا کریں تاکہ کسی پر ظلم نہ ہو۔"}],[4543,"عطا بن ابی رباح سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دیت کے سلسلے میں فیصلہ فرمایا کہ اونٹ والوں پر سو اونٹ، گائے بیل والوں پر دو سو گائیں، بکری والوں پر دو ہزار بکریاں، اور کپڑے والوں پر دو سو جوڑے کپڑے، اور گیہوں والوں پر بھی کچھ مقرر کیا جو محمد (محمد بن اسحاق) کو یاد نہیں رہا۔","ضعیف",{"u2":"جناب عطاء بن ابی رباح رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دیت کی شرح یوں مقرر فرمائی تھی کہ اونٹوں والوں پر ایک سو اونٹ، گائے والوں پر دو سو گائے، بکریوں والوں پر دو ہزار بکریاں، حلے والوں پر دو سو حلے اور گندم والوں پر بھی کچھ مقرر کی تھی جو محمد بن اسحاق کو یاد نہیں رہی۔"}],[4544,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مقرر کیا پھر راوی نے ایسے ہی ذکر کیا جیسے موسی کی روایت میں ہے البتہ اس میں اس طرح ہے کہ طَعام والوں پر کچھ مقرر کیا جو کہ مجھ کو یاد نہیں رہا۔","ضعیف",{"u2":"جناب عطاء (عطاء بن ابی رباح) نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے (دیت کی شرح) مقرر کی اور مذکورہ بالا حدیث موسیٰ بن اسماعیل کی مانند روایت کی۔ اور کہا کہ غلے والوں پر بھی کچھ مقرر کی تھی جو مجھے یاد نہیں۔"}],[4545,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قتل خطا کی دیت میں بیس حقے، بیس جزعے، بیس بنت مخاض، بیس بنت لبون اور بیس ابن مخاض ہیں\" اور یہی عبداللہ بن مسعود کا قول ہے۔","ضعیف",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” قتل خطا کی دیت بیس اونٹنیاں تین سالہ، بیس اونٹنیاں چار سالہ، بیس اونٹنیاں ایک سالہ، بیس اونٹنیاں دو سالہ اور بیس اونٹ مذکر ایک سالہ۔ “ اور سیدنا عبداللہ رضی اللہ عنہ کا قول بھی یہی ہے۔"}],[4546,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ بنی عدی کے ایک شخص کو قتل کر دیا گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کی دیت بارہ ہزار ٹھہرائی۔ ابوداؤد کہتے ہیں: اسے ابن عیینہ نے عمرو سے، عمرو نے عکرمہ سے اور عکرمہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کیا ہے اور اس میں انہوں نے ابن عباس کا ذکر نہیں کیا ہے۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ بنو عدی کا ایک آدمی قتل ہو گیا تو نبی کریم صلی اللہ علیہ وسلم نے اس کی دیت بارہ ہزار (درہم) طے فرمائی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو ابن عیینہ نے بواسطہ عمرو، عکرمہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیان کیا مگر اس میں سیدنا ابن عباس رضی اللہ عنہ کا واسطہ ذکر نہیں کیا۔"}],[4547,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (مسدد کی روایت کے مطابق) فتح مکہ کے دن مکہ میں خطبہ دیا، آپ نے تین بار اللہ اکبر کہا، پھر فرمایا: «لا إله إلا الله وحده صدق وعده ونصر عبده وهزم الأحزاب وحده» \"اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ تنہا ہے، اس نے اپنا وعدہ سچ کر دکھایا، اپنے بندے کی مدد کی، اور تنہا لشکروں کو شکست دی\" (یہاں تک کہ حدیث مجھ سے صرف مسدد نے بیان کی ہے صرف انہیں کے واسطہ سے میں نے اسے یاد کیا ہے اور اس کے بعد سے اخیر حدیث تک سلیمان اور مسدد دونوں نے مجھ سے بیان کیا ہے آگے یوں ہے) سنو! وہ تمام فضیلتیں جو جاہلیت میں بیان کی جاتی تھیں اور خون یا مال کے جتنے دعوے کئے جاتے تھے وہ سب میرے پاؤں تلے ہیں (یعنی لغو اور باطل ہیں) سوائے حاجیوں کو پانی پلانے اور بیت اللہ کی خدمت کے (یہ اب بھی ان کے ہی سپرد رہے گی جن کے سپر د پہلے تھی\" پھر فرمایا: \"سنو! قتل خطا یعنی قتل شبہ عمد کوڑے یا لاٹھی سے ہونے کی دیت سو اونٹ ہے جن میں چالیس اونٹنیاں ایسی ہوں گی جن کے پیٹ میں بچے ہوں\" (اور مسدد والی روایت زیادہ کامل ہے) ۔","حسن",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن خطبہ دیا اور تین بار &laquo;الله اكبر&raquo; کہا۔ پھر فرمایا &laquo;لا إله إلا الله وحده صدق وعده ونصر عبده وهزم الأحزاب وحده&raquo; &rdquo; ایک اللہ کے سوا کوئی معبود نہیں، اس نے اپنا وعدہ سچا کر دکھایا، اپنے بندے کی مدد کی۔ اور اس ایک اکیلے ہی نے تمام گروہوں کو پسپا کر دیا &ldquo; یہاں تک کی روایت مجھے مسدد سے یاد ہے۔ پھر سلیمان بن حرب اور مسدد دونوں روایت کرنے میں متفق ہیں، فرمایا &rdquo; خبردار! جاہلیت میں ذکر کیے جانے والے تمام مفاخر یا خون اور مال کے مطالبات میرے پاؤں تلے روندے جا رہے ہیں۔ (ان کی کوئی حیثیت نہیں اور کوئی مطالبہ نہیں ہو گا) سوائے اس کے جو حاجیوں کو پانی پلانے کی خدمت تھی یا بیت اللہ کی خدمت کا شرف تھا (وہ باقی رہے گا)۔ &ldquo; پھر فرمایا &rdquo; خبردار! قتل خطا جو عمد کے مشابہ ہو، جو سانٹے یا لاٹھی کی مار سے ہوا ہو اس کی دیت سو اونٹ ہے۔ ان میں چالیس اونٹنیاں ایسی ہوں جن کے پیٹوں میں بچے ہوں۔&ldquo; اور مسدد کی روایت زیادہ کامل ہے۔","f2":"قتل خطا شبہ عمد کی دیت کا یہ باب اس مقام پر بعض نسخوں کے اعتبار سے ہے،ورنہ اکثر نسخوں میں یہ باب فیمن تطبب۔۔۔ کے بعد ہے،جیسا کہ اس نسخے میں بھی دوبارہ یہ باب وہاں موجو د ہے،قتل کی تین قسمیں ہیں۔ قتل عمد (جو قصدجان بوجھ کر ہو) قتل خطا (جو بلا قصد وارادہ ہو جائے) قتل خطا شبہ العمد یعنی مارنے والے نے قصد کو ئی ایسی چیز ماری جس سے کوئی مرتا نہیں ہے۔،نہ اس کی نیت ہی اسے قتل کرنے کی تھی۔ مثلا لاٹھی،کوڑا یا پتھر مارا جس سے آدمی عموما مرتا نہیں ہے،مگر اتفاقامضروب مر گیا۔"}],[4548,"اس سند سے بھی اسی مفہوم کی حدیث مروی ہے۔","",{"u2":"موسیٰ بن اسماعیل نے بیان کیا، انہوں نے کہا کہ ہمیں وہیب نے خالد سے حدیث بیان کی اسی اسناد سے اور مذکورہ بالا کے ہم معنی روایت کیا۔"}],[4549,"عبداللہ بن عمر رضی اللہ عنہما نبی اکرم صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث روایت کرتے ہیں اس میں ہے: \"رسول اللہ صلی اللہ علیہ وسلم نے فتح کے دن یا فتح مکہ کے دن بیت اللہ یا کعبہ کی سیڑھی پر خطبہ دیا\"۔ ابوداؤد کہتے ہیں: اسے ابن عیینہ نے بھی اسی طرح علی بن زید سے، علی بن زید نے قاسم بن ربیعہ سے، قاسم نے ابن عمر سے اور ابن عمر نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے، اور اسے ایوب سختیانی نے قاسم بن ربیعہ سے، قاسم نے عبداللہ بن عمرو رضی اللہ عنہما سے خالد کی حدیث کے مثل روایت کی ہے۔ نیز اسے حماد بن سلمہ نے علی بن زید سے، علی بن زید نے یعقوب سدوسی سے، سدوسی نے عبداللہ بن عمرو سے، اور عبداللہ بن عمرو نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کیا ہے، اور زید اور ابوموسی کا قول نبی اکرم صلی اللہ علیہ وسلم کی حدیث اور عمر رضی اللہ عنہ کی حدیث کے مثل ہے۔","ضعیف",{"u2":"قاسم بن ربیعہ نے بواسطہ حضرت ابن عمر رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے اس حدیث کے ہم معنی روایت کیا انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن بیت اللہ کی سیڑھی پر کھڑے ہو کر خطبہ ارشاد فرمایا۔\nامام ابوداؤد رضی اللہ عنہ فرماتے ہیں: ابن عیینہ نے بسند علی بن زید، قاسم بن ربیعہ سے، انہوں نے ابن عمر رضی اللہ عنہ سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے ایسے ہی روایت کیا ہے۔ اور ایوب سختیانی نے قاسم بن ربیعہ سے، انہوں نے عبداللہ بن عمرو سے خالد کی حدیث کی مانند روایت کیا ہے۔ اور حماد بن سلمہ نے بسند علی بن زید، یعقوب سدوسی سے، انہوں نے عبداللہ بن عمرو رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے۔ زید اور ابوموسیٰ کا قول حدیث نبوی اور روایت عمر رضی اللہ عنہ (جو آگے آ رہی ہے) کے مطابق ہے"}],[4550,"مجاہد کہتے ہیں عمر نے قتل شبہ عمد میں تیس حقہ، تیس جزعہ، چالیس گابھن اونٹنیوں (جو چھ برس سے نو برس تک کی ہوں) کی دیت کا فیصلہ کیا۔","ضعیف الإسناد",{"u2":"مجاہد روایت کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے شبہ عمد میں فیصلہ کیا تھا کہ تیس اونٹنیاں تین سالہ، تیس اونٹنیاں چار سالہ اور چالیس اونٹنیاں جو حاملہ ہوں اور ان کی عمر میں دو دانتا یعنی چھٹے سے لے کر نویں سال میں شروع ہونے والی کے درمیان ہوں۔"}],[4551,"علی رضی اللہ عنہ کہتے ہیں شبہ عمد کی دیت میں تین قسم کے اونٹ ہوں گے، تینتیس حقہ، تینتیس جذعہ اور چونتیس ایسی اونٹنیاں جو چھ برس سے لے کر نو برس تک کی ہوں اور سب گابھن ہوں۔","ضعیف الإسناد",{"u2":"سیدنا علی رضی اللہ عنہ سے مروی ہے انہوں نے فرمایا کہ شبہ عمد کی دیت میں اونٹ تین قسموں کے ہوں: تینتیس اونٹنیاں تین سالہ، تینتیس اونٹنیاں چار سالہ اور چونتیس اونٹنیاں چھ سے نو سالہ کے درمیان ہوں اور (یہ آخری) سب حاملہ ہوں۔"}],[4552,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں شبہ عمد کی دیت پچیس حقہ، پچیس جزعہ، پچیس بنت لبون، اور پچیس بنت مخاض ہے۔","ضعیف الإسناد",{"u2":"سیدنا علی رضی اللہ عنہ سے مروی ہے کہ قتل خطا میں دیت کے اونٹ چار طرح کے ہوں: پچیس اونٹنیاں تین سالہ، پچیس اونٹنیاں چار سالہ، پچیس اونٹنیاں دو سالہ اور پچیس اونٹنیاں ایک سالہ ہوں۔"}],[4553,"علی رضی اللہ عنہ کہتے ہیں قتل خطا کی دیت میں چار قسم کے اونٹ ہوں گے: پچیس حقہ، پچیس جزعہ، پچیس بنت لبون، اور پچیس بنت مخاض۔","ضعیف الإسناد",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ شبہ عمد کی دیت میں اونٹوں کی تفصیل یہ ہے کہ پچیس اونٹنیاں تین سالہ، پچیس اونٹنیاں چار سالہ، پچیس اونٹنیاں دو سالہ اور پچیس اونٹنیاں ایک سالہ ہوں"}],[4554,"عثمان بن عفان اور زید بن ثابت رضی اللہ عنہما سے روایت ہے کہ دیت مغلظہ یعنی شبہ عمد میں چالیس گابھن جزعہ، تیس حقہ اور تیس بنت لبون ہیں، اور دیت خطا میں تیس حقہ، تیس بنت لبون، بیس ابن لبون، اور بیس بنت مخاض ہیں۔","صحیح",{"u2":"سیدنا عثمان بن عفان اور زید بن ثابت رضی اللہ عنہ سے مروی ہے کہ مغلظ دیت کی تفصیل یہ ہے کہ چالیس اونٹنیاں چار سالہ اور حاملہ، تیس اونٹنیاں تین سالہ اور تیس اونٹنیاں دو سالہ ہوں اور قتل خطا میں تیس اونٹنیاں تین سالہ، تیس اونٹنیاں دو سالہ، بیس اونٹ مذکر دو سالہ اور بیس اونٹنیاں ایک سالہ۔"}],[4555,"زید بن ثابت سے دیت مغلظہ یعنی شبہ عمد میں مروی ہے پھر راوی نے ہو بہو اسی کے مثل ذکر کیا جیسے اوپر گزرا۔","صحیح الإسناد"],[4556,"ابوموسی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انگلیاں سب برابر ہیں، ان کی دیت دس دس اونٹ ہیں\"۔","صحیح",{"u2":"سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” انگلیاں سب برابر ہیں۔ (ہر ایک کی دیت) دس دس اونٹ ہے۔ “","f2":"انگلیاں ہاتھ کی ہوں یا پاوں کی انگھوٹھا،چنگلیاوغیرہ سبھی برابر ہیں،ہر ایک میں دس دس اونٹ دیت ہیں۔"}],[4557,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انگلیاں تمام برابر ہیں\" میں نے عرض کیا، کیا ہر انگلی کی دیت دس دس اونٹ ہے؟ آپ نے فرمایا: \"ہاں\"۔","صحیح",{"u2":"سیدنا (ابوموسیٰ اشعری) اشعری رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” انگلیاں سب برابر ہیں۔ “ (مسروق کہتے ہیں) میں نے کہا: دس دس اونٹ؟ انہوں نے کہا: ” ہاں۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ حدیث محمد بن جعفر نے شعبہ سے، اس نے غالب سے روایت کی تو کہا: میں نے مسروق بن اوس سے سنا۔ اور اسماعیل نے روایت کی تو کہا: مجھے غالب التمار نے ابوولید کی سند سے بیان کی۔ اور حنظلہ بن ابو صفیہ نے غالب سے اسماعیل کی سند سے بیان کی۔"}],[4558,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ اور یہ برابر ہیں\" یعنی انگوٹھا اور چھنگلی (کانی انگلی)۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یہ اور یہ برابر ہیں۔ “ یعنی انگوٹھا اور چھنگلیا۔"}],[4559,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"انگلیاں سب برابر ہیں، دانت سب برابر ہیں، سامنے کے دانت ہوں، یا ڈاڑھ کے سب برابر ہیں، یہ بھی برابر اور وہ بھی برابر\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” انگلیاں سب برابر ہیں، دانت سب برابر ہیں، آگے کے دو دانت اور ڈاڑھیں، یہ اور یہ سب برابر ہیں۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یہ روایت نضر بن شمیل نے شعبہ سے (مذکورہ بالا روایت) عبدالصمد کے ہم معنی بیان کی۔ امام ابوداؤد رضی اللہ عنہ نے کہا: ہمیں (ابوجعفر احمد بن سعید) دارمی نے نضر (نضر بن شمیل) سے یہ حدیث بیان کی۔"}],[4560,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دانت سب برابر ہیں اور انگلیاں سب برابر ہیں\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” دانت سب برابر ہیں اور انگلیاں (سب) برابر ہیں۔“"}],[4561,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دونوں ہاتھ اور دونوں پیر کی انگلیوں کو برابر قرار دیا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دونوں ہاتھ اور دونوں پاؤں کی انگلیاں، سب برابر قرار دی ہیں۔"}],[4562,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنے خطبے میں جبکہ آپ اپنی پیٹھ کعبہ سے ٹیکے ہوئے تھے فرمایا: \"انگلیوں میں دس دس اونٹ ہیں\"۔","حسن صحیح",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ بی کریم صلی اللہ علیہ وسلم نے اپنے خطبے میں ارشاد فرمایا جب کہ آپ صلی اللہ علیہ وسلم اپنی کمر کعبہ سے لگائے ہوئے تھے ” انگلیوں میں دس دس اونٹ ہیں۔ “"}],[4563,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم کرم صلی اللہ علیہ وسلم نے فرمایا: \"دانتوں میں پانچ پانچ (اونٹ) ہیں\"۔","حسن صحیح",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” دانتوں میں پانچ پانچ اونٹ ہیں۔ “"}],[4564,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم گاؤں والوں پر قتل خطا کی دیت کی قیمت چار سو دینار، یا اس کے برابر چاندی سے لگایا کرتے تھے، اور اس کی قیمت اونٹوں کی قیمتوں پر لگاتے، جب وہ مہنگے ہو جاتے تو آپ اس کی قیمت میں بھی اضافہ کر دیتے، اور جب وہ سستے ہوتے تو آپ اس کی قیمت بھی گھٹا دیتے، رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں یہ قیمت چار سو دینار سے لے کر آٹھ سو دینار تک پہنچی، اور اسی کے برابر چاندی سے (دیت کی قیمت) آٹھ ہزار درہم پہنچی، اور رسول اللہ صلی اللہ علیہ وسلم نے گائے بیل والوں پر (دیت میں) دو سو گایوں کا فیصلہ کیا، اور بکری والوں پر دو ہزار بکریوں کا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دیت کا مال مقتول کے وارثین کے درمیان ان کی قرابت کے مطابق تقسیم ہو گا، اب اگر اس سے کچھ بچ رہے تو وہ عصبہ کا ہے\"۔ رسول اللہ صلی اللہ علیہ وسلم نے ناک کے سلسلے میں فیصلہ کیا کہ اگر وہ کاٹ دی جائے تو پوری دیت لازم ہو گی۔ اور اگر اس کا بانسہ (دونوں نتھنوں کے بیچ کی ہڈی) کاٹا گیا ہو تو آدھی دیت لازم ہو گی، یعنی پچاس اونٹ یا اس کے برابر سونا یا چاندی، یا سو گائیں، یا ایک ہزار بکریاں۔ اور ہاتھ جب کاٹا گیا ہو تو اس میں آدھی لازم ہو گی، پیر میں بھی آدھی دیت ہو گی۔ اور مامومہ ۱؎ میں ایک تہائی دیت ہو گی، تینتیس اونٹ اور ایک اونٹ کا تہائی یا اس کی قیمت کے برابر سونا، چاندی، گائے یا بکری اور جائفہ ۲؎ میں بھی یہی دیت ہے۔ اور انگلیوں میں ہر انگلی میں دس اونٹ اور دانتوں میں ہر دانت میں پانچ اونٹ کی دیت ہو گی۔ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا:\"عورت کی جنایت کی دیت اس کے عصبات میں تقسیم ہو گی (یعنی عورت اگر کوئی جنایت کرے تو اس کے عصبات کو دینا پڑے گا) یعنی ان لوگوں کو جو ذوی الفروض سے بچا ہوا مال لے لیتے ہیں (جیسے بیٹا، چچا، باپ، بھائی وغیرہ) اور اگر وہ قتل کر دی گئی ہو تو اس کی دیت اس کے وارثوں میں تقسیم ہو گی (نہ کہ عصبات میں) اور وہی اپنے قاتل کو قتل کریں گے (اگر قصاص لینا ہو)\"۔ اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قاتل کے لیے کچھ بھی نہیں، اور اگر اس کا کوئی وارث نہ ہو تو اس کا وارث سب سے قریبی رشتے دار ہو گا لیکن قاتل کسی چیز کا وارث نہ ہو گا\"۔\n§وضاحت\n۱؎ : «مامومہ» : سر کے ایسے زخم کو کہتے ہیں جو دماغ تک پہنچ جائے۔ ۲؎ : «جائفہ» : وہ زخم ہے جو سر، پیٹ یا پیٹھ کے اندر تک پہنچ جائے اور اگر وہ زخم دوسری طرف بھی پار کر جائے تو اس میں دو تہائی دیت دینی ہو گی۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم قتل خطا میں دیہات والوں پر اونٹوں کی قیمت کے اعتبار سے دیت لاگو کرتے تھے، چار سو دینار یا اس کے مساوی چاندی۔ جب اونٹ مہنگے ہو جاتے تو آپ دیت کی قیمت بڑھا دیتے اور جب سستے ہو جاتے تو دیت کی قیمت کم کر دیتے۔ رسول اللہ صلی اللہ علیہ وسلم کے دور میں یہ قیمت چار سو دینار سے آٹھ سو دینار تک یا اس کے برابر آٹھ ہزار درہم رہی۔ رسول اللہ صلی اللہ علیہ وسلم نے گائے والوں پر دو سو گائیں لاگو کیں اور جس کی دیت میں بکریاں آتی تھیں تو ان پر دو ہزار بکریاں مقرر کیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” دیت مقتول کے وارثوں میں قرابت کے اعتبار سے ورثے میں تقسیم ہو گی اور جو باقی بچ رہے وہ عصبات کے لیے ہے۔ “ رسول اللہ صلی اللہ علیہ وسلم نے ناک کے بارے میں فیصلہ فرمایا کہ جب پوری طرح کاٹ دی گئی ہو، اس میں پوری دیت ہے اور جب اس کا سرا (بانسہ) کاٹا گیا ہو تو اس میں نصف دیت پچاس اونٹ یا اس کے برابر سونا یا چاندی یا ایک سو گائے یا ایک ہزار بکری ہے۔ اور ایک ہاتھ میں، جب وہ کاٹ دیا گیا ہو، تو اس میں آدھی دیت ہے۔ اور ایک پاؤں میں آدھی دیت ہے۔ کھوپڑی کا زخم جو دماغ تک پہنچے اس میں تہائی دیت ہے، تینتیس اونٹ اور ایک اونٹ کا تہائی یا اس کی قیمت سونا یا چاندی یا گائیں یا بکریاں۔ اور جو زخم پیٹ میں لگے تو اس میں بھی اسی طرح سے ہے۔ (تہائی دیت) اور انگلیوں میں، ہر انگلی کے بدلے دس اونٹ ہیں۔ اور دانتوں میں ہر دانت میں پانچ اونٹ ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ عورت (اگر کوئی جرم کرے تو اس) کی دیت اس کے عصبہ کے ذمے ہے یعنی جو اس حصہ کے وارث بنتے ہیں جو مقررہ حصوں کے بعد باقی بچ رہے (یعنی باپ، بیٹا، بھائی اور چچا وغیرہ) اور اگر عورت قتل ہو جائے تو اس کی دیت اس کے وارثوں میں تقسیم ہو گی اور یہی لوگ قاتل سے قصاص لینے کے حقدار ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” قاتل کے لیے کچھ نہیں۔ اور اگر مقتول کا اور کوئی وارث نہ ہو تو سب سے قریب ترین آدمی اس کا وارث ہو گا اور قاتل کو وراثت میں سے کچھ نہیں ملے گا۔ “ محمد بن راشد نے کہا: مجھے یہ تمام روایت سلیمان بن موسیٰ نے بسند عمرو بن شعیب اپنے والد سے، اس نے اپنے دادا سے، اس نے نبی کریم صلی اللہ علیہ وسلم سے بیان کی۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ محمد بن راشد اہل دمشق سے تھے اور قتل (کے خوف) سے بصرہ بھاگ گئے تھے۔","f2":"1: علماپر واجب ہے کہ مسلمانوں کو ان کے معاشرتی شرعی حقوقوحدود سے آگاہ کرتے رہا کریں۔\n2: کسی بھی مسلمان کو روا نہیں کہ مغلوب الغضب ہو کر کوئی ایسی کاروائی کرے جس سے وہ خود اس کے اقارب طعن کا نشانہ بنیں ورنہ انہیں دیت دینے کا پابند ہونا پڑے گا۔\n3: مام کے لالچ میں اپنے مورث کو قتل کر دینا انتہائی عظیم اور قبیح جرم ہے ایسے نامعقول کو دنیا وآخرت خراب ہونے کے علاوہ وراثت سے بھی کلی طور پر محروم ٹھہرایا گیا ہے۔\n4: اس حدیث سے معاشرتی زندگی اور صلہ رحمی کی اہمیت اور ضرورت واضح ہوتی ہے کہ انسان کو اپنے اقارب سے ربط قائم رکھنا اوراسے مضبوط بنانا ضروری ہے،کیو نکہ اگر اللہ نہ کرے کبھی کوئی قصور ہو جائے تو دیت وغیرہ کی ادائیگی میں ان سے تعاون لے دے سکے۔ بالخصوص عورت کی دیت اس کے عصبات کے ذمے آتی ہے نہ کہ شوہر کے ذمے۔"}],[4565,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"شبہ عمد کی دیت عمد کی دیت کی طرح سخت ہے، البتہ اس کے قاتل کو قتل نہیں کیا جائے گا\"۔ خلیل کی محمد بن راشد سے روایت میں یہ اضافہ ہے \"یہ (قتل شبہ عمد) لوگوں کے درمیان ایک شیطانی فساد ہے کہ بلا کسی کینے اور بغیر ہتھیار اٹھائے خون ہو جاتا ہے اور قاتل کا پتا نہیں چلتا\"۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” قتل شبہ عمد کی دیت مغلظ (ثقیل اور شدید) ہوتی ہے جیسے کہ قتل عمد کی، مگر اس کا مرتکب قتل نہیں کیا جا سکتا۔ “ (امام ابوداؤد رضی اللہ عنہ نے) کہا کہ خلیل نے ابن راشد سے مزید کہا: ” وہ (شبہ عمد) یوں ہے کہ شیطان لوگوں میں فساد پیدا کر دے اور بلوے میں کوئی خون ہو جائے (قاتل کو کسی نے دیکھا نہ ہو) اور لڑائی کرنے والوں میں کوئی گہری عداوت بھی نہ ہو اور نہ انہوں نے اسلحہ اٹھایا ہو۔“"}],[4566,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" «مواضح» ۱؎ میں دیت پانچ اونٹ ہے\"۔\n§وضاحت\n۱؎ : «مواضح» ایسے زخم کو کہتے ہیں جس سے ہڈی دکھائی دینے لگے۔","حسن صحیح",{"u2":"جناب عمرو بن شعیب سے مروی ہے کہ ان کے والد نے انہیں (ان کے دادا) سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ایسے زخم جو ہڈی کھول دیں ان میں پانچ پانچ اونٹ ہیں۔“"}],[4567,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایسی آنکھ میں جو اپنی جگہ باقی رہے لیکن بینائی جاتی رہے، تہائی دیت کا فیصلہ فرمایا۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے، وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے آنکھ کی چوٹ میں فیصلہ فرمایا کہ آنکھ اگر اپنی جگہ قائم رہے (اور بینائی جاتی رہے) تو اس میں تہائی دیت ہے۔"}],[4568,"مغیرہ بن شعبہ رضی اللہ عنہ سے روایت ہے کہ قبیلہ ہذیل کے ایک شخص کی دو بیویاں تھیں ان میں سے ایک نے دوسری کو لکڑی سے مار کر اسے اور اس کے پیٹ کے بچے کو قتل کر دیا، وہ لوگ جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو ان میں سے ایک شخص نے کہا: ہم اس کی دیت کیوں کر ادا کریں جو نہ رویا، نہ کھایا، نہ پیا، اور نہ ہی چلایا، (اس نے یہ بات مقفّٰی عبارت میں کہی) آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم دیہاتیوں کی طرح مقفّی و مسجّع عبارت بولتے ہو؟\" تو آپ صلی اللہ علیہ وسلم نے اس میں ایک غرہ(لونڈی یا غلام) کی دیت کا فیصلہ کیا، اور اسے عورت کے عاقلہ (وارثین) کے ذمہ ٹھہرایا۔","صحیح",{"u2":"سیدنا مغیرہ بن شعبہ رضی اللہ عنہ سے روایت ہے کہ و عورتیں بنو ہذیل کے ایک آدمی کی زوجیت میں تھیں۔ ان میں سے ایک نے دوسری کو خیمے کا بانس دے مارا اور اسے اور اس کے پیٹ کے بچے کو قتل کر دیا۔ وہ لوگ اپنا جھگڑا نبی کریم صلی اللہ علیہ وسلم کے پاس لے آئے۔ تو دونوں اطراف کے لوگوں میں سے کسی ایک نے کہا: کس طرح دیت دیں ہم اس کی جو نہ رویا نہ کھایا، نہ پیا نہ چلایا۔ رسول اللہ صلی اللہ علیہ وسلم نے (اس کے انداز گفتگو پر) فرمایا &rdquo; کیا دیہاتیوں کی سی سجع ہے۔ &ldquo; الغرض آپ صلی اللہ علیہ وسلم نے فرمایا (اس بچے دی دیت) ایک غلام ہے اور اسے قاتلہ کے وارثوں کے ذمے لگایا کہ وہ ادا کریں۔","f2":"1: عورت اگر جرم کرے تو اس دیت اس وارثوں کے ذمے ہے۔ 2: اگر پیٹ کا بچہ مار دیا گیا تو اس دیت ایک غلام ہے۔ 3: جاہلوں کے اندر میں تکلف سے باتیں کرنا معیوب ہے دوسری روایت میں اسے جہلا ء اور کاہنوں کی سجع سے تشبیہ دی گئی ہے۔"}],[4569,"اس سند سے منصور سے اسی طرح کی حدیث مروی ہے، اور اس میں اتنا اضافہ ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مقتول عورت کی دیت قاتل عورت کے عصبات پر ٹھہرائی، اور پیٹ کے بچے کے لیے ایک غرہ (غلام یا لونڈی) ٹھہرایا۔ ابوداؤد کہتے ہیں: اسے اسی طرح حکم نے مجاہد سے مجاہد نے مغیرہ سے روایت کیا ہے۔","صحیح",{"u2":"منصور نے اپنی سند سے مذکورہ بالا کے ہم معنی روایت کیا۔ اور مزید کہا کہ نبی کریم صلی اللہ علیہ وسلم نے مقتولہ عورت کی دیت قاتلہ کے وارثوں کے ذمے ڈالی اور اس کے پیٹ کے بچے کے بدلے میں ایک غلام لازم کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ حکم نے بواسطہ مجاہد، سیدنا مغیرہ رضی اللہ عنہ سے اسی طرح روایت کیا ہے۔"}],[4570,"مسور بن مخرمہ رضی اللہ عنہما سے روایت ہے کہ عمر رضی اللہ عنہ نے عورت کے املاص کے بارے میں لوگوں سے مشورہ لیا تو مغیرہ بن شعبہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے اس میں ایک غلام یا لونڈی دینے کا فیصلہ کیا ہے، تو عمر نے کہا: میرے پاس اپنے ساتھ اس شخص کو لاؤ جو اس کی گواہی دے، تو وہ محمد بن مسلمہ رضی اللہ عنہ کو لے کر ان کے پاس آئے۔ ہارون کی روایت میں اتنا اضافہ ہے تو انہوں نے اس کی گواہی دی یعنی اس بات کی کہ کوئی آدمی عورت کے پیٹ میں مارے جو اسقاط حمل کا سبب بن جائے۔ ابوداؤد کہتے ہیں: مجھے ابو عبید سے معلوم ہوا اسقاط حمل کو املاص اس لیے کہتے ہیں کہ اس کے معنی ازلاق یعنی پھسلانے کے ہیں گویا عورت ولادت سے قبل ہی مار کی وجہ سے حمل کو پھسلا دیتی ہے اسی طرح ہاتھ یا کسی اور چیز سے جو چیز پھسل کر گر جائے تو اس کی تعبیر «مَلِصَ» سے کی جاتی ہے یعنی وہ پھسل گیا۔","صحیح",{"u2":"سیدنا مسور بن مخرمہ رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے لوگوں سے مشورہ کیا کہ اگر کسی عورت کے پیٹ کا بچہ ساقط کر دیا گیا ہو (تو اس میں کیا دیت ہو؟)۔ سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نے کہا: میں گواہی دیتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس میں ایک غلام یا لونڈی دینے کا فیصلہ فرمایا تھا۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ کوئی گواہ لایئے جو آپ کی تائید میں گواہی دے۔ چنانچہ وہ محمد بن مسلمہ رضی اللہ عنہ کو لے آئے۔ ہارون نے مزید کہا: چنانچہ انہوں نے گواہی دی یعنی اگر کوئی پیٹ والی عورت کو صدمہ پہنچائے (تو اس کی دیت یہی ہے)۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابوعبید سے مروی ہے کہ اسقاط کو &laquo;إملاص&raquo; اس لیے کہتے ہیں کہ عورت بچے کو قبل از وقت پھسلا دیتی ہے۔ اور ہر وہ چیز جو ہاتھ وغیرہ سے پھسل جائے اسے &laquo;ملص&raquo; کہتے ہیں۔"}],[4571,"عمر رضی اللہ عنہ سے بھی اسی مفہوم کی حدیث مروی ہے ابوداؤد کہتے ہیں: اسے حماد بن زید اور حماد بن سلمہ نے ہشام بن عروہ سے، عروہ نے اپنے باپ زبیر سے روایت کیا ہے کہ عمر نے کہا۔","صحیح",{"u2":"سیدنا مغیرہ رضی اللہ عنہ نے سیدنا عمر رضی اللہ عنہ سے مذکورہ بالا حدیث کے ہم معنی روایت کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو حماد بن زید اور حماد بن سلمہ نے ہشام بن عروہ سے اس نے اپنے والد سے روایت کیا کہ بیشک عمر رضی اللہ عنہ نے کہا۔"}],[4572,"عمر رضی اللہ عنہ سے روایت ہے کہ انہوں نے اس بارے میں نبی اکرم صلی اللہ علیہ وسلم کے فیصلے کے متعلق پوچھا تو حمل بن مالک بن نابغہ کھڑے ہوئے، اور بولے: میں دونوں عورتوں کے بیچ میں تھا، ان میں سے ایک نے دوسری کو لکڑی سے مارا تو وہ مر گئی اور اس کا جنین بھی، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے جنین کے سلسلے میں ایک غلام یا لونڈی کی دیت کا، اور قاتلہ کو قتل کر دیئے جانے کا حکم دیا۔ ابوداؤد کہتے ہیں: نضر بن شمیل نے کہا: «مسطح» چوپ یعنی (روٹی پکانے کی لکڑی) ہے۔ ابوداؤد کہتے ہیں: ابو عبید نے کہا:«مسطح» خیمہ کی لکڑیوں میں سے ایک لکڑی ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ سیدنا عمر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کے اس فیصلے کے بارے میں دریافت کیا (جو پیٹ کے بچے کے بارے میں ہوا تھا) تو حمل بن مالک بن نابغہ اٹھا اور کہا کہ میں دو عورتوں کے درمیان میں تھا (میری دو بیویاں تھیں) تو ایک نے دوسری کو خیمے کا بانس دے مارا اور اس کو اور اس کے پیٹ کے بچے کو مار ڈالا۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اس کے بچے کے بارے میں ایک غلام ادا کرنے کا فیصلہ کیا اور اس عورت کو (جو قاتلہ تھی قصاص میں) قتل کرنے کا فیصلہ کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ نضر بن شمیل نے کہا کہ &laquo;مسطح&raquo; سے مراد وہ لکڑی ہے جس کے ذریعے سے تنور سے روٹی نکالی جاتی ہے۔ امام ابوداؤد رضی اللہ عنہ بیان کرتے ہیں: جبکہ ابوعبید نے کہا کہ &laquo;مسطح&raquo; خیمے کی لکڑی کو کہتے ہیں۔","f2":"بھاری لکڑی سے مارقتل عمد میں شمارہو سکتا ہے۔"}],[4573,"طاؤس کہتے ہیں کہ عمر رضی اللہ عنہ منبر پر کھڑے ہوئے، آگے راوی نے اسی مفہوم کی حدیث ذکر کی البتہ اس کا ذکر نہیں کیا کہ وہ قتل کی جائے، اور انہوں نے «بغرة عبد أو أمة» کا اضافہ کیا ہے، راوی کہتے ہیں: اس پر عمر رضی اللہ عنہ نے کہا: اللہ اکبر! اگر ہم یہ حکم نہ سنے ہوتے تو اس کے خلاف فیصلہ دیتے۔","ضعیف الإسناد",{"u2":"جناب طاؤس کہتے ہیں کہ سیدنا عمر رضی اللہ عنہ منبر پر کھڑے ہوئے اور مذکورہ بالا حدیث کے ہم معنی بیان کیا مگر اس میں ” اس عورت (قاتلہ) کے قتل کیے جانے کا ذکر نہیں کیا۔“ البتہ (جنین کے بدلے میں) ایک غلام یا لونڈی دیے جانے کا بیان کیا۔ طاؤس نے کہا: اس پر سیدنا عمر رضی اللہ عنہ نے کہا: «الله اكبر»، اگر میں یہ نہ سنتا تو اس کے علاوہ کوئی اور فیصلہ کر بیٹھتا۔"}],[4574,"عبداللہ بن عباس رضی اللہ عنہما سے حمل بن مالک کے قصے میں روایت ہے، وہ کہتے ہیں تو اس نے بچہ کو جسے بال اگے ہوئے تھے ساقط کر دیا، وہ مرا ہوا تھا اور عورت بھی مر گئی، تو آپ نے وارثوں پر دیت کا فیصلہ کیا، اس پر اس کے چچا نے کہا: اللہ کے نبی! اس نے تو ایک ایسا بچہ ساقط کیا ہے جس کے بال اگ آئے تھے، تو قاتل عورت کے باپ نے کہا: یہ جھوٹا ہے، اللہ کی قسم! نہ تو وہ چیخا، نہ پیا، اور نہ کھایا، اس جیسے کا خون تو معاف (رائیگاں) قرار دے دیا جاتا ہے، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کیا جاہلیت جیسی مسجع عبارت بولتے ہو جیسے کاہن بولتے ہیں، بچے کی دیت ایک غلام یا لونڈی کی دینی ہو گی\"۔ ابن عباس کہتے ہیں: ان میں سے ایک کا نام ملیکہ اور دوسری کا ام غطیف تھا۔","ضعیف",{"u2":"جناب عکرمہ نے سیدنا ابن عباس رضی اللہ عنہ سے حمل بن مالک کے واقعہ میں بیان کیا کہ اس نے عورت کا بچہ ساقط کر دیا جو مردہ تھا اور اس کے بال اگ چکے تھے اور عورت بھی مر گئی۔ تو آپ صلی اللہ علیہ وسلم نے اس کی دیت اس قاتلہ کے وارثوں پر ڈال دی۔ مقتولہ کے چچا نے کہا: اس کا بچہ ساقط ہوا ہے، اے اللہ کے نبی، جس کے بال اگ چکے تھے۔ تو قاتلہ کے والد نے کہا: یہ جھوٹا ہے، اللہ کی قسم! بچہ نہ چیخا نہ چلایا، نہ پیا نہ کھایا، ایسا خون تو باطل ہوتا ہے (اس میں قصاص ہوتا ہے نہ دیت)۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” یہ کیا جاہلوں اور کاہنوں کی سی سجع ہے؟ بچے کی دیت میں ایک غلام یا لونڈی ادا کرو۔ “ سیدنا ابن عباس رضی اللہ عنہ کہتے ہیں ان عورتوں میں سے ایک کا نام ملیکہ تھا اور دوسری کا ام غطیف۔"}],[4575,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ قبیلہ ہذیل کی دو عورتوں میں سے ایک نے دوسری کو قتل کر دیا، ان میں سے ہر ایک کے شوہر بھی تھا، اور اولاد بھی، تو رسول اللہ صلی اللہ علیہ وسلم نے مقتولہ کی دیت قاتلہ کے عصبات پر ٹھہرائی اور اس کے شوہر اور اولاد سے کوئی مواخذہ نہیں کیا، مقتولہ کے عصبات نے کہا: کیا اس کی میراث ہمیں ملے گی؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، اس کی میراث تو اس کے شوہر اور اولاد کی ہو گی\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ قبیلہ ہذیل کی دو عورتوں میں سے ایک نے دوسری کو قتل کر دیا اور ان دونوں میں سے ہر ایک کا شوہر بھی تھا اور بچہ بھی۔ تو رسول اللہ صلی اللہ علیہ وسلم نے مقتولہ کی دیت قاتلہ کے عاقلہ پر ڈالی۔ اس قاتلہ کے شوہر اور بیٹے کو اس دیت کی ادائیگی سے بری رکھا۔ تو مقتولہ کے عاقلہ کہنے لگے کہ اس کی میراث ہمارا حق ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” نہیں اس کی وراثت اس کے شوہر اور بیٹے کا حق ہے۔ “","f2":"اس روایت کو بعض محقیقین نے صحیح قراردیا ہے (عاقلہ)سے مراد وہ لوگ ہیں جو وراثت کے متعینہ حصے دے دیے جانے کے بعد باقی مال سمیٹ لیتے ہیں جیسے کی باپ،بیٹا،بھائی اور چچا وغیرہ مگر اس حدیث میں بیٹے کو عاقلہ سے خارج رکھا گیا ہے۔"}],[4576,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ قبیلہ ہذیل کی دو عورتوں میں جھگڑا ہوا، ان میں سے ایک نے دوسری کو پتھر پھینک کر مارا تو اسے قتل ہی کر ڈالا، تو لوگ مقدمہ لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچے تو آپ نے فیصلہ کیا: \"جنین کی دیت ایک غلام یا لونڈی ہے، اور عورت کی دیت کا فیصلہ کیا کہ یہ اس کے عصبہ پر ہو گی\" اور اس دیت کا وارث مقتولہ کی اولاد کو اور ان کے ساتھ کے لوگوں کو قرار دیا۔ حمل بن مالک بن نابغہ ہذلی نے کہا: اللہ کے رسول! میں ایسی جان کی دیت کیوں ادا کروں جس نے نہ پیا، نہ کھایا، نہ بولا، اور نہ چیخا، ایسے کا خون تو لغو قرار دے دیا جاتا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کاہنوں کا بھائی معلوم ہوتا ہے\" آپ نے یہ بات اس کی اس «سجع» تعبیر کی وجہ سے کہی جو اس نے کی تھی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ قبیلہ ہذیل کی دو عورتیں لڑ پڑیں تو ایک نے دوسری کو پتھر دے مارا اور اسے قتل کر دیا۔ چنانچہ وہ اپنا معاملہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لے آئے اور رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ جنین کی دیت میں ایک غلام یا لونڈی ادا کی جائے اور مقتولہ کی وراثت اس کے بیٹے اور اس کے ساتھ دوسرے وارثوں کو دلوائی۔ تو حمل بن مالک بن نابغہ ہذلی نے کہا: اے اللہ کے رسول! میں بھلا اس کا جرمانہ کیونکر بھروں جس نے نہ پیا نہ کھایا، نہ بولا نہ چلایا، ایسا خون تو لغو ہوتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا &rdquo; یہ تو کاہنوں کا بھائی لگتا ہے۔ &ldquo; آپ صلی اللہ علیہ وسلم نے یہ اس کی مسجع گفتگو کی وجہ سے فرمایا۔"}],[4577,"ابوہریرہ رضی اللہ عنہ سے اس قصے میں روایت ہے، وہ کہتے ہیں پھر وہ عورت، جس کے لیے رسول اللہ صلی اللہ علیہ وسلم نے لونڈی یا غلام کا فیصلہ کیا تھا، مر گئی، تو آپ نے فیصلہ فرمایا کہ اس کی میراث اس کے بیٹوں کی ہے، اور دیت قاتلہ کے عصبہ پر ہو گی۔","صحیح",{"u2":"جناب ابن مسیب نے سیدنا ابوہریرہ رضی اللہ عنہ سے اس قصے میں روایت کیا کہ پھر وہ عورت جس کو آپ نے غلام یا لونڈی دلوائی فوت ہو گئی تو رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ کر دیا کہ اس کی وراثت اس کے بیٹے کو ملے اور (قاتلہ کی طرف سے) دیت اس کے عصبہ (عاقلہ) پر ڈالی۔"}],[4578,"بریدہ رضی اللہ عنہ سے روایت ہے کہ ایک عورت نے دوسری عورت کو پتھر مارا تو اس کا حمل گر گیا، یہ مقدمہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لے جایا گیا تو آپ نے اس بچہ کی دیت پانچ سو بکریاں مقرر فرمائی، اور لوگوں کو پتھر مارنے سے اسی دن سے منع فرما دیا۔ ابوداؤد کہتے ہیں: روایت اسی طرح ہے \"پانچ سو بکریوں کی\" لیکن صحیح \"سو بکریاں\" ہے، اسی طرح عباس نے کہا ہے حالانکہ یہ وہم ہے۔","ضعیف",{"u2":"سیدنا عبداللہ بن بریدہ اپنے والد سے روایت کرتے ہیں کہ ایک عورت نے دوسری کو پتھر دے مارا، اس سے اس کا بچہ ساقط ہو گیا۔ پس یہ مقدمہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے پیش کیا گیا تو آپ صلی اللہ علیہ وسلم نے اس کے بچے کے سلسلے میں پانچ سو بکریاں ذمے لگائیں اور اس دن سے پتھر مارنے سے منع فرمایا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ حدیث میں روایت تو پانچ سو بکریاں ہی ہیں، مگر صحیح یہ ہے کہ سو بکریاں تھیں۔ امام ابوداؤد رضی اللہ عنہ بیان کرتے ہیں کہ یہ عباس (عباس بن عبدالعظیم) کا وہم ہے۔"}],[4579,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے پیٹ کے بچے میں ایک غلام یا ایک لونڈی یا ایک گھوڑے یا ایک خچر کی دیت کا فیصلہ کیا۔ ابوداؤد کہتے ہیں: اس حدیث کو حماد بن سلمہ اور خالد بن عبداللہ نے محمد بن عمرو سے روایت کیا ہے البتہ ان دونوں نے «أو فرس أو بغل» کا ذکر نہیں کیا ہے۔","شاذ",{"u2":"سیدنا عبداللہ بن بریدہ اپنے والد سے روایت کرتے ہیں کہ ایک عورت نے دوسری کو پتھر دے مارا، اس سے اس کا بچہ ساقط ہو گیا۔ پس یہ مقدمہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے پیش کیا گیا تو آپ صلی اللہ علیہ وسلم نے اس کے بچے کے سلسلے میں پانچ سو بکریاں ذمے لگائیں اور اس دن سے پتھر مارنے سے منع فرمایا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ حدیث میں روایت تو پانچ سو بکریاں ہی ہیں، مگر صحیح یہ ہے کہ سو بکریاں تھیں۔ امام ابوداؤد رضی اللہ عنہ بیان کرتے ہیں کہ یہ عباس (عباس بن عبدالعظیم) کا وہم ہے۔"}],[4580,"شعبی کہتے ہیں کہ غرہ (غلام یا لونڈی) کی قیمت پانچ سو درہم ہے۔ ابوداؤد کہتے ہیں: ربیعہ نے کہا: غرہ (غلام یا لونڈی) پچاس دینار کا ہوتا ہے۔","ضعیف الإسناد",{"u2":"جناب شعبی سے مروی ہے کہ لونڈی غلام کی قیمت پانچ سو درہم ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں ربیعہ نے کہا کہ لونڈی غلام کی قیمت پچاس دینار ہے۔"}],[4581,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مکاتب غلام جسے قتل کر دیا جائے کی دیت میں فیصلہ فرمایا کہ قتل کے وقت جس قدر وہ بدل کتابت ادا کر چکا ہے اتنے حصہ کی دیت آزاد کی دیت کے مثل ہو گی اور جس قدر ادائیگی باقی ہے اتنے حصے کی دیت غلام کی دیت کے مثل ہو گی۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مکاتب، جو قتل کر دیا جائے، کی دیت کے سلسلے میں فیصلہ فرمایا کہ وہ جس قدر حصہ اپنی کتابت کا ادا کر چکا ہو اس نسبت سے آزاد آدمی کی دیت دی جائے اور جس قدر باقی ہو اس میں غلام کی دیت دی جائے۔","f2":"ایسا غلام جس نے اپنے مالک سے معاہدہ کیا ہو کہ میں اس قدر رقم دے کر آزاد ہو جاوں گا تو وہ اس مدت میں مکاتب کہلاتا ہے (مکاتب تاکے زبر کے ساتھ)"}],[4582,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب مکاتب کوئی حد کا کام کرے یا ترکے کا وارث ہو تو جس قدر آزاد ہوا ہے وہ اسی قدر وارث ہو گا\"۔ ابوداؤد کہتے ہیں: اسے وہیب نے ایوب سے، ایوب نے عکرمہ سے، عکرمہ نے علی رضی اللہ عنہ سے اور علی نے نبی اکرم صلی اللہ علیہ وسلم سے مرفوعاً روایت کیا ہے۔ اور حماد بن زید اور اسماعیل نے ایوب سے، ایوب نے عکرمہ سے اور عکرمہ نے نبی اکرم صلی اللہ علیہ وسلم سے مرسلاً روایت کیا ہے۔ اور اسماعیل بن علیہ نے اسے عکرمہ کا قول قرار دیا ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول صلی اللہ علیہ وسلم نے فرمایا ” مکاتب پر جب کوئی حد لازم آ رہی ہو یا کسی کا وارث بن رہا ہو تو جس نسبت سے آزاد ہو چکا ہو اسی حساب سے حد لاگو ہو گی یا وراثت کا حصہ پائے گا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں اس روایت کو وہیب نے بسند ایوب، عکرمہ سے انہوں نے سیدنا علی رضی اللہ عنہ سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے۔ اور حماد بن زید اور اسماعیل نے بواسطہ ایوب، عکرمہ سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل روایت کیا ہے جبکہ اسماعیل بن علیہ نے اسے عکرمہ کا قول بنایا ہے۔","f2":"اسلام نے جس انداز سے غلاموں کے حقوق کا تحفظ کیا ہے کسی اور ملت میں نہیں ہے۔ غلام اگر آدھا آزاد ہو چکا ہو غلام ہو تو آدھی دیت آزاد کی اور باقی غلام کی ادا کی جائے گی۔ اسی طرح امور باقی امور میں بھی ہے۔"}],[4583,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ذمی معاہد کی دیت آزاد کی دیت کی آدھی ہے ۱؎\"۔ ابوداؤد کہتے ہیں: اسے اسامہ بن زید لیثی اور عبدالرحمٰن بن حارث نے بھی عمرو بن شعیب سے اسی کی مثل روایت کیا ہے۔\n§وضاحت\n۱؎ : یعنی جو کافر دارالاسلام میں معاہدہ کی رو سے رہتا ہے اس کی دیت مسلمان کی دیت کی آدھی ہے۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے داد سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” عہد والے (ذمی) کی دیت آزاد سے آدھی ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو اسامہ بن زید لیثی اور عبدالرحمٰن بن حارث نے عمرو بن شعیب سے اسی کی مثل روایت کیا ہے۔","f2":"ایسا غیرمسلم جو مملکت اسلامی کی رعیت میں شامل ہو ذمی کہلاتا ہے۔"}],[4584,"یعلی رضی اللہ عنہ کہتے ہیں کہ میرے ایک مزدور نے ایک شخص سے جھگڑا کیا اور اس کے ہاتھ کو منہ میں کر کے دانت سے دبایا، اس نے اپنا ہاتھ کھینچا تو اس کا دانت باہر نکل آیا، پھر وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، تو آپ نے اسے لغو کر دیا، اور فرمایا: \"کیا چاہتے ہو کہ وہ اپنا ہاتھ تمہارے منہ میں دیدے، اور تم اسے سانڈ کی طرح چبا ڈالو\" ابن ابی ملیکہ نے اپنے دادا سے نقل کیا ہے کہ ابوبکر رضی اللہ عنہ نے اسے لغو قرار دیا اور کہا: (اللہ کرے) اس کا دانت نہ رہے۔","صحیح"],[4585,"اس سند سے بھی یعلی بن امیہ سے یہی حدیث مروی ہے البتہ اتنا اضافہ ہے \"پھر آپ نے (یعنی نبی اکرم صلی اللہ علیہ وسلم نے) دانت کاٹنے والے سے فرمایا: \"اگر تم چاہو تو یہ ہو سکتا ہے کہ تم بھی اپنا ہاتھ اس کے منہ میں دے دو وہ اسے کاٹے پھر تم اسے اس کے منہ سے کھینچ لو\" اور اس کے دانتوں کی دیت باطل قرار دے دی۔","صحیح الإسناد",{"u2":"سیدنا یعلیٰ بن امیہ نے یہ روایت بیان کی اور مزید کہا کہ پھر نبی کریم صلی اللہ علیہ وسلم نے دانت سے کاٹنے والے سے کہا ” اگر چاہو تو اپنا ہاتھ اس کے منہ میں دے دو، وہ بھی اسی طرح کاٹے جیسے کہ تم نے کاٹا تھا اور تم بھی اپنا ہاتھ کھینچ لینا۔ “ الغرض آپ صلی اللہ علیہ وسلم نے اس کے دانتوں کی دیت ضائع قرار دی۔"}],[4586,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو طب نہ جانتا ہو اور علاج کرے تو وہ(مریض کا) ضامن ہو گا\"۔ ابوداؤد کہتے ہیں: اسے ولید کے علاوہ کسی اور نے روایت نہیں کیا، ہمیں نہیں معلوم یہ صحیح ہے یا نہیں۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو ایسے ہی طبیب بن کر علاج کرے اور طبابت اور علاج معالجے میں مشہور نہ ہو تو وہ ذمہ دار ہے۔ “ نصر بن عاصم نے اپنی سند میں کہا: «حدثني ابن جريج»۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: یہ صرف ولید بن مسلم کی روایت ہے، ہمیں معلوم نہیں کہ صحیح ہے یا نہیں۔","f2":"بعض محققین کے نزدیک مذکورہ روایت حسن ہے ان کے نزدیک عطائی قسم کے غیر معروف طبیب اورمعالج اگر اپنے علاج سے کسی نقصان کردیں تو وہ ضامن اور ذمہ دار ہیں اور لوگوں کو بھی ایسے عطائیوں سے محتاط رہنا چاہیے۔"}],[4587,"عبدالعزیزبن عمر بن عبدالعزیز کہتے ہیں میرے والد کے پاس آنے والوں میں سے ایک شخص نے مجھ سے بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی قوم میں طبیب بن بیٹھے، حالانکہ اس سے پہلے اس کی طب دانی معروف نہ ہو اور مریض کا مرض بگڑ جائے اور اس کو نقصان لاحق ہو جائے تو وہ اس کا ضامن ہو گا\"۔ عبدالعزیز کہتے ہیں: «اعنت نعت» سے نہیں (بلکہ «عنت» سے ہے جس کے معنی) رگ کاٹنے، زخم چیرنے یا داغنے کے ہیں۔","حسن",{"u2":"جناب عبدالعزیز بن عمر بن عبدالعزیز سے روایت ہے کہ ایک وفد کے لوگ جو میرے والد کے پاس آئے تھے ان میں سے ایک نے کہا کہ رسول صلی اللہ علیہ وسلم نے فرمایا ” جو معالج کسی قوم میں طبیب بنا پھرتا ہو، جب کہ اس سے پہلے وہ علم طب میں معروف نہ ہو اور کسی کا نقصان کر دے تو وہ ذمہ دار ہے۔ “ عبدالعزیز نے کہا: یہ ضمانت دوا بتانے میں نہیں بلکہ یہ رگ کاٹنے، چیرا دینے یا داغ دینے کی صورت میں ہے۔","f2":"لوگ بالعموم سنےسنائے نسخے بیا ن کرتے ہیں،اس صورت میں بتانے والے کا قصورنہیں سمجھا جاتا،بلکہ ایسی دوا استعمال کرنے والے کو خوددواناہوناچاہیے ہاں اگر کوئی اناڑی فصدکھولے یاداغ وغیرہ دے اور نقصان ہوجائےتو ذمہ دارہو گا۔یہی وجہ ہے کہ نوآموزڈاکٹروں اور معالجین کے لئے پرانے ماہر طبیبوں کی زیر نگرانی طویل تربیت لازمی سمجھی جاتی ہے۔"}],[4588,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن خطبہ دیا آپ نے فرمایا: \"سنو! جاہلیت کے خون یا مال کی جتنی فضیلتیں بھی تھیں جن کا ذکر کیا جاتا تھا یا جن کے دعوے کئے جاتے تھے وہ سب میرے قدموں تلے ہیں، سوائے حاجیوں کو پانی پلانے اور بیت اللہ کی دیکھ ریکھ کے\" پھر فرمایا: \"سنو! قتل خطا جو کوڑے یا لاٹھی سے ہوا ہو شبہ عمد ہے، اس کی دیت سو اونٹ ہے، جن میں چالیس اونٹنیاں ایسی ہوں گی جن کے پیٹ میں بچے ہوں گے\"۔\n§وضاحت\n۱؎ : یہ اس سے پہلے حدیث نمبر (۴۵۴۷) کے تحت بھی گزر چکا ہے۔","حسن",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے، بقول مسدد فتح والے دن خطبہ ارشاد فرمایا پھر سلیمان بن حرب اور مسدد دونوں اپنے بیان میں متفق ہیں۔ آپ نے فرمایا &rdquo; خبردار! تحقیق جاہلیت کے دور کی فخر کی ہر بات خون سے متعلق ہو یا مال سے، جس کا ذکر کیا جاتا ہو یا دعویٰ کیا جاتا ہو، وہ میرے قدموں تلے (روندی جا رہی) ہے سوائے حاجیوں کو پانی پلانے اور بیت اللہ کی خدمت کے عمل کے۔ &ldquo; (وہ حسب سابق بحال ہے) پھر فرمایا &rdquo; خبردار! قتل خطا جو عمد کے مشابہ ہو سانٹے یا لاٹھی وغیرہ سے جیسے بھی ہو، اس کی دیت سو اونٹ ہے، ان میں چالیس اونٹنیاں ایسی ہوں جن کے پیٹوں میں بچے ہوں۔ &ldquo;"}],[4589,"اس سند سے بھی خالد سے اسی مفہوم کی حدیث مروی ہے۔","",{"u2":"وہیب نے خالد سے اسی سند سے مذکورہ بالا حدیث کے ہم معنی روایت کیا۔"}],[4590,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ فقیر لوگوں کے ایک غلام نے کچھ مالدار لوگوں کے ایک غلام کا کان کاٹ لیا، تو جس غلام نے کان کاٹا تھا اس کے مالکان نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: اللہ کے رسول! ہم فقیر لوگ ہیں، تو آپ نے ان پر کوئی دیت نہیں ٹھہرائی۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ فقیر لوگوں کا ایک غلام تھا، اس نے امیر لوگوں کے ایک غلام کا کان کاٹ دیا یہ (امیر) لوگ نبی کریم صلی اللہ علیہ وسلم کے پاس مقدمہ لے آئے تو دوسروں نے جواب دیا کہ اے اللہ کے رسول! ہم لوگ فقیر ہیں، تو آپ صلی اللہ علیہ وسلم نے ان پر کوئی چیز نہ ڈالی۔","f2":"بعض محققین کے نزدیک یہ روایت صحیح ہے۔\n2:اس حدیث غلام کا ایک ترجمہ معروف معنی میں ہے کہ وہ عبد مملوک تھے،چونکہ یہ معاملہ مملوکوں کے مابین تھااورقصورکے مالک فقیر بھی تھےاس لئےان پر کچھ نہ ڈالا گیا اور دوسراترجمعہ نو عمر لڑکے بھی کیا گیا ہے یعنی وہ آزادتھےمگران کے لڑکپن،خطااورقصورکے ولی فقیرہونے کی وجہ سے ان پر کچھ نہ ڈالا۔"}],[4591,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اندھا دھند مارا جائے یا کسی دنگے فساد میں جو ان میں چھڑ گیا ہو، یا کسی پتھر یا کوڑے سے مارا جائے تو اس کی دیت قتل خطا کی دیت ہو گی، اور جو جان بوجھ کر عمداً کسی کو قتل کرے تو وہ موجب قصاص ہے، اب اگر کوئی ان دونوں کے بیچ میں پڑ کر (قاتل کو بچانا چاہے) تو اس پر اللہ کی، فرشتوں کی اور تمام لوگوں کی لعنت ہے\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص کسی بلوے میں مارا جائے (اور قاتل دیکھا نہ گیا ہو) کہ ان کی آپس میں سنگباری ہوئی ہو یا سانٹے ڈنڈے بازی تو اس کی دیت قتل خطا والی ہو گی۔ اور جو عمداً جان بوجھ کر قتل کیا گیا ہو تو اس میں قاتل کی جان سے قصاص ہے اور جو کوئی اس (قصاص لینے) میں آڑے آئے تو اس پر اللہ کی، فرشتوں کی اور تمام لوگوں کی لعنت ہو۔","f2":"گزشتہ حدیث 4539 ملاحظہ ہو"}],[4592,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(جانور کا) پاؤں باطل و رائیگاں ہے اس کی کوئی دیت نہیں ہو گی\"۔ ابوداؤد کہتے ہیں: جانور پیر سے مار دے جب کہ وہ اس پہ سوار ہو تو اس کی کوئی دیت نہیں۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” (جانور کا) لات مار دینا ضائع ہے۔ اور معدنی کان (کا نقصان) ضائع ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ جانور کا مالک اس پر سوار ہو اور وہ لات مار دے (تو ضائع ہے)۔"}],[4593,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جانور کسی کو زخمی کر دے تو اس میں ہرجانہ نہیں ہے، کان میں ہلاک ہونے والے کا ہرجانہ نہیں ہے اور کنواں میں ہلاک ہو جانے والے کا ہرجانہ نہیں ہے ۱؎ اور رکاز میں پانچواں حصہ دینا ہو گا\"۔ ابوداؤد کہتے ہیں: جانور سے مراد وہ جانور ہے جو چھڑا کر بھاگ گیا ہو اور اس کے ساتھ کوئی نہ ہو اور دن ہو، رات نہ ہو۔\n§وضاحت\n۱؎ : یعنی جانور کسی کو زخمی کر دے یا کان اور کنویں میں گر کر کوئی ہلاک ہو جائے تو ان کے مالکوں پر اس کی دیت نہ ہو گی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے تھے کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جانور کا زخمی کر دینا، معدنی کان میں حادثہ ہو جانا یا کنویں میں گر پڑنا سب ضائع ہیں اور اگر کسی کو کوئی دفینہ ملے تو اس میں خمس ہے۔ “ (پانچواں حصہ ادا کرنا شرعی حق ہے)۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں جانور جب بھاگ گیا ہو اور اس کے ساتھ کوئی نہ ہو اور یہ حادثہ دن کے وقت ہوا ہو رات میں نہ ہوا ہو۔","f2":"1:جانور بے شعور اور ناسمجھ مخلوق ہےاس کےکاٹ کھانے یا لات ماردینے میں اس مالک کا قصور نہیں،الا جب وہ اس کے قریب ہواوراس کو ضبط رکھنے پر قادر ہو،یایقین ہو کہ لوگوں کو نقصان پہنچا سکتا ہے اور پھر بھی وہ اسے کھلا چھوڑ دے۔ امام ابو داود رحمہ اللہ کے قوم کا یہی مفہوم ہے۔\n2: مزدور کو جب معلوم ہو کہ اس نے معدنی کان میں کام کرنا ہے۔۔۔۔۔یا اسی طرح کسی اور جگہ پت چڑھنا ہے اور وہ اپنی رضا مندی سے کام کرے تو اتفاقی حادثہ کی وجہ سے مالک قصوروارنہیں ہو گا۔\n3:اپنی زمین میں کسی نے کنواں کھودا اور کوئی اس میں جا گرے تو مالک کا کوئی قصور نہیں سمجھا جائے گا،بخلاف اس کے کہ کسی عام گزرگاہ پر کھودے یا پھر اس پر باڑاوغیرہ نہ لگائے۔"}],[4594,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آگ باطل ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی کسی نے اپنی زمین پر آگ جلائی اور وہ وہاں سے اڑ کر کسی کے گھر یا سامان میں لگ گئی تو جلا نے والے پر کوئی تاوان نہ ہو گا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” آگ (سے ہونے والا نقصان) ضائع ہے۔ “","f2":"اگر کسی نے اپنی زمین یا گھر وغیرہ میں آگ جلائی اور پھر وہ پھیل گئی یا کوئی چنگاری اڑ کر دوسرے کا نقصان کر گئی تو آگ جلانے والا اس کا ذمہ دا ر نہ سمجھا جائے گا الا یہ کوئی واضح قصورہو مثلا اپنا کام کرکے اسے ویسے ہی چھوڑ دیا اور بھجا یا یا دبایا نہ ہو۔"}],[4595,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ انس بن نضر رضی اللہ عنہ کی بہن ربیع نے ایک عورت کا سامنے کا دانت توڑ دیا، تو وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، آپ نے اللہ کی کتاب کے مطابق قصاص کا فیصلہ کیا، تو انس بن نضر نے کہا، اس ذات کی قسم جس نے آپ کو حق کے ساتھ بھیجا ہے! اس کا دانت تو آج نہیں توڑا جائے گا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے انس! کتاب اللہ میں قصاص کا حکم ہے\" پھر وہ لوگ دیت پر راضی ہو گئے جسے انہوں نے لے لیا، اس پر اللہ کے نبی اکرم صلی اللہ علیہ وسلم کو تعجب ہوا اور آپ نے فرمایا: \"اللہ کے بعض بندے ایسے ہیں کہ اگر وہ اللہ کی قسم کھا لیں تو وہ ان کی قسم پوری کر دیتا ہے ۱؎\"۔ ابوداؤد کہتے ہیں: میں نے احمد بن حنبل کو کہتے سنا ان سے پوچھا گیا تھا کہ دانت کا قصاص کیسے لیا جائے؟ تو انہوں نے کہا: وہ ریتی سے رگڑا جائے۔\n§وضاحت\n۱؎ : انس بن نضر رضی اللہ عنہ نے غصے میں اللہ کے بھروسے پر قسم کھا لی تھی کہ میری بہن کا دانت نہیں توڑا جائے گا، چنانچہ اللہ نے ان کے لئے ایسا ہی سامان قانونی طور پر کر دیا۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ سیدنا انس بن نضر رضی اللہ عنہ کی بہن ربیع (را پر پیش، با پر زبر اور ی مشدد کے نیچے زیر) نے ایک عورت کا دانت توڑ دیا تو وہ لوگ نبی کریم صلی اللہ علیہ وسلم کے پاس آ گئے۔ پس آپ صلی اللہ علیہ وسلم نے اللہ کی کتاب کے مطابق قصاص کا فیصلہ فرمایا۔ انس بن نصر کہنے لگے: قسم اس ذات کی جس نے آپ کو حق کے ساتھ مبعوث فرمایا! آج اس کا دانت نہیں توڑا جائے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” انس! کتاب اللہ کا فیصلہ قصاص ہے۔ “ چنانچہ دوسرے لوگ دیت قبول کر لینے پر راضی ہو گئے (اور بدلہ نہیں لیا) تو نبی کریم صلی اللہ علیہ وسلم کو بڑا تعجب ہوا اور فرمایا ” اللہ کے کچھ بندے ایسے بھی ہوتے ہیں جو اللہ پر قسم ڈال دیں تو وہ پوری فر دیتا ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ میں نے امام احمد بن حنبل رضی اللہ عنہ سے سنا، ان سے پوچھا گیا کہ دانت کا قصاص کیسے لیا جائے؟ تو انہوں نے کہا ” اسے رگڑ دیا جائے۔ “","f2":": حضرت انس نضر رضی اللہ کا ان کا رسول صلی اللہ علیہ وسلم پر دیا شریعت کا انکا ر نہ تھا۔بلکہ یہ اس طبعی عاراوراذیت کا اظہار تھا جو دانت توڑے جانے کی صورت میں ایک خاتون اور اس کے قبیلے لو لاحق ہونے والی تھی اور ان کا مقصودیہ تھا کہ اس کے علاوہ کوئی اوجل نکالا جائے۔ اس کی مثال ایسے ہی ہے جیسے ایک انسان روزہ رکھنے کا شائق ہے مگر اس کے نتیجے میں بھوک پیاس سے اذیت محسوس کرتا ہے تو اس طبعی اذیت کا اظہار کوئی معیوب نہیں۔\n2: حضرت انس بن نضر اللہ کے محبوب بندے تھے کہ اللہ نے ا ن کی قسم پوری کردی۔\n3:امام حنبل رحمہ اللہ کا فتوی کہ دانت رگڑدیا جائے اسی وقت صحیح ہو گا جب دانت اوپر ٹوٹا ہو۔"}],[4596,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہود اکہتر یا بہتر فرقوں میں بٹ گئے، نصاری اکہتر یا بہتر فرقوں میں بٹ گئے اور میری امت تہتر فرقوں میں بٹ جائے گی ۱؎\"۔\n§وضاحت\n۱؎ : اس حدیث میں مذموم فرقوں سے فروعی مسائل میں اختلاف کرنے والے فرقے مراد نہیں ہیں، بلکہ اس سے مراد وہ فرقے ہیں جن کا اختلاف اہل حق سے اصول دین و عقائد اسلام میں ہے، مثلا مسائل توحید، تقدیر، نبوت، اور صحابہ کرام رضی اللہ عنہم سے محبت و موالات وغیرہ میں، کیونکہ انہی مسائل میں اختلاف رکھنے والوں نے باہم اکفار و تکفیر کی ہے، فروعی مسائل میں اختلاف رکھنے والے باہم اکفار و تکفیر نہیں کرتے، (۷۳) واں فرقہ جو ناجی ہے یہ وہ فرقہ ہے جو سنت پر گامزن ہے، بدعت سے مجتنب اور صحابہ کرام سے محبت کے ساتھ ان کے نقش قدم پر چلتا ہے، حدیث سے یہ بھی پتا چلا کہ ان تمام گمراہ فرقوں کا شمار بھی نبی اکرم صلی اللہ علیہ وسلم نے امت میں کیا ہے وہ جہنم میں تو جائیں گے، مگر ہمیشہ کے لئے نہیں، سزا کاٹ کر اس سے نجات پا جائیں گے (۷۳) واں فرقہ ہی اول وہلہ میں ناجی ہو گا کیونکہ یہی سنت پر ہے، یہی باب سے مناسبت ہے۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یہودی اکہتر یا بہتر فرقوں میں تقسیم ہوئے اور عیسائی بھی اکہتر یا بہتر فرقوں میں بٹے اور میری امت تہتر فرقوں میں تقسیم ہو گی “-","f2":"علامہ ابو منصور عبد القاہر تمیمی اس حدیث کی شرح میں لکھتے ہیں کہ\n’’ ان فقہاء کا اختلاف نہیں ہے کہ جن کے اجتہاد کی بنیاد فہم پرست پر ہے وہ اپنے اپنے اجتہاد کی بنیاد پراشیاء کے حلال یا حرام ہونے کی رائے دیتے ہیں بلکہ اس تفرقہ سے مراد وہ اصولی اختلافات ہیں جو تو حید تقدیر شروط نبوت ورسالت محبت حدیث اور صحابہ رضوان اللہ علیہم اجمعین کے ساتھ محبت وموالاۃ وغیرہ کے مسائل میں ظاہر ہوئے اور ان مسائل میں ایک دوسرے کو کافر کیاگیا۔جبکہ فقہی نوعیت کے مسائل میں کسی نے کسی کو کافر نہیں کہا۔ (عون المعبود) ‘‘"}],[4597,"ابوعامر عبداللہ بن لحی حمصی ہوزنی کہتے ہیں کہ معاویہ رضی اللہ عنہ نے ہمارے درمیان کھڑے ہو کر کہا: سنو! رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان کھڑے ہوئے اور فرمایا: \"سنو! تم سے پہلے جو اہل کتاب تھے، بہتر (۷۲) فرقوں میں بٹ گئے، اور یہ امت تہتر(۷۳) فرقوں میں بٹ جائے گی، بہتر فرقے جہنم میں ہوں گے اور ایک جنت میں اور یہی «الجماعة» ہے\"۔ ابن یحیی اور عمرو نے اپنی روایت میں اتنا مزید بیان کیا: \"اور عنقریب میری امت میں ایسے لوگ نکلیں گے جن میں گمراہیاں اسی طرح سمائی ہوں گی، جس طرح کتے کا اثر اس شخص پر چھا جاتا ہے جسے اس نے کاٹ لیا ہو ۱؎\"۔ اور عمرو کی روایت میں «لصاحبه» کے بجائے «بصاحبه» ہے اس میں یہ بھی ہے: کوئی رگ اور کوئی جوڑ ایسا باقی نہیں رہتا جس میں اس کا اثر داخل نہ ہوا ہو۔\n§وضاحت\n۱؎ : جس طرح کتے کا زہر رگ و ریشہ میں سرایت کر جاتا ہے، اسی طرح بدعتیں ان کے رگ و ریشہ میں سما جاتی ہیں۔","حسن",{"u2":"ابو عامر ہوزنی کا بیان ہے کہ سیدنا معاویہ بن ابوسفیان رضی اللہ عنہ ہم میں خطبہ دینے کے لیے کھڑے ہوئے اور کہا: خبردار! تحقیق رسول اللہ صلی اللہ علیہ وسلم ہم میں کھڑے ہوئے اور فرمایا خبردار! تم سے پہلے اہل کتاب بہتر (72) فرقوں میں تقسیم ہوئے تھے اور یہ ملت تہتر (73) فرقوں میں تقسیم ہو گی۔ بہتر (72) آگ میں جائیں گے اور ایک فرقہ جنت میں جائے گا اور یہی الجماعۃ ہو گا۔ ابن یحییٰ اور عمرو نے اپنی روایتوں میں مزید کہا بلاشبہ میری امت میں سے کچھ قومیں نکلیں گی ان میں یہ اہواء (من پسند نظریات اور اعمال کو دین میں داخل کرنا) ایسے سرایت کر جائیں گی جیسے کہ باؤلے پن کی بیماری اپنے بیمار میں سرایت کر جاتی ہے۔\nحضرت عمرو نے کہا باؤلے پن کے بیمار کی کوئی رگ اور کوئی جوڑ باقی نہیں رہتا جس میں اس بیماری کا اثر نہ ہو۔","f2":"۔ان احادیث میں صحابہ کرام رضی اللہ عنہ اور امت کے افراد کو متنبہ کیا گیا ہے کہ رسول اللہ صلى الله عليه وسلم نے پہلے ہی بتادیاتھا۔\n2۔ الجماعة بمعنی اجتماع دراصل اسم مصدر ہے اور ایسی قوم کے لیے بو لاگیا ہے جو آپس میں ہر طرح اکھٹے اور مجتمع ہوں۔اهل السنة والجماعة کا نام بھی اس معنی میں ہے کہ یہ لوگ کتاب و سنت پر مجتمع ہیں اور ان میں ایسا افتراق نہیں ہے کہ ایک دوسرے کو گمراہ قرار دیتے پھریں۔شیخ جیلانی رحمہ اللہ نے الجماعہ سے مراد جماعت صحابہ کے متبع لوگ بیان کیا ہے۔کیونکہ صحابہ کے زمانے میں صرف اور صرف کتاب و سنت پر سب اکھٹے تھے۔اہواءاور بدعات تو ایک طرف کسی فقہی مکتب فکر کا وجود بھی نہیں تھا۔\n3۔ اهل السنةوالجماعة وہی ایک فرقہ ہے جو بزبان رسالت نجات یافتہ ہے۔جب لوگ تفرقے کے اسباب سے باز آجائیں تو ان میں اتفاق واتحاد آجاتا ہےاور پھر وہ الجماعة بنتے ہیں۔تفرقہ کا بنیادی سبب اور سنت صحیحہ کو چھوڑ کر بدعات کی پیروی کرنا ہے"}],[4598,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے آیت کریمہ «هو الذي أنزل عليك الكتاب منه آيات محكمات» سے لے کر «أولو الألباب» ۱؎ تک تلاوت کی اور فرمایا: \"جب تم ایسے لوگوں کو دیکھو جو متشابہ آیات کے پیچھے پڑتے ہوں تو جان لو کہ یہی لوگ ہیں جن کا اللہ نے نام لیا ہے تو ان سے بچو ۲؎\"۔\n§وضاحت\nوضاحت ۱؎ : پوری آیت کا ترجمہ یہ ہے: اللہ ہی ہے جس نے تجھ پر وہ کتاب اتاری جس میں واضح و مضبوط آیتیں ہیں جو اصل کتاب ہیں، اور بعض متشابہ آیتیں ہیں، پس جن کے دلوں میں کجی ہے وہ محکم کو چھوڑ کر متشابہ کے پیچھے لگ جاتے ہیں فتنہ پروری کی طلب میں اور اس کی حقیقی مراد معلوم کرنے کے لئے، حالانکہ اس کی حقیقی مراد سوائے اللہ کے کوئی نہیں جانتا، پختہ علم والے تو یہی کہتے ہیں کہ ہم تو ان پر ایمان لاچکے یہ سب ہمارے رب کی طرف سے ہیں اور نصیحت تو صرف عقل والے ہی حاصل کرتے ہیں (سورۃ آل عمران:۷) ۲؎ : محکم آیات کو چھوڑ کر متشابہ کے پیچھے لگنا تمام بدعتیوں کی عادت ہے، وہ قدیم ہوں یا جدید ان سے دور رہنے کا حکم ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے بیان کیا کہ رسول صلی اللہ علیہ وسلم نے یہ آیت کریمہ تلاوت فرمائی «هو الذي أنزل عليك الكتاب منه آيات محكمات *** إلى *** ‏**أولو الألباب» ” (اللہ) وہ ذات ہے جس نے آپ پر کتاب نازل کی، جس میں بعض آیتیں محکم (واضح) ہیں جو اس کتاب کی اصل بنیاد ہیں اور کچھ دوسری آیتیں متشابہات (غیر واضح) ہیں، تو جن کے دلوں میں ٹیڑھ ہے وہ ان میں سے انہی آیتوں کے پیچھے پڑے رہتے ہیں جو متشابہ (غیر واضح) ہیں، ان کا مقصد محض فتنے اور تاویل کی تلاش ہوتا ہے، حالانکہ اللہ کے سوا کوئی بھی ان کی تاویل نہیں جانتا، اور جو لوگ پختہ علم والے ہیں وہ کہتے ہیں کہ ہمارا ان (متشابہات) پر ایمان ہے، یہ سب ہمارے رب کی طرف سے ہیں اور نصیحت وہی لوگ پکڑتے ہیں جو عقل والے ہیں۔ ” سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جب تم ایسے لوگوں کو دیکھو جو متشابہ آیتوں کے پیچھے پڑتے ہوں تو یہ وہی لوگ ہیں جن کے بارے میں اللہ نے فرمایا ہے «فاحذروهم» ” ان سے ڈرتے اور بچتے رہو۔ “","f2":"1۔قرآنی آیات کے محکم اور متشابہ ہونے کے کئی معانی ہیں۔مثلاًوہ آیات جو دوسری ایات کے لیے ناسخ ہیں۔\nیا جن میں حلال وحرام کابیان آیا ہے۔یاوہ آیات جن کے معانی واضح اور بندے ان سے آگاہ ہیں۔یا جن کی کوئی تاویل نہیں وہ محکم کہلاتی ہیں اور متشابہ سے مراد وہ آیات ہیں جو منسوخ ہوچکی ہیں مگر تلاوت بھی ہورہی ہے۔یا حق وصدق میں ایک دوسری کے مشابہ ہیں انہیں متشابہ کہا گیا ہے۔یا ایسی آیات جن کے معانی ومفاہیم سے صرف اللہ عزوجل ہی آگاہ ہے۔یاجن کے مفاہیم کئی پہلو رکھتے ہیں وہ متشابہات کہلاتی ہیں۔\n2۔جدال (لڑائی کرنا)بظاہرکوئی قابل تعریف نہیں سمجھاجاتا مگر اظہار حق اور ابطال باطل کے لیے ازحد ضروری ہے اور قابل تعریف ہے،قرآن کریم میں اللہ تعالی نے اس کے لیے علم وحکمت کو شرط قرار دیا ہے۔ارشاد الہی ہے: (وجادلهم بالتي هي احسن) النحل:١٢٥) محض ریاو سمعہ (شہرت)اور لوگوں کی توجہات حاصل کرنے کی کوشش میں یا باطل کی تائید میں جدال کرنا حرام ہے۔\n3۔اہل اہواء (اہل بدعت) اور متشابہات کے درپے ہونےوالوں سے دور رہنا چاہیے تاکہ انہیں تقویت وشہرت نہ ملے اور کہیں کسی فتنے میں مبتلا نہ کردیں البتہ راسخ علماء کا فریضہ ہے کہ حق کا اظہار وبیان کریں اور عوام کو باطل سے متنبہ اور آگاہ کرتے رہیں۔\n4۔اور ایسے لوگ مختلف ناموں سے ہر دور میں اور ہر جگہ موجود رہے ہیں۔"}],[4599,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے افضل عمل اللہ کے واسطے محبت کرنا اور اللہ ہی کے واسطے دشمنی رکھنا ہے\"۔","ضعیف",{"u2":"سیدنا ابوذر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اعمال میں سے افضل عمل اللہ کے لیے محبت کرنا اور اسی کے لیے بغض رکھنا ہے۔ “","f2":"یہ روایت سنداً ضعیف ہے لیکن اس موضوع پر دیگر صحیح روایات موجود ہیں (الحب في الله) اور (البعض في الله) کا مفہوم یہ ہے کہ کسی سے محبت کے بہت سے اسباب موجود ہ ہوں لیکن وہ اللہ کے دین میں بگاڑ کا شکار ہوتو اللہ کے لیے اس سے محبت نہ کی جائے اسی سے محبت کی جائےجو اللہ کی راہ میں چلیں اور صرف اسی غرض سے کی جائےکہ اللہ راضی ہو اور اسی طرح بغض بھی اللہ کے دین سے ہٹنے والے کے ساتھ اور اللہ کی رضا کے لیے ہونا چاہیے۔یہ بھی ضروری ہے کہ اللہ کی نافرمانی پر بعض رکھنا کافی نہیں۔اہل علم کے لیے واجب ہے کہ حق کی دعوت دینے میں کبھی بھی غفلت نہ کریں۔"}],[4600,"عبداللہ بن کعب سے روایت ہے (جب کعب رضی اللہ عنہ نابینا ہو گئے تو ان کے بیٹوں میں عبداللہ آپ کے قائد تھے) وہ کہتے ہیں: میں نے کعب بن مالک سے سنا (ابن السرح ان کے غزوہ تبوک میں نبی اکرم صلی اللہ علیہ وسلم سے پیچھے رہ جانے کا واقعہ ذکر کر کے کہتے ہیں کہ کعب نے کہا) رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں کو ہم تینوں سے گفتگو کرنے سے منع فرما دیا یہاں تک کہ جب لمبا عرصہ ہو گیا تو میں ابوقتادہ رضی اللہ عنہ کے باغ کی دیوار کود کر ان کے پاس گیا، وہ میرے چچا زاد بھائی تھے، میں نے انہیں سلام کیا تو قسم اللہ کی! انہوں نے میرے سلام کا جواب نہیں دیا، پھر راوی نے ان کی توبہ کے نازل ہونے کا قصہ بیان کیا ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے پتا چلا کہ صحابہ کرام رضوان اللہ علیہم اجمعین کو رسول اللہ صلی اللہ علیہ وسلم جس سے بات چیت کرنے سے منع فرما دیتے اس سے وہ ہرگز بات چیت نہیں کرتے تھے چاہے وہ عزیز و قریب دوست و رفیق ہی کیوں نہ ہو، اہل بدعت و اہل ہوس سے دور رہنے اور ان سے بغض رکھنے کا حکم ہے، تمام مسلمانوں کو اس کا خیال کرنا چاہئے تاکہ ان کے فتنوں سے خود محفوظ رہیں، اور اپنے معاشرے کو محفوظ رکہیں۔","صحیح",{"u2":"جناب عبداللہ اپنے والد سیدنا کعب بن مالک رضی اللہ عنہ کے نابینا ہو جانے کے بعد ان کے قائد ہوا کرتے تھے۔ وہ بیان کرتے ہیں کہ میں نے (اپنے والد) سیدنا کعب بن مالک رضی اللہ عنہ سے سنا اور ابن سرح نے ان کے غزوۃ تبوک میں نبی کریم صلی اللہ علیہ وسلم سے پیچھے رہ جانے کا قصہ بیان کیا، کہا کہ رسول صلی اللہ علیہ وسلم نے مسلمانوں کو ہم تینوں سے بات چیت سے منع فر دیا۔ حتیٰ کہ جب یہ صورت حال مجھ پر بہت طویل (اور گراں) ہو گئی تو میں نے ابوقتادہ کے باغ کی دیوار چڑھ کر اس سے بات کی، وہ میرے چچا کا بیٹا تھا، میں نے سلام کیا تو اللہ کی قسم! اس نے میرے سلام کا جواب نہیں دیا۔ پھر (ابن سرح نے) ان کی توبہ نازل ہونے کی خبر بیان کی۔","f2":"شخصی احوال میں اپنے کسی مسلمان بھائی سے ناراض ہوجائے تو تین دن سے زیادہ بات چیت چھوڑ دینا جائز نہیں۔لیکن اگر دینی اور شرعی سبب ہو تو یہ مقاطعہ طویل کیا جاسکتا ہے۔بالخصوص اہل بدعت سے دینی حق کی بناء پر دائمی مقاطعہ (قطع تعلقی) مطلوب ہے۔\n2۔حضرت کعب بن مالک مرارہ بن ربیع اور ہلالبن امیہ رضوان اللہ علیہم اجمعین کا غزوہ تبوک سے پیچھے رہ جانے کاواقعہ معروف ہے۔تفسیروسیرت اور احادیث کی کتب میں تفصیل دیکھی جاسکتی ہے۔ان حضرات کی توبہ پچاسدن کے بعد قبول ہوئی تھی۔اس دوران میں تادیب وتنبیہ کے لیے مسلمانوں کو ان سے بعد چیت سے منع کردیاگیا تھا۔صحیح بخاری اور صحیح مسلم میں اس کی پوری تفصیل موجود ہے"}],[4601,"عمار بن یاسر رضی اللہ عنہما کہتے ہیں کہ میں اپنے گھر والوں کے پاس آیا، میرے دونوں ہاتھ پھٹ گئے تھے، تو انہوں نے میرے (ہاتھوں پر) زعفران مل دیا، صبح کو میں نبی اکرم صلی اللہ علیہ وسلم کے پاس گیا اور سلام کیا تو آپ نے مجھے جواب نہیں دیا اور فرمایا: \"جاؤ اسے دھو ڈالو\"۔","حسن",{"u2":"سیدنا عمار بن یاسر رضی اللہ عنہ بیان کرتے ہیں کہ میں اپنے گھر والوں کے پاس پہنچا اور حالت یہ تھی کہ میرے ہاتھ پھٹ گئے تھے۔ تو انہوں نے مجھے (میرے ہاتھوں پر) زعفران لگا دیا۔ صبح کے وقت میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور میں نے سلام عرض کیا تو آپ نے مجھے جواب نہ دیا اور فرمایا ” جاؤ اسے دھو ڈالو۔ “","f2":"نبی صلى الله عليه وسلم نے عمار رضی اللہ عنہ کو اس کے عمل کے حوالے سے انہیں ناپسندیدگی کا احساس دلایا۔اسی سے یہ بھی ثابت ہوا کہ مقاطعہ کے دوران میں اصلاح احوال کے لیے بات سمجھانے میں کوئی حرج نہیں بلکہ یہ ضروری ہے۔"}],[4602,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ام المؤمنین صفیہ بنت حیی رضی اللہ عنہا کا ایک اونٹ بیمار ہو گیا اور ام المؤمنین زینب رضی اللہ عنہا کے پاس ایک فاضل سواری تھی تو رسول اللہ صلی اللہ علیہ وسلم نے زینب سے فرمایا: \"تم اسے ایک اونٹ دے دو\" وہ بولیں: میں اس یہودن کو دے دوں؟ اس پر رسول اللہ صلی اللہ علیہ وسلم ناراض ہو گئے اور ذی الحجہ، محرم اور صفر کے چند دنوں تک ان سے بات چیت ترک رکھی۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ ام المؤمنین سیدہ صفیہ بنت حییی رضی اللہ عنہا ا کا اونٹ بیمار ہو گیا اور ام المؤمنین سیدہ زینب رضی اللہ عنہا ا کے پاس ایک زائد سواری تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ زینب رضی اللہ عنہا ا سے کہا ” اونٹ اسے دے دو۔ “ تو انہوں نے کہا: بھلا میں اس یہودن کو دوں؟ تو رسول اللہ صلی اللہ علیہ وسلم غصے ہو گئے اور ذوالحجہ، محرم اور صفر کے کچھ دنوں تک ان سے بات چیت نہ کی۔","f2":"1۔آپ کا یہ مقاطعہ اس وجہ سے تھا کہ حضرت زینب رضی اللہ عنہ نے اسلامی آداب کو ملحوظ نہ رکھاتھا۔\n2۔کسی مسلمان کو اس کے گزشتہ دین کی بنیاد پر یہودی یا کافر کہنا حرام ہے۔\n3۔بلاوجہ عار دلانا بھی بہت بڑاعیب اور گناہ ہے۔\n4۔بلا عذر ضرورت کی چیز اپنے مسلمان بھائی کو نہ دینا بد اخلاقی ہے سورۃالماعون میں یہ مسئلہ خصوسیت سے بیان ہوا ہے۔\n5۔شرعی بنیاد پر مقاطعہ کیا جائے تو تین دن سے زائد عرصہ کے لیے بھی جائز ہے۔"}],[4603,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"قرآن کے بارے میں جھگڑنا کفر ہے ۱؎\"۔\n§وضاحت\n۱؎ : اس سے مراد کیا ہے؟ اس بارے میں متعدد اقوال ہیں: ( ۱ ) قرآن کے قدیم یا محدث ہونے میں بحث کرنا مراد ہے، (۲) متشابہ آیات کے بارے میں حقیقت تک پہنچنے میں بحث و مناظرہ کرنا مراد ہے، (۳) قرآن کی مختلف قراءتوں کے بارے میں اختلاف کرنا، کسی حرف کو ثابت کرنا اور کسی کا انکار کرنا وغیرہ مراد ہے، (۴) تقدیر وغیرہ کے سلسلہ میں جو آیات وارد ہیں اس میں بحث کرنا مراد ہے، ان تمام صورتوں میں بحث اکثر اس حد تک پہنچتی ہے کہ اس سے قرآن کے الفاظ و معانی کا انکار لازم آتا ہے جو کفر ہے، أعاذنا اللہ منہ۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” قرآن کریم میں جھگڑا کرنا کفر ہے۔ “","f2":"1۔(المراء) سے مراد جھگڑنا اور شک کا اظہار کرناہے۔لہذا قرآنی آیات میں ایسا مباحثہ اور جھگڑا کرنا کہ کسی حسے کی تکزیب لازم آئے یا شک وشبہ پیداہو حرام اور کفر ہے۔\n2۔قابل حل مقامات کے لیے ثقہ اور راسخ علماء کی طرف رجوع کرکے صحیح معنی ومفہوم معلوم کرنا چاہیے۔متشابہات کے درپے ہونے سے بچنا ضروری ہے اور جہاں تک ہوسکے شکوک و شبہات اور فتنہ پیدا کرنے والے لوگوں کو واضح دلائل سے قائل کیا جائے اور عوام کو ان سے دور رکھا جائے۔\n3۔مذکورہ احادیث سے پتا چلتا ہے کہ جان بوجھ کر لوگوں میں فتنہ انگیزی کرنے والے امت کے لیے خطرناک ہیں۔اس فتنہ انگیزی کو روکنے کے طریقے یہ ہیں:0اہل اہواء سے مقاطعہ۔\n() ان کی تمام با توں آکر اوٹ پٹانگ معاملات میں الجھنے سے پرہیز،\n0معاشرے میں نفرت پھیلانے والے کاموں سے اجتناب جو فتنہ برپا کرنے والے نہ ہوں غلطیوں پر ان کی پر حکمت تفہیم۔"}],[4604,"مقدام بن معد یکرب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سنو، مجھے کتاب (قرآن) دی گئی ہے اور اس کے ساتھ اسی کے مثل ایک اور چیز بھی (یعنی سنت)، قریب ہے کہ ایک آسودہ آدمی اپنے تخت پر ٹیک لگائے ہوئے کہے ۱؎: اس قرآن کو لازم پکڑو، جو کچھ تم اس میں حلال پاؤ اسی کو حلال سمجھو، اور جو اس میں حرام پاؤ، اسی کو حرام سمجھو، سنو! تمہارے لیے پالتو گدھے کا گوشت حلال نہیں، اور نہ کسی نوکیلے دانت والے درندے کا، اور نہ تمہارے لیے کسی ذمی کی پڑی ہوئی چیز حلال ہے سوائے اس کے کہ اس کا مالک اس سے دستبردار ہو جائے، اور اگر کوئی کسی قوم میں قیام کرے تو ان پر اس کی ضیافت لازم ہے، اور اگر وہ اس کی ضیافت نہ کریں تو اسے حق ہے کہ وہ ان سے مہمانی کے بقدر لے لے ۲؎\"۔\n§وضاحت\n۱؎ : یہ پیش گوئی منکرین حدیث کے سرغنہ عبداللہ چکڑالوی پر صادق آتی ہے، مولانا نورالدین کشمیری (صدر جمعیت اہل حدیث کشمیر) جب اس سے مناظرہ کرنے لاہور میں اس کے گھر پہنچے تو وہ مولانا سے انکار حدیث پر اس حال میں بحث کر رہا تھا کہ وہ اپنی چارپائی پر ٹیک لگائے ہوئے لیٹا تھا (مولانا مرحوم کا خود نوشت بیان، شائع شدہ اخبار تنظیم اہل حدیث کراچی)۔ ۲؎ : ضیافت اسلامی معاشرہ میں ایک نہایت ہی نیک عمل ہے اگر میزبان مہمان کی مہمانی نہ کرے تو اس کو مہمانی کے بقدر وصول کرنا ابتداء اسلام میں تھا بعد میں اس پر عمل نہ رہا، گری پڑی چیز ذمی کی ہو یا مسلمان کی اگر اس کا مالک اس کو چھوڑ دے اور اس سے مستغنی ہو جائے تو دوسرے کو لے لینا جائز ہے، ورنہ نہیں، اس حدیث میں صاف طور پر موجود ہے کہ حدیث کو قرآن پر پیش کرنا ضروری نہیں بلکہ قرآن کی طرح حدیث بھی مستقل حجت ہے، حدیث کو قرآن پر پیش کرنے سے متعلق جو حدیث بیان کی جاتی ہے کذب محض ہے، زنادقہ نے اس کو گھڑا ہے۔","صحیح",{"u2":"سیدنا مقدام بن معدیکرب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” خبردار! مجھے قرآن کے ساتھ اس جیسی ایک اور چیز بھی دی گئی ہے۔ عنقریب ایسے ہو گا کہ ایک پیٹ بھرا (آسودہ حال) آدمی اپنے تخت یا دیوان پر بیٹھا کہے گا کہ اسی قرآن کو اختیار کر لو، جو اس میں حلال ہے اسے حلال جانو اور جو اس میں حرام ہے اسے حرام سمجھو۔ خبردار! تمہارے لیے پالتو گدھے، نیش دار درندے اور کسی ذمی (کافر) کا گرا پڑا مال اٹھا لینا حلال نہیں، الا یہ کہ اس کا مالک اس سے بے پروا ہو۔ اور جو کوئی کسی قوم کے پاس جائے تو ان پر واجب ہے کہ اس کی مہمانی کریں، اگر وہ اس کی مہمانی نہ کریں تو اسے حق حاصل ہے کہ اپنی مہمانی کے مثل ان سے بذریعہ طاقت حاصل کر لے۔ “"}],[4605,"ابورافع رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں تم میں سے کسی کو اپنے تخت پر ٹیک لگائے ہرگز اس حال میں نہ پاؤں کہ اس کے پاس میرے احکام اور فیصلوں میں سے کوئی حکم آئے جن کا میں نے حکم دیا ہے یا جن سے روکا ہے اور وہ یہ کہے: یہ ہم نہیں جانتے، ہم نے تو اللہ کی کتاب میں جو کچھ پایا بس اسی کی پیروی کی ہے ۱؎\"۔\n§وضاحت\n۱؎ : یہ حدیث رسول اللہ صلی اللہ علیہ وسلم کے معجزات میں سے ایک زندہ معجزہ ہے، اور حدیث کی صداقت کا زندہ ثبوت ہے آج بعض منکرین حدیث \"اہل قرآن\" کے نام سے وہی کچھ کر رہے ہیں جن کی خبر رسول اکرم صلی اللہ علیہ وسلم نے دی تھی (دیکھئے حاشیہ حدیث نمبر: ۴۶۰۴)","صحیح",{"u2":"جناب عبیداللہ اپنے والد سیدنا ابورافع رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہرگز ایسا نہ ہو کہ میں تم میں سے کسی کو پاؤں کہ وہ اپنے تخت یا دیوان پر بیٹھا ہو اور اس کے پاس میرے احکام میں سے کوئی حکم پہنچے جس کا میں نے حکم دیا ہو یا اس سے منع کیا ہو تو وہ کہنے لگے کہ ہم نہیں جانتے، ہم تو کتاب اللہ میں جو پائیں گے، اسی پر عمل کریں گے۔“","f2":"1۔مذکورہ دونوں روایتوں میں اریکہ کا لفظ آیا ہے۔اس سے مراد لکڑی کا بنا ہوا تخت یادیوان ہے جس پر لوگ گھروں میں بیٹھتے تھے یا جائے نماز کے طور پر استعمال کرتے تھے۔\n2۔رسول اللہ صلى الله عليه وسلم کو قرآن کریم کر ساتھ اسی جیسی دی گئی چیز حدیث اور سنت ہے۔قرآن کو وحی جلی اور وحی متلو کہا جاتاہے۔یعنی جس کی تلاوت ہوتی ہے۔جبکہ حدیث اور سنت کو وحی خفی اور وحی غیر متلو کہتے ہیں۔یعنی جس کی تلاوت نہیں ہوتی لیکن وہ اللہ کی طرف سے ہے۔قرآن کریم بسبب تلاوت عامہ وکثیر ہ اول دن سے تواتر کے ساتھ ثابت ہے۔جبکہ احادیث کے اثبات کے لیے اسانید (خبر دینےوالوں کے سلسلے)کی صحت اولین شرط ہے۔علمائے راسخین اور ماہرین فن حدیث کی تنقیح وتحقیق کے بعد جن احادیث کی نسبت رسول اللہ صلى الله عليه وسلم کی طرف صحیح ثابت ہوا ن کا اتباع اسی طرح واجب ہے جیسے کہ قرآن مجید کا اور قرآن مجید کی متعدد آیات اس امر کی تصریح کرتی ہیں اور قول فیصل ہیں۔جیسے ارشاد الہی:(وانزلنا اليك الذكر لتبين للناس مانزل اليهم) (النحل:٤٤)ہم نے آپ کی طرف ذکر نازل کیاہے تاکہ آپ لوگوں کوان کی طرف نازل کردہ کی خوب وضاحت کردیں۔ اور بلاشبہ آپ صلى الله عليه وسلم کی وضاحت قول وفعل اور توثیق سے ہوئی ہے اور صحابہ کرام نے اس کو خوب محفوظ رکھا اور آگے نقل کیا ہے۔سورۃالنساء میں ہے:(من يطع الرسول فقد اطاع الله ومن تولي فما ارسلنك عليهم حفيظاً) (النساء;٨-) جس نے رسول اللہ کی اطاعت کی اس نے اللہ کی اطاعت کیاور جس نے منہ پھیر لیا تو ہم نے آپ کو ان پر نگران بنا کر نہیں بھیجاہے۔\nسورۃ النور میں ہے: قل اطيعو الله واطيعوالرسول فان تولوا فانما عليه ما حمل و عليكم ما حملتم وان تطيعوه تهتدوا وما علي الرسول الله الا البلغ المبين) (النور;٥٤)\nکہہ دیجیے اللہ کی اطاعت کرو اور رسول کی اطاعت کرو اگر تم اس سے منہ پھیرلوگے تو رسول پر وہی ہے جو اس پر لازم کیا گیا ہے اور تم سے صرف اس کی جوابدہی ہو گی جو تمھارے ذمے ہے اگر تم اس کی اطاعت کروگے تو ہدایت پر رہوگے اور رسول کے ذمے صرف واضح طور پر پہنچادینا ہے علاوہ ازیں فرمایا: (فليحذر الذين يخالفون عن امره ان تصيبهم فتنه او يصيبهم عذاب اليم) (النور:٦٣) ان لوگوں کو جو رسول کے حکم کی خلاف ورزی کرتے ہیں ڈرنا چاہیے کہ انہیں کوئی فتنہ نہ آلے یا کوئی دردناک عذاب نہ پہنچ جائے۔\nسورۃ الحشر میں فرمایا:(وما اتکم الرسول فخذوہ ومانھکم عنہ فانتھوا) (الحشر:7)\nاللہ کے رسول اللہ صلى الله عليه وسلم جو کچھ تمہیں دیں وہ لے لو اور جس سے روک دیں اس سے روک جاؤ۔ علاوہ ازیں اور بھی متعدد آیات جحیت حدیث کی واضح دلیل ہیں۔\n3۔ایسے تمام گروہ فرقے یا افراد جو محض قرآن کی اتباع کا دعوی کرتے ہیں لیکن صحیح احادیث سے اعراض کرتے ہیں مندرجہ بالا حدیث اور آیات میں ان کے لیے بہت بڑی تنبیہ ہے۔\n4۔یہ احادیث نبی کریم صلى الله عليه وسلم کی صداقت وحقانیت کی بہت بڑی دلیل ہیں کہ جو بھی غیب کی خبریں آپ نے دی ہیں وہ بالکل سچ ثابت ہورہی ہیں۔پاکستان کے صوبے پنجاب میں ظاہر ہونے والا فرقہ اہل قرآن اور ان کا سردار عبد اللہ چکڑالوی بالخصوص اس حدیث کا مصداق ثابت ہوا۔اس نے اپنے بیٹے مولوی محمد ابراہیم کو اپنے مال سے بغیر کسی قصور کے محروم کردیا۔وہ آئے اور والد کے سامنے کھڑے ہوکر بات کی اور یہ حدیث سنائی: کوئی اپنے ایک بیتے کو محروم کرے گا قیامت کے دن اس طرح اٹھے گا کہ اس کے جسم کا ایک مرا ہوا ہوگا۔حدیث سن کر باپ نے کہا ہم نہیں جانتے ہم اللہ کی کتاب میں جو پائیں گے اسی پر عمل کریں گے۔مولوی ابراہیم نے نظر اٹھاکر دیکھا تو سامنے عبداللہ چکڑالوی لکڑی کے دیوان پر سہارا لے کر بیٹھے ہوئے یہ فقرہ کہہ رہا تھا۔ان کے سامنے یہ منظر واضح طور پر آگیا جو حدیث میں دکھایا گیا ہے۔وہ حیرت ودہشت میں ڈوب گئے اور آپ تو وہی ہیں آپ تو وہی ہیں کہتے ہیں الٹے پاؤں واپس ہو گئےاور باپ کے شہر سے بہت دور ایک گاؤں میں جابسے اور زندگی بھر اپنے حصے کا مطالبہ نہیں کیاکہ ایسے باپ کی دولت سے مجھے کوئی حصہ نہیں چاہیے جو انکار حدیث کے سرغنہ کے طور پر رسول اللہ صلى الله عليه وسلم کو پہلے ہی دکھا دیا گیا تھا۔\n5۔صحیح احادیث حتمی طور پر واجب العمل ہیں۔یہ ایک حیلہ ہے کہ احادیث صحیحہ کو پہلے قرآن پر پیش کیا جائےاور پھر عمل کا فیصلہ کیا جائے۔احادیث قرآن سے ٹکراتی ہی نہیں بلکہ خود قرآن کی رو سے قرآن کی وضاحت اور تفسیر ہیں۔ان کی روشنی میں قرآن کا مفہوم متعین ہوتا ہے کوئی صحیح قرآن سے ٹکراتی ہی نہیں بلکہ یہ بھی اللہ کی طرف سے ہیں،سورۃ القیامۃ میں ارشاد الہی ہے: (فاذا قرانه فاتبع قرانه ّثم ان علينا بيانه) القيامه:١٩ ١٨)\nجب ہم اس کو پڑھ لیں تب آپ اس کی قرات کریں پھر اس کی وضاحت ہمارے ذمے ہے۔"}],[4606,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو ہمارے اس دین میں کوئی ایسی نئی بات پیدا کرے جو اس میں نہیں ہے تو وہ مردود ہے\"۔ ابن عیسی کی روایت میں ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی ایسا کام کرے جو ہمارے طریقے کے خلاف ہو تو وہ مردود ہے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ صدیقہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے ہمارے اس معاملے (دین) میں کوئی نئی چیز پیدا کی جو اس میں سے نہیں تو وہ مردود اور باطل ہے۔ “ ابن عیسیٰ نے یوں روایت کیا، نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے ہمارے طریقے کے خلاف کوئی کام کیا تو وہ مردود اور باطل ہے۔“","f2":"اس حدیث میں دین کے لیے لفظ (امرنا) استعمال کیا گیا ہے کیونکہ ہدایت کا سرچشمہ رسول اللہ صلى الله عليه وسلم ہی ہیں اس لیے آپ کے ارشاد کے بغیر کوئی کام بھی اللہ کے ہاں عبادت یا تقریب کا درجہ نہیں پاسکتا۔\n2۔(فهو رد) وہ مردود ہے کے دو مفہوم میں یعنی وہ کام باطل اور مردود ہے نیز وہ آدمی جو اس کا مرتکب ہووہ بھی مردود اور قابل نفرین ہے۔"}],[4607,"عبدالرحمٰن بن عمرو سلمی اور حجر بن حجر کہتے ہیں کہ ہم عرباض بن ساریہ رضی اللہ عنہ کے پاس آئے، یہ ان لوگوں میں سے ہیں جن کے بارے میں آیت کریمہ «ولا على الذين إذا ما أتوك لتحملهم قلت لا أجد ما أحملكم عليه» ۱؎ نازل ہوئی، تو ہم نے سلام کیا اور عرض کیا: ہم آپ کے پاس آپ سے ملنے، آپ کی عیادت کرنے، اور آپ سے علم حاصل کرنے کے لیے آئے ہیں، اس پر عرباض رضی اللہ عنہ نے کہا: ایک دن ہمیں رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی، پھر ہماری طرف متوجہ ہوئے اور ہمیں دل موہ لینے والی نصیحت کی جس سے آنکھیں اشک بار ہو گئیں، اور دل کانپ گئے، پھر ایک شخص نے عرض کیا: اللہ کے رسول! یہ تو کسی رخصت کرنے والے کی سی نصیحت ہے، تو آپ ہمیں کیا وصیت فرما رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں تمہیں اللہ سے ڈرنے، امیر کی بات سننے اور اس کی اطاعت کرنے کی وصیت کرتا ہوں، خواہ وہ کوئی حبشی غلام ہی کیوں نہ ہو، اس لیے کہ جو میرے بعد تم میں سے زندہ رہے گا عنقریب وہ بہت سے اختلافات دیکھے گا، تو تم میری سنت اور ہدایت یافتہ خلفاء راشدین کے طریقہ کار کو لازم پکڑنا، تم اس سے چمٹ جانا، اور اسے دانتوں سے مضبوط پکڑ لینا، اور دین میں نکالی گئی نئی باتوں سے بچتے رہنا، اس لیے کہ ہر نئی بات بدعت ہے، اور ہر بدعت گمراہی ہے ۲؎\"۔\n§وضاحت\n۱؎ : \" اور نہ ان پر کوئی حرج ہے کہ جب وہ آپ کے پاس آتے ہیں کہ آپ انہیں سوار کرائیں یعنی جہاد کے لئے سواری فراہم کریں تو آپ ان سے کہتے ہیں: میرے پاس تمہارے لئے سواری نہیں \" (سورۃ التوبۃ: ۹۲)۔ ۲؎ : اس حدیث میں ہر اس نئی بات سے جس کی شرع سے کوئی اصل نہ ملے منع کیا گیا ہے، اصول شریعت چار ہیں: قرآن، حدیث، اجماع صحیح اور قیاس شرعی ، جو بات ان چار اصول میں نہ ہو وہ بدعت ہے، بدعت دو قسم کی ہوتی ہے : ایک بدعت شرعی دوسری بدعت لغوی، اس حدیث میں بدعت شرعی کا ہی بیان ہے، اس لئے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ ہر بدعت گمراہی ہے، بعض سلف سے جو بعض بدعات کے سلسہ میں تحسین منقول ہے وہ بدعت لغوی کے سلسلہ میں ہے ناکہ بدعت شرعی کے بارے میں؛ چنانچہ عمر رضی اللہ عنہ نے تراویح با جماعت کے لئے فرمایا: «إن كانت هذه بدعة فنعمت البدعة» یعنی اگر یہ نئی چیز ہے تو کتنی اچھی ہے، بدعت شرعیہ کی کوئی قسم بدعت حسنہ نہیں، البتہ سنت حسنہ ہی ہوتی ہے، «سنة الخلفاء الراشدين» سے درحقیقت رسول اللہ صلی اللہ علیہ وسلم ہی کی سنت مراد ہے جسے رسول اکرم صلی اللہ علیہ وسلم کے زمانہ میں کسی وجہ سے شہرت حاصل نہ ہو سکی ، اور خلفاء راشدین کے زمانہ میں رواج پذیر اور مشہور ہوئی اس بنا پر ان کی طرف منسوب ہوئی (أشعة اللمعات، للدهلوي) نیز اگر خلفاء راشدین کسی بات پر متفق ہوں تو اس حدیث کے بموجب ان کی سنت ہمارے لئے سنت ہے۔","صحیح",{"u2":"جناب عبدالرحمٰن بن عمرو سلمی اور حجر بن حجر کا بیان ہے کہ ہم سیدنا عرباض بن ساریہ رضی اللہ عنہ کی خدمت میں حاضر ہوئے جن کے بارے میں یہ آیت کریمہ نازل ہوئی تھی «ولا على الذين إذا أتوك لتحملهم قلت لا أجد أحملكم عليه» ” ان لوگوں پر کوئی گناہ نہیں کہ جب وہ آپ کے پاس آئے کہ آپ انہیں سواری دیں، آپ نے کہا کہ میرے پاس کوئی چیز نہیں، تو وہ اس حال میں لوٹ گئے کہ ان کی آنکھیں، اس غم سے آنسو بہا رہی تھیں کہ انہیں کچھ میسر نہیں جسے وہ خرچ کریں۔ “ ہم نے انہیں سلام کیا اور عرض کیا: ہم آپ سے ملنے کے لیے آئے ہیں اور یہ کہ آپ کی عیادت ہو جائے اور کوئی علمی فائدہ بھی حاصل کر لیں، تو سیدنا عرباض رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک دن نماز پڑھائی، پھر ہماری طرف منہ کر لیا اور وعظ فرمایا، بڑا ہی بلیغ اور جامع وعظ، ایسا کہ اس سے ہماری آنکھیں بہہ پڑیں اور دل دہل گئے۔ ایک کہنے والے نے کہا: اے اللہ کے رسول! یہ تو گویا الوداعی وعظ تھا، تو آپ ہمیں کیا وصیت فرماتے ہیں؟ فرمایا ” میں تمہیں وصیت کرتا ہوں کہ اللہ کا تقویٰ اختیار کیے رہنا اور اپنے حکام کے احکام سننا اور ماننا، خواہ کوئی حبشی غلام ہی کیوں نہ ہو۔ بلاشبہ تم میں سے جو میرے بعد زندہ رہا وہ بہت اختلاف دیکھے گا، چنانچہ ان حالات میں میری سنت اور میرے خلفاء کی سنت اپنائے رکھنا، خلفاء جو اصحاب رشد و ہدایت ہیں، سنت کو خوب مضبوطی سے تھامنا، بلکہ ڈاڑھوں سے پکڑے رہنا، نئی نئی بدعات و اختراعات سے اپنے آپ کو بچائے رکھنا، بلاشبہ ہر نئی بات بدعت ہے اور ہر بدعت گمراہی ہے۔ “","f2":"1۔ایک بڑے کام میں ضمنی کئی منتیں کرلی جائیں تو جائز ہے۔اجر وثواب نیتوں ہی کے مطابق ملتا ہے۔چنانچہ زیارت علماء عیادت مریض اور علمی استفادہ سب کیر کے کام ہیں لہذا موقع محل اور حالات کی مناسبت سے یہ تمام کام کرنے چاہییں۔\n2۔رسول اللہ صلی اللہ علیہ وسلم حسب ضرورت نمازوں کے بعد بھی درس دیا کرتے تھے۔کتاب وسنت کا وعظ سن کر رونا جائز ہے۔\n3۔اختلاف امت کو مٹانے اور نجات وفلاح کی کلیدی صرف اور صرف رسول اللہ صلی اللہ علیہ وسلم اور خلفائے راشدین رضی اللہ عنہم کی سنت ہے۔خیال رہے کہ یہ کوئی دو سنتیں نہیں ہیں بلکہ یہ ایک ہی سنت ہے۔اگر بالفرض æÇÞÚÊÇð کہیں کوئی اختلاف محسوس ہو تو حجت صرف رسول اللہ صلی اللہ علیہ وسلم سے ثابت شدہ قول و فعل ہی ہے۔\n4۔مسلمانوں کے امام یعنی جس کو شوری کے ذریعے سے اپنا قائد چن لیا گیا ہو اس کی اطاعت واجب ہے بغیر اس کے کہ اس کا نام ونسب یا رنگ وروپ دیکھا جائے بشرطیکہ وہ قیادت میں شریعت کا پیرو ہو۔\n5۔دین میں بدعات سراسر گمراہی اور امت میں افتراق وفتنہ کا باعث ہیں۔جبکہ سنت وحدت واتفاق کی باعث اور نجات کی ضامن ہے۔"}],[4608,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے تین بار فرمایا: \"سنو، بہت زیادہ بحث و تکرار کرنے اور جھگڑنے والے ہلاک ہو گئے ۱؎\"۔\n§وضاحت\n۱؎ : متنطعون» سے مراد ایسے اشخاص ہیں جو حد سے تجاوز کر کے اہل کلام و فلسفہ کے طریقہ پر بے کار کی بحثوں میں پڑے رہتے ہیں اور ان مسائل میں بھی جو ماوراء عقل ہیں اپنی عقلیں دوڑاتے ہیں جس کی وجہ سے سلف کے طریقہ سے دور جا پڑتے ہیں، ان کے لئے اس میں سخت وعید ہے اور اس بات کی دلیل ہے کہ نصوص پر حکم ان کے ظاہر کے اعتبار ہی سے لگایا جائے گا اور جب تک ظاہری معنی مراد لینا ممکن ہو اس سے عدول نہیں کیا جائے گا۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” خبردار! غلو کرنے والے، حد سے بڑھنے والے ہلاک ہوئے۔ “ آپ صلی اللہ علیہ وسلم نے یہ بات تین بار فرمائی۔","f2":"قرآن وحدیث کے عام فہم معنی پر عمل کرنا واجب ہے۔بال کی کھال اتارنا اور دوردراز کی کوڑیان لانا اور لا یعنی تکلفات میں پڑنا یا دوسروں کو اس میں مبتلا کرنا دین نہیں ہے"}],[4609,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص دوسروں کو نیک عمل کی دعوت دیتا ہے تو اس کی دعوت سے جتنے لوگ ان نیک باتوں پر عمل کرتے ہیں ان سب کے برابر اس دعوت دینے والے کو بھی ثواب ملتا ہے، اور عمل کرنے والوں کے ثواب میں سے کوئی کمی نہیں کی جاتی، اور جو کسی گمراہی و ضلالت کی طرف بلاتا ہے تو جتنے لوگ اس کے بلانے سے اس پر عمل کرتے ہیں ان سب کے برابر اس کو گناہ ہوتا ہے اور ان کے گناہوں میں (بھی) کوئی کمی نہیں ہوتی\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو راہ حق کی دعوت دے اسے اس قدر ثواب ہے جس قدر اس کی اتباع کرنے والوں کو ہو گا۔ ان اتباع کرنے والوں میں سے کسی کے ثواب میں کوئی کمی نہیں ہو گی۔ اور جس نے کسی گمراہی کی دعوت دی تو اسے اس قدر گناہ ہو گا جس قدر اس کی پیروی کرنے والوں کو ہو گا۔ اس وجہ سے ان کے گناہوں میں کوئی کمی نہ ہو گی۔ “","f2":"دعوت دینے کا مفہوم بالعموم زبانی دعوت دینا سمجھاجاتا ہے حالانکہ اس کے ساتھ ساتھ ایک خاموش دعوت بھی ہوتی ہے کہ لوگ دوسروں کو دیکھ کر بہت سے کام شروع کردیتے ہیں لہذا انسان کو متنبہ ہونا چاہیے کہ وہ اپنے ماحول میں کیا کردار ادا کر رہا ہے۔کیا وہ اپنے لیے نیکیاں جمع کر رہا ہے۔کیا وہ اپنے لیے نیکیاں جمع کر رہا ہے یا لوگوں کی برائیاں اس کے کھاتے میں پڑرہی ہیں۔اس حدیث میں اصحاب خیر کے لیے بشارت اور بد عمل اور بد کردار لوگوں کے لیے بڑی تنبیہ ہے۔"}],[4610,"سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمانوں کے حق میں سب سے بڑا مجرم وہ مسلمان ہے جو ایسی چیز کے بارے میں سوال کرے جو حرام نہیں کی گئی تھی لیکن اس کے سوال کرنے کی وجہ سے مسلمانوں پر حرام کر دی گئی۱؎\"۔\n§وضاحت\n۱؎ : سوال دو طرح کا ہوتا ہے : ایک تو وہ جس کی ضرورت ہے اور معلوم نہیں تو آدمی کے جاننے کے لئے پوچھنا درست ہے، دوسرا وہ جس کی نہ حاجت ہے نہ ضرورت، آدمی بلا ضرورت یونہی خیالی و فرضی سوال کرے اور ناحق پریشان کرے، اور اس کے سوال کے سبب وہ حرام کر دی جائے، اس حدیث میں اسی قسم کے سوال کو سب سے بڑا جرم قرار دیا گیا ہے، آج کل بعض لوگ علماء سے یونہی بلا ضرورت یا بطور امتحان سوال کیا کرتے ہیں ان کو ڈرنا چاہئے۔","صحیح",{"u2":"جناب عامر بن سعد اپنے والد (سیدنا سعد بن ابی وقاص رضی اللہ عنہ) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مسلمانوں میں جرم کے اعتبار سے سب سے بڑا (مجرم) وہ مسلمان ہے جس نے کسی ایسی بات کے بارے میں سوال کیا جو پہلے حرام نہ تھی، مگر اس کے سوال کرنے کے باعث حرام کر دی گئی۔ “","f2":"دین کے احکام جس طرح ایک عام آدمی کی سمجھ میں آسکتے ہیں اسی طرح ان پر عمل کرنا چاہیے۔اطاعت کے لیے یہ کافی ہے۔خود ان احکام کے اندر مختلف پہلوؤں کو نکال کر سوال کرنے میں کئی قباحتیں ہیں۔بغیر ضرورتبال کی کھال اتانے سے اپنے اوردوسروں کے لیے سخت دشواریاں پیدا ہوتی ہیں ان سے احترازکرتے ہوئے صدق نیت سے آیات واحادیث کے سہل اور عام مفہوم پر عمل کرنا کافی ہے۔قرآن مجید میں بیان کیا گیا ہے کہ یہودیوں کو گائے ذبح کرنے کا حکم ملا۔انہوں نے کیسی کس رنگ کی کس طرح کی گائے کے حوالے سے سوال کرنے شروع کردیے۔ہر سوال سے گائے کی تخصیص ہوتی گئی اور اس طرح کی گائے ذبح کرنا مشکل سے مشکل تر ہوتا گیا۔اللہ تعالی نے اس طریقے کار کو یہود کے غلط طریق پر محمول فرمایا۔حکم ملتے ہی اگر وہ حسن نیت سے کوئی ایک گائے ذبح کردیتے تو اپنے فرض سے سبکدوش ہوجاتے۔بہت زیادہ سوالات کرنا کبھی بھی اچھا نہیں سمجھا گیا بالخصوص ایسے سوالات جن کا عملی زندگی سے واسطہ نہ ہو۔یا محض فرضی مسائل ہوں۔اب اگرچہ حلت وحرمت کا دورتو نہیں مگر علماء سے بھی لازمی اور ضروری سوالات ہی کرنے چاہییں جن کا تعلق حقیقت واقعہ سے ہو۔فرضی صورتیں سوچ سوچ کر ان کے جواب مانگنا یا تلاش کرنا غیر صحت مند رویہ ہے جس سے اسلام نے منع کیا ہے"}],[4611,"ابوادریس خولانی کہتے ہیں کہ یزید بن عمیرہ (جو معاذ بن جبل رضی اللہ عنہ کے شاگردوں میں سے تھے) نے انہیں خبر دی ہے کہ وہ جب بھی کسی مجلس میں وعظ کہنے کو بیٹھتے تو کہتے: اللہ بڑا حاکم اور عادل ہے، شک کرنے والے تباہ ہو گئے تو ایک روز معاذ بن جبل رضی اللہ عنہ کہنے لگے: تمہارے بعد بڑے بڑے فتنے ہوں گے، ان (دنوں) میں مال کثرت سے ہو گا، قرآن آسان ہو جائے گا، یہاں تک کہ اسے مومن و منافق، مرد و عورت، چھوٹے بڑے، غلام اور آزاد سبھی حاصل کر لیں گے، تو قریب ہے کہ کہنے والا کہے: لوگوں کو کیا ہو گیا ہے؟ میری پیروی نہیں کرتے، حالانکہ میں نے قرآن پڑھا ہے، وہ میری پیروی اس وقت تک نہیں کریں گے جب تک کہ میں ان کے لیے اس کے علاوہ کوئی نئی چیز نہ نکالوں، لہٰذا جو نئی چیز نکالی جائے تم اس سے بچو ۱؎ اس لیے کہ ہر وہ نئی چیز جو نکالی جائے گمراہی ہے، اور میں تمہیں حکیم و دانا کی گمراہی سے ڈراتا ہوں، اس لیے کہ بسا اوقات شیطان، حکیم و دانا شخص کی زبانی گمراہی کی بات کہتا ہے اور کبھی کبھی منافق بھی حق بات کہتا ہے۔ میں نے معاذ سے کہا: (اللہ آپ پر رحم کرے) مجھے کیسے معلوم ہو گا کہ حکیم و دانا گمراہی کی بات کہتا ہے، اور منافق حق بات؟ وہ بولے: کیوں نہیں، حکیم و عالم کی ان مشہور باتوں سے بچو، جن کے متعلق یہ کہا جاتا ہو کہ وہ یوں نہیں ہے، لیکن یہ چیز تمہیں خود اس حکیم سے نہ پھیر دے، اس لیے کہ امکان ہے کہ وہ (اپنی پہلی بات سے) پھر جائے اور حق پر آ جائے، اور جب تم حق بات سنو تو اسے لے لو، اس لیے کہ حق میں ایک نور ہوتا ہے۔ ابوداؤد کہتے ہیں: اس قصے میں معمر نے زہری سے «ولا يثنينك ذلك عنه» کے بجائے «ولا ينئينك ذلك عنه» روایت کی ہے اور صالح بن کیسان نے زہری سے اس میں«المشتهرات» کے بجائے «المشبهات» روایت کی ہے اور «ولا يثنينك» ہی روایت کی ہے جیسا کہ عقیل کی روایت میں ہے۔ ابن اسحاق نے زہری سے روایت کی ہے: کیوں نہیں، جب کسی حکیم و عالم کا قول تم پر مشتبہ ہو جائے یہاں تک کہ تم کہنے لگو کہ اس بات سے اس کا کیا مقصد ہے؟ (تو سمجھ لو کہ یہ حکیم و عالم کی زبانی گمراہی کی بات ہے) ۲؎۔\n§وضاحت\n۱؎ : جب وہ دیکھے گا کہ لوگ قرآن و سنت کو چھوڑ بیٹھے ہیں اور شیطان اور بدعت کے پیرو ہو رہے ہیں تو میں کیوں نہ کوئی بدعت ایجاد کروں، تو خبردار اس کی نکالی ہوئی بدعت سے بچتے رہو کیونکہ وہ گمراہی ہے۔ ۲؎ : آدمی اگر منصف اور حق پرست ہو تو اس پر باطل کی تاریکی و ظلمت کبھی نہیں چھپتی، معاذ رضی اللہ عنہ نے باطل کی نشانی یہ بیان کی کہ وہ قرآن وسنت میں نہ ہو، اور عقل سلیم بھی اس کو قبول نہ کرے، آپ نے عالم کے فتنے سے بھی ڈرایا کیونکہ عالم کا فتنہ بڑا سخت ہوتا ہے وہ جھوٹی باتوں، غلط استدلال اور چرب زبانی سے عوام کو فریفتہ کر لیتا ہے، آج یہی حال ہے، باطل پرست قرآن وسنت سے الگ ہٹ کر نئی نئی بدعتوں میں عوام کو پھنسائے ہوئے ہیں، اتفاق و اتحاد کو پارہ پارہ کر دیا ہے، اور لوگوں نے اپنے اپنے مولویوں کے ایجاد کئے ہوئے امور کو اسلام کا نام دے رکھا ہے، فتنے کے وقت میں طالب حق کو چاہئے کہ قرآن کو دیکھے اور صحیح احادیث میں تلاش کرے اور فرقہ بندی سے دور رہے۔","صحیح الإسناد",{"u2":"یزید بن عمیرہ سیدنا معاذ بن جبل کے ساتھیوں میں سے تھے۔ انہوں نے بتایا کہ سیدنا معاذ رضی اللہ عنہ جب بھی ذکر کی مجلس میں بیٹھتے تو ان کی زبان سے یہ الفاظ نکلتے: اللہ عزوجل خوب عادل اور فیصلہ کرنے والا ہے، شک کرنے والے ہلاک ہو گئے۔ سیدنا معاذ رضی اللہ عنہ نے ایک دین کہا: تمہارے بعد بڑے فتنے ہوں گے۔ مال بہت بڑھ جائے گا اور قرآن کھول (عام کر) دیا جائے گا حتیٰ کہ مومن، منافق، مرد، عورتیں، چھوٹا، بڑا، غلام اور آزاد سبھی اسے حاصل کریں گے اور ایسا ہو گا کہ کہنے والا کہے گا: لوگوں کو کیا ہوا میری پیروی نہیں کرتے، حالانکہ میں نے قرآن پڑھا ہے؟ (وہ کہے گا) یہ لوگ اس وقت تک میری پیروی نہیں کریں گے حتیٰ کہ میں ان کے لیے اس کے علاوہ کوئی نئی اختراع کروں۔ چنانچہ تم اپنے آپ کو اس کی بدعت سے بچائے رکھنا، اس کی بدعت ضلالت اور گمراہی ہو گی۔ اور میں تمہیں دانا بندے کی ٹھوکر سے بھی ڈراتا ہوں۔ شیطان کبھی دانا بندے کی زبان سے گمراہی کا کوئی کلمہ نکلوا دیتا ہے اور کبھی منافق بھی حق بات کہہ دیتا ہے۔ (یزید کہتے ہیں) میں نے سیدنا معاذ رضی اللہ عنہ سے کہا: اللہ آپ پر رحم فرمائے! مجھے کیسے معلوم ہو کہ دانا آدمی گمراہی کا کلمہ کہہ جاتا ہے اور منافق حق کی بات کہہ دیتا ہے؟ کہا کہ ہاں۔ دانا کی ایسی باتوں سے بچنا جو مشہور ہو جاتی ہیں، جن کے بارے میں کہا جاتا ہے کہ یہ کیا ہے؟ مگر یہ بات تمہارا اس سے رخ موڑ لینے کا باعث نہ بنے، ایسا (بھی تو) ہو سکتا ہے کہ وہ اس سے رجوع کر لے، اور حق جس کسی سے بھی سنو قبول کر لو، بلاشبہ حق پر نور ہوتا ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ معمر نے بواسطہ زہری اس روایت میں «يثنينك» کی بجائے «ولا ينئينك» ” یہ بات تجھے اس سے بے رخ نہ بنا دے۔ “ کے لفظ روایت کیے ہیں۔ صالح بن کیسان نے زہری سے روایت کرتے ہوئے «مشتهرات» کی بجائے «المشبهات» کا لفظ روایت کیا اور ایسے ہی «لا يثنينك» کا لفظ روایت کیا جیسے کہ عقیل نے روایت کیا ہے۔ ابن اسحاق نے زہری سے روایت کرتے ہوئے کہا: ہاں دانا کی جو بات تمہارے لیے شبہے کا باعث ہو حتیٰ کہ تم کہنے لگو نامعلوم اس نے اس کلمہ سے کیا مراد لیا ہے؟","f2":"1۔بعض اوقات دانا لوگ بھی کسی چیز کے فہم میں صحیح اور اعتدال کی راہ سے دور ہوسکتے ہیں۔ان کے ایسے اقوال امت کے لیے تعجب خیزہوتے ہیں۔ایسے اقوال کو چھوڑدیں لیکن ان کی صحیح باتوں کو مسترد کرنا شروع نہ کریں۔\n2۔داعی حق کو چاہیے ہمیشہ حکمت ودانائی کے ساتھ خالص قرآن اور صحیح سبت کا پیغام پہنچانے ہی کو اپنا مطمح نظر بنائے۔جب اس کی بات کتاب وسنت کے مطابق ہوتو بغیر اس فکر کےکہ لوگ اسے قبول کرتے ہیں یا نہیں یا کس قدر کرتے ہیں اپنا فرض ادا کرے۔اللہ عزوجل علیہم و خبیرہے اور مخلوقات کے دل اس کے ہاتھ میں ہیں بدعات سے ہر ایک کو دور بھاگنا چاہیے۔ان کا انجام ضلالت اور ہلاکت کے سوا کچھ نہیں۔\n3۔نبی صلی اللہ علیہ وسلم کے بعد کوئی کتنا ہی دانا کیوں نہ ہو وہ فی ذاتہ کسی طرح شرعی حجت اور دلیل نہیں۔اس کی بات قرآن وسنت کی کسوٹی پر جانچ کرہی قابل قبول ہوسکتی ہے"}],[4612,"سفیان ثوری کہتے ہیں کہ ایک شخص نے خط لکھ کر عمر بن عبدالعزیز سے تقدیر کے بارے میں سوال کیا تو انہوں نے (جواب میں) لکھا: امابعد! میں تمہیں اللہ سے ڈرنے اور اس کے دین کے سلسلہ میں میانہ روی اختیار کرنے، اس کے نبی کی سنت کی پیروی کرنے کی اور بدعتیوں نے جو بدعتیں سنت کے جاری اور ضروریات کے لیے کافی ہو جانے کے بعد ایجاد کی ہیں ان کے چھوڑ دینے کی وصیت کرتا ہوں، لہٰذا تم پر سنت کا دامن تھامے رہنا لازم ہے، اللہ کے حکم سے یہی چیز تمہارے لیے گمراہی سے بچنے کا ذریعہ ہو گی۔ پھر یہ بھی جان لو کہ لوگوں نے کوئی بدعت ایسی نہیں نکالی ہے جس کے خلاف پہلے سے کوئی دلیل موجود نہ رہی ہو یا اس کے بدعت ہونے کے سلسلہ میں کوئی نصیحت آمیز بات نہ ہو، اس لیے کہ سنت کو جس نے جاری کیا ہے، (اللہ تعالی یا نبی اکرم صلی اللہ علیہ وسلم) وہ جانتا تھا کہ اس کی مخالفت میں کیا وبال ہے، کیا کیا غلطیاں، لغزشیں، حماقتیں اور انتہا پسندیاں ہیں (ابن کثیر کی روایت میں «من قد علم» کا لفظ نہیں ہے) لہٰذا تم اپنے آپ کو اسی چیز سے خوش رکھو جس سے قوم (سلف) نے اپنے آپ کو خوش رکھا ہے، اس لیے کہ وہ دین کے بڑے واقف کار تھے، جس بات سے انہوں نے روکا ہے گہری بصیرت سے روکا ہے، انہیں معاملات کے سمجھنے پر ہم سے زیادہ دسترس تھی، اور تمام خوبیوں میں وہ ہم سے فائق تھے، لہٰذا اگر ہدایت وہ ہوتی جس پر تم ہو تو اس کا مطلب یہ ہوا کہ تم ان سے آگے بڑھ گئے، اور اگر تم یہ کہتے ہو کہ جن لوگوں نے بدعتیں نکالی ہیں وہ اگلے لوگوں کی راہ پر نہیں چلے اور ان سے اعراض کیا تو واقعہ بھی یہی ہے کہ اگلے لوگ ہی فائق و برتر تھے انہوں نے جتنا کچھ بیان کر دیا ہے اور جو کچھ کہہ دیا ہے شافی و کافی ہے، لہٰذا اب دین میں نہ اس سے کم کی گنجائش ہے نہ زیادہ کی، اور حال یہ ہے کہ کچھ لوگوں نے اس میں کمی کر ڈالی تو وہ جفا کار ٹھہرے اور کچھ لوگوں نے زیادتی کی تو وہ غلو کا شکار ہو گئے، اور اگلے لوگ ان دونوں انتہاؤں کے بیچ سیدھی راہ پر رہے، اور تم نے ایمان بالقدر کے اقرار کے بارے میں بھی پوچھا ہے تو باذن اللہ تم نے یہ سوال ایک ایسے شخص سے کیا ہے جو اس کو خوب جانتا ہے، ان لوگوں نے جتنی بھی بدعتیں ایجاد کی ہیں ان میں اثر کے اعتبار سے ایمان بالقدر کے اقرار سے زیادہ واضح اور ٹھوس کوئی نہیں ہے، اس کا تذکرہ تو جاہلیت میں جہلاء نے بھی کیا ہے، وہ اپنی گفتگو اور اپنے شعر میں اس کا تذکرہ کرتے تھے، اس کے ذریعے وہ اپنے آپ کو کسی فوت ہو جانے والے کے غم میں تسلی دیتے ہیں۔ پھر اسلام نے اس خیال کو مزید پختگی بخشی، رسول اللہ صلی اللہ علیہ وسلم نے اس کا ذکر ایک یا دو حدیثوں میں نہیں بلکہ کئی حدیثوں میں کیا، اور اس کو مسلمانوں نے آپ صلی اللہ علیہ وسلم سے سنا، پھر آپ کی زندگی میں بھی اسے بیان کیا اور آپ صلی اللہ علیہ وسلم کی وفات کے بعد بھی، اس پر یقین کر کے، اس کو تسلیم کر کے اور اپنے کو اس سے کمزور سمجھ کے، کوئی چیز ایسی نہیں جس کو اللہ کا علم محیط نہ ہو، اور جو اس کے نوشتہ میں نہ آ چکی ہو، اور اس میں اس کی تقدیر جاری نہ ہو چکی ہو، اس کے باوجود اس کا ذکر اس کی کتاب محکم میں ہے، اسی سے لوگوں نے اسے حاصل کیا، اسی سے اسے سیکھا۔ اور اگر تم یہ کہو: اللہ نے ایسی آیت کیوں نازل فرمائی؟ اور ایسا کیوں کہا (جو آیات تقدیر کے خلاف ہیں) ؟ تو (جان لو) ان لوگوں نے بھی اس میں سے وہ سب پڑھا تھا جو تم نے پڑھا ہے لیکن انہیں اس کی تاویل و تفسیر کا علم تھا جس سے تم ناواقف ہو، اس کے بعد بھی وہ اسی بات کے قائل تھے: ہر بات اللہ کی تقدیر اور اس کے لکھے ہوئے کے مطابق ہے جو مقدر میں لکھا ہے وہ ہو گا، جو اللہ نے چاہا، وہی ہوا، جو نہیں چاہا، نہیں ہوا۔ اور ہم تو اپنے لیے نہ کسی ضرر کے مالک ہیں اور نہ ہی کسی نفع کے پھر اس اعتقاد کے بعد بھی اگلے لوگ اچھے کام کرتے رہے اور بر ے کاموں سے ڈرتے رہے ۱؎۔\n§وضاحت\n۱؎ : عمر بن عبدالعزیز رحمہ اللہ کے اس جواب سے بدعت اور سنت کی راہ بالکل واضح ہو گئی اور یہ بات بھی صاف ہو گئی کہ کسی بھی عمل سے پہلے قرآن و سنت کو دیکھنا چاہئے، اگر ان میں نہ ملے تو صحابہ کرام اور تابعین عظام کو دیکھنا چاہئے کہ ان کا عمل اس پر تھا یا نہیں، اگر ہم اس معیار کو اختیار کر لیں تو اللہ کے فضل سے سارے اختلافات دور ہو جائیں اور بے شمار بدعات ہمیشہ کے لئے دم توڑ جائیں، لیکن ہم نے بعد کے لوگوں کی روش کو اپنا رکھا ہے اور بدعات کی گرم بازاری میں مگن ہیں۔","صحیح",{"u2":"ابورجاء نے ابوصلت سے روایت کیا کہ ایک شخص نے سیدنا عمر بن عبدالعزیز رضی اللہ عنہ کو خط لکھا۔ جس میں اس نے ان سے تقدیر کا مسئلہ دریافت کیا، تو انہوں نے جواب لکھا: حمد و صلاۃ کے بعد، میں تمہیں وصیت کرتا ہوں کہ اللہ کا تقویٰ اختیار کیے رہو اور اللہ کے امر میں اعتدال سے کام لو۔ اللہ کے نبی کی سنت کا اتباع کرو اور بدعتیوں کی بدعات سے دور رہو بالخصوص جب امر دین میں آپ صلی اللہ علیہ وسلم کی سنت جاری ہو چکی اور اس میں لوگوں کی ضرورت پوری ہو چکی۔ سنت کو لازم پکڑو یقیناً یہی چیز باذن اللہ تمہارے لیے (گمراہی سے) بچنے کا سبب ہو گی۔ یاد رکھو! لوگوں نے جس قدر بھی بدعات نکالی ہیں، ان سے پہلے وہ رہنمائی آ چکی جو ان (بدعات) کے خلاف دلیل ہے۔ یا اس میں کوئی نہ کوئی عبرت ہے۔ بلاشبہ سنت اس مقدس ذات نے عطا فرمائی جنہیں علم تھا کہ اس کی مخالفت میں کیا، راوی محمد بن کثیر نے «من قد علم» کے لفظ روایت نہیں کیے۔ خطا ٹھوکر اور حماقت اور (ہلاکت کی) کھائی ہے۔ لہٰذا اپنے آپ کو اس چیز پر راضی اور مطمئن رکھو جس پر قوم (صحابہ) راضی رہے ہیں، بلاشبہ وہ لوگ علم سے بہرہ ور تھے۔ (جن باتوں سے انہوں نے منع کیا) گہری بصیرت کی بنا پر منع کیا اور ان حقائق کی آگہی پر (جن سے تم بزعم خویش آگاہ ہوئے ہو) وہ لوگ زیادہ قادر تھے اور اپنے فضائل کی بنا پر اس کے زیادہ حقدار تھے۔ اگر حق و ہدایت یہی ہو جسے تم نے سمجھا ہے تو تم گویا ان سے سبقت لے گئے۔ اگر تم یہ کہو کہ یہ امور ان (صحابہ) کے بعد نئے ایجاد ہوئے ہیں تو ان کے ایجاد کرنے والے ان (صحابہ) کی راہ پر نہیں ہیں، بلکہ ان سے اعراض کرنے والے ہیں۔ بلاشبہ وہ صحابہ ہی (حق اور نیکی میں) سبقت لے جانے والے تھے۔ انہوں نے ان امور میں جو بات کی وہی کافی ہے۔ جو بیان کیا اسی میں شفا ہے۔ چنانچہ ان سے کم تر پر رکنا کوتاہی (تفریط) ہے اور ان سے بڑھ کر توضیح کرنا زیادتی یا تھکاوٹ (افراط) ہے (ان کے طرز عمل سے کمی کرنا جائز ہے، نہ ان سے بڑھنا جائز) جنہوں نے کمی کی انہوں نے ظلم کیا اور جو آگے بڑھے انہوں نے غلو کیا۔ جبکہ وہ (صحابہ) ان کے بین بین (اصل) ہدایت اور راہ مستقیم پر تھے۔ تم نے تقدیر کے اقرار کے متعلق لکھ کر پوچھا ہے تو اللہ کے فضل سے تم نے ایک صاحب علم و خبر سے پوچھا ہے۔ میں نہیں جانتا کہ لوگوں نے جتنی بھی نئی باتیں گھڑی ہیں اور جتنی بھی بدعات ایجاد کی ہیں ان میں تقدیر کے مسئلے سے بڑھ کر بھی کوئی مسئلہ واضح اور دلائل کی رو سے قوی تر ہو، اس کا ذکر تو قدیم ترین ایام جاہلیت میں بھی ہوتا تھا، لوگ اپنی گفتگو اور اپنے اشعار میں اس کا ذکر کرتے تھے، جو چیز انہیں حاصل نہ ہو پاتی تھی، تقدیر کا ذکر کر کے اس سے تسلی پاتے تھے۔ پھر اسلام نے ان کے بعد میں عقیدہ تقدیر کو مزید (واضح اور) مستحکم کیا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے ایک دو نہیں، متعدد احادیث میں اس کا ذکر کیا ہے۔ مسلمانوں نے آپ سے سن کر آپ کی زندگی میں اور آپ کے بعد بھی اس کے بارے میں گفتگو کی۔ جس میں اللہ رب العزت کے سامنے تسلیم و رضا اور اپنے عجز کا اعتراف کیا کہ کوئی چیز ایسی نہیں جس پر اللہ کا علم محیط نہ ہو، یا کتاب تقدیر میں اس کا شمار نہ ہو، یا اس میں اس کی تقدیر جاری نہ ہوئی ہو۔ ساتھ ہی یہ بات اس کی محکم کتاب (قرآن حکیم) میں بھی ہے۔ صحابہ کرام نے اس مسئلہ کو اسی سے اخذ کیا تھا اور یہیں سے وہ اس سے باخبر ہوئے۔ اگر تم کہو اللہ نے فلاں آیت کیوں نازل کی اور اس طرح کیوں کہا؟ تو (ذرا سوچو کہ) انہوں (یعنی صحابہ) نے بھی تو یہی آیات پڑھیں جو تم نے پڑھیں۔ البتہ وہ اس کی تفسیر و تاویل پا گئے جس سے تم جاہل رہے۔ اس کے بعد ان کا قول یہ ہے کہ یہ سب اللہ کی طرف سے لکھا ہوا اور اس کی تقدیر سے ہے۔ شقاوت اور بدبختی بھی لکھی ہوئی ہے۔ جو کچھ مقدر ہے، ہو جاتا ہے۔ اللہ جو بھی چاہتا ہے ہوتا ہے اور جو نہیں چاہتا نہیں ہوتا۔ ہم اپنے نفع اور نقصان کے مالک نہیں ہیں۔ پھر (اسی اصل پر) وہ اللہ کی طرف راغب رہے اور اسی سے ڈرتے رہے۔"}],[4613,"نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما کا ایک شامی دوست تھا جو ان سے خط و کتابت رکھتا تھا، تو عبداللہ بن عمر نے اسے لکھا کہ مجھے معلوم ہوا ہے کہ تم نے تقدیر کے سلسلے میں (سلف کے قول کے خلاف) کوئی بات کہی ہے، لہٰذا اب تم مجھ سے خط و کتابت نہ رکھنا، اس لیے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"میری امت میں کچھ ایسے لوگ ہوں گے جو تقدیر کو جھٹلائیں گے\"۔","حسن",{"u2":"جناب نافع بیان کرتے ہیں کہ شام میں سیدنا عبداللہ بن عمر رضی اللہ عنہ کا ایک دوست تھا، جس کی ان سے خط کتابت رہتی تھی۔ سیدنا عبداللہ رضی اللہ عنہ نے اس کو لکھا: مجھے یہ خبر پہنچی ہے کہ تو نے تقدیر کے بارے میں کوئی باتیں کی ہیں۔ (تو تقدیر کو جھٹلاتا ہے) لہٰذا آئندہ کے لیے مجھے کوئی خط نہ لکھنا۔ بلاشبہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ صلی اللہ علیہ وسلم فرماتے تھے ” تحقیق میری امت میں ایسے لوگ پیدا ہوں گے جو تقدیر کو جھٹلائیں گے۔“","f2":"حضرت عبد اللہ رضی اللہ عنہ کا یہ مقاطعہ(اعلان لاتعلقی) بغض فی اللہ کا اظہار تھا اور بلاشبہ اہل ایمان کی دوستی اور ناراضی اور اس کے دین کے ساتھ وابستہ رہنے کی بنیاد ہی پر ہوتی ہے۔"}],[4614,"خالد الحذاء کہتے ہیں کہ میں نے حسن (حسن بصری) سے کہا: اے ابوسعید! آدم کے سلسلہ میں مجھے بتائیے کہ وہ آسمان کے لیے پیدا کئے گئے، یا زمین کے لیے؟ آپ نے کہا: نہیں، بلکہ زمین کے لیے، میں نے عرض کیا: آپ کا کیا خیال ہے؟ اگر وہ نافرمانی سے بچ جاتے اور درخت کا پھل نہ کھاتے، انہوں نے کہا: یہ ان کے بس میں نہ تھا، میں نے کہا: مجھے اللہ کے فرمان «ما أنتم عليه بفاتنين * إلا من هو صال الجحيم» \"شیاطین تم میں سے کسی کو اس کے راستے سے گمراہ نہیں کر سکتے سوائے اس کے جو جہنم میں جانے والا ہو\"(الصافات: ۱۶۳) کے بارے میں بتائیے، انہوں نے کہا: \"شیاطین اپنی گمراہی کا شکار صرف اسی کو بنا سکتے ہیں جس پر اللہ نے جہنم واجب کر دی ہے\"۔","حسن الإسناد",{"u2":"جناب خالد الحذاء رضی اللہ عنہ کہتے ہیں کہ میں نے جناب حسن بصری رضی اللہ عنہ سے کہا: ابوسید! مجھے یہ بتائیں کہ سیدنا آدم علیہ السلام آسمان کے لیے پیدا کیے گئے تھے یا زمین کے لیے؟ انہوں نے کہا: زمین کے لیے۔ میں نے کہا: کیا خیال ہے اگر وہ گناہ سے بچ جاتے اور درخت سے نہ کھاتے تو؟ کہا: یہ ان کے لیے ممکن ہی نہ تھا (کیونکہ یہ مقدر تھا۔) میں نے کہا اللہ تعالیٰ کے اس فرمان کا کیا مفہوم ہے (جو جنات اور شیاطین کے متعلق فرمایا) &laquo; أنتم عليه بفاتنين * إلا من هو صال الجحيم&raquo; &rdquo; تم کسی کو اللہ کی طرف سے نہیں پھیر (بہکا) سکتے ہو، مگر اسے ہی جو جہنم میں پڑنے والا ہو۔) کہا کہ شیاطین اپنی گمراہی سے صرف انہی کو گمراہ کرتے ہیں جن پر اللہ نے جہنم میں گرنا واجب کیا ہو.","f2":"1۔انکار تقدیر کا فتنہ سب سے پہلے بصرے میں شروع ہوا تھااور حضرت حسن بصری رحمہ اللہ معروف تابعی ہیں ان کے متعلق لوگوں کو شبہ ہوا کہ شاید وہ بھی تقدیر کے انکاری ہیں۔مگر ایسی کوئی بات نہ تھی۔امام ابو داؤد نے اگلی روایات میں ان پر سے اسی تہمت کا رد کیا ہے کہ وہ تقدیر پر پوری طرح ایمان رکھتے تھے۔ 2۔جہنم میں جانا واجب اس طرح کہ اللہ کو پہلے سے علم ہے کہ جہنم میں کس کو جابا ہے۔اس یقینی علم کو وجوب کہا گیا ہے"}],[4615,"حسن بصری سے اللہ تعالی کے قول «ولذلك خلقهم» \"اور اسی کے لیے انہیں پیدا کیا\" (سورۃ ھود: ۱۱۹) کے بارے میں روایت ہے، انہوں نے کہا: انہیں پیدا کیا اس (جنت) کے لیے اور انہیں پیدا کیا اس (جہنم) کے لیے ۱؎۔\n§وضاحت\n۱؎ : انہیں جنت کے لئے اور انہیں جہنم کے لئے پیدا کیا، اس کا یہ مطلب نہیں ہے کہ: اگر اللہ نہ لکھتا تو جن کو جہنم کے لئے لکھا وہ اچھے اعمال کر کے جنت میں چلے جاتے وبالعکس، بلکہ اس کا مطلب یہ ہے کہ جن لوگوں کو اس نے جہنم کے لئے پیدا کیا اگر ان کی تقدیر میں کچھ نہ لکھتا تو یہ ممکن نہ تھا کہ وہ جنت میں چلے جاتے، یہ لوگ چونکہ برے اعمال ہی کرنے والے تھے جو اللہ کو معلوم تھا (کیونکہ اس کا علم ماضی مستقبل حال کے لئے یکساں ہے) اس لئے اس نے اپنے علم کی بنیاد پر لکھا ایسا نہیں کہ لکھنے سے یہ لوگ مجبور ہو گئے۔","صحیح الإسناد",{"u2":"حسن بصری سے اللہ تعالیٰ کے قول &laquo;ولذلك خلقهم&raquo; &rdquo; اور اسی کے لیے انہیں پیدا کیا &ldquo; (سورۃ ھود: ۱۱۹) کے بارے میں روایت ہے، انہوں نے کہا: انہیں پیدا کیا اس (جنت) کے لیے اور انہیں پیدا کیا اس (جہنم) کے لیے.","f2":"اس کے لیے پیدا کیا کا مطلب بھی یہی ہے کہ پیدائش یا اس سے بھی پہلے اللہ کو علم ہے۔آخرت کا معاملہ صرف اور صرف اللہ عزوجل کے علم اور تقدیر پر ہی منحصر ہے"}],[4616,"خالد الخداء کہتے ہیں کہ میں نے حسن بصری سے کہا «ما أنتم عليه بفاتنين * إلا من هو صال الجحيم» تو انہوں نے کہا: «إلا من هو صال الجحيم» کا مطلب ہے: سوائے اس کے جس کے لیے اللہ نے واجب کر دیا ہے کہ وہ جہنم میں جائے۔","صحیح الإسناد",{"u2":"خالد الحذاء کہتے ہیں کہ میں نے سیدنا حسن بصری رضی اللہ عنہ سے آیت کریمہ «أنتم عليه بفاتنين * إلا من هو صال الجحيم» (کی تفسیر) کے متعلق دریافت کیا تو انہوں نے فرمایا کہ یہ اللہ تعالیٰ نے اسی کے لیے لازم کیا ہے جو جہنم میں جلنے والا ہوا۔ (یہ مذکورہ بالا روایت 4614 کی مانند ہے۔)"}],[4617,"حمید کہتے ہیں کہ حسن بصری کہتے تھے: آسمان سے زمین پر گر پڑنا اس بات سے مجھے زیادہ عزیز ہے کہ میں کہوں: معاملہ تو میرے ہاتھ میں ہے ۱؎۔\n§وضاحت\n۱؎ : حسن بصری رحمہ اللہ نے یہ بات صاف کر دی کہ تمام امور اللہ کے ہاتھ میں ہیں خیر و شر سب کا مالک و خالق وہی ہے۔","صحیح الإسناد",{"u2":"جناب حمید سے منقول ہے کہ سیدنا حسن بصری رضی اللہ عنہ کہا کرتے تھے کہ آسمان سے زمین پر گر پڑنا مجھے اس سے زیادہ پسند ہے کہ میں یوں کہوں کہ معاملہ میرے ہاتھ میں ہے۔ (مقصد یہ ہے کہ تقدیر کا انکار مجھے ہرگز ہرگز گوارا نہیں)"}],[4618,"حمید کہتے ہیں کہ حسن ہمارے پاس مکہ تشریف لائے تو اہل مکہ کے فقہاء نے مجھ سے کہا کہ میں ان سے درخواست کروں کہ وہ ان کے لیے ایک دن نشست رکھیں، اور وعظ فرمائیں، وہ اس کے لیے راضی ہو گئے تو لوگ اکٹھا ہوئے اور آپ نے انہیں خطاب کیا، میں نے ان سے بڑا خطیب کسی کو نہیں دیکھا، ایک شخص نے سوال کیا: اے ابوسعید! شیطان کو کس نے پیدا کیا؟ انہوں نے کہا: سبحان اللہ! کیا اللہ کے سوا کوئی اور خالق ہے؟ اللہ نے شیطان کو پیدا کیا اور اسی نے خیر پیدا کیا، اور شر پیدا کیا، وہ شخص بولا: اللہ انہیں غارت کرے، کس طرح یہ لوگ اس بزرگ پر جھوٹ باندھتے ہیں ۱؎۔\n§وضاحت\n۱؎ : ہمیشہ اہل بدعت کا یہ طریقہ رہا ہے کہ وہ موحدین اور صحیح عقیدہ والوں پر افتراءات باندھتے رہتے ہیں، کچھ لوگوں نے حسن بصری کے متعلق بھی اسی طرح کے بہتان لگائے تھے اسی کی طرف اشارہ ہے۔","صحیح",{"u2":"جناب حمید نے بیان کیا کہسیدنا حسن بصری رضی اللہ عنہ مکہ آئے تو وہاں کے علماء و فقہاء نے مجھ سے کہا کہ میں ان سے یہ کہوں کہ وہ ایک دن ہمیں وعظ سنائیں۔ تو انہوں نے قبول کر لیا۔ چنانچہ وہ جمع ہو گئے اور حسن بصری رضی اللہ عنہ نے درس دیا تو میں نے ان سے بڑھ کر کسی کو خطیب نہ پایا۔ ایک آدمی نے پوچھا: ابوسعید! شیطان کو کس نے پیدا کیا ہے؟ وہ کہنے لگے سبحان اللہ! بھلا اللہ کے سوا بھی کوئی خالق ہے؟ اللہ ہی نے شیطان کو پیدا کیا ہے۔ خیر اور شر کا خالق وہی ہے۔ تو وہ آدمی کہنے لگا: اللہ ان کو ہلاک کرے (نامعلوم) کس بنا پر وہ اس شیخ پر جھوٹ بولتے ہیں۔","f2":"خالق صرف اللہ تعالی ہے۔ہر چیز اس نے پیدا کی ہے۔اندھیرا نہ ہوتو نور کی پہچان ممکن نہیں۔شر نہ ہوتو خیر کی خوبی کیسے معلوم ہو"}],[4619,"حسن بصری آیت کریمہ: «كذلك نسلكه في قلوب المجرمين» \"اسی طرح سے ہم اسے مجرموں کے دل میں ڈالتے ہیں\" (سورۃ الحجر: ۱۱۲) کے سلسلہ میں کہتے ہیں: اس سے مراد شرک ہے۔","صحیح",{"u2":"جناب حمید الطویل نے سیدنا حسن بصری رضی اللہ عنہ سے روایت کیا کہ انہوں نے اس آیت کریمہ «كذلك نسلكه في قلوب المجرمين» ” ایسے ہی ہم یہ بات مجرموں کے دلوں میں ڈال دیتے ہیں۔ “ کی تفسیر میں کہا: اس سے مراد ” شرک “ ہے۔"}],[4620,"حسن بصری آیت کریمہ: «وحيل بينهم وبين ما يشتهون» \"ان کے اور ان کی خواہشات کے درمیان حائل ہو گئی\" (سورۃ سبا: ۵۴) کی تفسیر میں کہتے ہیں: اس کا مطلب ہے ان کے اور ان کے ایمان کے درمیان حائل ہو گئی۔","ضعیف الإسناد",{"u2":"عبید الصید، سیدنا حسن بصری رضی اللہ عنہ سے روایت کرتے ہیں کہ انہوں نے آیت کریمہ «وحيل بينهم وبين يشتهون» کی تفسیر میں کہا کہ ان کے اور ان کے ایمان لانے کی خواہش میں رکاوٹ کر دی جائے گی","f2":"آیت کریمہ کا مفہوم واضح ہے کہ آخرت میں کفار چاہیں گے کہ ان کا ایمان قبول کرلیا جائےاور عذاب سے ان کی نجات ہوجائے لیکن ان کے اور ان کی اس کواہچ کے درمیان پردہ حائل کردیا جائے گا۔یعنی اس کواہش کو رد کردیا جائے گا۔(احسن البیان)"}],[4621,"ابن عون کہتے ہیں کہ میں ملک شام میں چل رہا تھا تو ایک شخص نے پیچھے سے مجھے پکارا جب میں مڑا تو دیکھا رجاء بن حیوہ ہیں، انہوں نے کہا: اے ابوعون! یہ کیا ہے جو لوگ حسن کے بارے میں ذکر کرتے ہیں؟ میں نے کہا: لوگ حسن پر بہت زیادہ جھوٹ باندھتے ہیں۱؎۔\n§وضاحت\n۱؎ : حسن بصری رحمہ اللہ سے متعلق خصوصا جھوٹے صوفیوں نے بہت سا کفر و شرک گھڑ رکھا ہے، اعاذنااللہ۔","صحیح الإسناد",{"u2":"جناب ابن عون کہتے ہیں کہ میں ملک شام میں تھا کہ پیچھے سے کسی نے مجھ کو آواز دی۔ میں متوجہ ہوا تو دیکھا کہ جناب رجاء بن حیوہ تھے۔ انہوں نے کہا: ابو عون! یہ کیا باتیں ہیں جو لوگ حسن بصری کے متعلق کہہ رہے ہیں؟ میں نے کہا: یہ لوگ حسن پر بہت جھوٹ بول رہے ہیں۔"}],[4622,"ایوب کہتے ہیں حسن پر جھوٹ دو قسم کے لوگ باندھتے ہیں: ایک تو قدریہ، جو چاہتے ہیں کہ اس طرح سے ان کے خیال و نظریہ کا لوگ اعتبار کریں گے، اور دوسرے وہ لوگ جن کے دلوں میں ان کے خلاف عداوت اور بغض ہے، وہ کہتے ہیں: کیا یہ ان کا قول نہیں؟ کیا یہ ان کا قول نہیں؟ ۔","صحیح",{"u2":"ایوب نے بیان کیا کہ سیدنا حسن بصری رضی اللہ عنہ پر جھوٹ بولنے والے دو طرح کے لوگ ہیں۔ ایک وہ جو تقدیر کے منکر ہیں۔ ان کی خواہش ہے کہ اس طرح سے اپنی بات اور رائے کو شہرت دے لیں اور عام کر دیں۔ اور دوسرے وہ ہیں جن کے دلوں میں بغض اور عداوت ہے (اور اس طرح باتیں کرتے ہیں) کیا یہ اس کا قول نہیں، کیا اس نے اس طرح نہیں کہا ہے؟ وغیرہ۔","f2":"اہل ہوا کا دستور ہے کہ وہ اپنے نظریات کو پھیلانے کے لیے ان لوگوں کی طرف اپنی غلط باتیں منسوب کرتے ہین جن کا لوگ احترام کرتے ہیں اور جن پر اعتماد کرتے ہیں۔"}],[4623,"یحیی بن کثیر بن عنبری کہتے ہیں کہ قرہ بن خالد ہم سے کہا کرتے تھے: اے نوجوانو! حسن کو قدریہ مت سمجھو، ان کی رائے سنت اور صواب تھی۔","صحیح",{"u2":"جناب قرہ بن خالد ہم سے کہا کرتے تھے اے جوانو! حسن بصری کے بارے میں مغلوب نہ ہو جانا۔ بلاشبہ ان کی رائے سنت کے مطابق اور حق و صواب (کے تابع) تھی"}],[4624,"ابن عون کہتے ہیں کہ اگر ہمیں یہ معلوم ہوتا کہ حسن کی بات (غلط معنی کے ساتھ شہرت کے) اس مقام کو پہنچ جائے گی جہاں وہ پہنچ گئی تو ہم لوگ ان کے اس قول کے بارے میں ان کے رجوع کی بابت ایک کتاب لکھتے اور اس پر لوگوں کو گواہ بناتے، لیکن ہم نے سوچا کہ ایک بات ہے جو نکل گئی ہے اور اس کے خلاف معنی پر محمول نہیں کی جائے گی ۱؎۔\n§وضاحت\n۱؎ : حسن بصری رحمہ اللہ کے بہت سے اقوال کو لوگوں نے اپنی گمراہ کن بدعتوں کی موافقت میں ڈھال لیا جب کہ خود ان کا مقصد اس قول سے وہ نہیں تھا جو اہل بدعت نے گھڑ لیا، اسی کو ابن عون فرماتے ہیں کہ اگر یہ احساس ہوتا کہ آپ کی بات کو یہ لوگ غلط معنی پہنا کر لوگوں کو گمراہ کریں گے تو ہم حسن بصری سے اس کا غلط ہونا ثابت کرتے، ان سے پوچھتے، وہ جواب دیتے، اور ہم اس پر لوگوں کی گواہیاں بھی کراتے، مگر اس وقت اس کا احساس نہ تھا، اب ان کے بعد اہل بدعت نے سیکڑوں غلط باتیں ان سے منسوب کر رکھی ہیں جن سے وہ بری ہیں۔","صحیح مثلہ",{"u2":"ابن عون نے کہا اگر ہمیں یہ علم ہوتا کہ حسن بصری کی کہی ہوئی بات اس حد تک پہنچ جائے گی جہاں تک کہ پہنچی تو ہم ان کے رجوع کے متعلق ایک کتاب لکھتے اور اس پر گواہیاں قائم کرتے۔ لیکن ہم سمجھے کہ ایک بات تھی جو ہو گئی سو ہو گئی، مشہور نہ ہو گی۔"}],[4625,"ایوب کہتے ہیں کہ مجھ سے حسن بصری نے کہا: میں اب دوبارہ کبھی اس میں سے کوئی بات نہیں کہوں گا، (جس سے تقدیر کی نفی کا گمان ہوتا) ۔","صحیح",{"u2":"ایوب کہتے ہیں کہ جناب حسن بصری رضی اللہ عنہ نے مجھ سے کہا: میں آئندہ کبھی ایسی بات نہیں کہوں گا۔ (جس میں تقدیر کے انکار کا شبہ ہو۔)"}],[4626,"عثمان کہتے ہیں کہ حسن نے جب بھی کسی آیت کی تفسیر کی تو تقدیر کا اثبات کیا۔","صحیح",{"u2":"عثمان البتی بیان کرتے ہیں کہ حسن بصری رضی اللہ عنہ نے جب بھی (قرآن کریم کی) کسی آیت کی تفسیر کی تو اس میں تقدیر کے اثبات (اور اس پر ایمان) ہی کا ذکر کیا۔","f2":"۔حضرت حسن بن ابو الحسن (یسار)انصار کے آزاد کردہ غلام تھے اور اسی نسبت ولاء سے انصاری کہلاتے تھے۔مشہور صاحب علم وفضل فقیہ اور ثقہ محدث ہیں۔روایت حدیث میں قابل احترام ہیں۔محدثین میں تابعین کے تیسرے طبقے کے رئیس شمار ہوتے ہیں۔تقریباً نوے سال کی عمر پائی اور110 ہجری میں فوت ہوئے۔\n2۔بعض لوگ اصحاب علم کی بعض باتوں سے غلط مفہوم نکالنے کی کوشش کرتے ہیں۔اپنی طرف سے اضافے کرتے ہیں اور عوام کو بہکاتے ہیں۔جب کسی اہل علم کے ساتھ ایسا ہوتو اسے الفاظ کو دیکھنا چاہیے کہ اگر لوگوں نے ان سے فائدہ اٹھانے کی کوشش کی ہے تو اپنے الفاظ بدل لیں بلکہ واپس لےلیں۔جناب حسن بصری رحمہ اللہ نے یہی طرز عمل اکتیار فرمایا،\n3۔علمائے حق پر وارد کیے جانے والے التہامات لا ازالہ کرنا اور ان کی عزت وکرامت کا داع کرنا اخلاقی شرعی اور اسلامی حق ہے۔ان کا دفاع کرنے سے حق کا دفاع ہوتا ہے۔اگر اہل حق کی شہرت کو مجروح کردیں تو حق کی اشاعت میں بڑی رکاوٹ آجاتی ہے۔"}],[4627,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے زمانے میں کہا کرتے تھے: ہم ابوبکر رضی اللہ عنہ کے برابر کسی کو نہیں جانتے، پھر عمر رضی اللہ عنہ کے، پھر عثمان رضی اللہ عنہ کے، پھر نبی اکرم صلی اللہ علیہ وسلم کے صحابہ کو چھوڑ دیتے، ان میں کسی کو کسی پر فضیلت نہیں دیتے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ہم سیدنا ابوبکر رضی اللہ عنہ کے برابر کسی کو نہ کرتے تھے۔ پھر ان کے بعد سیدنا عمر رضی اللہ عنہ اور ان کے بعد سیدنا عثمان رضی اللہ عنہ (کا درجہ سمجھتے تھے) پھر نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں کوئی تفضیل نہ سمجھتے تھے (بلکہ سب کو مساوی سمجھتے تھے)۔","f2":"-"}],[4628,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی زندگی میں ہم لوگ کہا کرتے تھے کہ نبی اکرم صلی اللہ علیہ وسلم کی امت میں آپ صلی اللہ علیہ وسلم کے بعد سب سے افضل ابوبکر ہیں، پھر عمر، پھر عثمان ہیں، رضی اللہ عنہم اجمعین۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ ہم کہا کرتے تھے جبکہ رسول اللہ صلی اللہ علیہ وسلم حیات تھے: نبی کریم صلی اللہ علیہ وسلم کی امت میں آپ صلی اللہ علیہ وسلم کے بعد سب سے افضل ابوبکر ہیں، پھر عمر اور پھر عثمان رضی اللہ عنہ م۔ اللہ ان سب سے راضی ہو۔"}],[4629,"محمد بن حنفیہ کہتے ہیں کہ میں نے اپنے والد علی بن ابی طالب رضی اللہ عنہ سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم کے بعد لوگوں میں سب سے بہتر کون تھا؟ انہوں نے کہا: ابوبکر رضی اللہ عنہ، میں نے کہا: پھر کون؟ پھر عمر رضی اللہ عنہ، پھر مجھے اس بات سے ڈر ہوا کہ میں کہوں پھر کون؟ اور وہ کہیں عثمان رضی اللہ عنہ، چنانچہ میں نے کہا: پھر آپ؟ اے ابا جان! وہ بولے: میں تو مسلمانوں میں کا صرف ایک فرد ہوں ۱؎۔\n§وضاحت\n۱؎ : یہ علی رضی اللہ عنہ کی غایت درجہ تواضع و انکساری ہے ورنہ باجماع امت آپ عثمان غنی رضی اللہ عنہ کے بعد سب سے افضل ہیں۔","صحیح",{"u2":"(سیدنا علی رضی اللہ عنہ کے فرزند ارجمند) جناب محمد بن حنفیہ سے مروی ہے کہتے ہیں کہ میں اپنے والد سے دریافت کیا کہ رسول اللہ علیہ وسلم کے بعد افضل کون ہے؟انہو ں نے کہا حضرت ابو بکر رضی اللہ عنہ۔میں نے کہا:پھر کون؟کہا حضرت عمر رضی اللہ عنہ پھر مجھے اندیشہ ہوا اگر میں نے پوچھا ان کے بعد کون ہے تو وہ کہیں گئے حضرت عثمان رضی اللہ عنہ تو میں نے ازخود کہ دیا:‎پھر تو ‎ آپ ہو‎ں گئے ابا جان! وہ کہنے لگے کہ میں تو مسلمانوں میں سےایک عام آدمی ہوں۔","f2":"1۔اہل بیت کے افراد بھی اپنے طور پرحضرت ابوبکر اور حضرت عمر اور حضرت عثمان رضی اللہ عنہ کی افضلیت اور مسلمانوں میں ان کی شہرت سے بخوبی آگاہ تھےاور اقراری بھی جیسے کہ سیدنا علی رضی اللہ عنہ نے صراحت سے فرمایا۔\n2۔حضرت علی رضی اللہ عنہ ایک متواضع شخصیت تھے۔ان میں تکبر اور تعلی نہیں تھی۔\n3۔تفضیل صحابہ کے حوالے سے فطری طور پر لوگوں میں ایک احساس موجود تھا۔لیکن اس پر کوئی جھگڑا موجود نہ تھا۔بعد میں فتنہ پروازوں نے اپنے مقاصد کے حصول اور مسلمانوں میں تفرقہ اور جدال پیدا کرنے کے لیے اس عقائد سے تعلق رکھنے والا ایک اہم نزاعی موضوع بنالیا۔"}],[4630,"سفیان کہتے تھے: جو یہ کہے کہ علی رضی اللہ عنہ ان دونوں (ابوبکر رضی اللہ عنہ اور عمر رضی اللہ عنہ) سے خلافت کے زیادہ حقدار تھے تو اس نے ابوبکر، عمر، مہاجرین اور انصار کو خطاکار ٹھہرایا، اور میں نہیں سمجھتا کہ اس کے اس عقیدے کے ہوتے ہوئے اس کا کوئی عمل آسمان کو اٹھ کر جائے گا۔","صحیح الإسناد",{"u2":"جناب سفیان ثوری کہا کرتے تھے جس شخص کا یہ گمان ہو کہ سیدنا علی رضی اللہ عنہ، سیدنا ابوبکر رضی اللہ عنہ اور سیدنا عمر رضی اللہ عنہما کی نسبت خلافت کے زیادہ حقدار تھے تو اس نے سیدنا ابوبکر، سیدنا عمر، مہاجرین اور انصار رضی اللہ عنہم م کو غلطی پر سمجھا۔ اور میں نہیں سمجھتا کہ اس عقیدہ کے ہوتے ہوئے اس کا کوئی عمل آسمان کی طرف اٹھتا ہو۔","f2":"مہاجرین اور انصار اور کل صحابہ کرام رضی اللہ عنہم تمام طبقات انسانی میں وہ محترم طبقہ ہیں جن کو اللہ عزوجل نے اپنے نبی صلی اللہ علیہ وسلم کی صحبت اور اپنے دین کی نصرت کے لیے منتخب فرمایا۔تو ان سب کی اجتماعی رائے کوباطل کس طرح قرار دیا جاسکتا۔بلاشبہ نبی صلی اللہ علیہ وسلم کے بعد کوئی معصوم نہیں مگر کیا وہ اس قدر ہی گزرگئے تھے کہ اپنے اجتماعی معاملات کو راہ حق وصواب پر چلانے سے قاصر تھے۔حاشاوكلا!وہ یقیناً علم و فضل کی طرح فہم وفراست میں بھی سب سے افضل واعلی تھےاور انہی فضائل کی بناء پر اللہ عزوجل نے ان کی قرآن مجید میں مدح فرمائی ہے۔انہوں نے اپنی شوری سے جن کو اپنا قائد بنایاوہ صحیح معنی میں افضل ترین لوگ تھے۔"}],[4631,"سفیان ثوری کہا کرتے تھے خلفاء پانچ ہیں: ابوبکر رضی اللہ عنہ، عمر رضی اللہ عنہ، عثمان رضی اللہ عنہ، علی رضی اللہ عنہ اور عمر بن عبدالعزیز رحمہ اللہ۔","",{"u2":"جناب سفیان ثوری کہا کرتے تھے کہ خلفاء پانچ ہیں یعنی ابوبکر رضی اللہ عنہ، عمر رضی اللہ عنہ، عثمان رضی اللہ عنہ، علی رضی اللہ عنہ اور عمر بن عبدالعزیز رضی اللہ عنہ۔","f2":"روایت اگرچہ ضعیف ہے۔تاہم عمومی رائے یہی ہے کہ منہاج النبوۃ پر صحیح معنوں میں قائم خلفاء یہ پانچ تھے دیگرخلافتوں میں کچھ نہ کچھ انحراف آگیا تھا۔چنانچہ یہ واقعہ خلفائے اربعہ کے علاوہ عمر بن عبد العزیز رحمہ اللہ جو تابعی تھے لیکن اہل سنت والجماعۃ عمومی طور پر ان کو بھی خلیفہ راشد سمجھتی تھی کیونکہ سلیمان بن ملک کی طرف سے نامزدگی کو انہوں نے قبول نہ کیا اور لوگوں کو اپنی شوری کے ذریعے سے اپنا حکمران منتخب کرنے کا اختیار ویا۔لوگوں نے اپنی مرضی سے انہی کو منتخب کرنے کا اختیار دیا،لوگوں نے اپنی مرضی سے انہی کو امیر المومنین منتخب کیا۔پھر انہوں نے دیگر خلفائے راشدین کی طرح معاملات حکومت بالکل قرآن وسنت کے مطابق چلائے اس لیے وہ بھی بجا طور پر خلیفہ راشد ہیں۔ حضرت حسن بصری رحمہ اللہ سات مہینے تک خلیفہ رہے۔ان کا یہ دور پہلی خلافت راشدہ کا حصہ ہے۔"}],[4632,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ابوہریرہ رضی اللہ عنہ بیان کرتے تھے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: میں نے رات کو بادل کا ایک ٹکڑا دیکھا، جس سے گھی اور شہد ٹپک رہا تھا، پھر میں نے لوگوں کو دیکھا وہ اپنے ہاتھوں کو پھیلائے اسے لے رہے ہیں، کسی نے زیادہ لیا کسی نے کم، اور میں نے دیکھا کہ ایک رسی آسمان سے زمین تک لٹکی ہوئی ہے، پھر میں نے آپ کو دیکھا اللہ کے رسول! کہ آپ نے اسے پکڑ ا اور اس سے اوپر چلے گئے، پھر ایک اور شخص نے اسے پکڑا اور وہ بھی اوپر چلا گیا، پھر ایک اور شخص نے اسے پکڑا اور وہ بھی اوپر چلا گیا، پھر اسے ایک اور شخص نے پکڑا تو وہ ٹوٹ گئی پھر اسے جوڑا گیا، تو وہ بھی اوپر چلا گیا۔ ابوبکر رضی اللہ عنہ نے کہا: میرے ماں باپ آپ پر قربان جائیں مجھے اس کی تعبیر بیان کرنے دیجئیے آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی تعبیر بیان کرو\" وہ بولے: بادل کے ٹکڑے سے مراد اسلام ہے، اور ٹپکنے والے گھی اور شہد سے قرآن کی حلاوت (شیرینی)اور نرمی مراد ہے، کم اور زیادہ لینے والوں سے مراد قرآن کو کم یا زیادہ حاصل کرنے والے لوگ ہیں، آسمان سے زمین تک پہنچی ہوئی رسی سے مراد حق ہے جس پر آپ ہیں، آپ اسے پکڑے ہوئے ہیں، اللہ آپ کو اٹھا لے گا، پھر آپ صلی اللہ علیہ وسلم کے بعد ایک اور شخص اسے پکڑے گا تو وہ بھی اٹھ جائے گا، پھر ایک اور شخص پکڑے گا تو وہ بھی اٹھ جائے گا، پھر اسے ایک اور شخص پکڑے گا، تو وہ ٹوٹ جائے گی تو اسے جوڑا جائے گا، پھر وہ بھی اٹھ جائے گا، اللہ کے رسول! آپ مجھے بتائیے کہ میں نے صحیح کہا یا غلط، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کچھ صحیح کہا اور کچھ غلط\" کہا: اللہ کے رسول! میں آپ کو قسم دلاتا ہوں کہ آپ مجھے بتائیے کہ میں نے کیا غلطی کی، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"قسم نہ دلاؤ\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے بیان کیا کہ سیدنا ابوہریرہ رضی اللہ عنہ کہا کرتے تھے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: میں نے آج رات خواب میں دیکھا ہے کہ ایک بادل سے گھی اور شہد ٹپک رہا ہے۔ میں نے لوگوں کو دیکھا کہ وہ اپنی ہتھیلیاں پھیلائے ہوئے تھے ‘ تو کچھ نے ان سے خوب خوب لیا اور کچھ نے کم لیا۔ اور میں نے ایک رسی دیکھی جو آسمان سے زمین تک لٹکی ہوئی ہے، اے اللہ کے رسول! آپ کو دیکھا کہ آپ نے اس کو پکڑا ہے اور اوپر چڑھ گئے ہیں۔ پھر ایک دوسرے آدمی نے اسے پکڑا وہ بھی اوپر چڑھ گیا۔ پھر ایک اور آدمی نے اسے پکڑا اور اوپر چڑھ گیا۔ پھر ایک اور آدمی نے اسے پکڑا تو وہ ٹوٹ گئی۔ پھر جوڑ دی گئی تو وہ اوپر چڑھ گیا۔ پس سیدنا ابوبکر رضی اللہ عنہ نے کہا: میرے ماں باپ آپ پر قربان! مجھے اجازت دیجئیے کہ میں اس کی تعبیر عرض کروں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کی تعبیر بیان کرو۔ “ تو انہوں نے کہا: وہ بادل ‘ اسلام کا سایہ ہے اور اس سے ٹپکنے والا گھی اور شہد، قرآن کی ملائمت اور شیرینی ہے۔ زیادہ یا کم لینے والے، تو وہ وہی ہیں جو قرآن سے اپنا حصہ زیادہ لے رہے ہیں یا کم۔ اور آسمان سے لٹکنے والی رسی، وہی حق ہے جس پر آپ صلی اللہ علیہ وسلم ہیں۔ آپ نے اسے پکڑا ہے تو اللہ آپ کو بلند فرمائے گا۔ پھر آپ کے بعد ایک آدمی پکڑے گا اور اس کے ذریعے سے اوپر چڑھ جائے گا۔ اس کے بعد دوسرا آدمی پکڑے گا تو وہ بھی اوپر چڑھ جائے گا۔ پھر تیسرا آدمی پکڑے گا تو وہ ٹوٹ جائے گی، پھر اسے اس کی خاطر جوڑ دیا جائے گا۔ تو پھر وہ اوپر چڑھ جائے گا۔ اے اللہ کے رسول! مجھے ضرور بتائیں کہ میں نے درست کہا: ہے یا غلط؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم نے کچھ درست کہا ہے اور کچھ میں غلطی کی ہے۔ “ انہوں نے کہا: اے اللہ کے رسول! میں آپ کو قسم دے کر کہتا ہوں مجھے ضرور بتائیں کہ میں نے کیا غلطی کی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” قسم مت دو۔ “","f2":"1۔سچے اور عمدہ خواب مومن کے لیے نبوت کا چھیالیسواں حصہ قرار دیے گئے ہیں اور ان کے ذریعے سے بندے کو بعض امور کی اطلاع یا بعض امور سے متنبہ کیا جاتا ہے۔\n2۔مذکورہ بالا خواب میں خلا فت نبوت کی طرف اشارہ تھا۔جسے کہ سیدنا حضرت ابوبکر صدیق رضی اللہ عنہ بجا طور پر سمجھ گئے تھے۔اس میں غلطی کیا تھی؟تو اس کے در پے ہونا قطعاً روا نہیں۔جب رسول اللہ صلی اللہ علیہ وسلم نے صراحت نہیں فرمائی تو کسی اور کو کیا حق پہنچتا ہےکہ ظن و تخمیم سے کوئی بات کہے۔\n3۔کسی کو لفظ قسم کے ساتھ قسم دینے سے اس کی تعمیل واجب نہیں ہوجاتی۔\n4۔کسی تلمیذ یا ادنی کو جائز ہے کہ اپنے شیخ یا بڑے کے ہوتے ہوئے اس کی اجازت سے کسی سوال کا جواب دے یا اس پر بحث کرے۔یہ خلاف ادب شمار نہیں ہوگا۔بلا اجازت بولنا البتہ بے ادبی ہوگی۔"}],[4633,"اس سند سے بھی ابن عباس رضی اللہ عنہما سے یہی قصہ مرفوعاً مروی ہے لیکن اس میں یہ ہے کہ آپ نے ان کو بتانے سے انکار کر دیا،(کہ انہوں نے کیا غلطی کی ہے) ۔","ضعیف الإسناد",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے یہ مذکورہ بالا قصہ بیان کیا، کہا کہ آپ صلی اللہ علیہ وسلم نے (غلطی کی وضاحت کرنے سے) انکار فر دیا۔"}],[4634,"ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک دن فرمایا: \"تم میں سے کسی نے خواب دیکھا ہے؟\" ایک شخص بولا: میں نے دیکھا: گویا ایک ترازو آسمان سے اترا، آپ صلی اللہ علیہ وسلم کو اور ابوبکر کو تولا گیا، تو آپ ابوبکر سے بھاری نکلے، پھر عمر اور ابوبکر کو تولا گیا تو ابوبکر بھاری نکلے، پھر عمر اور عثمان کو تولا گیا تو عمر بھاری نکلے، پھر ترازو اٹھا لیا گیا، تو ہم نے رسول اللہ صلی اللہ علیہ وسلم کے چہرے میں ناپسندیدگی دیکھی۔","صحیح",{"u2":"سیدنا ابوبکرہ رضی اللہ عنہ روایت کرتے ہیں کہنبی کریم صلی اللہ علیہ وسلم نے ایک دن دریافت فرمایا ” تم میں سے خواب کس نے دیکھا ہے؟ “ ایک آدمی نے کہا: میں نے۔ میں نے دیکھا کہ گویا آسمان سے ایک ترازو اتری ہے تو آپ کا اور سیدنا ابوبکر رضی اللہ عنہ کا وزن کیا گیا تو آپ سیدنا ابوبکر رضی اللہ عنہ سے بھاری ہو گئے۔ پھر سیدنا ابوبکر رضی اللہ عنہ اور سیدنا عمر رضی اللہ عنہ کا وزن کیا گیا تو ابوبکر رضی اللہ عنہ بھاری ہو گئے۔ اور سیدنا عمر رضی اللہ عنہ اور سیدنا عثمان رضی اللہ عنہ کا وزن کیا گیا تو سیدنا عمر رضی اللہ عنہ بھاری ہو گئی، پھر ترازو اٹھا لی گئی۔ تو (اس بات پر) ہم نے رسول اللہ صلی اللہ علیہ وسلم کے چہرہ اقدس پر ناپسندیدگی کے آثار دیکھے۔ “","f2":"1۔وزن کیا جانا خواب میں ایک تمثیل تھی جس کے معنی واضح ہیں کہ سول اللہ صلی اللہ علیہ وسلم اپنی ساری امت کے مقابلے میں افضل واعلی اور بھاری ہیں بلکہ سابقہ امتیں بھی ہیچ ہیں۔اسی طرح جلیل القدر صحابہ میں بھی حضرت ابوبکر صدیق رضی اللہ عنہ سے کوئی افضل نہیں۔ان کے بعد حضرت عمر رضی اللہ عنہکا درجہ ہے۔اگرچہ یہ اور دیگر صحابہ اپنے اپنے انفرادی فضائل ومناقب میں ایک دوسرے سے بڑھ کر ہیں مگر مجموعی اعتبار سے یہی نتیجہ ہے جو بیان ہوا اور امت کا یہی عقیدہ ہے۔\n2۔ترازو اٹھائے جانے پر رسول اللہ صلی اللہ علیہ وسلم کے چہرے کا بدل جانا غالباً اس وجہ سے تھاکہ اس کے بعد فتنے سر اٹھانے والے تھے۔جیسے کہ فی الواقع واقعات نے ثابت کیا ہے۔والله اعلم۔ بعض حضرات کے نزدیک یہ روایت صحیح ہے۔"}],[4635,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک دن فرمایا: \"تم میں سے کس نے خواب دیکھا ہے؟\" پھر راوی نے اسی مفہوم کی حدیث بیان کی اور چہرے پر ناگواری دیکھنے کا ذکر نہیں کیا بلکہ یوں کہا: رسول اللہ صلی اللہ علیہ وسلم کو وہ (خواب) برا لگا، اور فرمایا: \"وہ نبوت کی خلافت ہے، پھر اس کے بعد اللہ جسے چاہے گا سلطنت عطا کرے گا\"۔","صحیح",{"u2":"جناب عبدالرحمٰن اپنے والد ابوبکرہ رضی اللہ عنہ سے روایت کرتے ہیں کہنبی کریم صلی اللہ علیہ وسلم نے ایک دن دریافت فرمایا ” تم میں سے کسی نے خواب دیکھا ہے؟ “ تو مذکورہ بالا روایت کے ہم معنی بیان کیا۔ مگر اس روایت میں «كراهية» کا ذکر نہیں۔ بلکہ «فاستاء لها رسول الله صلى الله عليه وسلم» یعنی آپ صلی اللہ علیہ وسلم کو یہ کیفیت پسند نہ آئی۔ پھر فرمایا ” یہ نبوت کی خلافت ہے۔ پھر اس کے بعد اللہ جسے چاہے گا اپنا ملک عنایت فر دے گا۔ “"}],[4636,"جابر بن عبداللہ رضی اللہ عنہما بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آج کی رات ایک صالح شخص کو خواب میں دکھایا گیا کہ ابوبکر کو رسول اللہ صلی اللہ علیہ وسلم سے جوڑ دیا گیا ہے، اور عمر کو ابوبکر سے اور عثمان کو عمر سے\"۔ جابر کہتے ہیں: جب ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس سے اٹھ کر آئے تو ہم نے کہا: مرد صالح سے مراد تو رسول اللہ صلی اللہ علیہ وسلم ہیں، اور بعض کا بعض سے جوڑے جانے کا مطلب یہ ہے کہ یہی لوگ اس امر (دین) کے والی ہوں گے جس کے ساتھ اللہ نے اپنے نبی اکرم صلی اللہ علیہ وسلم کو مبعوث فرمایا ہے۔ ابوداؤد کہتے ہیں: اسے یونس اور شعیب نے بھی روایت کیا ہے، لیکن ان دونوں نے عمرو بن ابان کا ذکر نہیں کیا ہے۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کیا کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” آج رات ایک نیک بندے کو خواب دکھایا گیا ہے کہ سیدنا ابوبکر رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ معلق کیا گیا ہے اور سیدنا عمر کو سیدنا ابوبکر کے ساتھ معلق کیا گیا ہے اور سیدنا عثمان کو سیدنا عمر کے ساتھ معلق کیا گیا ہے۔ “ سیدنا جابر رضی اللہ عنہ نے کہا: پھر جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ہاں سے اٹھے تو ہم نے کہا: ” صالح آدمی “ تو وہ خود رسول اللہ صلی اللہ علیہ وسلم ہیں اور ان کا ایک دوسرے کے ساتھ معلق کرنا ‘ اس لیے کہ یہی لوگ اس امر کے ذمہ دار ہیں جس کے ساتھ اللہ نے اپنے نبی صلی اللہ علیہ وسلم کو مبعوث فرمایا ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو یونس اور شعیب نے روایت کیا ہے مگر ان دونوں نے سند میں عمرو (عمرو بن ابان) کا ذکر نہیں کیا۔"}],[4637,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے کہا: اللہ کے رسول! میں نے دیکھا گویا کہ آسمان سے ایک ڈول لٹکایا گیا پہلے ابوبکر آئے تو اس کی دونوں لکڑیاں پکڑ کر اس میں سے تھوڑا سا پیا، پھر عمر آئے تو اس کی دونوں لکڑیاں پکڑیں اور انہوں نے خوب سیر ہو کر پیا، پھر عثمان آئے اور اس کی دونوں لکڑیاں پکڑیں اور خوب سیر ہو کر پیا، پھر علی آئے اور اس کی دونوں لکڑیاں پکڑیں، تو وہ چھلک گیا اور اس میں سے کچھ ان کے اوپر بھی پڑ گیا۔","ضعیف",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے کہا: اے اللہ کے رسول! میں نے دیکھا ہے جیسے ایک ڈول آسمان سے لٹکایا گیا ‘ تو سیدنا ابوبکر رضی اللہ عنہ آئے ہیں اور اس کو اس کے دونوں طرف کے کناروں سے پکڑ لیا۔ اور اس سے پانی پیا، مگر کمزوری کے ساتھ۔ پھر سیدنا عمر رضی اللہ عنہ آئے انہوں نے اس کو اس کے دونوں کناروں سے پکڑا اور پیا اور خوب سیر ہو کر پیٹ بھر کر پیا۔ پھر سیدنا عثمان رضی اللہ عنہ آئے، انہوں نے اس کے دونوں کناروں سے پکڑا اور پیا حتیٰ کہ پیٹ بھر کر پیا۔ پھر سیدنا علی رضی اللہ عنہ آئے، انہوں نے اس کے دونوں کناروں سے پکڑا تو وہ ہلا اور اس سے کچھ پانی ان پر گر گیا۔"}],[4638,"مکحول نے کہا رومی شام میں چالیس دن تک لوٹ کھسوٹ کرتے رہیں گے اور سوائے دمشق اور عمان کے کوئی شہر بھی ان سے نہ بچے گا۔","صحیح الإسناد",{"u2":"جناب مکحول رضی اللہ عنہ سے روایت ہے انہوں نے کہا ضرور ایسا ہو گا کہ رومی لوگ چالیس دن تک شامیوں کے گھروں میں گھسے رہیں گے۔ اس (فتنے) سے سوائے دمشق اور عمان کے کوئی شہر نہ بچے گا۔"}],[4639,"عبدالعزیز بن علاء کہتے ہیں کہ انہوں نے ابو الأ عیس عبدالرحمٰن بن سلمان کو کہتے سنا کہ عجم کے بادشاہوں میں سے ایک بادشاہ تمام شہروں پر غالب آ جائے گا سوائے دمشق کے۔","صحیح الإسناد",{"u2":"جناب ابو اعیس عبدالرحمٰن بن سلمان رضی اللہ عنہ بیان کرتے تھے کہ ایک عجمی بادشاہ سارے شہروں پر غالب آ جائے گا اور صرف دمشق محفوظ رہے گا۔"}],[4640,"مکحول کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمانوں کا خیمہ لڑائیوں کے وقت ایک ایسی سر زمین میں ہو گا جسے غوطہٰ ۱؎کہا جاتا ہے\"۔\n§وضاحت\n۱؎ : دمشق کے پاس ملک شام میں ایک جگہ ہے۔","صحیح",{"u2":"جناب مکحول رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جنگوں (اور فتنوں) کے دنوں میں مسلمان ایک ایسی جگہ پر خیمہ زن ہوں گے جسے غوطہ کہتے ہوں گے۔ “","f2":"غوطہ دمشق کے ارد گرد باغات کا نام ہے۔دیکھیےگزشتہ حدیث:4298۔"}],[4641,"عوف الا عرابی کہتے ہیں کہ میں نے حجاج کو خطبہ میں یہ کہتے سنا: عثمان کی مثال اللہ کے نزدیک عیسی بن مریم کی طرح ہے، پھر انہوں نے آیت کریمہ «إذ قال الله يا عيسى إني متوفيك ورافعك إلى ومطهرك من الذين كفروا» \"جب اللہ نے کہا کہ: اے عیسی! میں تجھے پورا لینے والا ہوں، اور تجھے اپنی جانب اٹھانے والا ہوں، اور تجھے کافروں سے پاک کرنے والا ہوں\" (سورۃ آل عمران: ۵۵) پڑھی اور اپنے ہاتھ سے ہماری اور اہل شام کی طرف اشارہ کر رہے تھے ۱؎۔\n§وضاحت\n۱؎ : یہ تفسیر بالرائے کی بدترین قسم ہے حجاج نے اس آیت کریمہ کو اپنے اور اپنے مخالفوں پر منطبق کر ڈالا جب کہ حقیقت سے اس کا کوئی واسطہ نہیں، آج بھی بعض اہل بدعت آیات قرآنیہ کی من مانی تفسیر کرتے رہتے ہیں، اور اہل حق کو اہل باطل اور باطل پرستوں کو اہل حق باور کراتے ہیں۔","ضعیف",{"u2":"عوف (عوف ابی جمیلہ اعرابی) نے بیان کیا انہوں نے کہا کہ میں نے حجاج (حجاج بن یوسف) کو خطبہ دیتے ہوئے سنا، وہ کہہ رہا تھا کہ سیدنا عثمان رضی اللہ عنہ کی مثال اللہ کے ہاں عیسیٰ ابن مریم علیہ السلام کی طرح ہے۔ پھر یہ آیت پڑھی «إذ قال الله يا عيسى إني متوفيك ورافعك إلى ومطهرك من الذين كفروا» ” جب اللہ تعالیٰ نے فرمایا: اے عیسیٰ میں تمہیں (اس جہان سے) پورا پورا لے جانے والا ہوں اور اپنی طرف اٹھا لینے والا ہوں اور ان کافروں کی صحبت سے تمہیں پاک کرنے والا ہوں۔ “ وہ یہ آیت پڑھتا جاتا تھا اور اس کی شرح کرتے ہوئے اپنے ہاتھ سے ہماری طرف اور اہل شام کی طرف اشارے کرتا جاتا تھا۔","f2":"مفہوم کلام یہ تھا کہ جس طرح حضرت عیسی علیہ السلام اور ان کے متبعین کو اللہ تعالی نے کافروں پر غلبہ دیا اسی طرح حضرت عثمان رضی اللہ عنہ کے متبعین ہیں جو شام میں پورے ملک پر حکومت کر رہے ہیں دوسرے جو ان کے مخالف ہیں مغلوب ہیں"}],[4642,"ربیع بن خالد ضبی کہتے ہیں کہ میں نے حجاج کو خطبہ دیتے سنا، اس نے اپنے خطبے میں کہا: تم میں سے کسی کا پیغام بر جو اس کی ضرورت سے (پیغام لے جا رہا) ہو زیادہ درجے والا ہے، یا وہ جو اس کے گھربار میں اس کا قائم مقام اور خلیفہ ہو؟ تو میں نے اپنے دل میں کہا: اللہ کا میرے اوپر حق ہے کہ میں تیرے پیچھے کبھی نماز نہ پڑھوں، اور اگر مجھے ایسے لوگ ملے جو تجھ سے جہاد کریں تو میں ضرور ان کے ساتھ تجھ سے جہاد کروں گا۔ اسحاق نے اپنی روایت میں اتنا اضافہ کیا ہے: چنانچہ انہوں نے جماجم میں جنگ کی یہاں تک کہ مارے گئے۔","صحیح الإسناد",{"u2":"ربیع بن خالد ضبی نے بیان کیا کہ میں نے حجاج (حجاج بن یوسف) کو خطبہ دیتے ہوئے سنا، اس نے اپنے خطبے میں کہا: ہم میں سے کسی کا قاصد جو اس کے کسی کام میں مشغول ہو، وہ اس کے لیے زیادہ محترم ہوتا ہے یا اس کا وہ نائب جو اس کے اہل میں ٹھہرا ہوا ہو؟ پس میں نے اپنے دل میں کہا: مجھ پر اللہ کے لیے یہ نذر ہے کہ اب تیرے پیچھے کبھی نماز نہیں پڑھوں گا، اور اگر مجھے کچھ لوگ مل گئے جو تیرے خلاف جہاد کرتے ہوں تو میں ان کے ساتھ مل کر بالضرور جہاد کروں گا۔ اسحاق نے اپنی روایت میں مزید کہا: چنانچہ اس نے (ربیع بن خالد نے حجاج کے خلاف دیر) جماجم کے قتال میں حصہ لیا حتیٰ کہ قتل ہو گیا۔","f2":"حجاج کی طرف منسوب اس کلام کا مفہوم یہ بیان کیا جاتا ہے کہ جس طرح کسی کا نائب اور جو اس کے اہل میں رہ کر انکی خدمت کر رہا ہواس کے قاصد کی نسبت زیادہ افضل ہوتا ہے۔اسی طرح انبیاء جو فقط اللہ عزوجل کے احکام پہنچانے والے تھے نعوذ باللہ ان کی نسبت امراء بنو امیہ جو اس زمین میں اللہ کے خلیفہ ہیں بہتر ہیں اور یہ کہ خلیفہ قاصد سے افضل ہوا کرتا ہے۔یہ کلام مفہوم اگر درست ہو تو صریح کفر ہے مگر یہ روایت ضعیف ہے۔"}],[4643,"عاصم کہتے ہیں کہ میں نے حجاج کو منبر پر کہتے سنا: جہاں تک تم سے ہو سکے اللہ سے ڈرو، اس میں کوئی شرط یا استثناء نہیں ہے، امیر المؤمنین عبدالملک کی بات سنو اور مانو، اس میں بھی کوئی شرط اور استثناء نہیں ہے، اللہ کی قسم، اگر میں نے لوگوں کو مسجد کے ایک دروازے سے نکلنے کا حکم دیا پھر وہ لوگ کسی دوسرے دروازے سے نکلے تو ان کے خون اور ان کے مال میرے لیے حلال ہو جائیں گے، اللہ کی قسم! اگر مضر کے قصور پر میں ربیعہ کو پکڑ لوں، تو یہ میرے لیے اللہ کی جانب سے حلال ہے، اور کون مجھے عبدہذیل (عبداللہ بن مسعود ہذلی) کے سلسلہ میں معذور سمجھے گا جو کہتے ہیں کہ ان کی قرآت اللہ کی طرف سے ہے قسم اللہ کی، وہ سوائے اعرابیوں کے رجز کے کچھ نہیں، اللہ نے اس قرآت کو اپنے نبی علیہ السلام پر نہیں نازل فرمایا، اور کون ان عجمیوں کے سلسلہ میں مجھے معذور سمجھے گا جن میں سے کوئی کہتا ہے کہ وہ پتھر پھینک رہا ہے، پھر کہتا ہے، دیکھو پتھر کہاں گرتا ہے؟ (فساد کی بات کہہ کر دیکھتا ہے کہ دیکھوں اس کا کہاں اثر ہوتا ہے) اور کچھ نئی بات پیش آئی ہے، اللہ کی قسم، میں انہیں اسی طرح نیست و نابود کر دوں گا، جیسے گزشتہ کل ختم ہو گیا(جو اب کبھی نہیں آنے والا) ۔ عاصم کہتے ہیں: میں نے اس کا تذکرہ اعمش سے کیا تو وہ بولے: اللہ کی قسم میں نے بھی اسے، اس سے سنا ہے۔","صحیح",{"u2":"عاصم سے مروی ہے کہ میں نے حجاج سے سنا، وہ برسر منبر کہہ رہا تھا: اللہ کا تقویٰ اختیار کرو جہاں تک ہمت پاؤ، اس میں کوئی استثنا نہیں۔ امیر المؤمنین عبدالملک (عبدالملک بن مروان) کی بات سنو اور اطاعت کرو، اس میں کوئی استثنا نہیں۔ اللہ کی قسم! اگر میں لوگوں کو حکم دوں کہ مسجد کے فلاں دروازے سے باہر جاؤ اور وہ دوسرے کسی دروازے سے باہر نکلیں تو میرے لیے ان کے خون اور مال حلال ہوں گے۔ اللہ کی قسم! اگر میں مضر کے بدلے قبیلہ ربیعہ کی گرفت کروں تو یہ میرے لیے اللہ کی طرف سے حلال ہے۔ اور کون ہے جو مجھے ہذیل کے غلام (اشارہ ہے سیدنا عبداللہ بن مسعود رضی اللہ عنہ) کی طرف سے معذور جانے، اس کا خیال ہے کہ اس کی قرآت اللہ کی طرف سے ہے۔ اللہ کی قسم! یہ (اس کی قرآت) تو بدویوں کے رجز (چھوٹے چھوٹے شعروں) کی مانند ہے۔ اللہ نے اسے اپنے نبی صلی اللہ علیہ وسلم پر نازل نہیں کیا ہے۔ اور کون ہے جو مجھے ان عجمیوں سے معذور جانے، ان میں سے کوئی پتھر پھینک دیتا ہے (فتنے کی بات کر دیتا ہے) پھر کہتا ہے دیکھو یہ کہاں تک جاتا ہے۔ اللہ کی قسم! میں انہیں کل ماضی کی مانند کر کے رکھ دوں گا (نیست و نابود کر دوں گا)۔ راوی نے کہا کہ میں نے یہ واقعہ اعمش کو بیان کیا تو اس نے کہا: میں نے بھی اللہ کی قسم! اسے اس سے سنا ہے۔"}],[4644,"اعمش کہتے ہیں کہ میں نے حجاج کو منبر پر کہتے سنا: یہ گورے (عجمی) قیمہ بنائے جانے کے قابل ہیں قیمہ، موالی (غلامو) سنو، اللہ کی قسم، اگر میں لکڑی پر لکڑی ماروں تو انہیں اسی طرح برباد کر کے رکھ دوں جس طرح گزرا ہوا کل ختم ہو گیا، یعنی عجمیوں کو۔","صحیح",{"u2":"میں نے حجاج سے سنا وہ منبر پر کھڑا کہہ رہا تھا: یہ عجمی کاٹ ڈالے جانے کے لائق ہیں۔ اللہ کی قسم! میں نے اگر لاٹھی کو لاٹھی پر مارا تو ان لوگوں کو ماضی کی مانند کر چھوڑوں گا (نیست و نابود کر دوں گا)۔ اس کا اشارہ غیر عرب لوگوں کی طرف تھا۔","f2":"لاٹھی کو لاٹھی پر مارا یعنی ان کا قلع قمع کرنے کا ارادہ کیا تو۔۔۔۔اس سے پتا چلتا ہے کہ دین کے بجائے عربوں کی قومی عصبیت پر اس کا ایمان تھا۔\nفوائد ومسائل بنوزرقاء سے مراد بنو مروان ہیں زرقاء ان کے نسب میں آتی ہے جس کی یہ اولاد ہیں۔"}],[4645,"سلیمان الاعمش کہتے ہیں میں نے حجاج کے ساتھ جمعہ کی نماز پڑھی، اس نے خطبہ دیا، پھر راوی ابوبکر بن عیاش والی روایت (۴۶۴۳) ذکر کی، اس میں ہے کہ اس نے کہا: سنو اور اللہ کے خلیفہ اور اس کے منتخب عبدالملک بن مروان کی اطاعت کرو، اس کے بعد آگے کی حدیث بیان کی اور کہا: اگر میں مضر کے جرم میں ربیعہ کو پکڑوں (تو یہ غلط نہ ہو گا) اور عجمیوں والی بات کا ذکر نہیں کیا۔","صحیح إلی الحجاج",{"u2":"شریک نے سلیمان اعمش سے روایت کیا، کہا کہمیں نے حجاج کے ساتھ جمعہ پڑھا تو اس نے خطبہ دیا، اور ابوبکر بن عیاش والی (مذکورہ بالا) حدیث (4643) بیان کی۔ اس نے کہا: اللہ کے خلیفہ اور اس کے منتخب عبدالملک بن مروان کی بات سنو اور اس کی اطاعت کرو۔ اور حدیث بیان کی۔ مزید کہا: اور اگر میں مضر کے بدلے ربیعہ کی گرفت کروں اور عجمیوں کا ذکر نہیں کیا۔"}],[4646,"سفینہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خلافت علی منہاج النبوۃ (نبوت کی خلافت) تیس سال رہے گی۱؎، پھر اللہ تعالی سلطنت یا اپنی سلطنت جسے چاہے گا دے گا\" سعید کہتے ہیں: سفینہ نے مجھ سے کہا: اب تم شمار کر لو: ابوبکر رضی اللہ عنہ دو سال، عمر رضی اللہ عنہ دس سال، عثمان رضی اللہ عنہ بارہ سال، اور علی رضی اللہ عنہ اتنے سال۔ سعید کہتے ہیں: میں نے سفینہ رضی اللہ عنہ سے کہا: یہ لوگ (مروانی) کہتے ہیں کہ علی رضی اللہ عنہ خلیفہ نہیں تھے، انہوں نے کہا: بنی زرقاء یعنی بنی مروان کے ۲؎ چوتڑ جھوٹ بولتے ہیں۔\n§وضاحت\n۱؎ : ابوبکر رضی اللہ عنہ کی مدت خلافت: دو سال، تین ماہ، دس دن، عمر رضی اللہ عنہ کی: دس سال ، چھ ماہ، آٹھ دن، عثمان رضی اللہ عنہ کی: گیارہ سال، گیارہ ماہ، نو دن، علی رضی اللہ عنہ کی: چار سال، نو ماہ ، سات دن، حسن رضی اللہ عنہ کی: سات ماہ، کل مجموعہ: تیس سال ایک ماہ۔ ۲؎ : زرقاء بنی امیہ کی امّہات میں سے ایک خاتون کا نام ہے۔","حسن صحیح",{"u2":"(رسول اللہ صلی اللہ علیہ وسلم کے غلام) سیدنا سفینہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ نبوت کی خلافت تیس سال رہے گی پھر اللہ تعالی اپنا ملک جسے چاہے گا عنائت کرے گا۔\nسعید بن جمہان نے کہا کہ حضرت سفینہ ‎‎نے مجھے کہا حساب لگا لو حضرت ابو بکر رضی اللہ عنہ کے دو سال حضرت عمر رضی اللہ عنہ کے دس سال اور حضرت عثمان رضی اللہ عنہ کے بارہ سال اور اسی طرح کچھ حضرت علی رضی اللہ عنہ۔سعید کہتے ہیں کہ میں نے حضرت سفینہ سے کہا کہ یہ بنومروان سمجھتے ہیں کہ حضرت علی رضی اللہ عنہ خلیفہ نہ تھے تو انھوں نے کہا بنی زرقاء کے پچھلے حصوں نے جھوٹ بولا ہے۔","f2":"بنوزرقاء سے مراد بنو مروان ہیں زرقاء ان کے نسب میں آتی ہے جس کی یہ اولاد ہیں۔\n2۔پچھلے حصوں نے جھوٹ بولا ایک محاورہ ہے جو اپنے مفاد کے لیے من گھڑت بات پھیلانے والون کے بارے میں بولا جاتا ہے،\n3۔مذکورہ بالا مدت خلفاء اربعہ حضرت ابوبکرٌحضرت عمر حضرت عثمان حضرت علی اور حضرت حسن رضی اللہ عنہ کے دور خلافت کو محیط ہے۔حضرت ابوبکر رضی اللہ عنہ کی خلافت دوسال تین مہینے اور دس دن حضرت عمر رضی اللہ عنہ کی دس سال چھ مہینے اور آٹھ دن اور حضرت عثمان رضی اللہ عنہ کی گیارہ سال گیارہ مہینے اور نو دن حضرت علی رضی اللہ عنہ کی چار سال نو مہینے اور سات دن اور حضرت حسن رضی اللہ عنہ کی تقریباً سات مہینے ہے۔حضرت حسن رضی اللہ عنہ نے حالات کی نزاکت کو دیکھتے ہوئےخود ہی خلافت سے دست برداری اختیار کرکے خلافت حضرت معاویہ رضی اللہ عنہ کے سپرد کردی اور یوں وہ اختلافات ختم ہوگئے جو حضرت عثمان رضی اللہ عنہ کی مظلومانہ شہادت کے بعد قصاص عثمان کے مسئلے پر شروع ہوئے تھے جو بڑھتے بڑھتےباہمی جنگ اور خون یزی تک پہنچ گئے تھے۔اس کے بعد حضرت معاویہ رضی اللہ عنہ 20 سال تک خلیفہ رہے انہوں نے اندرونی شورش اور بد امنی کو بھی ختم کیااور بیرونی طور پر ان جہادی سرگرمیوںکا بھی پھر سے آغاز کیا جن کا سلسلہ آپس کے اختلافات کی وجہ سے منقطع ہوگیا تھا۔اس اعتبار سے حضرت معاویہ رضی اللہ عنہ کا یہ دور خلافت بھی اسلامی تاریخ کا ایک عہد زریں ہے۔حدیث میں جو خلافت نبوت کا دور جو صرف 30 سال بتلایا گیا ہے اس کا مطلب یہ ہے کہ اتنے عرسے تک خلافت میں دنیوی اغراض ومقاصد اور شاہانہ شان و شوکت شامل نہیں ہوگی لیکن اس کے بعد ان چیزوں کی کچھ آمیزش ہو جائے گی۔یہ مطلب نہیں ہے کہ سرے سے خلافت یا اسلامی نظام حکومت ہی کا خاتمہ ہوجائے گااو صرف ملوکیت یا مطلق العنایت ہی باقی رہ جائے گی۔ایسا الحمد للہ نہیں ہوا بلکہ خلافت کچھ جزوی خرابیوں کے ساتھ باقی رہی۔اور یہ تسلسل کم و بیش کے کچھ فرق کے ساتھ صدیوں تک قائم رہا تا آنکہ 1924میں ترکی کے مصطفی کمال پاشا نے ادارہ خلافت کا خاتمہ کردیا۔بعض لوگ اس حدیث کی بنیاد پر یہ دعوی کردیتے ہیںکہ اسلام کا سیاسی نظام صرف 30 سال چلااور پھر ختم ہوگیا۔یہ دعوی نہایت سطحی بھی ہےاور حقائق وواقعات کے خلاف بھی۔اسلام کے سیاسی نظام یعنی ادارہ کلافت نے صدیوں تک دنیا میں حکمرانی کی ہےاور اس کے ذریعے سے اسلام اور مسلمانوں کی عظمت کا سکہ منوایا ہے (تفصیل کے لیے ملاحظہ ہو:راقم(حافظ صلاح الدین یوسف کی کتاب رحمہ اللہ) خلافت و ملوکیت کی تاریخی و شرعی حیثیت) اس میں اسلام کے سیاسی نظام یعنی خلافت کے خدوخال بھی واضح کیے گیے ہیںاور مسلمان خلفاء وسلاطین کی بابت غلط پروپیگنڈے کی دبیز تہوں کو بھی صاف کیا گیاہے۔"}],[4647,"سفینہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خلافت علی منہاج النبوۃ (نبوت کی خلافت) تیس سال ہے، پھر اللہ تعالی سلطنت جسے چاہے گا یا اپنی سلطنت جسے چاہے گا، دے گا\"۔","حسن صحیح",{"u2":"سیدنا سفینہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” نبوت کی خلافت تیس سال تک رہے گی۔ پھر اللہ تعالیٰ اپنا ملک جسے چاہے گا دیدے گا۔ “"}],[4648,"عبداللہ بن ظالم مازنی کہتے ہیں کہ میں نے سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ کو کہتے سنا: جب فلاں شخص کوفہ میں آیا تو فلاں شخص خطبہ کے لیے کھڑا ہوا ۱؎، سعید بن زید نے میرا ہاتھ پکڑ کر کہا: ۲؎ کیا تم اس ظالم ۳؎ کو نہیں دیکھتے ۴؎ پھر انہوں نے نو آدمیوں کے بارے میں گواہی دی کہ وہ جنت میں ہیں، اور کہا: اگر میں دسویں شخص (کے جنت میں داخل ہونے) کی گواہی دوں تو گنہگار نہ ہوں گا، (ابن ادریس کہتے ہیں: عرب لوگ ( «إیثم» کے بجائے) «آثم» کہتے ہیں)، میں نے پوچھا: اور وہ نو کون ہیں؟ کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، اس وقت آپ حراء (پہاڑی) پر تھے: \"حراء ٹھہر جا (مت ہل) اس لیے کہ تیرے اوپر نبی ہے یا صدیق ہے یا پھر شہید\" میں نے عرض کیا: اور نو کون ہیں؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم، ابوبکر، عمر، عثمان، علی، طلحہ، زبیر، سعد بن ابی وقاص اور عبدالرحمٰن بن عوف رضی اللہ عنہم، میں نے عرض کیا: اور دسواں آدمی کون ہے؟ تو تھوڑا ہچکچائے پھر کہا: میں۔ ابوداؤد کہتے ہیں: اسے اشجعی نے سفیان سے، سفیان نے منصور سے، منصور نے ہلال بن یساف سے، ہلال نے ابن حیان سے اور ابن حیان نے عبداللہ بن ظالم سے اسی سند سے روایت کیا ہے۔\n§وضاحت\n۱؎ : ’’ فلاں شخص کوفہ میں آیا ‘‘ اس سے کنایہ معاویہ رضی اللہ عنہ کی طرف ہے، اور ’’ فلاں شخص خطبہ کے لئے کھڑا ہوا ‘‘ اس سے کنایہ مغیرہ بن شعبہ رضی اللہ عنہ کی طرف ہے، اس جیسے مقام کے لئے کنایہ ہی بہتر تھا تاکہ شرف صحابیت مجروح نہ ہو۔ ۲؎ : یہ عبداللہ بن ظالم مازنی کا قول ہے۔ ۳؎ : اس سے مراد خطیب ہے۔ ۴؎ : جو علی رضی اللہ عنہ کو برا بھلا کہہ رہا ہے۔","صحیح",{"u2":"جناب عبداللہ بن ظالم مازنی سے روایت ہے، انہوں نے کہا کہ میں نے سیدنا سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ سے سنا، انہوں نے کہا: جب فلاں کوفے میں آیا اور اس نے فلاں کو خطبے میں کھڑا کیا (عبداللہ نے کہا) تو سعید بن زید رضی اللہ عنہ نے میرے ہاتھ دبائے اور کہا: کیا تم اس ظالم (خطیب) کو نہیں دیکھتے ہو، (غالباً وہ خطیب سیدنا علی رضی اللہ عنہ کے بارے میں کچھ کہہ رہا تھا۔) میں نو افراد کے بارے میں گواہی دیتا ہوں کہ وہ جنتی ہیں، اگر دسویں کے بارے میں کہوں تو گناہ گار نہیں ہوں گا۔ ابن ادریس نے کہا عرب لوگ «آثم» کا لفظ بولتے ہیں (جبکہ سیدنا سعید نے «لم إيثم»)۔ عبداللہ کہتے ہیں، میں نے پوچھا: وہ نو افراد کون سے ہیں؟ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جبکہ آپ صلی اللہ علیہ وسلم حراء پر کھڑے ہوئے تھے: ” اے حراء ٹھر جا! تجھ پر سوائے نبی کے یا صدیق کے یا شہید کے اور کوئی نہیں ہے۔ “ میں نے کہا اور وہ نو کون کون ہیں؟ کہا: رسول صلی اللہ علیہ وسلم، ابوبکر، عمر، عثمان، علی، طلحہ، زبیر، سعد بن ابی وقاص، (مالک) اور عبدالرحمٰن بن عوف رضی اللہ عنہ م۔ میں نے پوچھا اور دسواں کون ہے؟ تو وہ لمحے بھر کے لیے ٹھٹھکے پھر کہا میں۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس حدیث کو اشجعی نے سفیان سے، انہوں نے منصور سے، انہوں نے ہلال بن یساف سے، انہوں نے ابن حیان سے، انہوں نے عبداللہ بن ظالم سے اسی کی سند سے مذکورہ بالا کی مانند روایت کیا ہے۔","f2":"معلوم ہوتا ہے کہ خطیب نے اشارے کنائے میں حضرت علی رضی اللہ عنہ کے بارے میں نامناسب انداز اختیار کیا تو حضرت سعید بن زید نے عشرہ مبشرہ کی فضیلت بیان کرکے جن میں سے ایک حضرت علی رضی اللہ عنہ بھی تھے اس خطیب کی تردید کی۔اگلی روایات میں اس بات کی مزید صراحت ہے۔"}],[4649,"عبدالرحمٰن بن اخنس سے روایت ہے کہ وہ مسجد میں تھے، ایک شخص نے علی رضی اللہ عنہ کا (برائی کے ساتھ) تذکرہ کیا، تو سعید بن زید رضی اللہ عنہ کھڑے ہو گئے اور فرمایا: میں گواہی دیتا ہوں رسول اللہ صلی اللہ علیہ وسلم پر کہ میں نے آپ کو فرماتے سنا: \"دس لوگ جنتی ہیں: ابوبکر جنتی ہیں، عمر جنتی ہیں، عثمان جنتی ہیں، علی جنتی ہیں، طلحہ جنتی ہیں، زبیر بن عوام جنتی ہیں، سعد بن مالک جنتی ہیں اور عبدالرحمٰن بن عوف جنتی ہیں\" اور اگر میں چاہتا تو دسویں کا نام لیتا، وہ کہتے ہیں: لوگوں نے عرض کیا: وہ کون ہیں؟ تو وہ خاموش رہے، لوگوں نے پھر پوچھا: وہ کون ہیں؟ تو کہا: وہ سعید بن زید ہیں۔","صحیح",{"u2":"جناب عبدالرحمٰن بن الاخنس سے روایت ہے کہ وہ مسجد میں بیٹھے ہوئے تھے جب ایک شخص نے سیدنا علی رضی اللہ عنہ کا ذکر کیا تو سیدنا سعید بن زید رضی اللہ عنہ کھڑے ہوئے اور کہا: میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ صلی اللہ علیہ وسلم فرماتے تھے: ” دس اشخاص جنت میں ہیں۔ نبی صلی اللہ علیہ وسلم جنت میں ہیں، ابوبکر جنت میں ہیں، عمر جنت میں ہیں، عثمان جنت میں ہیں، علی جنت میں ہیں، طلحہ جنت میں ہیں، زبیر بن عوام جنت میں ہیں، سعد بن مالک جنت میں ہیں اور عبدالرحمٰن بن عوف جنت میں ہیں۔ “ اگر میں چاہوں تو دسویں کا نام بھی لے سکتا ہوں۔ لوگوں نے پوچھا وہ کون ہے؟ تو وہ خاموش ہو رہے۔ لوگوں نے پوچھا: وہ کون ہے تو انہوں نے کہا: وہ سعید بن زید ہے۔","f2":"ان روایات کے علاوہ بھی اس مضمون میں بیت سی روایات کتب سنت میں موجود ہیں جبکہ کتاب اللہ میں بھی صحابہ کرام رضی اللہ عنہ کی مدح وستائش بصراحت آئی ہےمثلا(والسبقون الاولون من المهاجرين والانصار والذين اتبعوهم باحسان رضي الله عنهم ورضو ا عنه واعدلهم جنت تجري تحتها الانهر خلدين فيها ابدا ذلك الفوزالعظيم)(التوبه:١--) وہ مہاجرین وانصار جنہوں نے (سب سے پہلے ایمان لانے میں) سبقت کی اور وہ لوگ جنہوں نے احسن انداز میں ان کا اتباع کیا اللہ ان (سب) سے راضی ہوا اور وہ اس (اللہ) سے راضی ہوئے۔اللہ نے ان کے لیے ایسے باغات تیار کر رکھے ہیں جن کے نیچے نہریں جاری ہیں وہ ان میں ہمیشہ رہیں گے یہ بیت بڑی کامیابی ہے۔ اور (لكن الرسول والذين امنوا معه جاهدوا باموالهم و انفسهم و اولئك لهم الخيرات واولئك هم المفلحون اعدالله لهم جنت تجري من تهتها الانهرخلدين فيها ذلك الفوز العظيم) -(التوبه:٨٩٨٨)\nليكن رسول الله صلی اللہ علیہ وسلم نے اور ان لوگوں نے جو اس کے ساتھ ایمان لائے انہوں نے اپنے اموال اور اپنی جانوں کے ذریعے سے جہاد کیا انہی لوگوں کے لیے ساری بھلائیاں ہیں اور یہی لوگ فلاح پانے والے ہیں۔اللہ نے ان کے لیے ایسے باغات تیار رکھے ہیں جن کے نیچے نہریں جاری ہیں جن میں یہ ہمیشہ رہنے والے ہیں یہی بہت بڑی کامیابی ہے۔اور سورۃالفتح میں ہے:(لقد رضي الله عن المومنين اذ يبايعونك تحت الشجرة فعلم ما في قلوبهم فانزل المسكينة عليهم و اثابهم فتحا قريبا) (الفتح:١٨)\nتحقیق اللہ راضی ہوگیا مومنوں سے جب کہ وہ آپ سے اس درخت کے نیچے بیعت کر رہے تھے پس اس نے اس(خلوص) کو جان لیا جو ان کے دلوں میں تھا اس نے ان پر اطمینان نازل کیا اور بدلے میں انہیں جلد ہی فتح دیدی۔بعد کے دور میں صحابہ کے مابین جو چپقلش ہوئی ہے وہ بشری تقاضون کے تحت ان کے اجتہادات کی بناء پر ہوئی۔اللہ تعالی انہیں معاف کرنے والا ہے۔اہل السنہ والجماعۃ قطعاًجائز نہیں سمجھتے کہ ان امور کو سرعام موضوع بحث بنایا جائے۔رضي الله عنهم وارضاهم۔"}],[4650,"ریاح بن حارث کہتے ہیں میں کوفہ کی مسجد میں فلاں شخص ۱؎ کے پاس بیٹھا تھا، ان کے پاس کوفہ کے لوگ جمع تھے، اتنے میں سعید بن زید بن عمرو بن نفیل رضی اللہ عنہ آئے، تو انہوں نے انہیں خوش آمدید کہا، اور دعا دی، اور اپنے پاؤں کے پاس انہیں تخت پر بٹھایا، پھر اہل کوفہ میں سے قیس بن علقمہ نامی ایک شخص آیا، تو انہوں نے اس کا استقبال کیا، لیکن اس نے برا بھلا کہا اور سب وشتم کیا، سعید بولے: یہ شخص کسے برا بھلا کہہ رہا ہے؟ انہوں نے کہا: علی رضی اللہ عنہ کو کہہ رہا ہے، وہ بولے: کیا میں دیکھ نہیں رہا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم کے اصحاب کو تمہارے پاس برا بھلا کہا جا رہا ہے لیکن تم نہ منع کرتے ہو نہ اس سے روکتے ہو، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے اور مجھے کیا پڑی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کی طرف سے ایسی بات کہوں جو آپ نے نہ فرمائی ہو کہ کل جب میں آپ سے ملوں تو آپ مجھ سے اس کے بارے میں سوال کریں: \"ابوبکر جنتی ہیں، عمر جنتی ہیں\" پھر اوپر جیسی حدیث بیان فرمایا، پھر ان (صحابہ) میں سے کسی کا رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی جنگ میں شرکت جس میں اس چہرہ غبار آلود ہو جائے یہ زیادہ بہتر ہے اس سے کہ تم میں کا کوئی شخص اپنی عمر بھر عمل کرے اگرچہ اس کی عمر نوح کی عمر ہو ۲؎۔\n§وضاحت\n۱؎ : اس سے مراد مغیرہ بن شعبہ رضی اللہ عنہ ہیں۔ ۲؎ : ایک شخص کا ایمان کی حالت میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جنگ میں شریک ہونا اور اس کا گرد و غبار برداشت کرنا غیر صحابی کی ساری زندگی کے عمل سے بہتر ہے چاہے اس کی زندگی کتنی ہی طویل اور نوح علیہ السلام کی زندگی کے برابر ہو جن کی صرف دعوتی زندگی ساڑھے نو سو سال تھی، اس سے صحابہ کرام کا احترام اور ان کی فضیلت واضح ہوتی ہے اسی لئے امت کا عقیدہ ہے کہ کوئی بڑے سے بڑا ولی کسی ادنی صحابی کے درجہ کو نہیں پہنچ سکتا، رضی اللہ عنہم اجمعین۔","صحیح",{"u2":"ریاح بن حارث کا بیان ہے کہ میں کوفہ کی مسجد میں فلاں کے پاس بیٹھا ہوا تھا۔ (اشارہ ہے سیدنا مغیرہ بن شعبہ رضی اللہ عنہ کی طرف) اور ان کے پاس اہل کوفہ کے کچھ لوگ بھی بیٹھے ہوئے تھے۔ تو سیدنا سعید بن زبیر بن عمرہ بن نفیل رضی اللہ عنہ تشریف لائے۔ پس انہوں (مغیرہ) نے انکو مرحبا کہا اور خوش آمدید کہا اور پھر انہیں اپنی چارپائی کی پائنتی کی طرف بٹھا لیا۔ پھر اہل کوفہ میں سے ایک شخص آیا جس کا نام قیس بن علقمہ تھا۔ انہوں نے اس کا بھی استقبال کیا۔ پھر اس نے بدگوئی کی اور بدگوئی کی۔ سعید نے پوچھا یہ کسے گالیاں دے رہا ہے؟ کہا: سیدنا علی رضی اللہ عنہ کو۔ تو سعید نے کہا: (تعجب ہے) میں دیکھ رہا ہوں کہ تمہارے سامنے اصحاب رسول اللہ صلی اللہ علیہ وسلم کو برا بھلا کہا جا رہا ہے اور آپ ہیں کہ اسے ٹوکتے ہی نہیں اور نہ سمجھاتے ہیں۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ صلی اللہ علیہ وسلم فر رہے تھے، اور مجھے کوئی ایسی نہیں پڑی کہ آپ صلی اللہ علیہ وسلم پر کوئی ایسی بات کہہ دوں جو آپ نے نہ کہی ہو پھر کل جب آپ سے میری ملاقات ہو اور وہ مجھ سے پوچھ لیں ” ابوبکر جنت میں ہے، عمر جنت میں ہے۔ “ اور مذکورہ بالا حدیث کے ہم معنی روایت کیا۔ پھر کہا ان میں سے کسی ایک کا رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (جہاد میں) حاضر رہنا اور اس کے چہرے کا غبار آلود ہو جانا تمہاری ساری زندگی کے اعمال سے کہیں بہتر ہے خواہ تمہیں سیدنا نوح علیہ السلام کی زندگی ہی کیوں نہ مل جائے۔"}],[4651,"انس بن مالک رضی اللہ عنہ بیان کرتے ہیں نبی اکرم صلی اللہ علیہ وسلم احد پہاڑ پر چڑھے پھر آپ کے پیچھے ابوبکر، عمر، عثمان رضی اللہ عنہم بھی چڑھے، تو وہ ان کے ساتھ ہلنے لگا، نبی اکرم صلی اللہ علیہ وسلم نے اسے اپنے پاؤں سے مارا اور فرمایا: \"ٹھہر جا اے احد!(تیرے اوپر) ایک نبی، ایک صدیق اور دو شہید ہیں ۱؎\"۔\n§وضاحت\n۱؎ : تیرے اوپر ایک نبی یعنی خود نبی اکرم صلی اللہ علیہ وسلم، ایک صدیق یعنی ابوبکر، اور دو شہید یعنی عمر اور عثمان رضی اللہ عنہم ہیں، یہ تیرے لئے باعث فخر ہے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا کہ اللہ کے نبی صلی اللہ علیہ وسلم احد پہاڑ پر چڑھے تو سیدنا ابوبکر، سیدنا عمر اور سیدنا عثمان رضی اللہ عنہما م بھی آپ صلی اللہ علیہ وسلم کے پیچھے چلے گئے، پس پہاڑ نے حرکت کی۔ تو نبی کریم صلی اللہ علیہ وسلم نے اس پر اپنا پاؤں مارا اور فرمایا &rdquo; احد! ٹھہر جا! (تیرے اوپر) ایک نبی، ایک صدیق اور دو شہید ہیں۔"}],[4652,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس جبرائیل آئے، انہوں نے میرا ہاتھ پکڑا، اور مجھے جنت کا وہ دروازہ دکھایا جس سے میری امت داخل ہو گی\" ابوبکر رضی اللہ عنہ نے کہا: اللہ کے رسول! میری خواہش ہے کہ آپ کے ساتھ میں بھی ہوتا تاکہ میں اسے دیکھتا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سنو اے ابوبکر! میری امت میں سے تم ہی سب سے پہلے جنت میں داخل ہو گے\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میرے پاس جبرائیل علیہ السلام آئے، میرا ہاتھ پکڑا اور مجھے جنت کا وہ دروازہ دکھلایا جس میں سے میری امت داخل ہو گی۔ “ تو سیدنا ابوبکر رضی اللہ عنہ نے کہا: اے اللہ کے رسول! میں پسند کرتا ہوں کاش میں بھی آپ کے ساتھ ہوتا حتیٰ کہ اسے دیکھ لیتا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم اے ابوبکر! یقیناً میری امت کے وہ فرد ہو جو سب سے پہلے جنت میں داخل ہو گے۔“"}],[4653,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جہنم میں ان لوگوں میں سے کوئی بھی داخل نہیں ہو گا، جنہوں نے درخت کے نیچے بیعت کی (یعنی صلح حدیبیہ کے وقت بیعت رضوان میں شریک رہے)\"۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ نے بیان کیا کہ بلاشبہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جنہوں نے درخت کے نیچے بیعت کی ہے ان میں سے کوئی بھی آگ میں داخل نہیں ہو گا۔“","f2":"سن6 ہجری میں حدیبیہ کے مقام پر حضرت عثمان کے قتل کیے جانے کی افواہ پر صحابہ رضی اللہ عنہ سے جو بیعت لی گئی تھی وہ کیکر کے درخت کے نیچے ہوئی تھی۔حدیث میں اسی کی طرف اشارہ ہے۔اللہ نے خود اس درخت کا ذکر فرماکر بیعت کرنے والوں کے بارے میں فرمایا:(رضی اللہ عنہم ورضواعنہ) اس لیےاسے بیعت رضوان کا نام دیا گیاہے۔اس میں صحابہ کی تعداد چودہ پندرہ سو تھی۔(صحيح البخاري المغازي حديث:٤١٥٣)"}],[4654,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: (موسی کی روایت میں «فلعل الله» کا لفظ ہے، اور ابن سنان کی روایت میں «اطلع الله» ہے) \"اللہ تعالی بدر والوں کی طرف متوجہ ہوا اور انہیں نظر رحمت و مغفرت سے دیکھا تو فرمایا: جو عمل چاہو کرو میں نے تمہیں معاف کر دیا ہے ۱؎\"۔\n§وضاحت\n۱؎ : اس کا مطلب یہ ہے کہ اگر ان اصحاب بدر صحابہ کرام رضی اللہ عنہم سے اس کے بعد کوئی عمل اللہ کی منشاء کے خلاف بھی ہو جائے تو وہ ان سے باز پرس نہ فرمائے گا کیونکہ ان کو معاف کر چکا ہے، اس کا یہ مطلب ہرگز نہیں ہے کہ ان کو بداعمالیوں کی اجازت دی جا رہی ہے یا یہ کہ ان سے دنیا میں بھی باز پرس نہ ہو گی بلکہ اگر خدانخواستہ وہ دنیا میں کوئی عمل قابل حد کر بیٹھے تو حد جاری کی جائے گی۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” شاید کہ اللہ تعالیٰ نے اہل بدر پر نظر فرمائی ہے اور کہا ہے کہ جو چاہے عمل کرو میں نے تمہیں بخش دیا ہے۔ “","f2":"۔جب دین کی سر بلندی کے لیے یہ لوگ خود کو قربان کرنے پر تل گئے تو ان کو اخلاص اور ایمان کا اعلی ترین معیار حاصل ہوگیا۔اس لیے ان کو ایسی عظیم خوشخبری دی گئی۔ان کا یہ عظیم عمل ان کے باقی تمام اعمال سے چاہے وہ مثبت ہوں یا منفی بہت بڑا تھا۔\n2۔حدیث میں مذکورہ فرمان کا یہ مفہوم ہرگز نہیں تھا کہ وہ شرعی اور اخلاقی حدود وقیود سے مبرا ہوگئے تھے۔نہیں بلکہ اس بیان میں ان کے متعلق اللہ تعالی کی طرف سے یہ خبر صادق ہے کہ یہ لوگ تا حیات دین وشریعت کے تقاضے پورے کرتے رہیں گےاور ان سے کوئی ایسا عمل سرزد نہیں ہوگا جو ان کے لیے اللہ عزوجل کی ناراضی یا جہنم میں جانے کا باعث ہو اس میں ان کے معصوم عن الخطا ہونے کا مفہوم نہیں ہے بلکہ بشارت ہے کہ ان کی تمام تقصیرات معاف کردی جائیں گی۔رضی اللہ عنہم۔توحیف ہے ان لوگوں پر جو ان کی اجتہادی خطاؤں کو نمایاں کرتے اور ان پر طعن و تشنیع کرنا اور تاریخ کی خدمت سمجھتے ہیں۔فان لله وانا اليه راجعون۔"}],[4655,"مسور بن مخرمہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم حدیبیہ کے زمانے میں نکلے، پھر راوی نے حدیث بیان کی، وہ کہتے ہیں کہ آپ کے پاس وہ یعنی عروہ بن مسعود آیا اور نبی اکرم صلی اللہ علیہ وسلم سے گفتگو کرنے لگا، جب وہ آپ سے بات کرتا، تو آپ کی ڈاڑھی پر ہاتھ لگاتا، مغیرہ بن شعبہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کے پاس کھڑے تھے، ان کے پاس تلوار تھی اور سر پر خود، انہوں نے تلوار کے پر تلے کے نچلے حصہ سے اس کے ہاتھ پر مارا اور کہا: اپنا ہاتھ ان کی ڈاڑھی سے دور رکھ، عروہ نے اپنا سر اٹھایا اور بولا: یہ کون ہے؟ لوگوں نے کہا: مغیرہ بن شعبہ ہیں۔","صحیح",{"u2":"سیدنا مسور بن مخرمہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم حدیبیہ کے دنوں میں روانہ ہوئے، اور حدیث بیان کی، کہا کہ پھر (مشرکین کی طرف سے) عروہ بن مسعود آیا اور نبی کریم صلی اللہ علیہ وسلم سے بات کرنے لگا اور اس اثنا میں وہ آپ صلی اللہ علیہ وسلم کی ڈاڑھی مبارک کو بھی ہاتھ لگاتا تھا۔ جبکہ سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم کے سر پر کھڑے ہوئے تھے، ان کے ہاتھ میں تلوار اور سر پر خود تھی۔ تو انہوں نے اپنی تلوار کے دستے سے عروہ کے ہاتھ کو ٹھوکا دیا اور کہا: آپ کی ڈاڑھی مبارک سے اپنا ہاتھ دور رکھ۔ عروہ نے اپنا سر اوپر اٹھایا اور پوچھا یہ کون ہے؟ صحابہ نے کہا: یہ سیدنا مغیرہ بن شعبہ ہیں۔ (رضی اللہ عنہ)","f2":"امام ابو داود کے اسلوب سے واضح ہوتا ہے کہ اوپر کی احادیث میں حضرت مغیرہ رضی اللہ عنہ نے حضرت معاویہ رضی اللہ عنہ کی جو سیاسی حمایت کی ہے وہ ان کے شرف صحابیت اور اللہ کے ہاں ان کے مقام کی منافی نہیں ہے۔ صرف یہ ہی نہیں بلکہ دیگر کتنے ہی صحابہ تھےجو اپنی اپنی سوچ کے مطابق حضرت علی رضی اللہ عنہ یا حضرت معاویہ رضی اللہ عنہ کے حامی یا مخالف تھےاور یہ سب ان کے اجتہادات تھے۔اس لیے ہم کسی کو بھی صراحت سے غلط کہنے کے مجاز ہوتو ان کے شرف صحابیت رسول اللہ صلی اللہ علیہ وسلم کے لیے ان کی وفا شعار ی اور ان بشارتوں کے پیش نظر جو رسول اللہ صلی اللہ علیہ وسلم نے انکے متعلق فرمائی ہیں صرف نظرکرنااور ان کے فعال کی تاویل کرنا واجب ہے۔(رضي الله تعالي عنهم وارضاهم)"}],[4656,"عمر بن خطاب رضی اللہ عنہ کے مؤذن اقرع کہتے ہیں مجھے عمر نے ایک پادری کے پاس بلانے کے لیے بھیجا، میں اسے بلا لایا، تو عمر نے اس سے کہا: کیا تم کتاب میں مجھے (میرا حال) پاتے ہو؟ وہ بولا: ہاں، انہوں نے کہا: کیسا پاتے ہو؟ وہ بولا: میں آپ کو قرن پاتا ہوں، تو انہوں نے اس پر درہ اٹھایا اور کہا: قرن کیا ہے؟ وہ بولا: لوہے کی طرح مضبوط اور سخت امانت دار، انہوں نے کہا: جو میرے بعد آئے گا تم اسے کیسے پاتے ہو؟ وہ بولا: میں اسے نیک خلیفہ پاتا ہوں، سوائے اس کے کہ وہ اپنے رشتہ داروں کو ترجیح دے گا، عمر نے کہا: اللہ عثمان پر رحم کرے، (تین مرتبہ) پھر کہا: ان کے بعد والے کو تم کیسے پاتے ہو؟ وہ بولا: وہ تو لوہے کا میل ہے (یعنی برابر تلوار سے کام رہنے کی وجہ سے ان کا بدن اور ہاتھ گویا دونوں ہی زنگ آلود ہو جائیں گے) عمر نے اپنا ہاتھ اس کے سر پر رکھا، اور فرمایا: اے گندے! بدبودار (تو یہ کیا کہتا ہے) اس نے کہا: اے امیر المؤمنین! وہ ایک نیک خلیفہ ہو گا لیکن جب وہ خلیفہ بنایا جائے گا تو حال یہ ہو گا کہ تلوار بے نیام ہو گی، خون بہہ رہا ہو گا، (یعنی اس کی خلافت فتنہ کے وقت ہو گی) ۔ ابوداؤد کہتے ہیں: «الدفر» کے معنی «نتن» یعنی بدبو کے ہیں۔","ضعیف الإسناد",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ کے مؤذن جناب اقرع رضی اللہ عنہ نے بیان کیا کہ سیدنا عمر رضی اللہ عنہ نے مجھے عیسائیوں کے مذہبی سردار کے پاس بھیجا۔ میں اسے بلا لایا۔ سیدنا عمر رضی اللہ عنہ نے اس سے پوچھا: کیا تم اپنی کتاب میں میرا ذکر پاتے ہو؟ کہا: ہاں۔ پوچھا کیسے؟ کہا: میں پاتا ہوں کہ آپ ایک قرن ہیں۔ سیدنا عمر رضی اللہ عنہ نے اپنا درہ اس پر بلند کیا اور پوچھا ” قرن “ سے کیا مراد ہے؟ کہا: بہت سخت فولادی قلعہ، انتہائی امین۔ سیدنا عمر رضی اللہ عنہ نے پوچھا جو میرے بعد آئے گا اس کے بارے میں کیا پاتے ہو؟ کہا: وہ ایک صالح خلیفہ ہو گا، صرف اتنا ہو گا کہ وہ اپنے قرابت داروں کو ترجیح دے گا۔ سیدنا عمر رضی اللہ عنہ نے کہا: اللہ سیدنا عثمان رضی اللہ عنہ پر رحم فرمائے، تین بار کہا۔ پھر پوچھا: ان کے بعد جو آئے گا اس کے بارے میں کیا پاتے ہو؟ کہا: میں اسے پاتا ہوں کہ وہ لوہے کا زنگ ہو گا۔ تو سیدنا عمر رضی اللہ عنہ نے اپنا ہاتھ اپنے سر پر رکھ لیا اور کہا: اے بدبودار! اے بدبودار! (کیا کہہ رہے ہو؟) تو اس نے کہا: امیر المؤمنین! یہ صالح خلیفہ ہو گا مگر جب اسے یہ منصب ملے گا تو تلواریں نکلی ہوئی ہوں گی اور خون بہائے جا رہے ہوں گے۔ امام ابوداؤد رضی اللہ عنہ نے کہا کہ «الدفر» کے معنی ہیں ” بدبو “۔","f2":"مسلمانوں میں اہل کتاب کی اس قسم کی روایات کی بصراحت تصدیق یا تکذیب نہیں کی جاتی صرف روایت کی اجازت ہے۔"}],[4657,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میری امت کے سب سے بہتر لوگ وہ ہیں جن میں مجھے مبعوث کیا گیا، پھر وہ جو ان سے قریب ہیں، پھر وہ جو ان سے قریب ہیں\" اللہ ہی زیادہ جانتا ہے کہ آپ صلی اللہ علیہ وسلم نے تیسرے کا ذکر کیا یا نہیں، \"پھر کچھ لوگ رونما ہوں گے جو بلا گواہی طلب کئے گواہی دیتے پھریں گے، نذر مانیں گے لیکن پوری نہ کریں گے، خیانت کرنے لگیں گے جس سے ان پر سے بھروسہ اٹھ جائے گا، اور ان میں موٹاپا عام ہو گا ۱؎\"۔\n§وضاحت\nوضاحت ۱؎ : کیونکہ جواب دہی کا خوف ان کے دلوں سے جاتا رہے گا، عیش وآرام کے عادی ہو جائیں گے اور دین و ایمان کی فکر جاتی رہے گی جو ان کے مٹاپے کا سبب ہوگی۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میری امت کا بہترین زمانہ یہی ہے جس میں میں مبعوث کیا گیا ہوں، پھر وہ جو ان سے متصل ہوں گے، اور پھر وہ جو ان سے متصل ہوں گے۔ واللہ اعلم آپ نے یہ تیسری بار فرمایا کہ نہیں، پھر ان کے بعد ایسے لوگ آئیں گے جو گواہیاں دیں گے حالانکہ ان سے گواہی مانگی نہ گئی ہو گی، نذریں مانیں گے مگر پوری نہیں کریں گے۔ خیانتیں کریں گے اور ان پر اعتماد نہیں کیا جائے گا اور ان میں موٹاپا بھی عام ہو گا۔ “","f2":"1۔اس صحیح حدیث میں صحابہ کرام تابعین عظام اور تبع تابعین کے ادوارکے متعلق اجمالی اور مجموعی طور پر بھلائی کی خبر دی گئی ہے۔\n2۔ان کے بعد وقار میں کمی ہوگی۔دینداری میں ضعف آجائے گااور آخرت کی فکر کم ہوجائے گی۔\n3۔اطباء کے قول کے مطابق آدمی کے جسم میں موٹاپا عام طور پر خوش خورا کی کے علاوہ بے فکری اور بے خوفی کی بناء پر آتا ہے۔"}],[4658,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے صحابہ کو برا بھلا نہ کہو، اس ذات کی قسم! جس کے ہاتھ میں میری جان ہے، اگر تم میں سے کوئی احد (پہاڑ) کے برابر سونا خرچ کر دے تو وہ ان کے ایک مد یا نصف مد کے برابر بھی نہ ہو گا ۱؎\"۔\n§وضاحت\n۱؎ : اس حدیث کا شان ورود یہ ہے کہ ایک بار عبدالرحمن بن عوف رضی اللہ عنہ اور خالد بن ولید رضی اللہ عنہ کے درمیان کچھ کہا سنی ہو گئی جس پر خالد نے عبدالرحمن کو کچھ نامناسب الفاظ کہہ دیئے، جس پر رسول اکرم صلی اللہ علیہ وسلم نے یہ فرمایا، اس سے پتہ چلا کہ مخصوص اصحاب کے مقابلہ میں دیگر صحابہ کرام کا یہ حال ہے تو غیر صحابی کا کیا ذکر، غیر صحابی کا احد پہاڑ کے برابر سونا خرچ کرنا صحابی کے ایک مُد غلہ کے برابر بھی نہیں ہو سکتا، اس سے صحابہ کرام رضی اللہ عنہم کے مقام عالی کا پتہ چلتا ہے، اور یہیں سے ان بدبختوں کی بدبختی اور بدنصیبی کا اندازہ کیا جا سکتا ہے جن کے مذہب کی بنیاد صحابہ کرام کو سب وشتم کا نشانہ بنانا اور تبرا بازی کو دین سمجھنا ہے۔","صحیح",{"u2":"سیدنا ابوسعید (ابوسعید خدری) رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میرے صحابہ کی بدگوئی مت کرو۔ قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! اگر تم میں سے کوئی احد پہاڑ جتنا سونا بھی خرچ کر ڈالے تو وہ ان کے ایک مد یا آدھے کو بھی نہیں پہنچ سکتا۔ “ سیدنا ابوسعید رضی اللہ عنہ نے کہا: ہمیں عطاردی نے حدیث بیان کی، اس نے کہا: ہمیں ابومعاویہ نے بیان کیا اور حدیث بیان کی۔"}],[4659,"عمرو بن ابی قرہ کہتے ہیں کہ حذیفہ رضی اللہ عنہ مدائن میں تھے اور وہ ان باتوں کا ذکر کیا کرتے تھے، جو رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب میں سے بعض لوگوں سے غصہ کی حالت میں فرمائی تھیں، پھر ان میں سے کچھ لوگ جو حذیفہ سے باتیں سنتے چل کر سلمان رضی اللہ عنہ کے پاس آتے اور ان سے حذیفہ رضی اللہ عنہ کی باتوں کا تذکرہ کرتے تو سلمان رضی اللہ عنہ کہتے: حذیفہ ہی اپنی کہی باتوں کو بہتر جانتے ہیں، تو وہ لوگ حذیفہ کے پاس لوٹ کر آتے اور ان سے کہتے: ہم نے آپ کی باتوں کا تذکرہ سلمان سے کیا تو انہوں نے نہ آپ کی تصدیق کی اور نہ تکذیب، یہ سن کر حذیفہ سلمان کے پاس آئے، وہ اپنی ترکاری کے کھیت میں تھے کہنے لگے: اے سلمان! ان باتوں میں میری تصدیق کرنے سے آپ کو کون سی چیز روک رہی ہے جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہیں؟ تو سلمان نے کہا: رسول اللہ صلی اللہ علیہ وسلم بلاشبہ کبھی غصے میں اپنے بعض اصحاب سے کچھ باتیں کہہ دیتے اور کبھی خوش ہوتے تو خوشی میں اپنے بعض اصحاب سے کچھ باتیں کہہ دیتے، تو کیا آپ اس وقت تک باز نہ آئیں گے جب تک کہ بعض لوگوں کے دلوں میں بعض لوگوں کی محبت اور بعض دوسروں کے دلوں میں بعض کی دشمنی نہ ڈال دیں اور ان کو اختلاف میں مبتلا نہ کر دیں، حالانکہ آپ جانتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ایک خطبہ میں فرمایا: \"میں نے اپنی امت کے کسی فرد کو غصے کی حالت میں اگر برا بھلا کہا یا اسے لعن طعن کی تو میں بھی تو آدم کی اولاد میں سے ہوں، مجھے بھی غصہ آتا ہے جیسے انہیں آتا ہے، لیکن اللہ نے مجھے رحمۃ للعالمین بنا کر بھیجا ہے تو (اے اللہ) میرے برا بھلا کہنے اور لعن طعن کو ان لوگوں کے لیے قیامت کے روز رحمت بنا دے\" اللہ کی قسم یا تو آپ اپنی اس حرکت سے باز آ جائیں ورنہ میں عمر بن الخطاب (امیر المؤمنین) کو لکھ بھیجوں گا۔","صحیح",{"u2":"عمرو بن ابوقرہ نے بیان کیا کہ اپنے صحابہ سے کچھ کہتے تھے، تو کیا آپ اپنے اس انداز سے باز نہیں آ سکتے۔ کیا آپ لوگوں کے دلوں میں کچھ کی محبت پیدا کرنا چاہتے ہیں اور کچھ کے متعلق بغض ڈال دینا چاہتے ہیں؟ اس طرح تو آپ ان لوگوں میں اختلاف و افتراق پیدا کر دیں گے، حالانکہ میں بخوبی جانتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک خطبہ دیا اور فرمایا تھا: ” (اے اللہ!) اپنی امت کے جس کسی کو میں نے کبھی کوئی برا بھلا کہا: ہو یا ناراضی کی حالت میں لعنت کی ہو تو میں بھی آدم زاد ہوں، جس طرح وہ غصے میں آ جاتے ہیں میں بھی آ جاتا ہوں اور مجھے جہان والوں کے لیے رحمت بنا کر بھیجا ہے (یا اللہ! میری ان باتوں کو) ان کے لیے قیامت کے روز رحمت بنا دے۔ “ (اے حذیفہ!) اللہ کی قسم! تم باز آ جاؤ یا میں عمر رضی اللہ عنہ کو لکھ بھیجوں گا۔ پھر کچھ لوگوں نے ان سے سفارش کی تو انہوں نے اپنی قسم کا کفارہ ادا کر دیا اور سیدنا عمر رضی اللہ عنہ کو نہ لکھا۔ اور کفارہ بھی قسم توڑنے سے پہلے دیا۔ امام ابوداؤد رضی اللہ عنہ نے کہا: قسم کا کفارہ، قسم توڑنے سے پہلے ادا کرنا یا بعد میں ادا کرنا سب جائز ہے۔","f2":"کسی بھی شخص کو خواہ وہ ذاتی طور پر کتنا بھی خیر وفلاح کے درجے پر فائز ہو اس بات کی اجازت نہیں دی جاسکتی کہ عوام میں صحابہ کرام رضوان اللہ اجمعین کی تقصیرات کی اشاعت کرے کی ان میں سے کچھ کے تعلق محبت اور کچھ کے متعلق بغض پیدا ہوجائیں اور لوگ اس قدسی جماعت کے بارے میں شکوک وشبہات کا شکار ہوں اور ان میں تفرقہ پیدا ہوجائے تاہم ایک محدود خاص علمی حلقے میں قابل اعتماد اصحاب علم وفضل کے سامنے ان امور کا تذکرہ بطور افہام و تفہیم جائز ہے۔"}],[4660,"حارث بن ہشام عبداللہ بن زمعہ رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کی بیماری سخت ہوئی اور میں آپ ہی کے پاس مسلمانوں کی ایک جماعت کے ساتھ تھا تو بلال رضی اللہ عنہ نے آپ کو نماز کے لیے بلایا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کسی سے کہو جو لوگوں کو نماز پڑھائے\" عبداللہ بن زمعہ نکلے تو دیکھا کہ لوگوں میں عمر رضی اللہ عنہ موجود ہیں، ابوبکر رضی اللہ عنہ موقع پر موجود نہ تھے، میں نے کہا: اے عمر! اٹھیے نماز پڑھائیے، تو وہ بڑھے اور انہوں نے اللہ اکبر کہا، وہ بلند آواز شخص تھے، رسول اللہ صلی اللہ علیہ وسلم نے جب ان کی آواز سنی تو فرمایا: \"ابوبکر کہاں ہیں؟ اللہ کو یہ پسند نہیں اور مسلمانوں کو بھی، اللہ کو یہ پسند نہیں اور مسلمانوں کو بھی\" تو ابوبکر رضی اللہ عنہ کو بلا بھیجا، وہ عمر کے نماز پڑھا چکنے کے بعد آئے تو انہوں نے لوگوں کو (پھر سے) نماز پڑھائی۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے خلافت صدیقی کا صاف اشارہ ملتا ہے کیونکہ امامت صغری امامت کبری کا پیش خیمہ ہے۔","حسن صحیح",{"u2":"جناب عبداللہ بن زمعہ رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کی تکلیف بہت بڑھ گئی اور میں مسلمانوں کی ایک جماعت کے ساتھ آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر تھا کہ سیدنا بلال رضی اللہ عنہ نے آپ کو نماز کے لیے بلایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کسی سے کہہ دو، وہ لوگوں کو نماز پڑھا دے۔ “ عبداللہ بن زمعہ رضی اللہ عنہ کہتے ہیں کہ میں نکلا تو سیدنا عمر رضی اللہ عنہ موجود تھے جب کہ سیدنا ابوبکر رضی اللہ عنہ موجود نہیں تھے۔ میں نے کہا: اے عمر! اٹھیے اور لوگوں کو نماز پڑھا دیجئیے۔ چنانچہ وہ آگے بڑھے اور تکبیر کہ۔ (ادھر) جب رسول اللہ صلی اللہ علیہ وسلم نے ان کی آواز سنی اور سیدنا عمر رضی اللہ عنہ بلند آواز آدمی تھے تو فرمایا ” ابوبکر کہاں ہیں؟ اللہ اس کا انکار کرتا ہے اور مسلمان بھی۔ اللہ اس کا انکار کرتا ہے اور مسلمان بھی۔ “ پس آپ صلی اللہ علیہ وسلم نے سیدنا ابوبکر رضی اللہ عنہ کو بلا بھیجا تو وہ آ گئے جبکہ سیدنا عمر رضی اللہ عنہ لوگوں کو نماز پڑھا چکے تھے، پھر سیدنا ابوبکر رضی اللہ عنہ نے لوگوں کو وہی نماز پڑھائی۔"}],[4661,"عبیداللہ بن عبداللہ بن عتبہ سے روایت ہے کہ عبداللہ بن زمعہ رضی اللہ عنہ نے انہیں یہی بات بتائی اور کہا: جب نبی اکرم صلی اللہ علیہ وسلم نے عمر رضی اللہ عنہ کی آواز سنی تو آپ نکلے یہاں تک کہ حجرے سے اپنا سر نکالا، پھر فرمایا: \"نہیں، نہیں، نہیں، ابن ابی قحافہ(یعنی ابوبکر) کو چاہیئے کہ لوگوں کو نماز پڑھائیں\" آپ صلی اللہ علیہ وسلم یہ غصے میں فرما رہے تھے۔","صحیح",{"u2":"جناب عبداللہ بن زمعہ رضی اللہ عنہ نے یہ خبر بیان کی کہ جب نبی کریم صلی اللہ علیہ وسلم نے سیدنا عمر رضی اللہ عنہ کی آواز سنی تو آپ صلی اللہ علیہ وسلم تشریف لائے، اپنا سر مبارک حجرے سے نکالا اور فرمایا ” نہیں۔ نہیں۔ نہیں۔ ابن ابی قحافہ (ابوبکر رضی اللہ عنہ) لوگوں کو نماز پڑھائیں۔ “ آپ صلی اللہ علیہ وسلم نے یہ بات ناراضی کی کیفیت میں فرمائی۔","f2":"1: رسول صلی اللہ علیہ وسلم کی آخری بیماری کے ایام میں پہلی نماز حضرت عمر رضی اللہ نے پڑھائی،بعدازاں سیدنا ابو بکر رضی اللہ پڑھاتے رہے اور نبی صلی اللہ علیہ وسلم کی حیات مبارکہ میں ان کی پڑھائی ہوئی نمازوں کی تعداد سترہ ہے۔\n2: رسول صلی اللہ علیہ وسلم کا حضرت ابو بکر رضی اللہ کے لئے اصرارخصوصا یہ لفظ کہ (اس سے فرماتا ہے اور مسلمان انکار کرتے ہیں ابو بکر کے علاوہ کوئی اور نمازپڑھائے)ان کی خلیفہ ہونے کا واضح اشارہ بلکہ اس بات کی شہادت تھی کہ وہ مسلمانوں کافطری انتخاب ہیں۔\n3: اس واقعہ میں حضرت عمر فاروق رضی اللہ کی کوئی تنقیص نہیں ہوئی بلکہ یہ حضرت ابو بکر رضی اللہ کا وہ شرف تھا جسے حضرت عمر رضی اللہ اور تمام صحابہ کرام رضی اللہ اس سے پہلے تسلیم کرتے تھے۔"}],[4662,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حسن بن علی رضی اللہ عنہما کو فرمایا: \"میرا یہ بیٹا سردار ہے اور مجھے امید ہے کہ اللہ تعالی اس کے ذریعے میری امت کے دو گروہوں میں صلح کرائے گا\"۔ حماد کی روایت میں ہے: \"شاید اللہ تعالی اس کے ذریعے مسلمانوں کے دو بڑے گروہوں میں صلح کرائے گا ۱؎\"۔\n§وضاحت\n۱؎ : یہ پیشین گوئی رسول اللہ صلی اللہ علیہ وسلم کی اس طرح سچ ثابت ہوئی کہ حسن رضی اللہ عنہ نے معاویہ رضی اللہ عنہ سے صلح کر لی اور ایک عظیم فتنہ کو ختم کر دیا یہ سال اتحاد ملت کا سال تھا۔","صحیح",{"u2":"سیدنا ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا حسن بن علی رضی اللہ عنہ کے متعلق فرمایا ” میرا یہ بیٹا سردار ہے اور مجھے امید ہے کہ اللہ تعالیٰ اس کے ذریعے سے میری امت کے دو گروہوں میں صلح کرا دے گا۔ “ حماد کی روایت کے الفاظ ہیں: ” اور امید ہے کہ اللہ تعالیٰ اس کے ذریعے سے مسلمانوں کے دو بڑے گروہوں میں صلح کرا دے گا۔“","f2":"1: حضرت علی رضی اللہ کے دور میں سیدنا عثمان رضی اللہ کی شہادت کی بنا پر ہر مسلمان دو گرہوں میں بٹ گئے تھے۔ ایک طرف علی رضی اللہ تھے اوردوسری طرف حضرت معاویہ رضی اللہ اور دونوں ہی اپنی اپنی ترجیحات میں بر حق تھے،تاہم سیدنا علی رضی اللہ کا موقف اقرب الی الحق تھا۔\n2: سیدنا حسن رضی اللہ نے اپنی خلافت سے دست بردارہو کر ایک عظیم کارنامہ سرانجام دیا اور اس کی وجہ سے ان کے شرف سیادت میں اور اضافہ ہو گیا۔ مگر کچھ لوگوں کو اب تک ان کا یہ عمل ناپسند ہے۔\n3: رسول صلی اللہ علیہ وسلم نے دونوں اطراف کے لوگوں کو اپنی امت کے مسلمان قراردیا ہے اورکسی کو بھی گمراہ یا باطل نہیں فرمایا۔\n4: صحابہ کرام یا پھر فقہا ءوائمہ کی اجتہادی غلطیوں کی اشاعت کرنا بہت بڑا اور برا فتنہ ہے،صرف خاص محدود علمی حلقہ میں ان کے مسائل کی علمی تفہیم جائز ہے۔"}],[4663,"محمد بن سیرین کہتے ہیں کہ حذیفہ رضی اللہ عنہ نے کہا: لوگوں میں کوئی ایسا نہیں جس کو فتنہ پہنچے اور مجھے اس کے فتنے میں پڑنے کا خوف نہ ہو، سوائے محمد بن مسلمہ کے کیونکہ ان کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہیں کوئی فتنہ ضرر نہ پہنچائے گا\"۔","صحیح",{"u2":"جناب محمد بن سیرین رضی اللہ عنہ نے روایت کیا کہ سیدنا حذیفہ رضی اللہ عنہ نے کہا کہ لوگوں میں کوئی ایسا نہیں کہ اسے کوئی فتنہ درپیش ہو (اور وہ اس سے محفوظ رہے) مجھے اندیشہ رہتا ہے کہ وہ اس میں مبتلا ہو جائے گا، سوائے محمد بن مسلمہ رضی اللہ عنہ کے، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم (انہیں) فر رہے تھے: ” تجھے فتنہ نقصان نہیں دے گا۔“","f2":"اس کی واحد وجہ اللہ تعالی کے خاص فضل کے بعدان کا فتنوں سے الگ تھلگ رہ کر تنہائی اختیار کرلینا تھا جیسے کہ درج ذیل روایت میں آرہا ہے لیکن اس کا یہ مفہوم بھی نہیں کہ انسان لوگوں پر موثر ہو سکتا ہو اس کی بات سنی جاتی ہو تو وہ خاموش تماشائی بنارہے اور امر بالمعروف اور نہی عن المنکر کا فریضہ سر انجام نہ دے بلکہ یہ اس صورت میں ہے جب آدی کوئی اہم کرداراداکرنے کی حالت میں نہ ہو تو اس وقت الگ تھلگ رہنے ہ میں عافیت ہوتی ہے۔"}],[4664,"ثعلبہ بن ضبیعہ کہتے ہیں کہ ہم حذیفہ رضی اللہ عنہ کے پاس گئے تو آپ نے کہا: میں ایک ایسے شخص کو جانتا ہوں جسے فتنے کچھ بھی ضرر نہ پہنچا سکیں گے، ہم نکلے تو دیکھا کہ ایک خیمہ نصب ہے، ہم اندر گئے تو اس میں محمد بن مسلمہ رضی اللہ عنہ ملے، ہم نے ان سے پوچھا (کہ آبادی چھوڑ کر خیمہ میں کیوں ہیں؟) تو فرمایا: میں نہیں چاہتا کہ تمہارے شہروں کی کوئی برائی مجھ سے چمٹے، اس لیے جب تک فتنہ فرو نہ ہو جائے اور معاملہ واضح اور صاف نہ ہو جائے شہر کو نہیں جاؤں گا۔","صحیح",{"u2":"جناب ثعلبہ بن ضبیعہ کہتے ہیں کہ ہم سیدنا حذیفہ رضی اللہ عنہ کے ہاں گئے تو انہوں نے کہا: میں یقیناً اس آدمی کو جانتا ہوں جسے فتنے کوئی نقصان نہیں پہنچا سکیں گے۔ کہا کہ پھر ہم ان کے ہاں سے نکلے تو ہمیں ایک خیمہ نظر آیا، ہم اس میں چلے گئے، تو دیکھا کہ اس میں سیدنا محمد بن مسلمہ رضی اللہ عنہ ہیں۔ ہم نے ان سے اس (تنہائی اور گوشہ گیری) کے متعلق پوچھا تو انہوں نے کہا: میں نہیں چاہتا کہ تمہارے شہروں کا کوئی فتنہ مجھے اپنی لپیٹ میں لے لے حتیٰ کہ یہ صورت حال صاف ہو جائے (فتنے ختم ہو جائیں)۔"}],[4665,"ضبیعہ بن حصین ثعلبی سے بھی اسی مفہوم کی حدیث مروی ہے۔","صحیح",{"u2":"ابوبردہ نے بیان کیا کہ صبیعہ بن حصین ثعلبی نے مذکورہ بالا کے ہم معنی روایت کیا۔"}],[4666,"قیس بن عباد کہتے ہیں کہ میں نے علی رضی اللہ عنہ سے کہا: ہمیں آپ (معاویہ رضی اللہ عنہ سے جنگ کے لیے) اپنی اس روانگی کے متعلق بتائیے کہ آیا رسول اللہ صلی اللہ علیہ وسلم کا کوئی حکم ہے جو انہوں نے آپ کو دیا ہے یا آپ کا اپنا خیال ہے جسے آپ درست سمجھتے ہیں، وہ بولے: مجھے رسول اللہ صلی اللہ علیہ وسلم نے کوئی حکم نہیں دیا بلکہ یہ میری رائے ہے۔","صحیح الإسناد",{"u2":"جناب قیس بن عباد کہتے ہیں کہ میں نے سیدنا علی رضی اللہ عنہ سے پوچھا: آپ کا (سیدنا معاویہ رضی اللہ عنہ کے مقابلے میں) نکلنا رسول اللہ صلی اللہ علیہ وسلم کے فرمان کی بنا پر ہے یا یہ آپ کی اپنی ذاتی رائے ہے؟ انہوں نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے کچھ نہیں فرمایا تھا، بلکہ یہ میری اپنی ذاتی رائے ہے۔","f2":"صحابہ کرام رضی اللہ کے تنازعات ان کی اپنی اجتہاد آراء تھیں جن میں سے ایک فریق برحق اوردوسرا اس کے بر خلاف تھا،مگر بوجہ اخلاص اور حسن نیت دونوں ہی ماجورتھے اور حضرت معاویہ رضی اللہ کے مقابلے میں حضرت علی رضی اللہ اقرب الی الحق تھے۔"}],[4667,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمانوں میں اختلاف کے وقت ایک فرقہ نکلے گا جسے دونوں گروہوں میں سے جو حق سے قریب تر ہو گا قتل کرے گا\"۔","صحیح",{"u2":"سیدنا ابوسعید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مسلمانوں میں افتراق کے وقت ایک فتنہ انگیز جماعت نکلے گی جسے مسلمانوں کا وہ گروہ قتل کرے گا جو حق کے زیادہ قریب ہو گا۔“","f2":"1: مسلمانوں میں مختلف آرا کے حامل افرا د یا جماعتوں کا وجود ہو سکتا ہے جن میں سے یقینا ایک ہی حق پر ہو گا اور دوسرااس سے بعید۔ مگر جب تک کوئی واضح صریح باطل فکروعمل سامنے نہ آئے ان کی ضلالت کا حکم نہ لگایا جائے۔ بلکہ علم وحکمت سے تفہیم ہونی چاہیے اور حتی الامکان ان کی اشاعت اور تشہیر سے خاموشی اختیار کی جائے،اسی سے وہ فتنہ دن سکے گا۔\n2: اس حدیث میں خوارج کے ظہور کی پیشین گوئی کا بیان ہے،یہ حدیث نبی صلی اللہ علیہ وسلم کی صداقت کی ایک دلیل ہے کیونکہ خوارج کا جس وقت ظہور ہوا م،وہ اس حدیث کے عین مطابق ہے،یہ 32،38 ہجری کا واقعہ ہے جب حضرت علی اور حضرت معاویہ رضی اللہ کے درمیان لڑائی جاری تھی۔ اس وقت نہروان سے فرقہ خوارج کا ظہورہوا اورحضرت علی رضی اللہ نے ان سے جنگ کی اور انہیں شکست فاش دی۔ اسی قسم کی احادیث کی بنا پر حضرت علی رضی اللہ کو حضرت معاویہ کے مقابلے میں اقرب الی الحق کہا جاتا ہے۔\n3: اس میں باہم لڑنے والے دونوں گروہوں کو مسلمان کہا گیا ہے،اس لئے حضرت علی اور حضرت معاویہ رضی اللہ دونوں اور ان کے ساتھیوں کے بارے میں طعن وتشنیع کی بجائے کف لسان (خاموشی) ضروری ہے،کیونکہ دونوں ہی مسلمان اورحق پر تھے،گو ایک احق (زیادہ صحیح) تھا۔\n4: فتنہ انگیز یا دین سے نکل جانے والا گروہ خوارج کا تھا،نہ کہ حضرت علی یا حضرت معاویہ رضی اللہ کا گروہ تھا،وہ دونوں تو مسلمانوں کے عظیم گروہ تھے۔"}],[4668,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"نبیوں کو ایک دوسرے پر فضیلت نہ دو ۱؎\"۔\n§وضاحت\n۱؎ : اس کے یہ معنی نہیں کہ انبیاء فضیلت میں برابر ہیں، بلکہ مطلب یہ ہے کہ اپنی طرف سے ایسا مت کرو ، یا مطلب یہ ہے کہ ایک کو دوسرے پر ایسی فضیلت نہ دو کہ دوسرے کی تنقیص لازم آئے، یا یہ ہے کہ نفس نبوت میں سب برابر ہیں، خصائص اور فضائل میں ایک دوسرے پر فوقیت رکھتے ہیں ،جیسا کہ اللہ نے فرمایا : «تلك الرسل فضلنا بعضهم على بعض» ۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” انبیاء کو ایک دوسرے پر فضیلت و ترجیح مت دیا کرو۔“","f2":"بلا شبہ انبیا ورسل صلی اللہ علیہ وسلم میں بعض پر فضیلت حاصل ہے اور قرآن مجید نے واضح طور بیان کیا ہے،مگر ان فضائل کا اس انداز سے تقابلی بیان کہ دوسروں کی تنقیص لازم آئے،حرام ہے۔"}],[4669,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کسی بندے کے لیے درست نہیں کہ وہ کہے کہ میں یونس بن متی سے بہتر ہوں ۱؎\"۔\n§وضاحت\n۱؎ : اس میں اس بات سے منع کیا گیا ہے کہ کوئی شخص اپنے کو یونس علیہ السلام سے افضل کہے، کیونکہ غیر نبی کبھی کسی بھی نبی سے افضل نہیں ہو سکتا، یا یہ کہ یونس علیہ السلام پر نبی اکرم صلی اللہ علیہ وسلم کو فضیلت دے اس صورت میں آپ کا یہ فرمانا بطور تواضع ہو گا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کسی بندے کو لائق نہیں کہ وہ یوں کہے کہ میں (محمد صلی اللہ علیہ وسلم) سیدنا یونس بن متی علیہ السلام سے بہتر ہوں۔","f2":"کسی بندے کو لائق نہیں ان الفاظ سے سمجھا جا سکتا ہے کہ نبی صلی اللہ علیہ وسلم کے علاوہ کسی اور کو اس طرح کہنا جائز نہیں اور اگر نبی صلی اللہ علیہ وسلم خود بھی اس میں شامل ہوں جیسے کہ درج ذیل روایت میں ہے تو اس میں آپ کی ازحد تواضع کا اظہار ہے۔"}],[4670,"عبداللہ بن جعفر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: \"کسی نبی کے لیے یہ کہنا مناسب نہیں کہ میں یونس بن متی سے بہتر ہوں\"۔","صحیح لغیرہ",{"u2":"سیدنا عبداللہ بن جعفر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے ” کسی نبی کو لائق نہیں کہ یوں کہے کہ میں سیدنا یونس بن متی علیہ السلام سے بہتر ہوں۔“","f2":"حضرت یونس کا نام اس لئے لیا کہ انہی کے بارے میں وضاحت آتی ہے کہ بغیر اجازت بستی چھوڑکے چلے گئے اس پر وہ مچھلی کے پیٹ میں پہنچا دیے گئے اور تیرے سوا کوئی معبود نہیں تو پاک ہے،بلا شبہ میں ہی ظالموں میں سے ہوں۔ (الانبیا 84) کا ورد کرتے رہے اس کے نتیجے میں انہیں نجات مل گئی اور کسی نبی کے بارے میں ایسی کوئی بات مذکور نہیں، اس کے باوجود آپ صلی اللہ علیہ وسلم نے یہ بھی گوارا نہیں فرمایاکہ ان سے آپ کا تقابل کرکے آپ فضلیت کا اظہا ر کیا جائے۔"}],[4671,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ یہود کے ایک شخص نے کہا: قسم اس ذات کی جس نے موسی علیہ السلام کو چن لیا، یہ سن کر مسلمان نے یہودی کے چہرہ پر طمانچہ رسید کر دیا، یہودی رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور اس کی شکایت کی تو آپ نے فرمایا: \"مجھے موسی علیہ السلام پر فضیلت نہ دو، (پہلا صور پھونکنے سے) سب لوگ بیہوش ہو جائیں گے تو سب سے پہلے میں ہوش میں آؤں گا، اس وقت موسی علیہ السلام عرش کا ایک کنارا مضبوطی سے پکڑے ہوئے ہوں گے، تو مجھے نہیں معلوم کہ آیا وہ ان لوگوں میں سے تھے جو بیہوش ہو گئے تھے اور مجھ سے پہلے ہوش میں آ گئے، یا ان لوگوں میں سے تھے جنہیں اللہ نے بیہوش ہونے سے محفوظ رکھا ۱؎\"۔ ابوداؤد کہتے ہیں: ابن یحیی کی حدیث زیادہ کامل ہے۔\n§وضاحت\n۱؎ : چونکہ اس یہودی نے موسی علیہ السلام کو تمام عالم سے افضل قرار دیا تھا اس لئے مسلمان نے اُسے طمانچہ رسید کر دیا، رسول اکرم صلی اللہ علیہ وسلم نے جس چیز سے منع کیا وہ انبیاء کرام علیہم السلام کو ایک دوسرے پر حمیت و عصبیت کی بنا پر فضیلت دینا ہے، ورنہ اس میں شک نہیں کہ نبی اکرم صلی اللہ علیہ وسلم موسی علیہ السلام سے افضل ہیں، آپ نے موسی علیہ السلام کے بے ہوش نہ ہونے وغیرہ کی بات صرف اس لئے فرمائی کہ ہر نبی کو اللہ نے کچھ خصوصیات عنایت فرمائی ہیں، لیکن ان کی بنیاد پر دوسرے انبیاء کی کسر شان درست نہیں، ہمارے لئے سارے انبیاء علیہ السلام قابل احترام ہیں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک یہودی نے کہا: قسم اس ذات کی جس نے موسیٰ علیہ السلام کو منتخب فرمایا، تو ایک مسلمان نے اپنا ہاتھ اٹھایا اور یہودی کے منہ پر تھپڑ مار دیا۔ وہ یہودی نبی کریم صلی اللہ علیہ وسلم کے پاس چلا آیا اور آپ صلی اللہ علیہ وسلم کو بتایا تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” مجھے موسیٰ علیہ السلام پر فضیلت مت دو۔ بلاشبہ (قیامت برپا ہونے پر) جب لوگ بیہوش کیے جائیں گے تو میں ہی ہوں گا جو سب سے پہلے ہوش میں آؤں گا اور دیکھوں گا کہ موسیٰ علیہ السلام عرش کا پایہ پکڑے کھڑے ہوں گے۔ معلوم نہیں وہ بیہوش ہوئے ہوں گے اور مجھ سے پہلے ہوش میں آ گئے ہوں گے یا یہ ان افراد میں سے ہوں جنہیں اللہ تعالیٰ نے بے ہوشی سے مستثنیٰ رکھا ہو گا۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن یحییٰ کی روایت زیادہ مکمل ہے۔"}],[4672,"انس رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم کو کہا: اے مخلوق میں سے سب سے بہتر! تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ شان تو ابراہیم علیہ السلام کی ہے ۱؎\"۔\n§وضاحت\n۱؎ : ممکن ہے خیرالبریۃ ابراہیم علیہ السلام کا لقب ہو، وہ اپنے زمانہ کے سب سے بہتر تھے، آپ نے ازراہ انکسار ایسا فرمایا ورنہ آپ یقینا خیرالبریۃ ہیں۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے یوں خطاب کیا «يا خير البرية» ” اے مخلوق میں سب سے افضل شخصیت! “ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یہ سیدنا ابراہیم علیہ السلام تھے۔“","f2":"اس میں بھی کسی نبی سے آپ کا تقابل نہیں۔ ساری مخلوق میں آپ کے مرتبے کا ذکر ہے۔"}],[4673,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں اولاد آدم کا سردار ہوں، اور میں سب سے پہلا شخص ہوں جو اپنی قبر سے باہر آئے گا، سب سے پہلے سفارش کرنے والا ہوں اور میری ہی سفارش سب سے پہلے قبول ہو گی\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میں اولاد آدم کا سردار ہوں اور پہلا شخص ہوں گا جس سے زمین پھٹے گی، میں سب سے پہلے سفارش کروں گا اور میری سفارش ہی سب سے پہلے قبول ہو گی۔","f2":"آپ صلی اللہ علیہ وسلم نے حقائق بیان فرمائے لیکن ایسا انداز ہر گزاختیار نہیں فرمایہ جس میں دوسرے انبیا کی تنفیض ہو یا کوئی تقابل ہی سامنے آئے۔"}],[4674,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے نہیں معلوم کہ تبع قابل ملامت ہے یا نہیں، اور نہ مجھے یہ معلوم ہے کہ عزیر نبی ہیں یا نہیں ۱؎\"۔\n§وضاحت\n۱؎ : تبع کے بارے میں یہ فرمان آپ صلی اللہ علیہ وسلم کا اس وقت کا ہے جب آپ کو اس کے بارے میں نہیں بتایا گیا تھا، بعد میں آپ کو بتا دیا گیا کہ وہ ایک مرد صالح تھے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تبع کے متعلق مجھے نہیں معلوم وہ لعین تھا یا نہیں۔ اور عزیر کے متعلق خبر نہیں کہ وہ نبی تھا یا نہیں۔“","f2":"1: قوم سبا کا قبیلہ حمیر اپنے بادشاہ کو تبع کہتا تھا۔ یہ قوم تکذب انبیااور شرک کی وجہ سے ہلاک ہوئی تھی جیسے کی سورہ دخان میں ان کا ذکر آیا ہے کیایہ (مشرقین مکہ) بہترین ہیں یا قوم تنع اور جوان سے بھی پہلے تھے؟ہم نے ان کو ہلاک کردیا،کیو نکہ وہ مجرم تھے اور سورہ ق میں ہے ایکہ (بستی)و الوں نے اور قوم نے تبع نے (ان) سب نے (ہمارے) رسولوں کی تکذیب کی (ان سب) پر میری وعید ثابت ہو گئی رسول اللہ صلی اللہ علیہ وسلم کے فرمان کا مطلب یہ ہے کہ قیامت کےدن عنداللہ اچھائی یا برائی میں کون کس درجے کا ہو گا،اس پر کچھ نہیں کہا جا سکتا،نیز یہ کی جن اشخاص کے بارے میں قرآن میں وضاحت نہیں ان کو اپنی طرف سے نبی کا قراردینے کی کسی کو اجازت نہیں۔ ایک تبع کے متعلق آتاہے کہ وہ مسلمان ہو گیا تھا ااسے برا نہ کہا جائے۔\n2: مستدرک حاکم اورابن عساکروغیرہ کی روایات میں عزیر کی بجائے ذولقرنین کا ذکر ہے،نہیں معلوم وہ نبی تھا یا نہیں۔ حضرت عزیرکے متعلق مشہور ہے کہ وہ نبی تھے۔"}],[4675,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"میں ابن مریم سے لوگوں میں سب سے زیادہ قریب ہوں، انبیاء علیہم السلام علاتی بھائی ہیں، میرے اور ان کے درمیان کوئی نبی نہیں ۱؎\"۔\n§وضاحت\n۱؎ : انبیاء علیہم السلام علاتی بھائی ہیں، علاتی بھائی وہ ہوتے ہیں جن کی مائیں مختلف ہوں اور باپ ایک ہو، انبیاء کی شریعتیں مختلف اور دین ایک تھا ،یا یہ مراد ہے کہ زمانے مختلف ہیں اور دین ایک ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” میں ابن مریم علیہ السلام کے سب سے زیادہ قریب ہوں اور انبیاء گویا ایک باپ کی اولاد ہیں (جن کی مائیں الگ الگ ہوں) میرے اور ابن مریم علیہ السلام کے درمیان اور کوئی نبی نہیں۔“","f2":"انبیا کرام کا علاقی بھائی (باپ کی طرف سے بھائی) ہونے کے معنی یہ ہیں کہ ان کی دعوت کے اصول ایک ہیں،یعنی توحید،نبوت اور بعثت قیامت،البتہ دیگر مسائل شرعیہ میں اختلاف رہا ہے۔ آپ نے خود انبیا کو اخی (یوسف) کہہ کر یاد فرمایا،انبیا کا تذکرہ بہت محبت سےاور خوبصورت انداز سے فرمایا۔ پھر امت کے لئے کیسے رواہو سکتا ہے کہ وہ تفصیل دینے کا اندازمیں ان کا تذکرہ کرے یا کسی کو افضل اور کسی کو مفضول قراردے۔"}],[4676,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایمان کی ستر سے کچھ زیادہ شاخیں ہیں، ان میں سب سے افضل \"لا إله إلا الله\" کہنا، اور سب سے کم تر راستے سے ہڈی ہٹانا ہے ۲؎، اور حیاء ایمان کی ایک شاخ ہے ۳؎\"۔\n§وضاحت\n۱؎ : «ارجاء» کے معنی تاخیر کے ہیں اسی سے فرقہ مرجئہ ہے جس کا عقیدہ ہے کہ ایمان کے ساتھ کوئی معصیت نقصان دہ نہیں، اور کفر کے ساتھ کوئی نیکی نفع بخش نہیں، یہ قدیم گمراہ فرقوں میں سے ایک ہے، اس کی تردید میں محدثین کرام نے مستقل کتابیں لکھی ہیں، اس کتاب میں بھی ان کا رد و ابطال مقصود ہے، ان کے نزدیک اعمال ایمان کا جزء نہیں، بلکہ ایمان محض تصدیق اور اقرار کا نام ہے، جب کہ اہل سنت و اہل حدیث کے یہاں ایمان کے ارکان تین ہیں ، دل سے تصدیق، زبان سے اقرار، اور اعضاء و جوارح سے عملی ثبوت فراہم کرنا۔ ۲؎ : بعض نسخوں میں «عظم» کے بجائے «اذی» کا لفظ ہے گویا کوئی بھی تکلیف دہ چیز۔ ۳؎ : حدیث سے ظاہر ہے کہ اعمال صالحہ سے مومن کو فائدہ اور اعمال بد سے نقصان اور ضرر ہوتا ہے، جب کہ مرجئہ کہتے ہیں کہ اعمال ایمان میں داخل نہیں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ایمان کی ستر اور کچھ شاخیں ہیں۔ سب سے افضل «لا إله إلا الله» کہنا ہے اور سب سے نیچے یہ ہے کہ کوئی راستے میں پڑی ہڈی دور کر دے۔ اور حیاء بھی ایمان کی ایک شاخ ہے۔ “","f2":"1: سلف صالحین یعنی صحابہ اور تابعین نے نزدیک ایمان زبان کے قول،دل کی حقیقی تصدیق اور اعضا ء کے اعمال کا نام ہے،شیخ محی الدین کا قول ہے:یہ بات واضح اور راجح ہے کہ زیادہ سے زیادہ غور وفکر اورواضح سے واضح تردلیل کی وجہ سے تصدیق قلب میں زیادتی ہوتی ہے، جب صدیقیت حاصل ہو تو اس کا ایمان دوسروں سے زیادہ اور مضبوط ہوتا ہے۔ تصدیق قلب کا عمل ہے باقی اعضاءکے عمل بھی زیادہ کم ہوں گے تو یہ ایمان کی کمی یا اضافے کا سبب ہوں گے کیونکہ عمل ایمان کے کمال میں شامل ہے۔ سلف صالحین کے نزدیک دیگر اعضاء (اعضائے ظاہری) کے عمل کمال ایمان کی شرط ہیں البتہ معتزلہ کے نزدیک یہ اعمال ایمان کی صحت کی شرط ہیں۔ (فتح الباری،کتاب ایمان)\n2:سو جو کوئی جس قدر شرعی اعمال بجا لائے اسی قدر اس کا ایمان کا مل ہوتا جائے گا ورنہ اسی قدر ناقص رہے گا۔ جب آپ نے ایمان کے مدارج بیان فرمائے ہیں تو مرجہ کا یہ قول کیسے صحیح ہو سکتا ہے کہ ایمان کم وپیش نہیں ہوتا۔\n3:سب سے افضل اوراعلی عمل لا اله الا الله (توحید) کا قرارہے اور محمد رسول صلی اللہ علیہ وسلم کی رسالت کا اقراراس کا لازمی حصہ ہے،کیونکہ توحید وہی معتبر ہے جو رسول صلی اللہ علیہ وسلم نے بتائی ہے لہذاجو شخص رسالت کا منکر ہو اس کی توحید بھی معتبر نہیں جیسے کی درج ذیل حدیث میں وضاحت آرہی ہے۔"}],[4677,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ عبدالقیس کا وفد جب رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو آپ نے انہیں ایمان باللہ کا حکم دیا اور پوچھا: \"کیا تم جانتے ہو: ایمان باللہ کیا ہے؟\" وہ بولے: اللہ اور اس کے رسول زیادہ جانتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس بات کی شہادت دینی کہ اللہ کے سوا کوئی معبود برحق نہیں اور محمد اللہ کے رسول ہیں، نماز کی اقامت، زکاۃ کی ادائیگی، رمضان کے روزے رکھنا، اور مال غنیمت میں سے پانچواں حصہ ادا کرو\"۔","صحیح",{"u2":"ابوحمزہ سے روایت ہے، انہوں نے کہا کہ میں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا، انہوں نے فرمایا: جب عبدالقیس کا وفد رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو آپ صلی اللہ علیہ وسلم نے انہیں ا اللہ پر ایمان لانے کا حکم دیا۔ آپ صلی اللہ علیہ وسلم نے ان سے پوچھا ” کیا جانتے ہو ا اللہ پر ایمان لانا کیا ہے؟ “ انہوں نے کہا: ا اللہ اور اس کا رسول ہی بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” صرف ایک ا اللہ کے معبود حقیقی ہونے اور محمد کے رسول ا اللہ ہونے کی گواہی دینا، نماز قائم کرنا ‘ زکوٰۃ دینا، رمضان کے روزے رکھنا اور یہ کہ تم مال غنیمت میں سے پانچواں حصہ ادا کرو۔ “","f2":"ایمان صرف زبانی اقرارنہیں اورنہ محض دل کی تصدیق کا نام ہے،بلکہ زبان کے اقرار،دل کی تصدیق اور اعضا ء سے عمل کے مجموعے کوایمان کہا گیا ہے۔ اس قصے میں حج کا ذکر اس لئے نہیں کہ اس وقت تک حج فرض نہیں ہوا تھا۔"}],[4678,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بندے اور کفر کے درمیان حد فاصل نماز کا ترک کرنا ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی کفر اور بندے میں نماز حد فاصل ہے، اگر نماز ادا کرتا ہے تو صاحب ایمان ہے، نہیں ادا کرتا ہے تو کافر ہے، صحابہ کرام رضی اللہ عنہم کسی عمل کے ترک کو کفر نہیں خیال کرتے تھے سوائے نماز کے، عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں: ’’نماز کا ترک کرنا کفر ہے‘‘، عمر رضی اللہ عنہ کہتے ہیں: اس کا اسلام سے کوئی تعلق نہیں جو نماز چھوڑ دے، امام شافعی رحمہ اللہ کہتے ہیں: تارک نماز مرتد ہے اگرچہ دین سے خارج نہیں ہوتا، اصحاب الرای کا مذہب ہے کہ اس کو قید کیا جائے تاوقتیکہ نماز پڑھنے لگے، امام احمد بن حنبل، اور امام اسحاق بن راہویہ، اور ائمہ کی ایک بڑی جماعت تارک نماز کو کافر کہتی ہے، اس لئے ہر مسلمان کو اپنے ایمان کی حفاظت کے لئے نماز کا سخت اہتمام کرنا چاہئے، اور عام لوگوں میں اس عظیم عبادت، اور اسلامی رکن کی اہمیت کی تبلیغ کرنی چاہئے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بندے اور کفر کے درمیان فرق نماز چھوڑ دینا ہے۔ “","f2":"معلوم ہوا کہ عمل ایمان کا حصہ ہے،علامہ خطابی رحمہ اللہ نے لکھا ہے کہ نماز چھوڑنے کی تین صورتیں ہیں:\n1:مطلقا نماز کا انکار کرنا،یعنی یہ سمجھنا کہ دین کا کوئی حصہ نہیں، یہ عقیدہ اجماعی طور پر صریح کفر ہے بلکہ اس طرح سے دین میں ثابت کسی بھی چیز کا انکار کفر ہے۔\n2:غفلت اور بھول سے نماز چھوڑ دینا،آدمی بہ اجماع امت کا فر نہیں۔\nعمدنماز چھوڑے رہنا مگر انکار بھی نہ کرنا،ایسے شخص کے بارے میں ائمہ کا ختلاف ہے۔ ابراہیم نخعی،ابن مبارک،احمد بن حنبل اوراسحاق بن راہویہ کا یہ قول ہے کہ بلا ناغہ عمداتارک صلاۃحتی کہ اس کا وقت نکل جائے،کافر ہے۔ امام احمد کا کہناہے کہ ہم تارک صلاۃکے سوا کسی کو کسی گناہ پر کافر نہیں کہتے۔ زیادہ سخت موقف امام مکحول اور امام شافعی کا ہے کہ تارک صلاۃکو اسی طرح قتل کیا جائے جیسے کا فر کو کیا جاتاہےلیکن اس سبب سے وہ ملت سے خارج نہیں ہوتا۔ مسلمانوں کے قبرستان میں دفن ہو گا۔ اس کے اہل اس وارث ہوں گے۔امام شافعی رحمہ اللہ رحمہ اللہ کے کئی اصحاب نے کہا کہ اس کا جنازہ نہ پڑھاجائے۔ امام ابو حنیفہ رحمہ اللہ اور ان کے اصحاب کا کہنا ہے کہ تارک صلاۃ کو قید کیا جائےاور جسمانی سزا دی جائے حتی کہ وہ نماز پڑھنےلگے۔"}],[4679,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عقل اور دین میں ناقص ہوتے ہوئے عقل والے پر غلبہ پانے والا میں نے تم عورتوں سے زیادہ کسی کو نہیں دیکھا\" (ایک عورت) نے کہا: عقل اور دین میں کیا نقص ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"عقل کا نقص تو یہ ہے کہ دو عورتوں کی گواہی ایک مرد کی گواہی کے برابر ہوتی ہے، اور دین کا نقص یہ ہے کہ (حیض و نفاس میں) تم میں کوئی نہ روزے رکھتی ہے اور نہ نماز پڑھتی ہے ۱؎\"۔\n§وضاحت\n۱؎ : چونکہ اعمال ایمان میں داخل ہیں اس مدت میں نماز و روزے کے ترک سے ایمان میں نقص ثابت ہوا۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (عورتوں کو خطاب کرتے ہوئے) فرمایا: ” میں نے کسی ناقص عقل اور ناقص دین والی کو نہیں پایا جو تم سے بڑھ کر عقلمند بندے کو بے عقل بنا دینے والی ہو۔ “ ایک عورت بولی: عقل اور دین میں کمی اور نقص کیسے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” عقل کی کمی یہ ہے کہ دو عورتوں کی گواہی ایک مرد کے برابر ہوتی ہے اور دین میں کمی یوں ہے کہ بلاشبہ عورت رمضان کے دوران میں روزے چھوڑ دیتی ہے اور کئی کئی دن نماز نہیں پڑھتی۔ “","f2":"1:عورت کا نمازاورروزے چھوڑدینا اگرچہ شرعی،معقول ومقبول عذرہے مگر مجموعی لحاظ سے اس کے اعمال بندگی پر اس کا اثر بھی ضرورمرتب ہوتا ہے کہ کجا ایک مردبلا توقف مسلسل عمل کرتا رہتا ہے جب عورت کے اعمال میں تسلسل نہیں رہتا اور یہی اس کے نقصان دین اور مرد کے کمال دین کی علامت ہے۔\n2:نبی صلی اللہ علیہ وسلم نے عورت کی گواہی کو آدھی گواہی اس لیے قراردیا ہے کہ ان کی یادداشت اور حافظہ کمزورہوتا ہے جیسا کہ قرآن مجید میں اللہ تعالی نے فرمایا ایک عورت اگر بھول جائے تو ان میں سے دوسری اسے یاد دلائے بھول جانا ہی ان کا نقصان عقل ہے اور یہ ایسی حقیقت ہے جس کاتجددپسند چاہے،انکار کرتے رہیں لیکن ان کے آقایان مغرب کے بہت سے مفکرین نے بھی اس کو تسلیم کیا اوراس کا برملا اظہار کیا ہے۔"}],[4680,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ جب (نماز میں) نبی اکرم صلی اللہ علیہ وسلم نے کعبہ کی طرف رخ کرنا شروع کیا تو لوگ کہنے لگے: اللہ کے رسول! ان لوگوں کا کیا ہو گا جو مر گئے، اور وہ بیت المقدس کی طرف نماز پڑھتے تھے؟ تو اللہ تعالی نے یہ آیت نازل فرمائی «وما كان الله ليضيع إيمانكم» \"ایسا نہیں ہے کہ اللہ تمہارے ایمان یعنی نماز ضائع فرما دے\" (البقرہ: ۱۴۳) ۱؎۔\n§وضاحت\n۱؎ : اس آیت میں نماز کو اللہ تعالی نے ایمان قرار دیا ہے، کیونکہ سوال ان صلاتوں کے بارے میں تھا جو بیت اللہ کی طرف رخ کرنے سے پہلے بیت المقدس کی طرف رخ کرکے ادا کی گئی تھیں، اور بہت سے صحابہ کرام رضی اللہ عنہم انتقال بھی کر چکے تھے تو اللہ نے فرمایا : بیت المقدس کی طرف رخ کر کے پڑھی گئی نمازیں ضائع نہیں کرے گا، پس ایمان سے مراد نماز ہے۔","صحیح بخاری کی براء رضی اللہ عنہ کی حدیث سے تقویت پا کر یہ روایت بھی صحیح ہے، ورنہ عکرمہ سے سماک کی روایت میں اضطراب پایا جاتا ہے",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ ہو گا جو بیت المقدس کی طرف منہ کر کے نمازیں پڑھتے رہے ‘ تو اللہ تعالیٰ نے یہ آیت نازل فرمائی «و كان الله ليضيع إيمانكم» ” اللہ تعالیٰ ایسا نہیں ہے کہ تمہارے ایمانوں کو ضائع کر دے۔ “","f2":"اس آیت کریمہ میں اللہ عزوجل نے ایک عمل،نماز کو ایمان سے تعبیر فرمایا ہے،معلوم ہوا کہ اعمال ایمان کا جز ہیں اور اعمال کے کمال سے ایمان کا مل ہوتا ہے ورنہ کمی آجاتی ہے"}],[4681,"ابوامامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اللہ ہی کے رضا کے لیے محبت کی، اللہ ہی کے رضا کے لیے دشمنی کی، اللہ ہی کے رضا کے لیے دیا، اللہ ہی کے رضا کے لیے منع کر دیا تو اس نے اپنا ایمان مکمل کر لیا ۱؎\"۔\n§وضاحت\n۱؎ : اس حدیث میں اعمال کو ایمان کی تکمیل کا سبب قرار دیا گویا ان اعمال کی کمی ایمان کی کمی ٹھہری، پتہ چلا ایمان گھٹتا بڑھتا ہے۔","صحیح",{"u2":"سیدنا ابوامامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے ا اللہ کی خاطر محبت کی، ا اللہ کی خاطر غصہ کیا، ا اللہ کے لیے دیا، اور ا اللہ کی رضا مندی کے پیش نظر نہ دیا تو اس نے ایمان کو کامل کر لیا۔ “","f2":"محبت کرنا یا بعض رکھنا دل کے اعمال ہیں اور کسی کو کوئی چیز دینا یا نہ دينا ہاتھ کے اعمال ہیں اور یہ سب ایمان کے مکمل کرنے یا ناقص رکھنے کے اسباب ہیں"}],[4682,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومنوں میں سب سے کامل ایمان والا وہ ہے جو ان میں سب سے بہتر اخلاق والا ہے\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اہل ایمان میں سب سے بڑھ کر کامل ایمان والا وہی ہے جو اخلاق میں سب سے بڑھ کر ہو۔ “","f2":"(اخلاق‘خلق) کی جمع ہے خا اور لام كے پیش کے ساتھ۔ اور اس سے مراد انسان کی عادات اور اعمال ہیں، عمدہ عادات کو ایمان کا کمال کہا گیا ہے۔جس شخص کی عادات اوردوسروں کے ساتھ معاملات غلط ہوں وہ اتنا ہی ایمان میں ناقص ہوتا ہے"}],[4683,"سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو دیا اور ان میں سے ایک شخص کو کچھ نہیں دیا تو سعد نے عرض کیا: اللہ کے رسول! آپ نے فلاں اور فلاں کو دیا لیکن فلاں کو کچھ بھی نہیں دیا حالانکہ وہ مومن ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یا مسلم ہے\" سعد نے تین بار یہی عرض کیا اور نبی اکرم صلی اللہ علیہ وسلم کہتے رہے: \"یا مسلم ہے\" پھر آپ نے فرمایا: \"میں بعض لوگوں کو دیتا ہوں اور ان میں تجھے جو زیادہ محبوب ہے اسے چھوڑ دیتا ہوں، میں اسے کچھ بھی نہیں دیتا، ایسا اس اندیشے سے کہ کہیں وہ جہنم میں اوندھے منہ نہ ڈال دیئے جائیں ۱؎\"۔\n§وضاحت\n۱؎ : کیونکہ یہ شخص پکا سچا مومن ہے اگر میں اس کو نہ دوں گا تو بھی اس کے ایمان میں کوئی فرق نہیں پڑے گا، لیکن یہ لوگ جن کو دیتا ہوں ناقص ایمان والے ہیں نہ دوں گا تو ان کے ایمان میں فرق پڑے گا کہ ان کا ایمان ابھی پختہ نہیں، لہٰذا مصلحتا میں ایسا کرتا ہوں، پتہ چلا ایمان گھٹتا بڑھتا ہے۔","صحیح",{"u2":"جناب عامر بن سعد اپنے والد (سیدنا سعد بن ابی وقاص رضی اللہ عنہ) سے روایت کرتے ہیں کہ (ایک بار) نبی کریم صلی اللہ علیہ وسلم نے بعض لوگوں کو کچھ عنایت فرمایا اور ایک آدمی کو کچھ نہ دیا۔ تو سیدنا سعد رضی اللہ عنہ نے کہا: اے ا اللہ کے رسول! آپ نے فلاں فلاں کو عنایت فرمایا ہے اور فلاں کو کچھ نہیں دیا حالانکہ وہ مومن ہے۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” یا مسلم ہے۔ “ سیدنا سعد رضی اللہ عنہ نے یہ بات تین بار کہی اور نبی کریم صلی اللہ علیہ وسلم یا مسلم ہے ‘ مسلم ہے فرماتے رہے اور پھر کہا ” میں بعض آدمیوں کو دیتا ہوں اور بعض کو چھوڑ دیتا ہوں حالانکہ وہ مجھے ان کی نسبت زیادہ محبوب ہوتے ہیں اس اندیشے سے کہ کہیں وہ اپنے مونہوں کے بل آگ میں نہ ڈال دیے جائیں۔ “","f2":"1:ایمان اور اسلام اگرچہ آپس میں لازم وملزوم ہیں،مگر ایمان اعضائے باطن وظاہر کے اعمال (تصدیق عمل قلب ہے اور نماز،حج،زکوۃ وغیرہ تمام اعمال صالحہ اعضائے ظاہر کے عمل ہیں) کا نام ہے جبکہ اسلام کا تعلق ظاہری افعال سے۔ اس لیے ہم ظاہری اعمال کی روشنی میں کسی کو صاحب اسلام تو کہہ سکتے ہیں لیکن صاحب ایمان ہونے کا دعوی درست نہیں۔ یہ بات اللہ ہی بہتر جانتا ہے۔ اعضائے ظاہری کے ان اعمال کے ساتھ تصدیق بالقلب کی حالت ہے۔\n2:اسلام قبول کرنے والے نو مسلم لوگوں کو اسلام میں راسخ اور مطئمن کرنے کے لئے ماوی تعاون دینا ضروری ہے تاکہ اسلامی معاشرے کے شرعی اعمال کی روح میں اتر جائیں۔ ایسے لوگوں کواصطلا حا(مولفةالقلوب) كہا جاتا ہے"}],[4684,"ابن شہاب زہری آیت کریمہ «قل لم تؤمنوا ولكن قولوا أسلمنا» \"آپ کہہ دیجئیے تم ایمان نہیں لائے بلکہ یوں کہو کہ مسلمان ہوئے\" (سورۃ الحجرات: ۱۴) کی تفسیر میں کہتے ہیں: ہم سمجھتے ہیں کہ (اس آیت میں) اسلام سے مراد زبان سے کلمے کی ادائیگی اور ایمان سے مراد عمل ہے۔","صحیح الإسناد",{"u2":"جناب ابن شہاب زہری رضی اللہ عنہ نے آیت کریمہ «قل لم تؤمنوا ولكن قولوا أسلمنا» ” کہہ دیجئیے! (اے بدویو!) تم ایمان نہیں لائے بلکہ یوں کہو کہ ہم نے اسلام قبول کیا ہے۔ “ کی تفسیر میں بیان کیا کہ ہم سمجھتے ہیں اسلام سے مراد زبانی اقرار ہے اور ایمان سے مراد عمل ہے۔","f2":"یہ امام زہری رحمہ اللہ کی تعبیر ہے ان کا مطلب یہ ہے کہ اعضائے باطنی اور اعضائے ظاہری جن میں زبان بھی شامل ہے کے اعمال کا نام ایمان ہے۔ اگر صرف زبان نے اقرارکیا ہے تو ہم اسے سلام کہہ سکتے ہیں ایمان نہیں"}],[4685,"سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے مسلمانوں میں کچھ تقسیم فرمایا تو میں نے عرض کیا: فلاں کو بھی دیجئیے، وہ بھی مومن ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یا مسلم ہے، میں ایک شخص کو کچھ عطا کرتا ہوں حالانکہ اس کے علاوہ دوسرا مجھے اس سے زیادہ محبوب ہوتا ہے (جس کو نہیں دیتا) اس اندیشے سے کہ کہیں ایسا نہ ہو کہ میں اس کو نہ دوں تو وہ اوندھے منہ(جہنم میں) ڈال دیا جائے\"۔","صحیح",{"u2":"جناب عامر اپنے والد سیدنا سعد (سعد بن ابی وقاص) رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے مسلمانوں میں کچھ مال تقسیم کیا تو میں نے عرض کیا: فلاں کو بھی دیجئیے بلاشبہ وہ مومن ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یا مسلم ہے، بیشک میں کسی شخص کو کوئی عطیہ دیتا ہوں حالانکہ اس کے بجائے کوئی دوسرا مجھے زیادہ محبوب ہوتا ہے، (اسے کچھ نہیں دیتا) میں اس اندیشے سے اسے دیتا ہوں کہ کہیں اوندھے منہ نہ گرا دیا جائے"}],[4686,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ میرے بعد کافر نہ ہو جانا کہ تم میں سے بعض بعض کی گردن مارنے لگے ۱؎\"۔\n§وضاحت\n۱؎ : اس حدیث میں ایک دوسرے کی گردن مارنے کو ایمان کے منافی قرار دیا، حدیث کا معنی یہ ہے کہ: میرے بعد فرقہ بندی میں پڑ کر ایک دوسرے کی گردن مت مارنے لگ جانا کہ یہ کام کافروں کے مشابہ ہے کیونکہ کافر آپس میں دشمن اور مومن آپس میں بھائی ہیں۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے تھے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کہیں میرے بعد کافر نہ بن جانا کہ ایک دوسرے کی گردنیں مارنے لگو۔ “","f2":"اعمال سئیہ سےایمان میں کمی آتی ہے مسلمانوں کا آپس میں ایک دوسرے کو قتل کرنا بد ترین اعمال میں سے ہے،یہ ایمان کی کمی کی دلیل ہے جسے کفر سے تعبیر کیا گیا ہے،لیکن اس وجہ سے انسان ملت سے خارج نہیں ہوتا ہے"}],[4687,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو مسلمان کسی مسلمان کو کافر قرار دے تو اگر وہ کافر ہے (تو کوئی بات نہیں) ورنہ وہ (قائل) خود کافر ہو جائے گا\"۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس کسی مسلمان نے کسی مسلمان کو کافر کہا، تو اگر وہ (فی الواقع) کافر ہوا تو «فبها» ورنہ کہنے والا ہی کافر ہے۔","f2":"زبان کابول بے کار نہیں جاتا،کسی مسلمان کو بغیر کسی واضح شرعی دلیل کے کافر قرار نہیں دیا جاسکتا۔ اگر مخاطب فی الواقع اس کا مستحق نہ ہو،تو کہنے والا ضرور اس سے متاثر ہوتا ہے۔مگر یہ کفر اکبر سے کم درجے کا ہے۔ کبیرہ گناہ ہے جس کے مرتکب کو اسی معنی میں کافر قرار دیاگیا ہے جس معنی میں اوپر کی حدیث میں کہا گیا ہے"}],[4688,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چار خصلتیں جس میں ہوں وہ خالص منافق ہے اور جس میں ان میں سے کوئی ایک خصلت ہو تو اس میں نفاق کی ایک خصلت ہے یہاں تک کہ وہ اسے چھوڑ دے: جب بات کرے تو جھوٹ بولے، وعدہ کرے تو وعدہ خلافی کرے، معاہدہ کرے تو اس کو نہ نبھائے، اگر کسی سے جھگڑا کرے تو گالی گلوچ دے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” چار خصلتیں جس شخص میں پائی جائیں وہ خالص منافق ہوتا ہے اور جس میں ان میں سے کوئی ایک ہو تو اس میں نفاق کی ایک خصلت ہوتی ہے حتیٰ کہ وہ اسے چھوڑ دے۔ یعنی جب بات کرے تو جھوٹ بولے، وعدہ کرے تو خلاف کرے، عہد معاہدہ کرے تو دھوکہ دے اور اگر جھگڑا ہو جائے تو بدزبانی (گالی گلوچ) پر اتر آئے۔ “","f2":"نفاق بنیادی طور پر قول وعمل کے شدید تضاد کا نام ہے اگر کسی نے اقرارباللسان کیا لیکن اس کے اعمال اس کے برعکس ہیں تو اس کا اقرار غیر حقیقی یا انتہائی کمزورہے۔ آپ صلی اللہ علیہ وسلم نے جن چیزوں کو علامات نفاق قراردیا ہے وہ اعمال شنیعہ ہی ہیں۔ یہ بھی اس بات کی دلیل ہے کہ اعمال سے ایمان میں کمی بیشی ہوتی ہے۔ یہ بھی پتہ چلتا ہے کہ اگر چہ کسی پر مسلمان ہونے یا نہ ہونے کا حکم اس کے دعوی اور اعمال کے مطابق لگایا جاسکتا ہے لیکن بعض بنیادی عمل ایسے ہیں کہ صرف زبانی اقراروالے عموماان کا اہتمام نہیں کرسکتے۔ چاہے وہ بڑے بڑے اعمال جیسے نماز وغیرہ کا اہتمام کرتے بھی ہوں، جہاں نیکی ایمان میں اضافے اور ترقی کا باعث بنتی ہے تو وہاں ہر گناہ اور برائی ایمان میں کمی لاتی ہے اور کسی مسلمان میں نفاق کی علامتوں کا پایا جانا ہی قبیح اور بڑا عیب ہے"}],[4689,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زانی زنا کے وقت مومن نہیں رہتا، چور چوری کے وقت مومن نہیں رہتا، شرابی شراب پیتے وقت مومن نہیں رہتا (یعنی ایمان اس سے جدا ہو جاتا ہے پھر بعد میں واپس آ جاتا ہے) توبہ کا دروازہ اس کے بعد بھی کھلا ہوا ہے\" (یعنی اگر توبہ کر لے تو توبہ قبول ہو جائے گی اللہ بخشنے والا ہے) ۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بدکار زانی جس وقت زنا کر رہا ہو ‘ ایماندار نہیں ہوتا۔ چور جس وقت چوری کر رہا ہو، ایمان والا نہیں ہوتا، اور شرابی جب شراب پی رہا ہو، مومن نہیں ہوتا، اس کے بعد توبہ اس کے سامنے ہے۔ “"}],[4690,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب آدمی زنا کرتا ہے تو ایمان اس سے نکل جاتا ہے اور بادل کے ٹکڑے کی طرح اس کے اوپر لٹکا رہتا ہے، پھر جب زنا سے الگ ہوتا ہے تو دوبارہ ایمان اس کی طرف لوٹ آتا ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” آدمی جب زنا کرتا ہے تو ایمان اس سے نکل جاتا ہے اور اس کے اوپر چھتری کی مانند ہو جاتا ہے۔ پس جب وہ اپنی بدکاری سے نکل آتا ہے تو ایمان اس کی طرف واپس آ جاتا ہے۔ “","f2":"ان احادیث میں مذکورہ افعال بد کی شناعت اور برائی اور ان کے مرتکب کی بد بختی کا بیان ہے جو کسی بھی ایماندارکےشایان شان نہیں۔ بالفرض ایسا آدمی اگر اسی حالت میں مر جائے تو غور کریں وہ کس حال میں مرا۔ فرقہ خوارج نے اس کےمعنی سمجھے ہیں ایسا آدمی ایمان سے خارج اور حتمی طور پر کافر ہو جاتا ہے مگر ان احادیث میں اس انتہا پسند انہ موقف اور غلو کی تردید ہوتی ہے۔ اہل السنتہ والجماعۃکے نزدیک یہ اعمال کفر یہ ہیں مگر قطی طور پر ملت سے اخراج کا سبب نہیں جانتے جس وقت کوئی ایسے اعمال میں مبتلا نہیں ہوتا اس وقت وہ کافر نہیں ہوتا بلکہ اگر وہ توبہ کرلے تو ایمان کی کمی یا عارضی طور پر ایمان کی نفی کیفیت سے نکل آتا ہے جسے کہ (کفر دون کفر) سے تعبیر کیا جاتا ہے۔ یعنی بڑے کفر سے چھوٹاکفر"}],[4691,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"قدریہ (منکرین تقدیر) اس امت (محمدیہ) کے مجوس ہیں، اگر وہ بیمار پڑیں تو ان کی عیادت نہ کرو، اور اگر وہ مر جائیں تو ان کے جنازے میں شریک مت ہو ۱؎\"۔\n§وضاحت\n۱؎ : قدریہ ایک گمراہ فرقہ ہے جو تقدیر کا منکر ہے، اس کا عقیدہ ہے کہ انسان اپنے افعال کا خود خالق ہے، اس فرقہ کو مجوس سے اس لئے تشبیہ دی کہ مجوس دو خالق کے قائل ہیں، یعنی خالق شر و خالق خیر: خالق شر کو اہرمن اور خالق خیر کو یزداں کہتے ہیں، جبکہ اسلام کا عقیدہ یہ ہے کہ خالق صرف ایک ہے چنانچہ «هل من خالق غير الله» فرما کر قرآن نے دوسرے کسی خالق کی تردید فرما دی، انسان جو کچھ کرتا ہے اس کو اس کا اختیار اللہ ہی نے دیا ہے، اگر نیک عمل کرے گا تو ثواب پائے گا، بد کرے گا تو عذاب پائے گا، ہر فعل کا خالق اللہ ہی ہے، دوسرا کوئی نہیں، یہ مسئلہ نہایت معرکۃ الآراء ہے، عام آدمی کو اس کی ٹوہ میں نہیں پڑنا چاہئے، سلامتی کا راستہ یہی ہے کہ مسلمان تقدیر پر ایمان رکھے اور شیطان کے وسوسہ سے بچے، تقدیر کے منکروں سے ہمیشہ دور رہنا چاہئے ان سے میل جول بھی درست نہیں۔","حسن",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” قدریہ (تقدیر کا انکار کرنے والے) اس امت کے مجوسی ہیں۔ اگر بیمار ہو جائیں تو ان کی عیادت کو مت جاؤ اور اگر مر جائیں تو جنازے میں شریک نہ ہو۔ “","f2":"1:مجوسی دوالہوں کے قائل ہیں ایک خالق خیر سے وہ یزواں کہتے ہیں اور دوسرا خالق شر جسے وہ اہرمن کا نام دیتے ہیں اسی طرح تقدیر کے منکر خیرکو اللہ کی اور شر کو غیر اللہ کی خلق سمجھتے ہیں،حالانکہ خلق اور ایجاد میں اللہ عزوجل کا کوئی شریک وسہیم نہیں ہے،نہ کوئی اس پر غالب ہے، اس نے اپنی حکمت کے تحت شر اور شیطان کو پیدا کیا ہے اور انسان اللہ عزوجل کی مشیت اور ارادے کے معنی ہمیشہ رضامندی الگ الگ دوچیزیں ہیں۔ جو کچھ بھی ہوتا ہے وہ یقینامشیت الہی ہی سے ہوتا ہے اس کے بغیر اچھا یا برا کوئی کام بھی نہیں ہوتا،لیکن یہ ضروری نہیں کہ اللہ تعالی کا پسندیدہ بھی ہو۔ اللہ تعالی کو تو صرف وہی کام پسند ہیں جن کے کرنے کااس نے حکم دیا ہے۔ باقی کام ناپسندیدہ ہیں گو ہوتے وہ بھی اس کی مشیت ہی سے ہیں،\n2:اسلامی معاشرے میں شرعی اقدار کا تحفظ کرنے کےلئے ضروری ہے کہ ملحد اور بد عقیدہ کوگوں سے مقاطعہ کیا جائے تاکہ صاحب ایمان کی غیرت کا اظہار ہو اور انہیں مومنین سے جدا ہونے کا احساس رہے مگر اہل علم پر لازم ہے کہ ان کے سامنے حق کا اظہار اور ان غلطیوں کی نشاندہی کریں۔\n3:بعض حضرات نے اس حدیث کو حسن قرار دیا ہے"}],[4692,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر امت کے مجوس ہوتے ہیں، اس امت کے مجوس وہ لوگ ہیں جو تقدیر کے منکر ہیں، ان میں کوئی مر جائے تو تم اس کے جنازے میں شرکت نہ کرو، اور اگر کوئی بیمار پڑے، تو اس کی عیادت نہ کرو، یہ دجال کی جماعت کے لوگ ہیں، اللہ ان کو دجال کے زمانے تک باقی رکھے گا\"۔","ضعیف",{"u2":"سیدنا حذیفہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہر امت کے مجوسی ہوتے ہیں اور اس امت کے مجوسی وہ ہیں جو تقدیر کے منکر ہیں۔ ان میں سے جو مر جائے اس کے جنازے میں مت جاؤ اور جو بیمار ہو اس کی عیادت کے لیے مت جاؤ۔ یہی لوگ دجال کے حامی ہوں گے اور ا اللہ پر حق ہے کہ انہیں دجال کے ساتھ ملائے۔ “"}],[4693,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے آدم کو ایک مٹھی مٹی سے پیدا کیا جس کو اس نے ساری زمین سے لیا تھا، چنانچہ آدم کی اولاد اپنی مٹی کی مناسبت سے مختلف رنگ کی ہے، کوئی سفید، کوئی سرخ، کوئی کالا اور کوئی ان کے درمیان، کوئی نرم خو، تو کوئی درشت خو، سخت گیر، کوئی خبیث تو کوئی پاک باز\"۔","صحیح",{"u2":"سیدنا ابوموسیٰ اشعری رضی اللہ عنہ نے بیان کیا کہ چنانچہ آدم کی اولاد اس مٹی کے لحاظ سے ہوئی ہے، کئی سرخ ہیں اور کئی سفید، کئی سیاہ ہیں اور کئی ان کے بین بین۔ کئی نرم خو ہیں اور کئی سخت طبیعت۔ کئی بری طبیعت کے مالک ہوتے ہیں اور کئی اچھی اور عمدہ طبیعت والے۔ “ یحییٰ بن سعید کی روایت میں اضافہ ہے ” اور کئی ان کے درمیان درمیان ہیں۔ “ یزید (یزید بن زریع) کی روایت میں «أخبرنا» کا صیغہ استعمال ہوا ہے۔","f2":"اس حدیث میں مجبور اور صاحب اختیار ہونے کا مسئلہ حل فرمایا گیا ہے۔انسان کا گورایا کالا ہونا اس کی طبعیت کا سخت یانرم ہونا۔ ایسا معاملہ ہے جس میں اس کا اپنا کوئی اختیار نہیں اس میں وہ مجبور محض ہے۔ مگر اسے اختیار ہے کہ طبعیت کی نرمی کو اہل ایمان کے لئے سختی کو کفار کے مقابلے میں استعمال کرے۔ اسی طرح جس میں خیر اور بھلائی کا عنصر ہے اسے اپنے خالق کا بہت زیادہ شکر ادا کرتے ہوئے اپنی اس خیر اور بھلائی کی حفاظت کرنی چاہیے اور جس میں دوسری کیفیت ہو اسے چاہیے کہ رب ذوالجلال کی طرف رجوع کرے اور توفیق طلب کرے کہ وہ اس کی اس حالت کو بدل دے مگر اپنی غلط عادات پر ڈٹے رہنا اور تقدیر کو مور د الزام تھہراناکسی طرح جائز نہیں۔ اگر تقدیر کے معنی جبر ہوں تو یہ لوگ اپنی بد قماشیوں میں کیوں محنت کرتے ہیں؟یہ محنت اور کوشش نیکی اور خیر کے لئے بھی ہو سکتی ہے!وہ بد قماشی یا مادی فائدہ اپنی محنت کےثمرات سمجھتے ہیں توان کے ذمہ دار بھی ہیں۔ اللہ تعالی نے زندگی،صحت،عافیت،فہموفراست اور صلاحیت اور اچھائی سے فطری محبت جیسی تمام نعمتوں سے ہر انسان کو نیکی کی توفیق دی ہوئی ہے،نیکی ہی راستے پر ہر ایک کو آگے بڑھنا چاہیے"}],[4694,"علی رضی اللہ عنہ کہتے ہیں کہ ہم مدینہ کے قبرستان بقیع غرقد میں ایک جنازے میں شریک تھے، جس میں رسول اللہ صلی اللہ علیہ وسلم بھی تھے، آپ آئے اور بیٹھ گئے، آپ کے پاس ایک چھڑی تھی، چھڑی سے زمین کریدنے لگے، پھر اپنا سر اٹھایا اور فرمایا: \"اللہ تعالی نے تم میں سے ہر ایک متنفس کا ٹھکانہ جنت یا دوزخ میں لکھ دیا ہے، اور یہ بھی کہ وہ نیک بخت ہو گا یا بدبخت\" لوگوں میں سے ایک شخص نے عرض کیا: اللہ کے نبی! پھر ہم کیوں نہ اپنے لکھے پر اعتماد کر کے بیٹھ رہیں اور عمل ترک کر دیں کیونکہ جو نیک بختوں میں سے ہو گا وہ لازماً نیک بختی کی طرف جائے گا اور جو بدبختوں میں سے ہو گا وہ ضرور بدبختی کی طرف جائے گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"عمل کرو، ہر ایک کے لیے اس کا عمل آسان ہے، اہل سعادت کے لیے سعادت کی راہیں آسان کر دی جاتی ہیں اور بدبختوں کے لیے بدبختی کی راہیں آسان کر دی جاتی ہیں\" پھر نبی اکرم صلی اللہ علیہ وسلم نے اللہ تعالی کا یہ فرمان سنایا: \"جو شخص اللہ کے راستے میں خرچ کرے، اللہ سے ڈرے، اور کلمہ توحید کی تصدیق کرے تو ہم اس کے لیے آسانی اور خوشی کی راہ آسان کر دیں گے، اور جو شخص بخل کرے، دنیوی شہوات میں پڑ کر جنت کی نعمتوں سے بے پروائی برتے اور کلمہ توحید کو جھٹلائے تو ہم اس کے لیے سختی اور بدبختی کی راہ آسان کر دیں گے\" ۱؎۔\n§وضاحت\n۱؎ : اس حدیث میں اس شیطانی وسوسہ کا جواب رسول اللہ صلی اللہ علیہ وسلم نے دیا، جو اکثر لوگوں کے ذہن میں آتا ہے، اور ان کو بدعملی پر ابھارتا ہے، جب جنتی اور جہنمی کا فیصلہ پہلے ہی ہو چکا ہے تو عمل کیوں کریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \" کسی کو معلوم نہیں کہ اس کے مقدر میں کیا لکھا ہے\"، لہٰذا ہر شخص کو نیک عمل کرنا چاہئے کہ یہی نیکی کی راہ ، اور یہی جنت میں جانے کا سبب ہے، بندے کو اس بحث میں پڑے بغیر کہ وہ کہاں جائے گا نیک عمل کرتے رہنا چاہئے، تاکہ وہ اللہ کی رحمت کا مستحق ہو، اور نتیجے میں جنت نصیب ہو، آمین۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ جس نے (ا اللہ کے لیے مال) دیا اور تقٰوی اختیار کیا اور نیکی کی تصدیق کی، ہم اسے آسان منزل کی توفیق دیتے ہیں۔ اور جس نے بخل کیا اور بے پروا بنا رہا اور نیکی کو جھٹلایا، تو ہم اسے تنگی والی منزل کی توفیق دیتے ہیں۔ “","f2":"تقدیر اللہ عز وجل کے ازلی وابدی علم کا نام ہے اور ہرشخص کے بارےمیں ریکارڈ ہو چکا ہے کہ کو ن کہاں جانے والا ہے،جنت میں یا دوزخ میں۔ اللہ عزوجل کا یہ علم ازلی غلط نہیں ہوسکتا۔ وہ علیم وخبیر ہےاس کے علم میں ذرہ برابر بھی کمی نہیں۔ مگر کوئی اس مستقبل کے ریکارڈ کو اپنے لئے عذربنا لے۔۔۔۔۔ حالانکہ اس کو خبر نہیں کہ کیا لکھا ہے تو یہ لغومحض ہے،تعجب ہے کہ لوگ شرعی تکلیفات میں تقدیر کو بہانہ بناتے ہیں مگر اپنی ہواوہوس کے معاملات میں سر توڑ محنت اور کوشش کرتے ہیں اور ان سے باز نہیں رہتے۔ آخرت کے انجام کے سلسلے میں اس دنیا میں ایک علامت ضرور رکھی دی گئی ہے کہ نیکی کا عزم رکھنے والے اور اس میں محنت کرنے والے نیکی کے احوال وظروف کی تائید ملتی رہتی ہے۔ ایسے شخص کے بارے میں امید کرنی چاہیےکہ اس کی عاقبت بھی بفضل اللہ عمدہ ہو گی۔ اور جو شخص بد عملی میں ملوث اور اس کے لئے سر گردان ہو اسے انہی مقاصد کے لئے احوال کی تائید مہیا ہو جاتی ہے۔ باوجودیکہ سب کچھ پہلے سے ریکارڈ کر لیا گیا ہے لیکن انسان خود اس کے متعلق بابکل بے خبر ہے وہ اپنی مرضی سے اپنی راہ خود چنتا ہے اور خود اس پر چلتا ہے۔ اب یہ اس کا اپنا فیصلہ اوراختیار ہے کہ وہ کونسی راہ اپناتا ہے۔ اللہ تعالی نے فر مایا ہم نےانسان کو رستے کی رہنمائی کردی ہے خواہشکر گزار بن جائے یا نا شکر ا اور فرمایا ہم نے انسان کو ادھر ہی پھیر دیتے ہیں ہیں جد ھر کا رخ کرتا ہے"}],[4695,"یحیی بن یعمر کہتے ہیں کہ بصرہ میں سب سے پہلے معبد جہنی نے تقدیر کا انکار کیا، ہم اور حمید بن عبدالرحمٰن حمیری حج یا عمرے کے لیے چلے، تو ہم نے دل میں کہا: اگر ہماری ملاقات رسول اللہ صلی اللہ علیہ وسلم کے کسی صحابی سے ہوئی تو ہم ان سے تقدیر کے متعلق لوگ جو باتیں کہتے ہیں اس کے بارے میں دریافت کریں گے، تو اللہ نے ہماری ملاقات عبداللہ بن عمر رضی اللہ عنہما سے کرا دی، وہ ہمیں مسجد میں داخل ہوتے ہوئے مل گئے، چنانچہ میں نے اور میرے ساتھی نے انہیں گھیر لیا، میرا خیال تھا کہ میرے ساتھی گفتگو کا موقع مجھے ہی دیں گے اس لیے میں نے کہا: ابوعبدالرحمٰن! ہماری طرف کچھ ایسے لوگ ظاہر ہوئے ہیں جو قرآن پڑھتے اور اس میں علمی باریکیاں نکالتے ہیں، کہتے ہیں: تقدیر کوئی چیز نہیں ۱؎، سارے کام یوں ہی ہوتے ہیں، تو آپ نے عرض کیا: جب تم ان سے ملنا تو انہیں بتا دینا کہ میں ان سے بری ہوں، اور وہ مجھ سے بری ہیں (میرا ان سے کوئی تعلق نہیں)، اس ہستی کی قسم، جس کی قسم عبداللہ بن عمر کھایا کرتا ہے، اگر ان میں ایک شخص کے پاس احد کے برابر سونا ہو اور وہ اسے اللہ کی راہ میں خرچ کر دے تو بھی اللہ اس کے کسی عمل کو قبول نہ فرمائے گا، جب تک کہ وہ تقدیر پر ایمان نہ لے آئے، پھر آپ نے کہا: مجھ سے عمر بن خطاب رضی اللہ عنہ نے بیان کیا کہ ایک بار ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے کہ اچانک ایک شخص ہمارے سامنے نمودار ہوا جس کا لباس نہایت سفید اور بال انتہائی کالے تھے، اس پر نہ تو سفر کے آثار دکھائی دے رہے تھے، اور نہ ہی ہم اسے پہچانتے تھے، یہاں تک کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس جا کر بیٹھ گیا، اس نے اپنے گھٹنے نبی اکرم صلی اللہ علیہ وسلم کے گھٹنوں سے ملا دئیے، اور اپنی ہتھیلیوں کو آپ کی رانوں پر رکھ لیا اور عرض کیا: محمد! مجھے اسلام کے بارے میں بتائیے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسلام یہ ہے کہ تم گواہی دو کہ اللہ کے سوا کوئی معبود برحق نہیں اور محمد اللہ کے رسول ہیں، نماز قائم کرو، زکاۃ دو، رمضان کے روز ے رکھو، اور اگر پہنچنے کی قدرت ہو تو بیت اللہ کا حج کرو\" وہ بولا: آپ نے سچ کہا، عمر بن خطاب کہتے ہیں: ہمیں اس پر تعجب ہوا کہ وہ آپ سے سوال بھی کرتا ہے اور تصدیق بھی کرتا ہے۔ اس نے کہا: مجھے ایمان کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایمان یہ ہے کہ تم اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر، اس کے رسولوں پر، آخرت کے دن پر اور تقدیر ۲؎ کے بھلے یا برے ہونے پر ایمان لاؤ\" اس نے کہا: آپ نے سچ کہا۔ پھر پوچھا: مجھے احسان کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اللہ کی عبادت اس طرح کرو گویا تم اسے دیکھ رہے ہو، اور اگر یہ کیفیت پیدا نہ ہو سکے تو (یہ تصور رکھو کہ) وہ تو تمہیں ضرور دیکھ رہا ہے\" اس نے کہا: مجھے قیامت کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس سے پوچھا جا رہا ہے، وہ اس بارے میں پوچھنے والے سے زیادہ نہیں جانتا\" ۳؎۔ اس نے کہا: تو مجھے اس کی علامتیں ہی بتا دیجئیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی علامتوں میں سے یہ ہے کہ لونڈی اپنی مالکن کو جنے گی۴؎، اور یہ کہ تم ننگے پیر اور ننگے بدن، محتاج، بکریوں کے چرواہوں کو دیکھو گے کہ وہ اونچی اونچی عمارتیں بنانے میں فخر و مباہات کریں گے\" پھر وہ چلا گیا، پھر میں تین ۵؎ (ساعت) تک ٹھہرا رہا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے عمر! کیا تم جانتے ہو کہ پوچھنے والا کون تھا؟\" میں نے عرض کیا: اللہ اور اس کے رسول زیادہ جانتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ جبرائیل تھے، تمہیں تمہارا دین سکھانے آئے تھے\"۔\n§وضاحت\n۱؎ : بندہ اپنے افعال میں خود مختار ہے اور وہی ان کا خالق ہے۔ ۲؎ : یعنی اللہ تعالی نے ہر چیز کا اندازہ مقرر فرما دیا ہے اب ہر شیٔ اسی اندازے کے مطابق اس کے پیدا کرنے سے ہو رہی ہے کوئی چیز اس کے ارادے کے بغیر نہیں ہوتی۔ ۳؎ : مطلب یہاں یہ ہے کہ قیامت کے وقوع کا علم چونکہ اللہ نے کسی کو نہیں دیا اس لئے نہ تم جانتے ہو اور نہ میں، بلکہ ہر سائل اور مسئول قیامت کے بارے میں ایسا ہی ہے یعنی نہیں جانتا، ہاں قیامت علامات بتلائی گئی ہیں جس سے عبرت حاصل کر کے نیک عمل کرنا چاہئے۔ ۴؎ : اس کے کئی معنی بیان کئے گئے ہیں ایک یہ کہ چھوٹے بڑے کا فرق مٹ جائے گا، اولاد اپنے والدین کے ساتھ غلاموں جیسا برتاؤ کرنے لگے گی۔ ۵؎ : تین ساعت یا تین رات یا چند لمحے۔","صحیح",{"u2":"یحییٰ بن یعمر رضی اللہ عنہ نے بیان کیا کہ سوال بھی کرتا ہے اور تصدیق بھی کرتا ہے۔ پھر کہنے لگا: آپ مجھے ایمان کے متعلق بتلائیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” (ایمان یہ ہے) کہ تم ا اللہ پر، اس کے فرشتوں، اس کی کتابوں، اس کے رسولوں اور آخرت کے دن پر ایمان لاؤ اور تقدیر کے اچھے اور برے ہونے پر بھی ایمان لاؤ۔ “ اس نے کہا: آپ نے سچ فرمایا۔ پھر بولا مجھے احسان کے متعلق بتلائیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ا اللہ کی عبادت اس طرح سے کرو گویا کہ تم اسے دیکھ رہے ہو، اگر یہ کیفیت حاصل نہ ہو تو یہ ہو کہ وہ تمہیں دیکھ رہا ہے۔ “ اس نے کہا کہ مجھے قیامت کے متعلق بتلائیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کی بابت جس سے پوچھ رہے ہو، وہ پوچھنے والے سے زیادہ نہیں جانتا۔ “ تب اس نے کہا: اچھا مجھے اس کی علامت بتا دیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ کہ لونڈی اپنی مالکہ کو جہنم دے اور تم دیکھو کہ پاؤں اور جسم سے ننگے، فقیر اور بکریوں کے چرواہے اونچی اونچی عمارتیں بنانے میں ایک دوسرے سے بڑھنے لگ جائیں۔ “ پھر وہ چلا گیا۔ پھر میں (عمر بن خطاب) تین دن رکا رہا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اے عمر! کیا تمہیں خبر ہے وہ سائل کون تھا؟ “ میں نے عرض کیا: ا اللہ اور اس کے رسول ہی بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بیشک وہ جبرائیل تھے جو تمہیں تمہارا دین سکھانے آئے تھے۔ “","f2":"1: بالخصوص فتنوں کے دنوں میں ضروری ہے کہ انسان علمائے راسخین سے رابطے میں رہے ان سے استفادہ کرکے ہی وہ اپنے ایمان وعمل کو محفوظ رکھ سکتا ہے صحابہ کرام رضی اللہ اس سلسلے کی اولین کڑی ہیں۔\n2: الولا ء والبراء ایک اہم ترین مسئلہ ہے،ہر مومن کے لئے اس سے آگاہی اور اس پر عمل ضروری ہے،یعنی اہل ایمان سے محبت اور اہل کفراور ملحدین سے بغض اور اعراض۔\n3: ایمانیات کی تمامتر جزئیات تسلیم اور قبول کیے بغیر کوئی نیکی درجہ قبول نہیں پاسکتی،ان میں سے ایک اہم مسئلہ تقدیر بھی ہے۔\n4:لازمی ہے کہ علم شریعت قوت اور شباب (جوانی) کے دنوں میں حاصل کیا جائے۔ طالب علم کا لباس انتہائی صاف ستھراہو اور وہ اپنے مشائخ سے از حد تواضع کا معاملہ رکھے۔\n5:ایمان اعضائے باطنی اور اعضائے ظاہری دونوں عمل یعنی تصدیق بالقلب اور اقرار باللسان و اعمال صالحہ کا نام ہے جبکہ اسلام اعضائے ظاہری کے اعمال یعنی اقرارباللسان واعمال صالحہ کا نا م ہے۔ ایمان میں اسلام بھی شامل ہے مگر جہاں ان کی الگ الگ پہچان کرنا مقصود ہو وہاں اسلام کا اطلاق ظاہری اعمال پر اور ایمان کا اطلاق باطنی امور پر ہوتا ہے جن کو ظاہری اعمال خود بخود مستلزم ہوتے ہیں۔\n6: صفت احسان یعنی بندے کایہ تصور ہوکہ وہ اللہ کو دیکھ رہا ہے یا کم از کم یہ کہ اللہ اسے دیکھ رہا ہے،ایمان اور اسلام کے کمال کی نشانی ہے۔\n7: قیامت کا علم اللہ کے سوا کسی کو نہیں\n8: اولادوں کا نافرمان ہونا اور بلند سے بلند عمارتوں کی تعمیر میں مقابلہ بالخصوص قرب قیامت کی علامات میں سے ہے۔\n9: فرامین رسول صلی اللہ علیہ وسلم یعنی حدیث وسنت شرعی حجت ہیں۔رسول اللہ صلی اللہ علیہ وسلم کے علاوہ کوئی انسان خواہ کتنا ہی صاحب عظمت ہو،شریعت میں اس کے قول وفعل کی کوئی حیثیت نہیں جب تک الصادق والمصدوق صلی اللہ علیہ وسلم کی توثیق نہ ہو۔ جس طرح کہ جبریل امین علیہ السلام نے دین کی سب سے تفصیلات رسول اللہ صلی اللہ علیہ وسلم کی زبان سے اداکروائیں۔ براہ راست کچھ نہیں کہا۔۔۔۔اور اگر بالفرض وہ کہہ بھی دیتے تو امت کے لئے یہ حجت نہ ہوتا۔\n10:صحابہ کرام رضی اللہ کو آنے والے کا پتہ نہ تھا اس کا مطلب ہے کہ اولیا اللہ غیب نہیں جانتے۔\n11: لفظ دین شریعت کے تمام ظاہری اور باطنی امور کو محیط ہے"}],[4696,"یحیی بن یعمر اور حمید بن عبدالرحمٰن کہتے ہیں کہ ہم عبداللہ بن عمر رضی اللہ عنہما سے ملے تو ہم نے آپ سے تقدیر کے بارے میں جو کچھ لوگ کہتے ہیں اس کا ذکر کیا۔ پھر راوی نے اسی طرح کی روایت ذکر کی اور اس میں یہ اضافہ کیا کہ آپ سے مزینہ یا جہینہ ۱؎ کے ایک شخص نے پوچھا: اے اللہ کے رسول! پھر ہم کیا جان کر عمل کریں؟ کیا یہ جان کر کہ جو کچھ ہم کر رہے ہیں وہ سب پہلے ہی تقدیر میں لکھا جا چکا ہے، یا یہ جان کر کہ (پہلے سے نہیں لکھا گیا ہے) نئے سرے سے ہونا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ جان کر کہ جو کچھ ہونا ہے سب تقدیر میں لکھا جا چکا ہے\" پھر اس شخص نے یا کسی دوسرے نے کہا: تو آخر یہ عمل کس لیے ہے؟ ۲؎، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اہل جنت کے لیے اہل جنت والے اعمال آسان کر دئیے جاتے ہیں اور اہل جہنم کو اہل جہنم کے اعمال آسان کر دیئے جاتے ہیں\"۔\n§وضاحت\n۱؎ : دو قبیلوں کے نام ہیں۔ ۲؎ : یعنی جب جنت و جہنم کا فیصلہ ہو چکا ہے تو عمل کیوں کریں، یہی سوچ گمراہی کی ابتداء تھی۔","صحیح",{"u2":"جناب یحییٰ بن یعمر اور حمید بن عبدالرحمٰن نے بیان کیا کہ ہم سیدنا عبداللہ بن عمر رضی اللہ عنہ سے ملے اور ان سے تقدیر اور دیگر مسائل جو وہ لوگ بولتے تھے، دریافت کیے، تو مذکورہ بالا حدیث کی مانند ذکر کیے اور مزید کہا: مزینہ یا جہینہ کے آدمی نے آپ صلی اللہ علیہ وسلم سے دریافت کیا: اے ا اللہ کے رسول! ہم عمل کس بنا پر کریں؟ کیا یہ جان کر کہ سب کچھ طے ہو چکا ہے یا یہ سمجھ کر کہ معاملہ نیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ سمجھ کر کہ سب کچھ طے ہو چکا ہے۔ “ تو قوم میں سے ایک نے کہا: تو پھر عمل کیوں ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ جنتی اہل جنت کے عملوں کی توفیق دیے جاتے ہیں اور دوزخی اہل جہنم کے عملوں کی توفیق دیے جاتے ہیں۔ “","f2":"مسلسل عمل کرنا انسانی فطرت کا لازمی حصہ ہے تو جو کوئی اپنے اعمال میں خیر پائے اسے اللہ کا شکر کرتے ہوئے ثابت قدم رہنا چاہیے اور مزید محنت کرنی چاہیے اور جس کے اعمال ہوں تو وہ توبہ کرے اور اپنے اعمال بد ل کر خیراپنائے۔ اللہ عزوجل تو نہ قبول کرنے والا اور نیکی کی توفیق دینے والا ہے،غلط سے صحیح کی یہ تبدیلی اللہ تعالی کو پہلے ہی معلوم ہے"}],[4697,"یحیی بن یعمر سے یہی حدیث کچھ الفاظ کی کمی اور بیشی کے ساتھ مروی ہے اس نے پوچھا: اسلام کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نماز کی اقامت، زکاۃ کی ادائیگی، بیت اللہ کا حج، ماہ رمضان کے روزے رکھنا اور جنابت لاحق ہونے پر غسل کرنا\"۔ ابوداؤد کہتے ہیں: علقمہ مرجئی ہیں۔","صحیح",{"u2":"جناب سلیمان بن بریدہ نے ابن یعمر سے یہ روایت نقل کی جس میں کچھ کمی بیشی ہے (اس کے الفاظ میں) کہا: اسلام کیا ہے؟ فرمایا ” نماز قائم کرنا، زکوٰۃ دینا، بیت اللہ کا حج کرنا، ماہ رمضان کے روزے رکھنا اور جنابت سے غسل کرنا۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا کہ علقمہ (علقمہ بن مرثد) کا تعلق فرقہ مرجئہ سے تھا۔","f2":"1: اسلام اللہ کی رضا کے لئے ظاہری اعضا کے صالح اعمال کا نام ہے۔\n2:جنابت سے غسل فرض ہے،فرمایا اگر تم جنابت سے ہو تو غسل کر لیا کرو\n3:اعمال ایمان اور اسلام کا لازمی حصہ ہیں۔\n4:بد عقیدہ لوگ اگرروایات کی نقل میں سچے ہوں اور اپنی بدعت کے داعی نہ ہو ں تو ان کی روایات مقبول ہوتی ہیں،بلکہ اس روایت سے یہ ثابت ہوتاہے کہ جو حدیث علقمہ کو پہنچی وہ اس کے عقائد کے برعکس تھی اس نے من وعن بیان کردی۔ سچا ہونے کی وجہ سے اس راوی کی روایت بلند یایہ محدثین نے قبول کی"}],[4698,"ابوذر اور ابوہریرہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے اصحاب کے بیچ میں اس طرح بیٹھتے تھے کہ جب کوئی اجنبی شخص آتا تو وہ بغیر پوچھے آپ کو پہچان نہیں پاتا تھا، تو ہم نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی کہ ہم آپ کے لیے ایک ایسی جائے نشست بنا دیں کہ جب بھی کوئی اجنبی آئے تو وہ آپ کو پہچان لے، ابوہریرہ رضی اللہ عنہ کہتے ہیں: چنانچہ ہم نے آپ کے لیے ایک مٹی کا چبوترا بنا دیا، تو آپ صلی اللہ علیہ وسلم اس پر بیٹھتے اور ہم آپ کے اردگرد بیٹھتے، آگے ابوہریرہ رضی اللہ عنہ نے اسی جیسی روایت ذکر کی، اس میں ہے کہ ایک شخص آیا، پھر انہوں نے اس کی ہیئت ذکر کی، یہاں تک کہ اس نے بیٹھے ہوئے لوگوں کے کنارے سے ہی آپ کو یوں سلام کیا: السلام علیک یا محمد! تو نبی اکرم صلی اللہ علیہ وسلم نے اسے سلام کا جواب دیا۔","صحیح",{"u2":"سیدنا ابوذر اور سیدنا ابوہریرہ رضی اللہ عنہما کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ کے درمیان بیٹھا کرتے تھے۔ چنانچہ جب کوئی نو وارد آتا تو وہ آپ صلی اللہ علیہ وسلم کو پہچان نہ پاتا تھا حتیٰ کہ آپ صلی اللہ علیہ وسلم کے متعلق پوچھتا (کہ رسول ا اللہ کون ہیں؟) تو ہم نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا کہ آپ کے لیے خاص جگہ بنا دیں تاکہ نو وارد جب آئے تو آپ کو پہچان لیا کرے۔ چنانچہ ہم نے آپ صلی اللہ علیہ وسلم کے لیے مٹی کا ایک چبوترہ سا بنا دیا اور آپ صلی اللہ علیہ وسلم اس پر بیٹھے لگے اور ہم اس کے اطراف میں بیٹھ جایا کرتے تھے۔ اور مذکورہ بالا خبر (حدیث) کی مانند بیان کیا۔ چنانچہ ایک آدمی آیا اور اس کی شکل و صورت بیان کی، حتیٰ کہ اس نے جماعت کی ایک جانب سے سلام کیا اور کہا: السلام علیک یا محمد! نبی کریم صلی اللہ علیہ وسلم نے اس کے سلام کا جواب دیا۔","f2":"حسب ضرورت اور مصلحت رئیس مجلس اور شیخ یا استاذکو دوسروں کی نسبت نمایاں یا بلند جگہ پر بیٹھنا جائز ہے،بشرطیکہ تکبر کا اظہار نہ ہو"}],[4699,"ابن دیلمی ۱؎ کہتے ہیں کہ میں ابی بن کعب رضی اللہ عنہ کے پاس آیا اور ان سے کہا: میرے دل میں تقدیر کے بارے میں کچھ شبہ پیدا ہو گیا ہے، لہٰذا آپ مجھے کوئی ایسی چیز بتائیے جس سے یہ امید ہو کہ اللہ اس شبہ کو میرے دل سے نکال دے گا، فرمایا: اگر اللہ تعالی آسمان والوں اور زمین والوں کو عذاب دینا چاہے تو دے سکتا ہے، اور عذاب دینے میں وہ ظالم نہیں ہو گا، اور اگر ان پر رحم کرے تو اس کی رحمت ان کے لیے ان کے اعمال سے بہت بہتر ہے، اگر تم احد کے برابر سونا اللہ کی راہ میں خرچ کر دو تو اللہ اس کو تمہاری طرف سے قبول نہیں فرمائے گا جب تک کہ تم تقدیر پر ایمان نہ لے آؤ اور یہ جان لو کہ جو کچھ تمہیں پہنچا ہے وہ ایسا نہیں ہے کہ نہ پہنچتا، اور جو کچھ تمہیں نہیں پہنچا وہ ایسا نہیں کہ تمہیں پہنچ جاتا، اور اگر تم اس عقیدے کے علاوہ کسی اور عقیدے پر مر گئے تو ضرور جہنم میں داخل ہو گے۔ ابن دیلمی کہتے ہیں: پھر میں عبداللہ بن مسعود رضی اللہ عنہ کے پاس آیا تو انہوں نے بھی اسی طرح کی بات کہی، پھر میں حذیفہ بن یمان رضی اللہ عنہ کے پاس آیا تو انہوں نے بھی اسی طرح کی بات کہی، پھر میں زید بن ثابت رضی اللہ عنہ کے پاس آیا تو انہوں نے مجھ سے اسی کے مثل نبی اکرم صلی اللہ علیہ وسلم کی ایک مرفوع روایت بیان کی۔\n§وضاحت\n۱؎ : یعنی ابوالبسر عبداللہ بن فیروز الدیلمی۔","صحیح",{"u2":"جناب (عبداللہ بن فیروز) ابن دیلمی نے کہا کہ احد پہاڑ جتنا سونا بھی ا اللہ تعالیٰ کی راہ میں خرچ کر ڈالو تو جب تک تقدیر پر ایمان نہیں لاؤ گے ا اللہ تعالیٰ اسے تم سے قبول نہیں کرے گا اور (جب تک) یہ نہ جان لو کہ جو کچھ تمہیں پہنچا ہے، وہ کسی صورت فوت نہیں ہو سکتا تھا اور جو حاصل نہیں ہوا، وہ کسی صورت حاصل نہیں ہو سکتا تھا۔ اگر تم اس عقیدے کے سوا کسی اور پر مر گئے تو جہنم میں جاؤ گے۔ (ابن دیلمی) کہتے ہیں کہ پھر میں سیدنا عبداللہ مسعود رضی اللہ عنہ کے پاس گیا تو انہوں نے بھی ایسے ہی کہا۔ انہوں نے کہا: پھر میں سیدنا حذیفہ بن یمان رضی اللہ عنہ کے پاس گیا، تو انہوں نے بھی ایسے ہی کہا۔ پھر میں سیدنا زید بن ثابت رضی اللہ عنہ کے پاس گیا، تو انہوں نے بھی مجھ سے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مثل بیان کیا۔","f2":"دین وایمان کے مسائل میں حق الیقین حاصل کرنے کے لئے مختلف علمائے راسخین سے رجوع کرتے رہنا چاہیے۔ اس سے بہت فائدہ ہوتا ہے اور جو شفا رسول صلی اللہ علیہ وسلم کی احادیث مبارکہ میں ہے وہ اور کہیں نہیں"}],[4700,"ابوحفصہ کہتے ہیں کہ عبادہ بن صامت رضی اللہ عنہ نے اپنے بیٹے سے کہا: اے میرے بیٹے! تم ایمان کی حقیقت کا مزہ ہرگز نہیں پا سکتے جب تک کہ تم یہ نہ جان لو کہ جو کچھ تمہیں ملا ہے وہ ایسا نہیں کہ نہ ملتا اور جو کچھ نہیں ملا ہے ایسا نہیں کہ وہ تمہیں مل جاتا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"سب سے پہلی چیز جسے اللہ تعالی نے پیدا کیا، قلم ہے، اللہ تعالی نے اس سے کہا: لکھ، قلم نے کہا: اے میرے رب! میں کیا لکھوں؟ اللہ تعالی نے کہا: قیامت تک ہونے والی ساری چیزوں کی تقدیریں لکھ\" اے میرے بیٹے! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"جو اس کے علاوہ (کسی اور عقیدے) پر مرا تو وہ مجھ سے نہیں\"۔","صحیح",{"u2":"سیدنا عبادہ بن صامت رضی اللہ عنہ نے اپنے بیٹے سے کہا تھا اور جو حاصل نہیں ہوا ہے، وہ مل نہیں سکتا تھا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ صلی اللہ علیہ وسلم فرماتے تھے ” سب سے پہلی چیز جو ا اللہ نے پیدا فرمائی وہ قلم تھی۔ پھر اس سے فرمایا کہ لکھو ‘ اس نے کہا: اے میرے رب! کیا لکھوں؟ ا اللہ تعالیٰ نے فرمایا: قیامت قائم ہونے تک ہر ہر چیز کی تقدیر لکھ۔ “ اے میرے بیٹے! بیشک میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے آپ صلی اللہ علیہ وسلم فرماتے تھے ” جو شخص اس کے سوا (کسی اور عقیدے) پر مر گیا وہ مجھے سے نہیں۔ “"}],[4701,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آدم اور موسی نے بحث کی تو موسی نے کہا: اے آدم! آپ ہمارے باپ ہیں، آپ ہی نے ہمیں محرومی سے دو چار کیا، اور ہمیں جنت سے نکلوایا، آدم نے کہا: تم موسی ہو تمہیں اللہ تعالی نے اپنی گفتگو کے لیے چن لیا، اور تمہارے لیے تورات کو اپنے ہاتھ سے لکھا، تم مجھے ایسی بات پر ملامت کرتے ہو جسے اس نے میرے لیے مجھے پیدا کرنے سے چالیس سال پہلے ہی لکھ دیا تھا، پس آدم موسی پر غالب آ گئے\" ۱؎۔\n§وضاحت\n۱؎ : یہ بحث و تکرار اللہ کے سامنے ہوئی جیسا کہ مسلم کی روایت میں ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا نے ہمیں بہت گھاٹا دیا اور جنت سے نکال دیا۔ آدم نے کہا: تم موسیٰ ہو، اللہ نے تمہیں اپنے ساتھ ہم کلام ہونے کا شرف بخشا اور تمہارے لیے اپنے ہاتھ سے تورات لکھی۔ تم مجھے ایک ایسی بات (تقدیر) پر ملامت کر رہے ہو جو اس نے میرے پیدا ہونے سے چالیس سال پہلے ہی میرے لیے مقدر کر دی تھی۔ چنانچہ آدم علیہ السلام موسیٰ علیہ السلام پر غالب آ گئے۔ “ احمد بن صالح نے سند یوں بیان کی «عن عمرو عن طاؤس سمع أبا هريرة»۔"}],[4702,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"موسی (علیہ السلام) نے کہا: اے میرے رب! ہمیں آدم علیہ السلام کو دکھا جنہوں نے ہمیں اور خود کو جنت سے نکلوایا، تو اللہ نے انہیں آدم علیہ السلام کو دکھایا، موسی علیہ السلام نے کہا: آپ ہمارے باپ آدم ہیں؟ تو آدم علیہ السلام نے ان سے کہا: ہاں، انہوں نے کہا: آپ ہی ہیں جس میں اللہ نے اپنی روح پھونکی، جسے تمام نام سکھائے اور فرشتوں کو حکم دیا تو انہوں نے آپ کو سجدہ کیا؟ انہوں نے کہا: ہاں، انہوں نے کہا: تو پھر کس چیز نے آپ کو اس پر آمادہ کیا کہ آپ نے ہمیں اور خود کو جنت سے نکلوا دیا؟ تو آدم نے ان سے کہا: اور تم کون ہو؟ وہ بولے: میں موسی ہوں، انہوں نے کہا: تم بنی اسرائیل کے وہی نبی ہو جس سے اللہ نے پردے کے پیچھے سے گفتگو کی اور تمہارے اور اپنے درمیان اپنی مخلوق میں سے کوئی قاصد مقرر نہیں کیا؟ کہا: ہاں، آدم علیہ السلام نے کہا: تو کیا تمہیں یہ بات معلوم نہیں کہ وہ (جنت سے نکالا جانا) میرے پیدا کئے جانے سے پہلے ہی کتاب میں لکھا ہوا تھا؟ کہا: ہاں معلوم ہے، انہوں نے کہا: پھر ایک چیز کے بارے میں جس کے متعلق اللہ تعالی کا فیصلہ میرے پیدا کئے جانے سے پہلے ہی مقدر ہو چکا تھا کیوں مجھے ملامت کرتے ہو؟\" یہاں پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تو آدم، موسی پر غالب آ گئے، تو آدم موسی پر غالب آ گئے\"۔","حسن",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ سے مروی ہے کہ کسی کو واسطہ نہیں بنایا تھا؟ کہا: ہاں۔ آدم علیہ السلام نے کہا: کیا تم نے نہیں پایا کہ یہ سب کچھ میرے پیدا کیے جانے سے پہلے ہی کتاب اللہ میں (ایسے ہی) تھا؟ موسیٰ علیہ السلام نے کہا: ہاں۔ آدم علیہ السلام نے کہا: تو پھر تم مجھے کس چیز پر ملامت کرتے ہو، حالانکہ وہ مجھ سے پہلے ہی اللہ کے فیصلے میں تھی۔ “ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” آدم علیہ السلام موسیٰ علیہ السلام پر دلیل میں غالب آ گئے۔ “","f2":"تقدیر یعنی اللہ عزوجل کا ازلی اور ابدی علم عین برحق ہے،کہیں بھی اس سے ذرہ برابر کچھ مختلف نہیں ہو سکتا،مگر علم بندوں کو مجبور نہیں کرتا۔ انسانوں کے لئے جائز نہیں کہ اپنے آئندہ امور میں تقدیرکو بطور عذراور بہانہ پیش کریں،کیونکہ ہر ایک کو صحیح راہ کا اختیار کرنے اور اس کے مطابق عمل کرنے کا مکلف بنایا گیا ہے،لیکن ماضی کے حقائق میں تقدیر کا بیان بطور عذر،مباح ہے"}],[4703,"مسلم بن یسار جہنی سے روایت ہے کہ عمر بن خطاب رضی اللہ عنہ سے اس آیت «وإذ أخذ ربك من بني آدم من ظهورهم» کے متعلق پوچھا گیا ۱؎۔ (حدیث بیان کرتے وقت) قعنبی نے آیت پڑھی تو آپ نے کہا: جب نبی اکرم صلی اللہ علیہ وسلم سے اس آیت کے بارے میں سوال کیا گیا تو میں نے آپ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ تعالی نے آدم کو پیدا کیا، پھر ان کی پیٹھ پر اپنا داہنا ہاتھ پھیرا، اس سے اولاد نکالی اور کہا: میں نے انہیں جنت کے لیے پیدا کیا ہے، اور یہ جنتیوں کے کام کریں گے، پھر ان کی پیٹھ پر ہاتھ پھیرا تو اس سے بھی اولاد نکالی اور کہا: میں نے انہیں جہنمیوں کے لیے پیدا کیا ہے اور یہ اہل جہنم کے کام کریں گے\" تو ایک شخص نے کہا: اللہ کے رسول! پھر عمل سے کیا فائدہ؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی جب بندے کو جنت کے لیے پیدا کرتا ہے تو اس سے جنتیوں کے کام کراتا ہے، یہاں تک کہ وہ جنتیوں کے اعمال میں سے کسی عمل پر مر جاتا ہے، تو اس کی وجہ سے اسے جنت میں داخل کر دیتا ہے، اور جب کسی بندے کو جہنم کے لیے پیدا کرتا ہے تو اس سے جہنمیوں کے کام کراتا ہے یہاں تک کہ وہ جہنمیوں کے اعمال میں سے کسی عمل پر مر جاتا ہے تو اس کی وجہ سے اسے جہنم میں داخل کر دیتا ہے\"۔\n§وضاحت\n۱؎ : اور یاد کرو اس وقت کو جب تمہارے رب نے آدم کی اولاد کو اُن کی پشتوں سے نکالا۔","صحیح",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ سے «وإذ أخذ ربك من بني آدم من ظهورهم» ” اور جب تیرے رب نے بنو آدم کی پیٹھوں سے ان کی اولاد نکالی اور انہیں خود انہی پر گواہ ٹھہرایا، کیا میں تمہارا رب نہیں ہوں؟ انہوں نے کہا: ہاں، ہم اقرار کرتے ہیں۔ “ کی تفسیر پوچھی گئی تو سیدنا عمر رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ سے اس کے بارے میں پوچھا گیا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ عزوجل نے آدم علیہ السلام کو پیدا کیا، پھر اپنا داہنا ہاتھ اس کی پشت پر پھیرا اور اس سے اس کی اولاد نکالی اور فرمایا: ان کو میں نے جنت کے لیے پیدا کیا ہے اور یہ جنتیوں والے عمل کریں گے۔ پھر اس کی پشت پر ہاتھ پھیرا اور اس سے اس کی اولاد نکالی اور فرمایا: ان کو میں نے دوزخ کے لیے پیدا کیا ہے اور یہ دوزخیوں والے عمل کریں گے۔ “ ایک آدمی نے کہا: اے اللہ کے رسول! تو پھر عمل کیونکر ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ اللہ عزوجل نے جب بندے کو جنت کے لیے پیدا کیا ہے تو اس سے اہل جنت والے عمل کرواتا ہے حتیٰ کہ وہ اہل جنت کے عمل کرتا ہوا مر جائے گا تو اللہ انہی اعمال کی وجہ سے اسے جنت میں داخل فر دے گا اور جب کسی بندے کو آگ کے لیے پیدا کیا ہے تو اس سے دوزخیوں والے عمل کرواتا ہے حتیٰ کہ وہ دوزخیوں والے عمل کرتا ہوا مر جائے تو اللہ اسی کے سبب سے اسے آگ میں ڈال دے گا۔“","f2":"اولاد آدم کے ایک طبقے کا جنت کے لئے دوسرے کا جہنم کے لئے پیدا کیے جانے کا مطلب یہ ہے کہ اللہ کے علم کے مطابق ایک گروہ اچھے عمل کرتے کرتے جنت میں دوسرا برے عمل کرتے کرتے جہنم میں جائے گا۔ جس طرح اللہ کا علم یے یقینی اور حتمی طور پر ایساہی ہو گا۔ اس بات کو اس طرح کہا جاسکتاہے کہ ایک جنت کے لئے اور دوسرا جہنم کے لئے پیدا کیا گیا ہے۔ مگر اس سے یہ سمجھناصحیح نہیں کہ انسان مجبور محض ہے،کیونکہ انسان کو پورا اختیار اور عمل کی تمام تر صلاحیتیں دے کر پیدا کیا گیا ہے۔ انسان جو کچھ کرتاہے وہ یقینا اللہ کی مشیت کے دائرے کے اند ررہ کر کرتا ہے،لیکن اپنے اس اختیار سے کرتا ہے جو اسے ودیعت کیا گیا ہے اور اسی پر جزا اور سزا مرتب ہونے والی ہے۔ بعض حضرات نے اس روایت کو صحیح قرار دیا ہے"}],[4704,"نعیم بن ربیعہ کہتے ہیں کہ میں عمر بن خطاب رضی اللہ عنہ کے پاس تھا، پھر انہوں نے یہی حدیث روایت کی، مالک کی روایت زیادہ کامل ہے۔","صحیح",{"u2":"جناب نعیم بن ربیعہ کہتے ہیں کہ میں سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس تھا، اور حدیث روایت کی۔ اور (مذکورہ بالا) حدیث مالک زیادہ مکمل ہے۔"}],[4705,"ابی بن کعب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ لڑکا جسے خضر (علیہ السلام) نے قتل کر دیا تھا طبعی طور پر کافر تھا اگر وہ زندہ رہتا تو اپنے ماں باپ کو سرکشی اور کفر میں مبتلا کر دیتا\"۔","صحیح",{"u2":"سیدنا ابی بن کعب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” وہ لڑکا جسے خضر نے قتل کیا تھا وہ کافر پیدا کیا گیا تھا۔ اگر زندہ رہتا تو اپنے ماں باپ کو سرکشی اور کفر پر مجبور کر دیتا۔“","f2":"1: وہ کافر پیدا کیا گیا تھا کا مطلب یہی ہے کہ اس نے اللہ کی طرف سے ودیعت کردہ اختیار سے کام لیتے ہوئے کفر ہی کرنا تھا اور یہ بات اللہ کو پہلے سے معلوم تھی۔\n2:حضرت خضر اور حضرت موسی علیہ السلام کا دلچسپ واقعہ سورۃ کہف میں اور اس کی تفصیلات صحیین میں موجود ہیں۔\n3: حضرت خضر اللہ کی طرف سے عطا کردہ خا ص علم کے حامل اور کچھ کاموں کے مکلف تھے،اس لئے اس پر کوئی قیاس نہیں ہو سکتا"}],[4706,"ابی بن کعب رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اللہ تعالی کے فرمان «وأما الغلام فكان أبواه مؤمنين»\"اور رہا لڑکا تو اس کے ماں باپ مومن تھے\" (سورۃ الکہف: ۸۰) کے بارے میں فرماتے سنا کہ وہ پیدائش کے دن ہی کافر پیدا ہوا تھا۔","صحیح",{"u2":"سیدنا ابی بن کعب رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: آپ اللہ تعالیٰ کے فرمان «وأ الغلام فكان أبواه مؤمنين» ” اور اس لڑکے کے ماں باپ مومن تھے۔ “ کی تفسیر میں فر رہے تھے ” وہ لڑکا جس دن پیدا کیا گیا، کافر پیدا کیا گیا تھا۔ “","f2":"1: وہ اس کے مطابق ہی پیدا ہوا جو اس کے لئے اللہ کے علم میں تھا کہ وہ کفر کرے گا۔\n2:ہر مسلمان کو اپنی عاقبت کے بارے میں فکر مند رہنا چاہیے،ہمیشہ برے انجام سے پناہ اور خیر وسعادت کی دعا کرتے رہنا چاہیے، اے اللہ! تمام امور میں ہمارا انجام بہترین بنا اور دنیا کی رسوائی ا"}],[4707,"ابی بن کعب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خضر (علیہ السلام) نے ایک لڑکے کو بچوں کے ساتھ کھیلتے دیکھا تو اس کا سر پکڑا، اور اسے اکھاڑ لیا، تو موسی (علیہ السلام) نے کہا: کیا تم نے بےگناہ نفس کو مار ڈالا؟\"۔","صحیح",{"u2":"سیدنا ابی بن کعب رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” سیدنا خضر علیہ السلام نے لڑکے کو دیکھا جو دوسرے بچوں کے ساتھ کھیل رہا تھا۔ تو انہوں نے اس کا سر پکڑ کر مروڑ دیا۔ تو موسیٰ علیہ السلام بولے ” آپ نے ایک پاک جان کو قتل کر ڈالا ہے۔ “","f2":"1: حضرت موسی علیہ السلام اپنی شریعت کے پابند تھے،بظاہر ایک برائی کو دیکھ کر اس کی مخالفت کرناان کا فرض تھا،مگر معاملہ درحقیقت اور تھا جس سے وہ آگاہ نہ تھے، حضرت خضر آگاہ تھے۔\n2:اللہ ہی کے پاس ہر غیب کا علم ہے اس کی مخلوق میں سے کسی کے پاس بھی غیب کا علم نہیں ہے،خواہ کوئی رسول اور نبی ہو یا صالح بزرگ اور ولی،سوائے اس کے جس پر اللہ نے اپنے انبیاء ورسل کو مطلع کردیا۔ قرآن مقدس کا یہ مقام اس بات کی مکمل صراحت کررہا ہے کہ اللہ تعالی نے خضر علیہ السلام کو ایک بات کی خبر دے دی تو وہ ان کومعلوم ہو گئی اور حضرت موسی علیہ السلام جیسے جلیل القدر پیغمبر،نبوت ورسالت کے ساتھ ساتھ کلیم اللہ جیسے اونچے مقام کے حامل انسان کو اس کی خبر نہیں دی تو انہیں اس کا کچھ بھی علم نہ سکا"}],[4708,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں ہم سے رسول اللہ صلی اللہ علیہ وسلم نے (آپ صادق اور آپ کی صداقت مسلم ہے) بیان فرمایا:\"تم میں سے ہر شخص کا تخلیقی نطفہ چالیس دن تک اس کی ماں کے پیٹ میں جمع رکھا جاتا ہے، پھر اتنے ہی دن وہ خون کا جما ہوا ٹکڑا رہتا ہے، پھر وہ اتنے ہی دن گوشت کا لوتھڑا رہتا ہے، پھر اس کے پاس ایک فرشتہ بھیجا جاتا ہے اور اسے چار باتوں کا حکم دیا جاتا ہے: تو وہ اس کا رزق، اس کی عمر، اس کا عمل لکھتا ہے، پھر لکھتا ہے: آیا وہ بدبخت ہے یا نیک بخت، پھر وہ اس میں روح پھونکتا ہے، اب اگر تم میں سے کوئی جنتیوں کے عمل کرتا ہے، یہاں تک کہ اس (شخص) کے اور اس (جنت) کے درمیان صرف ایک ہاتھ یا ایک ہاتھ کے برابر فاصلہ رہ جاتا ہے کہ کتاب (تقدیر) اس پر سبقت کر جاتی ہے اور وہ جہنمیوں کے کام کر بیٹھتا ہے تو وہ داخل جہنم ہو جاتا ہے، اور تم میں سے کوئی شخص جہنمیوں کے کام کرتا ہے یہاں تک کہ اس (شخص) کے اور اس (جہنم) کے درمیان صرف ایک ہاتھ یا ایک ہاتھ کے برابر کا فاصلہ رہ جاتا ہے کہ کتاب (تقدیر) اس پر سبقت کر جاتی ہے، اب وہ جنتیوں کے کام کرنے لگتا ہے تو داخل جنت ہو جاتا ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے بیان فرمایا، اور آپ صادق اور مصدوق ہیں۔ (اللہ تعالیٰ کی طرف سے اور اس کے ملائکہ، انبیاء و رسل اور مومنین کی جانب سے آپ کی تصدیق کی گئی ہے) ” تمہاری پیدائش کے مراحل میں نطفہ ماں کے پیٹ میں چالیس دن تک مجتمع رہتا ہے، پھر اتنے ہی دن ج ہوا خون (لوتھڑا) بن جاتا ہے۔ پھر اتنے ہی دنوں کے لیے گوشت کی بوٹی بن جاتا ہے۔ پھر اللہ تعالیٰ اس کی طرف ایک فرشتہ بھیجتا ہے اور اسے چار باتیں لکھنے کا حکم ہوتا ہے۔ وہ اس کا رزق، اجل (عمر یا موت)، عمل اور یہ کہ وہ خوش بخت ہو گا یا بدبخت، یہ سب لکھ دیتا ہے۔ پھر اس میں روح پھونک دی جاتی ہے۔ چنانچہ یقیناً تم میں سے کوئی اہل جنت والے عمل کرتا ہے حتیٰ کہ اس کے اور اس (جنت) کے درمیان صرف ایک ہاتھ کا فاصلہ رہ جاتا ہے، مگر اس سے پہلے جس طرح لکھا ہوا ہے اس کے مطابق دوزخیوں والے عمل شروع کر دیتا ہے اور دوزخ میں جا پڑتا ہے۔ اور بیشک تم میں سے کوئی دوزخیوں والے عمل کرتا رہتا ہے حتیٰ کہ اس کے اور دوزخ کے درمیان صرف ایک ہاتھ کا فاصلہ رہ جاتا ہے، لیکن اس سے پہلے جو لکھا ہے اس کے مطابق وہ جنتیوں والا عمل کر لیتا ہے اور جنت میں چلا جاتا ہے۔ “","f2":"1: بظاہر اگر کوئی انسان ایک راہ پر جارہا ہوتو یہ نہیں سمجھنا چاہیے کہ وہ ہمیشہ اسی راہ پر چلتا رہے گا اس کے اگر آخر میں جا کر بھی راستہ بدل لینا ہے تو یہ سب پہلے سے اللہ کے علم کے مطابق لکھا ہواہے۔\n2: تقدیرکا معاملہ سراسر غیب کا معاملہ ہے،انسان کو خود بھی خیر کے عمل کرکے دھوکے میں نہیں پڑنا چاہیے کہ بس بخشا گیا یا غلط ہونے کی وجہ سے بابکل ہی مایوس نہیں ہونا چاہیے کہ بس مارا گیا،بلکہ ہمیشہ اللہ الرحمن الرحیم سے بھلائی کی توفیق مانگتے رہنا چاہیے اور غلط کشی سے فورا تونہ کرنی چاہیے اے دلوں کے بدلنے والے،مجھے اپنے دین کی اطاعت پر ثابت قدم رکھ۔۔۔۔اور اے دلوں کے پھیرنے والے!میرے دل کو اپنی اطاعت کی طرف پھیر دے"}],[4709,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا گیا: اللہ کے رسول! کیا جنتی اور جہنمی پہلے ہی معلوم ہو چکے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\" اس نے کہا: پھر عمل کرنے والے کس بنا پر عمل کریں؟ آپ نے فرمایا: \"ہر ایک کو توفیق اسی بات کی دی جاتی ہے جس کے لیے وہ پیدا کیا گیا ہے\"۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: اے اللہ کے رسول! کیا دوزخیوں کے مقابلے میں جنتیوں کو جانا جا چکا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہاں “ کہا گیا: تو پھر عمل کرنے والے کیونکر عمل کرتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہر ایک کو اسی کی توفیق ملتی ہے جس کے لیے اسے پیدا کیا گیا ہے۔“","f2":"اس حدیث میں تقدیرکو صراحتا(اللہ کا)علم قراردیا گیا ہے اس معنی کی احادیث میں اہل خیر کو ایک حد تک خیر کی بشارت اور امید دلائی گئی ہے اور دوسروں کے لئے تنبیہ اور توبہ کی دعوت ہے"}],[4710,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم منکرین تقدیر کے پاس نہ بیٹھو اور نہ ہی ان سے سلام و کلام کی ابتداء کرو\"۔","ضعیف",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” منکرین تقدیر کے ساتھ مت بیٹھا کرو اور نہ ان سے بات چیت (یا مناظرے) کی ابتداء کیا کرو۔ “"}],[4711,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں پوچھا گیا، تو آپ نے فرمایا:\"اللہ بہتر جانتا ہے کہ وہ زندہ رہتے تو کیا عمل کرتے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے متعلق پوچھا گیا (جو بچپن میں فوت ہو جاتے ہیں) تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اللہ کو خوب علم ہے کہ وہ (بڑے ہو کر) کیا عمل کرنے والے تھے۔“"}],[4712,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے عرض کیا: اللہ کے رسول! مومنوں کے بچوں کا کیا حال ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ اپنے ماں باپ کے حکم میں ہوں گے\" میں نے عرض کیا: اللہ کے رسول! بغیر کسی عمل کے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ زیادہ بہتر جانتا ہے کہ وہ کیا عمل کرتے\" میں نے عرض کیا: اللہ کے رسول! اور مشرکین کے بچے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے ماں باپ کے حکم میں ہوں گے\" میں نے عرض یا بغیر کسی عمل کے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ بہتر جانتا ہے کہ وہ کیا عمل کرتے\" ۱؎۔\n§وضاحت\n۱؎ : ام المومنین عائشہ رضی اللہ عنہا کا سوال ان بچوں کے متعلق تھا جو قبل بلوغت انتقال کر گئے تھے، رسول اکرم صلی اللہ علیہ وسلم کا جواب یہ ہے کہ وہ اپنے والدین کے ساتھ ہی رہیں گے، اگرچہ ان سے کوئی کفر یا نیک عمل صادر نہ ہوا، لیکن اللہ بہتر جانتا ہے کہ وہ اگر زندہ رہتے تو کیا کرتے۔","صحیح الإسناد",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کہتی ہیں کہ میں نے عرض کیا: اے اللہ کے رسول! مومنوں کی اولادوں کا کیا انجام ہو گا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” وہ اپنے آباء میں سے ہیں۔ “ میں نے کہا: اے اللہ کے رسول! عمل کے بغیر ہی؟ فرمایا ” اللہ کو خوب علم ہے کہ وہ کیا عمل کرنے والے تھے۔ “ میں نے عرض کیا: اے اللہ کے رسول! مشرکوں کی اولادوں کا انجام کیا ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” وہ اپنے آباء میں سے ہیں “ میں نے کہا: عمل کے بغیر ہی؟ فرمایا ” اللہ کو بہتر علم ہے جو وہ عمل کرنے والے تھے۔ “","f2":"بچوں کا کیا انجام ہوگا؟ یہ قابل غور مسئلہ ہے۔ وہ فطرت اسلام پر پیدا ہوتے ہیں چاہے مسلمان کے گھر پیدا ہوں چاہے کا فر کے (صحيح البخاري ‘كتاب التفسير ‘سورت الروم‘باب (لاتبديل الخلق الله حديث٤٧٧٥) كفار اپنے بچوں کو اپنے دین کے مطابق ڈھال کر کافر بنا لیتے ہیں، اس باب کی احادیث٤٧١٤ اور٤٧١٦ سے یہ حقیقت واضح ہے۔غیر مسلموں اور مشرکوں کے بچے سن تمیز سے پہلے فوت ہو جائیں اور ان کے والدین کا فر ہوں تو دنیا میں ان کا حکم کافروں کا ہو گا،انہیں نہ غسل دیا جائے گانہ کفن دیا جائے گا،نہ جنازہ پڑھا جائے گا او ر نہ ہی انہیں مسلمانوں کے ساتھدفن کیا جائے گا،کیونکہ وہ اپنے والدین کے ساتھ ہی کافر ہیں اورآخرت میں ان کا معاملہ اللہ تعالی کے سپرد ہے،صحیح حدیث میں ہے کہ رسول صلی اللہ علیہ وسلم سے جب مشرکوں کے بچوں کے بارے میں پوچھا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا اللہ تعالی ان بابت زیادہ بہتر جانتا ہے کہ وہ کیا عمل کرنے والے تھے؟ ان کے بارے میں صحیح ترین قول یہ ہے کہ اللہ تعالی قیامت کے دن انہیں کوئی حکم دے کر ان کی آزمائش کرے گا اور اگر وہ اللہ تعالی کے حکم کی اطاعت کرلیں گے تو اللہ تعالی انہیں جنت میں داخل کرے گااور اگر وہ نافرمانی کریں گے تو پھر اللہ تعالی انہیں جہنم رسید کرے گا۔\nصحیح احادیث سے ثابت ہے کہ اہل فترہ(جن کے پاس انبیا کی دعوت نہ پہنچی ہوگی۔) کا قیامت کے دن امتحان ہو گا۔اہل فترہ کی بابت سب سے زیادہ صحیح اور راجحقول یہی ہے،جسے شیخ الاسلام ان تیمیہ،امام بن قیم۔فضیلہ محمد بن صالح العثمین اور فضیلہ الشیخ عبدلعزیز عبداللہ بن باز رحمہ اللہ نے بھی اختیار کیا ہے اسی طرح جو لوگ ان کے حکم میں ہوں گے مثلا مشرکوں کے بچے،ان کا بھی امتحان ہو گا کیو نکہ ارشاد باری تعالی ہے کہ اور جب تک ہم پیغمبر نہ بھجیں ہم عذاب نہیں دیا کرتے"}],[4713,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس انصار کا ایک بچہ نماز پڑھنے کے لیے لایا گیا، میں نے عرض کیا: اللہ کے رسول! زندگی کے مزے تو اس بچے کے لیے ہیں، اس نے نہ کوئی گناہ کیا اور نہ ہی وہ اسے (گناہ کو) سمجھتا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! کیا تم ایسا سمجھتی ہو حالانکہ ایسا نہیں ہے؟ اللہ تعالی نے جنت کو پیدا کیا اور اس کے لیے لوگ بھی پیدا کئے اور جنت کو ان لوگوں کے لیے جب بنایا جب وہ اپنے آباء کی پشتوں میں تھے، اور جہنم کو پیدا کیا اور اس کے لیے لوگ بھی پیدا کئے گئے اور جہنم کو ان لوگوں کے لیے پیدا کیا جب کہ وہ اپنے آباء کی پشتوں میں تھے\" ۱؎۔\n§وضاحت\n۱؎ : ام المومنین عائشہ رضی اللہ عنہا کے کہنے کا مطلب یہ تھا کہ چونکہ اس بچے نے کوئی گناہ نہ کیا اس لئے یہ تو یقینا جنتی ہے، رسول اکرم صلی اللہ علیہ وسلم نے اس یقین کی تردید فرمائی کہ بلا دلیل کسی کو جنتی کہنا درست نہیں، جنتی یا جہنمی ہونے کا فیصلہ تو اللہ نے انسان کے دنیا میں آنے سے قبل ہی کر دیا ہے، اور وہ ہمیں معلوم نہیں تو ہم کسی کو حتمی اور یقینی طور پر جنتی یا جہنمی کیسے کہہ سکتے ہیں، یہ حدیث مندرجہ بالا حدیث سے معارض معلوم ہوتی ہے جس میں یہ بیان کیا گیا ہے کہ مسلمان بچے جو بچپن ہی میں مر جائیں گے اپنے والدین کے ساتھ ہوں گے، نیز علماء کا اس پر تقریباً اتفاق ہے کہ مسلمانوں کے بچے جنتی ہیں، اس حدیث کا یہ جواب دیا گیا کہ عائشہ رضی اللہ عنہا کو جنتی یا جہنمی کا فیصلہ کرنے میں جلد بازی سے روکنا مقصود تھا اور بس، بعض نے کہا :یہ اس وقت کی بات ہے جب رسول اکرم صلی اللہ علیہ وسلم کو بتایا نہیں گیا تھا کہ مسلم بچے جنتی ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے بیان کیا، انہوں نے کہا کہ نبی کریم صلی اللہ علیہ وسلم کے پاس انصاریوں کا ایک بچہ لایا گیا کہ آپ صلی اللہ علیہ وسلم اس کی نماز جنازہ پڑھائیں۔ کہتی ہیں کہ میں نے کہا: اے اللہ کے رسول! مبارک ہو اسے! اس نے کوئی برا عمل نہیں کیا، نہ برے عملوں کی اسے کوئی خبر ہی ہوئی۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” عائشہ! یا پھر اس سے مختلف؟ بیشک اللہ عزوجل نے جنت پیدا فرمائی تو اس کے لیے مخلوق بھی پیدا کر دی اور اس جنت کو انہی کے لیے بنایا جبکہ وہ ابھی اپنے باپوں کی پشتوں میں ہوتے ہیں۔ اور ا ٓگ (جہنم) پیدا کی تو اس کے لیے مخلوق بھی پیدا کر دی اور اس جہنم کو ان ہی لوگوں کے لیے بنایا جبکہ وہ ابھی اپنے باپوں کی پشتوں میں ہوتے ہیں۔ “"}],[4714,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر بچہ فطرت (اسلام) پر پیدا ہوتا ہے، پھر اس کے والدین اسے یہودی یا نصرانی بنا ڈالتے ہیں، جیسے اونٹ صحیح و سالم جانور سے پیدا ہوتا ہے تو کیا تمہیں اس میں کوئی کنکٹا نظر آتا ہے؟\" لوگوں نے عرض کیا: اللہ کے رسول! آپ کا اس کے بارے میں کیا خیال ہے جو بچپنے میں مر جائے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ خوب جانتا ہے کہ وہ کیا عمل کرتے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہر پیدا ہونے والا بچہ فطرت پر پیدا ہوتا ہے (دین حق، اسلام اور توحید کا حامل ہوتا ہے) پھر اس کے ماں باپ اسے یہودی اور عیسائی بنا دیتے ہیں، جیسے اونٹ کا بچہ صحیح سالم جنم لیتا ہے، کیا تم کسی کو کان کٹا پاتے ہو؟ “ لوگوں نے کہا: اے اللہ کے رسول! اس کے متعلق فرمائیں جو چھوٹی عمر میں فوت ہو جاتا ہے؟ فرمایا ” اللہ کو بہتر علم ہے جو وہ عمل کرتے۔“","f2":"بچہ بنیادی طور ہر دین فطرت یعنی اگر و ہ والدین،اساتذہ اور ماحول سے متاثر نہ ہو تو دین حق ہی پر پروان چڑھے، مگر برے ماحول اور غلط تربیت کے زیر اثر وہ دین حق سے دور ہو جاتا ہے۔"}],[4715,"ابن وہب کہتے ہیں کہ میں نے مالک کو کہتے سنا، ان سے پوچھا گیا: اہل بدعت (قدریہ) اس حدیث سے ہمارے خلاف استدلال کرتے ہیں؟ مالک نے کہا: تم حدیث کے آخری ٹکڑے سے ان کے خلاف استدلال کرو، اس لیے کہ اس میں ہے: صحابہ نے پوچھا کہ بچپن میں مرنے والے کا کیا حکم ہے؟ تو آپ نے فرمایا: \"اللہ خوب جانتا ہے کہ وہ کیا عمل کرتے\"۔","صحیح الإسناد",{"u2":"امام مالک رضی اللہ عنہ سے کہا گیا کہ اہل اہواء، یعنی بدعتی لوگ یہ مذکورہ حدیث ہمارے خلاف پیش کرتے ہیں (انکار تقدیر اور اثبات جبر میں) امام مالک رضی اللہ عنہ نے کہا: تم اسی حدیث کے آخری حصے کو ان پر الٹا دیا کرو۔ (جس میں ہے کہ) لوگوں نے کہا: اس بچے کے متعلق فرمائیں جو چھوٹی عمر میں فوت ہو جاتا ہے؟ آپ نے فرمایا ” اللہ کو بہتر علم ہے جو وہ عمل کرتے۔ “","f2":"رسول صلی اللہ علیہ وسلم کے جواب سے واضح ہو ا کہ ان کا فیصلہ ان کے اس عمل اور امتحان ہر ہو گا جو محشر میں ہو گا،اور اس میں جبر مکمل طور پر نفی ہے۔"}],[4716,"حجاج بن منہال کہتے کہ میں نے حماد بن سلمہ کو «كل مولود يولد على الفطرة» \"ہر بچہ فطرت (اسلام) پر پیدا ہوتا ہے\" ۱؎ کی تفسیر کرتے سنا، آپ نے کہا: ہمارے نزدیک اس سے مراد وہ عہد ہے جو اللہ نے ان سے اسی وقت لے لیا تھا، جب وہ اپنے آباء کی پشتوں میں تھے، اللہ نے ان سے پوچھا تھا: «ألست بربكم قالوا بلى» \"کیا میں تمہارا رب (معبود) نہیں ہوں؟\" تو انہوں نے کہا تھا: کیوں نہیں، ضرور ہیں۔\n§وضاحت\n۱؎ : فطرت اسلام پر پیدا ہونے کی تاویل اس طرح بیان فرمائی کہ چونکہ میثاق الٰہی کے مطابق ہر ایک نے اللہ کی وحدانیت کا اقرار کیا تھا، لہٰذا اسی اقرار پر وہ پیدا ہوتا ہے، بعد میں لوگ اس کو یہودی، نصرانی ، مجوسی یا مشرک بنا لیتے ہیں۔","صحیح الإسناد",{"u2":"جناب حماد بن سلمہ نے حدیث ” ہر بچہ فطرت پر پیدا ہوتا ہے۔ “ کی تشریح میں کہا کہ اس کا مفہوم ہمارے نزدیک یہ ہے کہ یہ اس وقت کی بات ہے جب اللہ عزوجل نے روحوں سے عہد لیا جبکہ وہ اپنے باپوں کی پشتوں میں تھے، اس وقت کہا تھا «ألست بربكم» ” کیا میں تمہارا رب نہیں ہوں؟ “ تو سب نے کہا: کیوں نہیں۔"}],[4717,"عامر شعبی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" «وائدہ» (زندہ درگور کرنے والی) اور «مؤودہ» (زندہ درگور کی گئی دونوں) جہنم میں ہیں\" ۱؎۔ یحیی بن زکریا کہتے ہیں: میرے والد نے کہا: مجھ سے ابواسحاق نے بیان کیا ہے کہ عامر شعبی نے ان سے اسے بیان کیا ہے، وہ علقمہ سے اور علقمہ، ابن مسعود رضی اللہ عنہ سے اور ابن مسعود نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔\n§وضاحت\n۱؎ : «وائدہ» اور «مؤودہ» سے کیا مراد ہے؟ بعض محدثین نے «وائدہ» سے زندہ درگور کرنے والی عورت، اور «مؤودہ» سے زندہ درگور کی گئی بچی مراد لی ہے، اس صورت میں ان حضرات کا کہنا یہ ہے کہ نبی کریم صلی اللہ علیہ وسلم نے یہ ایک خاص بچی کے بارے میں فرمایا، یہ حکم عام نہیں ہے، بعض محدثین کے نزدیک «وائدہ» سے مراد زندہ درگور کرنے والی عورت، اور «مؤودہ» سے مراد وہ عورت ہے جو اپنی بچی کو زندہ درگور کرنے پر راضی ہو، اس صورت میں اس پر کوئی اعتراض نہیں۔","صحیح",{"u2":"جناب عامر شعبی رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بچے کو زندہ دفن کرنے والی اور زندہ دفن ہونے والی (دونوں) آگ میں ہیں۔ “ یحییٰ بن زکریا نے کہا: میرے والد نے کہا کہ مجھے ابواسحاق نے بیان کیا کہ عامر نے اس کو یہ حدیث بواسطہ علقمہ، سیدنا ابن مسعود رضی اللہ عنہ سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیان کی تھی۔","f2":"جس کو کم سنی میں ظلما دفن کر دیا گیا وہ جہنم کی مستحق نہیں ہو سکتی۔ حضرت ابن عباس رضی اللہ نے وضاحت سے کہا ہے کہ وہ موودہ کے جہنمی ہونے کا نظریہ درست نہیں۔ انہوں نے فرمایاآیت(ما كنا معذبين حتي نبعث رسول)(بني اسرائيل:١٥) كے مطابق عاقل وبالغ کو اگر اسے دعوت نہ پہنچی ہو عذاب نہیں دیا جا سکتا تو غیر عاقل کو کیسے دیا جا سکتا ہے۔ پہلے وضاحت ہو چکی ہے کہ مشرکین کی اولاد کو بھی عذاب نہ ہو گا۔ حدیث١٤٧١٧ ایک طویل حدیث کا حصہ ہے۔ اصل حدیث کا ایک حصہ ہے۔اصل حدیث میں تفصٰل ہے کہ سلمہ بن بزید جعفی اور ان کے بھائی رسول صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اورعرض کی کہ ہماری والدہ ملیکہ(جو جاہلیت میں مر گئیں)اچھی خاتون تھیں،صلہ رحمی اور مہمان نوازی کرنے والی تھیں،کیا ا ن باتوں کا ان کی والدہ کو فائدہ ہو گا؟آپ صلی اللہ علیہ وسلم نے فرمایا نہیں، انہوں نے پوچھا ہماری ماں نے ہماری ایک بہن کو زندہ دگن کردیا تھا،کیا اسے کوئی فائد ہ ہو گا؟آپ صلی اللہ علیہ وسلم نے فرمایا: (یہ) زندہ دفن کرنے والی اور زندہ دفن ہونےھ والی دونوں آگ میں ہیں۔گویا آپ کا جواب ایک خاص موودہ کے بارے میں تھا۔ یہ عام حکم نہ تھا غالبا یہ موودہ کفر کے عالم میں ہی بالغ ہو چکی تھی۔"}],[4718,"انس رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے عرض کیا: اللہ کے رسول! میرے والد کہاں ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"تمہارے والد جہنم میں ہیں\" جب وہ پیٹھ پھیر کر چلا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے والد اور تیرے والد دونوں جہنم میں ہیں\" ۱؎۔\n§وضاحت\n۱؎ : امام نووی فرماتے ہیں کہ اس سے صاف ظاہر ہے اہل فترہ (عیسی علیہ السلام کے بعد اور نبی اکرم صلی اللہ علیہ وسلم کی بعثت سے پہلے کے لوگ) اگر مشرک ہیں تو جہنمی ہیں، کیونکہ ان کو دعوت ابراہیمی پہنچی تھی، نبی اکرم صلی اللہ علیہ وسلم کے والد کے بارے میں یہ حدیث نص صریح ہے، علامہ سیوطی وغیرہ نے جو لکھا ہے کہ اللہ تعالی نے ان کو دوبارہ زندہ فرمایا، یا وہ ایمان لائے اور پھر مر گئے ،تو یہ محض موضوع من گھڑت روایات پر مبنی ہے، ائمہ حدیث مثلا دارقطنی، جورقانی، ابن شاہین، ابن عساکر، ابن ناصر، ابن الجوزی، سہیلی، قرطبی، محب الطبری، ابن سیدالناس، ابراہیم الحلبی وغیرہم نے ان احادیث کو مکذوب مفتری اور موضوع قرار دیا ہے، علامہ ابراہیم حلبی نے اس بارے میں مستقل کتاب لکھی ہے، اسی طرح ملا علی قاری نے شرح فقہ اکبر میں اور ایک مستقل کتاب میں یہ ثابت کیا ہے کہ رسول اکرم صلی اللہ علیہ وسلم کے والدین کے ایمان کی بات غلط محض ہے، علی کل حال اس مسئلہ میں زیادہ نہیں پڑنا چاہیئے بلکہ اپنی نجات کی فکر کرنی چاہیئے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ نے بیان کیا کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے کہا: اے اللہ کے رسول! میرا باپ کہاں ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تیرا باپ آگ میں ہے۔ “ جب اس نے گردن پھیری تو آپ صلی اللہ علیہ وسلم نے فرمایا ” میرا باپ اور تیرا باپ جہنم میں ہیں۔“","f2":"ایمان وعمل کے بغیر محض نسب اور قرابت داری کسی کے باعث نجات نہیں۔\n2:ایسی تمام روایات جن میں رسول صلی اللہ علیہ وسلم کے والدین کو دوبارہ زندہ کیے جانے اور ان کے اسلام کرنے کا ذکر ہے ضعیف اور ناقاقبل حجت ہیں۔\n3:اس بارے میں بحث وگفتگو کی بجائے سکوت (خاموشی) بہتر ہے۔"}],[4719,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"شیطان ابن آدم (انسان) کے بدن میں اسی طرح دوڑتا ہے جس طرح خون رگوں میں گردش کرتا ہے\"۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ شیطان ابن آدم کے جسم میں اس طرح گردش کرتا ہے جیسے خون۔ “","f2":"انسان کے جسم میں شیطان کی گردش کانتیجہ اوہام،وساوس اور اللہ تعالی کی نافرمانی کی صورت میں سامنے آتا ہےاس کے فتنوں سے بچنے کا واحد ذریعہ ایمان اور عمل صالح کے ساتھ ساتھ کثرت ذکر کرے،ورنہ اس کے حملوں سے بچنا بہت مشکل ہے اور سب عزوجل کی تقدیر اور مشیت سے ہے۔"}],[4720,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"منکرین تقدیر کے پاس نہ بیٹھو اور نہ ہی ان سے بات چیت میں پہل کرو ۱؎\"۔\n§وضاحت\n۱؎ : جہمیہ: اہل بدعت کا ایک مشہور فرقہ ہے جو اللہ کی صفات کا منکر ہے اور قرآن کو مخلوق کہتا ہے ، ائمہ دین کی بہت بڑی تعداد نے ان کی تکفیر کی ہے۔","ضعیف",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” منکرین تقدیر کی صحبت سے بچو اور ان سے بات چیت (اور مناظرے) میں ابتداء نہ کیا کرو۔ “"}],[4721,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگ ایک دوسرے سے برابر سوال کرتے رہیں گے یہاں تک کہ یہ کہا جائے گا، اللہ نے تمام مخلوقات کو پیدا کیا تو اللہ کو کس نے پیدا کیا؟ لہٰذا تم میں سے کسی کو اس سلسلے میں اگر کوئی شبہ گزرے تو وہ یوں کہے: میں اللہ پر ایمان لایا\" ۱؎۔\n§وضاحت\n۱؎ : اگر آدمی کو کوئی اس طرح کا شیطانی وسوسہ لاحق ہو تو اس کو دور کرنے اور ذہن سے جھٹکنے کی پوری کوشش کرے اور یوں کہے: میں اللہ پر ایمان لا چکا ہوں، صحیحین کی روایت میں ہے: میں اللہ و رسول پر ایمان لا چکا ہوں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” لوگ سوالات کرتے رہیں گے حتیٰ کہ کہا جائے گا: یہ مخلوق اللہ نے پیدا کی ہے تو اللہ کو کس نے پیدا کیا؟ سو جو کوئی اس قسم کی بات کرے (یا وہم پائے) تو اسے چاہیئے کہ یوں کہے ” میں اللہ پر ایمان لایا۔“"}],[4722,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، پھر اس جیسی روایت ذکر کی، البتہ اس میں ہے، آپ نے فرمایا: \"جب لوگ ایسا کہیں تو تم کہو: «الله أحد * الله الصمد * لم يلد ولم يولد * ولم يكن له كفوا أحد» \"اللہ ایک ہے وہ بے نیاز ہے ۱؎، اس نے نہ کسی کو جنا اور نہ وہ کسی سے جنا گیا اور نہ کوئی اس کا ہمسر ہے\" پھر وہ اپنے بائیں جانب تین مرتبہ تھوکے اور شیطان سے پناہ مانگے\"۔\n§وضاحت\n۱؎ : احد وہ ہے جس کا کوئی مثیل و نظیر نہ ہو ، صمد وہ کہ سب اس کے محتاج ہوں وہ بے نیاز ہے، کسی کا محتاج نہیں۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، کہتے تھے، اور مذکورہ بالا کی مانند بیان کیا۔ کہا: ” جب وہ لوگ یہ کہیں تو تم کہو: اللہ ایک ہے۔ اللہ بے نیاز ہے۔ نہ اس نے جنا اور نہ وہ جنا گیا اور کوئی نہیں جو اس کی برابری کر سکے۔ پھر چاہیئے کہ بائیں جانب کچھ لعاب تھوکے اور شیطان کے شر سے اللہ کی پناہ مانگے۔ “"}],[4723,"عباس بن عبدالمطلب رضی اللہ عنہ کہتے ہیں کہ میں بطحاء میں ایک جماعت کے ساتھ تھا، جس میں رسول اللہ صلی اللہ علیہ وسلم بھی موجود تھے، اتنے میں بادل کا ایک ٹکڑا ان کے پاس سے گزرا تو آپ نے اس کی طرف دیکھ کر پوچھا: \"تم اسے کیا نام دیتے ہو؟\" لوگوں نے عرض کیا: «سحاب» (بادل)، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اور «مزن» بھی\" لوگوں نے کہا: ہاں «مزن» بھی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اور «عنان» بھی\" لوگوں نے عرض کیا: اور «عنان» بھی، (ابوداؤد کہتے ہیں: «عنان» کو میں اچھی طرح ضبط نہ کر سکا)آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا تمہیں معلوم ہے کہ آسمان اور زمین کے درمیان کتنی دوری ہے؟\" لوگوں نے عرض کیا: ہمیں نہیں معلوم، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان دونوں کے درمیان اکہتر یا بہتر یا تہتر سال کی مسافت ہے، پھر اسی طرح اس کے اوپر آسمان ہے\" یہاں تک کہ آپ صلی اللہ علیہ وسلم نے سات آسمان گنائے \"پھر ساتویں کے اوپر ایک سمندر ہے جس کی سطح اور تہہ میں اتنی دوری ہے جتنی کہ ایک آسمان اور دوسرے آسمان کے درمیان ہے، پھر اس کے اوپر آٹھ جنگلی بکرے ہیں جن کے کھروں اور گھٹنوں کے درمیان اتنی لمبائی ہے جتنی ایک آسمان سے دوسرے آسمان تک کی دوری ہے، پھر ان کی پشتوں پر عرش ہے، جس کے نچلے حصہ اور اوپری حصہ کے درمیان کی مسافت اتنی ہے جتنی ایک آسمان سے دوسرے آسمان کی، پھر اس کے اوپر اللہ تعالی ہے\"۔\n§وضاحت\n۱؎ : یعنی فرشتے ان کی شکل میں ہیں۔","ضعیف",{"u2":"سیدنا عباس بن عبدالمطلب رضی اللہ عنہ سے روایت ہے کہتے ہیں کہ میں وادی بطحاء میں ایک جماعت میں بیٹھا ہوا تھا جس میں رسول اللہ صلی اللہ علیہ وسلم بھی تشریف فر تھے، وہاں سے بادل کا ایک ٹکڑا گزرا۔ آپ صلی اللہ علیہ وسلم نے اس کی طرف دیکھا اور پوچھا ” تم لوگ اسے کیا کہتے ہو؟“ انہوں نے کہا: «سحاب» آپ صلی اللہ علیہ وسلم نے فرمایا ” اور «مزن» بھی؟ “ انہوں نے کہا: ہاں «مزن» بھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اور «عنان» بھی کہتے ہو؟ “ انہوں نے کہا: ہاں «عنان» بھی کہتے ہیں۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں مجھے «العنان» کا ذکر کوئی زیادہ اچھی طرح یاد نہیں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا جانتے ہو آسمان اور زمین میں کتنا فاصلہ ہے؟ “ انہوں نے کہا: ہمیں معلوم نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ان دونوں کے درمیان اکہتر یا بہتر یا تہتر سال کا فاصلہ ہے۔ پھر اس کے بعد دوسرے آسمان کا بھی اتنا ہی فاصلہ ہے۔ “ حتیٰ کہ آپ نے سات آسمان شمار کیے۔ پھر فرمایا ” ساتویں کے اوپر سمندر ہے جس کی گہرائی اور اونچائی اس قدر ہے جیسے ایک آسمان سے دوسرے آسمان تک، پھر اس کے اوپر آٹھ بکرے ہیں جن کے کھروں اور گھٹنوں کے درمیان اس قدر فاصلہ ہے جیسے ایک آسمان سے دوسرے آسمان تک، پھر ان کی پشتوں پر عرش ہے، جس کی تہہ اور اونچائی میں اتنا ہی فاصلہ ہے جیسے ایک آسمان سے دوسرے آسمان تک۔ پھر اس سے اوپر اللہ تبارک و تعالیٰ ہے۔“"}],[4724,"اس سند سے بھی سماک سے اسی مفہوم کی حدیث مروی ہے۔","ضعیف",{"u2":"جناب عمرو بن ابوقیس نے بواسطہ سماک اپنی سند سے مذکورہ بالا حدیث کے ہم معنی روایت کیا۔"}],[4725,"اس سند سے بھی سماک سے اسی لمبی حدیث کا مفہوم مروی ہے۔","ضعیف",{"u2":"جناب ابراہیم بن طہمان نے بواسطہ سماک اس کی سند سے مذکورہ بالا طویل حدیث کے ہم معنی بیان کیا۔"}],[4726,"جبیر بن مطعم رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک اعرابی آیا اور کہا: اللہ کے رسول! لوگ مصیبت میں پڑ گئے، گھربار تباہ ہو گئے، مال گھٹ گئے، جانور ہلاک ہو گئے، لہٰذا آپ ہمارے لیے بارش کی دعا کیجئے، ہم آپ کو سفارشی بناتے ہیں اللہ کے دربار میں، اور اللہ کو سفارشی بناتے ہیں آپ کے دربار میں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا برا ہو، سمجھتے ہو تم کیا کہہ رہے ہو؟\" پھر رسول اللہ صلی اللہ علیہ وسلم سبحان اللہ کہنے لگے، اور برابر کہتے رہے یہاں تک کہ اس کا اثر آپ صلی اللہ علیہ وسلم کے اصحاب کے چہروں پر دیکھا گیا، پھر فرمایا: \"تمہارا برا ہو اللہ کو اس کی مخلوق میں سے کسی کے دربار میں سفارشی نہیں بنایا جا سکتا، اللہ کی شان اس سے بہت بڑی ہے، تمہارا برا ہو! کیا تم جانتے ہو اللہ کیا ہے، اس کا عرش اس کے آسمانوں پر اس طرح ہے (آپ نے انگلیوں سے گنبد کے طور پر اشارہ کیا) اور وہ چرچراتا ہے جیسے پالان سوار کے بیٹھنے سے چرچراتا ہے، (ابن بشار کی حدیث میں ہے) اللہ تعالی اپنے عرش کے اوپر ہے، اور اس کا عرش اس کے آسمانوں کے اوپر ہے\" اور پھر پوری حدیث ذکر کی۔ عبدالاعلی، ابن مثنی اور ابن بشار تینوں نے یعقوب بن عتبہ اور جبیر بن محمد بن جبیر سے ان دونوں نے محمد بن جبیر سے اور محمد بن جبیر نے جبیر بن مطعم سے روایت کی ہے۔ البتہ احمد بن سعید کی سند والی حدیث ہی صحیح ہے، اس پر ان کی موافقت ایک جماعت نے کی ہے، جس میں یحیی بن معین اور علی بن مدینی بھی شامل ہیں اور اسے ایک جماعت نے ابن اسحاق سے روایت کیا ہے جیسا کہ احمد بن سعید نے بھی کہا ہے، اور عبدالاعلی، ابن مثنی اور ابن بشار کا سماع جیسا کہ مجھے معلوم ہوا ہے، ایک ہی نسخے سے ہے۔","ضعیف",{"u2":"جناب جبیر بن محمد بن جبیر بن مطعم اپنے والد محمد سے وہ اپنے دادا جبیر بن مطعم سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک اعرابی آیا۔ اس نے کہا: اے اللہ کے رسول! جانوں پہ بن آئی ہے ‘ بال بچے ہلاک ہو رہے ہیں ‘ مال ختم ہو گئے ہیں ‘ اور مویشی مر رہے ہیں ‘ اللہ سے ہمارے لیے بارش طلب کیجئیے۔ ہم اللہ کے حضور آپ کی سفارش پیش کرتے ہیں اور اللہ کو آپ کے حضور سفارشی لاتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” افسوس تجھ پر! کیا جانتے ہو کہ تم کیا کہہ رہے ہو؟ “ اور رسول اللہ صلی اللہ علیہ وسلم مسلسل تسبیح (سبحان اللہ) کہتے رہے حتیٰ کہ اس (خوف کے اثر) کو آپ صلی اللہ علیہ وسلم کے صحابہ کرام کے چہروں پر محسوس کیا گیا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” افسوس تجھ پر! اللہ تعالیٰ کو اس کی مخلوق میں سے کسی کے ہاں سفارشی پیش نہیں کیا جا سکتا۔ اللہ تعالیٰ کی شان اس سے کہیں زیادہ با عظمت (اور برتر) ہے۔ افسوس تجھ پر! کیا تم جانتے ہو کہ اللہ کی کیا شان ہے؟ بلاشبہ اس کا عرش آسمانوں پر اس طرح ہے۔ “ اور آپ صلی اللہ علیہ وسلم نے اپنی انگلیوں سے قبے کی سی شکل بنائی۔ اور فرمایا ” وہ عرش اس طرح سے چرچرا رہا ہے جیسے پالان اپنے سوار کے ساتھ چرچراتا ہے۔ “ ابن بشار نے اپنی روایت میں کہا: ” بلاشبہ اللہ تعالیٰ اپنے عرش سے اوپر ہے۔ اور اس کا عرش اس کے آسمانوں سے اوپر ہے۔ “ بواسطہ یعقوب بن عتبہ اور جبیر بن محمد بن جبیر ‘ اس نے اپنے والد سے اس نے اپنے دادا سے روایت کی۔ امام ابوداؤد رضی اللہ عنہ نے کہا: اور حدیث احمد بن سعید کی سند سے ہی صحیح ہے۔ اور جماعت محدثین نے اس کی موافقت کی ہے جن میں یحییٰ بن معین اور علی بن مدینی بھی ہیں۔ اور ایک جماعت نے ابن اسحاق سے اسی طرح روایت کیا ہے جیسے احمد نے کہا: اور جیسے کہ مجھے روایت پہنچی ہے عبدالاعلیٰ ‘ ابن مثنیٰ اور ابن بشار کا سماع ایک ہی نسخے سے ہے۔"}],[4727,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مجھے اجازت ملی ہے کہ میں عرش کے اٹھانے والے فرشتوں میں سے ایک فرشتے کا حال بیان کروں جو عرش کو اٹھائے ہوئے ہیں، اس کے کان کی لو سے اس کے مونڈھے تک کا فاصلہ سات سو برس کی مسافت ہے ۱؎\"۔\n§وضاحت\n۱؎ : عمدہ گھوڑے کی چال سے جیسا کہ دوسری حدیث میں مروی ہے، اس حدیث کا مقصود حاملین عرش کا طول و عرض اور عظمت و جثہ بتانا ہے، اور ستر کا عدد بطور تحدید نہیں ہے بلکہ اس سے کثرت مراد ہے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مجھے کہا گیا ہے کہ میں تمہیں حاملین عرش میں سے ایک فرشتہ کے متعلق بتاؤں۔ بلاشبہ اس کے کانوں کی لو سے اس کے کندھے تک کا فاصلہ سات سو سال کے سفر کے برابر ہے۔ “","f2":"جب اللہ عزوجل کی مخلوق میں سے ایک فرشتے کی بڑائی کا یہ حال ہے تواللہ عزوجل کی عظمت وکبریائی اوربڑائی کا کیا ٹھکا نا ہو گا۔ جو بلا شبہ ہمارے لئے ناقابل تصور ہے اور وہ بے مثل وبے مثال ہے۔"}],[4728,"ابوہریرہ رضی اللہ عنہ کے غلام ابو یونس سلیم بن جبیر کہتے ہیں کہ میں نے ابوہریرہ رضی اللہ عنہ کو آیت کریمہ «إن الله يأمركم أن تؤدوا الأمانات إلى أهلها *** إلى قوله تعالى *** سميعا بصيرا» \"اللہ تمہیں حکم دیتا ہے کہ تم امانتوں کو ان کے مالکوں تک پہنچا دو۔ ۔ ۔ اللہ سننے اور دیکھنے والا ہے\" (سورۃ النساء: ۵۸) تک پڑھتے سنا، وہ کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ اپنے انگوٹھے کو اپنے کان پر اور انگوٹھے کے قریب والی انگلی کو آنکھ پر رکھتے، (یعنی شہادت کی انگلی کو)، ابوہریرہ کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اسے پڑھتے اور اپنی دونوں انگلیوں کو رکھتے دیکھا۔ ابن یونس کہتے ہیں: عبداللہ بن یزید مقری نے کہا: یعنی«إن الله سميع بصير» پر انگلی رکھتے تھے، مطلب یہ ہے کہ اللہ کے کان اور آنکھ ہے۔ ابوداؤد کہتے ہیں: یہ جہمیہ کا رد ہے ۱؎۔\n§وضاحت\n۱؎ : اس حدیث میں جہمیہ کا رد بلیغ ہے، جہمیہ اللہ کے لئے صفت سمع و بصر کی نفی کرتے ہیں، رسول اکرم صلی اللہ علیہ وسلم نے انگوٹھا اور انگلی رکھ کر ان کی تردید فرما دی، جہمیہ تشبیہ سے بچنے کے لئے ایسا کہتے ہیں، جب کہ اس میں تشبیہ ہے ہی نہیں، مقصود صفت سمع (سننا) صفت بصر (دیکھنا) کا اثبات ہے، یہ مقصود نہیں کہ اس کی آنکھ وکان ہماری آنکھ اور کان جیسے ہیں، بلکہ اللہ تعالی کی آنکھ کان اس کی عظمت وجلال کے لائق ہیں، بلا کسی کیفیت تشبیہ، وتمثیل اور تعطیل کے سبحانہ تعالی۔","صحیح الإسناد",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے یہ آیت کریمہ پڑھی «إن الله يأمركم أن تؤدوا الأمانات إلى أهلها *** إلى قوله تعالى *** سميعا بصيرا» ” بلاشبہ اللہ تمہیں حکم دیتا ہے کہ امانتیں ان کے حقداروں کو پہنچا دو اور جب لوگوں کے درمیان فیصلہ کرو تو عدل و انصاف کے ساتھ فیصلہ کرو ‘ اللہ اچھی نصیحت کرتا ہے ‘ بلاشبہ اللہ خوب سننے والا خوب دیکھنے والا ہے۔ “ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم اپنا انگوٹھا اپنے کان پر اور ساتھ والی انگلی اپنی آنکھ پر رکھ رہے تھے۔ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم اس آیت کو پڑھتے ہوئے اپنی انگلیاں (کان اور آنکھ پر) رکھ رہے تھے۔ ابن یونس نے روایت کیا کہ عبداللہ بن زید مقری نے کہا: مقصد یہ ہے کہ بلاشبہ اللہ تعالیٰ سمیع و بصیر ہے یعنی وہ خوب سنتا اور خوب دیکھتا ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس میں جہمیہ کی تردید ہے (اللہ عزوجل ان صفات سے فی الوقع متصف ہے)۔","f2":"یہ اور اس معنی کی دیگر احادیث میں بنی صلی اللہ علیہ وسلم کا کان اور آنکھ کی طرف اشارہ کرنا تشبیہ کے لئے نہیں،بلکہ صفت سمع اور بصر کے اثبات اور سامعین کے لئے تقریب معنی کے لئے تھا۔ کیو نکہ قرآن کریم میں بصراحت واردہے(ليس كمثله شي ءوهوالسميع البصير (الشوري:١١) اس کی مثل کو ئی چیز نہیں،وہ خوب سننے والا او ر خوب دیکھنے والا ہے۔"}],[4729,"جریر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ آپ نے چودہویں شب کے چاند کی طرف دیکھا، اور فرمایا: \"تم لوگ عنقریب اپنے رب کو دیکھو گے، جیسے تم اسے دیکھ رہے ہو، تمہیں اس کے دیکھنے میں کوئی زحمت نہ ہو گی، لہٰذا اگر تم قدرت رکھتے ہو کہ تم فجر اور عصر کی نماز میں مغلوب نہ ہو تو ایسا کرو\" پھر آپ نے یہ آیت «فسبح بحمد ربك قبل طلوع الشمس وقبل غروبها» \"اور اپنے رب کی تسبیح کرو، سورج کے نکلنے اور ڈوبنے سے پہلے\" (سورۃ طہٰ: ۱۳۰)پڑھی ۱؎۔\n§وضاحت\n۱؎ : قیامت میں موحدین کو اللہ تعالی کا دیدار نصیب ہو گا، اہل سنت و الجماعت اور صحابہ و تابعین کا یہی مسلک ہے، جہمیہ و معتزلہ اور بعض مرجئہ اس کے خلاف ہیں، ان کے پاس کوئی دلیل قرآن و سنت سے موجود نہیں ہے، محض تاویل اور بعض بے بنیاد شبہات کے بل بوتے پر انکار کرتے ہیں، اس باب میں ان کی تردید مقصود ہے۔","صحیح",{"u2":"سیدنا جریر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے ہوئے تھے کہ آپ صلی اللہ علیہ وسلم نے چاند کی طرف نظر اٹھائی جبکہ رات چودھویں کی تھی اور چاند خوب چمک رہا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم اپنے رب کو دیکھو گے جیسے اس کو دیکھ رہے ہو ‘ اس کے دیکھنے میں کوئی جمگھٹا نہیں ہو گا چنانچہ اگر کر سکتے ہو تو یہ کرو کہ سورج نکلنے اور غروب ہونے سے پہلے کی نمازوں میں مغلوب نہ ہو جاؤ ‘ پھر آپ صلی اللہ علیہ وسلم نے یہ آیت تلاوت فرمائی: «فسبح بحمد ربك قبل طلوع الشمس وقبل غروبها» ” پس اپنے رب کی حمد بیان کر ‘ سورج طلوع ہونے سے پہلے اور اس کے غروب ہونے سے پہلے۔ “","f2":"قیامت میں اور جنت میں رب ذوالجلال کا دیدار عین حق ہے اور یہ شرف اہل ایمان کو انتہائی آسانی کے ساتھ اور بغیر کسی دھکم پیل کے حاصل ہو گا۔ مگر وہی ایمان دار اس سے بہرہ ور ہوں گے جو نمازوں کی پابندی کرنے والے ہوں گے۔\n2: جو شخص طلوع آفتاب سے پہلے فجر اور غروب آفتاب سے پہلے نماز عصر کی پابندی کر لے وہ نمازوں سے بھی غافل نہیں روہ سکتا۔\n3: رسول صلی اللہ علیہ وسلم کا چاند کی طرف دیکھ کر یہ مسئلہ بیان کرنا نظر کو نظرسے تشبیہ دینے کے لئے تھا۔ ورنہ عزوجل کے مثل کوئی شے نہیں ہے۔"}],[4730,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ کچھ لوگوں نے عرض کیا: اللہ کے رسول! کیا قیامت کے دن ہم اپنے رب کو دیکھیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تمہیں دوپہر کے وقت سورج کو دیکھنے میں کوئی زحمت ہوتی ہے جب کہ وہ بدلی میں نہ ہو؟\" لوگوں نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم چودہویں رات کے چاند کو دیکھنے میں دقت محسوس کرتے ہو، جب کہ وہ بدلی میں نہ ہو؟\" لوگوں نے عرض کیا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس ذات کی قسم جس کے ہاتھ میں میری جان ہے تمہیں اللہ کے دیدار میں کوئی دقت نہ ہو گی مگر اتنی ہی جتنی ان دونوں میں سے کسی ایک کے دیکھنے میں ہوتی ہے ۱؎\"۔\n§وضاحت\n۱؎ : اور چونکہ ان کے دیکھنے میں کوئی دقت نہیں ہوتی اسی طرح اللہ کے دیدار میں بھی دقت نہ ہو گی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ لوگوں نے پوچھا: اے اللہ کے رسول! کیا قیامت کے روز ہم اپنے رب عزوجل کو دیکھیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بھلا عین دوپہر کے وقت ‘ جب فضا میں کوئی بادل وغیرہ نہ ہو ‘ تمہیں سورج کے دیکھنے میں کوئی الجھن یا مشکل ہوتی ہے؟ “ انہوں نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تمہیں چودھویں کی رات میں ‘ جب کوئی بادل وغیرہ نہ ہو ‘ چاند کے دیکھنے میں کوئی دقت ہوتی ہے؟ “ انہوں نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! تمہیں اس کے دیکھنے میں کوئی دقت اور مشکل نہیں ہو گی مگر اتنی ہی جتنی چاند یا سورج کے دیکھنے میں ہوتی ہے۔ “ (کوئی مشکل نہیں ہو گی)۔","f2":"سورج کے دیکھنے سے مراد محض دیکھنا ہے ٹکٹکی لگا کر مسلسل اسی طرف دیکھتے ہی رہنا نہیں۔"}],[4731,"ابورزین عقیلی رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! کیا ہم میں سے ہر ایک اپنے رب کو (قیامت کے دن) بلا رکاوٹ دیکھے گا؟ اور اس کی مخلوق میں اس کی مثال کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے ابورزین! کیا تم سب چودہویں کا چاند بلا رکاوٹ نہیں دیکھتے؟\" میں نے عرض کیا: کیوں نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو اللہ تو اور بھی بڑا ہے\" ابن معاذ کی روایت میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تو اللہ کی مخلوقات میں سے ایک مخلوق ہے، اللہ تو اس سے بہت بڑا اور عظیم ہے ۱؎\"۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ جب اس کی مخلوق کو ہر ایک بلا روک ٹوک دیکھ لیتا ہے تو اللہ کو جو اس سے بہت ہی بڑا ہے کیوں نہیں دیکھ سکتا ؟۔","حسن",{"u2":"سیدنا ابورزین (لقیط بن عامر) رضی اللہ عنہ نے بیان کیا کہ میں نے کہا: اے اللہ کے رسول! کیا ہم سب اپنے رب کو دیکھیں گے؟ عبیداللہ بن معاذ کے الفاظ ہیں: کیا ہم سب قیامت کے روز اسے الگ الگ دیکھیں گے ‘ تو مخلوق میں اس کی کیا علامت ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” اے ابورزین! کیا تم میں سے ہر کوئی چاند کو نہیں دیکھتا ہے؟ “ ابن معاذ کے الفاظ ہیں ” کیا چودھویں کی رات کو ہر کوئی اسے اکیلے اکیلے نہیں دیکھتا ہے؟ “ پھر دونوں راویوں کا اتفاق ہے، میں نے کہا: کیوں نہیں (اس کو دیکھنے میں دقت یا ازدحام نہیں ہوتا)۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ تو اللہ کی شان بہت بلند ہے۔ “ ابن معاذ کے الفاظ ہیں ‘ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ تو اللہ کی ایک مخلوق کا حال ہے اور اللہ کی شان بےانتہا بلند ہے۔ “"}],[4732,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے روز اللہ آسمانوں کو لپیٹ دے گا، پھر انہیں اپنے دائیں ہاتھ میں لے لے گا، اور کہے گا: میں ہوں بادشاہ، کہاں ہیں ظلم و قہر کرنے والے؟ کہاں ہیں تکبر اور گھمنڈ کرنے والے؟ پھر زمینوں کو لپیٹے گا، پھر انہیں اپنے دوسرے ہاتھ میں لے لے گا، پھر کہے گا: میں ہوں بادشاہ، کہاں ہیں ظلم و قہر کرنے والے؟ کہاں ہیں اترانے والے؟\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” قیامت کے دن اللہ تعالیٰ آسمانوں کو لپیٹ لے گا اور انہیں اپنے داہنے ہاتھ میں لے گا اور کہے گا: میں ہی بادشاہ ہوں۔ کہاں ہیں جابر؟ کہاں ہیں تکبر کرنے والے؟ پھر زمینوں کو لپیٹ لے گا اور انہیں پکڑے گا۔ ابن العلاء نے کہا: انہیں دوسرے ہاتھ میں پکڑے گا اور فرمائے گا: میں ہی بادشاہ ہوں۔ کہاں ہیں جابر؟ کہاں ہیں تکبر کرنے والے؟ “","f2":"اللہ عزوجل کی صفات میں وارد الفاظ واضح اور صریح ہیں، ہم انہیں اپنے رب تعالی کے حق میں بلا جھجک استعمال کرسکتے ہیں اور کرتے ہیں لیکن ان کی حقیقت کا ہمیں کوئی ادراک نہیں کیونکہ (لیس کمثلہ شئی وھوالسمیع البصیر)(الشوری)\n2:اللہ کے دو ہاتھ ہیں اور دونوں ہی داہنے ہیں اور اللہ تعالی کلام کرنے سے موصوف ہے۔\n3:حقیقی بادشاہ تو اب بھی اللہ عزوجل ہی ہے،مگر دنیا میں نام کے بادشاہ موجود ہیں اورا ن میں جبار اور متکبر بھی ہیں لیکن محشر میں کسی کا کوئی وجود نہیں ہو گا اور بادشاہت صرف ایک اکیلے اللہ کی ہوگی۔"}],[4733,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہمارا رب ہر رات آسمان دنیا پر اترتا ہے، جب رات کا آخری تہائی حصہ باقی رہ جاتا ہے اور کہتا ہے: کون ہے جو مجھے پکارے، میں اس کی پکار کو قبول کروں؟ کون ہے جو مجھ سے مانگے میں اسے دوں؟ کون ہے جو مجھ سے مغفرت طلب کرے میں اسے معاف کر دوں ۱؎\"۔\n§وضاحت\n۱؎ : دونوں احادیث میں اللہ کی صفات کا ذکر ہے جن کا جہمیہ انکار کرتے ہیں، علماء سلف کا مسلک اس بارے میں یہ ہے کہ صفات باری تعالی جس طرح قرآن وسنت میں وارد ہیں ان کو جوں کا توں باقی رکھا جائے نہ ان کا انکار کیا جائے، اور نہ ان کی تاویل کی جائے، شیخ الاسلام علامہ ابن تیمیہ کی کتاب شرح حدیث النزول دیکھیے جو اس بارے میں دلائل سے پُر اور اپنے باب میں عدیم النظیر ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہر رات جب اس کا آخری تہائی حصہ باقی ہوتا ہے تو ہمارا رب تعالیٰ آسمان دنیا کی طرف اترتا ہے اور ندا دیتا ہے کون ہے جو مجھے پکارے ‘ میں اس کی سنوں اور قبول کروں؟ کون ہے جو مجھ سے مانگے اور میں اس کو عطا کروں؟ کون ہے جو مجھ سے بخشش طلب کرے اور میں اس کو بخش دوں؟ “","f2":"اللہ عزوجل کا آسمان دنیا پر تشریف لانا حق ہے اس کاندادینا بھی حق ہے او راس کی ان صفات کی حقیقت ویسی ہی ہے جو اس کی شان عظمت وجلال کے لائق ہے ان پر ایمان رکھنا واجبا ان کاانکا ر کفر،ان کی تاویل اورا ن صفات کی حقیقت کی ٹوہ لگانا یا اس کا سوال کرنا بدعت ہے۔\n2:فرض نمازوں کے بعد نوافل کے لئے رات کا آخری پہر اللہ سے لو لگانے اور دعا کی قبولیت کا انتہائی شاندار وقت ہوتا ہے۔"}],[4734,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم خود کو موقف (عرفات میں ٹھہرنے کی جگہ) میں لوگوں پر پیش کرتے تھے اور فرماتے: \"کیا کوئی ایسا شخص نہیں ہے جو مجھے اپنی قوم کے پاس لے چلے، قریش نے مجھے میرے رب کا کلام پہنچانے سے روک دیا ہے ۱؎\"۔\n§وضاحت\n۱؎ : رسول اکرم صلی اللہ علیہ وسلم موسم حج میں مختلف قبائل کے پاس جاتے اور ان میں دین اسلام کی تبلیغ کرتے تھے، اسی کی طرف اشارہ ہے، اس حدیث میں قرآن کو کلام اللہ فرمایا گیا ہے جس سے معتزلہ وغیرہ کی تردید ہوتی ہے جو کلام اللہ کو اللہ کی صفت نہ مان کر اس کو مخلوق کہتے تھے، سلف صالحین نے قرآن کو مخلوق کہنے والے گروہ کی تکفیر کی ہے، جب کہ قرآنی نصوص ، احادیث شریفہ اور آثار سلف سے قرآن کا کلام اللہ ہونا ، اور کلام اللہ کا صفت باری تعالی ہونا ثابت ہے، اور اس پر سلف کا اجماع ہے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ (ابتدائی بعثت کے دنوں میں) رسول اللہ صلی اللہ علیہ وسلم میدان عرفات میں اپنے آپ کو لوگوں کے سامنے پیش کرتے تھے اور کہتے تھے: ” سنو! کوئی مجھے اپنی قوم کی طرف لے جائے ‘ بلاشبہ قریش نے مجھے اپنے رب کا کلام پہنچانے سے روک دیا ہے۔ “","f2":"للہ عزوجل صفت کلا م سے موصوف ہے جس کا رسول صلی اللہ علیہ وسلم نے اپنی اولین دعوت میں اظہار فرمایا اور لوگوں نے بھی اسکے ظاہری معنی ہی سمجھے۔ اس پر ہمارا ایمان ہے مگر کلام کرنے کی کیفیت سے ہم آگاہ نہیں اور قرآن مجید بھی اسی کا کلام ہے جو جبرائیل امین علیہ السلام لے کر آئے اور حضرت محمد رسول صلی اللہ علیہ وسلم کے سینے میں اتارا،مسلمان اسے پڑھتے،یاد کرتے اور مصحف کے اوراق میں لکھتے ہیں۔\n2: اللہ تعالی کی ذات جس طرح قدیم ہے،اسی طرح اس کی تمام صفات بھی قدیم ہیں، بنا بریں قرآن مجید اللہ تعالی کا کلام ہے،تو یہ بھی اس کی قدیم اور غیر حادث صفت ہوئی۔ اسی لیے امام احمد بن حنبل اور دیگر محدثین رحمہ اللہ اسے غیر مخلوق کہتے تھے اور معتزلہ اسے مخلوق قراردیتے تھے۔ اس مسئلے میں امام احمد رحمہ اللہ کی استقامت اور اس کی خاطر قیدوبند کی صعوبتیں برداشت کرنا،مشہور معروف ہے۔\n3: عالم اسباب میں رسول صلی اللہ علیہ وسلم کو بھی افراد کے تعاون کی ضرورت تھی جو اس تبلیغ حق میں آپ صلی اللہ علیہ وسلم کے معاون بنتے جو بالا آخر مہاجرین وانصار کی صورت میں آپ کو مل گئے۔ اسی طرح ہر داعی کی بھی ضرورت ہے۔ سوسعادت مند ہیں وہ عظیم لو گ ہیں جو داعیان حق کے دست وبازوبنتے ہیں۔\n4: ظاہری اسباب کے مطابق ایک دوسرے سے مدد مانگنا نہ صرف جائز ہے بلکہ نیکی اور تقوی کے کاموں میں ایک دوسرے کی مدد کرنا فرض ہے اسی لیے نبی کریم صلی اللہ علیہ وسلم نے بھی تبلیغ ودعوت کے کام میں لوگوں سے تعاون طلب کیا اور لوگوں نے بھی ان کے ساتھ تعاون کیا۔ البتہ ماورائے اسباب طریقے سے کسی سے مدد طلب کرنا شرک ہے کیو نکہ اسطرح اللہ تعالئ کے سوا کوئی بھی مدد کرنے پر قادر نہیں ہے۔"}],[4735,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں میرے جی میں میرا معاملہ اس سے کمتر تھا کہ اللہ تعالی میرے بارے میں ایسی گفتگو فرمائے گا کہ وہ ہمیشہ تلاوت کی جائے گی ۱؎۔\n§وضاحت\n۱؎ : یعنی میں اپنے آپ کو اس قابل نہیں سمجھتی تھی کہ اللہ تعالی میرے بارے میں کلام کرے، اور قرآن میں اس کو نازل فرما دے جو ہمیشہ تلاوت کیا جائے، ان کا اشارہ واقعہ افک کی طرف تھا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ میں اپنے آپ کو اس بات سے بہت ہیچ سمجھتی تھی کہ اللہ عزوجل میری برات کے سلسلے میں کوئی ایسا کلام فرمائے گا جس کی تلاوت کی جائے گی۔","f2":"غزوہ نبی مصطلق 5 یا 6 ہجری میں منافقین نے سیدہ عائشہ رضی اللہ پر بہتان کا ایک بہت بڑا پہاڑتوڑدیا تھا جو خود سیدہ کے لئے،رسول صلی اللہ علیہ وسلم اور دیگر تمام اہل ایمان کے لئے انتہائی کرب واذیت کا باعث بنا،مگر اس کا انجام اس اعتبار سے بہت مسرت افزا رہا کہ ان کی برات میں سولہ آیتیں نازل ہوئیں (سورۃالنور آیت 11 سے 26)جو ان کی مدح وستائش میں قیامت تک تلاوت ہوتی رہیں گی۔\n2: اس واقعہ اورروایت میں اللہ عزوجل کی صفت کلام کا ذکر کیا گیا ہے۔\n3: مذکورہ واقعہ ایک حادثہ تھا مگر کلام اللہ کا حادث نہیں ہے۔"}],[4736,"عامر بن شہر رضی اللہ عنہ کہتے ہیں کہ میں نجاشی کے پاس تھا کہ ان کے ایک لڑکے نے انجیل کی ایک آیت پڑھی، تو میں ہنس پڑا انہوں نے کہا: کیا تم اللہ کے کلام پر ہنستے ہو؟","صحیح",{"u2":"جناب عامر بن شہر رضی اللہ عنہ نے روایت کیا انہوں نے کہا کہ میں نجاشی کے دربار میں تھا کہ اس کے بیٹے نے انجیل کی ایک آیت پڑھی ‘ میں ہنس پڑا۔ تو اس نے کہا: کیا تم اللہ تعالیٰ کے کلام سے ہنستے ہو؟","f2":"عیسائیوں کے نزدیک بھی اللہ عزوجل کلام صفت کلام سے موصوف ہے۔ بعض حضرات نے اس روایت کو صحیح قرار دیا ہے۔"}],[4737,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم حسن اور حسین رضی اللہ عنہما کے لیے (ان الفاظ میں) اللہ تعالی پناہ مانگتے تھے «أعيذكما بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة» \"میں تم دونوں کے لیے پناہ مانگتا ہوں اللہ کے پورے کلمات کے ذریعہ، ہر شیطان سے، ہر زہریلے کیڑے (سانپ بچھو وغیرہ) سے اور ہر نظر بد والی آنکھ سے\" پھر فرماتے:\"تمہارے باپ (ابراہیم) اسماعیل و اسحاق کے لیے بھی انہی کلمات کے ذریعہ پناہ مانگتے تھے\"۔ ابوداؤد کہتے ہیں: یہ اس بات کی دلیل ہے کہ قرآن مخلوق نہیں ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم سیدنا حسن اور حسین رضی اللہ عنہ کو ان الفاظ سے دم کیا کرتے تھے «أعيذك بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة» ” میں تم دونوں کو اللہ کے کامل کلمات کی پناہ میں دیتا ہوں کہ ہر شیطان ‘ ہر موذی اور ہر بد نظر کے شر سے محفوظ رہو۔ “ پھر فرماتے: ” تمہارے ابا (سیدنا ابراہیم علیہ السلام) سیدنا اسماعیل علیہ السلام اور سیدنا اسحاق علیہ السلام کو ان کے ذریعے سے پناہ دیا کرتے تھے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: یہ دلیل ہے کہ قرآن کریم مخلوق نہیں۔","f2":"کیونکہ سیدنا خلیل الرحمن یا حضرت محمد رسول صلی اللہ علیہ وسلم کے متعلق تصور نہیں کیا جا سکتا کہ وہ کسی مخلوق کی پناہ حاصل کریں۔\n2:جب ابنیا علیہ السلام کی صالح اولاد اللہ کی امان اور پناہ سے مستغنی نہیں تو دوسرے لوگوں کو تو اس کی احتیاج اور بھی زیادہ ہے۔\n3: مستحب ہے کہ بچوں کو ان مبارک کلمات سے ہمیشہ دم کیا جائے۔"}],[4738,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب اللہ تعالی وحی کے لیے کلام کرتا ہے تو سبھی آسمان والے آواز سنتے ہیں جیسے کسی چکنے پتھر پر زنجیر کھینچی جا رہی ہو، پھر وہ بیہوش کر دئیے جاتے ہیں اور اسی حال میں رہتے ہیں یہاں تک کہ ان کے پاس جبرائیل آتے ہیں، جب جبرائیل ان کے پاس آتے ہیں تو ان کی غشی جاتی رہتی ہے، پھر وہ کہتے ہیں: اے جبرائیل! تمہارے رب نے کیا کہا؟ وہ کہتے ہیں: حق (فرمایا) تو وہ سب کہتے ہیں حق (فرمایا) حق (فرمایا)\"۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب اللہ عزوجل کسی وحی کا کلام فرماتا ہے تو آسمان والے آسمان میں ایک آواز سنتے ہیں جیسے پتھر پر زنجیر گھسیٹی جا رہی ہو ‘ اس سے وہ بیہوش ہو جاتے ہیں اور پھر اسی کیفیت میں رہتے ہیں حتیٰ کہ ان کے پاس جبرائیل آتے ہیں ‘ ان کے آنے سے ان کے دلوں سے یہ کیفیت زائل ہو جاتی ہے اور وہ جبرائیل سے پوچھتے ہیں تمہارے رب نے کیا فرمایا؟ وہ کہتے ہیں: حق فرمایا۔ تو وہ بھی کہتے ہیں: حق فرمایا ‘ حق فرمایا۔ “","f2":"وحی اللہ تعالی کا کلام ہے اللہ عزوجل کے کلام میں آواز بھی ہے جسے جبرئیل امین علیہ السلام اور دیگر فرشتے سنتے ہیں۔ کئی لوگوں کا یہ کہنا کہ اللہ کا کلام آواز سے معری ہے،درست نہیں،حالانکہ کلام آواز ہی سے سنا جاتا ہے۔ جیسے کہ فرمایا پس جب وہاں پہنچے تو اس بابرکت زمین کے میدان کے دائیں کنارے پر درخت میں سے آواز دیے گئے: اےموسی!یقینامیں ہی اللہ ہوں سارے جہانوں کا پروردگار۔ اور ہم نے اس کو آواز دی:اے ابراہیم! اوراللہ کی یہ آوازبے مثل وبے مثال تھی اور ہے۔"}],[4739,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میری شفاعت ۱؎ میری امت کے کبیرہ گناہ کرنے والوں کے لیے ہے ۲؎\"۔\n§وضاحت\n۱؎ : یہ باب خوارج اور بعض معتزلہ کے رد میں ہے جو شفاعت رسول صلی اللہ علیہ وسلم کے منکر ہیں، اہل حدیث و اہل سنت شفاعت کے قائل ہیں۔ ۲؎ : یعنی جن لوگوں کے کبیرہ گناہ ان کے جنت میں جانے سے مانع ہوں گے جبکہ وہ موحد تھے تو ان کے لئے میری شفاعت جنت میں جانے کا ذریعہ ہو گی، لیکن یہ شفاعت اللہ کے حکم اور اس کے اِذْن سے ہوگی جیسا کہ آیت الکرسی میں نیز اس آیت میں ہے «يومئذ لا تنفع الشفاعة إلا من أذن له الرحمن ورضي له قولا» (سورۃ طہ: ۱۰۹) کسی مشرک کو شفاعت نصیب نہ ہو گی، اس لئے ہر آدمی کو اس بات کا خیال رکھنا چاہئے کہ وہ شرک و بدعت کو سمجھے، اور اس بات کی پوری کوشش کرے کہ وہ ان سب سے دور رہے، اور دوسرے لوگوں کو بھی اس سے بچائے، تا کہ رسول اکرم صلی اللہ علیہ وسلم کی شفاعت کا مستحق ہو۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” میری سفارش میری امت کے ان لوگوں کے لیے ہو گی جو کبیرہ گناہوں کے مرتکب ہوئے ہوں گے۔ “","f2":"گناہ گاروں کو امید رکھنی چاہیے کہ ان کی سفارش ہوگی اور انہیں معاف کردیا جائے گامگر ساتھ ہی شدیدخوف بھی چاہیے کیو نکہ یہ بھی معلوم نہیں کہ کس گناہ گارکی شفاعت ہو گی اور کون اس سے محروم رہے گا یا کس کے بارے میں شفاعت ہوگی؟کیونکہ یہ معاملہ سارے کا سارااللہ رب العالمین کی اپنی مشیت پر ہے۔ اگر مشیت ہوئی تو فبہاورنہ شدیدعقاب ہو گا۔ اللہ تعالی کا ارشاد گرامی ہے(ان الله لا يغفرا ن يشرك به ويغفرمادون ذلك لمن يشاء)(النساء٤٨) يقيناالله تعالی اپنے ساتھ شریک کیے جانےکو نہیں بخشااوراس کے سواجسے چاہے بخش دیتا ہے ارشاد ہے (و كم من ملك في السموت لا تغني شفاعتهم شيا الا من بعدان ياذن الله لمن يشاء ويرضي)(النجم ٢٦) اورآسمانوں میں بہت سے فرشتے ہیں جن کی سفارش کچھ نفع نہیں دے سکتی مگر بعداس کے کہ اللہ تعالی جس کے لئے چاہے اور پسند فرمائے تو اجازت دے دے اس دن سفارش کچھ کام نہیں آئے گی مگر جسے رحمن اجازت دےاور اس کی بات کو پسند فرمائے اور یہ لوگ صرف اہل توحید ہوں گے جن کے حق میں اللہ تعالی سفارش کرنے کی اجازت دے گا۔\n2:اس خوشخبری کا مطلب یہ نہیں کہ انسان گناہوں کے ارتکاب میں جری ہو جائے بلکہ خوف کے پہلو کو غالب رکھنا چاہیے کیو نکر میدان حشر کی تکلیف ہ ی ناقابل برداشت ہو گی جہنم تو اس سے بہت زیادہ سخت ہے۔ پھر یہ بھی معلوم نہیں کہ شفاعت قبول ہوتے ہوتے کتنی مدت لگ جائے۔"}],[4740,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کچھ لوگ جہنم سے محمد (صلی اللہ علیہ وسلم) کی سفارش پر نکالے جائیں گے، وہ جنت میں داخل ہوں گے، اور وہ «جهنميين» جہنمی کہہ کر پکارے جائیں گے\"۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ایک گروہ جہنم میں سے محمد صلی اللہ علیہ وسلم کی شفاعت سے نکلے گا اور وہ جنت میں داخل ہوں گے اور ان کا نام «جهنميين» ہو گا۔ “","f2":"یہ لقب جنت میں ان کے لئے اذیت کا باعث نہیں ہو گا اس سے نام محض یہ پتہ چلے گا کہ یہ لوگ جہنم سے آزادشدہ ہیں۔"}],[4741,"جابر رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے سنا: \"جنت والے اس میں کھائیں گے پیئیں گے ۱؎\" ۔\n§وضاحت\n۱؎ : حدیث کا باب سے کوئی تعلق نہیں لیکن وہ اس کے متعلقات سے ہے جنت کی نعمتوں سے جنتی کھائیں گے پیئیں گے لیکن وہ کبھی ختم نہ ہوں گی۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا ” بلاشبہ اہل جنت ‘ جنت میں کھائیں گے اور پیئں گے۔ “","f2":"آخرت میں جنت کی نعمتیں یادوزخ کا عذاب کوئی وہمی باتیں ہیں بلکہ حقیقی امور ہیں۔ البتہ انہیں اس دنیا پر قیاس نہیں کیا جا سکتا۔"}],[4742,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \" «صور» ایک سنکھ ہے، جس میں پھونک ماری جائے گی\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” صور ایک سینگ ہے جس میں پھونک ماری جائے گی۔ “","f2":"حضرت اسرافیل علیہ السلام اپنے منہ میں صورلیے امرالہٰی کے منتظرکھڑے ہیں، جب حکم ہو گا تو وہ اس میں پھونک ماریں گے اورساری دنیا فنا ہو جائے گی پھر اللہ کے حکم سے دوبارہ پھونکیں گے تو سب جی اٹھیں گے۔"}],[4743,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زمین ابن آدم (انسان) کے تمام اعضاء (جسم) کو بجز ریڑھ کی نچلی ہڈی کے کھا جاتی ہے اس لیے کہ وہ اسی سے پیدا ہوا ہے ۱؎، اور اسی سے اسے دوبارہ جوڑ کر اٹھایا جائے گا\"۔\n§وضاحت\n۱؎ : تخلیق انسان کی ابتداء اسی سے ہوتی ہے، اور شاید وہ بہت چھوٹی ہوتی ہے جو لوگوں کو محسوس نہیں ہوتی، اس حدیث کے حکم سے انبیاء کرام مستثنی ہیں کیونکہ «إن الله حرم على الأرض أن تأكل أجساد الأنبياء» ان کے بارے میں وارد ہے، اللہ نے زمین پر حرام قرار دے دیا ہے کہ وہ انبیاء (علیہم السلام) کے اجسام کو کھائے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ابن آدم کے سارے جسم کو مٹی کھا جائے گی مگر دم کی جڑ کا آخری حصہ بچ رہے گا۔ اسی سے پیدائش کی ابتدا ہوتی ہے اور اسی سے دوبارہ جسم مرکب ہوں گے۔ “","f2":"صحیح احادیث کے مطابق انبیا ء ورسل علیہ السلام کے جسم مٹی کے کھائے جانے سے محفوظ رہتے ہیں۔"}],[4744,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب اللہ نے جنت کو پیدا کیا تو جبرائیل سے فرمایا: جاؤ اور اسے دیکھو، وہ گئے اور اسے دیکھا، پھر واپس آئے، اور کہنے لگے: اے میرے رب! تیری عزت کی قسم، اس کے متعلق جو کوئی بھی سنے گا وہ اس میں ضرور داخل ہو گا، پھر (اللہ نے) اسے مکروہات (ناپسندیدہ) (چیزوں) سے گھیر دیا، پھر فرمایا: اے جبرائیل! جاؤ اور اسے دیکھو، وہ گئے اور اسے دیکھا، پھر لوٹ کر آئے تو بولے: اے میرے رب! تیری عزت کی قسم! مجھے ڈر ہے کہ اس میں کوئی داخل نہ ہو سکے گا، جب اللہ نے جہنم کو پیدا کیا تو فرمایا: اے جبرائیل! جاؤ اور اسے دیکھو، وہ گئے اور اسے دیکھا، پھر واپس آئے اور کہنے لگے: اے میرے رب! تیری عزت کی قسم! جو اس کے متعلق سنے گا اس میں داخل نہ ہو گا، تو اللہ نے اسے مرغوب اور پسندیدہ چیزوں سے گھیر دیا، پھر فرمایا: جبرائیل! جاؤ اور اسے دیکھو، وہ گئے، جہنم کو دیکھا پھر واپس آئے اور عرض کیا: اے میرے رب! تیری عزت کی قسم! مجھے ڈر ہے کہ کوئی بھی ایسا نہیں بچے گا جو اس میں داخل نہ ہو ۱؎\"۔\n§وضاحت\n۱؎ : یہ باب معتزلہ وغیرہ گمراہ فرقوں کے رد و ابطال میں ہے، جو یہ عقیدہ رکھتے ہیں کہ جنت و جہنم ابھی پیدا نہیں ہوئے ہیں جب کہ اہل حدیث و سنت کا یہ عقیدہ ہے کہ دونوں پیدا کی جا چکی ہیں۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب اللہ عزوجل نے جنت کو پیدا کیا تو جبرائیل امین سے کہا: جاؤ اور اسے دیکھو۔ چنانچہ وہ گئے اور اسے دیکھا ‘ پھر آئے تو کہا: اے میرے رب! تیری عزت کی قسم! اس کے متعلق جو کوئی بھی سنے گا اس میں داخل ہونا چاہے گا۔ پھر اللہ نے اس کو مکروہات کے گھیرے میں دے دیا۔ “ (اس میں آنے والوں کو جو عمل کرنے ہوں گے اور جن شرعی پابندیوں کو قبول کرنا ہو گا ‘ عمومی طور پر ان کی طرف طبیعت مائل نہیں ہوتی یا حق کی راہ پر جمے رہنے کی وجہ سے تکلیفیں اٹھانی ہوں گی۔) بھر فرمایا: جبرائیل! جاؤ اور اسے دیکھ کر آؤ۔ پس وہ گئے اور اس کو دیکھا۔ پھر آئے اور کہا: اے میرے رب! تیری عزت کی قسم! مجھے اندیشہ ہے کہ اس میں کوئی داخل نہیں ہو سکے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” پھر جب دوزخ کو پیدا کیا تو جبرائیل سے کہا: جاؤ اور دوزخ کو دیکھ کر آؤ۔ وہ گئے اور دیکھ کر آئے۔ واپس آ کر کہا: اے میرے رب! تیری عزت کی قسم! کوئی نہیں جو اس کے متعلق سنے اور پھر اس میں داخل ہو۔ پھر اللہ تعالیٰ نے اس کو نفسانی خواہشات اور مرغوبات کے گھیرے میں دے دیا۔ پھر فرمایا: اے جبرائیل! جاؤ اور اسے دیکھ کر آؤ۔ وہ گئے اور اسے دیکھا۔ پھر آئے اور کہا: اے میرے رب! تیری عزت اور تیرے جلال کی قسم! مجھے اندیشہ ہے کہ اس میں داخل ہونے سے کوئی بھی نہیں بچ سکے گا۔ “","f2":"جنت اور اس کی نعمتیں،دوزخ اوراس کا عذاب فی لواقع پیدا کیے جاچکے ہیں۔\n2:جنت کا داخلہ شرعی پابندیوں پر عمل کرنے سے ہی ممکن ہے اور ان کے بالمقابل نفسانی خواہشات کی پیروی اور شرعی پابندیوں سے آزادی جہنم میں جانے کا باعث ہیں لہذاضروری ہے کہ انسان نفسانی خواہشات کی پیروی سے دور رہے۔"}],[4745,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے سامنے (قیامت کے دن) ایک حوض ہو گا، جس کے دونوں کناروں کے درمیان اتنا فاصلہ ہے جتنا «جرباء» اور «اذرح» ۱؎ کے درمیان ہے ۲؎\"۔\n§وضاحت\n۱؎ : «جرباء» اور «اذرح» نام ہیں شام میں دو گاؤں کے ان کے درمیان تین دن کی مسافت کا فاصلہ ہے۔ ۲؎ : حوض کے حدود کے بارے میں مختلف بیانات وارد ہیں، ان سے تحدید مقصود نہیں بلکہ مسافت کا طول مراد ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ تمہارے آگے (محشر میں) ایک حوض ہے۔ اس کے کنارے اس قدر لمبے ہیں جیسے جرباء اور اذرح کے مابین فاصلہ ہے۔ (یہ علاقہ شام کے دو مقام ہیں ان کے درمیان پرانے زمانے میں تین راتوں کے سفر کا فاصلہ تھا۔)"}],[4746,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، ہم نے ایک جگہ پڑاؤ کیا تو آپ نے فرمایا: \"تم لوگ ان لوگوں کے ایک لاکھ حصوں میں کا ایک حصہ بھی نہیں ہو جو لوگ حشر میں حوض کوثر پر آئیں گے\"۔ راوی (ابوحمزہ) کہتے ہیں: میں نے زید بن ارقم رضی اللہ عنہ سے کہا: اس دن آپ لوگ کتنے تھے؟ کہا: سات سویا آٹھ سو۔","صحیح",{"u2":"سیدنا زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ ہم نے ایک منزل پر پڑاؤ کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تم لوگ میرے پاس حوض پر آنے والے لوگوں کا لاکھواں حصہ بھی نہیں ہو۔ ابو حمزہ کہتے ہیں ‘ میں نے پوچھا: اس دن آپ لوگوں کی تعداد کیا تھی؟ کہا: سات، آٹھ سو۔","f2":"رسول صلی اللہ علیہ وسلم کی امت گنتی میں سب امتوں سے بڑھ کر ہے اور اہل ایمان وتوحید ہی اس حوض کے پانی سے مستفید ہوں گے یعنی وہ خوش بخت عظما ءاور اچھے نصیبے والے لوگ جو شرک وبدعات سے محفوظ رہے۔"}],[4747,"مختار بن فلفل کہتے ہیں کہ میں نے انس بن مالک رضی اللہ عنہ کو کہتے سنا: (ایک بار) رسول اللہ صلی اللہ علیہ وسلم پر ہلکی اونگھ طاری ہوئی، پھر آپ صلی اللہ علیہ وسلم نے مسکراتے ہوئے سر اٹھایا، تو یا تو آپ نے لوگوں سے کہا، یا لوگوں نے آپ سے کہا: اللہ کے رسول! آپ کو ہنسی کیوں آئی؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ابھی میرے اوپر ایک سورت نازل ہوئی\" پھر آپ صلی اللہ علیہ وسلم نے پڑھا: «بسم الله الرحمن الرحيم إنا أعطيناك الكوثر» یہاں تک کہ سورت ختم کر لی، جب آپ صلی اللہ علیہ وسلم اسے پڑھ چکے تو آپ نے فرمایا: \"کیا تم جانتے ہو کوثر کیا ہے؟\" لوگوں نے کہا: اللہ اور اس کے رسول زیادہ جانتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ جنت کی ایک نہر ہے جس کا وعدہ مجھ سے میرے رب نے کیا ہے اور اس پر بڑا خیر ہے، اس پر ایک حوض ہے جس پر قیامت کے دن میری امت (پینے) آئے گی، اس کے برتن ستاروں کی تعداد میں ہوں گے\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم کو اونگھ آ گئی۔ پھر آپ صلی اللہ علیہ وسلم نے مسکراتے ہوئے اپنا سر اٹھایا۔ آپ صلی اللہ علیہ وسلم نے صحابہ سے کہا ‘ یا صحابہ نے آپ صلی اللہ علیہ وسلم سے پوچھا: اے اللہ کے رسول! آپ کیوں مسکرائے ہیں؟ فرمایا ” مجھ پر ابھی ابھی ایک سورت نازل ہوئی ہے۔ “ تو آپ صلی اللہ علیہ وسلم نے پڑھا «إنا أعطيناك الكوثر» آخر تک۔ جب آپ صلی اللہ علیہ وسلم نے اسے پڑھ لیا تو فرمایا ” کیا جانتے ہو کوثر کیا ہے؟ “ صحابہ نے کہا: اللہ اور اس کا رسول بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ ایک نہر ہے جو میرے رب عزوجل نے مجھے جنت میں دینے کا وعدہ فرمایا ہے اور اس پر خیر کثیر ہو گی ‘ اس پر ایک حوض ہو گا جس پر قیامت کے روز میری امت کے لوگ آئیں گے ‘ اس کے پینے کے برتن (پیالے) ستاروں کی تعداد میں ہوں گے۔ “","f2":"میدان کا حشر کا حوض،نہر کوثر کا ایک حصہ ہو گا۔\n2:اس حدیث میں دلیل (بسم الله الرحمن الرحيم)ہر سورت کا جزواور اس کی آیت ہوتی ہے مگر دوسرا فریق دوسرے دلائل سے اس کو مرجوح کہتا ہے ایک تیسرا مسلک یہ ہے کہ بسم اللہ صرف سورۃفاتحہ کی آیت ہے۔ دوسری سورتوں میں اس کو تبرک اور فصل کے طور پر لکھا جاتا ہے اس کی تائید اس حدیث سے ہوتی ہے جس میں اسے سورۃ فاتحہ کی ایک آیت قرار دیا گیاہے۔"}],[4748,"انس بن مالک رضی اللہ عنہ کہتے ہیں جب اللہ کے نبی اکرم صلی اللہ علیہ وسلم کو معراج میں جنت میں لے جایا گیا تو آپ کے سامنے ایک نہر لائی گئی، جس کے دونوں کنارے «مجیّب» یا کہا «مجوّف» (خول دار) یاقوت کے تھے، آپ صلی اللہ علیہ وسلم کے ساتھ جو فرشتہ تھا اس نے اپنا ہاتھ مارا اور اندر سے مشک نکالی، تو محمد صلی اللہ علیہ وسلم نے اپنے ساتھ والے فرشتے سے پوچھا یہ کیا ہے؟ اس نے کہا: یہی کوثر ہے جسے اللہ تعالی نے آپ کو عطا کیا ہے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ جب اللہ کے نبی صلی اللہ علیہ وسلم کو معراج کے موقع پر جنت میں لے جایا گیا تو آپ صلی اللہ علیہ وسلم کو ایک نہر دکھلائی گئی جس کے کنارے ایسے یاقوت کے تھے کہ جو خول دار تھے۔ تو وہ فرشتہ جو آپ صلی اللہ علیہ وسلم کے ساتھ تھا اس نے (اس کی تہہ میں) ہاتھ مارا اور کستوری نکالی۔ تو نبی کریم صلی اللہ علیہ وسلم نے اس فرشتے سے پوچھا ” یہ کیا ہے؟ “ اس نے کہا: یہ وہ کوثر ہے جو اللہ عزوجل نے آپ کو دی ہے۔"}],[4749,"عبدالسلام بن ابی حازم ابوطالوت بیان کرتے ہیں کہ میں نے ابوبرزہ رضی اللہ عنہ کو دیکھا وہ عبیداللہ بن زیاد کے ہاں گئے، پھر مجھ سے فلاں شخص نے بیان کیا جو ان کی جماعت میں شریک تھا، (مسلم نے اس کا نام ذکر کیا ہے) جب انہیں عبیداللہ نے دیکھا تو بولا: دیکھو تمہارا یہ محمدی موٹا ٹھگنا ہے، تو شیخ (ابوبرزہ) اس کے اس طعنہ اور توہین کو سمجھ گئے اور بولے: مجھے یہ گمان نہ تھا کہ میں ایسے لوگوں میں باقی رہ جاؤں گا جو محمد صلی اللہ علیہ وسلم کی صحبت کا مجھے طعنہ دیں گے، تو عبیداللہ نے ان سے کہا: محمد صلی اللہ علیہ وسلم کی صحبت تو آپ کے لیے فخر کی بات ہے، نہ کہ عیب کی، پھر کہنے لگا: میں نے آپ کو اس لیے بلایا ہے کہ میں آپ سے حوض کوثر کے بارے میں معلوم کروں، کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے متعلق کچھ ذکر فرماتے سنا ہے؟ تو ابوبرزہ رضی اللہ عنہ نے کہا: ہاں ایک بار نہیں، دو بار نہیں، تین بار نہیں، چار بار نہیں، پانچ بار نہیں (یعنی بہت بار سنا ہے) تو جو شخص اسے جھٹلائے اللہ اسے اس حوض میں سے نہ پلائے، پھر غصے میں وہ نکل کر چلے گئے۔","صحیح",{"u2":"مسلم بن ابراہیم نے بیان کیا کہ ہمیں عبداالسلام بن ابوحازم ابو طالوت نے بیان کیا اور کہا کہ میں نے ابوبرزہ رضی اللہ عنہ کو دیکھا کہ وہ (یزید بن معاویہ کی جانب سے کوفہ کے امیر) عبیداللہ بن زیاد کے پاس گئے۔ عبداالسلام نے کہا: مجھے ایک شخص نے بیان کیا جو اس مجلس میں شریک تھا۔ (ابوداود کہتے ہیں) مسلم بن ابراہیم نے اس کا نام بھی لیا تھا۔ عبیداللہ نے جب ابوبرزہ رضی اللہ عنہ کو دیکھا تو بولا: اپنے اس موٹے ٹھگنے محمدی کو دیکھو۔ شیخ اس کی بات سمجھ گئے (کہ اس نے طعنہ دیا ہے) تو انہوں نے کہا: مجھے یہ امید نہیں تھی کہ میں اس قوم میں باقی رہوں گا جو مجھے سیدنا محمد صلی اللہ علیہ وسلم کی صحابیت پر طعنہ دے گی۔ تو عبیداللہ نے ان سے کہا: بلاشبہ محمد صلی اللہ علیہ وسلم کی صحبت تمہارے لیے باعث عزت ہے۔ اس میں کوئی عیب کی بات نہیں ہے۔ پھر کہا: میں نے آپ کو اس لیے بلا بھیجا ہے کہ آپ سے حوض کے متعلق دریافت کروں۔ کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو اس بارے میں کچھ کہتے سنا ہے؟ تو سیدنا ابوبرزہ رضی اللہ عنہ نے کہا: ہاں۔ کوئی ایک، دو، تین، چار یا پانچ بار نہیں (بلکہ بارہا سنا ہے) تو جو اس کو جھٹلائے اللہ اس کو اس سے نہ پلوائے ‘ پھر غصے سے باہر نکل آئے۔","f2":"میدان حشر میں حوض کو ثر کا وجود اور متواتر احادیث سے ثابت ہے اس کا انکار کفر ہے۔"}],[4750,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان سے جب قبر میں سوال ہوتا ہے اور وہ گواہی دیتا ہے کہ اللہ کے سوا کوئی معبود برحق نہیں اور محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں\"۔ تو یہی مراد ہے اللہ کے قول «يثبت الله الذين آمنوا بالقول الثابت» \"اللہ ایمان والوں کو پکی بات کے ساتھ مضبوط کرتا ہے\" (سورۃ ابراہیم: ۲۷) سے۔","صحیح",{"u2":"سیدنا براء بن عازب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مسلمان سے جب قبر میں سوال کیا جاتا ہے تو وہ شہادت دیتا ہے کہ ایک اللہ کے سوا کوئی معبود نہیں اور سیدنا محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ اور یہی مصداق ہے اللہ عزوجل کے اس فرمان کا «يثبت الله الذين آمنوا بالقول الثابت» ” اللہ تعالیٰ اہل ایمان کو پختہ بات کے ساتھ دنیا میں ثابت قدم رکھتا ہے اور آخرت میں بھی ثابت قدم رکھے گا۔ “","f2":"قبر کے سوال وجواب کا مسئلہ قرآن مجیدکی مذکورہ بالا آیت میں بیان ہواہے اور متعددصحیح احادیث میں وارد ہے اس لئے اس کا انکار کفر ہے۔"}],[4751,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ اللہ کے نبی اکرم صلی اللہ علیہ وسلم بنی نجار کے کھجور کے ایک باغ میں داخل ہوئے، تو ایک آواز سنی، آپ صلی اللہ علیہ وسلم گھبرا اٹھے، فرمایا: \"یہ قبریں کس کی ہیں؟\" لوگوں نے عرض کیا: زمانہ جاہلیت میں مرنے والوں کی ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ جہنم کے عذاب سے اور دجال کے فتنے سے اللہ کی پناہ مانگو\" لوگوں نے عرض کیا: ایسا کیوں؟ اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا: \"مومن جب قبر میں رکھا جاتا ہے تو اس کے پاس ایک فرشتہ آتا ہے، اور اس سے کہتا ہے: تم کس کی عبادت کرتے تھے؟ تو اگر اللہ اسے ہدایت دیئے ہوتا ہے تو وہ کہتا ہے: میں اللہ کی عبادت کرتا تھا؟ پھر اس سے کہا جاتا ہے، تم اس شخص کے بارے میں کیا کہتے تھے؟ ۱؎ تو وہ کہتا ہے: وہ اللہ کے بندے اور اس کے رسول ہیں، پھر اس کے علاوہ اور کچھ نہیں پوچھا جاتا، پھر اسے ایک گھر کی طرف لے جایا جاتا ہے، جو اس کے لیے جہنم میں تھا اور اس سے کہا جاتا ہے: یہ تمہارا گھر ہے جو تمہارے لیے جہنم میں تھا، لیکن اللہ نے تمہیں اس سے بچا لیا، تم پر رحم کیا اور اس کے بدلے میں تمہیں جنت میں ایک گھر دیا، تو وہ کہتا ہے: مجھے چھوڑ دو کہ میں جا کر اپنے گھر والوں کو بشارت دے دوں، لیکن اس سے کہا جاتا ہے، ٹھہرا رہ، اور جب کافر قبر میں رکھا جاتا ہے، تو اس کے پاس ایک فرشتہ آتا ہے اور اس سے ڈانٹ کر کہتا ہے: تو کس کی عبادت کرتا تھا؟ تو وہ کہتا ہے: میں نہیں جانتا، تو اس سے کہا جاتا ہے: نہ تو نے جانا اور نہ کتاب پڑھی (یعنی قرآن)، پھر اس سے کہا جاتا ہے: تو اس شخص کے بارے میں کیا کہتا تھا؟ تو وہ کہتا ہے: وہی کہتا تھا جو لوگ کہتے تھے، تو وہ اسے لوہے کے ایک گرز سے اس کے دونوں کانوں کے درمیان مارتا ہے، تو وہ اس طرح چلاتا ہے کہ اس کی آواز آدمی اور جن کے علاوہ ساری مخلوق سنتی ہے\"۔\n§وضاحت\n۱؎ : بعض لوگوں نے «في هذا الرجل» سے یہ خیال کیا ہے کہ میت کو نبی اکرم صلی اللہ علیہ وسلم کی شبیہ دکھائی جاتی ہے، یا پردہ ہٹا دیا جاتا ہے، مگر یہ محض خیال ہے، اس کی کوئی دلیل قرآن وسنت میں وارد نہیں ، مردہ نور ایمانی سے ان سوالوں کے جواب دے گا نا کہ دیکھنے اور جاننے کی بنیاد پر، ابوجہل نے آپ صلی اللہ علیہ وسلم کو دیکھا تھا منکر نکیر کے سوال پر وہ آپ کو نہیں پہچان سکتا ،اور آج کا مومن موحد باوجود یہ کہ اس نے آپ کو دیکھا نہیں مگر جواب درست دے گا کیونکہ اس کا نور ایمان اس کو جواب سمجھائے گا، اگرچہ لفظ «هذا» محسوس قریب کے لئے آتا ہے مگر «ذلك» جو بعید کے لئے وضع کیا گیا ہے، اس کے معنی میں بھی استعمال ہوتا ہے وبالعکس، «وقد ذكره البخاري عن معمر بن المثنى عن أبي عبيدة» پھر جواب میں «هو» کا لفظ موجود ہے جو ضمیر غائب ہے جو اس کے حقیقی معنی مراد لینے سے مانع ہے، «فافهم» ۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم بنو نجار کے ایک نخلستان میں داخل ہوئے۔ آپ صلی اللہ علیہ وسلم نے ایک آواز سنی اور گھبرا گئے اور پوچھا ” یہ قبروں والے کون ہیں؟ “ انہوں نے کہا: اے اللہ کے رسول! کچھ لوگ تھے جو دور جاہلیت میں مر گئے تھے، تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اللہ سے آگ کے عذاب اور دجال کے فتنے سے امان مانگو۔ “ انہوں نے کہا: اور یہ کیسے ہے اے اللہ کے رسول؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ مومن آدمی کو جب قبر میں رکھا جاتا ہے تو اس کے پاس فرشتہ آتا ہے ‘ وہ اس سے پوچھتا ہے تو کس کی عبادت کرتا تھا؟ تو اگر اللہ تعالیٰ اسے توفیق دے ‘ تو وہ کہتا ہے: میں اللہ کی عبادت کیا کرتا تھا۔ پھر اس سے پوچھا جاتا ہے ‘ تو اس آدمی کے بارے میں کیا کہا کرتا تھا؟ تو وہ کہتا ہے: یہ اللہ کے بندے اور اس کے رسول ہیں۔ تو اس سے اس کے علاوہ کچھ اور نہیں پوچھا جاتا۔ چنانچہ اسے ایک گھر کی طرف لے جایا جاتا ہے جو اس کے لیے دوزخ میں مقرر تھا اور اس سے کہا جاتا ہے: (دیکھ) دوزخ میں یہ تیرا گھر تھا لیکن اللہ نے تجھ کو بچا لیا ہے اور تجھ پر رحم کیا ہے اور اس کے بدلے تجھے جنت میں گھر دے دیا ہے۔ تو وہ کہتا ہے: مجھے چھوڑو کہ جاؤں اور اپنے گھر والوں کو خوشخبری دے آؤں ‘ تو اسے کہا جاتا ہے آرام کرو۔ اور کافر آدمی کو جب قبر میں رکھا جاتا ہے تو اس کے پاس فرشتہ آتا ہے اور اس کو جھڑکتا ہے اور پوچھتا ہے: تو کس کی عبادت کیا کرتا تھا؟ وہ کہتا ہے مجھے نہیں معلوم۔ پھر اس سے کہا جاتا ہے: نہ تو نے جانا اور نہ پڑھا۔ پھر اس سے پوچھا جاتا ہے: تو اس آدمی کے بارے میں کیا کہا کرتا تھا؟ وہ جواب دیتا ہے: میں وہی کہتا تھا جو لوگ کہتے تھ۔ تو وہ فرشتہ لوہے کے ایک بھاری بھر کم ہتھوڑے (گرز) کے ساتھ اس کے کانوں کے درمیان مارتا ہے تو وہ اس سے اس قدر چیختا چلاتا ہے کہ جنوں اور انسانوں کے علاوہ ساری مخلوق اس کی آواز سنتی ہے۔ “"}],[4752,"عبدالوہاب سے اسی جیسی سند سے اس طرح کی حدیث مروی ہے اس میں ہے: \"جب بندہ قبر میں رکھ دیا جاتا ہے، اور اس کے رشتہ دار واپس لوٹتے ہیں تو وہ ان کے جوتوں کی چاپ سنتا ہے، اتنے میں اس کے پاس دو فرشتے آتے ہیں، اور اس سے کہتے ہیں پھر انہوں نے پہلی حدیث کے قریب قریب بیان کیا، اور اس میں اس طرح ہے: رہے کافر اور منافق تو وہ دونوں اس سے کہتے ہیں\" راوی نے \"منافق\"کا اضافہ کیا ہے اور اس میں ہے: \"اسے ہر وہ شخص سنتا ہے جو اس کے قریب ہوتا ہے، سوائے آدمی اور جن کے ۱؎\"۔\n§وضاحت\n۱؎ : مردہ واپس لوٹنے والوں کی جوتیوں کی آواز سنتا ہے کیونکہ وہ نیچے زمین میں ہے اور چلنے والے اوپر چل رہے ہوتے ہیں، ان کی بات چیت نہیں سنتا کیونکہ قبر پر آواز جانے کا کوئی ذریعہ نہیں، اس سے سماع موتی پر استدلال کرنا محض غلط ہے، کیونکہ لوٹنے والوں کی بات سننے کا ذکر اس حدیث میں نہیں ہے، لہٰذا جوتیوں کی دھمک سننے سے بات چیت کے سننے کا اثبات غلط ہے، نیز حدیث میں اس خاص موقع پر مردوں کے سننے کی یہ بات آئی ہے، جیسے غزوہ بدر میں قریش کے مقتولین جو بدر کے کنویں میں ڈال دئیے گئے تھے، اور رسول اکرم صلی اللہ علیہ وسلم نے ان کو مخاطب کیا تھا یہ بھی مخصوص صورت حال تھی، اس طرح کے واقعات سے مردوں کے عمومی طور پر سننے پر استدلال صحیح نہیں ہے، دلائل کی روشنی میں صحیح بات یہی ہے کہ مردے سنتے نہیں ہیں، (ملاحظہ ہو علامہ آلوسی کی کتاب: ’’ کیا مردے سنتے ہیں ؟ ‘‘ نیز مولانا عبداللہ بھاولپوری کا رسالہ ’’ سماع موتی ‘‘ )۔","صحیح",{"u2":"محمد بن سیلمان نے عبدالوہاب سے اسی اسناد سے اس حدیث کی مانند روایت کیا، کہا کہ ” جب بندے کو اس کی قبر میں رکھا جاتا ہے اور اس کے ساتھی واپس آنے لگتے ہیں تو وہ ان کے قدموں کی آہٹ سنتا ہے اور اس کے پاس دو فرشتے آتے ہیں اور اس سے کہتے ہیں “ اور پہلی حدیث کے قریب قریب بیان کیا۔ اس میں کہا: ” کافر اور منافق کہتے ہیں “ اس میں ” منافق “ کا لفظ زیادہ ہے۔ نیز یہ کہا: ” اس کی چیخ کو جنوں اور انسانوں کے علاوہ قریب قریب کی سب مخلوق سنتی ہے۔ “","f2":"مذکورہ بالا احادیث میں کوئی تعارض نہیں ہے بظاہر جواختلاف نظرآتا ہے مختلف افراد کے احوال کی بنا پر ہے صالح بندے کے پاس ایک ہی فرشتہ آتاہے اور نرمی کا معاملہ کرتاہے اور دوسرے کے پاس دوآتے ہیں اور یہ فرشتے کبھی لوگوں کے جانے سے پہلے آجاتے ہیں اور دونوں ہی سوال کرتے ہیں تا کہ قبر کے سوالات اور وہاں کے امتحان کی ہیبت اور شدت میں سختی کا اظہارہو۔"}],[4753,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ انصار کے ایک شخص کے جنازے میں نکلے، ہم قبر کے پاس پہنچے، وہ ابھی تک تیار نہ تھی، تو رسول اللہ صلی اللہ علیہ وسلم بیٹھ گئے اور ہم بھی آپ کے اردگرد بیٹھ گئے گویا ہمارے سروں پر چڑیاں بیٹھی ہیں، آپ صلی اللہ علیہ وسلم کے ہاتھ میں ایک لکڑی تھی، جس سے آپ زمین کرید رہے تھے، پھر آپ صلی اللہ علیہ وسلم نے سر اٹھایا اور فرمایا: \"قبر کے عذاب سے اللہ کی پناہ طلب کرو\" اسے دو بار یا تین بار فرمایا، یہاں جریر کی روایت میں اتنا اضافہ ہے: اور فرمایا: \"اور وہ ان کے جوتوں کی چاپ سن رہا ہوتا ہے جب وہ پیٹھ پھیر کر لوٹتے ہیں، اسی وقت اس سے پوچھا جاتا ہے، اے جی! تمہارا رب کون ہے؟ تمہارا دین کیا ہے؟ اور تمہارا نبی کون ہے؟\" ہناد کی روایت کے الفاظ ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر اس کے پاس دو فرشتے آتے ہیں، اسے بٹھاتے ہیں اور اس سے پوچھتے ہیں: تمہارا رب (معبود) کون ہے؟ تو وہ کہتا ہے، میرا رب (معبود)اللہ ہے، پھر وہ دونوں اس سے پوچھتے ہیں: تمہارا دین کیا ہے؟ وہ کہتا ہے: میرا دین اسلام ہے، پھر پوچھتے ہیں: یہ کون ہے جو تم میں بھیجا گیا تھا؟ وہ کہتا ہے: وہ اللہ کے رسول صلی اللہ علیہ وسلم ہیں، پھر وہ دونوں اس سے کہتے ہیں: تمہیں یہ کہاں سے معلوم ہوا؟ وہ کہتا ہے: میں نے اللہ کی کتاب پڑھی اور اس پر ایمان لایا اور اس کو سچ سمجھا\" جریر کی روایت میں یہاں پر یہ اضافہ ہے: \"اللہ تعالی کے قول«يثبت الله الذين آمنوا» سے یہی مراد ہے\" (پھر دونوں کی روایتوں کے الفاظ ایک جیسے ہیں) آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر ایک پکارنے والا آسمان سے پکارتا ہے: میرے بندے نے سچ کہا لہٰذا تم اس کے لیے جنت کا بچھونا بچھا دو، اور اس کے لیے جنت کی طرف کا ایک دروازہ کھول دو، اور اسے جنت کا لباس پہنا دو\" آپ صلی اللہ علیہ وسلم فرماتے ہیں: \"پھر جنت کی ہوا اور اس کی خوشبو آنے لگتی ہے، اور تا حد نگاہ اس کے لیے قبر کشادہ کر دی جاتی ہے\"۔ اور رہا کافر تو آپ صلی اللہ علیہ وسلم نے اس کی موت کا ذکر کیا اور فرمایا:\"اس کی روح اس کے جسم میں لوٹا دی جاتی ہے، اس کے پاس دو فرشتے آتے ہیں، اسے اٹھاتے ہیں اور پوچھتے ہیں: تمہارا رب کون ہے؟ وہ کہتا ہے: ہا ہا! مجھے نہیں معلوم، وہ دونوں اس سے پوچھتے ہیں: یہ آدمی کون ہے جو تم میں بھیجا گیا تھا؟ وہ کہتا ہے: ہا ہا! مجھے نہیں معلوم، پھر وہ دونوں اس سے پوچھتے ہیں: تمہارا دین کیا ہے؟ وہ کہتا ہے: ہا ہا! مجھے نہیں معلوم، تو پکارنے والا آسمان سے پکارتا ہے: اس نے جھوٹ کہا، اس کے لیے جہنم کا بچھونا بچھا دو اور جہنم کا لباس پہنا دو، اور اس کے لیے جہنم کی طرف دروازہ کھول دو، تو اس کی تپش اور اس کی زہریلی ہوا (لو) آنے لگتی ہے اور اس کی قبر تنگ کر دی جاتی ہے یہاں تک کہ اس کی پسلیاں ادھر سے ادھر ہو جاتی ہیں\"جریر کی روایت میں یہ اضافہ ہے: \"پھر اس پر ایک اندھا گونگا (فرشتہ) مقرر کر دیا جاتا ہے، اس کے ساتھ لوہے کا ایک گرز ہوتا ہے اگر وہ اسے کسی پہاڑ پر بھی مارے تو وہ بھی خاک ہو جائے، چنانچہ وہ اسے اس کی ایک ضرب لگاتا ہے جس کو مشرق و مغرب کے درمیان کی ساری مخلوق سوائے آدمی و جن کے سنتی ہے اور وہ مٹی ہو جاتا ہے\" آپ صلی اللہ علیہ وسلم فرماتے ہیں: \"پھر اس میں روح لوٹا دی جاتی ہے\"۔","صحیح",{"u2":"سیدنا براء بن عازب رضی اللہ عنہ سے روایت ہے انہوں نے کہا کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک انصاری کے جنازے میں گئے۔ ہم قبر کے پاس پہنچے تو ابھی لحد تیار نہیں ہوئی تھی ‘ تو رسول اللہ صلی اللہ علیہ وسلم بیٹھ گئے اور ہم بھی آپ صلی اللہ علیہ وسلم کے اردگرد بیٹھ گئے۔ گویا کہ ہمارے سروں پر پرندے ہوں (نہایت پر سکون اور خاموشی سے بیٹھے تھے۔) آپ صلی اللہ علیہ وسلم کے ہاتھ میں چھڑی تھی ‘ آپ صلی اللہ علیہ وسلم اس سے زمین کرید رہے تھے۔ آپ صلی اللہ علیہ وسلم نے اپنا سر اٹھایا اور فرمایا ” اللہ سے قبر کے عذاب کی امان مانگو۔ “ آپ صلی اللہ علیہ وسلم نے یہ دو یا تین بار فرمایا۔ جریر کی روایت میں یہاں یہ اضافہ ہے ” جب لوگ واپس جاتے ہیں تو میت ان کے قدموں کی آہٹ سنتی ہے ‘ جبکہ اس سے یہ پوچھا جا رہا ہوتا ہے: اے فلاں! تیرا رب کون ہے؟ تیرا دین کیا ہے؟ اور تیرا نبی کون ہے؟ ہناد نے کہا: فرمایا ” اس کے پاس دو فرشتے آتے ہیں اور اسے بٹھاتے ہیں اور اسے کہتے ہیں: تیرا رب کون ہے؟ تو وہ کہتا ہے: میرا رب اللہ ہے۔ پھر وہ پوچھتے ہیں تیرا دین کیا ہے؟ تو وہ کہتا ہے: میرا دین اسلام ہے۔ پھر وہ پوچھتے ہیں: یہ آدمی کون ہے جو تم میں مبعوث کیا گیا تھا؟ تو وہ کہتا ہے: وہ اللہ کے رسول ہیں۔ پھر وہ کہتے ہیں: تجھے کیسے علم ہوا؟ وہ کہتا ہے: میں نے اللہ کی کتاب پڑھی ‘ میں اس پر ایمان لایا اور اس کی تصدیق کی۔ “ جریر کی روایت میں مزید ہے ” یہی (سوال جواب ہی) مصداق ہے اللہ عزوجل کے اس فرمان کا «يثبت الله الذين آمنوا بالقول الثابت في الحياة الدنيا وفي الآخرة» پھر وہ دونوں روایت کرنے میں متفق ہیں۔ فرمایا ” پھر آسمان سے منادی کرنے والا اعلان کرتا ہے: تحقیق میرے بندے نے سچ کہا ہے ‘ اسے جنت کا بستر بچھا دو ‘ اور اس کو جنت کا لباس پہنا دو ‘ اور اس کے لیے جنت کی طرف سے دروازہ کھول دو۔ “ فرمایا ” جنت کی طرف سے وہاں کی ہوائیں ‘ راحتیں اور خوشبو آنے لگتی ہیں اور اس کی قبر کو انتہائے نظر تک وسیع کر دیا جاتا ہے۔ ” پھر کافر اور اس کی موت کا ذکر کیا اور فرمایا: اس کی روح اس کے جسم میں لوٹائی جاتی ہے اور وہ اس کے پاس آتے ہیں اور اسے بٹھاتے ہیں اور اس سے پوچھتے ہیں: تیرا رب کون ہے؟ تو وہ کہتا ہے: ہاہ! ہاہ! مجھے خبر نہیں۔ پھر وہ اس سے پوچھتے ہیں: تیرا دین کیا ہے؟ تو وہ کہتا ہے: ہاہ! ہاہ! مجھے خبر نہیں۔ پھر وہ اس سے پوچھتے ہیں: یہ آدمی کون ہے جو تم میں مبعوث کیا گیا تھا؟ تو وہ کہتا ہے: ہاہ! ہاہ! مجھے خبر نہیں۔ تو منادی آسمان سے ندا دیتا ہے کہ اس نے جھوٹ کہا ‘ اسے آگ کا بستر بچھا دو ‘ اسے آگ کا لباس پہنا دو اور اس کے لیے دوزخ کی طرف سے دروازہ کھول دو۔ فرمایا کہ پھر اس جہنم کی طرف سے اس کی تپش اور سخت گرم ہوا آنے لگتی ہے اور اس پر قبر کو تنگ کر دیا جاتا ہے حتیٰ کہ اس کی پسلیاں ایک دوسری میں گھس جاتی ہیں۔ “ جریر کی روایت میں مزید ہے ” پھر اس پر ایک اندھا گونگا فرشتہ مقرر کر دیا جاتا ہے ‘ جس کے پاس بھاری گرز ہوتا ہے۔ اگر اسے پہاڑ پر مار جائے تو وہ (پہاڑ) مٹی مٹی ہو جائے۔ پھر وہ اسے اس کے ساتھ ایسی چوٹ مارتا ہے جس کی آواز جنوں اور انسانوں کے علاقہ مشرق و مغرب کے درمیان ساری مخلوق سنتی ہے۔ اور پھر وہ مٹی (ریزہ ریزہ) ہو جاتا ہے۔ ” فرمایا: پھر اس میں روح لوٹائی جاتی ہے۔ “"}],[4754,"ابوعمر زاذان کہتے ہیں کہ میں نے براء رضی اللہ عنہ کو نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے سنا، پھر انہوں نے اسی طرح کی حدیث ذکر کی۔","صحیح",{"u2":"ابوعمر زاذان نے کہا کہ میں نے سیدنا براء بن عازب رضی اللہ عنہ سے سنا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اس کی مانند روایت کیا۔"}],[4755,"حسن بصری کہتے ہیں کہ ام المؤمنین عائشہ رضی اللہ عنہا نے جہنم کا ذکر کیا تو رونے لگیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم کیوں روتی ہو؟\"، وہ بولیں: مجھے جہنم یاد آ گئی تو رونے لگی، کیا آپ قیامت کے دن اپنے گھر والوں کو یاد کریں گے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین جگہوں پر تو وہاں کوئی کسی کو یاد نہیں کرے گا: ایک میزان کے پاس یہاں تک کہ یہ معلوم ہو جائے کہ اس کا میزان ہلکا ہے یا بھاری ہے، دوسرے کتاب کے وقت جب کہا جائے گا: آؤ پڑھو اپنی اپنی کتاب یہاں تک کہ یہ معلوم ہو جائے کہ اس کی کتاب کس میں دی جائے گی آیا دائیں ہاتھ میں یا بائیں ہاتھ میں، یا پھر پیٹھ کے پیچھے سے اور تیسرے پل صراط کے پاس جب وہ جہنم پر رکھا جائے گا\"۔ یعقوب نے «عن يونس» کے الفاظ سے روایت کی اور یہ حدیث اسی کے الفاظ میں ہے۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ انہوں نے جہنم کا ذکر کیا اور رونے لگیں ‘ تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا ” تجھے کس چیز نے رلایا ہے؟ “ کہنے لگیں: مجھے جہنم یاد آئی ہے تو رونے لگی ہوں۔ تو کیا بھلا آپ قیامت کے روز اپنے گھر والوں کو یاد رکھیں گے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تین مقامات ایسے ہیں جہاں کوئی کسی کو یاد نہیں کرے گا: ترازو کے پاس حتیٰ کہ اسے پتا چل جائے کہ اس کا تول ہلکا ہوا یا بھاری ‘ نامہ اعمال ملنے کے وقت ‘ جب کہا جائے گا «هاؤم اقرءوا كتابيه» ” آؤ میرا نامہ اعمال پڑھو۔ “ حتیٰ کہ جان لے کہ اس کا اعمال نامہ اس کے دائیں ہاتھ میں آتا ہے یا بائیں میں یا کمر کے پیچھے سے ‘ اور (تیسرا مقام) پل صراط ہے جب اسے جہنم پر عین وسط میں ٹکایا جائے گا۔ “ یعقوب نے «عن يونس» کے الفاظ سے روایت کی اور یہ حدیث اسی کے الفاظ میں ہے۔","f2":"یہ روایت سنداضعیف ہے تاہم یہ حقیقت ہے کہ محشر کے سارے ہی مراحل وہشت ناک ہیں مگر یہ مذکورہ احوال زیادہ سخت ہوں گے۔"}],[4756,"ابوعبیدہ بن جراح رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"نوح کے بعد کوئی ایسا نبی نہیں ہوا جس نے اپنی قوم کو دجال سے نہ ڈرایا ہو اور میں بھی تمہیں اس سے ڈراتا ہوں\" پھر رسول اللہ صلی اللہ علیہ وسلم نے ہمارے سامنے اس کی صفت بیان کی اور فرمایا: \"شاید اسے وہ شخص پائے جس نے مجھے دیکھا اور میری بات سنی\" لوگوں نے عرض کیا: اس دن ہمارے دل کیسے ہوں گے؟ کیا اسی طرح جیسے آج ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس سے بھی بہتر\" (کیونکہ فتنہ و فساد کے باوجود ایمان پر قائم رہنا زیادہ مشکل ہے) ۔","ضعیف",{"u2":"سیدنا ابوعبیدہ بن جراح رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے سنا ” تحقیق نوح علیہ السلام کے بعد جو بھی نبی آیا اس نے اپنی قوم کو دجال سے ڈرایا ہے اور میں بھی تمہیں اس سے ڈرا رہا ہوں۔ “ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اس کی علامات بیان فرمائیں اور کہا ” ممکن ہے کہ اسے وہ آدمی پا لے جس نے مجھے دیکھا ہے اور میری باتیں سنی ہیں۔ “ صحابہ نے کہا: اے اللہ کے رسول! ان دنوں ہمارے دل کیسے ہوں گے؟ کیا بھلا ایسے ہی ہوں گے جیسے آج ہیں؟ فرمایا ” یا اس سے بہتر۔ “"}],[4757,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم لوگوں میں کھڑے ہوئے، اللہ کی لائق شان حمد و ثنا بیان فرمائی، پھر دجال کا ذکر کیا اور فرمایا: \"میں تمہیں اس سے ڈراتا ہوں، کوئی نبی ایسا نہیں گزرا جس نے اپنی قوم کو اس سے ڈرایا نہ ہو، نوح (علیہ السلام) نے بھی اپنی قوم کو اس سے ڈرایا تھا، لیکن میں تمہیں اس کے بارے میں ایسی بات بتا رہا ہوں جو کسی نبی نے اپنی قوم کو نہیں بتائی: وہ کانا ہو گا اور اللہ کانا نہیں ہے\"۔","صحیح",{"u2":"جناب سالم اپنے والد (سیدنا عبداللہ بن عمر رضی اللہ عنہ) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کو خطبہ دینے کے لیے کھڑے ہوئے۔ آپ صلی اللہ علیہ وسلم نے اللہ کی حمد و ثنا بیان کی جو اس کے لائق ہے۔ پھر آپ صلی اللہ علیہ وسلم نے دجال کا ذکر کیا اور فرمایا ” میں تمہیں اس سے ڈرا رہا ہوں اور جو بھی نبی آیا ہے اس نے اپنی قوم کو اس سے ڈرایا ہے ‘ یقیناً نوح علیہ السلام نے بھی اپنی قوم کو اس سے ڈرایا تھا، لیکن میں تمہیں اس کے بارے میں ایسی بات کہہ رہا ہوں جو کسی نبی نے اپنی قوم کو نہیں بتائی۔ تم جان لو کہ وہ کانا ہے اور اللہ عزوجل قطعاً کانا نہیں ہے۔ “","f2":"دجال کا لفظ دجل سے اسم مبالغہ ہے اور معنی ہیں قیامت سے پہلے ایک شخص ظاہر ہو گا جو مختلف شعبدہ بازیوں سے لوگوں کے ایمان پر حملہ آور ہو گا اور اپنی الوہیت کا دعوی کرے گا۔ اس کا یہ فتنہ سب فتنوں سے بڑھ کر ہو گا۔ اس کی ظاہر علامات اور اس کے اعمال کا بیان احادیثکی سب کتب میں موجود ہے۔ آخر میں اس کا قتل سید نا حضرت عیسی علیہ السلام کے ہاتھوں سے ہو گا۔\n1: وجال کا سب سے بڑا دجل اور فتنہ مختلف شعبدے دکھا کر اپنی الوہیت کا اقرارکرانا ہو گا۔\n2: اللہ عزوجل صفت عین (آنکھ) سے وصوف ہے اور اس کی آنکھیں ہیں اور دجال کا عیب یہ بتایا گیا ہے کہ وہ داہنی آنکھ سے کانا ہو گا۔وصف باری تعالی کی بابت قرآن مجید میں ہے: اللہ کے حکم کے مطابق صبر کیجیے۔ بلا شبہ آپ ہماری آنکھوں کے سامنے ہیں اللہ عزوجل کی تمام صفات پر ہم اہل السنتہ والجماعتہ کا ایمان ہے،ہم ان کو کوئی تاویل نہیں کرتے۔ ہم نہ ان کو معطل سمجھتے ہیں نہ انکار کرتے ہیں اور نہ تشبیہ دیتے ہیں،بلکہ یہ ویسی ہی ہیں جیسی اس کی ذات والاشان کے لائق ہیں ان کی حقیقت کی ٹوہ میں لگنا اور ان کے متعلق سوال کرنا بدعت ہے۔ اس لیے کہ ہماری عقل اور ادارک اس کو پا ہی نہیں سکتے۔ ٹوہ لگانے سے محض پر یشان خیالی پیدا ہو گی۔"}],[4758,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے جماعت ۲؎ سے ایک بالشت بھی علیحدگی اختیار کی تو اس نے اسلام کا قلادہ اپنی گردن سے اتار پھینکا\"۔\n§وضاحت\n۱؎ : خوارج جمع ہے خارجی کی، یہ ایک گمراہ فرقہ ہے، یہ لوگ علی رضی اللہ عنہ کے ساتھ تھے پھر ان کے لشکر سے نکل کر فاسد عقیدے اختیار کئے اور آپ کے خلاف قتال کیا، ان کا عقیدہ ہے: کبیرہ گناہ کا مرتکب کافر ہے، یہ لوگ علی ،عثمان، معاویہ اور عائشہ رضی اللہ عنہم وغیرہم کی تکفیر کرتے ہیں، علی اور معاویہ نے ان لوگوں سے قتال کیا اور ان کے فتنہ کا سد باب کیا۔ ۲؎ : امام جماعت سے یا مسلمانوں کے اجتماعی معاملہ سے علیحدگی اختیار کی وہ گمراہی و ہلاکت کا شکار ہوا۔","صحیح",{"u2":"سیدنا ابوذر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے جماعت سے بالشت بھر بھی علیحدگی اختیار کی ‘ اس نے اسلام کی رسی کو اپنے گلے سے اتار پھینکا۔ “","f2":"جماعةسے مراد اہلالسنتہوالجماعتہ ہیں جو عقیدہ توحیداورتمسک بالسنہ کو دین کی بنیادمانتے ہیں اسی پر آپس میں متحدہ متفق ہیں۔\n2:مسلمانوں کے حاکم سے کوئی گناہ اور غلطی ہو جائے تو اس کے خلاف بغاوت کرنا جائز نہیں الا یہ کہ وہ صریح کفر کا مرتکب ہو یا جب وہ نفاذدین کے راستے سے انحراف کریں۔"}],[4759,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا کیا حال ہو گا ۱؎ جب میرے بعد حکمراں اس مال فے کو اپنے لیے مخصوص کر لیں گے\" میں نے عرض کیا: تب تو اس ذات کی قسم، جس نے آپ کو حق کے ساتھ بھیجا ہے، میں اپنی تلوار اپنے کندھے پر رکھوں گا، پھر اس سے ان کے ساتھ لڑوں گا یہاں تک کہ میں آپ سے ملاقات کروں یا آ ملوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تمہیں اس سے بہتر چیز نہ بتاؤں؟ تم صبر کرنا یہاں تک کہ تم مجھ سے آ ملو\"۔\n§وضاحت\n۱؎ : تم کیا کرو گے ؟ صبر کرو گے یا قتال۔","ضعیف",{"u2":"سیدنا ابوذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میرے بعد تمہارا کیا حال ہو گا جبکہ امام (خلیفہ) اس مال فے اور غنیمت کو ذاتی مال سمجھیں گے۔ “ (یعنی شرعی تقاضوں کے مطابق خرچ اور تقسیم نہیں کریں گے)۔ میں نے عرض کیا اس ذات کی قسم! جس نے آپ کو حق کے ساتھ (سچا پیغمبر بنا کے) بھیجا ‘ تب تو میں اپنی تلوار اپنے کندھے پر رکھ لوں گا اور اس سے ماروں گا حتیٰ کہ آپ صلی اللہ علیہ وسلم سے آ ملوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا میں تمہیں اس سے بہتر بات نہ بتا دوں؟ صبر کرنا حتیٰ کہ مجھ سے آ ملو۔"}],[4760,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عنقریب تم پر ایسے حاکم ہوں گے جن سے تم معروف (نیک اعمال) ہوتے بھی دیکھو گے اور منکر (خلاف شرع امور) بھی دیکھو گے، تو جس نے منکر کا انکار کیا، (ابوداؤد کہتے ہیں: ہشام کی روایت میں «بلسانہ» کا لفظ بھی ہے (جس نے منکر کا) اپنی زبان سے انکار کیا) تو وہ بری ہو گیا اور جس نے دل سے برا جانا وہ بھی بچ گیا، البتہ جس نے اس کام کو پسند کیا اور اس کی پیروی کی تو وہ بچ نہ سکے گا\" عرض کیا گیا: اللہ کے رسول! کیا ہم انہیں قتل نہ کر دیں؟ (سلیمان ابن داود طیالسی) کی روایت میں ہے: کیا ہم ان سے قتال نہ کریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں جب تک کہ وہ نماز پڑھتے رہیں ۱؎\"۔\n§وضاحت\n۱؎ : منکر اور خلاف شرع کام کا انکار کرنا زبان سے نفاق سے براءت دلاتا ہے، اور جو شخص دل سے برا جانتا اور اس میں شریک نہیں ہوتا وہ گناہ سے بچ جاتا ہے، لیکن جو پسند کرے اور اس میں شریک ہو تو وہ انہی جیسا ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم پر ایسے امام (امیر) مقرر ہوں گے جن کی کچھ باتیں تمہیں بھلی لگیں گی اور کچھ بری بھی جانو گے۔ تو جس نے انکار کیا، بالفاظ ہشام، اپنی زبان سے انکار کیا ‘ تو وہ بری ہوا ‘ اور جس نے دل سے انکار کیا وہ محفوظ رہا ‘ لیکن جو راضی رہا اور ان کا متبع بنا۔ “ کہا گیا: اے اللہ کے رسول! تو کیا ہم ان کو قتل نہ کریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں ‘ جب تک کہ وہ نماز پڑھتے رہیں۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا: «أفلا نقاتلهم؟» کیا ہم ان سے قتال نہ کریں؟","f2":"نماز ایک ایسا عمل ہے اس کی پابندی انسان کے لئے بڑے سے بڑے گناہ سے بھی قتل وقتال سےرکاوٹ بن جاتی ہے،سوائے اس کہ معروف حدودکا ارتکاب کرے۔\n2:اورایسے امراء جو نماز پڑھتے ہوں ان کے خلاف خروج (بغاوت) جائز نہیں۔ نماز ترکر دیں تو مسئلہ اختلافی ہے۔\n3:شرعی منکرات اور رعیت پرظلم کو آدمی قوت سے بدلنے پر قادر نہ ہو تو زبان سے یا کم از کم دل سے ان کو برا کہنا اور جاننا فرض ہے ورنہ ایمان نہیں۔\n4:ظالموں کے ظلم پر راضی رہنا اور ان کا معاون بننا دنیا اور آخرت کی ہلاکت کا باعث ہے۔"}],[4761,"اس سند سے بھی ام سلمہ رضی اللہ عنہا نے نبی اکرم صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث روایت کی ہے، البتہ اس میں یہ ہے کہآپ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ناپسند کیا تو وہ بری ہو گیا اور جس نے کھل کر انکار کر دیا تو وہ محفوظ ہو گیا\" قتادہ کہتے ہیں: مطلب یہ ہے کہ جس نے دل سے اس کا انکار کیا اور جس نے دل سے اسے ناپسند کیا۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کے ہم معنی روایت کیا کہا کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جس نے دل سے ناپسند جانا اور مکروہ سمجھا وہ بری ہوا اور جس نے انکار کیا وہ محفوظ رہا۔ “ قتادہ رضی اللہ عنہ نے کہا: مقصد یہ ہے کہ دل سے انکار کیا اور دل سے برا جانا۔","f2":"دل سے برا جاننے کا مفہوم یہ ہے کہ ایسے آدمی کو عزم رکھنا چاہیے کہ آج تو نہیں کل لاں جب ممکن ہوا اس برائی کا قلع قمع کرکے رہوں گا۔"}],[4762,"عرفجہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"میری امت میں کئی بار شر و فساد ہوں گے، تو متحد مسلمانوں کے شرازہ کو منتشر کرنے والے کی گردن تلوار سے اڑا دو خواہ وہ کوئی بھی ہو\"۔","صحیح",{"u2":"سیدنا عرفجہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ” میری امت میں فتنے ہوں گے ‘ فتنے اور فتنے۔ چنانچہ جس نے چاہا کہ مسلمانوں کے معاملے میں تفرقہ ڈال دے جبکہ وہ متحد و متفق ہوں تو ایسے کو تلوار سے قتل کر دینا ‘ خواہ کوئی بھی ہو۔ “","f2":"یہ فتنہ سب سے پہلے انہی لوگوں نے ڈالا جنہوں نے حضرت عثمان رضی اللہ کے خلاف بغاوت کی جو متفق علیہ خلیفہ راشد تھے۔ بعد میں انہی لوگوں نے حضرت علی رضی اللہ کے خلاف خروج (بغاوت) کیا۔"}],[4763,"عبیدہ سے روایت ہے کہ علی رضی اللہ عنہ نے اہل نہروان ۱؎ کا ذکر کیا اور کہا: ان میں چھوٹے ہاتھ کا ایک آدمی ہے، اگر مجھے تمہارے اترانے کا اندیشہ نہ ہوتا تو میں تمہیں بتاتا کہ اللہ تعالی نے محمد صلی اللہ علیہ وسلم کی زبان سے کس چیز کا وعدہ کیا ہے ان لوگوں کے لیے جو ان سے جنگ کریں گے، راوی کہتے ہیں: میں نے کہا: کیا آپ نے اسے اللہ کے رسول صلی اللہ علیہ وسلم سے سنا ہے؟ انہوں نے کہا: ہاں رب کعبہ کی قسم۔\n§وضاحت\n۱؎ : بغداد اور واسط کے درمیان تین گاؤں ہیں جن میں ایک اونچائی پر ہے دوسرا درمیان میں اور تیسرا نشیب میں ، اسی جگہ امیر المومنین علی رضی اللہ عنہ نے خوارج کے ساتھ جنگ کی۔","صحیح",{"u2":"جناب عبیدہ سلمانی نے روایت کیا کہ سیدنا علی رضی اللہ عنہ نے اہل نہروان کا تذکرہ کیا اور بتایا کہ ان میں ایک آدمی ہو گا جس کا ایک ہاتھ چھوٹا ہو گا یا اس میں نقص ہو گا یا ایسے ہو گا جیسے عورت کا پستان ‘ اگر مجھے اندیشہ نہ ہو کہ تم لوگ خوشی میں آ کر بہت آگے بڑھ جاؤ گے تو میں تمہیں وہ ضرور بتا دیتا جو اللہ عزوجل نے محمد صلی اللہ علیہ وسلم کی زبانی ان سے قتال کرنے والے کے بارے میں وعدہ فرمایا ہے۔ عبیدہ کہتے ہیں کہ میں نے سیدنا علی رضی اللہ عنہ سے پوچھا: کیا یہ فرمان آپ نے نبی کریم صلی اللہ علیہ وسلم سے سنا تھا؟ فرمایا ہاں ‘ رب کعبہ کی قسم!۔"}],[4764,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں علی رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم کے پاس مٹی سے آلودہ سونے کا ایک ٹکڑا بھیجا ۱؎، آپ صلی اللہ علیہ وسلم نے اسے چار لوگوں: اقرع بن حابس حنظلی مجاشعی، عیینہ بن بدر فزاری، زید الخیل طائی جو بنی نبہان کے ایک فرد ہیں اور علقمہ بن علاثہ عامری جو بنی کلاب سے ہیں کے درمیان تقسیم کر دیا، اس پر قریش اور انصار کے لوگ ناراض ہو گئے اور کہنے لگے: آپ اہل نجد کے رئیسوں کو دیتے ہیں اور ہمیں چھوڑ دیتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں ان کی تالیف قلب کرتا ہوں\"اتنے میں ایک شخص آیا (جس کی آنکھیں دھنسی ہوئی، رخسار ابھرے ہوئے اور پیشانی بلند، داڑھی گھنی اور سر منڈا ہوا تھا) اور کہنے لگا: اے محمد! اللہ سے ڈرو، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب میں ہی اس کی نافرمانی کرنے لگوں گا تو کون اس کی فرمانبرداری کرے گا، اللہ تو زمین والوں میں مجھے امانت دار سمجھتا ہے اور تم مجھے امانت دار نہیں سمجھتے؟\" تو ایک شخص نے اس کے قتل کی اجازت چاہی، میرا خیال ہے وہ خالد بن ولید رضی اللہ عنہ تھے، تو آپ صلی اللہ علیہ وسلم نے منع فرمایا، اور جب وہ لوٹ گیا تو آپ نے فرمایا: \"اس کی نسل میں کچھ ایسے لوگ ہوں گے جو قرآن پڑھیں گے، وہ ان کے گلوں سے نیچے نہیں اترے گا، وہ اسلام سے اسی طرح نکل جائیں گے جیسے تیر اس شکار کے جسم سے نکل جاتا ہے جسے تیر مارا جاتا ہے، وہ اہل اسلام کو قتل کریں گے اور بت پوجنے والوں کو چھوڑ دیں گے، اگر میں نے انہیں پایا تو میں انہیں قوم عاد کی طرح قتل کروں گا ۲؎\"۔\n§وضاحت\n۱؎ : یعنی جس طرح زمیں سے نکلا ویسے ہی مٹی سمیت بھیج دیا۔ ۲؎ : یہ حدیث خوارج کے سلسلہ میں ہے، اعتراض کرنے والا خارجیوں کا سردار ہوا، ایک بات اس حدیث سے یہ بھی معلوم ہوئی کہ نبی کریم صلی اللہ علیہ وسلم نے جن لوگوں کو مال دیا تھا وہ نجدی تھے، اور یہ شخص نجدی نہیں تھا، اسی نے \"یا محمد\" کہا جو آج اہل بدعت نے اپنا شعار بنا رکھا ہے، ان لوگوں کو علی رضی اللہ عنہ نے مقام نہروان میں قتل کیا ،آپ صلی اللہ علیہ وسلم کے فرمان کہ \" میں قوم عاد کی طرح قتل کروں گا \" کا مطلب یہ ہے کہ ان کو نیست ون ابود کر دوں گا، جیسے قوم عاد نیست و نابود ہو گئی، قوم عاد سے مشابہت صرف کلی ہلاکت میں ہے۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ سیدنا علی رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کی خدمت میں کچھ سونا بھیجا جو ابھی صاف نہیں کیا گیا تھا۔ آپ صلی اللہ علیہ وسلم نے اسے اقرع بن حابس حنظلی مجاشعی ‘ عیینہ بن بدر فزاری ‘ بنو نبھان کے زید الخیل الطائی اور بنو کلاب کے علقمہ بن علاثہ مری چار آدمیوں میں تقسیم کر دیا۔ تو قریشیوں اور انصاریوں کو اس پر غصہ آیا اور انہوں نے کہا: اہل نجد کے بڑوں کو دے رہے ہیں اور ہمیں چھوڑ رہے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں تو ان کی تالیف قلب کرنا چاہتا ہوں (تاکہ اسلام میں ان کا دل جم جائے۔ “) تو اس اثناء میں ایک آدمی آیا جس کی آنکھیں گہری (اندر کو دھنسی ہوئی) تھیں رخسار ابھرے ہوئے ‘ پیشانی اوپر کو اٹھی ہوئی، ڈاڑھی گھنی اور سر منڈا ہوا تھا ‘ کہنے لگا: اے محمد! اللہ سے ڈرو۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر میں ہی اللہ کی نافرمانی کرنے لگوں تو کون اس کی اطاعت کرے گا؟ اللہ عزوجل تو مجھے زمین والوں کے لیے امین بنائے اور تم مجھے امین نہیں سمجھتے ہو؟ “ راوی نے کہا: اس پر ایک شخص نے پوچھا: کیا میں اس کو قتل کر دوں؟ میرا خیال ہے وہ خالد بن ولید رضی اللہ عنہ تھے۔ مگر آپ صلی اللہ علیہ وسلم نے اسے روک دیا۔ پھر جب وہ کمر پھیر کر چلا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اس شخص کی نسل میں ایسے لوگ ہوں گے جو قرآن پڑھیں گے مگر وہ ان کے حلقوں سے نیچے نہیں اترے گا ‘ اسلام سے ایسے نکلیں گے جیسے تیر اپنے شکار سے نکل جاتا ہے یہ لوگ مسلمانوں کو قتل کریں گے اور بت پرستوں کو چھوڑیں گے ‘ اللہ کی قسم! اگر میں نے ان کو پایا تو انہیں قوم عاد کی مانند قتل کروں گا۔ “","f2":"رسول صلی اللہ علیہ وسلم انتہائی حلیم ومتحمل مزاج تھے اور بے ادب وگستاخ لوگوں سے بھی صرفنظر کر جاتے تھے۔ چنانچہ حکام،قضاہ اور اصحاب منصب کو بھی چاہیے کہ پہلے جاہلوں کی اصلاح کی کوشش کریں اگر وہ اعلانیہ فساد پھیلانے لگیں تو ان کا قلع قمع کریں۔"}],[4765,"ابو سعید خدری اور انس بن مالک رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میری امت میں اختلاف اور تفرقہ ہو گا، کچھ ایسے لوگ ہوں گے، جو باتیں اچھی کریں گے لیکن کام برے کریں گے، وہ قرآن پڑھیں گے لیکن وہ ان کے حلق سے نیچے نہ اترے گا، وہ دین سے اسی طرح نکل جائیں گے جس طرح تیر شکار سے نکل جاتا ہے، وہ (اپنی روش سے) باز نہیں آئیں گے جب تک تیر سوفار (اپنی ابتدائی جگہ) پر الٹا نہ آ جائے، وہ سب لوگوں اور مخلوقات میں بدترین لوگ ہیں، بشارت ہے اس کے لیے جو انہیں قتل کرے یا جسے وہ قتل کریں، وہ کتاب اللہ کی طرف بلائیں گے، حالانکہ وہ اس کی کسی چیز سے کچھ بھی تعلق نہیں رکھتے ہوں گے، جو ان سے قتال کرے گا، وہ لوگوں میں سب سے زیادہ اللہ سے قریب ہو گا\" لوگوں نے عرض کیا: اللہ کے رسول! ان کی نشانی کیا ہو گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"سر منڈانا\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ اور سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میری امت میں اختلاف و افتراق آ جائے گا۔ ایک قوم باتیں بہت اچھی اچھی کرے گی مگر کام ان کے بہت برے ہوں گے۔ قرآن پڑھتے ہوں گے مگر وہ ان کی ہنسلیوں سے نیچے نہیں اترے گا۔ وہ دین سے ایسے نکل جائیں گے جیسے تیر اپنے ہدف (شکار) سے نکل جاتا ہے۔ ان کا حق کی طرف لوٹنا ایسے ہی محال ہو گا جیسے تیر کا اپنی کمان پر واپس آنا۔ وہ انسانوں میں اور مخلوقات میں سب سے برے ہوں گے۔ مبارک ہو ایسے شخص کو جو انہیں قتل کرے اور وہ اسے قتل کریں۔ (شہادت پا جائیں)۔ وہ بظاہر اللہ کی کتاب کی طرف بلائیں گے مگر ان کا کوئی تعلق اس کتاب سے نہیں ہو گا۔ جو ان سے قتال کرے گا وہ ان کی نسبت اللہ تعالیٰ سے بہت قریب ہو گا۔ “ صحابہ کرام رضی اللہ عنہم م نے کہا: اے اللہ کے رسول! ان کی علامت کیا ہو گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” سر منڈانا۔ “","f2":"ہمارے فاضل محقق نے اس روایت کو سندا ضعیف قراد دیا ہے جبکہ دیگر محققیناس کو صحیح قراردیتے ہیں اور انہی کی رائے اقرب الی الصوب محسوس ہوتی ہے۔\n2:انسان کے قول و فعل میں تضادہونا ایسی قبیح بات ہے جو اللہ عزوجل کے انتہائی غضب اوراس کی ناراضی کا باعث ہے۔ ارشاد باری تعالی ہے۔ (كبر مقتاعندالله ان تقولوما لا تفعلون)(الصف:٣) الله عزوجل كے نزديك انتہائی ناپسند ہے کہ تم وہ کہو جو کرتے نہیں۔\n3:دین کی من مانی تعبیر،فسق وفجوراور بدعات اوران میں غلوکی نحوست یہ ہے کہ انسان توبہ اور حق کی طرف لوٹنے کی توفیق سے محروم کر دیا جاتا ہے۔\n4:دین کا وہی تعبیر ومعتبرہے جو جمہور صحابہ کرام رضی اللہ نے رسول اللہ صلی اللہ علیہ وسلم سے نقل کی۔\n5:خلیفہ المسلمین کا فرض ہے کہ دین اور مسلمانوں میں فتنہ اور انتشار پیدا کرنے والوں کا قلع قلع کرے اوران سےقتال کرنے والے یا اس میں شہید ہو جانے والے لوگ افضل لو گ ہوتے ہیں۔\n6:سر کے بال بڑھا کر رکھنا منڈانے کی نسبت زیادہ افضل ہے تاکہ ایسے لوگوں سے مشا بہت نہ رہے۔ ویسے منڈانا بھی جائز ہے،جیساکہ حضرت علی رضی اللہ کا معمول تھا،البتہ خوارج اس کا التزام کرتے تھے اور یہ ان کی پہچان بن گئی تھی۔"}],[4766,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح فرمایا، البتہ اس میں یہ ہے کہ آپ نے فرمایا: \"ان کی علامت سر منڈانا اور بالوں کو جڑ سے ختم کرنا ہے، لہٰذا جب تم انہیں دیکھو تو انہیں قتل کر دو\"۔ ابوداؤد کہتے ہیں: «تسبید» : بال کو جڑ سے ختم کرنے کو کہتے ہیں۔","صحیح",{"u2":"جناب قتادہ نے سیدنا انس رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کی مانند روایت کیا ہے اس روایت میں ہے کہ ” ان (خوراج) کی علامت سر منڈانا اور بال دور کرنا ہے۔ جب تم انہیں پاؤ تو انہیں سلا (قتل کر) دینا۔ “ امام ابوداؤد رضی اللہ عنہ نے فرمایا حدیث میں وارد لفظ «التسبيد» کے معنی ہیں «استئصال الشعر» ” بالوں کو جڑوں سے اکھیڑنا یا جڑوں سے مونڈنا۔ “"}],[4767,"سوید بن غفلہ کہتے ہیں کہ علی رضی اللہ عنہ نے کہا: جب میں رسول اللہ صلی اللہ علیہ وسلم کی کوئی حدیث تم سے بیان کروں تو آسمان سے میرا گر جانا مجھے اس بات سے زیادہ محبوب ہے کہ میں آپ پر جھوٹ بولوں، اور جب میں تم سے اس کے متعلق کوئی بات کروں جو ہمارے اور تمہارے درمیان ہے تو جنگ چالاکی و فریب دہی ہوتی ہی ہے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"آخری زمانے میں کچھ ایسے لوگ آئیں گے جو کم عمر اور کم عقل ہوں گے، جو تمام مخلوقات میں بہتر شخص کی طرح باتیں کریں گے، وہ اسلام سے اس طرح نکل جائیں گے جس طرح تیر شکار سے نکل جاتا ہے، ان کا ایمان ان کی گردنوں سے نیچے نہ اترے گا، لہٰذا جہاں کہیں تم ان سے ملو تم انہیں قتل کر دو، اس لیے کہ ان کا قتل کرنا، قیامت کے روز اس شخص کے لیے اجر و ثواب کا باعث ہو گا جو انہیں قتل کرے گا\"۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ نے کہا کہ جب میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کرتا ہوں (تو اس میں کوئی خفا نہیں ہوتا ‘ بالکل حق اور صاف ہوتی ہے) مجھے آسمان سے گرنا ‘ رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ بولنے کی نسبت بہت زیادہ پسند ہے اور جب میں تم سے آپس کی کوئی بات کرتا ہوں تو (یاد رکھو) لڑائی چال کا نام ہے (بہت سے مصلحتیں ملحوظ رکھنی ضروری ہیں اس لیے ان باتوں کو عام نہیں کرنا چاہیئے) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ” آخری زمانے میں لوگ آئیں گے جو عمروں میں نوجوان ہوں گے مگر بے عقل۔ مخلوق میں سب سے افضل ترین شخصیت (رسول اللہ صلی اللہ علیہ وسلم) کی باتیں کرتے ہوں گے مگر دین سے ایسے گزر جائیں گے جیسے کہ تیر اپنے شکار سے نکل جاتا ہے۔ ان کا ایمان ان کے حلقوں سے نیچے نہیں اترتا ہو گا۔ تم ان سے جہاں بھی ملو ‘ انہیں قتل کر دینا۔ بلاشبہ ان کے قتل میں ان کے قاتل کے لیے قیامت کے روز بہت بڑا اجر ہو گا۔ “جب میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کی حدیث بیان کرتا ہوں (تو اس میں کوئی خفا نہیں ہوتا ‘ بالکل حق اور صاف ہوتی ہے) مجھے آسمان سے گرنا ‘ رسول اللہ صلی اللہ علیہ وسلم پر جھوٹ بولنے کی نسبت بہت زیادہ پسند ہے اور جب میں تم سے آپس کی کوئی بات کرتا ہوں تو (یاد رکھو) لڑائی چال کا نام ہے (بہت سے مصلحتیں ملحوظ رکھنی ضروری ہیں اس لیے ان باتوں کو عام نہیں کرنا چاہیئے) میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ” آخری زمانے میں لوگ آئیں گے جو عمروں میں نوجوان ہوں گے مگر بے عقل۔ مخلوق میں سب سے افضل ترین شخصیت (رسول اللہ صلی اللہ علیہ وسلم) کی باتیں کرتے ہوں گے مگر دین سے ایسے گزر جائیں گے جیسے کہ تیر اپنے شکار سے نکل جاتا ہے۔ ان کا ایمان ان کے حلقوں سے نیچے نہیں اترتا ہو گا۔ تم ان سے جہاں بھی ملو ‘ انہیں قتل کر دینا۔ بلاشبہ ان کے قتل میں ان کے قاتل کے لیے قیامت کے روز بہت بڑا اجر ہو گا۔ “"}],[4768,"زید بن وہب جہنی بیان کرتے ہیں کہ وہ اس فوج میں شامل تھے جو علی رضی اللہ عنہ کے ساتھ تھی، اور جو خوارج کی طرف گئی تھی، علی نے کہا: اے لوگو! میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"میری امت میں کچھ لوگ ایسے نکلیں گے کہ وہ قرآن پڑھیں گے، تمہارا پڑھنا ان کے پڑھنے کے مقابلے کچھ نہ ہو گا، نہ تمہاری نماز ان کی نماز کے مقابلے کچھ ہو گی، اور نہ ہی تمہارا روزہ ان کے روزے کے مقابلے کچھ ہو گا، وہ قرآن پڑھیں گے، اور سمجھیں گے کہ وہ ان کے لیے (ثواب) ہے حالانکہ وہ ان پر (عذاب) ہو گا، ان کی صلاۃ ان کے حلق سے نیچے نہ اترے گی، وہ اسلام سے نکل جائیں گے، جس طرح تیر شکار سے نکل جاتا ہے، اگر ان لوگوں کو جو انہیں قتل کریں گے، یہ معلوم ہو جائے کہ ان کے لیے ان کے نبی اکرم صلی اللہ علیہ وسلم کی زبانی کس چیز کا فیصلہ کیا گیا ہے، تو وہ ضرور اسی عمل پر بھروسہ کر لیں گے (اور دوسرے نیک اعمال چھوڑ بیٹھیں گے) ان کی نشانی یہ ہے کہ ان میں ایک ایسا آدمی ہو گا جس کے بازو ہو گا، لیکن ہاتھ نہ ہو گا، اس کے بازو پر پستان کی گھنڈی کی طرح ایک گھنڈی ہو گی، اس کے اوپر کچھ سفید بال ہوں گے\" تو کیا تم لوگ معاویہ اور اہل شام سے لڑنے جاؤ گے، اور انہیں اپنی اولاد اور اسباب پر چھوڑ دو گے (کہ وہ ان پر قبضہ کریں اور انہیں برباد کریں) اللہ کی قسم مجھے امید ہے کہ یہی وہ لوگ ہیں (جن کے بارے میں نبی اکرم صلی اللہ علیہ وسلم کا فرمان ہے) اس لیے کہ انہوں نے ناحق خون بہایا ہے، لوگوں کی چراگاہوں پر شب خون مارا ہے، چلو اللہ کے نام پر۔ سلمہ بن کہیل کہتے ہیں: پھر زید بن وہب نے مجھے ایک ایک مقام بتایا (جہاں سے ہو کر وہ خارجیوں سے لڑنے گئے تھے) یہاں تک کہ وہ ہمیں لے کر ایک پل سے گزرے۔ وہ کہتے ہیں: جب ہماری مڈبھیڑ ہوئی تو خارجیوں کا سردار عبداللہ بن وہب راسبی تھا اس نے ان سے کہا: نیزے پھینک دو اور تلواروں کو میان سے کھینچ لو، مجھے اندیشہ ہے کہ کہیں وہ تم سے اسی طرح صلح کا مطالبہ نہ کریں جس طرح انہوں نے تم سے حروراء کے دن کیا تھا، چنانچہ انہوں نے اپنے نیز ے پھینک دئیے، تلواریں کھینچ لیں، لوگوں (مسلمانوں) نے انہیں اپنے نیزوں سے روکا اور انہوں نے انہیں ایک پر ایک کر کے قتل کیا اور (مسلمانوں میں سے) اس دن صرف دو آدمی شہید ہوئے، علی رضی اللہ عنہ نے کہا: ان میں «مخدج» یعنی لنجے کو تلاش کرو، لیکن وہ نہ پا سکے، تو آپ خود اٹھے اور ان لوگوں کے پاس آئے جو ایک پر ایک کر کے مارے گئے تھے، آپ نے کہا: انہیں نکالو، تو انہوں نے اسے دیکھا کہ وہ سب سے نیچے زمین پر پڑا ہے، آپ نے نعرہ تکبیر بلند کیا اور بولے: اللہ نے سچ فرمایا اور اس کے رسول نے ساری باتیں پہنچا دیں۔ پھر عبیدہ سلمانی آپ کی طرف اٹھ کر آئے کہنے لگے: اے امیر المؤمنین! قسم ہے اس ذات کی جس کے سوا کوئی لائق عبادت نہیں کیا آپ نے اسے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے؟ وہ بولے: ہاں، اللہ کی قسم جس کے سوا کوئی لائق عبادت نہیں، یہاں تک کہ انہوں نے انہیں تین بار قسم دلائی اور وہ (تینوں بار) قسم کھاتے رہے۔","صحیح",{"u2":"زید بن وہب جہنی نے بیان کیا کہ زید بن وہب جہنی نے بیان کیا کوہ سیدنا علی رضی اللہ عنہ کے ساتھ اس لشکر میں شریک تھا جو خارجیوں کی طرف گیا تھا۔ سیدنا علی رضی اللہ عنہ نے فرمایا: لوگو! میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ‘ آپ صلی اللہ علیہ وسلم فرماتے تھے ” میری امت میں ایسے لوگ ہوں گے جو قرآن پڑھتے ہوں گے۔ تمہاری قرآت ان کی قرآت کے مقابلے میں کچھ بھی نہیں ہو گی ‘ نہ تمہاری نمازیں ان کی نمازوں کے مقابلے میں کچھ ہوں گی نہ تمہارے روزے ان کے روزوں کے مقابلے میں کچھ حیثیت رکھتے ہوں گے ‘ وہ قرآن پڑھتے ہوں گے اور سمجھیں گے کہ یہ ان کے حق میں دلیل اور تائید ہے ‘ حالانکہ وہ ان کے خلاف ہو گا۔ ان کی نمازیں ان کی ہنسلیوں سے آگے نہیں بڑھیں گی۔ اسلام سے ایسے گزر جائیں گے جیسے تیر اپنے شکار میں سے نکل جاتا ہے۔ “ اگر اس لشکر کو جو ان (خارجیوں) کو قتل کرے گا ان فضائل کا علم ہو جائے جو اللہ نے ان کے نبی صلی اللہ علیہ وسلم کی زبانی ان کے لیے مقدر فرمائے ہیں تو وہ اسی پر تکیہ کر لیں اور ان (خارجیوں) کی نشانی یہ ہے کہ ان میں ایک ایسا آدمی ہو گا جس کی کہنی سے اوپر کا بازو تو ہو گا ‘ کہنی سے نیچے کلائی نہیں ہو گی۔ اوپر کے بازو کا آخر پستان کی بھٹنی کی طرح ہو گا۔ اس پر سفید بال ہوں گے۔ کیا بھلا تم لوگ معاویہ اور اہل شام کی طرف جانا چاہتے ہو اور ان (خارجیوں) کو اپنی اولادوں اور مال و اسباب میں پیچھے چھوڑ دینا چاہتے ہو؟ اللہ کی قسم! مجھے امید ہے کہ یہی وہ لوگ ہیں۔ (جن کی خبر رسول اللہ صلی اللہ علیہ وسلم نے دی) انہوں نے حرام خون بہایا اور لوگوں کے محفوظ علاقے (جان ‘ عزت ‘ مال) لوٹی۔ چنانچہ اللہ کا نام لے کر (ان کے مقابلے میں) چلو۔ سلمہ بن کہیل نے کہا کہ زید بن وہب مجھے منزل بمنزل لے کر چلتے گئے حتیٰ کہ ہم ایک پل سے گزرے ‘ پھر بتایا کہ جب ہم ان کے مقابل ہوئے اور خارجیوں کا سردار عبداللہ بن وہب راسبی تھا تو اس نے اپنے لوگوں سے کہا: نیزے پھینک دو اور تلواریں اپنی میانوں سے نکال لو۔ مجھے ڈر ہے کہ یہ تم سے اسی طرح مقابلہ کریں گے جیسے حروراء والے دن کیا تھا۔ کہا: چنانچہ ان لوگوں نے اپنے نیزے پھینک دیے اور تلواریں کھینچ لیں تو لوگوں نے ان کو اپنے نیزوں سے چھلنی کرنا شروع کر دیا اور ان کو ایک دوسرے کے اوپر قتل کیا۔ جبکہ سیدنا علی رضی اللہ عنہ کے لشکر میں سے صرف دو آدمی شہید ہوئے۔ تو سیدنا علی رضی اللہ عنہ نے کہا: تلاش کرو ‘ ان میں ایک لنجا ہو گا ‘ مگر انہیں نہ ملا۔ تو سیدنا علی رضی اللہ عنہ خود اٹھے حتیٰ کہ ان میتوں کے پاس آئے جو ایک دوسرے پر قتل ہوئے تھے۔ انہوں نے فرمایا: انہیں نکالو۔ چنانچہ انہوں نے اسے پا لیا جو کہ سب سے نیچے زمین پر پڑا تھا۔ سیدنا علی رضی اللہ عنہ نے اللہ اکبر پکارا اور کہا: اللہ نے سچ فرمایا اور اس کے رسول صلی اللہ علیہ وسلم نے پہنچا دیا۔ پس جناب عبیدہ سلمانی ان کی طرف کھڑے ہوئے اور کہا: اے امیر المؤمنین! قسم اس اللہ کی جس کے سوا کوئی معبود نہیں! کیا یہ بیان آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا؟ انہوں نے فرمایا: ہاں اللہ کی قسم! جس کے سوا کوئی معبود نہیں۔ حتیٰ کہ انہوں نے تین بار قسم دی اور سیدنا علی رضی اللہ عنہ نے بھی تین بار قسم سے جواب دیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ امام مالک نے فرمایا: یہ علم کی اہانت ہے کہ عالم ہر پوچھنے والے کا جواب دینے لگے۔ہ","f2":"جو اعمال ایمان واخلاص اور تقوی وسنت کے مطابق نہ ہوں،وہ مقدارمیں خواہ کتنے ہی کیوں نہ ہوں،اللہ کے ہاں ان کی کوئی قدر نہیں۔\n2:عام سیاسی مخالف اور دینی دشمن مقابلے میں ہوں تو مسلمان کو اپنی نظر دینی دشمن پر رکھنی چاہیے۔\n3:حضرت علی رضی اللہ وہ خلیفہ راشدتھےجنہوں نے خارجیوں کا قلع قمع کرنے میں سرتوڑکوشش فرمائی۔\n4:امام مالک کے قول کا مطلب یہ ہے کہ جس طرح حضرت علی رضی اللہ نے سب کے سامنے ایک حقیقت واضح کرنے کے لئے بار بار قسم کے ساتھ جواب دیا،یہ ضرورت کے مطابق تھا لیکن اس سے نہ سمجھ لیا جائے کہ کسی عام سی بات کو اس طرح کوئی پوچھے تو جواب دینا ضروری ہے۔"}],[4769,"ابوالوضی کہتے ہیں کہ علی رضی اللہ عنہ نے کہا: «مخدج» (لنجے) کو تلاش کرو، پھر راوی نے پوری حدیث بیان کی، اس میں ہے: لوگوں نے اسے مٹی میں پڑے ہوئے مقتولین کے نیچے سے ڈھونڈ نکالا، گویا میں اس کی طرف دیکھ رہا ہوں، وہ ایک حبشی ہے چھوٹا سا کرتا پہنے ہوئے ہے، اس کا ایک ہاتھ عورت کے پستان کی طرح ہے، جس پر ایسے چھوٹے چھوٹے بال ہیں، جیسے جنگلی چوہے کی دم پر ہوتے ہیں۔","صحیح الإسناد"],[4770,"ابومریم کہتے ہیں کہ یہ «مخدج» (لنجا) مسجد میں اس دن ہمارے ساتھ تھا ہم اس کے ساتھ رات دن بیٹھا کرتے تھے، وہ فقیر تھا، میں نے اسے دیکھا کہ وہ مسکینوں کے ساتھ آ کر علی رضی اللہ عنہ کے کھانے پر لوگوں کے ساتھ شریک ہوتا تھا اور میں نے اسے اپنا ایک کپڑا دیا تھا۔ ابومریم کہتے ہیں: لوگ «مخدج» (لنجے) کو «نافعا ذا الثدية» (پستان والا) کا نام دیتے تھے، اس کے ہاتھ میں عورت کے پستان کی طرح گوشت ابھرا ہوا تھا، اس کے سرے پر ایک گھنڈی تھی جیسے پستان میں ہوتی ہے اس پر بلی کی مونچھوں کی طرح چھوٹے چھوٹے بال تھے۔ ابوداؤد کہتے ہیں: لوگوں کے نزدیک اس کا نام حرقوس تھا۔","ضعیف الإسناد",{"u2":"ابومریم نے کہا: تحقیق یہ لنجا آدمی ان دنوں ہمارے ساتھ مسجد میں ہوتا تھا۔ دن رات ہم اس کے ساتھ بیٹھتے تھے ‘ فقیر آدمی تھا۔ میں نے اسے مسکینوں کے ساتھ دیکھا جو سیدنا علی رضی اللہ عنہ کے طعام میں شریک ہوتا تھا ‘ جو وہ لوگوں کے ساتھ تناول کرتے تھے۔ اور میں نے اس کو اپنا اوور کوٹ بھی دیا تھا۔ ابومریم نے کہا: اس لنجے کو «نافع ذوالثدية» (پستان والا) کہا جاتا تھا۔ اس کے بازو پر عورت کے پستان کی طرح پستان سا تھا اور اس کے سرے پر بھٹنی بھی تھی۔ اور اس پر بلی کی مونچھوں کی طرح کچھ بال تھے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: لوگوں میں اس کا نام حرقوس معروف ہے۔"}],[4771,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس کا مال لینے کا ناحق ارادہ کیا جائے اور وہ (اپنے مال کے بچانے کے لیے) لڑے اور مارا جائے تو وہ شہید ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس کسی کا مال ناحق طور پر چھیننے کی کوشش کی گئی اور پھر اس نے قتال کیا اور اس میں وہ قتل ہو گیا ‘ تو وہ شہید ہے۔ “"}],[4772,"سعید بن زید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اپنا مال بچانے میں مارا جائے وہ شہید ہے اور جو اپنے بال بچوں کو بچانے یا اپنی جان بچانے یا اپنے دین کو بچانے میں مارا جائے وہ بھی شہید ہے\"۔","صحیح",{"u2":"سیدنا سعید بن زید رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا &rdquo; جو شخص اپنے مال کی حفاظت میں قتل ہو جائے وہ شہید ہے۔ اور جو اپنے گھر والوں کی حفاظت یا خون یا دین کے دفاع میں قتل ہو جائے &lsquo; وہ شہید ہے۔ &ldquo; امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ہمیں عبداللہ بن قریش بخاری نے بیان کیا &lsquo; انہوں نے کہا کہ میں نے نعیم بن حماد سے سنا &lsquo; وہ کہتے تھے کہ فرقہ معتزلہ کے لوگ نبی کریم صلی اللہ علیہ وسلم کی تقریباً دو ہزار احادیث رد کرتے ہیں۔ جناب عوف بن مالک رضی اللہ عنہ سے مروی ہے &lsquo; انہوں نے کہا: میں نے حجاج (حجاج بن یوسف) کو سنا &lsquo; وہ خطبہ دیتے ہوئے کہہ رہا تھا کہ سیدنا عثمان رضی اللہ عنہ کی مثال اللہ کے ہاں عیسیٰ ابن مریم علیہ السلام کی مانند ہے۔ پھر اس نے یہ آیت پڑھی &laquo;إذ قال الله يعيسى *** الذين کفروا&raquo; &rdquo; اور جب اللہ تعالیٰ نے فرمایا: اے عیسیٰ! میں تجھے پورا (جسم و جان سمیت) اپنے پاس لانے والا ہوں &lsquo; تجھے اپنی جانب اٹھانے والا ہوں اور تجھے کافروں سے پاک کرنے والا ہوں۔ &ldquo; پھر اس کی تفسیر کرتے ہوئے وہ اپنے ہاتھ سے ہماری اور اہل شام کی طرف اشارہ کرتا تھا۔ جناب وہب بن منبہ اپنے بھائی ہمام بن منبہ کے واسطے سے سیدنا معاویہ رضی اللہ عنہ سے روایت کرتے ہیں &lsquo; انہوں نے کہا کہ سفارش کرو اجر پاؤ گے &lsquo; بلاشبہ میں کسی معاملے کا ارادہ کرتا ہوں تو اسے ٹالتا رہتا ہوں تاکہ تم سفارش کرو اور ثواب کے مستحق بنو۔ اس لیے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے &rdquo; سفارش کیا کرو اجر پاؤ گے۔ &ldquo; جناب ابومعمر اپنی سند سے بواسطہ سیدنا ابوموسیٰ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے اس ک مثل روایت کرتے ہیں۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ میں نے امام احمد بن حنبل رضی اللہ عنہ سے سنا &lsquo; وہ فرماتے تھے: عفان بن مسلم نے کہا کہ یحییٰ بن بن سعید القطان &lsquo; ہمام بن یحییٰ سے روایت نہیں کرتے تھے۔ امام احمد رضی اللہ عنہ نے کہا: عفان (عفان بن مسلم) نے بتایا کہ جب معاذ بن ہشام (دستوائی) نے اور احادیث بیان کیں &lsquo; جن سے ہمام کی مرویات کی تائید ہوئی (تو یحییٰ بن سعید نے ان کے بارے میں اپنے رائے بدل لی) چنانچہ اس کے بعد یحییٰ یوں پوچھا کرتے تھے: ہمام نے اس بارے میں کیا کہا ہے؟ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ میں نے امام احمد رضی اللہ عنہ سے سنا &lsquo; وہ کہتے تھے کہ عفان اور ان کے ساتھیوں کا ہمام سے سماع عبدالرحمٰن بن مہدی کے (ہمام سے) سماع سے بہت بہتر ہے۔ (اور عفان سماع کے بعد) کتابوں کا مراجعہ کرتے رہتے تھے۔ سیدنا حسین بن علی رضی اللہ عنہ سے مروی ہے کہ عفان نے انشاءاللہ ہمیں بتایا کہ مجھے ہمام بن یحییٰ نے کہا: میں غلطی کرتا رہا کہ مراجعہ نہیں کرتا تھا اور اس بات پر اللہ تعالیٰ سے استغفار کرتا ہوں۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ میں نے علی بن عبداللہ (المدینی) سے سنا &lsquo; وہ کہتے تھے: اپنی سماع کردہ احادیث سے بخوبی آگاہ ہونے اور ان کے مراجعہ میں شعبہ سب سے بڑھ کر ہیں اور روایت کرنے میں سب سے عمدہ ہشام (ہشام دستوائی) اور حفظ میں سعید بن ابی عروبہ سب سے بڑھ کر ہیں۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ میں نے یہ بات امام احمد رضی اللہ عنہ کے سامنے ذکر کی تو انہوں نے کہا کہ سعید بن ابی عروبہ نے ہشام (ہشام دستوائی) کے بارے میں جو کچھ کہا ہے وہ سب (اس کے بیٹے) معاذ بن ہشام سے بیان کرتے ہیں۔ اور ہشام کا سعید سے کیا مقابلہ &lsquo; اگر وہ اس سے موازنہ کیا بھی جائے۔"}],[4773,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں میں سب سے بہتر اخلاق والے تھے، ایک دن آپ نے مجھے کسی ضرورت سے بھیجا تو میں نے کہا: قسم اللہ کی، میں نہیں جاؤں گا، حالانکہ میرے دل میں یہ بات تھی کہ اللہ کے نبی اکرم صلی اللہ علیہ وسلم نے حکم دیا ہے، اس لیے ضرور جاؤں گا، چنانچہ میں نکلا یہاں تک کہ جب میں کچھ بچوں کے پاس سے گزر رہا تھا اور وہ بازار میں کھیل رہے تھے کہ اچانک رسول اللہ صلی اللہ علیہ وسلم نے میرے پیچھے سے میری گردن پکڑ لی، میں نے آپ صلی اللہ علیہ وسلم کی طرف مڑ کر دیکھا، آپ ہنس رہے تھے، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے ننھے انس! جاؤ جہاں میں نے تمہیں حکم دیا ہے\"میں نے عرض کیا: ٹھیک ہے، میں جا رہا ہوں، اللہ کے رسول، انس کہتے ہیں: اللہ کی قسم، میں نے سات سال یا نو سال آپ صلی اللہ علیہ وسلم کی خدمت کی، لیکن مجھے نہیں معلوم کہ آپ نے کبھی میرے کسی ایسے کام پر جو میں نے کیا ہو یہ کہا ہو کہ تم نے ایسا اور ایسا کیوں کیا؟ اور نہ ہی کسی ایسے کام پر جسے میں نے نہ کیا ہو یہ کہا ہو کہ تم نے ایسا اور ایسا کیوں نہیں کیا؟ ۔","حسن",{"u2":"سیدنا انس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں میں سے سب بڑھ کر عمدہ اخلاق کے مالک تھے۔ آپ صلی اللہ علیہ وسلم نے ایک روز مجھے کسی کام کے لیے بھیجا ‘ میں نے کہا: اللہ کی قسم! میں نہیں جاؤں گا ‘ حالانکہ میرے دل میں تھا کہ اللہ کے نبی صلی اللہ علیہ وسلم نے جو بھی فرمایا ہے میں اس کے لیے جاؤں گا۔ کہتے ہیں: پس میں نکلا حتیٰ کہ بچوں کے پاس سے میرا گزر ہوا جو بازار میں کھیل رہے تھے۔ تو اچانک (کیا دیکھتا ہوں کہ) رسول اللہ صلی اللہ علیہ وسلم مجھے میرے پیچھے سے میری گدی پکڑے ہوئے تھے۔ میں نے آپ صلی اللہ علیہ وسلم کی طرف دیکھا تو آپ صلی اللہ علیہ وسلم ہنس رہے تھے۔ فرمایا ” انیس! ادھر جاؤ جہاں کا میں نے تمہیں کہا ہے۔ “ میں نے عرض کیا: ہاں اے اللہ کے رسول! جا رہا ہوں۔ سیدنا انس رضی اللہ عنہ نے کہا: قسم اللہ کی! میں نے سات سال آپ صلی اللہ علیہ وسلم کی خدمت کی ہے یا نو سال، مجھے نہیں معلوم کہ آپ نے مجھے کسی کام پر جو میں نے کیا ہو، کبھی یوں کہا ہو: ” تو نے ایسے کیوں کیا؟ “ یا کوئی کام جو میں نے چھوڑ دیا ہو، تو کہا ہو کہ ” ایسے ایسے کیوں نہیں کیا؟ “","f2":"رسول اللہ صلی اللہ علیہ وسلم حلم اور اخلاقِ حسنہ کی شاندار تصویر تھے اور بچوں کی نفسیات سے خوب آگاہ تھے۔نیز حضرت انس رضی اللہ تعالی عنہ نے بھی کبھی نبی اکرم صلی اللہ علیہ وسلم کو ایسا موقع نہیں دیا تھا جو آپ کے ذوق اور مزاج کے لیئے گرانی کا باعث بنتا۔"}],[4774,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے دس سال مدینہ میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت کی، میں ایک کمسن بچہ تھا، میرا ہر کام اس طرح نہ ہوتا تھا جیسے میرے آقا کی مرضی ہوتی تھی، لیکن آپ صلی اللہ علیہ وسلم نے کبھی بھی مجھ سے اف تک نہیں کہا اور نہ مجھ سے یہ کہا: تم نے ایسا کیوں کیا؟ یا تم نے ایسا کیوں نہیں کیا؟ ۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہمیں نے نبی کریم صلی اللہ علیہ وسلم کی مدینہ منورہ میں دس سال تک خدمت کی جبکہ میں ایک نوخیز لڑکا تھا۔ میرے سب کام اس معیار کے نہیں ہوتے تھے جیسے میرے حبیب صلی اللہ علیہ وسلم کی خواہش ہوتی تھی۔ (اس کے باوجود) آپ صلی اللہ علیہ وسلم نے مجھے کبھی اف تک نہیں کہا اور نہ یوں کہا: تو نے یہ کیوں کیا؟ اور اس طرح کیوں نہیں کیا؟","f2":"بعض نوخیز بچے ایسے ہوتے ہیں کہ اگر ان کو انکے کاموں میں حوصلہ اور اعتماد دیا جائے تو اس طرح سے انکی عملی زندگی بڑ ی کامیاب رہتی ہے۔تاہم سارے بچے اس طرح ذہین ہی ہوتے ہیں نہ زیادہ سمجھدار ہی انکو آداب سکھانے کے لیئے کچھ نہ کچھ سرزنش بھی کرنی پڑتی ہے۔حضرت انس رضی اللہ تعالی عنہ اول الذکر قسم کے بچے تھے وہ بچہ ہونے کے با وجود رسول اللہ صلی اللہ علیہ وسلم کو شکائیت کا مو قع نہی دیتے تھے اور نبی اکرم صلی اللہ علیہ وسلم تو تھے سراپا شفقت اور مجسمِ رحمت۔آپ نے حضرت انس رضی اللہ تعالی عنہ سےہمیشہ شفقت و پیار والا معاملہ ہی کیا۔"}],[4775,"ہلال بیان کرتے ہیں کہ ابوہریرہ رضی اللہ عنہ نے ہم سے بیان کرتے ہوئے کہا: نبی اکرم صلی اللہ علیہ وسلم ہمارے ساتھ مجلس میں بیٹھا کرتے تھے، آپ صلی اللہ علیہ وسلم ہم سے باتیں کرتے تھے تو جب آپ اٹھ کھڑے ہوتے تو ہم بھی اٹھ کھڑے ہوتے یہاں تک کہ ہم آپ صلی اللہ علیہ وسلم کو دیکھتے کہ آپ اپنی ازواج میں سے کسی کے گھر میں داخل ہو گئے ہیں، چنانچہ آپ صلی اللہ علیہ وسلم نے ہم سے ایک دن گفتگو کی، تو جب آپ صلی اللہ علیہ وسلم کھڑے ہوئے ہم بھی کھڑے ہو گئے، تو ہم نے ایک اعرابی کو دیکھا کہ اس نے آپ صلی اللہ علیہ وسلم کو پکڑ کر اور آپ کے اوپر چادر ڈال کر آپ کو کھینچ رہا ہے، آپ صلی اللہ علیہ وسلم کی گردن لال ہو گئی ہے، ابوہریرہ کہتے ہیں: وہ ایک کھردری چادر تھی، آپ صلی اللہ علیہ وسلم اس کی طرف مڑے تو اعرابی نے آپ سے کہا: میرے لیے میرے ان دونوں اونٹوں کو (غلے سے) لاد دو، اس لیے کہ نہ تو تم اپنے مال سے لادو گے اور نہ اپنے باپ کے مال سے تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"نہیں ۱؎ اور میں اللہ سے مغفرت طلب کرتا ہوں، نہیں اور میں اللہ سے مغفرت طلب کرتا ہوں، نہیں اور میں اللہ سے مغفرت طلب کرتا ہوں ۲؎ میں تمہیں نہیں دوں گا یہاں تک کہ تم مجھے اپنے اس کھینچنے کا بدلہ نہ دے دو\" لیکن اعرابی ہر بار یہی کہتا رہا: اللہ کی قسم میں تمہیں اس کا بدلہ نہ دوں گا۔ پھر راوی نے حدیث ذکر کی، اور کہا: آپ صلی اللہ علیہ وسلم نے ایک شخص کو بلایا اور اس سے فرمایا: \"اس کے لیے اس کے دونوں اونٹوں پر لاد دو: ایک اونٹ پر جو اور دوسرے پر کھجور\" پھر آپ صلی اللہ علیہ وسلم ہماری طرف متوجہ ہوئے اور فرمایا: \"واپس جاؤ اللہ کی برکت پر بھروسہ کر کے ۳؎\" ۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ جو میں تمہیں دوں گا وہ یقیناً میرا اپنا مال نہیں ہو گا۔ ۲؎ : اگر معاملہ اس طرح نہ ہو۔ ۳؎ : اس حدیث میں نبی اکرم صلی اللہ علیہ وسلم کے کمال اخلاق و حلم کا بیان ہے۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے ہم سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے ساتھ مسجد میں بیٹھا کرتے تھے اور باتیں کرتے رہتے تھے۔ جب آپ صلی اللہ علیہ وسلم اٹھتے تو ہم بھی کھڑے ہو جاتے ‘ حتیٰ کہ ہم دیکھتے کہ آپ صلی اللہ علیہ وسلم اپنی کسی اہلیہ کے گھر میں داخل ہو گئے ہیں۔ چنانچہ آپ صلی اللہ علیہ وسلم ایک دن ہمارے ساتھ باتیں کرتے رہے جب آپ صلی اللہ علیہ وسلم اٹھے تو ہم بھی اٹھ کھڑے ہوئے۔ پھر ہم نے دیکھا کہ ایک بدوی نے آپ صلی اللہ علیہ وسلم کو جا لیا اور آپ صلی اللہ علیہ وسلم کی چادر پکڑ کے کھینچنے لگا حتیٰ کہ آپ صلی اللہ علیہ وسلم کی گردن سرخ ہو گئی۔ سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ چادر بھی بڑی کھردری تھی۔ آپ صلی اللہ علیہ وسلم اس کی طرف متوجہ ہوئے تو اس اعرابی نے آپ صلی اللہ علیہ وسلم سے کہا: مجھے میرے یہ دو اونٹ لا دیں۔ بلاشبہ آپ مجھے کوئی اپنے ذاتی مال سے نہیں دیں گے اور نہ اپنے باپ کے مال سے دیں گے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ” نہیں ‘ میں اللہ سے استغفار کرتا ہوں۔ نہیں ‘ میں اللہ سے استغفار کرتا ہوں۔ نہیں ‘ میں اللہ سے استغفار کرتا ہوں اور میں تجھے اس وقت تک نہیں دے سکتا جب تک مجھے چھوڑ نہ دو جو یہ تم نے مجھے پکڑا ہوا ہے۔ “ اور وہ بدوی ہر بار آپ صلی اللہ علیہ وسلم سے یہی کہتا تھا: اللہ کی قسم! میں تمہیں نہیں چھوڑوں گا۔ اور راوی نے پوری حدیث ذکر کی۔ پھر آپ صلی اللہ علیہ وسلم نے ایک شخص کو بلایا اور اس سے کہا: ” اس کو اس کے یہ دونوں اونٹ لا دو ‘ ایک پر جو اور ایک پر کھجور۔ “ پھر آپ صلی اللہ علیہ وسلم ہماری طرف متوجہ ہوئے اور فرمایا: ” تم لوگ جاؤ ‘ تم پر اللہ کی برکتیں ہوں۔ “","f2":"یہ روایت سندَا ضعیف ہے۔ مگر حضرت انس رضی اللہ تعالی عنہ سے صحییحن میں اس سے قریب قریب ایک دوسرا واقع روایت کیا گیا ہے۔ (دیکھیئے صحیح البخاری، الادب، باب التبسم والضحک، حدیث6088) اس قسم کے واقعات میں رسول اللہ صلی اللہ علیہ وسلم کے متحمل مزاج ہونے اور درشت طبیعت لوگوں سے بھی نرم انداز میں معاملہ کرنے کا بیان ہے۔"}],[4776,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"راست روی، خوش خلقی اور میانہ روی نبوت کا پچیسواں حصہ ہے ۱؎\"۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ یہ خصلتیں اللہ تعالی نے انبیاء علیہم السلام کو عطا کی ہیں، لہٰذا انہیں اپنانے میں ان کی پیروی کرو، یہ معنی نہیں کہ نبوت کوئی ذو اجزاء چیز ہے، اور جس میں یہ خصلتیں پائی جائیں گی اس کے اندر نبوّت کے کچھ حصے پائے جائیں گے کیونکہ نبوت کوئی کسبی چیز نہیں ہے بلکہ یہ اللہ کی طرف سے ایک اعزاز ہے وہ اپنے بندوں میں سے جسے چاہتا ہے اس اعزاز سے نوازتا ہے۔","حسن",{"u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” نیک چلن ‘ عمدہ کردار اور میانہ روی نبوت کا پچیسواں حصہ ہے۔ “","f2":"یہ وہ عظیم اور اہم عمل ہیں جن سے انبیاء علیہ السلام موصوف رہے ہیں اور اپنی امتوں کو انکے اختیار کرنے کی دعوت دیتے رہے ہیں۔"}],[4777,"معاذ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنا غصہ پی لیا حالانکہ وہ اسے نافذ کرنے پر قادر تھا تو قیامت کے دن اللہ تعالی اسے سب لوگوں کے سامنے بلائے گا یہاں تک کہ اسے اللہ تعالی اختیار دے گا کہ وہ بڑی آنکھ والی حوروں میں سے جسے چاہے چن لے\"۔","حسن",{"u2":"جناب سہل بن معاذ اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص غصہ پی جائے جبکہ وہ اس پر عمل درآمد کی قدرت رکھتا ہو تو ا اللہ اسے قیامت کے دن برسر مخلوق بلائے گا اور اسے اختیار دے گا کہ جنت کی حورعین میں سے جسے چاہے منتخب کر لے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ سند کے راوی ابو مرحوم کا نام عبدالرحمٰن بن میمون ہے۔","f2":"قرآن مجید میں اللہ تعالی نے()(آلِ عمران:134) کے الفاظ سے غصہ پی جانے کو اہلِ ایمان کی اہم صفات میں شمار کیا ہے۔"}],[4778,"نبی اکرم صلی اللہ علیہ وسلم کے اصحاب کے فرزندوں میں سے ایک شخص اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح فرمایا، آپ نے فرمایا: \"اللہ اسے امن اور ایمان سے بھر دے گا اور اس میں یہ واقعہ مذکور نہیں کہ اللہ اسے بلائے گا، البتہ اتنا اضافہ ہے، اور جو خوب (تواضع و فروتنی میں) صورتی کا لباس پہننا ترک کر دے، حالانکہ وہ اس کی قدرت رکھتا ہو، تو اللہ تعالی اسے عزت کا جوڑا پہنائے گا، اور جو اللہ کی خاطر شادی کرائے گا ۱؎ تو اللہ اسے بادشاہت کا تاج پہنائے گا\"۔\n§وضاحت\n۱؎ : «من زوج لله» میں مفعول محذوف ہے، اصل عبارت یوں ہے «من زوج من يحتاج إلى الزواج» یعنی جو کسی ایسے شخص کی شادی کرائے گا جو شادی کا ضرورت مند ہو، بعض لوگوں نے کہا ہے کہ اس کا مفعول «كريمته» ہے یعنی جو اپنی بیٹی کی شادی کرے گا، اور بعض لوگوں نے کہا ہے کہ «من زوَّج» کے معنی «من أعطى لله اثنين من الأشياء» کے ہیں، یعنی جس نے اللہ کی خاطر کسی کو دو چیز دی۔","ضعیف",{"u2":"اصحاب نبی کریم صلی اللہ علیہ وسلم میں سے کسی کے بیٹے نے اپنے والد سے بیان کیا کہرسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اور مندرجہ بالا حدیث کی مانند ذکر کیا کہا ” ا اللہ اسے امن اور ایمان سے بھر دے گا۔ “ مگر اس میں یہ نہیں ” ا اللہ اسے بلائے گا۔ “ مزید کہا: ” جس شخص نے زینت اور جمال والا لباس ترک کیا حالانکہ وہ اس کی استطاعت رکھتا ہو۔ “ بشر بن منصور نے کہا میرا خیال ہے کہ آپ نے فرمایا ” وہ اس نے تواضع کی وجہ سے چھوڑا ہو تو ا اللہ اسے عزت اور کرامت کا جوڑا پہنائے گا۔ اور جس نے ا اللہ کی رضا کے لیے نکاح کر دیا ہو تو ا اللہ اسے تاج شاہی پہنائے گا۔ “"}],[4779,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ پہلوان کس کو شمار کرتے ہو؟\" لوگوں نے عرض کیا: اس کو جسے لوگ پچھاڑ نہ سکیں، آپ نے فرمایا: \"نہیں، بلکہ پہلوان وہ ہے جو غصے کے وقت اپنے نفس پر قابو رکھتا ہو\"۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم لوگ زبردست پہلوان (بہت زیادہ پچھاڑنے والا) کسے کہتے ہو؟ “ صحابہ نے کہا: جسے لوگ پچھاڑ نہ سکیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں پہلوان وہ ہے جو غصے کی حالت میں اپنے آپ کو قابو میں رکھے۔ “"}],[4780,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ دو شخصوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس گالی گلوج کی تو ان میں سے ایک کو بہت شدید غصہ آیا یہاں تک کہ مجھے ایسا محسوس ہونے لگا کہ مارے غصے کے اس کی ناک پھٹ جائے گی، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مجھے ایک ایسا کلمہ معلوم ہے کہ اگر وہ اسے کہہ دے تو جو غصہ وہ اپنے اندر پا رہا ہے دور ہو جائے گا\" عرض کیا: کیا ہے وہ؟ اللہ کے رسول! آپ نے فرمایا: \"وہ کہے «اللهم إني أعوذ بك من الشيطان الرجيم» \"اے اللہ! میں شیطان مردود سے تیری پناہ مانگتا ہوں\" تو معاذ اسے اس کا حکم دینے لگے، لیکن اس نے انکار کیا، اور لڑنے لگا، اس کا غصہ مزید شدید ہوتا چلا گیا۔","ضعیف",{"u2":"سیدنا معاذ بن جبل رضی اللہ عنہ کا بیان ہے کہ دو آدمی نبی کریم صلی اللہ علیہ وسلم کے سامنے ایک دوسرے کو گالیاں دینے لگے۔ ان میں ایک اس قدر غضبناک ہو گیا کہ میں نے سمجھا کہ انتہائی غصے سے اس کی ناک ہی چر جائے گی۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ مجھے ایک کلمہ معلوم ہے ‘ اگر یہ کہہ لے تو اس کا یہ غصہ دور ہو جائے۔ “ (معاذ رضی اللہ عنہ نے) کہا: اے ا اللہ کے رسول! وہ کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یوں کہہ لے «اللهم إني أعوذ بك من الشيطان الرجيم» ” اے ا اللہ! میں شیطان مردود کے شر سے تیری پناہ چاہتا ہوں۔ “ چنانچہ سیدنا معاذ رضی اللہ عنہ اس شخص سے کہنے لگے کہ یہ کلمہ پڑھ لے مگر اس نے انکار کر دیا بلکہ اور لڑنے لگا اور غصے ہونے لگا۔"}],[4781,"سلیمان بن صرد کہتے ہیں کہ دو شخصوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس گالی گلوج کی تو ان میں سے ایک کی آنکھیں سرخ ہو گئیں، اور رگیں پھول گئیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے ایک ایسا کلمہ معلوم ہے کہ اگر وہ اسے کہہ دے تو جو غصہ وہ اپنے اندر پا رہا ہے دور ہو جائے گا، وہ کلمہ «أعوذ بالله من الشيطان الرجيم» ، تو اس آدمی نے کہا: کیا آپ یہ سمجھتے ہیں کہ مجھے جنون ہے ۱؎۔\n§وضاحت\n۱؎ : غالباً اس نے یہ سمجھا کہ «أعوذ بالله من الشيطان الرجيم» پڑھنا جنون ہی کے ساتھ مخصوص ہے، یا ہو سکتا ہے کہ وہ کوئی منافق یا غیر مہذب اور غیر مہذب بدوی رہا ہو۔","صحیح",{"u2":"سیدنا سلیمان بن صرد رضی اللہ عنہ سے روایت ہے کہ دو آدمی نبی کریم صلی اللہ علیہ وسلم کے سامنے ایک دوسرے کو برا بھلا کہنے لگے حتیٰ کہ ایک کی آنکھیں سرخ ہو گئیں اور گلے کی رگیں پھول گئیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مجھے ایک کلمہ معلوم ہے ‘ اگر یہ شخص وہ کلمہ کہہ لے تو اس سے یہ کیفیت دور ہو جائے گی۔ (اور وہ کلمہ یہ ہے) «أعوذ بالله من الشيطان الرجيم» ” میں شیطان مردود کے شر سے ا اللہ کی پناہ میں آتا ہوں۔ “ مگر وہ آدمی کہنے لگا: کیا تم سمجھتے ہو کہ میں مجنون ہوں؟","f2":"شرعی غیرت کے علاوہ انتہائی غصہ شیطانی اثر ہوتا ہے اور اسکا علاج تعوذ ہے۔بشرطیکہ بندہ اس حقیقت کا ادراک رکھتا ہو۔\n2) غیر شرعی غصے کی ایک حقیقت یہ بھی ہے کہ انسان حق قبول نہیں کرتا۔"}],[4782,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا: \"جب تم میں سے کسی کو غصہ آئے اور وہ کھڑا ہو تو چاہیئے کہ بیٹھ جائے، اب اگر اس کا غصہ رفع ہو جائے (تو بہتر ہے) ورنہ پھر لیٹ جائے\"۔","صحیح",{"u2":"سیدنا ابوذر غفاری رضی اللہ عنہ سے روایت ہے، کہا تحقیق رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا ” جب تم میں سے کسی کو غصہ آئے اور وہ کھڑا ہوا ہو ‘ تو بیٹھ جائے ‘ اسی طرح اگر اس کا غصہ فرد ہو جائے (تو بہتر) ورنہ لیٹ جائے۔ “"}],[4783,"بکر سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ابوذر کو بھیجا آگے یہی حدیث مروی ہے۔ ابوداؤد کہتے ہیں: دونوں حدیثوں میں یہ زیادہ صحیح ہے۔","صحیح",{"u2":"جناب بکر (بکر بن عبداللہ) سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سیدنا ابوذر رضی اللہ عنہ کو (کسی کام سے) بھیجا اور یہ حدیث بیان کی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ حدیث (باوجود یہ کہ مرسل ہے) صحیح تر ہے۔","f2":"غصہ آجانے کی صورت میں آدمی کو چاہیئے کہ ہر طرح سے پر سکون رہنے کی کوشش کرےاور اپنی ہیت کو بدل لے۔اور وضو کرنا بہترین حل ہےجیسے کہ درج ذیل حدیث میں آرہا ہے۔"}],[4784,"ابووائل قاص کہتے ہیں کہ ہم عروہ بن محمد بن سعدی کے پاس داخل ہوئے، ان سے ایک شخص نے گفتگو کی تو انہیں غصہ کر دیا، وہ کھڑے ہوئے اور وضو کیا، پھر لوٹے اور وہ وضو کئے ہوئے تھے، اور بولے: میرے والد نے مجھ سے بیان کیا وہ میرے دادا عطیہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"غصہ شیطان کے سبب ہوتا ہے، اور شیطان آگ سے پیدا کیا گیا ہے، اور آگ پانی سے بجھائی جاتی ہے، لہٰذا تم میں سے کسی کو جب غصہ آئے تو وضو کر لے\"۔","ضعیف",{"u2":"ابووائل القاص (واعظ) کہتے ہیں کہ ہم جناب عروہ بن محمد سعدی رضی اللہ عنہ کے ہاں گئے۔ ایک آدمی نے ان سے کوئی بات کی تو انہیں غصہ آ گیا ‘ تو وہ اٹھے اور وضو کیا پھر (وضو کر کے) واپس آئے اور بیان کیا کہ مجھے میرے والد نے میرے دادا عطیہ رضی اللہ عنہ سے روایت کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ غصہ شیطان کی طرف سے ہوتا ہے اور شیطان کو آگ سے پیدا کیا گیا ہے اور آگ کو پانی سے بجھایا جاتا ہے۔ سو جب تم میں سے کسی کو غصہ آ جائے تو اسے چاہیئے کہ وہ وضو کر لے۔ “"}],[4785,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو دو کاموں میں جب بھی اختیار کا حکم دیا گیا تو آپ نے اس میں آسان تر کو منتخب کیا، جب تک کہ وہ گناہ نہ ہو، اور اگر وہ گناہ ہوتا تو آپ لوگوں میں سب سے زیادہ اس سے دور رہنے والے ہوتے، اور رسول اللہ صلی اللہ علیہ وسلم نے اپنی خاطر کبھی انتقام نہیں لیا، اس صورت کے علاوہ کہ اللہ تعالی کی حرمت کو پامال کیا جاتا ہو تو آپ اس صورت میں اللہ تعالی کے لیے اس سے بدلہ لیتے ۱؎۔\n§وضاحت\n۱؎ : مثلاً زنا میں رجم کرتے یا کوڑے لگاتے اور چوری میں ہاتھ کاٹتے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے، وہ بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو جب بھی دو کاموں میں سے کسی کا اختیار دیا گیا تو آپ صلی اللہ علیہ وسلم نے ہمیشہ آسان ہی کو اختیار فرمایا بشرطیکہ وہ گناہ نہ ہوتا۔ اگر اس میں گناہ ہوتا تو آپ صلی اللہ علیہ وسلم سب سے بڑھ کر اس سے دور ہونے والے ہوتے تھے۔ اور رسول اللہ صلی اللہ علیہ وسلم نے کبھی اپنی ذات کے لیے انتقام نہیں لیا ‘ سوائے اس کے کہ ا اللہ کی حرمتوں کی پامالی ہوتی ہو ‘ تو اس میں ا اللہ کے لیے انتقام لیتے تھے۔","f2":"معاملات دین کے ہوں یا دنیا کے بندے کو چاہیئے کہ آسان جانب اختیار کرےاور پھر اخلاص اور پابندی کے ساتھ اس پر عمل پیرا رہے۔ یہ اس سے زیادہ افضل ہے کہ پُر مُشقت عمل ایک دو بار کر کےچھوڑ دیا جائے۔\n2) انسان اپنی ذات کے لیئے انتقام سے بالا تر تو اس میں بری فضیلت ہے۔\n3) اللہ کی حرمتوں کی پامالی پر اللہ کے لیئے غضبناک ہونا ایمان کا حصہ ہے۔"}],[4786,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نہ کبھی کسی خادم کو مارا، اور نہ کبھی کسی عورت کو۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کبھی کسی خادم یا عورت کو نہیں مارا۔","f2":"افضلیت اس میں ہے کی اپنے زیردست کو جسمانی سزا نہ دی جائے اور جہاں تک ہو سکے زبانی فہمائش سے کام لیا جائے۔ تاہم اگر کوئی زبانی نصیحت یا روئیے کا نہ سمجھتا ہو تو مناسب سزا دینا جائز ہے۔ جیسے بد خوبیوں کے سلسلے میں قرآن مجید میں ارشاد الٰہی ہے اور جنکی بد خوئی کا تمھیں اندیشہ ہو تو انھیں سمجھاؤ بستروں سے علیحدہ کردو اور مارو۔"}],[4787,"عبداللہ بن زبیر رضی اللہ عنہما سے اللہ کے فرمان «خذ العفو» \"عفو کو اختیار کرو\" کی تفسیر کے سلسلے میں روایت ہے، وہ کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم کو حکم دیا گیا کہ وہ لوگوں کے اخلاق میں سے عفو کو اختیار کریں۔","صحیح",{"u2":"سیدنا عبداللہ بن زبیر رضی اللہ عنہ سے روایت ہے کہ ا اللہ کے فرمان «خذ العفو» ” معاف کرنا اپنائیے “ کی تفسیر میں انہوں نے بیان کیا کہ ا اللہ کے نبی صلی اللہ علیہ وسلم کو حکم دیا گیا تھا کہ لوگوں کی عادات و معاملات میں ان کے ساتھ معافی کا رویہ اختیار کریں۔","f2":"معافی اور درگزرانتہائی عزیمت کا عمل ہے کہ انسان دل سے دوسرے کو معاف کر دے اور معاملے کو بھول جائے۔ کمزور ایمان و عمل کے آدمی سے ایسا ہو نا بہت نادر ہوتا ہے اس لیئے اللہ نے اپنے نبی صلی اللہ علیہ وسلم کو اسکا خاص حکم ارشاد فرمایا۔"}],[4788,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو جب کسی شخص کے بارے میں کوئی بری بات پہنچتی تو آپ یوں نہ فرماتے: \"فلاں کو کیا ہوا کہ وہ ایسا کہتا ہے؟\" بلکہ یوں فرماتے: \"لوگوں کو کیا ہو گیا ہے جو ایسا اور ایسا کہتے ہیں\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم کو جب کسی کے متعلق کوئی (نامناسب) خبر ملتی تو یوں نہ کہتے: فلاں کو کیا ہوا ہے کہ یوں کہتا ہے یا کرتا ہے؟ بلکہ یوں فرماتے ” لوگوں کو کیا ہوا ہے کہ ایسے ایسے کہتے ہیں یا کرتے ہیں۔ “","f2":"نصیحت کا پہلا اور عمدہ ترین ادب یہی ہے کہ اشارے اور کنائے سے بات ہو اور ایسے ہی خطیب کو بھی کسی فرد کی بصراحت نشاندہی سے بچنا چاہیئے۔"}],[4789,"انس رضی اللہ عنہ کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اس پر زردی کا نشان تھا، رسول اللہ صلی اللہ علیہ وسلم کا حال یہ تھا کہ آپ بہت کم کسی ایسے شخص کے روبرو ہوتے، جس کے چہرے پر کوئی ایسی چیز ہوتی جسے آپ ناپسند کرتے تو جب وہ نکل گیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"کاش تم لوگ اس سے کہتے کہ وہ اسے اپنے سے دھو ڈالے\"۔ ابوداؤد کہتے ہیں: سلم علوی (یعنی اولاد علی میں سے) نہیں تھا بلکہ وہ ستارے دیکھا کرتا تھا ۱؎ اور اس نے عدی بن ارطاۃ کے پاس چاند دیکھنے کی گواہی دی تو انہوں نے اس کی گواہی قبول نہیں کی۔\n§وضاحت\n۱؎ : یعنی علو (بلندی) کی طرف دیکھتا تھا کیونکہ ستارے بلندی ہی میں ہوتے ہیں، اسی وجہ سے علو کی طرف نسبت کر کے اسے علوی کہا جاتا تھا۔","ضعیف",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا جبکہ اس پر زرد رنگ کا کچھ نشان تھا۔ اور رسول اللہ صلی اللہ علیہ وسلم کسی شخص کو اس کے منہ پر بہت کم ایسی بات کہتے تھے جو اس کو ناگوار ہو۔ (یعنی اس کی غلطی پر اس کو نہ ٹوکتے تھے۔) جب وہ چلا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر تم ہی اس کو کہہ دو کہ اس (رنگ) کو دھو ڈالے (تو بہتر ہو)۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس کا راوی ” سلم علوی “ حقیقت میں اولاد علی میں سے نہیں (یہ دوسرا شخص ہے۔ اس کا نام سلم بن قیس ہے اور یہ بصری ہے چونکہ ستارے اوپر ہوتے ہیں) ستاروں پر نظر رکھنے کی وجہ سے اسے علوی کہا جانے لگا۔ اس نے سیدنا عدی بن ارطاۃ کے سامنے چاند دیکھنے کی گواہی دی تو انہوں نے قبول نہ کی۔"}],[4790,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن بھولا بھالا اور شریف ہوتا ہے اور فاجر فسادی اور کمینہ ہوتا ہے\"۔","حسن",{"u2":"نصر بن علی اور محمد بن متوکل عسقلانی دونوں سیدنا ابوہریرہ رضی اللہ عنہ سے مرفوعاً روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مومن بھولا بھالا اور سخی ہوتا ہے اور فاجر آدمی فریبی اور بخیل ہوتا ہے۔ “","f2":"بعض محقیقین نے اس روایت کو حسن قرار دیا ہے۔"}],[4791,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے (اندر آنے کی) اجازت طلب کی تو آپ نے فرمایا: \"اپنے خاندان کا لڑکا یا خاندان کا آدمی برا شخص ہے\" پھر فرمایا: اسے اجازت دے دو، جب وہ اندر آ گیا تو آپ نے اس سے نرمی سے گفتگو کی، اس پر عائشہ رضی اللہ عنہا نے کہا: اللہ کے رسول! آپ نے اس سے نرم گفتگو کی حالانکہ آپ اس کے متعلق ایسی ایسی باتیں کہہ چکے تھے، آپ نے فرمایا: \"لوگوں میں سب سے برا شخص اللہ کے نزدیک قیامت کے دن وہ ہو گا جس سے لوگوں نے اس کی فحش کلامی سے بچنے کے لیے علیحدگی اختیار کر لی ہو یا اسے چھوڑ دیا ہو\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم کے ہاں آنے کی اجازت طلب کی تو آپ صلی اللہ علیہ وسلم نے فرمایا ” کنبے کا بہت برا آدمی ہے۔ “ پھر فرمایا ” اسے اجازت دے دو (بلا لو)۔ “ جب وہ اندر آ گیا تو آپ صلی اللہ علیہ وسلم نے اس کے ساتھ نہایت نرمی کے ساتھ باتیں کیں۔ سیدہ عائشہ رضی اللہ عنہا ا (کہتی ہیں میں) نے کہا: اے ا اللہ کے رسول! آپ نے اس کے ساتھ بڑی نرمی کے ساتھ باتیں کی ہیں ‘ حالانکہ آپ نے اس کے متعلق ایسے ایسے فرمایا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” قیامت کے دن ا اللہ کے ہاں سب سے برا وہ آدمی ہو گا جسے لوگوں نے اس کی بدکلامی کی وجہ سے چھوڑ دیا ہو۔ “"}],[4792,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کے پاس اندر آنے کی اجازت مانگی تو آپ نے فرمایا: \"اپنے کنبے کا برا شخص ہے\" جب وہ اندر آ گیا، تو رسول اللہ صلی اللہ علیہ وسلم اس سے کشادہ دلی سے ملے اور اس سے باتیں کیں، جب وہ نکل کر چلا گیا تو میں نے عرض کیا: اللہ کے رسول! جب اس نے اجازت طلب کی تو آپ نے فرمایا: \"اپنے کنبے کا برا شخص ہے، اور جب وہ اندر آ گیا تو آپ اس سے کشادہ دلی سے ملے\" آپ نے فرمایا: \"عائشہ! اللہ تعالی کو فحش گو اور منہ پھٹ شخص پسند نہیں\"۔","حسن صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ ایک شخص نے نبی کریم صلی اللہ علیہ وسلم کے ہاں آنے کی اجازت چاہی تو آپ صلی اللہ علیہ وسلم نے فرمایا ” کنبے کا بہت برا آدمی ہے۔ “ پھر جب وہ آپ کے پاس آ گیا تو آپ نے اس کے ساتھ بڑی فراخدلی کے ساتھ باتیں کیں۔ جب وہ چلا گیا تو میں نے عرض کیا: اے ا اللہ کے رسول! جب اس نے اجازت مانگی تو آپ نے فرمایا ” کنبے کا برا آدمی ہے۔ “ جب وہ آ گیا تو آپ نے اس کے ساتھ بڑی فراخدلی کے ساتھ باتیں کی ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اے عائشہ! بلاشبہ ا اللہ تعالیٰ کسی بدگو ‘ تکلف سے بدگوئی کرنے والے سے محبت نہیں کرتا۔ “ امام ابوداؤد رضی اللہ عنہ سے نبی کریم صلی اللہ علیہ وسلم کے فرمان «بئس أخو العشيرة» کے معنی کی بابت سوال کیا گیا تو انہوں نے بیان کیا کہ یہ نبی کریم صلی اللہ علیہ وسلم کا خاصہ ہے۔","f2":"قاضی عیاض رحمہ اللہ کہتے ہیں کہ یہ شخص عیینہ بن حسن فزاری تھا جو رسول اللہ صلی اللہ علیہ وسلم کے دور میں مسلمان ہو اتھا مگر دورِ ابوبکر صدیق رضی اللہ عنہ میں مرتدین سے جا ملا اور پھر اسے قیدی بنا کر لایا گیا تھا۔\n2) علامہ قرطبی رحمہ اللہ فرماتے ہیں: اس حدیث سے معلوم ہوا کہ جو شخص علی الاعلان فسق و فجور و ظلم کا مرتکب ہو تا ہے یا کسی بدعت کا داعی ہے اس کی غیبت کرنا جائز ہے۔ اور اس قسن کے لوگوں کے شر سے بچنے کے لیئے ان کے ساتھ مدارات یعنی رواداری کا معاملہ کرنا مباح ہے بشرطیکہ دین میں مُدَا ہَنت لازم نہ آتی ہو۔\n3) مدارات اور مُدَا ہَنت میں فرق یہ ہے کہ دینی یا دنیاوی فوائد کے لیئے کسی کے ساتھ اپنے شخصی اور دنیاوی حقوق نظر انداز کر دینا مدارات ہوتی ہے۔ یہ ایک جائز امر ہے بلکہ نعض دفع مستحب ہے۔ جبکہ مُدَا ہَنت یہ ہے کہ انسان کسی کے ساتھ محض دنیاوی مفادات کے لیئے دین کے تقاضوں کو نظر انداز کر دے۔ یہ کسی صورت میں جائز نہیں۔"}],[4793,"اس سند سے بھی ام المؤمنین عائشہ رضی اللہ عنہا سے یہی واقعہ مروی ہے، وہ کہتی ہیں آپ نے یعنی نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\"اے عائشہ! لوگوں میں سب سے بدترین لوگ وہ ہیں وہ جن کا احترام و تکریم ان کی زبانوں سے بچنے کے لیے کیا جائے\"۔","ضعیف الإسناد",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے اس قصے میں بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اے عائشہ! بدترین ہیں وہ لوگ جن کی زبان کے شر سے بچنے کے لیے عزت کی جائے۔ “"}],[4794,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے کسی شخص کو نہیں دیکھا جس نے رسول اللہ صلی اللہ علیہ وسلم کے کان پر منہ رکھا ہو (کچھ کہنے کے لیے) تو آپ نے اپنا سر ہٹا لیا ہو یہاں تک کہ خود وہی شخص نہ ہٹا لے، اور میں نے ایسا بھی کوئی شخص نہیں دیکھا، جس نے آپ کا ہاتھ پکڑا ہو، تو آپ نے اس سے ہاتھ چھڑا لیا ہو، یہاں تک کہ خود اس شخص نے آپ کا ہاتھ نہ چھوڑ دیا ہو۔","حسن",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نہیں دیکھا کہ کسی نے نبی کریم صلی اللہ علیہ وسلم کے کان میں سرگوشی کرنا چاہی ہو تو آپ نے اس سے اپنا سر دور کر لیا ہو ‘ حتیٰ کہ وہ آدمی خود ہی آپ صلی اللہ علیہ وسلم سے اپنا سر دور کرتا تھا۔ اور میں نے نہیں دیکھا کہ کسی نے آپ کا ہاتھ پکڑا ہو ‘ تو آپ نے اس کا ہاتھ جھٹک دیا ہو ‘ حتیٰ کہ وہ از خود آپ کا ہاتھ چھوڑتا تھا۔","f2":"یہ روایت بعض محقیقین کے نزدیک سندَا ضعیف ہے اور بعض کے نزدیک حسن درجے کی ہے تفصیل کے لیئے دیکھئے: (الصحیحۃ حدیث:2485)"}],[4795,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم انصار کے ایک شخص پر سے گزرے، وہ اپنے بھائی کو شرم و حیاء کرنے پر ڈانٹ رہا تھا (اور سمجھا رہا تھا کہ زیادہ شرم کرنا اچھی بات نہیں) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے اس کے حال پر چھوڑ دو، شرم تو ایمان کا ایک حصہ ہے ۱؎\"۔\n§وضاحت\n۱؎ : اگرچہ وہ ایک طبعی خصلت ہے لیکن قانون شرع کے مطابق اس کا استعمال قصد اکتساب اور علم کا محتاج ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم ایک انصاری کے پاس سے گزرے جب کہ وہ اپنے بھائی کو حیاء کے بارے میں وعظ کر رہا تھا ‘ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسے چھوڑ دو۔ بلاشبہ حیاء ایمان سے ہے۔ “","f2":"حیا اگرچہ ایک طبعی اور فطری عمل ہوتاہے۔ مگر اس کے باوجود شرعی امور میں اور شرعی طور پر اسکے اظہار و استعمال کے لیئے قصد۔ کسب اور علم کی ضرورت ہوتی ہے۔ اسی وجہ سے اسے ایمان میں شمار کیا گیا ہے۔"}],[4796,"ابوقتادہ کہتے ہیں ہم عمران بن حصین رضی اللہ عنہما کے ساتھ تھے اور وہاں بشیر بن کعب بھی تھے تو عمران بن حصین رضی اللہ عنہما نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"حیاء خیر ہے پورا کا پورا، یا کہا حیاء پورا کا پورا خیر ہے،، اس پر بشیر بن کعب نے کہا: ہم بعض کتابوں میں لکھا پاتے ہیں کہ حیاء میں سے کچھ تو سکینہ اور وقار ہے، اور کچھ ضعف و ناتوانی، یہ سن کر عمران نے حدیث دہرائی تو بشیر نے پھر اپنی بات دہرائی تو عمران رضی اللہ عنہ غصہ ہو گئے یہاں تک کہ ان کی آنکھیں سرخ ہو گئیں، اور بولے: میں تم سے حدیث رسول اللہ بیان کر رہا ہوں، اور تم اپنی کتابوں کے بارے میں مجھ سے بیان کرتے ہو۔ ابوقتادہ کہتے ہیں: ہم نے کہا: اے ابونجید(عمران کی کنیت ہے) چھوڑئیے جانے دیجئیے۔","صحیح",{"u2":"جناب ابوقتادہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم سیدنا عمران بن حصین رضی اللہ عنہ کے ساتھ تھے جبکہ وہاں بشیر بن کعب بھی تھے (با کے ضمہ کے ساتھ) سیدنا عمران بن حصین نے حدیث بیان کی ‘ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” حیاء سراسر خیر ہے۔ “ بشیر بن کعب نے کہا: ہمیں کئی کتابوں میں ملتا ہے کہ بعض حیاء اطمینان اور وقار کی وجہ سے ہوتی ہے اور بعض حیاء کمزوری اور بزدلی کی وجہ سے ہوتی ہے۔ تو سیدنا عمران نے حدیث رسول دوبارہ دہرائی اور پھر بشیر نے بھی اپنی بات دہرا دی۔ راوی بیان کرتے ہیں کہ سیدنا عمران رضی اللہ عنہ اس قدر غصے میں آ گئے کہ ان کی آنکھیں سرخ ہو گئی اور بولے: میں تجھے رسول اللہ صلی اللہ علیہ وسلم کی حدیث سنا رہا ہوں اور تو مجھے اپنی کتابوں سے بتائے جا رہا ہے۔ ہم نے کہا: اے ابونجید! بس کیجئیے۔ بس کیجئیے۔ (اسے یہ تنبیہ کافی ہے)۔","f2":"ابو نجید حضرت عمران بن حصین رضی اللہ تعالی عنہ کی کنیت ہے۔\n2) حضرت محمد صلی اللہ علیہ وسلم کا فرمان اپنے ظاہر معانی میں جامع ومانع ہے لہذا کسی صاحبِ ایمان کو کسی طرح روا نہیں کہ آپ صلی اللہ علیہ وسلم کے فرمان کی بے مقصد تاویل کرے۔\n3) صاحبِ ایمان کو نصیحت کرتے ہوئے مناسب حد ت غصہ کرنا چاہیئے۔ حد سے زیادہ غصے کی وجہ سے بعض اوقات غلط نتائج نکلتے ہیں۔"}],[4797,"ابومسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سابقہ نبوتوں کے کلام میں سے باقی ماندہ چیزیں جو لوگوں کو ملی ہیں ان میں سے ایک یہ بھی ہے کہ جب تمہیں شرم نہ ہو تو جو چاہو کرو\"۔","صحیح",{"u2":"سیدنا ابومسعود رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” گزشتہ انبیاء کی تعلیمات میں سے جو بات لوگوں کے پاس محفوظ رہی ہے وہ یہی ہے کہ جب حیاء نہ رہے تو جو جی چاہے کر۔ “ امام ابوداؤد رضی اللہ عنہ سے پوچھا گیا: کیا قعنبی کے پاس شعبہ کے واسطے سے اس حدیث کے سوا کوئی اور حدیث بھی ہے؟ انہوں نے فرمایا نہیں۔","f2":"اس کلام میں وعید اور تہدید کے معنی یہ ہیں کہ حیا کرو ورنہ عتاب ہوگا۔ یا ترغیب کا مفہوم ہے کہ اقدام سے پہلے سوچ لو کہ اگر کام بے حیائی کا ہے تو باز رہو۔"}],[4798,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"مومن اپنی خوش اخلاقی سے روزے دار اور رات کو قیام کرنے والے کا درجہ پا لیتا ہے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” بلاشبہ مومن اپنے حسن اخلاق (عمدہ عادات) کی بنا پر روزہ دار ‘ شب زندہ دار کا درجہ حاصل کر لیتا ہے۔ “","f2":"حسنِ خلق سے مراد وہی عادات ہیں جن کا اعتبار شریعت اسلامیہ نے کیا ہے اور عرف میں انکو عمدہ سمجھا جاتا ہے۔ اس میں حقوق اللہ اور حقوق العباد دونوں کا لحاظ رکھنا ضروری ہے۔ ایسا حسنِ خلق جو حقوق اللہ کی ادائیگی سے عاری ہو معتبر نہیں۔یا اگر کو ئی حقوق اللہ تو ادا کرتا ہو مگر حقوق العبا دمیں افراط و تفریط کا شکار ہو تو بھی کسی طرح مقبول و ممدوح نہیں۔"}],[4799,"ابوالدرداء رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"(قیامت کے دن) میزان میں خوش خلقی سے زیادہ بھاری کوئی چیز نہ ہو گی\"۔","صحیح",{"u2":"سیدنا ابو درداء رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” میزان میں حسن خلق سے بڑھ کر اور کئی چیز بھاری نہیں ہو گی۔ “ ابوولید طیالسی کہتے ہیں (قاسم بن ابی بزہ کی سند میں تصریح ہے کہ) میں نے عطاء کیخارانی سے سنا ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یہ عطاء بن یعقوب ہیں اور ابراہیم بن نافع کے ماموں ہیں۔ ان کی نسبت کیخارانی اور کوخارانی ‘ دونوں طرح بیان کی جاتی ہے۔"}],[4800,"ابوامامہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں اس شخص کے لیے جنت کے اندر ایک گھر کا ضامن ہوں جو لڑائی جھگڑا ترک کر دے، اگرچہ وہ حق پر ہو، اور جنت کے بیچوں بیچ ایک گھر کا اس شخص کے لیے جو جھوٹ بولنا چھوڑ دے اگرچہ وہ ہنسی مذاق ہی میں ہو، اور جنت کی بلندی میں ایک گھر کا اس شخص کے لیے جو خوش خلق ہو\"۔","حسن",{"u2":"سیدنا ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میں ذمہ دار ہوں ایک محل کا ‘ جنت کی ایک جانب میں ‘ اس شخص کے لیے جو جھگڑا چھوڑ دے ‘ اگرچہ حق پر ہو۔ اور ایک محل کا ‘ جنت کے درمیان میں ‘ اس شخص کے لیے جو جھوٹ چھوڑ دے ‘ اگرچہ مزاح ہی میں ہو ‘ اور جنت کی اعلی منازل میں ایک محل کا ‘ اس شخص کے لیے جو اپنے اخلاق کو عمدہ بنا لے۔ “","f2":"حق پر ہوتے ہو ئے جھگڑا چھوڑ دینا انتہائی عزیمت کا عمل ہے اور اس کا اجر جنت میں شاندار محل کی صورت حاصل ہو گا۔\n2) مومن کے لیئے جھوٹ بولنا کسی طرح روا نہیں۔ سوائے اس کے کہ زوجین میں یا دو مسلمان بھائیوں میں صلح صفائی کے غرض سے کو ئی مناسب با ت بنا لی جائے۔"}],[4801,"حارثہ بن وہب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «جواظ» جنت میں نہ داخل ہو گا اور نہ «جعظری»جنت میں داخل ہو گا ۱؎۔ راوی کہتے ہیں «جواظ» کے معنی بدخلق اور سخت دل کے ہیں۔\n§وضاحت\n۱؎ : یہ دونوں لفظ کثیرالمعانی ہیں ، حافظ ابن الاثیرجواظ کی شرح میں فرماتے ہیں: مال جوڑنے والا اور خرچ نہ کرنے والا، یا لحیم شحیم اپنی چال میں اترنے والا ، یا چھوٹا بڑے پیٹ والا، مصباح اللغات میں «جواظ» کے معنی میں فرمایا: تکبر سے چلنے والا، اجڈ بہت کھانے والا، ابن الاثیر «جعظری» کے بارے میں فرماتے ہیں: بھدا موٹا اور متکبر، یا ایسا شخص جو ڈینگیں مارے، اور اس کے پاس کچھ نہ ہو، اور چھوٹا ناٹا ہو، مولانا وحیدالزمان حیدرآبادی نے ان لفظوں کے ترجمہ میں فرمایا : فریبی یا مال جوڑنے والا ، اور دمڑی خرچ نہ کر نے والا ، یا موٹا غلیظ ، یا بیہودہ چلانے والا بدخلق سرکش (یہ سب «جواظ» کے معنی تھے) اور مغرور سخت گویا موٹا بھدا بہت کھانے والا (یہ جب ہے کہ حرام کے مال سے موٹا ہوا ہو) (ابوداود ۳/۵۸۱)","صحیح",{"u2":"سیدنا حارثہ بن وہب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا \u0004” ترش رو بدمزاج جنت میں داخل نہیں ہو گا اور نہ تکبر سے چلنے والا۔ “ اور «جواظ» کا مفہوم ہے سخت مزاج، بدخلق۔","f2":"لفظ(جَعُظُرِی) کے کئی معنی آتے ہیں، مثلاََ موٹا، تکبرانہ چال چلنے والا، پیٹو، جسے سر درد نہ ہوتا ہو،خود آراء، پلے کچھ نہ ہو مگر باتیں بہت بنائے اور پستہ قد ہو۔ واللہ اعلم۔"}],[4802,"انس رضی اللہ عنہ کہتے ہیں کہ (نبی اکرم صلی اللہ علیہ وسلم کی اونٹنی) عضباء مقابلے میں کبھی پیچھے نہیں رہی تھی (ایک بار) ایک اعرابی اپنے ایک نوعمر اونٹ پر سوار ہو کر آیا، اور اس نے اس سے مقابلہ کیا تو اعرابی اس سے آگے نکل گیا تو ایسا لگا کہ یہ چیز رسول اللہ صلی اللہ علیہ وسلم کے اصحاب پر گراں گزری ہے تو آپ نے فرمایا: \"اللہ کا یہ دستور ہے کہ جو چیز بھی اوپر اٹھے اسے نیچا کر دے\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ (رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی) عضباء ہمیشہ سب سے آگے رہتی تھی کوئی اس سے آگے نہ بڑھتا تھا۔ ایک بدوی اپنے ایک جوان اونٹ پر آیا اور اس اونٹنی سے مقابلہ کیا اور اس سے آگے بڑھ گیا۔ اس سے اصحاب رسول اللہ صلی اللہ علیہ وسلم کو گویا ناگواری ہوئی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ پر یہ حق ہے کہ جو کوئی بھی دنیا میں اونچا ہوتا ہے تو وہ اسے نیچا دکھا دیتا ہے۔“"}],[4803,"اس سند سے بھی انس رضی اللہ عنہ سے یہی قصہ مرفوعاً مروی ہے اس میں ہے، آپ نے فرمایا: \"اللہ تعالی کا یہ دستور ہے کہ دنیا کی جو بھی چیز بہت اوپر اٹھے تو اسے نیچا کر دے\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے یہ قصہ مروی ہے اس میں ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ اللہ پر حق ہے کہ دنیا میں جو چیز بھی سر اونچا اٹھاتی ہے تو وہ اسے نیچا دکھا دیتا ہے۔ “","f2":"تواضع اور انکسار میں ہمیشہ خیر اور برکت ہو تی ہے۔ البتہ اثنائے جہاد میں کفار کے مقابلے میں اسلام اور مسلمانوں کی رفعت کا اظہار کرنے کے لیئے اترانا اور بڑائی کا اظہار کرنا جائز ہے۔"}],[4804,"ہمام کہتے ہیں کہ ایک شخص آیا اور عثمان رضی اللہ عنہ کی تعریف انہی کے سامنے کرنے لگا، تو مقداد بن اسود رضی اللہ عنہ نے مٹی لی اور اس کے چہرے پہ ڈال دی اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: جب تم تعریف کرنے والوں سے ملو تو ان کے چہروں پر مٹی ڈال دو۔","صحیح",{"u2":"جناب ہمام (ہمام بن حارث رضی اللہ عنہ) کہتے ہے کہ ایک شخص آیا اور اس نے سیدنا عثمان رضی اللہ عنہ کے منہ پر ان کی تعریف شروع کر دی۔ تو سیدنا مقداد بن اسود رضی اللہ عنہ نے مٹی اٹھائی اور اس کے منہ پر دے ماری اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے ” جب تمہارا سامنا ایسے لوگوں سے ہو جو مدح سرائی اور خوشامد کرنے والے ہوں تو ان کے مونہوں میں مٹی ڈالو۔ “۔","f2":"یہ مذمت اور یہ معاملہ ایسے لوگوں کے لیئے معلوم ہو تا ہے جنکا وتیرہ ہوتا ہے کہ وہ بڑے لوگوں کی خوش آمد اور مدح سرائی کر کے مال کھاتے اور اپنے کام نکالتے ہیں لیکن اگر کسی کی حوصلہ افزائی اور ترغیب و تشویق کے لیئے اس کے اعمال خیر کی مناسب حد تک مدح کردی جائےتو انشا اللہ مباح ہے بہر حال حضرت مقداد رضی اللہ عنہ فرمانِ رسول صلی اللہ علیہ وسلم کے ظاہری معنی ہی لیتے تھے۔ جو بلاشبہ حق اور سچ ہے۔"}],[4805,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک شخص کی تعریف کی، تو آپ نے اس سے فرمایا: \"تم نے اپنے ساتھی کی گردن کاٹ دی\" اسے آپ نے تین بار کہا، پھر فرمایا: \"جب تم میں سے کسی کو اپنے ساتھی کی مدح و تعریف کرنی ہی پڑ جائے تو یوں کہے: میں اسے ایسے ہی سمجھ رہا ہوں، لیکن میں اللہ کے بالمقابل اس کا تزکیہ نہیں کرتا ۱؎\"۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ میں اس کا ظاہر دیکھ کر ایسا کہہ رہا ہوں رہا اس کا باطن تو اس کا علم اللہ ہی کو ہے۔","صحیح",{"u2":"جناب عبدالرحمٰن بن ابوبکرہ اپنے والد سے روایت کرتے ہیں کہ ایک شخص نے نبی کریم صلی اللہ علیہ وسلم کی موجودگی میں دوسرے کی تعریف کی تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا ” تو نے اپنے ساتھی کی گردن کاٹ دی۔ “ آپ صلی اللہ علیہ وسلم نے یہ تین بار فرمایا۔ پھر فرمایا ” اگر کوئی اپنے کسی ساتھی کی مدح کرنا ہی چاہتا ہو تو چاہیئے کہ یوں کہے ” میں اسے یوں سمجھتا ہوں کہ وہ ایسے ایسے ہے اور اللہ کے علم کے مقابلے میں، میں اس کی صفائی نہیں دیتا۔ “"}],[4806,"مطرف کے والد عبداللہ بن شخیر کہتے ہیں کہ میں بنی عامر کے وفد میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا، تو ہم نے عرض کیا: آپ ہمارے سید، آپ نے فرمایا: \"سید تو اللہ تعالی ہے ۱؎\" ہم نے عرض کیا: اور آپ ہم سب میں درجے میں افضل ہیں اور دوستوں کو نوازنے اور دشمنوں پر فائق ہونے میں سب سے عظیم ہیں، آپ نے فرمایا: \"جو کہتے ہو کہو، یا اس میں سے کچھ کہو، (البتہ) شیطان تمہیں میرے سلسلے میں جری نہ کر دے (کہ تم ایسے کلمات کہہ بیٹھو جو میرے لیے زیبا نہ ہو)\"۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ وہی اس لفظ کا حقیقی مستحق ہے، اور حقیقی معنی میں سید اللہ ہی ہے، اور یہ مجازی اضافی سیادت جو افراد انسانی کے ساتھ مخصوص ہے منافی نہیں، حدیث میں ہے «أنا سيد ولد آدم ولا فخر» ۔","صحیح",{"u2":"جناب مطرف رضی اللہ عنہ بیان کرتے ہیں کہ میرے والد (عبداللہ بن شخیر رضی اللہ عنہ) نے کہا کہ میں بنو عامر کے وفد کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ تو ہم نے کہا: آپ ہمارے (سید) سردار ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” سید (اور حقیقی سردار) اللہ تبارک و تعالیٰ ہے۔ “ ہم نے کہا: آپ صلی اللہ علیہ وسلم ہمارے صاحب فضل و فضیلت اور صاحب جود و سخا ہیں۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تم اس طرح کی بات کہہ سکتے ہو۔ مگر کہیں شیطان تمہیں اپنا وکیل نہ بنا لے (کہ کوئی ایسی بات کہہ گزرو جو میری شان کے مطابق نہ ہو)۔ “","f2":"لفظ السید اپنے حقیقی معانی میں اللہ عزوجل کے لیئے ہی زیبا ہے تا ہم مجازی طور پر رسول اللہ صلی اللہ علیہ وسلم نے اپنے لیئے استعمال فرمایا اور خبر دی ہے میں اولادِ آدم کا سردار ہوں اور مجھے اس پر کو ئی ناز نہیں (سنن ابنِ ماجہ، الذھد حدیث: 4308)۔ اسی طرح حضرت عمر رضی اللہ عنہ نے کہا: حضرت ابو بکر رضی اللہ عنہ ہمارے سید ہیں اور انھوں نے ہمارے سید حضرت بلال رضی اللہ عنہ کو آزاد کیا۔ (صحیح البخاری فضائل النبی صلی اللہ علیہ وسلم، حدیث:3754) معلوم ہوا کہ اصحابِ علم و فضل کے لیئے مجازََا یہ لفط استعمال کو سکتا ہے۔ خیال رہے کہ درود شریف کے الفاظ میں سیدنا کا لفظ کسی صحیح روایت میں ثابت نہیں ہے۔"}],[4807,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ رفیق ہے، رفق اور نرمی پسند کرتا ہے، اور اس پر وہ دیتا ہے، جو سختی پر نہیں دیتا ۱؎\"۔\n§وضاحت\n۱؎ : یعنی وہ اپنے بندوں کے ساتھ نرمی کرنے والا ہے، اس کا معاملہ اپنے بندوں کے ساتھ لطف و مہربانی کا ہوتا ہے ، وہ ان پر آسانی چاہتا ہے، سختی نہیں اور انہیں ایسی چیزوں کا مکلف نہیں بناتا جوان کے بس میں نہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن مغفل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ عزوجل رفق اور نرمی سے موصوف ہے ‘ اسے نرمی اور نرم خوئی پسند ہے۔ وہ اس پر وہ کچھ عنایت فرماتا ہے جو ترشی اور کرختگی پر نہیں دیتا۔ “"}],[4808,"شریح کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے دیہات (بادیہ) جانے، وہاں قیام کرنے کے بارے میں پوچھا (کہ کیسا ہے)آپ نے کہا: رسول اللہ صلی اللہ علیہ وسلم ان نالوں کی طرف دیہات (بادیہ) جایا کرتے تھے، ایک بار آپ نے باہر دیہات (بادیہ) جانے کا ارادہ کیا تو میرے پاس زکوٰۃ کے اونٹوں میں سے ایک اونٹنی بھیجی، جس پر سواری نہیں کی گئی تھی، اور مجھ سے فرمایا: اے عائشہ! نرمی کرو، اس لیے کہ جس چیز میں نرمی ہوتی ہے، اسے زینت دیتی ہے اور جس چیز سے بھی نکل جاتی ہے، اسے عیب دار بنا دیتی ہے۔ ابن الصباح اپنی حدیث میں کہتے ہیں: «محرمۃ» سے مراد وہ اونٹنی ہے جس پر سواری نہ کی گئی ہو۔","صحیح",{"u2":"جناب مقدام بن شریح اپنے والد سے روایت کرتے ہیں، انہوں نے کہا کہ میں نے ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے پوچھا کہ جنگل میں جانا کیسا ہے؟ تو انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم ان ٹیلوں کی طرف نکل جایا کرتے تھے۔ آپ صلی اللہ علیہ وسلم نے ایک بار ارادہ کیا کہ جنگل میں جائیں تو آپ صلی اللہ علیہ وسلم نے میرے پاس صدقہ کی اونٹوں میں سے ایک اونٹنی بھیجی جس پر ابھی سواری نہیں ہوئی تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” عائشہ! نرمی اختیار کیا کرو ‘ بلاشبہ نرمی جس چیز میں بھی ہو وہ اسے مزین اور خوبصورت بنا دیتی ہے اور جس چیز سے نکال لی جائے اسے بدصورت اور بھدا بنا دیتی ہے۔ “ ابن صباح نے اپنی حدیث میں واضح کیا کہ «محرمة» سے مراد ایسی اونٹنی ہے جس پر باقاعدہ سواری نہ ہوئی ہو۔","f2":"تدبر فی النفس ولآفاق کی نیت سے آدمی کسی وقت عزلت اختیار کرے تو مفید ہے جسکی مشروع صورت اعتکاف ہے نہ کہ صوفیاء کی سیاحت۔\n2) حیوانات کے ساتھ نرم خوئی ممدوح اور مطلوب ہے تو انسانوں کے ساتھ یہ معاملہ اور بھی باعثِ اجر وثواب ہے۔"}],[4809,"جریر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو رفق (نرمی) سے محروم کر دیا جاتا ہے وہ تمام خیر سے محروم کر دیا جاتا ہے\"۔","صحیح",{"u2":"سیدنا جریر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص نرم خوئی سے محروم ہوا وہ سب بھلائیوں سے محروم ہوا۔ “"}],[4810,"سعد رضی اللہ عنہ کہتے ہیں کہ تاخیر اور آہستگی ہر چیز میں (بہتر) ہے، سوائے آخرت کے عمل کے ۱؎۔ اعمش کہتے ہیں میں یہی جانتا ہوں کہ یہ حدیث نبی اکرم صلی اللہ علیہ وسلم سے مروی ہے یعنی مرفوع ہے۔\n§وضاحت\n۱؎ : کیونکہ نیک کاموں میں تاخیر اور التواء «سارعوا إلى مغفرة من ربكم» کے منافی ہے۔","صحیح",{"u2":"جناب مصعب اپنے والد (سیدنا سعد بن ابی وقاص رضی اللہ عنہ) سے روایت کرتے ہیں۔ اعمش کہتے ہیں اور مجھے ایسے ہی معلوم ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ‘ آپ صلی اللہ علیہ وسلم نے فرمایا ” کسی کام میں جلد بازی نہیں (کرنی) چاہیئے سوائے اس کے کہ آخرت کا کام ہو۔ “","f2":"ایسے تمام اعمال جو اللہ کی رضامندی کے حصول کا ذریعہ ہوں حقوق اللہ ہوں یا حقوق العباد ان کی انجام دہی میں دیر نہیں کرنی چاہیئے۔ البتہ دنیاوی کاموں میں سوچ بچار اور مشورے سے اقدام کرنا چاہیئے۔ یہ حدیث بعض محقیقن کے نزدیک صحیح ہے۔ تفصیل کے لیئے دیکھیئے: (الصحیحۃ: حدیث: 1794)۔"}],[4811,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو لوگوں کا شکر ادا نہیں کرتا اللہ کا (بھی) شکر ادا نہیں کرتا\"۔\n§وضاحت\n۱؎ : جس کی عادت و طبیعت میں بندوں کی ناشکری ہو وہ اللہ کے احسانات کی بھی ناشکری کرتا ہے، یا یہ مطلب ہے کہ اللہ ایسے بندوں کا شکر قبول نہیں فرماتا جو لوگوں کے احسانات کا شکریہ ادا نہ کرتے ہوں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شخص لوگوں کا شکریہ ادا نہیں کرتا ‘ وہ اللہ کا بھی شکر گزار نہیں ہوتا۔ “","f2":"لوگوں کے اچھے معا ملے اور احسان پر شکرئیے کا اظہار انسا ن کے صاحبِ خلق ہونے کی دلیل ہو تا ہے۔ جبکہ اللہ عزوجل کا شکر عبادت اور عبودیت کا حصہ ہے۔ لوگ جو آپ کے ساتھ احسان کرتے ہیں وہ دراصل اللہ عزوجل کے تصرف سے ہی کرتے ہیں لہذا حقیقی شکر گزاری تو رب تعالی ہی کا حق ہے۔ تاہم با لتبع لوگوں سے احسان مندی کا اظہار بھی لازمی طور پر مشروع اور مسنون ہے۔"}],[4812,"انس رضی اللہ عنہ کہتے ہیں کہ مہاجرین نے کہا: اللہ کے رسول! سارا اجر تو انصار لے گئے، آپ نے فرمایا: \"نہیں (ایسا نہیں ہو سکتا کہ تم اجر سے محروم رہو) جب تک تم اللہ سے ان کے لیے دعا کرتے رہو گے اور ان کی تعریف کرتے رہو گے\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے مروی ہے کہ مہاجرین کہنے لگے: اے اللہ کے رسول! سارا اجر تو انصار لے گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں ‘ جب تک تم اللہ تعالیٰ سے ان کے لیے دعائیں کرتے رہو گے اور ان سے احسان مندی کا اظہار کرو گے (اس طرح ان کو اجر ملنے کے ساتھ ساتھ تمہیں بھی ملے گا)۔ “","f2":"زبانی اور عملی احسان مندی اور شکرئیے کےساتھ ساتھ اہم عمل یہ ہے کہ انسان اپنے محسن کے لیئے دعائیں کیا کرے۔ یعنی محض زبان سے شکریہ کا لفظ نہ کہے بلکہ دُعائیہ کلمات کہے اللہ تعالی تمھیں بہترین بدلہ عطا فرمائے۔ اس کے علاوہ اپنے محسنوں کے لیئے غائیبانہ طور پر خصوصی دُعائیں بھی کرتا رہے۔"}],[4813,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کو کوئی چیز دی جائے پھر وہ بھی (دینے کے لیے کچھ) پا جائے تو چاہیئے کہ اس کا بدلہ دے، اور اگر بدلہ کے لیے کچھ نہ پائے تو اس کی تعریف کرے، اس لیے کہ جس نے اس کی تعریف کی تو گویا اس نے اس کا شکر ادا کر دیا، اور جس نے چھپایا (احسان کو) تو اس نے اس کی ناشکری کی۔ ابوداؤد کہتے ہیں: اسے یحیی بن ایوب نے عمارہ بن غزیہ سے، انہوں نے شرحبیل سے اور انہوں نے جابر سے روایت کیا ہے۔ ابوداؤد کہتے ہیں: سند میں «رجل من قومی» سے مراد شرحبیل ہیں، گویا وہ انہیں ناپسند کرتے تھے، اس لیے ان کا نام نہیں لیا۔","حسن",{"u2":"جناب عمارہ بن غزیہ نے بیان کیا کہ میری قوم کے ایک آدمی نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کیا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جسے کوئی عطیہ اور ہدیہ دیا جائے تو اگر ہمت ہو اور میسر ہو تو اس کا بدلہ دے اور اگر نہ پائے تو اس کی مدح و ثنا کرے۔ جس نے اپنے محسن کی مدح کی اس نے اس کا شکریہ ادا کیا اور جس نے اس (کے احسان) کو چھپایا اس نے اس کی ناشکری کی۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو یحییٰ بن ایوب نے بواسطہ عمارہ بن غزیہ ‘ شرجیل سے اور اس نے سیدنا جابر رضی اللہ عنہ سے روایت کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ سند میں عمارہ بن غزیہ نے جس آدمی کا نام لیا اور یوں کہا ہے کہ ” میری قوم کے ایک آدمی نے مجھ سے بیان کیا۔ “ وہ شرجیل ہی ہے۔ گویا انہوں نے اس کا نام ذکر کرنا پسند نہیں کیا۔","f2":"یہ روایت بعض محقیقین کے نزدیک حسن ہے۔"}],[4814,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کو کوئی چیز ملے اور وہ اس کا تذکرہ کرے تو اس نے اس کا شکر ادا کر دیا اور جس نے اسے چھپایا تو اس نے ناشکری کی ۱؎\"۔\n§وضاحت\n۱؎ : حدیث میں «أبلى بلائً» جو «من أعطى عطائًا» کے معنی میں ہے «بلاء» کا لفظ خیر اور شر دونوں معنی میں استعمال ہوتا ہے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے کسی پر کوئی احسان کیا پھر اس دوسرے نے اس کا ذکر کیا تو یہ اس کا شکریہ ادا کرنا ہے اور اگر اس (دوسرے) نے اسے چھپایا تو یہ اس کی ناشکری اور ناقدری کی۔ “","f2":"مناسب مقام اور مناسب انداز سے منعم اور محسن کے احسان کا ذکرِ خیر کرنا حق ہے اور قدر دانی مین شمار ہے۔ اس سے اُلفت بڑھتی ہے اور اسکے بر خلاف میں کبیدگی آتی ہے۔ یہ روایت بعض محقیقین کے نزدیک صحیح ہے۔ تفصیل کے لیئے دیکھیں(الصحیحۃ: حدیث: 618)"}],[4815,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ راستوں میں بیٹھنے سے بچو\" لوگوں نے عرض کیا: اللہ کے رسول! ہمیں اپنی مجالس سے مفر نہیں ہم ان میں (ضروری امور پر) گفتگو کرتے ہیں، آپ نے فرمایا: \"پھر اگر تم نہیں مانتے تو راستے کا حق ادا کرو\" لوگوں نے عرض کیا: راستے کا حق کیا ہے؟ اللہ کے رسول! آپ نے فرمایا: \"نگاہ نیچی رکھنا، ایذاء نہ دینا، سلام کا جواب دینا، نیکی کا حکم دینا اور برائی سے روکنا\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” راستوں پر بیٹھنے سے احتراز کرو۔ “ لوگوں نے کہا: اے اللہ کے رسول! ہمیں تو اس سے چارہ نہیں ہے ‘ ہم نے آپس میں بات چیت کرنی ہوتی ہے ‘ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اگر اس سے انکار کرتے ہو تو پھر راستے کے حق کا خیال رکھو۔ “ انہوں نے پوچھا: اے اللہ کے رسول! راستے کا کیا حق ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نظر نیچی رکھنا ‘ تکلیف دہ چیز کا ہٹا دینا ‘ سلام کا جواب دینا ‘ بھلی بات کہنا اور برائی سے روکنا۔ “","f2":"راستوں اور چوکوں پر بلا وجہ معقول دھرنا مار کر بیٹھےرہنا شریفاء کا کام نہیں۔ ضرورت اور مجبوری کی کیفیت الگ چیز ہے۔ اس سے پردہ دار خواتین کو بالخصوص اذیت ہوتی ہے۔ اصحابِ مجلس اگر دین و تقوٰی سے موصوف نہ ہوں تو راہ گزرنے والوں پر بے جا تبصرے بھی ہوتے ہیں جو مسلمانوں کو کسی طرح بھی زیب نہیں دیتا۔ اور اگر کوئی بطور مہمان آیا ہو تو اس کے ساتھ سرِراہ ہی مجلس لگا لینا اسکا اکرام نہیں ہے۔ بہر حال سرِ راہ بیٹھنے کی صورت میں مندرجہ بالا شرعی ہدایات کا پاس رکھنا لازم ہے۔"}],[4816,"ابوہریرہ رضی اللہ عنہ سے یہی قصہ مرفوعاً مروی ہے اس میں یہ بھی ہے آپ نے فرمایا: \"اور (بھولے بھٹکوں کو) راستہ بتانا\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے اس قصے (حدیث) میں بیان کیا آپ صلی اللہ علیہ وسلم نے فرمایا ” راہ گیر کی رہنمائی کرنا (بھی راستے کے حق میں شامل ہے)۔ “"}],[4817,"ابن حجیر عدوی کہتے ہیں کہ میں نے اس قصے میں عمر بن خطاب رضی اللہ عنہ کو نبی اکرم صلی اللہ علیہ وسلم سے یہ بھی روایت کرتے ہوئے سنا، آپ نے فرمایا: \"اور تم آفت زدہ لوگوں کی مدد کرو اور بھٹکے ہووں کو راستہ بتاؤ\"۔","صحیح",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ نے اس قصے (حدیث) میں بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” پریشان حال کی مدد کرو اور راستہ بھول جانے والے کی رہنمائی کرو۔ “","f2":"ان صفات و خصائل کو معمولی اور اضافی صفات نہیں سمجھنا چاہیئے۔ حقیقت یہ ہے کہ یہ صفات ایمان واسلام کو کامل کرتی ہیں۔ یہ روایت بعض کے نزدیک صحیح ہے۔"}],[4818,"انس رضی اللہ عنہ کہتے ہیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی، اور بولی: اللہ کے رسول! مجھے آپ سے ایک ضرورت ہے، آپ نے اس سے فرمایا: \"اے فلاں کی ماں! جہاں چاہو گلی کے کسی کونے میں بیٹھ جاؤ، یہاں تک کہ میں تمہارے پاس آ کر ملوں\" چنانچہ وہ بیٹھ گئی، پھر نبی اکرم صلی اللہ علیہ وسلم اس سے آ کر ملے، یہاں تک کہ اس نے آپ سے اپنی ضرورت کی بات کی۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ ایک عورت نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہنے لگی: اے اللہ کے رسول! مجھے آپ سے ایک کام ہے۔ آپ صلی اللہ علیہ وسلم نے اس سے فرمایا ” اے فلاں! کسی گلی کے کونے پر بیٹھ جاؤ میں تیرے ساتھ بیٹھ سکتا ہوں (تیری بات سن سکتا ہوں)۔ “ چنانچہ وہ بیٹھ گئی اور نبی کریم صلی اللہ علیہ وسلم بھی اس کے ساتھ بیٹھ گئے حتیٰ کہ اس نے اپنا مقصد پا لیا۔ ابن عیسیٰ نے «حتى قضت حاجتها» کا لفظ ذکر نہیں کیا۔ اور کثیر (کثیر بن عبید) نے اپنی سند میں (عنعنہ سے روایت کرتے ہوئے) «عن حميد عن أنس» کہا۔"}],[4819,"انس رضی اللہ عنہ سے روایت ہے کہ ایک عورت تھی جس کی عقل میں کچھ فتور تھا پھر انہوں نے اسی مفہوم کی حدیث بیان کی۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ نے بیان کیا کہ اس عورت کی عقل میں کوئی کمی تھی۔ اور مذکورہ بالا کے ہم معنی بیان کیا۔","f2":"کسی ضرورت کی بنا پر کہیں سرِراہ بیٹھنا پڑ جائے تو کو ئی معیوب نہیں۔ اس حدیث کا یہ مفہوم بھی لیا گیا ہے کہ آپ صلی اللہ علیہ وسلم نے سرِ راہ بیٹھنے کی بجائے کسی ایک طرف الگ ہو کر بیٹھنے کا کہا تھا۔\n2) سادہ لوح اور بے عقل قسم لوگوں کی دلداری کرنا بھی شرعی اور اخلاقی فریضہ ہے۔ا س طرح یہ لوگ کافی حد تک خوش اور پرسکون ہو جا تے ہیں۔ ورنہ پریشان ہونے کی وجہ سے کئی طرح کی حرکتیں کرتے ہیں۔ ایسے لوگوں سے استہز ہ کرنا اور اُنھیں مسخرہ بنانا قطعاَ روا نہیں۔ ایسا عمل اُن پر بہت بڑا ظلم ہے اور ایسا کرنے والے بہت بڑے ظالم ہوتے ہیں۔ اسلام اس کی قطعاََ اجازت نہیں دیتا۔\n3) قضاء الحاجة ايك عام تركيب اور جملہ ہے جیسے اس روایت میں آیا ہے اور اس کے معنی بھی واضح ہیں کہ وہ جو بات کرنا چاہتی تھی وہ اس نے کر لی۔"}],[4820,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"مجالس میں بہتر وہ ہے جو زیادہ کشادہ ہو\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ” بہترین مجلس وہ ہے جو وسیع اور کھلی ہو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ راوی حدیث عبدالرحمٰن بن ابو عمرہ کا صحیح نسب یوں ہے ” عبدالرحمٰن بن عمرو بن ابو عمرہ الانصاری۔ “","f2":"مجلس میں اگرافراد زیادہ ہوں تو حسن ادب اور وقار کا تقاضا ہے کہ حلقہ وسیع کع لیا جائے۔ اور اس قسم کے اعمال میں اتباع ِ فرمان ِ رسول صلی اللہ علیہ وسلم کی نیت شامل ہو تو ثواب زیادہ ملتا ہے۔"}],[4821,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی دھوپ میں ہو (مخلد کی روایت) سایہ میں ہو، پھر سایہ اس سے سمٹ گیا ہو اس طرح کہ اس کا کچھ حصہ دھوپ میں آ جائے اور کچھ سایہ میں رہے تو چاہیئے کہ وہ اٹھ جائے ۱؎\"۔\n§وضاحت\n۱؎ : اس لئے کہ اس سے ضرر کا اندیشہ ہے، جیسے بیک وقت گرم و سرد چیز کا استعمال مضر ہوتا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا ” جب کوئی شخص دھوپ میں بیٹھا ہو، مخلد کے الفاظ ہیں اگر کوئی سائے میں بیٹھا ہو اور پھر اس سے سایہ ٹل جائے اور وہ کچھ دھوپ میں آ جائے اور کچھ سائے میں تو وہاں سے اٹھ جائے۔ “"}],[4822,"ابوحازم البجلی رضی اللہ عنہ کہتے ہیں کہ وہ آئے اور رسول اللہ صلی اللہ علیہ وسلم خطبہ دے رہے تھے، تو وہ دھوپ میں کھڑے ہو گئے، اس کے بعد (آپ نے انہیں سایہ میں آنے کے لیے کہا) تو وہ سائے میں آ گئے ۔","صحیح",{"u2":"جناب قیس (قیس بن ابوحازم) اپنے والد سے روایت کرتے ہیں کہ وہ آئے جبکہ رسول اللہ صلی اللہ علیہ وسلم خطبہ ارشاد فر رہے تھے۔ تو یہ دھوپ میں کھڑے ہو گئے تو آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا تو سائے میں چلے گئے۔","f2":"اطباء بھی یہی کہتے ہیں کی انسان ی سارا دھوپ میں ہو یا سارا ہی سائے میں\nہو۔ آدھا دھوپ میں ہونا اور آدھا سائے میں ہونا طبی طور پر نقصان دہ ہے۔ خاص طور پر شدید گرمی والے علاقوں میں۔"}],[4823,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے اور لوگ حلقے بنا کر بیٹھے ہوئے تھے، آپ نے فرمایا: \"کیا وجہ ہے کہ میں تم لوگوں کو الگ الگ گروہوں میں دیکھ رہا ہوں\"۔","صحیح",{"u2":"سیدنا جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف لائے جب کہ صحابہ ٹولیاں بنائے بیٹھے تھے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا بات ہے تم ٹولیوں میں جدا جدا بیٹھے ہو؟ “"}],[4824,"اعمش سے بھی یہی حدیث مروی ہے البتہ اس میں ہے \"گویا کہ آپ اجتماعیت کو پسند فرماتے تھے\"۔","صحیح",{"u2":"جناب اعمش رضی اللہ عنہ نے یہ روایت بیان کی اور کہا گویا آپ صلی اللہ علیہ وسلم نے اجتماعیت کو پسند فرمایا۔","f2":"اگر اہلِ اجتماع کا موضوع ایک ہو تو افضل اور مستحب یہی ہے کہ ایک حلقے میں بیٹھیں۔ لیکن اگر موضوعات مختلف ہوں تو حلقے بنا لینا جائز ہے جیسے کہ طلباءِ علم اور اصحابِ ذوق میں ہوتا ہے۔ خیال رہے کہ نماز کی جماعت کے انتظار میں حلقے بنا کر بیٹھنا معیوب ہے چاہیے کی ترتیب سے صف میں جگہ بنا کر بیٹھا جائے۔"}],[4825,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ جب ہم نبی اکرم صلی اللہ علیہ وسلم کے پاس آتے، تو ہم میں سے جس کو جہاں جگہ ملتی بیٹھ جاتا۔","صحیح",{"u2":"سیدنا جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ ہم جب نبی کریم صلی اللہ علیہ وسلم کی مجلس میں آتے تھے تو جہاں مجلس پہنچی ہوتی وہیں (آخر میں) بیٹھ جایا کرتے تھے۔","f2":"یہ بات انتہائی معیوب ہوتی ہے کہ انسان دیر سے آئے اور پہلے سے بیٹھے ہو ئے لوگوں کی گردنیں پھلانگتا ہوا آگے جگہ لینے کی کوشش کرے۔ ہاں اگر پہلے آنے والوں نے مجلس کا ادب ملحوظ نہ رکھا ہو کہ آگے جگہ خالی چھوڑ دی ہو اور راستے میں بیٹھ گئے ہوں تو گردنیں پھلانگنا جائز ہو گا۔ کیونکہ انھوں نے از خود اپنا وقار ضائع کیا ہو تا ہے\n2) یہ روایت ہمارے فاضل محقق کے نزدیک سندََا ضعیف ہے، تاہم معنوی طور پر یہ روایت صحیح ہے جیسا کہ ہمارے فاضل محقق نے تحقیق و تخریج میں اس بات کی وضاحت کی ہے علاوہ ازیں شیخ البانی رحمہ اللہ نے بھی اسکو صحیح قرار دیا ہے۔"}],[4826,"حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس پر لعنت فرمائی جو حلقہ کے بیچ میں جا کر بیٹھے۔","ضعیف",{"u2":"سیدنا حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لعنت کی ہے ایسے آدمی پر جو حلقے کے درمیان میں بیٹھتا ہے۔"}],[4827,"سعید بن ابوالحسن کہتے ہیں کہ ابوبکرہ رضی اللہ عنہ ایک گواہی کے سلسلے میں ہمارے ہاں آئے، تو ان کے لیے ایک شخص اپنی جگہ سے اٹھ کھڑا ہوا، تو انہوں نے وہاں بیٹھنے سے انکار کیا، اور کہا: نبی اکرم صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے، اور نبی اکرم صلی اللہ علیہ وسلم نے اس بات سے بھی منع فرمایا ہے کہ آدمی اپنا ہاتھ کسی ایسے شخص کے کپڑے سے پونچھے جسے اس نے کپڑا نہ پہنایا ہو۔","ضعیف",{"u2":"جناب سعید بن ابوالحسن بیان کرتے ہیں کہ سیدنا ابوبکرہ رضی اللہ عنہ ایک گواہی کے سلسلے میں ہمارے ہاں تشریف لائے تو مجلس میں سے ایک آدمی ان کے لیے اپنی جگہ سے اٹھ کھڑا ہوا۔ تو انہوں نے اس جگہ بیٹھنے سے انکار کر دیا اور کہا: تحقیق نبی کریم صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے۔ اور نبی کریم صلی اللہ علیہ وسلم نے اس سے بھی روکا ہے کہ کوئی شخص کسی دوسرے کے کپڑے سے جو اس نے اسے نہ پہنایا ہو، اپنا ہاتھ پونچھے۔","f2":"یہ روایت سندَا ضعیف ہے، تاہم اس میں بیان کردہ باتیں دیگر احادیث سے ثابت ہیں\n2) پہلے سے بیٹھا ہو شخص ہی زیادہ حقدار ہے کہ وہ اپنی جگہ پر بیٹھے۔ دیگر احادیث کی روشنی میں اگر اُٹھنے والا دلی خوشی سے ایسا کرے تو مباح بھی ہےجیسے کہ کتاب الصلوۃ میں گزرا ہے کہ کسی کی عزت کی جگہ پر بیٹھنا جائز نہیں اِلا یہ کہ وہ ازخود اجاز ت دے۔\n3) دوسرے کے کپڑے سے بلااجازت ہاتھ پونچھنا کسی طرح روا نہیں کہ یہ دوسرے کے مال میں تصرف ہے سوائے اسکے کہ دوسرا زیرِ تولیت ہو مثلاََ اپنا بیٹا، غلام یا بیوی۔ کیونکہ انکا کپڑا اور مال ولی کا مال ہی ہوتا ہے۔"}],[4828,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، تو ایک شخص اس کے لیے اپنی جگہ سے اٹھ کھڑا ہوا تو وہ وہاں بیٹھنے چلا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے روک دیا۔","حسن",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا تو ایک آدمی اس کے لیے اپنی جگہ سے اٹھ کھڑا ہوا ‘ وہ (آنے والا) وہاں بیٹھنے لگا تو نبی کریم صلی اللہ علیہ وسلم نے اس کو منع فر دیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ابو خصیب کا نام زیاد بن عبدالرحمٰن ہے۔","f2":") یہ ممانعت بھی احتیاط کے طور پر ہے تاکہ لوگ ایک دوسرے کی جگہ پر نہ بیٹھیں۔ ورنہ اگر کو ئی شخص احتراماَ کسی دوسرے کو اپنی جگہ بیٹھنے کی پیشکش کرتا ہے تو دیگر دلائل کی رُو سے اسکا جواز ہے۔\n2) یہ رویت ہمارے فاضل محقق کے نزدیک ضعیف ہے تاہم معنوی طور پر صحیح ہے جیسا کہ خود اُنھوں نے اپنی تحقیق میں بخاری و مسلم کی روایات کا حوالہ درج کرنے کے بعد یغنی عنة یعنی بخاری اور مسلم کی روایات کفایت کرتی ہیں کہا ہے۔ علاوہ ازیں شیخ البانی رحمہ اللہ نے بھی اسے حسن کہا ہے، تفصیل کے لیئے دیکھئے:(الصحٰحة حديث ٢٢٨)"}],[4829,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسے مومن کی مثال جو قرآن پڑھتا ہے اس نارنگی کی سی ہے جس کی بو بھی اچھی ہے اور جس کا ذائقہ بھی اچھا ہے اور ایسے مومن کی مثال جو قرآن نہیں پڑھتا اس کھجور کی طرح ہے جس کا ذائقہ اچھا ہوتا ہے لیکن اس میں بو نہیں ہوتی، اور فاجر کی مثال جو قرآن پڑھتا ہے، گلدستے کی طرح ہے جس کی بو عمدہ ہوتی ہے اور اس کا مزا کڑوا ہوتا ہے، اور فاجر کی مثال جو قرآن نہیں پڑھتا، ایلوے کے مانند ہے، جس کا ذائقہ کڑوا ہوتا ہے، اور اس میں کوئی بو بھی نہیں ہوتی، اور صالح دوست کی مثال مشک والے کی طرح ہے، کہ اگر تمہیں اس سے کچھ بھی نہ ملے تو اس کی خوشبو تو ضرور پہنچ کر رہے گی، اور برے دوست کی مثال اس دھونکنی (لوہے کی بٹھی) والے کی سی ہے، کہ وہ اگر اس کی سیاہی سے بچ بھی جائے تو اس کا دھواں تو لگ ہی کر رہے گا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مومن جو قرآن مجید کی تلاوت کرتا ہے اس کی مثال ترنج کی سی ہے کہ اس کی خوشبو عمدہ اور وہ خوش ذائقہ بھی ہوتا ہے۔ اور مومن جو قرآن کی تلاوت نہیں کرتا اس کی مثال کھجور کی سی ہے کہ اس کا ذائقہ عمدہ ہوتا ہے مگر اس میں خوشبو نہیں ہوتی۔ اور فاجر آدمی جو قرآن پڑھتا ہے اس کی مثال ریحان (نازبو) کی سی ہے کہ اس کی خوشبو عمدہ مگر ذائقہ کڑوا ہوتا ہے۔ اور فاجر آدمی جو قرآن نہیں پڑھتا اس کی مثال حنظل (اندرائن۔ کوڑتمہ) کی سی ہے کہ اس کا ذائقہ کڑوا اور خوشبو کوئی نہیں ہوتی۔ اور نیک صالح ساتھی کی مثال کستوری والے کے مانند ہے اگر تجھے اس سے نہ بھی ملی تو اس کی خوشبو تو (ضرور) پہنچے گی اور برے ساتھی کی مثال بھٹی والے کی طرح ہے ‘ اگر تجھے اس کی کالک نہ لگی تو دھواں تو ضرور آئے گا۔","f2":"صالح متقی اور صاحبِ عمل مومن کی صحبت حاصل کرنے کی کوشش کرنی چاہیے۔ اس میں دین اور دُنیا دونوں کا فائدہ ہے۔\n2) فاسق و فاجر لوگوں سے دور رہنا چاہیئے کہ ان کی صحبت میں خسارہ ہی خسارہ ہے۔\n3) استاذ اور خطیب کو عمدہ مثالوں سے اپنی بات واضح کرنے کی کوشش کرنی چاہیئے۔"}],[4830,"اس سند سے بھی ابوموسی رضی اللہ عنہ سے شروع سے «طعمها مر» (اس کا مزا کڑوا ہے) تک اسی طرح مرفوعاً مروی ہے، اور ابن معاذ نے یہ اضافہ کیا ہے کہ انس رضی اللہ عنہ نے کہا: اور ہم آپس میں کہتے تھے کہ اچھے ہم نشین کی مثال، پھر راوی نے بقیہ حدیث بیان کی۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ نے سیدنا ابوموسیٰ رضی اللہ عنہ سے انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کا پہلا حصہ ” اس کا ذائقہ کڑوا ہوتا ہے۔ “ تک بیان کیا۔ اور ابن معاذ نے مزید کہا کہ سیدنا انس رضی اللہ عنہ نے کہا: ہم کہا کرتے تھے کہ صالح ساتھی کی مثال، اور بقیہ حدیث بیان کی۔"}],[4831,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: اچھے ہم نشین کی مثال ... پھر راوی نے اس جیسی روایت ذکر کی۔","صحیح",{"u2":"شبیل بن عزرہ نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” صالح ساتھی کی مثال “ اور مذکورہ بالا حدیث کی مانند بیان کیا۔"}],[4832,"ابوسعید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مومن کے سوا کسی کو ساتھی نہ بناؤ ۱؎، اور تمہارا کھانا سوائے پرہیزگار کے کوئی اور نہ کھائے\"۔\n§وضاحت\n۱؎ : اس میں کفار و منافقین کی مصاحبت سے ممانعت ہے کیونکہ ان کی مصاحبت دین کے لئے ضرر رساں ہے۔","حسن",{"u2":"سیدنا ابوسعید رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” صرف مومن آدمی کی صحبت اختیار کر اور تیرا کھانا بھی کوئی متقی ہی کھائے۔ “","f2":"فارسی میں کہتے ہیں صحبت صا لح ترا صالح کند صحبت طالح ترا طالح کند۔ صحبت اور مجلس سے انسان اپنے ساتھی کی عادات اور رنگ ڈھنگ اختیار کرلیتا ہے اور دھیرے دھیرے اس کی محبت بھی دل میں گھر کر جاتی ہے اور معا ملہ دین اور عقیدے تک جا پہنچتا ہے اس لیئے صاحبِ ایمان کے علاوہ فاسق و فاجر کی صحبت سے گریز کرنا واجب ہے۔\n2) صدقات ع ہدایات میں اولیت اہلِ ایمان اور اہلِ تقوٰی کو حاصل ہےدیگر لوگ دوسرے درجے پر ہیں اور ان سے احسان کرنے میں بھی اجر ہے۔ جیسے کہ ارشادِ باری تعالی ہے: اہلِ ایمان اللہ کی محبت کی بنا پر مسکینوںِ یتیموں اور قیدیوں کو کھانا کھلاتے ہیں۔ اور قیدی ہر طرح کے لوگ ہو سکتے ہیں۔ مسلمان، فاسق، فاجر اور کافر۔ اسی طرح یتامٰی اور مساکین کا معاملہ ہے۔"}],[4833,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آدمی اپنے دوست کے دین پر ہوتا ہے، لہٰذا تم میں سے ہر شخص کو یہ دیکھنا چاہیئے کہ وہ کس سے دوستی کر رہا ہے\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” انسان اپنے محبوب ساتھی کے دین پر ہوتا ہے۔ تو تمہیں چاہیئے کہ غور کرو کس سے دوستی کر رہے ہو۔ “"}],[4834,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"روحیں (عالم ارواح میں) الگ الگ جھنڈوں میں ہوتی ہیں یعنی(بدن کے پیدا ہونے سے پہلے روحوں کے جھنڈ الگ الگ ہوتے ہیں) تو ان میں سے جن میں آپس میں (عالم ارواح میں) جان پہچان تھی وہ دنیا میں بھی ایک دوسرے سے مانوس ہوتی ہیں اور جن میں اجنبیت تھی وہ دنیا میں بھی الگ الگ رہتی ہیں\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ مرفوعاً (نبی کریم صلی اللہ علیہ وسلم سے) بیان کرتے ہیں کہ ” روحیں (ازل میں) مجتمع لشکر تھیں ‘ جن کا (وہاں) آپس میں تعارف ہو گیا (دنیا میں) ان کے اندر الفت ہو جاتی ہے اور جن کی (وہاں) آپس میں ناواقفی رہی ہو وہ (اس دنیا میں بھی) ایک دوسرے سے جدا جدا رہتی ہیں۔ “","f2":"اگر کسی کو صالحین کی صحبت میسر ہو اور انکے ساتھ انس بھی ہو تو یہ اللہ کی نعمت ہے۔ اس پر اللہ کا شکر ادا کرنے کے ساتھ ساتھ اس تعلق کو اور زیادہ مضبوط بنانا چاہیئے۔ لیکن اگر معاملہ اس کے برعکس ہو تو صاحبِ ایمان ہونے کے ناطے چاہیئے کہ بندہ اپنے عمل اور مزاج میں تبدیلی لائے۔"}],[4835,"ابوموسی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنے صحابہ میں سے کسی کو اپنے کام کے لیے بھیجتے تو فرماتے، خوشخبری دینا، نفرت مت دلانا، آسانی اور نرمی کرنا، دشواری اور مشکل میں نہ ڈالنا۔","صحیح",{"u2":"سیدنا ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ کو جب اپنے کسی کام کے لیے بھیجا کرتے تھے تو انہیں فرماتے ” خوشخبری دینے والے بننا ‘ نفرت نہ دلانا ‘ آسانی کرنا اور تنگی اور مشقت نہ ڈالنا۔ “","f2":"قائد اور صاحبِ منصب کے لیئے خاص نبوی ہدایت یہ ہے کہ اپنے ماتحت افراد کے لیئے نرمی اور آسانی پیدا کرنے والا بنے۔ بے مقصد سختی مخالفت کا باعث بنتی ہے۔ جو نفرت لاتی ہے اور کسی بھی نظم اور اجتماعیت کے لیئے سم قاتل ہے۔"}],[4836,"سائب رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، تو لوگ میری تعریف اور میرا ذکر کرنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں ان کو تم لوگوں سے زیادہ جانتا ہوں\" میں نے عرض کیا: سچ کہا آپ نے میرے باپ ماں آپ پر قربان ہوں، آپ میرے شریک تھے، تو آپ ایک بہترین شریک تھے، نہ آپ لڑتے تھے اور نہ جھگڑتے تھے۔","صحیح",{"u2":"سیدنا سائب رضی اللہ عنہ سے مروی ہے کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو لوگ میری مدح اور میرے اعمال کا ذکر کرنے لگے ‘ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میں اس کے متعلق تم سے زیادہ جانتا ہوں۔ “ میں نے عرض کیا: آپ نے بجا فرمایا ‘ میرے ماں باپ آپ پر قربان! آپ میرے شراکت دار تھے اور بہت ہی خوب شراکت دار تھے۔ آپ میں مخالفت کرنے یا لڑنے جھگڑنے والی کوئی بات نہیں تھی۔","f2":"نبی صلی اللہ علیہ وسلم کے انہی خصائلِ حمیدہ کی وجہ سے آپ صلی اللہ علیہ وسلم کی نبوت سے پہلے کی زندگی کو بطور نمونہ پیش کیا گیا ہے۔ ارشادِ الٰہی ہے بلا شبہ میں تم میں اس سے پہلے ایک عمر گزار چکا ہوں۔ کیا پس تم عقل نہیں کرتے ہو (یونس 16) اور اللہ عزوجل نے آپ کی حیاتِ مبارکہ کہ قسم کھائی ہے فرمایا تیری عمر کی قسم! وہ تو اپنی بد مستی میں سرگرداں تھے (الحجر 72)۔ یہ رویت سندَا ضعیف ہے لیکن معناََ صحیح ہے جیسا کہ سیخ البانی رحمہ اللہ نے بھی اس روایت کو صحیح قرار دیا ہے۔"}],[4837,"عبداللہ بن سلام رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب گفتگو کرنے بیٹھتے تو آپ اکثر اپنی نگاہ آسمان کی طرف اٹھاتے۔","ضعیف",{"u2":"جناب یوسف رضی اللہ عنہ اپنے والد عبداللہ بن سلام رضی اللہ عنہ سے روایت کرتے ہیں کہ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب بیٹھے باتیں کر رہے ہوتے تو آپ صلی اللہ علیہ وسلم کی نظر اکثر آسمان کی طرف ہوتی تھی۔"}],[4838,"مسعر کہتے ہیں کہ میں نے مسجد میں ایک بزرگ کو کہتے سنا کہ میں نے جابر بن عبداللہ رضی اللہ عنہما کو کہتے سنا: رسول اللہ صلی اللہ علیہ وسلم کی گفتگو میں ترتیل یا ترسیل ہوتی تھی یعنی آپ ٹھہر ٹھہر کر صاف صاف گفتگو کرتے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی گفتگو میں انتہائی ٹھہراؤ ہوتا تھا۔"}],[4839,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی گفتگو کا ہر لفظ الگ الگ اور واضح ہوتا تھا، جو بھی اسے سنتا سمجھ لیتا۔","حسن",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی گفتگو اس قدر واضح ہوا کرتی تھی کہ ہر سننے والا اسے سمجھ لیتا تھا۔","f2":"جلدی اور تیزی تیزی سے گفتگو کرنا باوقار لوگوں کے ہاں ہمیشہ معیوب سمجھا گیا ہے۔ اور از حد تیز بولنے والا خطیب بھی کامیاب خطیب نہی سمجھا جاتا۔"}],[4840,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر وہ کلام جس کی ابتداء الحمدللہ (اللہ کی تعریف) سے نہ ہو تو وہ ناقص و ناتمام ہے\"۔ ابوداؤد کہتے ہیں: اسے یونس، عقیل، شعیب، اور سعید بن عبدالعزیز نے زہری سے انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے مرسلاً روایت کیا ہے۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہر گفتگو جس کی ابتداء اللہ کی حمد و ثنا سے نہ ہو وہ بے برکت ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو یونس ‘ عقیل ‘ شعیب ‘ اور سعید بن عبدالعزیز نے بواسطہ زہری ‘ نبی کریم صلی اللہ علیہ وسلم سے مرسل روایت کیا ہے۔","f2":"یہ روایت سندَ ا ضعیف ہے۔ تاہم اس کے بعد آنے والی صحیح روایت سے یہ بات واضح ہو رہی ہے کہ اس سے مراد عام گفتگو نہیں بلکہ اہم گفتگو اور خطبہ و تقریر وغیرہ ہے لہذا خطبے کی ابتدا میں حمدوثنا کرنا تاکیدی عمل ہے۔"}],[4841,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر وہ خطبہ جس میں تشہد نہ ہو تو وہ کٹے ہوئے ہاتھ کی طرح ہے (یعنی وہ ناتمام اور ناقص ہے) یا اس ہاتھ کی طرح ہے جس میں جذام ہو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہر وہ خطبہ جس میں تشہد (اللہ کی توحید اور محمد رسول اللہ صلی اللہ علیہ وسلم کی رسالت کا ذکر) نہ ہو ایسے ہے جیسے جذام زدہ (ناقص اور عیب دار) ہاتھ۔ “","f2":"اہم خطبہ، تقریر اور درس کی ابتدا میں تشہد پڑھنا تاکیدی سنت ہے۔"}],[4842,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ان کے پاس سے ایک بھکاری گزرا تو انہوں نے اس کو روٹی کا ایک ٹکڑا دے دیا، پھر ایک شخص کپڑوں میں ملبوس اور معقول صورت میں گزرا تو انہوں نے اسے بٹھایا اور (اسے کھانا پیش کیا) اور اس نے کھایا، لوگوں نے ان سے اس (امتیاز) کی بابت پوچھا تو وہ بولیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے ہر شخص کو اس کے مرتبے پر رکھو ۱؎۔ ابوداؤد کہتے ہیں: یحیی کی حدیث مختصر ہے، اور میمون نے عائشہ رضی اللہ عنہا کو نہیں پایا ہے۔\n§وضاحت\n۱؎ : لوگوں کے ساتھ اس طرح پیش آؤ جیسا کہ ان کے منصب کے شایان شان ہو۔","ضعیف",{"u2":"میمون بن ابوشعیب سے روایت ہے کہ ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کے پاس سے ایک سائل گزرا۔ تو آپ نے اسے ایک روٹی کا ٹکڑا دیا۔ پھر ایک دوسرا آدمی گزرا جس نے (اچھے) کپڑے پہنے ہوئے تھے اور اس کی حالت عمدہ تھی تو انہوں نے اس کو بٹھلا کر کھلایا۔ ان سے اس فرق کے بارے میں پوچھا گیا تو انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے ” ہر شخص کو اس کے مقام پر رکھو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یحییٰ کی حدیث مختصر ہے امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ میمون نے سیدہ عائشہ رضی اللہ عنہا ا کو نہیں پایا ہے۔","f2":"یہ روایت سندَا ضعیف ہے لیکن معنی صحیح ہے۔ ہرشخص کے ساتھ اس کے مقام اور مرتبے کی رعایت سے معاملہ کرنا چاہیئے۔"}],[4843,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"معمر اور سن رسیدہ مسلمان کی اور حافظ قرآن کی جو نہ اس میں غلو کرنے والا ہو ۱؎ اور نہ اس سے دور پڑ جانے والا ہو، اور عادل بادشاہ کی عزت و تکریم دراصل اللہ کے اجلال و تکریم ہی کا ایک حصہ ہے۔\n§وضاحت\n۱؎ : غلو کرنے والے سے مراد ایسا شخص ہے جو قرآن مجید پر عمل کرنے ، اس کے متشابہات کے معانی میں کھوج کرنے نیز اس کی قرات اور اس کے حروف کو مخارج سے ادائیگی میں حد سے تجاوز کرنے والا ہو۔","حسن",{"u2":"سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ بوڑھے مسلمان اور صاحب قرآن کی عزت کرنا جو اس میں غلو اور تقصیر سے بچتا ہو اور (اسی طرح) حاکم عادل کی عزت کرنا ‘ اللہ عزوجل کی عزت کرنے کا حصہ ہے۔ “","f2":"جس شخص کی جوانی اسلام میں گزری ہو اور بڑھاپا آگیا ہو تو وہ بندہ اللہ تعالی کے نزدیک بہت مکرم اور با عزت ہوتا ہے۔ اسلامی معاشرے میں انھیں وقار دیا جانا لازمی ہے۔\n2) صاحبِ قرآن یعنی حافظ، قاری، مدرس، مفسر اور داعی اسلام جو فی الواقع شرعی حدود کے پابند ہوں، تجاوز کریں نہ تقصیر کریں، انکا احترام بھی لازمی ہے۔\n3) حدود اللہ نافذ کرنے والے منصف حاکم کا بھی یہی حق ہے کہ اس کا اعزاز و اکرام کیا جائے۔ ان حضرات کی اہمیت کے پیشِ نظر ہے اللہ عزوجل نے ان کے اعزاز و اکرام کو اپنے اعزاز کا حصہ قرار دیا ہے۔ اور یہ بنا ن بطور تمثیل اور مبالغہ کے ہے۔\n4) یہ روایت بعض محقیقین کے نزدیک حسن درجے کی ہے۔ دیکھئے صحیح الجامع، حدیث 2095"}],[4844,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو آدمیوں کے درمیان گھس کر ان کی اجازت کے بغیر نہ بیٹھا جائے\"۔","حسن",{"u2":"جناب عمرو بن شعیب، اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” دو آدمیوں کے درمیان گھس کر مت بیٹھا جائے سوائے اس کے کہ وہ اجازت دے دیں۔ “"}],[4845,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی شخص کے لیے یہ جائز نہیں کہ وہ دو آدمیوں کے درمیان ان کی اجازت کے بغیر گھس کر دونوں میں جدائی ڈال دے\"۔","حسن صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کسی کیلئے حلال نہیں کہ دو آدمیوں کو جدا جدا کر دے (جو مل کر بیٹھے ہوئے ہوں تو ان میں گھس بیٹھے) الا یہ کہ ان دونوں کی اجازت ہو۔ “","f2":"دو مسلمانوں کے درمیان جو پہلے سے اکٹھے بیٹھے ہوئے ہوں، زور سے گھس بیٹھنا اور ان کے درمیان تفریق کر دینا جائز نہیں، دوبھائیوں کے درمیان پھوٹ ڈال دینا تو اور بھی بڑا جرم ہے۔"}],[4846,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب بیٹھتے تھے تو اپنے ہاتھ سے احتباء کرتے تھے ۱؎۔ ابوداؤد کہتے ہیں: عبداللہ بن ابراہیم ایک ایسے شیخ ہیں جو منکر الحدیث ہیں۔\n§وضاحت\n۱؎ : سرین زمین پر لگا کر دونوں پاؤں کھڑے کر کے اور دونوں ہاتھوں سے پاؤں پر حلقہ بنا کر بیٹھنے کو احتباء کہتے ہیں۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب بیٹھتے تو اپنے گھٹنوں کو سینے سے ملا کر اپنے ہاتھ ان کے گرد لپیٹ لیا کرتے تھے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ سند میں مذکور عبداللہ بن ابراہیم شیخ منکر الحدیث ہے۔"}],[4847,"قیلہ بنت مخرمہ رضی اللہ عنہا نے خبر دی ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا، آپ دونوں ہاتھ سے احتباء کرنے والے کی طرح بیٹھے ہوئے تھے تو جب میں نے رسول اللہ صلی اللہ علیہ وسلم کو بیٹھنے میں «مختشع» اور موسی کی روایت میں ہے «متخشع» ۱؎دیکھا تو میں خوف سے لرز گئی ۲؎۔\n§وضاحت\n۱؎ : ان دونوں لفظوں میں سے پہلا باب افتعال، اور دوسرا باب تفعل سے ہے، دونوں کے معنی عاجزی اور گریہ و زاری کرنے والا ہے۔ ۲؎ : یہ نور الٰہی کا اجلال تھا کہ عاجزی کے باوجود رسول اللہ صلی اللہ علیہ وسلم کا رعب دل میں اتنا زیادہ سما گیا۔","حسن",{"u2":"سیدہ قیلہ بنت مخرمہ رضی اللہ عنہا ا سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ وہ «قرفصاء» کی صورت میں بیٹھے ہوئے تھے (کہ ان کے گھٹنے سینے سے ملے ہوئے اور ہاتھ ان کے گرد لپٹے ہوئے تھے) میں نے جب رسول اللہ صلی اللہ علیہ وسلم کو خشوع اور انکسار کی اس کیفیت میں دیکھا تو خوف سے لرز اٹھی۔","f2":"احتبا ء اور قر فصاء یہاں دونوں کا مفہوم ایک ہی ہے یہ بیٹھنے کا ایک انداز ہے جسکی وضاحت ترجمے میں موجود ہے آدمی اس طرح سے کبھی مجلس میں بھی بیٹھ جاتا ہے۔ اس میں تواضع، انکسار اور خشوع کا اظہار ہوتا ہے۔ مگرخطبہ جمعہ میں ا س طرح بیٹھنا ممنوع ہے۔ دیکھئے: (سنن ابی داؤد، الصلاۃ: حدیث 1110)\n2) حضرت قیلہ رضی اللہ عنہ کا لرزہ براندام ہونا اس تاثر کی وجہ سے تھا کہ جب رسول اللہ صلی اللہ علیہ وسلم جیسی عظیم ہستی کا ظاہری بیٹھنا اس قدر خشوع اور انکسار کا مظہر ہے تو باطنی طور پر آپ صلی اللہ علیہ وسلم کی کیا کیفیت ہو گی اور ہم عام لوگ کس قدر بے پرواہ ہیں۔\n3) اس حدیث سے یہ بھی اخذ کیا گیا کے کہ رسول اللہ صلی اللہ علیہ وسلم با وجود تواضع اور خشوع کے انتہا ئی بارعب اور ہیبت و دبدبہ والے تھے۔ اور یہ سب للہیت اور خشیت کا نتیجہ تھا۔\n4) ہر صاحبِ ایمان کو اپنی نشست و بر خاست میں تواضع کا انداز اختیار کرنا چاہیئے۔ اس سے وقار میں کوئی کمی نہیں آتی بلکہ اضافہ ہی ہوتا ہے۔\n5) مذکورہ دونوں روایات سندََا ضعیف ہیں لیکن دیگر شواہد کی بنا پر حسن یا صحیح درجے تک پہنچ جاتی ہیں جیسا کہ خود ہمارے فاضل محقق نے4846 نمبر حدیث کی تحقیق میں صحیح بخاری کا حوالہ ذکر کرنے کے بعد لکھا ہے کہ وہ یغنی عنہ یعنی بخاری کی روایت اس سے کفایت کرتی ہے۔ علاوہ ازیں شیخ البانی رحمہ اللہ نےپہلی روایت کو صحیح اور دوسری کو حسن قرار دیا ہے۔ تفصیل کے لیئے دیکھئے: (الصحیحة حديث: ٨٦٧ الترمذي حديث ٦٩٧٩)"}],[4848,"شرید بن سوید رضی اللہ عنہ کہتے ہیں کہ میرے پاس سے رسول اللہ صلی اللہ علیہ وسلم گزرے اور میں اس طرح بیٹھا ہوا تھا کہ میں نے اپنا بایاں ہاتھ اپنی پیٹھ کے پیچھے رکھ چھوڑا تھا اور اپنے ایک ہاتھ کی ہتھیلی پر ٹیک لگائے ہوئے تھا، آپ نے فرمایا: \"کیا تم ان لوگوں کی طرح بیٹھتے ہو جن پر غضب نازل ہوا؟\"۔","صحیح",{"u2":"سیدنا شرید بن سوید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرے پاس سے گزرے جب کہ میں اپنا بایاں ہاتھ کمر کے پیچھے کر کے انگوٹھے کی جگہ پر دباؤ ڈال کر بیٹھا ہوا تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تم ان لوگوں کی طرح بیٹھتے ہو جن پر اللہ کا غضب ہوا ہے۔ “","f2":"کمر کے پیچھے زمیں پر ہاتھ کی ٹیک لگا کر بیٹھنا مکروہ ہے۔ اس روایت کو بعض نے صحیح کہا ہے دیکھئے: (حجاب المرا ۃ للبانی 2/100)"}],[4849,"ابوبرزہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عشاء سے پہلے سونے ۱؎ اور اس کے بعد بات کرنے ۲؎ سے منع فرماتے تھے۔\n§وضاحت\n۱؎ : کیونکہ اس میں عشاء چھوٹ جانے کا خطرہ رہتا ہے۔ ۲؎ : اور اس صورت میں قیام اللیل (تہجد) اور فجر کے چھوٹنے کا خطرہ رہتا ہے۔","صحیح",{"u2":"سیدنا ابوبرزہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم منع فرمایا کرتے تھے کہ عشاء کی نماز سے پہلے سویا جائے یا اس کے بعد باتوں میں مشغول رہا جائے۔","f2":"عشاء کی نماز سے پہلے سو جانے سے اندیشہ ہے کہ عشاء کی نماز یا جماعت فوت ہا جائےٓ اور ایسے ہی عشاء کی نماز کے بعد بے مقسد باتوں میں مشغول رہنے سے فجر کی نماز یا جماعت فوت ہونے کا اندیشہ ہوتا ہے۔ ہاں اگر کو ئی اہم مقصد ہو تو مشغول ہونا جائز ہے۔ جیسے کی طلباء کا رات گئے تک مطالعہ یا مذاکرہ کرنا یا دیگر اہم ذمہ داریوں کی ادائیگی کی غرض سے جاگنا جائز ہے مگر شرط یہ ہے کہ فجر کی نماز ضائع نہ ہو۔"}],[4850,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب نماز فجر پڑھ لیتے تو چارزانو (آلتی پالتی) ہو کر بیٹھتے یہاں تک کہ سورج خوب اچھی طرح نکل آتا۔","صحیح",{"u2":"سیدنا جابر بن سمرہ رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم جب فجر کی نماز پڑھا لیتے تو اپنی جگہ پر آلتی پالتی مار کر بیٹھے رہتے , حتیٰ کہ سورج خوب چڑھ آتا۔","f2":"عام حالت میں آلتی پالتی کی حالت میں بیٹھنا جائز ہےحتی کہ مریض اس حالت میں بیٹھ کر نماز پڑھ سکتا ہے۔ مگر کھانے کے لیئے بعض علما ء نے اس طرح بیٹھنے کو مکروہ جانا ہےاور اس کی وجہ ان کے نزدیک یہ ہے کہ اس طرح بیٹھناٹیک لگانے کے ضمن میں آ سکتا ہے اور ٹیک لگا کر کھا نا ممنوع ہے۔\n2) مستحب ہے کی انسان نمازِ فجر کے بعد طلو ع آفتاب تک مسجد میں بیٹھے اور ذکر و تسبیح اور قرآت و قرآن وغیرہ میں مشغول رہے۔"}],[4851,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو آدمی تیسرے کو چھوڑ کر سرگوشی نہ کریں، کیونکہ یہ چیز اسے رنجیدہ کر دے گی\"۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” دو آدمی اپنے تیسرے ساتھی کو چھوڑ کر سرگوشی نہ کریں ‘ اس سے وہ رنجیدہ ہو گا۔ “"}],[4852,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اسی کے مثل فرمایا، ابوصالح کہتے ہیں: میں نے ابن عمر سے کہا: اگر چار آدمی ہوں تو؟ وہ بولے (تو کوئی حرج نہیں) اس لیے کہ یہ چیز تم کو ایذاء نہ دے گی۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور مذکورہ بالا کی مانند بیان کیا۔ ابوصالح کہتے ہیں کہ میں نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا ‘ اگر چار افراد ہوں تو؟ کہا کہ اس میں کوئی حرج نہیں۔","f2":"چار آدمیوں میں دد دد آدمی آپس میں کوئی خاص بات کریں تو یہ کیفیت گوارا ہو سکتی ہے۔ مگر تین میں دو کا تیسرے کو چھوڑ کر آپس میں سرگوشی کرنا یا کسی ایسی زبان میں بات کرنا جو اس کی سمجھ میں نہ آتی ہو اس کے لیئے ازحد کلفت کا باعث ہوگی اور یہ صور ت اس تیسرے کی عزت و کرامت کے خلاف بھی ہے۔"}],[4853,"سہیل بن ابی صالح کہتے ہیں کہ میں اپنے والد کے پاس بیٹھا ہوا تھا، ان کے پاس ایک لڑکا تھا، وہ اٹھ کر گیا پھر واپس آیا، تو میرے والد نے بیان کیا کہ ابوہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے فرمایا: \"جب آدمی ایک جگہ سے اٹھ کر جائے پھر وہاں لوٹ کر آئے تو وہی اس (اس جگہ بیٹھنے) کا زیادہ مستحق ہے\"۔","صحیح",{"u2":"جناب سہیل بن ابی صالح کہتے ہیں کہ میں اپنے والد کے پاس بیٹھا ہوا تھا ‘ ان کے پاس ایک غلام بھی تھا۔ تو وہ اٹھ کر گیا اور پھر واپس آ گیا تو میرے والد نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شخص اپنی جگہ سے اٹھ کر جائے اور پھر واپس لوٹ آئے تو وہی اس جگہ کا زیادہ حقدار ہے۔ “","f2":"یہ حکم علمی اور خاص حلقات کا معلوم ہوتا ہے جہاں لوگ اہتمام سے باقاعدہ بیٹھتے ہیں۔ عام اجتماعات میں اگر کوئی جاکر واپس آنا چاہتا ہو تو اسے چاہیئے کہ اپنی جگہ پر کوئی علامت چھوڑ جائے۔ جیسا کہ درج ذیل روایت میں آرہا ہے۔"}],[4854,"کعب الایادی کہتے ہیں کہ میں ابو الدرداء کے پاس آتا جاتا تھا تو ابو الدرداء نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب بیٹھتے اور ہم آپ کے اردگرد بیٹھتے تو آپ (کسی کام سے جانے کے لیے) کھڑے ہوتے اور لوٹنے کا ارادہ ہوتا تو اپنی جوتیاں اتار کر رکھ جاتے یا اور کوئی چیز رکھ جاتے جو آپ کے پاس ہوتی، اس سے آپ کے اصحاب سمجھ لیتے تو وہ ٹھہرے رہتے۔","ضعیف",{"u2":"جناب کعب ایادی رضی اللہ عنہ کہتے ہیں کہ میں سیدنا ابودرداء رضی اللہ عنہ کے ہاں آیا جایا کرتا تھا۔ تو سیدنا ابودرداء رضی اللہ عنہ نے بیان کیا کہ جب رسول اللہ صلی اللہ علیہ وسلم (کسی جگہ) تشریف فر ہوتے اور ہم بھی آپ صلی اللہ علیہ وسلم کے اردگرد بیٹھ جاتے ‘ تو اگر آپ صلی اللہ علیہ وسلم اٹھ کر جاتے اور واپس آنے کا ارادہ رکھتے تو اپنا جوتا یا جو کچھ آپ پر (کپڑا وغیرہ) ہوتا ‘ وہاں چھوڑ جاتے ‘ اس سے صحابہ کرام رضی اللہ عنہم م آپ صلی اللہ علیہ وسلم کے واپس آنے کے متعلق جان جاتے اور بیٹھے رہتے۔"}],[4855,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو لوگ بھی بغیر اللہ کو یاد کئے کسی مجلس سے اٹھ کھڑے ہوتے ہوں تو وہ ایسی مجلس سے اٹھے ہوتے ہیں جو بدبو میں مرے ہوئے گدھے کی لاش کی طرح ہوتی ہے، اور وہ مجلس ان کے لیے(قیامت کے روز) باعث حسرت ہو گی\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو لوگ کسی مجلس سے اٹھیں اور انہوں نے اس میں ا اللہ کا ذکر نہ کیا ہو ‘ تو وہ ایسے ہیں گویا کسی مردار گدھے پر سے اٹھے ہوں اور (آخرت میں) یہ مجلس ان کے لیے حسرت کا باعث ہو گی (تمنا کریں گے کاش کہ ہم نے اس میں ا اللہ کا ذکر کر لیا ہوتا)۔ “"}],[4856,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی جگہ بیٹھے اور اس میں وہ اللہ کا ذکر نہ کرے، تو یہ بیٹھک اللہ کی طرف سے اس کے لیے باعث حسرت و نقصان ہو گی اور جو کسی جگہ لیٹے اور اس میں اللہ کو یاد نہ کرے تو یہ لیٹنا اس کے لیے اللہ کی طرف سے باعث حسرت و نقصان ہو گا\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص کسی جگہ یا مجلس میں بیٹھا ہو اور اس میں اس نے ا اللہ کا ذکر نہ کیا ہو ‘ تو یہ اس کے لیے ا اللہ کی طرف سے بہت نقصان کا باعث ہو گی۔ اور جو کوئی کسی جگہ لیٹا ہو اور اس میں اس نے ا اللہ کا ذکر نہ کیا ہو ‘ تو یہ اس کے لیے ا اللہ کی طرف سے بہت نقصان کا باعث ہو گی۔ “","f2":"مومنین مخلصین کا خاص وصف یہی ہے کہ وہ ہمیشہ اللہ کا ذکر کرنے والے ہوتے ہیں، جیسا کہ ارشادِ باری تعالیٰ ہے جو لوگ اُٹھتے بیٹھتے اور اپنے پہلوؤں کے بل لیٹے ہو ئے اللہ کو یاد کرتے ہیں اور آسمانوں زمیں کی خلقت میں تفکر و تدبر کرتے رہتے ہیں (آلِ عمران: 191) اس کے معنی یہ بھی نہیں کہ بندہ اپنے لازمی واجبات سے پہلو تہی کر کے بس تسبیح لیئے بیٹھا رہے، بلکہ سنتِ نبوی کے مطابق مو قع بموقع مسنون دُعائیں پڑھتے رہنا ہی ذکرِ کثیر ہے۔"}],[4857,"عبداللہ بن عمرو بن عاص رضی اللہ عنہما کہتے ہیں کہ تین کلمے ایسے ہیں جنہیں کوئی بھی مجلس سے اٹھتے وقت تین مرتبہ پڑھے تو یہ اس کے لیے (ان گناہوں کا جو اس مجلس میں اس سے ہوئے) کفارہ بن جاتے ہیں، اور اگر انہیں نیکی یا ذکر الٰہی کی مجلس میں کہے گا تو وہ مانند مہر کے ہوں گے جیسے کسی تحریر یا دستاویز پر اخیر میں مہر ہوتی ہے اور وہ کلمات یہ ہیں «سبحانك اللهم وبحمدك لا إله إلا أنت أستغفرك وأتوب إليك» \"اے اللہ! تو پاک ہے، اور تو اپنی ساری تعریفوں کے ساتھ ہے، نہیں ہے معبود برحق مگر تو ہی اور میں تجھی سے مغفرت طلب کرتا ہوں اور تیری ہی طرف رجوع کرتا ہوں\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ نے فرمایا چند کلمات ہیں جو کوئی انہیں اپنی مجلس سے اٹھتے ہوئے تین بار پڑھ لے تو یہ اس کے لیے کفارہ بن جائیں گے ‘ اور جو کوئی انہیں اپنی اس مجلس کے دوران میں پڑھ لے ‘ وہ مجلس خیر کی ہو یا ذکر کی تو یہ اس کے لیے ایسے ہوں گے جیسے کسی تحریر کو مہر بند کر دیا گیا ہو (اس کے لیے اس کا اجر اور گناہوں کا کفارہ ہونا محفوظ ہو گا۔ وہ کلمات یہ ہیں) «سبحانك اللهم وبحمدك لا إله إلا أنت أستغفرك وأتوب إليك» ” اے ا اللہ! تو اپنی تعریفوں سمیت پاک ہے ‘ تیرے سوا کوئی معبود نہیں ‘ میں تجھ سے اپنے گناہوں کی معافی مانگتا ہوں اور میں تیری ہی طرف رجوع کرنے والا ہوں۔ “","f2":"اس روایت میں مذکورہ دُعا کو تین بار پڑھنے کی شرط صحیح نہیں(علامہ البانی رحمہ اللہ) بلکہ ایک ہی بار پڑھنے سے مذکورہ فضیلت حاصل ہوجاتی ہے۔"}],[4858,"ابوہریرہ رضی اللہ عنہ بھی نبی اکرم صلی اللہ علیہ وسلم سے اسی کے مثل روایت کرتے ہیں۔","صحیح",{"u2":"عبدالرحمٰن بن ابو عمرو نے بواسطہ مقبری سیدنا ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالاحدیث کی مانند بیان کیا۔"}],[4859,"ابوبرزہ اسلمی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب مجلس سے اٹھنے کا ارادہ کرتے، تو آخر میں فرماتے: «سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك» تو ایک شخص نے عرض کیا: اللہ کے رسول! آپ اب ایک ایسا کلمہ کہتے ہیں جو پہلے نہیں کہا کرتے تھے، آپ نے فرمایا: \"یہ کفارہ ہے ان (لغزشوں) کا جو مجلس میں ہو جاتی ہیں\"۔","حسن صحیح",{"u2":"سیدنا ابوبرزہ اسلمی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے آخری ایام میں جب کسی مجلس سے اٹھتے تو یہ کلمات کہتے تھے «سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك» ایک آدمی نے آپ صلی اللہ علیہ وسلم سے پوچھ لیا کہ اے ا اللہ کے رسول! آپ یہ کلمات کہتے ہیں جو پہلے نہیں کہا کرتے تھے (اس کی کیا وجہ ہے؟) آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ اس چیز کے کفارے کے لیے ہے جو مجلس میں ہو جاتی ہے۔ “","f2":"رسول اللہ صلی اللہ علیہ وسلم تو بے مقصد گفتگو سے مبرا تھے آپکا یہ عمل اُمت کے لیئے تعلیم تھالہذا ہر مسلمان کو اس مبارک ورد کا عامل ہونا چاہیے۔ نیز اپنی مجالس کو لغویات سے پاک رکھنے کی ہر ممکن کوشش کرنی چاہیئے کہ ان میں غیبت، تہمت جھوٹ قیل و قال اور قہقے نہ ہوں۔ اور یہ سمجھ کر کہ میں آخر میں دُعائے کفارہ مجلس پڑھ لونگا جو جی چاہے کہتا اور کرتا رہے ناجائز ہےنہ معلوم دُعا کا مو قع ملے نہ ملے اور پھر قبول ہو یا نا۔"}],[4860,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے صحابہ میں سے کوئی کسی کے بارے میں کوئی شکایت مجھ تک نہ پہنچائے، اس لیے کہ میں چاہتا ہوں کہ میں (گھر سے) نکل کر تمہاری طرف آؤں، تو میرا سینہ صاف ہو (یعنی کسی کی طرف سے میرے دل کوئی میں کدورت نہ ہو) ۔","ضعیف",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کوئی شخص مجھے میرے صحابہ کی بابت کوئی بات نہ پہنچائے۔ میں چاہتا ہوں کہ میں تمہارے پاس آؤں ‘ تو میرا سینہ صاف ہو (کسی کے متعلق میرے دل میں کدورت نہ ہو)۔ “","f2":"انسان کو جب کسی اپنے پرائے کی کو ئی غلط بات پہنچتی ہے تو وہ اس سے متاثر ہوئے بغیر نہیں رہ سکتا۔ زبان یا عمل سے خواہ اسکا اظہار نہ بھی کرے مگر دل میں ضرور اسکا اثر ہوتا ہے۔ اس لئے بلا وجہِ معقول کسی کی غلط بات دوسرے کے سامنے نہیں کرنی چاہیئے۔ ہاں اگر شرعی ضرورت ہو۔ مثلاَ کسی واسطے سے اسکی نصیحت اور اصلاح مقصود ہو یا کسی کو متنبہ رکھنا مقصود ہو تا جائز ہے۔ یا وہ ازحد فاسق، فاجر اور ظالم ہو۔ قرآن مجید میں ارشادِ باری تعالی ہے: برائی کے ساتھ آواز بلند کرنے کو اللہ تعالی پسند نہیں فرماتا مگر مظلوم کو اجازت ہے (النساء 148) علمائے اخلاق لکھتے ہیں کہ جو آدمی آپکے سامنے دوسروں پر تبصرے کرتا اور ان ی باتیں نقل کرتا ہے غالب گمان ہے کہ وہ آپکے متعلق بھی دوسروں کے ہاں باتیں کرتا ہوگااس لیئے ایسے آدمی کی اس عادت کی حوصلہ افزائی نہیں کرنی چاہییے۔"}],[4861,"عمرو بن فغواء خزاعی رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے بلایا، آپ مجھے کچھ مال دے کر ابوسفیان کے پاس بھیجنا چاہتے تھے، جو آپ فتح مکہ کے بعد قریش میں تقسیم فرما رہے تھے، آپ نے فرمایا: \"کوئی اور ساتھی تلاش کر لو\"، تو میرے پاس عمرو بن امیہ ضمری آئے، اور کہنے لگے: مجھے معلوم ہوا ہے کہ تمہارا ارادہ نکلنے کا ہے اور تمہیں ایک ساتھی کی تلاش ہے، میں نے کہا: ہاں، تو انہوں نے کہا: میں تمہارا ساتھی بنتا ہوں چنانچہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور میں نے عرض کیا، مجھے ایک ساتھی مل گیا ہے، آپ نے فرمایا: \"کون؟\" میں نے کہا: عمرو بن امیہ ضمری، آپ نے فرمایا: \"جب تم اس کی قوم کے ملک میں پہنچو تو اس سے بچ کے رہنا اس لیے کہ کہنے والے نے کہا ہے کہ تمہارا سگا بھائی ہی کیوں نہ ہو اس سے مامون نہ رہو\"، چنانچہ ہم نکلے یہاں تک کہ جب ہم ابواء میں پہنچے تو اس نے کہا: میں ودان میں اپنی قوم کے پاس ایک ضرورت کے تحت جانا چاہتا ہوں لہٰذا تم میرے لیے تھوڑی دیر ٹھہرو، میں نے کہا: جاؤ راستہ نہ بھولنا، جب وہ چلا گیا تو مجھے رسول اللہ صلی اللہ علیہ وسلم کی بات یاد آئی، تو میں نے زور سے اپنے اونٹ کو بھگایا، اور تیزی سے دوڑاتا وہاں سے نکلا، یہاں تک کہ جب مقام اصافر میں پہنچا تو دیکھا کہ وہ کچھ لوگوں کے ساتھ مجھے روکنے آ رہا ہے میں نے اونٹ کو اور تیز کر دیا، اور میں اس سے بہت آگے نکل گیا، جب اس نے مجھے دیکھا کہ میں اسے بہت پیچھے چھوڑ چکا ہوں، تو وہ لوگ لوٹ گئے، اور وہ میرے پاس آیا اور بولا، مجھے اپنی قوم میں ایک کام تھا، میں نے کہا: ٹھیک ہے اور ہم چلتے رہے یہاں تک کہ ہم مکہ پہنچ گئے تو میں نے وہ مال ابوسفیان کو دے دیا۔","ضعیف",{"u2":"جناب عبداللہ بن عمرو بن فغواء خزاعی اپنے والد سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے بلوایا۔ جب کہ آپ صلی اللہ علیہ وسلم مجھے کچھ مال دے کر مکہ میں سیدنا ابوسفیان رضی اللہ عنہ کے ہاں بھیجنا چاہ رہے تھے جو وہ اہل قریش میں تقسیم کر دیتا اور یہ فتح مکہ کے بعد کا واقعہ ہے۔ آپ صلی اللہ علیہ وسلم نے مجھے فرمایا ” کوئی رفیق سفر ڈھونڈ لو۔ “ چنانچہ عمرو بن امیہ ضمری میرے پاس آیا اور کہا سنا ہے کہ تم مکے جانا چاہتے ہو اور رفیق سفر کی تلاش میں ہو۔ میں نے کہا: ہاں۔ اس نے کہا: میں تمہارے ساتھ چلوں گا۔ چنانچہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا کہ میں نے رفیق سفر ڈھونڈ لیا ہے۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کون؟ “ میں نے بتایا کہ عمرو بن امیہ ضمری۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” جب تم اس کی قوم کے علاقے میں اترو تو ہوشیار رہنا۔ “ کہنے والے نے کہا ہے کہ بکری (با کے زیر کے ساتھ) تیرا بھائی ہے مگر اس پر اعتماد نہ کرنا۔ چنانچہ ہم نکل پڑے۔ حتیٰ کہ جب میں ابواء مقام پر پہنچا تو اس نے مجھ سے کہا کہ مجھے اپنی قوم سے ایک کام ہے میں ودان جا رہا ہوں تم یہاں رک کر میرا انتظار کرنا۔ میں نے کہا: خیر سلامتی سے جاؤ۔ جب وہ روانہ ہوا تو مجھے نبی کریم صلی اللہ علیہ وسلم کا فرمان یاد آیا تو میں اپنے اونٹ پر سوار ہو لیا اور اسے بھگاتا ہوا اصافر تک جا پہنچا۔ تو اچانک دیکھتا ہوں کہ امیہ اپنی قوم کے کچھ لوگوں کے ساتھ میرے آڑے آ گیا ہے۔ چنانچہ میں نے اپنا اونٹ اور تیز بھگایا حتیٰ کہ ان سے آگے نکل گیا۔ جب انہوں نے دیکھا کہ میں ان کے ہاتھوں سے نکل گیا ہوں تو وہ واپس ہو گئے۔ پھر وہ (اکیلا) میرے پاس آیا اور کہنے لگا کہ مجھے اپنی قوم کے ہاں ایک کام تھا۔ میں نے کہا: ہو گا۔ حتیٰ کہ ہم مکہ آ گئے اور میں نے وہ مال سیدنا ابوسفیان رضی اللہ عنہ کے حوالے کر دیا۔","f2":"یہ روایت سندَا ضعیف ہےتاہم اس میں بیان کردہ کئی باتیں صحیح احادیث سے ثابت ہیں۔ مثلاََ سفر میں ساتھی ضرور ہونا چاہیئے۔ اکیلے سفر کرنا خطرات سے خالی نہیں۔\n2) مخلص ساتھی کے سوا ہر کسی کو اپنا راز دینا اور اس پر کلی بھروسہ کرلینا بھی روا نہیں۔\n3) صدقات اور بیت المال سے نئے مسلمانوں کی تالیف قلب ہوتی رہنی چاہیئے تا کہ وہ اسلام میں راسخ ہو جائیں۔\n4) مصلحت کے پیشِ نظر ایک شہر کے صدقات دوسرے شہروں میں منتقل کرنا جائز ہے۔"}],[4862,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مومن ایک سوراخ سے دو بار نہیں ڈسا جاتا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” مومن ایک بل سے دوبار نہیں ڈسا جاتا۔ “","f2":"آزمائے ہوئے کو آزمانا بہت بڑی غلطی ہے۔"}],[4863,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب چلتے تو ایسا لگتا گویا آپ آگے کی جانب جھکے ہوئے ہیں (جیسے کوئی اونچے سے نیچے کی طرف اتر رہا ہو) ۔","صحیح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب چلتے تو ایسے لگتا جیسے آگے کو جھکے جاتے ہوں۔","f2":"یعنی متواضعانہ انداز سے چلتے بخلاف متکبر لوگوں کی چال کے، کہ وہ سینہ نکال کر اکڑ کر چلتے ہیں۔"}],[4864,"سعید جریری کی روایت ہے کہ ابوالطفیل رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا، سعید کہتے ہیں کہ میں نے کہا: آپ کو کیسا دیکھا؟ وہ کہا: آپ گورے خوبصورت تھے جب چلتے تو ایسا لگتا گویا آپ نیچی جگہ میں اتر رہے ہیں۔","صحیح",{"u2":"سیدنا ابوطفیل (عامر بن واثلہ رضی اللہ عنہ) کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا تھا۔ سعید جریری نے ان سے پوچھا کہ آپ نے ان کو کیونکر دیکھا؟ انہوں نے کہا: آپ سفید رنگ اور انتہائی خوبصورت تھے اور جب چلتے تھے تو لگتا تھا کہ اوپر سے نیچے کو اتر رہے ہیں۔","f2":"طاقت ورصحت مند اور چاق و چوبند آدمیوں کی چال بالعموم ایسے ہی ہوا کرتی ہے۔ تواضع کے نام سے ایسی ڈھیلی ڈھیلی چال چلنا گویا کوئی،مریض جا رہا ہوممدوح (پسندیدہ) نہیں ہے۔"}],[4865,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ آدمی اپنا ایک پاؤں دوسرے پر رکھے۔ قتیبہ کی روایت میں«أن يضع» کے بجائے «أن يرفع» کے الفاظ ہیں، اور قتیبہ کی روایت میں یہ بھی زیادہ ہے \"اور وہ اپنی پیٹھ کے بل چت لیٹا ہو\"۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ آدمی اپنی ٹانگ پر ٹانگ رکھے۔ قتیبہ کی روایت میں اضافہ ہے کہ جب وہ چٹ لیٹا ہوا ہو۔","f2":"کیونکہ اس میں بے پردگی کا اندیشہ ہوتا ہے اور مجلس میں دوسروں کے سامنے ایسا عمل ویسے ہی برا لگتا ہے۔ تاہم اسکا جواز بھی ہے، با لخصوص جب بے پردگی کا اندیشہ نہ ہو۔ جیسے کہ درجِ ذیل روایات میں آرہا ہے۔"}],[4866,"عباد بن تمیم اپنے چچا (عبداللہ بن زید بن عاصم رضی اللہ عنہ) سے روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو مسجد میں ایک پیر کو دوسرے پیر پر رکھے ہوئے چت لیٹے دیکھا ۱؎۔\n§وضاحت\n۱؎ : اس حدیث میں اور اس سے پہلے والی حدیث میں بظاہر تعارض ہے ، تطبیق کی صورت یہ ہے کہ ممانعت اس صورت میں ہے جب لنگی ( ازار ) تنگ ہو ، اور ایسا کرنے سے ستر کھلنے کا اندیشہ ہو ، اور اگر ازار کشادہ ہو ، اور ستر کھلنے کا اندیشہ نہ ہو تو درست ہے ، یا دونوں پیر پھیلا کر ایسا کرنا درست ہے ، کیونکہ اس صورت میں ستر کھلنے کا اندیشہ نہیں رہتا ، البتہ ایک پیر کو کھڑا کر کے دوسرے کو کھڑے پر رکھنا درست نہیں کیونکہ اس میں ستر کھلنے کا اندیشہ رہتا ہے۔","صحیح",{"u2":"جناب عباد بن تمیم اپنے چچا (عبداللہ بن زید بن عاصم انصاری رضی اللہ عنہ) سے روایت کرتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا جب کہ آپ صلی اللہ علیہ وسلم چت لیٹے ہوئے تھے۔ قعنبی نے کہا: مسجد میں لیٹے ہوئے تھے اور آپ اپنی ایک ٹانگ دوسری پر رکھے ہوئے تھے۔"}],[4867,"سعید بن مسیب کہتے ہیں کہ عمر بن خطاب اور عثمان بن عفان رضی اللہ عنہما بھی اسے کیا کرتے تھے۔","صحیح الإسناد عن عثمان",{"u2":"جناب سعید بن مسیب رضی اللہ عنہ سے مروی ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ اور سیدنا عثمان بن عفان رضی اللہ عنہ ایسے کر لیا کرتے تھے (لیٹنے کی حالت میں اپنی ایک ٹانگ پر دوسری رکھ لیا کرتے تھے)۔"}],[4868,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب کوئی شخص کوئی بات کرے، پھر ادھر ادھر مڑ مڑ کر دیکھے تو وہ امانت ہے (اسے افشاء نہیں کرنا چاہیئے)\"۔","حسن",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب کوئی تم سے بات کرتے ہوئے ادھر ادھر سے چوکنا ہو رہا ہو (کہ کہیں کوئی سنتا تو نہیں) تو یہ بات امانت ہے۔ “","f2":"مسلمان کو از حد دانا ہونا چاہیئے۔ جب آپکا بھائی آپ سے بات کرتے ہوئے ادھر ادھر دیکھ رہا ہو تو یہ اشارہ ہوتا ہے کہ یہ خاص بات ہےجس کی آپ نے حفاظت کرنی ہے اور یہ امانت ہے اسے آگے نقل نہیں ہونا چاہیئے۔"}],[4869,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجلسیں امانت داری کے ساتھ ہیں (یعنی ایک مجلس کی بات دوسری جگہ جا کر بیان نہیں کرنی چاہیئے) سوائے تین مجلسوں کے، ایک جس میں ناحق خون بہایا جائے، دوسری جس میں بدکاری کی جائے اور تیسری جس میں ناحق کسی کا مال لوٹا جائے ۱؎\"۔\n§وضاحت\n۱؎ : ان تینوں صورتوں میں سننے والے کے لئے اس کا چھپانا جائز نہیں، بلکہ اس کا افشاء برائی کے دفعیہ کے لیے ضروری ہے۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مجالس امانت کے ساتھ ہیں۔ سوائے تین مجلسوں کے جن میں ناحق خون بہانے ‘ یا ناحق فحش کاری ‘ یا ناحق مال مارنے کی بات ہو۔ “","f2":"یہ روایت ضعیف ہے۔ مگر حکمت و اخلاق اور دوسرے دلائل کو تقاضا یہی ہے کہ مجلسِ مشاورت میں ہونے والی گفتگو راز اور امانت ہوتی ہے۔ اس کی حفاظت کرنا اصحابِ مجلس پر لازم ہے الا یہ کہ کسی کی جان و مال اور عزت لوٹنے کی بات ہو تو ایسے رازوں کو راز رکھنا حرام ہے۔"}],[4870,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے دن اللہ کے نزدیک سب سے بڑی امانت یہ ہے کہ مرد اپنی بیوی سے خلوت میں ملے اور وہ (بیوی) اس سے ملے پھر وہ (مرد) اس کا راز فاش کرے\"۔","ضعیف",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ا اللہ کے نزدیک قیامت کے روز امانت میں یہ بات بہت بڑی خیانت شمار ہو گی کہ مرد اپنی بیوی کے اور بیوی اپنے شوہر کے قریب ہو اور پھر اس کے راز کو افشا کر دے۔ “","f2":"اللہ عزوجل نے میاں بیوی کو ایک دوسرے کا لباس بنایا ہے تو انکا آپس کے رازوں کو دوسروں کے سامنے افشاہ کردینا بہت قبیح عمل ہے۔سوائے اس کے کہ کسی شرعی ضرورت کے تحت قاضی وغیرہ کے سامنے کوئی بات کہنی پڑے۔"}],[4871,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چغل خور جنت میں داخل نہیں ہو گا\"۔\n§وضاحت\n۱؎ : سب سے پہلے اس گناہ کی سزا میں پہلے داخل جہنم ہو گا، اور سزا بھگت کر موحد ہونے کی صورت میں جنت کا مستحق ہو گا۔","صحیح",{"u2":"سیدنا حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” چغل خور جنت میں نہیں جائے گا۔ “","f2":") لوگوں میں فساد ڈالنے کی غرض سے ایک دوسرے کی باتیں ادھر ادھر نقل کرنا بدترین خصلت ہے۔ لوگوں کے نزدیک بھی اور اللہ کے ہاں بھی۔\n2) اس طرح کی احادیث عموما ایسے ہی بیان کرنی چاہیئںتاہم نص قرآنی سے ثابت ہے کہ جنت صرف مشرک پر حرام ہےلیکن بطور سزا کے مسلمان بھی جہنم کا عذاب بھگتیں گے۔ اس لیئے بعض اعمال کی بابت جو آتا ہے کہ اس کا مرتکب جنت میں نہیں جائے گا تو اس کے معنی یہ ہوتے ہیں کہ ابتدائی طور پر جنت میں داخل نہیں کیا جائے گا۔ البتہ سزا اور عتاب کے بعد جنت میں جائے گا۔\n3) عربی زبان میں(قتات) اور (نمام) میں فرق یہ کیا جاتا ہے کہ (نمام) مجلس میں حاضر رہ کر وہاں کی باتیں دوسروں کو جا بتاتا ہے جبکہ (قتات) چوری چھپے سن کر نقل کرتا ہے۔"}],[4872,"ابوہریرہ رضی اللہ عنہ کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں میں برا وہ شخص ہے جو دورخا ہو، اِن کے پاس ایک منہ لے کر آتا ہو اور ان کے پاس دوسرا منہ لے کر جاتا ہو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بدترین ہے وہ آدمی جو دو رخا ہو کہ ان کے پاس جائے تو ایک منہ ہو ‘ دوسروں کے پاس جائے تو دوسرا منہ۔ “"}],[4873,"عمار رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کے دنیا میں دو رخ ہوں گے قیامت کے دن اس کے لیے آگ کی دو زبانیں ہوں گی\"۔","صحیح",{"u2":"سیدنا عمار بن یاسر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس کے دنیا میں دو منہ ہوئے (جو آدمی دو رخا ہوا) قیامت کے روز اس کی دو زبانیں ہوں گی جو آگ کی ہوں گے۔ “","f2":"ایسے لوگ اپنی سمجھ میں بڑے دانا بننے کی کوشش کرتے ہیں اور اپنے آپ کو مصلحت کیش باور کراتے ہیں جبکہ حقیقت یہ ہے کہ یہ لوگ انتہائی بزدل اور پستی میں گرے ہوئے ہوتے ہیں۔ ان کو ابن الوقت اور منافق کہتے ہیں قرآن مجید کی ابتدا میں کفار کی مذمت میں صرف دو آئتیں(البقرہ6،7) ہیں مگر مصلحت کیش منافقین کی مذمت میں تیرہ آیتئں مذکور ہیں۔ دیکھئے (البقرہ: از آیت نمبر 8 تا 20)"}],[4874,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ عرض کیا گیا: اللہ کے رسول! غیبت کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا اپنے بھائی کا اس طرح ذکر کرنا کہ اسے ناگوار ہو\" عرض کیا گیا: اور اگر میرے بھائی میں وہ چیز پائی جاتی ہو جو میں کہہ رہا ہوں تو آپ کا کیا خیال ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ چیز اس کے اندر ہے جو تم کہہ رہے ہو تو تم نے اس کی غیبت کی، اور اگر جو تم کہہ رہے ہو اس کے اندر نہیں ہے تو تم نے اس پر بہتان باندھا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: اے ا اللہ کے رسول! غیبت کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تمہارا اپنے بھائی کا ایسے انداز میں ذکر کرنا جسے وہ ناپسند کرتا ہو۔ “ کہا گیا: جو بات میں کہہ رہا ہوں اگر وہ میرے بھائی میں (فی الواقع) ہو؟ (تو بھی وہ غیبت ہو گی؟) آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر اس میں وہ بات موجود ہو اور تم کہو ‘ تب ہی تو غیبت ہے۔ اگر تم کوئی ایسی بات کہو جو اس میں نہ ہو ‘ تو تم نے اس پر بہتان لگایا۔ “"}],[4875,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے عرض کیا: آپ کے لیے تو صفیہ رضی اللہ عنہا کا یہ اور یہ عیب ہی کافی ہے، یعنی پستہ قد ہونا تو آپ نے فرمایا: \"تم نے ایسی بات کہی ہے کہ اگر وہ سمندر کے پانی میں گھول دی جائے تو وہ اس پر بھی غالب آ جائے\" اور میں نے ایک شخص کی نقل کی تو آپ نے فرمایا: \"مجھے یہ بات پسند نہیں کہ میں کسی انسان کی نقل کروں اگرچہ میرے لیے اتنا اور اتنا (مال) ہو\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کہہ دیا: آپ کو صفیہ رضی اللہ عنہا ا میں یہی کافی ہے کہ وہ ایسے ایسے ہے، مسدد کے علاوہ دوسرے نے وضاحت کی کہ اس سے ان کی مراد سیدہ صفیہ رضی اللہ عنہا ا کا پستہ قد ہونا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم نے ایسا کلمہ کہا ہے کہ اگر اسے سمندر میں ملا دیا جائے تو کڑوا ہو جائے۔ “ سیدہ عائشہ رضی اللہ عنہا ا کہتی ہیں کہ میں نے آپ صلی اللہ علیہ وسلم کے سامنے کسی کی نقل اتاری تو آپ صلی اللہ علیہ وسلم نے فرمایا ” میں کسی کی نقل اتارنا پسند نہیں کرتا ‘ خواہ مجھے اتنا اتنا مال بھی ملے۔ “","f2":"کسی کی فطری خلقت پر عیب لگانا اور تمسخر اور ٹھٹھا کرنا حرام ہے- یہ گو یا اللہ عزوجل پر عیب لگانا اور اپنی بڑائی کا اظہار ہے۔ جب فطری امور پر عیب لگانا حرام ہے تو اعمال پر تبصرہ بھی جائز نہیں الا یہ کہ کوئی مصیبت کا عمل ہو تا کہ عبرت ہو۔ اگر اس نے توبہ کرلی ہو تو ذکر کرنا بالا ولٰی جائز نہیں۔ البتہ اعمالِ خیر کا ذکر جائز ہے۔"}],[4876,"سعید بن زید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سب سے بڑی زیادتی یہ ہے کہ آدمی ناحق کسی مسلمان کی بے عزتی کرے\"۔","صحیح",{"u2":"سیدنا سعید بن زید رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” سب سے بڑا سود (سب سے بڑی زیادتی) یہ ہے کہ انسان ناحق کسی کی عزت سے کھیلے۔“","f2":"جس طرح معا ملاتِ تجارت میں سود حرام ہےاسی طرح اپنے مسلمان بھائی کی بےعزتی اور بے ادبی کرنا بھی حرام ہے۔"}],[4877,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بڑے گناہوں میں سب سے بڑا گناہ یہ ہے کہ آدمی ناحق کسی مسلمان کی بے عزتی میں زبان دراز کرے، اور یہ بھی کبیرہ گناہوں میں سے ہے کہ ایک گالی کے بدلے دو گالیاں دی جائیں\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بیشک کبیرہ گناہوں میں ایک بڑا کبیرہ گناہ یہ ہے کہ انسان اپنے مسلمان بھائی کی ناحق ہتک اور توہین کر دے۔ کبیرہ گناہوں میں یہ بھی ہے کہ کوئی ایک کے بدلے دو گالیاں دے۔","f2":"یہ روایت ضعیف ہے۔ تاہم یہ افعال با اعتبارِ شریعیت اور اخلاق ہر طرح سے مذموم ہیں۔"}],[4878,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب مجھے معراج کرائی گئی، تو میرا گزر ایسے لوگوں پر سے ہوا، جن کے ناخن تانبے کے تھے اور وہ ان سے اپنے منہ اور سینے نوچ رہے تھے، میں نے پوچھا: جبرائیل! یہ کون لوگ ہیں؟ کہا: یہ وہ ہیں جو لوگوں کا گوشت کھاتے (غیبت کرتے) اور ان کی بے عزتی کرتے تھے\"۔ ابوداؤد کہتے ہیں: ہم سے اسے یحیی بن عثمان نے بیان کیا ہے اور بقیہ سے روایت کر رہے تھے، اس میں انس موجود نہیں ہیں۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب مجھے معراج کرائی گئی تو میرا گزر ایک ایسی قوم پر ہوا جن کے ناخن تانبے کے تھے جو اپنے چہروں اور سینوں کو چھیل رہے تھے۔ میں نے پوچھا: اے جبرائیل! یہ کون لوگ ہیں؟ انہوں نے کہا: یہ وہ ہیں جو دوسرے لوگوں کا گوشت کھاتے اور ان کی عزتوں سے کھیلتے ہیں۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: اس روایت کو یحییٰ بن عثمان نے بقیہ سے روایت کیا مگر اس میں سیدنا انس رضی اللہ عنہ کا ذکر نہیں (مرسل روایت کیا)۔","f2":"مسلمان کی غیبت کرنا یا چھوٹی سطح کے مسلمانوں کی عزت و توقیر کو ملحوظ نہ رکھناسخت خطرناک ہے۔"}],[4879,"ابومغیرہ سے بھی اسی طرح مروی ہے جیسا کہ ابن مصفی نے روایت کیا ہے۔","",{"u2":"عیسیٰ بن ابی عیسیٰ السیلحینی نے ابومغیرہ سے اسی طرح روایت کیا جیسے کہ (مذکورہ بالا حدیث میں) ابن مصفٰی نے کہا۔"}],[4880,"ابوبرزہ اسلمی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے وہ لوگو! جو ایمان لائے ہو اپنی زبان سے اور حال یہ ہے کہ ایمان اس کے دل میں داخل نہیں ہوا ہے مسلمانوں کی غیبت نہ کرو اور ان کے عیوب کے پیچھے نہ پڑو، اس لیے کہ جو ان کے عیوب کے پیچھے پڑے گا، اللہ اس کے عیب کے پیچھے پڑے گا، اور اللہ جس کے عیب کے پیچھے پڑے گا، اسے اسی کے گھر میں ذلیل و رسوا کر دے گا\"۔","حسن صحیح",{"u2":"سیدنا ابوبرزہ اسلمی رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اے وہ لوگو جو اپنی زبانوں سے ایمان لائے ہو مگر ایمان ان کے دلوں میں نہیں اترا ہے! مسلمانوں کی بدگوئی نہ کیا کرو اور نہ ان کے عیبوں کے درپے ہوا کرو، بلاشبہ جو ان کے عیبوں کے درپے ہو گا اللہ بھی اس کے عیبوں کے درپے ہو گا۔ اور اللہ جس کے عیبوں کے درپے ہو گیا تو اسے اس کے گھر کے اندر رسوا کر دے گا۔ “","f2":"یہ ضروری نہیں کہ انسان باہر ہی جائے تو رسوا ہو گھر کے اند ر رہتے ہوئے بھی ذلیل و رسوا ہو سکتا ہے۔"}],[4881,"مستورد رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص کسی مسلمان کا عیب بیان کر کے ایک نوالا کھائے گا تو اس کو اللہ اتنا ہی جہنم سے کھلائے گا، اور جو شخص کسی مسلمان کا عیب بیان کر کے ایک کپڑا پہنے گا تو اللہ اسے اسی جیسا لباس جہنم میں پہنائے گا، اور جو شخص کسی شخص کو شہرت اور ریا کے مقام پر پہنچائے گا تو قیامت کے دن اللہ اسے خوب شہرت اور ریا کے مقام پر پہنچا دے گا\" (یعنی اس کی ایسی رسوائی ہو گی کہ سارے لوگوں میں اس کا چرچا ہو گا) ۔","صحیح",{"u2":"سیدنا مستورد (مستورد بن شداد رضی اللہ عنہ) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے کسی مسلمان کی وجہ سے ایک بھی لقمہ کھایا ہو گا (اس کی غیبت یا ہتک وغیرہ کر کے کسی سے کوئی عوض لیا ہو گا) تو اللہ تعالیٰ اسے جہنم سے اسی طرح کا لقمہ کھلائے گا۔ اور جسے کسی مسلمان کی وجہ سے کوئی کپڑا پہنایا گیا تو اللہ تعالیٰ اسے جہنم سے اسی طرح کا کپڑا پہنائے گا۔ اور جس نے کسی کی تشہیر کی اور اسے دکھلاوے کے مقام پر پہنچایا ہو (اس کا چرچا کیا ہو) تو اللہ قیامت کے روز اس کی تشہیر کرے گا اور دکھلاوے کے مقام پر کھڑا کرے گا۔ “ (ایسا عذاب دے گا یا ایسی جگہ عذاب دے گا کہ اس کا سب لوگوں میں چرچا ہو گا)۔","f2":"یہ روایت بعض کے نزدیک صحیح ہے۔ تفصیل کے لیئے دیکھیں(الصحیحۃ: 934)"}],[4882,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کی ہر چیز اس کا مال، اس کی عزت اور اس کا خون دوسرے مسلمان پر حرام ہے، اور آدمی میں اتنی سی برائی ہونا ہی کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر سمجھے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ایک مسلمان کے لیے دوسرے مسلمان کا مال، عزت اور خون حرام ہے۔ بندے کے لیے یہی برائی کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر جانے۔“","f2":"جہاں مسلمان بھائی کی دوسروں کے ہاں بدگوئی کرنا یا توہین کرنا یا اسکا مال مار لینا حرام ہے، وہاں اپنے جی میں اسے حقیر جاننا بھی بہت بڑا گناہ ہے۔"}],[4883,"معاذ بن انس جہنی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی مومن کی عزت و آبرو کی کسی منافق سے حفاظت کرے گا تو اللہ ایک فرشتہ بھیجے گا جو قیامت کے دن اس کے گوشت کو جہنم کی آگ سے بچائے گا\" اور جو شخص کسی مسلمان پر تہمت لگائے گا، اس سے اس کا مقصد اسے مطعون کرنا ہو تو اللہ اسے جہنم کے پل پر روکے رکھے گا یہاں تک کہ جو اس نے جو کچھ کہا ہے اس سے نکل جائے۔","حسن",{"u2":"جناب سہل بن معاذ بن انس جہنی اپنے والد سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے کسی مومن کا کسی منافق سے بچاؤ کیا، راوی کہتا ہے میرا خیال آپ صلی اللہ علیہ وسلم نے یوں کہا: اللہ عزوجل قیامت کے دن ایک فرشتہ بھیجے گا۔ جو اس کے گوشت کو جہنم کی آگ سے بچائے گا۔ اور جس نے کسی مسلمان پر کسی چیز کی تہمت لگائی کہ اس کے ذریعے سے اس نے اس پر عیب لگانا چاہا تو اللہ اسے جہنم کے پل صراط پر روکے رکھے گا، حتیٰ کہ اس کے کہے کی سزا پوری ہو جائے۔ “","f2":"مسلمان صاحبِ ایمان کی عزت کا دفاع کرنا، اس کے سامنے ہو یا اس کی غیر موجودگی میں بہت بڑی وعزیمت اور فضیلت کا کام ہے،اس سے ایک صالح معاشرہ تشکیل پاتا ہے اور شریر طبیعت افراد کو پنپنے کا مو قع نہیں ملتا۔ یہ روایت بعض محقیقین کے نزدیک حسن درجے کی ہے۔ تفصیل کے لیئے دیکھئے: (التعلیق الرغیب: 3/302 303 و مشکوۃالتحقیق الثانی للبانی حدیث: 4986)"}],[4884,"جابربن عبداللہ اور ابوطلحہ بن سہل انصاری رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی مسلمان شخص کو کسی ایسی جگہ میں ذلیل کرے گا، جہاں اس کی بے عزتی کی جائے اس کی عزت میں کمی آئے تو اللہ اسے ایسی جگہ ذلیل کرے گا، جہاں وہ اس کی مدد چاہے گا، اور جو کسی مسلمان کی ایسی جگہ میں مدد کرے گا جہاں اس کی عزت میں کمی آ رہی ہو اور اس کی آبرو جا رہی ہو تو اللہ اس کی ایسی جگہ پر مدد کرے گا، جہاں پر اس کو اللہ کی مدد محبوب ہو گی\"۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ اور ابوطلحہ بن سہل انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے کسی مسلمان کو کہیں بے یارومددگار چھوڑا جہاں کہ وہ بے عزت کیا جا رہا تھا تو اللہ اسے ایسی جگہ بے یارومددگار چھوڑے گا جہاں وہ چاہے گا کہ (کاش) اس کی مدد کی جائے۔ اور جس نے کسی مسلمان کی مدد کی (اور اس کا دفاع کیا) جہاں اسے بے عزت اور ذلیل کیا جا رہا تھا تو اللہ اس کی ایسی جگہ مدد فرمائے گا جہاں وہ چاہے گا کہ اس کی مدد کی جائے۔ “ یحییٰ کہتے ہیں: مجھے یہ حدیث عبیداللہ بن عبداللہ بن عمر اور عقبہ بن شداد نے بھی روایت کی ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ یحییٰ بن سلیم، سیدنا زید رضی اللہ عنہ کے صاحبزادے ہیں جو نبی کریم صلی اللہ علیہ وسلم کے آزاد کردہ غلام تھے اور اسماعیل بن بشیر بنو مغالہ کے آزاد کردہ غلام ہیں اور عقبہ بن شداد کی بجائے عتبہ بھی کہا گیا ہے۔","f2":"یہ روایت سندََا ضعیف ہے تاہم صحیح حدیث میں ہے: جب تک بندہ اپنے بھائی کی نصرت اور مدد میں رہےاللہ اپنے بندے کی مدد میں رہتا ہے۔ (صحیح المسلم الذکر و الدعاء: 2699)"}],[4885,"ابوعبداللہ جشمی کہتے ہیں کہ ہم سے جندب رضی اللہ عنہ نے بیان کیا کہ ایک اعرابی آیا اس نے اپنی سواری بٹھائی پھر اسے باندھا، اس کے بعد وہ مسجد میں داخل ہوا اور رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی، جب آپ نے سلام پھیرا تو وہ اپنی سواری کے پاس آیا، اسے اس نے کھولا پھر اس پر سوار ہوا اور پکار کر کہا: اے اللہ! مجھ پر اور محمد پر رحم فرما اور ہمارے اس رحم میں کسی اور کو شامل نہ کر(یعنی کسی اور پر رحم نہ فرما) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ کیا کہتے ہو؟ یہ زیادہ نادان ہے یا اس کا اونٹ؟ کیا تم نے وہ نہیں سنا جو اس نے کہا؟ لوگوں نے عرض کیا: کیوں نہیں ضرور سنا ہے\"۔","ضعیف",{"u2":"سیدنا جندب (جندب بن عبداللہ بجلی رضی اللہ عنہ) سے روایت ہے کہ ایک دیہاتی آیا، اس نے اپنی سواری بٹھائی، اس کا گھٹنا باندھا پھر مسجد کے اندر آ گیا اور رسول اللہ صلی اللہ علیہ وسلم کے پیچھے نماز پڑھی۔ جب رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا تو وہ اپنی سواری کے پاس آیا، اسے کھولا، اس پر سوار ہوا پھر اونچی آواز میں بولا: اے اللہ! مجھ پر رحم کر اور محمد (صلی اللہ علیہ وسلم) پر رحم کر، اور ہماری اس رحمت میں کسی اور کو شریک نہ کر۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم کیا سمجھتے ہو یہ زیادہ جاہل ہے یا اس کا اونٹ۔ کیا تم نے سنا نہیں جو وہ کہہ رہا ہے؟ “ صحابہ نے کہا: کیوں نہیں۔","f2":"اس روایت کا پہلا حصہ (اللھم ار حمنی۔۔۔۔۔) اے اللہ مجھ پر رحم کر اور حضرت محمد(صلی اللہ علیہ وسلم) پر رحم کر اور ہماری اس رحمت میں کسی کو شریک نہ کر صحیح ہے جو پہلے حدیث نمبر: 380 میں گزر چکا ہے جبکہ دوسرا حصہ صحیح نہیں ہے۔ بہر حال بطور نصیحت و عبرت جاہلوں کی جاہلیت کا ذکر جائز ہے۔"}],[4886,"قتادہ کہتے ہیں کیا تم میں سے کوئی شخص ابوضیغم یا ضمضم کی طرح ہونے سے عاجز ہے، وہ جب صبح کرتے تو کہتے: اے اللہ میں نے اپنی عزت و آبرو کو تیرے بندوں پر صدقہ کر دیا ہے۔","صحیح",{"u2":"جناب قتادہ رضی اللہ عنہ مروی ہے، انہوں نے کہا کیا تم سے ممکن نہیں کہ ابوضیغم یا ابو ضمضم کی طرح ہو جاؤ۔ نام میں محمد بن عبید کو شبہ ہوا ہے۔ جب صبح ہوتی تو وہ کہا کرتا تھا: اے اللہ! میں نے اپنی عزت تیرے بندوں کے لیے صدقہ کر دی ہے۔ (جنہوں نے میری کوئی بے عزتی کی ہو میں نے انہیں معاف کر دیا ہے)۔"}],[4887,"عبدالرحمٰن بن عجلان کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم میں سے کوئی اس بات سے عاجز ہے کہ وہ ابوضمضم کی طرح ہو\" لوگوں نے عرض کیا: ابوضمضم کون ہیں؟ آپ نے فرمایا: \"تم سے پہلے کے لوگوں میں ایک شخص تھا\" پھر اسی مفہوم کی حدیث بیان کی، البتہ اس میں ( «عرضي على عبادك») کے بجائے ( «عرضي لمن شتمني») (میری آبرو اس شخص کے لیے صدقہ ہے جو مجھے برا بھلا کہے) ہے۔ ابوداؤد کہتے ہیں: اسے ہاشم بن قاسم نے روایت کیا وہ اسے محمد بن عبداللہ العمی سے، اور وہ ثابت سے روایت کرتے ہیں، ثابت کہتے ہیں: ہم سے انس نے نبی اکرم صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث روایت کی ہے۔ ابوداؤد کہتے ہیں: حماد کی حدیث زیادہ صحیح ہے۔","ضعیف",{"u2":"جناب عبدالرحمٰن بن عجلان سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کیا تم میں سے کوئی عاجز ہے کہ ابوضمضم کی طرح ہو جائے؟ “ صحابہ نے کہا: ابوضمضم کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم سے پہلے ایک آدمی ہو گزرا ہے۔ اور مذکورہ بالا حدیث کے ہم معنی بیان کیا۔ کہا: جس نے مجھے برا بھلا کہا ہو میری عزت اس کے لیے (صدقہ) ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: اس روایت کو ہاشم بن قاسم نے روایت کیا تو کہا: «عن محمد بن عبد الله العمي عن ثابت قال حدثنا أنس عن النبي صلى الله عليه وسلم» مذکورہ بالا حدیث کے ہم معنی بیان کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ حماد کی روایت زیادہ صحیح ہے۔"}],[4888,"معاویہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: اگر تم لوگوں کی پوشیدہ باتوں کے پیچھے پڑو گے، تو تم ان میں بگاڑ پیدا کر دو گے، یا قریب ہے کہ ان میں اور بگاڑ پیدا کر دو ۱؎۔ ابو الدرداء کہتے ہیں: یہ وہ کلمہ ہے جسے معاویہ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے اور اللہ نے انہیں اس سے فائدہ پہنچایا ہے۔\n§وضاحت\n۱؎ : کیونکہ راز فاش ہو جانے کی صورت میں ان کی جھجھک ختم ہو جائے گی، اور وہ کھلم کھلا گناہ کرنے لگیں گے۔","صحیح",{"u2":"سیدنا معاویہ رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” اگر تو لوگوں کے عیوب کے پیچھے پڑ گیا تو تو انہیں بگاڑ دے گا “ یا ” قریب ہے کہ تو انہیں بگاڑ دے۔ ” تو سیدنا ابودرداء رضی اللہ عنہ کہتے ہیں: یہ بات جو سیدنا معاویہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی اللہ نے انہیں اس سے بہت فائدہ دیا۔","f2":"عین ممکن ہے کہ لوگ عیب کھل جانے کی وجہ سے مزید جری ہو جائیں اور علی الا علان غلط کام کرنے لگیں۔ تاہم امام ِ عادل نصیحت اور اصلاح ِ احوال کے لیئے ان کی خبریں معلوم کرے تو جائز ہو گا۔\n2) جس طرح سیدنا معاویہ رضی اللہ عنہ کو اس فرمانِ نبوی سے فائدہ ہوا کہ وہ ایک کامیاب امیر رہے اس طرح امت کے سب افراد ان کی اتبا ع کر کے فائدہ حاصل کر سکتے ہیں۔"}],[4889,"جبیر بن نفیر، کثیر بن مرہ، عمرو بن اسود، مقدام بن معد یکرب اور ابوامامہ رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"حاکم جب لوگوں کے معاملات میں بدگمانی اور تہمت پر عمل کرے گا تو انہیں بگاڑ دے گا\"۔","صحیح لغیرہ",{"u2":"جناب جبیر بن نفیر، کثیر بن مرہ، عمرو بن اسود، سیدنا مقدام بن معدیکرب اور سیدنا ابوامامہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا &rdquo; امیر (حاکم وقت) اگر تہمت اور شبہے کی بنا پر لوگوں کے درپے ہو گا تو ان کو بگاڑ دے گا۔&ldquo;","f2":"حاکمِ وقت کو عفو و درگزر سے کام لینا چاہیئے اور خوردہ گیری سے اجتناب کرنا چاہیئے۔ البتہ حدود کے نفاذ میں اسے کسی قسم کی رو رعائت نہیں کرنی چاہیئے۔"}],[4890,"زید بن وہب کہتے ہیں کہ عبداللہ بن مسعود رضی اللہ عنہ کے پاس کسی آدمی کو لایا گیا اور کہا گیا: یہ فلاں شخص ہے جس کی داڑھی سے شراب ٹپکتی ہے تو عبداللہ (عبداللہ بن مسعود) نے کہا: ہمیں ٹوہ میں پڑنے سے روکا گیا ہے، ہاں البتہ اگر کوئی چیز ہمارے سامنے کھل کر آئے تو ہم اسے پکڑیں گے۔","صحیح الإسناد",{"u2":"جناب زید بن وہب بیان کرتے ہیں کہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ کے پاس ایک آدمی لایا گیا اور بتایا گیا کہ یہ فلاں آدمی ہے اور اس کی ڈاڑھی سے شراب کے قطرے ٹپک رہے ہیں۔ تو عبداللہ نے کہا: ہمیں ٹوہ لگانے سے منع کیا گیا ہے، ہاں اگر کوئی بات واضح ظاہر ہو تو ہم اس کا مواخذہ کریں گے۔"}],[4891,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی کا کوئی عیب دیکھے پھر اس کی پردہ پوشی کرے تو وہ اس شخص کی طرح ہے جس نے کسی زندہ دفنائی گئی لڑکی کو نئی زندگی بخشی ہو\"۔","ضعیف",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے کسی کی کوئی برائی دیکھی اور پھر اس پر پردہ ڈال دیا تو اس نے گویا قبر میں گاڑی گئی لڑکی کو زندہ کر دیا۔“","f2":"مسلمان جس سے کبھی کوئی غلطی ہو گئی ہوتو اس کے راز کو فاش کرنا کسی طرح نیکی نہیں، نصیحت ضرور کرنی چاہیئے۔ ہاں اگر کوئی عادی مجرم اور فاسق فاجر ہو تو اس کی پردہ پوشی مناسب نہیں کیونکہ اس سے اس کے فسق و فجور میں اور اضافہ ہو جائے گا۔ اس لئے اس کی شکائت حاکم اور قاضی تک ضرور پہنچنی چاہیئےتا کہ اس کی اصلاح ہو۔"}],[4892,"عقبہ بن عامر رضی اللہ عنہ کے منشی (سکریٹری) دخین کہتے ہیں کہ ہمارے کچھ پڑوسی شراب پیتے تھے، میں نے انہیں منع کیا تو وہ باز نہیں آئے، چنانچہ میں نے عقبہ بن عامر سے کہا کہ ہمارے یہ پڑوسی شراب پیتے ہیں، ہم نے انہیں منع کیا لیکن وہ باز نہیں آئے، لہٰذا اب میں ان کے لیے پولیس کو بلاؤں گا، تو انہوں نے کہا: انہیں چھوڑ دو، پھر میں دوبارہ عقبہ کے پاس لوٹ کر آیا اور میں نے ان سے کہا: میرے پڑوسیوں نے شراب پینے سے باز آنے سے انکار کر دیا ہے، اور اب میں ان کے لیے پولیس بلانے والا ہوں، انہوں نے کہا: تمہارا برا ہو، انہیں چھوڑ دو، اس لیے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے ... پھر انہوں نے مسلم جیسی حدیث بیان کی۔ ابوداؤد کہتے ہیں: ہاشم بن قاسم نے کہا کہ اس حدیث میں لیث سے اس طرح روایت ہے کہ عقبہ بن عامر رضی اللہ عنہ کہا: \"ایسا نہ کرو بلکہ انہیں نصیحت کرو اور انہیں دھمکاؤ\"۔","ضعیف",{"u2":"جناب دخین جو سیدنا عقبہ بن عامر رضی اللہ عنہ کے سیکرٹری تھے، نے بیان کیا کہ ہمارے کچھ ہمسائے تھے جو شراب پیتے تھے۔ میں نے ان کو منع کیا مگر وہ باز نہ آئے۔ میں نے سیدنا عقبہ سے کہا: ہمارے یہ ہمسائے شراب پیتے ہیں، میں نے ان کو منع کیا ہے مگر یہ باز نہیں آئے۔ میں پولیس کو بلاتا ہوں۔ تو انہوں نے کہا: دفع کر انہیں چھوڑ دے۔ میں پھر دوبارہ سیدنا عقبہ رضی اللہ عنہ کے پاس آیا اور انہیں بتایا کہ ہمارے ان ہمسایوں نے شراب چھوڑنے سے انکار کر دیا ہے اور میں پولیس کو بلاتا ہوں۔ تو انہوں نے کہا: افسوس تجھ پر! انہیں چھوڑ دے۔ بلاشبہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے۔ اور (مذکورہ بالا) حدیث مسلم (مسلم بن ابراہیم) کے ہم معنی بیان کی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: ہاشم بن قاسم نے جناب لیث سے اس روایت میں بیان کیا کہ ایسے مت کرو، بلکہ انہیں نصیحت کرو اور دھمکی دو۔"}],[4893,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان مسلمان کا بھائی ہے، وہ نہ (خود) اس پر ظلم کرتا ہے، اور نہ اسے (کسی ظالم) کے حوالہ کرتا ہے، جو شخص اپنے بھائی کی کوئی حاجت پوری کرنے میں لگا رہتا ہے، اللہ تعالی اس کی حاجت کی تکمیل میں لگا رہتا ہے، اور جو کسی مسلمان کی کوئی مصیبت دور کرے گا، تو اس کے بدلہ میں اللہ تعالی قیامت کے دن اس کے مصائب و مشکلات میں سے اس سے کوئی مصیبت دور فرمائے گا، اور جو کوئی کسی مسلمان کی پردہ پوشی کرے گا تو قیامت کے دن اللہ تعالی اس کی پردہ پوشی فرمائے گا\"۔","صحیح",{"u2":"سیدنا سالم اپنے والد (سیدنا عبداللہ بن عمر رضی اللہ عنہ) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” مسلمان مسلمان کا بھائی ہے، نہ اس پر ظلم و زیادتی کرتا ہے اور نہ اسے اس کے حالات پر چھوڑ دیتا ہے (کہ اس کی کوئی پروا ہی نہ کرے) جو شخص اپنے بھائی کے کام میں ہو گا (اس کی کوئی ضرورت پوری کرے گا) تو اللہ اس کے کام میں ہو گا (اللہ تعالیٰ بھی اس کی کوئی ضرورت پوری کر دے گا)۔ اور جس نے کسی مسلمان کا ایک دکھ دور کیا اللہ عزوجل قیامت کے روز اس کا ایک دکھ دور کرے گا، اور جس نے کسی مسلمان کا عیب چھپایا، اللہ عزوجل قیامت کے روز اس کے عیب چھپائے گا۔","f2":"دوسرے مسلمان بہن بھائیوں، عزیزوں، رشتے داروں، ہمسائیوں اور احباب کے احوال کی خبر رکھنی چاہیئے۔ بالخصوص مشکلات میں ان سے بے پر واہ ہو جانا اور اُنھیں انکے احوال پر چھوڑ دینا خلافِ شریعت اور بہت بری خصلت ہے۔"}],[4894,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"باہم گالی گلوچ کرنے والے جو کچھ کہتے ہیں اس کا گناہ اس شخص پر ہو گا جس نے ابتداء کی ہو گی جب تک کہ مظلوم اس سے تجاوز نہ کرے\" (اگر وہ تجاوز کر جائے تو زیادتی و تجاوز کا گناہ اس پر ہو گا) ۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” آپس میں گالی گلوچ کرنے والے جو بھی کہیں، اس کا گناہ ابتداء کرنے والے ہی پر ہے جب تک کہ مظلوم زیادتی نہ کرے۔“","f2":"جو شخص کسی گناہ کا سبب بنے تو مقابل کے گناہ کا وبال بھی ابتدا کرنے والے ہی کے سر ہوتا ہے۔ الا یہ کہ مقابل ذیادتی کر جائے۔"}],[4895,"عیاض بن حمار رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ نے مجھ کو وحی کی ہے کہ تم لوگ تواضع اختیار کرو یہاں تک کہ تم میں سے کوئی کسی پر زیادتی نہ کرے اور نہ کوئی کسی پر فخر کرے\"۔","صحیح",{"u2":"سیدنا عیاض بن حمار رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ اللہ عزوجل نے مجھے وحی فرمائی ہے کہ تواضع اور انکسار اختیار کرو حتیٰ کہ کوئی کسی پر ظلم و زیادتی نہ کرے اور نہ کوئی کسی پر فخر کرے۔“","f2":"سبھی احادیثِ نبویہ اللہ عزوجل کی جانب سے وحی کا حصہ ہیں۔ ارشادِ باری تعالی ہے آپ صلی اللہ علیہ وسلم اپنی خوہش سے نہیں بولتے، مگر سب وحی ہوتا ہے تو بعض فرامین میں اس قسم کے جملوں کا اضافہ کہ اللہ نے مجھے وحی کی ہے وہ اس مضمون کی اہمیت اور تاکید کے پیش ِ نظر ہوتا ہے اور ایسی احادیث کو احادیثِ قدسیہ کہا جاتا ہے۔"}],[4896,"سعید بن مسیب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھے ہوئے تھے اور آپ کے ساتھ آپ کے صحابہ بھی تھے کہ اسی دوران ایک شخص ابوبکر رضی اللہ عنہ سے الجھ پڑا اور آپ کو ایذاء پہنچائی تو آپ اس پر خاموش رہے، اس نے دوسری بار ایذاء دی، ابوبکر رضی اللہ عنہ اس بار بھی چپ رہے پھر اس نے تیسری بار بھی ایذاء دی تو ابوبکر رضی اللہ عنہ نے اس سے بدلہ لے، جب ابوبکر رضی اللہ عنہ بدلہ لینے لگے تو رسول اللہ صلی اللہ علیہ وسلم اٹھ کھڑے ہوئے، ابوبکر رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! کیا آپ مجھ سے ناراض ہو گئے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آسمان سے ایک فرشتہ نازل ہوا تھا، وہ ان باتوں میں اس کے قول کی تکذیب کر رہا تھا، لیکن جب تم نے بدلہ لے لیا تو شیطان آ پڑا پھر جب شیطان آ پڑا ہو تو میں بیٹھنے والا نہیں\"۔","حسن لغیرہ",{"u2":"جناب سعید بن مسیب رضی اللہ عنہ سے روایت ہے کہ ایک بار رسول اللہ صلی اللہ علیہ وسلم بیٹھے ہوئے تھے اور آپ صلی اللہ علیہ وسلم کے ساتھ آپ صلی اللہ علیہ وسلم کے صحابہ بھی تھے کہ ایک آدمی نے سیدنا ابوبکر رضی اللہ عنہ کو برا بھلا کہا اور انہیں اذیت دی، تو ابوبکر رضی اللہ عنہ خاموش رہے۔ اس نے پھر دوسری بار اذیت دی تو ابوبکر رضی اللہ عنہ خاموش رہے۔ اس نے پھر تیسری بار اذیت دی تو ابوبکر رضی اللہ عنہ نے اسے بدلے میں کچھ کہا۔ جب سیدنا ابوبکر رضی اللہ عنہ نے اس سے بدلہ لیا تو رسول اللہ صلی اللہ علیہ وسلم اٹھ کھڑے ہوئے، تو ابوبکر رضی اللہ عنہ نے کہا: اے اللہ کے رسول! کیا آپ مجھ سے ناراض ہو گئے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” آسمان سے ایک فرشتہ اترا تھا جو اس آدمی کو اس کے کہے پر جھٹلا رہا تھا۔ جب تم نے اس سے بدلہ لیا تو شیطان آ گیا۔ اور جب شیطان آ گیا تو میں نہیں بیٹھ سکتا۔“"}],[4897,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص ابوبکر رضی اللہ عنہ کو گالی دے رہا تھا، پھر انہوں نے اسی طرح کی حدیث بیان کی۔ ابوداؤد کہتے ہیں: اور اسی طرح اسے صفوان بن عیسی نے ابن عجلان سے روایت کیا ہے جیسا کہ سفیان نے کیا ہے۔","ضعیف"],[4898,"ابن عون کہتے ہیں آیت کریمہ «ولمن انتصر بعد ظلمه فأولئك ما عليهم من سبيل» \"اور جو لوگ اپنے مظلوم ہونے کے بعد (برابر کا) بدلہ لے لیں تو ایسے لوگوں پر الزام کا کوئی راستہ نہیں\" (سورۃ الشوری: ۴۱) میں بدلہ لینے کا جو ذکر ہے اس کے متعلق میں پوچھ رہا تھا تو مجھ سے علی بن زید بن جدعان نے بیان کیا، وہ اپنی سوتیلی ماں ام محمد سے روایت کر رہے تھے، (ابن عون کہتے ہیں: لوگ کہتے ہیں کہ وہ (ام محمد) ام المؤمنین ۱؎ کے پاس جایا کرتی تھیں) ام محمد کہتی ہیں: ام المؤمنین نے کہا: میرے پاس رسول اللہ صلی اللہ علیہ وسلم آئے، ہمارے پاس زینب بنت حجش رضی اللہ عنہا تھیں آپ اپنے ہاتھ سے مجھے کچھ چھیڑنے لگے (جیسے میاں بیوی میں ہوتا ہے) تو میں نے ہاتھ کے اشارہ سے آپ کو بتا دیا کہ زینب بنت حجش بیٹھی ہوئی ہیں، تو آپ رک گئے اتنے میں زینب آ کر ام المؤمنین عائشہ رضی اللہ عنہا سے الجھ گئیں اور انہیں برا بھلا کہنے لگیں، تو آپ نے انہیں اس سے منع فرمایا لیکن وہ نہ مانیں، تو آپ نے ام المؤمنین عائشہ سے فرمایا: \"تم بھی انہیں کہو\"، تو انہوں نے بھی کہا اور وہ ان پر غالب آ گئیں، تو ام المؤمنین زینب رضی اللہ عنہا، علی رضی اللہ عنہ کے پاس گئیں، اور ان سے کہا کہ ام المؤمنین عائشہ رضی اللہ عنہا نے تمہیں یعنی بنو ہاشم کو گالیاں دیں ہیں (کیونکہ ام زینب ہاشمیہ تھیں) پھر فاطمہ رضی اللہ عنہا (نبی اکرم صلی اللہ علیہ وسلم کے پاس ام المؤمنین عائشہ رضی اللہ عنہا کی شکایت کرنے) آئیں تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: قسم ہے کعبہ کے رب کی وہ (یعنی عائشہ) تمہارے والد کی چہیتی ہیں تو وہ لوٹ گئیں اور بنو ہاشم کے لوگوں سے جا کر انہوں نے کہا: میں نے آپ سے ایسا اور ایسا کہا تو آپ نے مجھے ایسا اور ایسا فرمایا، اور علی رضی اللہ عنہ بھی نبی اکرم صلی اللہ علیہ وسلم کے پاس آپ سے اس سلسلے میں گفتگو کی۔\n§وضاحت\n۱؎ : اس سے مراد ام المومنین عائشہ رضی اللہ عنہا ہیں۔","ضعیف الإسناد",{"u2":"جناب (عبداللہ) ابن عون رضی اللہ عنہ کہتے ہیں کہ میں آیت کریمہ «ولمن انتصر بعد ظلمه فأولئك عليهم من سبيل» میں وارد «انتصار» کے معنی پوچھتا تھا کہ مجھے علی بن زید بن جدعان نے اپنی سوتیلی والدہ ام محمد سے روایت کیا اور ابن عون نے کہا: ان لوگوں کا خیال تھا کہ ام محمد، ام المؤمنین (سیدہ عائشہ) رضی اللہ عنہ ا کے ہاں آیا جایا کرتی تھی ام محمد نے کہا: ام المؤمنین رضی اللہ عنہا ا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے، جبکہ (ام المؤمنین) زینب بنت جحش رضی اللہ عنہا ا بھی ہمارے ہاں تھیں، تو رسول اللہ صلی اللہ علیہ وسلم نے مجھے اپنے ہاتھ سے چھیڑا (جیسے میاں بیوی میں ہوتا ہے) تو میں نے آپ کا ہاتھ پکڑ لیا اور آپ کو اشارے سے سمجھایا کہ وہ (زینب بھی) ہمارے ہاں موجود ہیں۔ تو آپ رک گئے۔ پھر سیدہ زینب رضی اللہ عنہا ا، سیدہ عائشہ رضی اللہ عنہا ا پر بولنے لگیں۔ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ زینب رضی اللہ عنہا ا کو منع کیا مگر وہ نہ رکیں تو آپ نے سیدہ عائشہ رضی اللہ عنہا ا سے کہا کہ اسے جواب دو، چنانچہ انہوں نے اسی انداز سے جواب دیا اور (سیدہ زینب پر) غالب آ گئیں۔ تو سیدہ زینب رضی اللہ عنہا ا سیدنا علی رضی اللہ عنہا کے ہاں گئیں اور کہا کہ سیدہ عائشہ رضی اللہ عنہا ا تم لوگوں (بنو ہاشم) کے بارے میں ایسے ایسے باتیں کرتی ہے اور ایسے ایسے کیا ہے۔ تو سیدہ فاطمہ رضی اللہ عنہا ا (رسول اللہ صلی اللہ علیہ وسلم کے پاس) آئیں تو آپ صلی اللہ علیہ وسلم نے انہیں کہا ” رب کعبہ کی قسم! یہ تمہارے ابا کی چہیتی ہے۔ “ چنانچہ سیدہ فاطمہ رضی اللہ عنہا ا واپس چلی گئیں اور آ کر انہیں (سیدنا علی رضی اللہ عنہ اور زینب رضی اللہ عنہا ا کو) بتایا کہ میں نے آپ کو ایسے ایسے کہا ہے تو آپ نے مجھے ایسے ایسے کہا ہے۔ چنانچہ سیدنا علی رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے اس بارے میں بات کی۔"}],[4899,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تمہارا ساتھی (یعنی مسلمان جس کے ساتھ تم رہتے سہتے ہو) مر جائے تو اسے چھوڑ دو ۱؎ اس کے عیوب نہ بیان کرو۔\n§وضاحت\n۱؎ : یعنی اس کے سلسلہ میں کوئی ایسی بات نہ کہو جس سے اگر وہ زندہ ہوتا تو اسے تکلیف ہوتی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تمہارا کوئی فوت ہو جائے تو اسے چھوڑ دو اور اس کی عیب چینی مت کرو۔ “"}],[4900,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے مردوں کی خوبیاں بیان کرو اور ان کی برائیاں بیان کرنے سے باز رہو ۱؎\"۔\n§وضاحت\n۱؎ : مرے ہوئے کافروں اور فاسقوں کی برائیوں کا ذکر اگر اس لیے کیا جائے تاکہ لوگ اس سے بچیں اور عبرت حاصل کریں تو جائز ہے ، اسی طرح سے ضعیف اور مجروح رواۃ حدیث پر جرح و تنفید بھی باتفاق علماء جائز ہے ، خواہ وہ مردہ ہو یا زندہ ، اس لیے کہ اس کا مقصد عقیدہ ، علم ، اور حدیث کی خدمت و حفاظت ہے۔","ضعیف",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اپنے مرنے والوں کی خوبیاں بیان کیا کرو اور ان کی برائیوں سے باز رہو۔ “","f2":"مرنے والا اپنے کیئے ہوئے اعمال کی جزا وسزا پانے کے لیئے اگلے جہا ں جا چکا ہےاب اسکا برا تذکرہ اس کے وارثوں کے لیئے اذیت کے علاوہ تمھارے آپس کے درمیان بغض کا باعث بنے گا۔ ہاں شرعی ضرورت کے تحت کسی کا کفرشرک بدعت واضح کرنا ضروری ہو تو بیان کیا جائے تا کہ لوگ متنبہ رہیں جیسے بعض لوگ فاسد عقیدے کی اشاعت کا باعث بنے ہوں یا روایتِ حدیث میں ضعیف رہے ہوں تو انکا تذکرہ دین کا حصہ ہے نہ کہ کوئی ذاتی غرض۔"}],[4901,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"بنی اسرائیل میں دو شخص برابر کے تھے، ان میں سے ایک تو گناہ کے کاموں میں لگا رہتا تھا\" اور دوسرا عبادت میں کوشاں رہتا تھا، عبادت گزار دوسرے کو برابر گناہ میں لگا رہتا دیکھتا تو اس سے کہتا: باز رہ، ایک دفعہ اس نے اسے گناہ کرتے پایا تو اس سے کہا: باز رہ اس نے کہا: قسم ہے میرے رب کی تو مجھے چھوڑ دے (اپنا کام کرو) کیا تم میرا نگہبان بنا کر بھیجے گئے ہو؟ تو اس نے کہا: اللہ کی قسم، اللہ تعالی تمہیں نہیں بخشے گا یا تمہیں جنت میں داخل نہیں کرے گا، پھر ان کی روحیں قبض کر لی گئیں تو وہ دونوں رب العالمین کے پاس اکٹھا ہوئے، اللہ نے اس عبادت گزار سے کہا: تو مجھے جانتا تھا، یا تو اس پر قادر تھا، جو میرے دست قدرت میں ہے؟ اور گنہگار سے کہا: جا اور میری رحمت سے جنت میں داخل ہو جا، اور دوسرے کے متعلق کہا: اسے جہنم میں لے جاؤ۔ ابوہریرہ رضی اللہ عنہ کہتے ہیں: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے، اس نے ایسی بات کہی جس نے اس کی دنیا اور آخرت خراب کر دی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” بنو اسرائیل میں دو آدمی آپس میں بھائی بنے ہوئے تھے۔ ایک گناہوں میں ملوث تھا جب کہ دوسرا عبادت میں کوشاں رہتا تھا۔ عبادت میں راغب جب بھی دوسرے کو گناہ میں دیکھتا تو اسے کہتا کہ باز آ جا۔ آخر ایک دن اس نے دوسرے کو گناہ میں پایا تو اسے کہا کہ باز آ جا۔ اس نے کہا: مجھے رہنے دے، میرا معاملہ میرے رب کے ساتھ ہے۔ کیا تو مجھ پر کوئی چوکیدار بنا کر بھیجا گیا ہے؟ تو اس نے کہا: اللہ کی قسم! اللہ تجھے معاف نہیں کرے گا یا تجھے جنت میں داخل نہیں کرے گا۔ چنانچہ وہ دونوں فوت ہو گئے اور رب العالمین کے ہاں جمع ہوئے، تو اللہ نے عبادت میں کوشش کرنے والے سے فرمایا ” کیا تو میرے متعلق (زیادہ) جاننے والا تھا یا جو میرے ہاتھ میں ہے تجھے اس پر قدرت حاصل تھی؟ اور پھر گناہ گار سے فرمایا: جا میری رحمت سے جنت میں داخل ہو جا۔ اور دوسرے کے متعلق فرمایا: اسے جہنم میں لے جاؤ۔ “ سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اس نے ایسی بات کہہ دی جس نے اس کی دنیا اور آخرت تباہ کر کے رکھ دی۔","f2":"1۔ نیکی خیر امر بالمعروف نہی عن المنکر کے مبارک اعمال میں مشغول افراد کو حد سے تجاوز نہیں کرنا چاہیے۔ نیز اُنھیں اپنے اعمالِ خیر پر کسی طرح دھوکہ نہیں کھنا چاہیئے کہ وہ یقینا َ جنت میں چلے جائیں گے اور گنہگار مسلمانوں کے متعلق یہ وہم نہی ہونا چاہیئے کہ اللہ اُنھیں معاف نہیں کرے گا یا وہ جنت میں نہیں جائیں گے۔ اللہ عزوجل کا میزانِ عدل برا دقیق او رعجیب ہے۔ اللہ عزوجل نے جو بھی فیصلے فرمائے اور جو فرمائے گا وہ عدل ہی پر مبنی ہیں اور کوئی نہیں جو اس سے پوچھ سکے اور وہ ہر ایک سے پوچھ سکتا ہے۔ ارشادِ گرامی ہے: (لا يسل عما يفعل و حم يُسعلون)(الانبياء:٢٣:)\n2۔ جنت سراسر اللہ عزوجل کا فضل اور اسکی عنائیت ہے نیکیوں کا بدل یا قیمت نہیں۔ نیکیاں بس بندگی کا اظہار ہیں۔ بندہ اظہارِ بندگی میں جس قدر آگے بڑھے گا اُمید کرنی چاہیئے کی اسی قدر زیادہ فضل و عنایئت کا مستحق ٹہرے گا اور اس کے ساتھ ساتھ ہمیشہ ڈرتے بھی رہنا چاہیئے کہ یہ سب کچھ نامقبول نہ ہو جائے۔ ﴿رَبَّنَا تَقَبَّلْ مِنَّا ؕ اِنَّكَ اَنْتَ السَّمِیْعُ الْعَلِیْمُ رَبَّنَا وَ اجْعَلْنَا مُسْلِمَیْنِ لَكَ وَ مِنْ ذُرِّیَّتِنَاۤ اُمَّةً مُّسْلِمَةً لَّكَ ۪ وَ اَرِنَا مَنَاسِكَنَا وَ تُبْ عَلَیْنَا ۚ اِنَّكَ اَنْتَ التَّوَّابُ الرَّحِیْمُ﴾"}],[4902,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ظلم و بغاوت اور قطع رحمی (رشتہ ناتا توڑنے) جیسا کوئی اور گناہ نہیں ہے، جو اس لائق ہو کہ اللہ تعالی اس کے مرتکب کو اسی دنیا میں سزا دے باوجود اس کے کہ اس کی سزا اس نے آخرت میں رکھ چھوڑی ہو ۱؎\"۔\n§وضاحت\n۱؎ : «بغی» سے مراد باغی کا ظلم یا سلطان کے خلاف بغاوت یا کبر و غرور ہے۔","صحیح",{"u2":"سیدنا ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کوئی گناہ اس لائق نہیں کہ اللہ تعالیٰ اس کی سزا دنیا میں بھی جلدی دے دے اور اس کے ساتھ ساتھ آخرت میں بھی اس کی سزا جمع رکھے جیسے کہ ظلم و زیادتی اور قطع رحمی ہے۔ “","f2":"مطلب یہ ہے کہ بغی و عدوان(ظلم و ذیادتی) اور قطع رحمی یہ دو جرم ایسے ہیں کہ اللہ تعالی اخروی سزا کے علاوہ دنیا میں بھی عام طور پر جلد ہی انکی سزا دے دیتا ہے۔ اس لیئے قطع رحمی سے بچنا چاہیئے اور ظلم و عدوان سے بھی۔"}],[4903,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ حسد سے بچو، اس لیے کہ حسد نیکیوں کو ایسے کھا لیتا ہے، جیسے آگ ایندھن کو کھا لیتی ہے یا کہا گھاس کو (کھا لیتی ہے) ۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” حسد (دوسروں پر جلنے اور کڑھنے) سے اپنے آپ کو بچاؤ۔ بلاشبہ حسد نیکیوں کو ایسے کھا جاتا ہے جیسے آگ ایندھن کو یا فرمایا ” جیسے آگ) گھاس پھوس کو کھا جاتی ہے۔ “","f2":"یہ روایت ضعیف ہے۔ تاہم حسد کے برا ہونے میں کوئی شک نہیں۔ کیونکہ حسد در اصل عقیدہ رضا بالقضا(اللہ کے فیصلوں اور اس کی تقسیم پر راضی رہنے) میں کمی کی وجہ سے آتا ہے اس لیئے انسان کسی کے پاس کوئی نعمت اور خیر دیکھے تو اس پر جلنے کڑھنے کی بجائے اللہ سے دُعا کیا کرے کہ اے اللہ! مجھے بھی یہ یا اس سے عمدہ عنائت فرما۔یہ کیفیت رشک کہلاتی غیبُطہ ہے کہلاتی ہے جو ایک ممدوح صفت ہے۔"}],[4904,"سہل بن ابی امامہ کا بیان ہے کہ وہ اور ان کے والد عمر بن عبدالعزیز کے زمانے میں جب وہ مدینے کے گورنر تھے، مدینے میں انس رضی اللہ عنہ کے پاس گئے تو دیکھا، وہ ہلکی یا مختصر نماز پڑھ رہے ہیں، جیسے وہ مسافر کی نماز ہو یا اس سے قریب تر کوئی نماز، جب انہوں نے سلام پھیرا تو میرے والد نے کہا: اللہ آپ پر رحم کرے، آپ بتائیے کہ یہ فرض نماز تھی یا آپ کوئی نفلی نماز پڑھ رہے تھے تو انہوں نے کہا: یہ فرض نماز تھی، اور یہ رسول اللہ صلی اللہ علیہ وسلم کی نماز ہے، اور جب بھی مجھ سے کوئی غلطی ہوتی ہے، میں اس کے بدلے سجدہ سہو کر لیتا ہوں، پھر کہنے لگے: رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: اپنی جانوں پر سختی نہ کرو ۲؎ کہ تم پر سختی کی جائے۳؎ اس لیے کہ کچھ لوگوں نے اپنے اوپر سختی کی تو اللہ تعالی نے بھی ان پر سختی کر دی تو ایسے ہی لوگوں کے باقی ماندہ لوگ گرجا گھروں میں ہیں انہوں نے رہبانیت کی شروعات کی جو کہ ہم نے ان پر فرض نہیں کی تھی پھر جب دوسرے دن صبح ہوئی تو کہا: کیا تم سواری نہیں کرتے یعنی سفر نہیں کرتے کہ دیکھو اور نصیحت حاصل کرو، انہوں نے کہا: ہاں (کرتے ہیں) پھر وہ سب سوار ہوئے تو جب وہ اچانک کچھ ایسے گھروں کے پاس پہنچے، جہاں کے لوگ ہلاک اور فنا ہو کر ختم ہو چکے تھے، اور گھر چھتوں کے بل گرے ہوئے تھے، تو انہوں نے کہا: کیا تم ان گھروں کو پہنچانتے ہو؟ میں نے کہا: مجھے کس نے ان کے اور ان کے لوگوں کے بارے میں بتایا؟ (یعنی میں نہیں جانتا) تو انس نے کہا: یہ ان لوگوں کے گھر ہیں جنہیں ان کے ظلم اور حسد نے ہلاک کر دیا، بیشک حسد نیکیوں کے نور کو گل کر دیتا ہے اور ظلم اس کی تصدیق کرتا ہے یا تکذیب اور آنکھ زنا کرتی ہے اور ہتھیلی، قدم جسم اور زبان بھی اور شرمگاہ اس کی تصدیق یا تکذیب کرتی ہے۔\n§وضاحت\n۱؎ : دشوار اور شاق عمل کر کے جیسے صوم دہر، پوری پوری رات شب بیداری اور عورتوں سے مکمل علیحدگی وغیرہ اعمال۔ ۲؎ : یعنی یہ اعمال تم پر فرض قرار دے دئیے جائیں۔","حسن",{"u2":"جناب سہل بن ابوامامہ رضی اللہ عنہ نے بیان کیا کہ وہ اور اس کا والد مدینہ میں سیدنا انس بن مالک رضی اللہ عنہ کے ہاں گئے۔ یہ سیدنا عمر بن عبدالعزیز رضی اللہ عنہ کے دور کی بات ہے، جبکہ وہ مدینہ کے گورنر تھے۔ ہم سیدنا انس رضی اللہ عنہ کے ہاں پہنچے تو وہ بڑی ہلکی پھلکی نماز پڑھ رہے تھے، گویا کہ مسافر کی نماز ہو یا اس کے قریب۔ جب انہوں نے سلام پھیرا تو میرے والد نے پوچھا: اللہ آپ پر رحم فرمائے! یہ بتائیں کہ یہ فرض نماز تھی یا آپ نے کوئی نفل پڑھے ہیں؟ انہوں نے کہا: یہ فرض نماز تھی اور رسول اللہ صلی اللہ علیہ وسلم کی نماز ایسے ہی ہوتی تھی۔ میں نے اس میں سے کوئی چیز نہیں چھوڑی سوائے اس کے جو کوئی میں بھول گیا ہوں (تو وہ الگ بات ہے)۔ انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے ” اپنی جانوں پر سختی مت کرو ورنہ تم پر سختی کی جائے گی۔ بلاشبہ کئی قوموں نے اپنی جانوں پر سختیاں کیں تو اللہ نے بھی ان پر سختی کی۔ جنگلوں میں معبدوں کے اندر اور گرجا گھروں میں انہی لوگوں کے بقایا لوگ ہیں (جن کا قرآن مجید میں ذکر ہے)۔ ان لوگوں نے رہبانیت اختیار کر لی، انہوں نے یہ بدعت نکالی، ہم نے اسے ان پر فرض نہیں کیا تھا۔ “ (الحدید 27) پھر ہم اگلے دن صبح کے وقت ان کے پاس گئے تو انہوں نے کہا: کیا تم سوار نہیں ہو جاتے کہ کچھ دیکھو اور عبرت پکڑو۔ والد نے کہا: ہاں چلتے ہیں۔ چنانچہ ہم سب سوار ہو لیے۔ تو انہوں نے کچھ بستیاں دکھائیں کہ ان کے لوگ ہلاک ہو گئے تھے، مر کھپ گئے تھے اور نہیں برباد کر دیا گیا تھا اور ان کی بستیاں اپنی چھتوں پر گری پڑی تھیں۔ انہوں نے کہا: کیا تم ان بستیوں کو پہچانتے ہو؟ والد نے کہا: نہیں، مجھے ان بستیوں کا اور ان لوگوں کا کوئی علم نہیں ہے۔ انہوں نے بتایا کہ یہ اس قوم کی بستیاں ہیں جن کو بغاوت اور حسد نے ہلاک کر کے رکھ دیا تھا۔ بلاشبہ حسد سے نیکیوں کا نور بجھ جاتا ہے اور بغاوت اس کی تصدیق کرتی ہے یا اسے جھٹلا دیتی ہے۔ آنکھ زنا کرتی ہے اور پھر ہاتھ، پاؤں، جسم، زبان اور شرمگاہ اس کی تصدیق کر دیتے ہیں یا تکذیب۔","f2":"یہ روایت بھی ضعیف ہے۔ مگر حقیقت یہ ہے کہ حسد اور بغاوت کی وجہ سے افراد، خاندان اور قو میں دنیا کے اند ر ہی تباہ و برباد ہو کر رہ جاتی ہیں۔"}],[4905,"ام الدرداء رضی اللہ عنہا کہتی ہیں کہ میں نے ابو الدرداء کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بندہ جب کسی چیز پر لعنت کرتا ہے، تو یہ لعنت آسمان پر چڑھتی ہے، تو آسمان کے دروازے اس کے سامنے بند ہو جاتے ہیں پھر وہ اتر کر زمین پر آتی ہے، تو اس کے دروازے بھی بند ہو جاتے ہیں پھر وہ دائیں بائیں گھومتی ہے، پھر جب اسے کوئی راستہ نہیں ملتا تو وہ اس کی طرف پلٹ آتی ہے جس پر لعنت کی گئی تھی، اب اگر وہ اس کا مستحق ہوتا ہے تو ٹھیک ہے، ورنہ وہ کہنے والے کی طرف ہی پلٹ آتی ہے۔","حسن",{"u2":"سیدنا ابودرداء رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بندہ جب کسی چیز کو لعنت کرتا ہے تو وہ لعنت آسمان کی جانب چڑھتی ہے تو اس کے آگے آسمان کے دروازے بند کر دیے جاتے ہیں۔ پھر وہ زمین کی طرف اترتی ہے تو اس کے آگے اس کے دروازے بند کر دیے جاتے ہیں۔ پھر وہ دائیں اور بائیں جاتی ہے۔ اگر کوئی جگہ نہ پائے تو جس پر لعنت کی گئی ہو اس پر واقع ہو جاتی ہے بشرطیکہ وہ چیز اس کی حقدار ہو ورنہ اس کے کہنے والے کی طرف لوٹ جاتی ہے۔“ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ مروان بن محمد نے کہا: (سند میں مذکور راوی ولید بن رباح دراصل) رباح بن ولید ہے۔ یحییٰ بن حسان کو اس میں وہم ہوا ہے۔","f2":"یہ روایت ہمارے فاضل محقق کے نزدیک ضعیف ہے۔ لیکن معناَ صحیح ہے یعنی لعنت کرنا بہت برا عمل ہے۔ اگر لعنت کردہ چیز اسکی مستحق نہ ہو تو لعنت کرنے والا خود ملعون ہو جاتا ہے۔ علاوہ ازیں شیخ البانی رحمہ اللہ نے اس روایت کو حسن قرار دیا ہے۔ تفصیل کے لیئے دیکھئے: (الصحیحۃ حدیث 1269) لعنت کے لغوی معنی ہیں اللہ کی رحمت سے دور ہونا۔"}],[4906,"سمرہ بن جندب رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی لعنت یا اللہ کا غضب یا جہنم کی لعنت کسی پر نہ کیا کرو ۱؎\"۔\n§وضاحت\n۱؎ : یعنی یوں نہ کہو: تجھ پر اللہ کی لعنت ہو، یا اللہ کا غضب ہو، یا اللہ تجھے جہنم میں داخل کرے، یہ ممانعت اس صورت کے ساتھ مخصوص ہے کہ آدمی کسی معین شخص پر لعنت بھیجے، اور اگر کسی وصف عام یا وصف خاص کے ساتھ لعنت بھیج رہا ہو مثلاً یوں کہے«لعنة الله على الكافرين» ، یا «لعنة الله على اليهود» ، یا کسی ایسے متعین کافر پر لعنت بھیج رہا ہو جس کا کفر کی حالت میں مرنا معلوم ہو تو یہ جائز ہے جیسے «لعنة الله على الكافرين» ، یا «لعنة الله على أبي جهل» کہنا۔","حسن",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اللہ کی لعنت سے لعنت مت کیا کرو اور اللہ کے غضب اور دوزخ کی بد دعا مت دیا کرو۔“","f2":"اس روایت کو بھی بعض محقیقن نے حسن قرار دیا ہے۔"}],[4907,"ام الدرداء رضی اللہ عنہا کہتی ہیں کہ میں نے ابوالدرداء کو سنا وہ کہہ رہے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:\"لعنت کرنے والے نہ سفارشی ہو سکتے ہیں اور نہ گواہ ۱؎\"۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ آپ صلی اللہ علیہ وسلم کی امت کے فرد نہیں ہو سکتے، کیونکہ آپ کی امت قیامت کے روز دوسری امتوں پر سفارشی اور گواہ ہو گی۔","صحیح",{"u2":"سیدنا ابودرداء رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ” جو بہت زیادہ لعنت کرنے والے ہوئے وہ (کسی کے) سفارشی یا گواہ نہیں بن سکیں گے۔ “","f2":"یہ کس قدر بڑی محرومی ہے کہ کسی بندے کو اس فضیلت سے محروم کر دیا جائے۔ حالانکہ اہلِ ایمان اپنے عزیزوں اور دوسروں کی سفارش کو سکیں گے اور ان کے لیئے گواہ بھی بنیں گے۔"}],[4908,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک شخص نے ہوا پر لعنت کی (مسلم کی روایت میں اس طرح ہے) نبی اکرم صلی اللہ علیہ وسلم کے زمانے میں ہوا نے ایک شخص کی چادر اڑا دی، تو اس نے اس پر لعنت کی، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس پر لعنت نہ کرو، اس لیے کہ وہ تابعدار ہے، اور اس لیے کہ جو کوئی ایسی چیز کی لعنت کرے جس کا وہ اہل نہ ہو تو وہ لعنت اسی کی طرف لوٹ آتی ہے\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے ہوا کو لعنت کی۔ اور مسلم (مسلم بن ابراہیم) کے الفاظ ہیں کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں ہوا سے ایک شخص کی چادر اڑ گئی تو اس نے اسے لعنت کر دی، تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اسے لعنت مت کرو، بلاشبہ یہ (اللہ کے حکم کی) پابند ہے۔ اور بلاشبہ جس نے کسی چیز کو لعنت کی جب کہ وہ اس کی حقدار نہ ہو، تو یہ لعنت کرنے والے پر لوٹ آتی ہے۔“","f2":"اس روایت کو بھی بعض نے صحیح کہا ہے لہذا اللہ کی صلی اللہ علیہ وسلم مخلوق پر لعنت کرنا جائز نہیں سوائے انکے جن پر اللہ نے اور اس کے رسول صلی اللہ علیہ وسلم نے لعنت کی۔ مثلاَ کافرین، ظالمین، کاذبین وغیرہ۔ جیسے کہ دُعائے قنوت ِ نازلہ میں ہے اے اللہ اُن کا فروں پر لعنت فرما جو تیرے راستے سے روکتے ہیں۔ تیرے پیغمبروں کو جھٹلاتے ہیں اور تیرے دوستوں سے لڑتے ہیں۔"}],[4909,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ان کی کوئی چیز چوری ہو گئی، تو وہ اس پر بد دعا کرنے لگیں، تو ان سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس (چور) سے عذاب کو ہلکا نہ کر\"۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ ان کی کوئی چیز چوری ہو گئی تو وہ (چور کو) بد دعا دینے لگیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا ” اس کی سزا کو اس سے ہلکا مت کرو۔ “"}],[4910,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ ایک دوسرے سے بغض نہ رکھو، ایک دوسرے سے حسد نہ کرو، اور ایک دوسرے کو پیٹھ نہ دکھاؤ (یعنی ملاقات ترک نہ کرو) اور اللہ کے بندے بھائی بھائی بن کر رہو، اور کسی مسلمان کے لیے یہ درست نہیں کہ وہ اپنے بھائی سے تین دن سے زیادہ ملنا جلنا چھوڑے رکھے ۱؎\"۔\n§وضاحت\n۱؎ : یہ حکم ایسی ناراضگی سے متعلق ہے جو مسلمانوں کے درمیان باہمی معاشرتی حقوق میں کوتاہی کی وجہ سے ہوئی ہو ، اور اگر دینی امور میں کوتاہی کی وجہ سے ہو تو یہ جائز ہے، بلکہ بدعتیوں اور ہوا پرستوں سے میل جول نہ رکھنا واجب ہے جب تک کہ وہ توبہ نہ کر لیں، اور حق کی طرف پلٹ نہ آئیں۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” غصہ مت کیا کرو۔ ایک دوسرے سے حسد مت کیا کرو۔ ایک دوسرے کو پیٹھ مت دیا کرو (کہ میل جول چھوڑ دو) بلکہ اللہ کے بندے بھائی بھائی بن کر رہو۔ کسی مسلمان کے لیے حلال نہیں کہ اپنے بھائی سے تین رات سے زیادہ میل جول چھوڑے رہے۔ “","f2":"تین دن رات سے زیادہ قطع تعلقی کرنا اور میل جول چھوڑ دینا اس صورت میں ناجائز اور حرام ہے جب محض اپنی ذات کے لیئے ہو۔ اگر اللہ تعالی کے لیئے ہو تو یہ مشروع، محبوب اور ممدوح ہے۔ امام ابو داؤد رحمہ اللہ نے حدیث: 4916 کے آخر میں اس مسئلے کی وضاحت کر دی ہے۔"}],[4911,"ابوایوب انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان کے لیے درست نہیں کہ وہ اپنے بھائی کو تین دن سے زیادہ چھوڑے رکھے کہ وہ دونوں ملیں تو یہ منہ پھیر لے، اور وہ منہ پھیر لے، اور ان دونوں میں بہتر وہ ہے جو سلام میں پہل کرے ۱؎\"۔\n§وضاحت\n۱؎ : کیونکہ اس کا پہل کرنا اس بات کی دلیل ہے کہ اس میں تواضع اور خاکساری زیادہ ہے۔","صحیح",{"u2":"سیدنا ابوایوب انصاری رضی اللہ عنہ سے روایت ہے کہرسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کسی مسلمان کے لیے جائز نہیں کہ اپنے بھائی کے ساتھ تین دن سے زیادہ میل جول چھوڑے رہے کہ جب دونوں کی ملاقات ہو تو یہ بھی منہ پھیر لے اور وہ بھی۔ اور ان میں سب سے بہتر وہ ہے جو السلام علیکم کہنے میں ابتداء کرے۔ “","f2":"اگر کہیں شک رنجی ہو جائے تو تعلقات کو بالکل ہی مقطہ کر لینا جائز نہیں۔ہاں اگر مزید روابط بڑھانا خلافِ مصلحت ہو تو سلام دُعا سے بخیل نہیں ہونا چاہیئے۔ اس حدیث اور اگلی حدیث سے معلوم ہوتا ہے کہ سلام کرنا اور اسکا جواب دینا مقاطعے کے گناہ کو ختم کر دیتا ہے۔"}],[4912,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کسی مومن کے لیے درست نہیں کہ وہ کسی مومن کو تین دن سے زیادہ چھوڑے رکھے، اگر اس پر تین دن گزر جائیں تو وہ اس سے ملے اور اس کو سلام کرے، اب اگر وہ سلام کا جواب دیتا ہے، تو وہ دونوں اجر میں شریک ہیں اور اگر وہ جواب نہیں دیتا تو وہ گنہگار ہوا، اور سلام کرنے والا قطع تعلق کے گناہ سے نکل گیا\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کسی مسلمان کو حلال نہیں کہ کسی صاحب ایمان سے تین دن سے زیادہ مقاطعہ کرے۔ اگر تین دن گزر جائیں تو چاہیئے کہ اس سے ملے اور اس کو سلام کہے۔ اگر وہ سلام کا جواب دیدے تو اجر و ثواب میں دونوں شریک ہو گئے۔ اگر وہ جواب نہ دے تو اس کا گناہ اسی دوسرے کے ذمے ہے۔ “ احمد (احمد بن سعید سرخسی) نے مزید کہا: ” سلام کرنے والا مقاطعے کے گناہ سے نکل گیا۔ “"}],[4913,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان کے لیے درست نہیں کہ وہ اپنے بھائی کو تین دن سے زیادہ چھوڑے رکھے تو جب وہ (تین دن کے بعد) اس سے ملے اسے تین مرتبہ سلام کرے، اور وہ ایک بار بھی سلام کا جواب نہ دے تو وہ اپنا گناہ لے کر لوٹے گا ۱؎\"۔\n§وضاحت\n۱؎ : اگر «إثمه» کی ضمیر سلام کا جواب نہ دینے والے «لا يرد عليه» کی طرف لوٹتی ہو تو مفہوم یہ ہو گا کہ سلام کرنے والا قطع تعلق کے گناہ سے بری ہو گیا، اور سلام کا جواب نہ دینے والا اپنے قطع تعلق کا گناہ لے کر لوٹا، اور اگر «إثمه» کی ضمیر سلام کرنے والے کی طرف لوٹتی ہو تو مفہوم یہ ہو گا کہ وہ اپنا اور سلام کرنے والے دونوں کا گناہ لے کر لوٹے گا۔","حسن",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کسی مسلمان کو روا نہیں کہ کسی مسلمان سے تین دن سے زیادہ مقاطعہ رکھے۔ چنانچہ (چاہیئے کہ) جب اس سے ملے تو اسے سلام کہے، تین بار، اگر کسی بار بھی جواب نہ دے تو وہی گناہ گار ہوا۔“"}],[4914,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان کے لیے درست نہیں کہ وہ اپنے بھائی کو تین دن سے زیادہ چھوڑے رکھے، لہٰذا جو تین سے زیادہ چھوڑے رکھے پھر وہ (بغیر توبہ کے اسی حال میں) مر جائے تو وہ جہنم میں داخل ہو گا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کسی مسلمان کے لیے حلال نہیں کہ اپنے بھائی سے تین دن سے زیادہ میل جول چھوڑے رہے۔ جس نے تین دن سے زیادہ مقاطعہ کیا اور مر گیا تو وہ آگ میں جائے گا۔ “"}],[4915,"ابو خراش سلمی رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے اپنے بھائی سے ایک سال تک قطع تعلق رکھا تو یہ اس کے خون بہانے کی طرح ہے\"۔","صحیح",{"u2":"سیدنا ابو خراش سلمی رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فر رہے تھے ” جس نے ایک سال تک اپنے بھائی سے روابط توڑے رکھے تو وہ ایسے ہے جیسے اس کا خون بہایا ہو۔ “"}],[4916,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر دوشنبہ اور جمعرات کو جنت کے دروازے کھول دیئے جاتے ہیں پھر ان دنوں میں ہر اس بندے کی مغفرت کی جاتی ہے، جو اللہ کے ساتھ کسی چیز کو شریک نہیں کرتا البتہ اس بندے کی نہیں جس کے درمیان اور اس کے بھائی کے درمیان دشمنی اور رقابت ہو، پھر کہا جاتا ہے: ان دونوں (کی مغفرت) کو ابھی رہنے دو جب تک کہ یہ صلح نہ کر لیں\"۔ ابوداؤد کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے اپنی بعض ازواج مطہرات کو چالیس دن تک چھوڑے رکھا، اور ابن عمر رضی اللہ عنہما نے اپنے ایک بیٹے سے بات چیت بند رکھی یہاں تک کہ وہ مر گیا۔ ابوداؤد کہتے ہیں: یہ قطع کلامی اگر اللہ کے لیے ہو ۱؎ تو اس میں کوئی حرج نہیں اور عمر بن عبدالعزیز نے ایک شخص سے اپنا چہرہ ڈھانک لیا۔\n§وضاحت\n۱؎ : یعنی اللہ کے حقوق میں کسی سے کسی حق کی پاسداری کے لئے ہو تو یہ اس وعید میں داخل نہیں ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہر سوموار اور جمعرات کو جنت کے دروازے کھولے جاتے ہیں تو ہر وہ بندہ جو اللہ کے ساتھ کسی کو شریک نہ کرتا ہو اسے بخش دیا جاتا ہے۔ سوائے اس کے کہ اس کے اور اس کے بھائی کے درمیان بغض اور ناراضی ہو۔ تو کہا جاتا ہے: انہیں مہلت دو حتیٰ کہ صلح کر لیں۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے اپنی بعض ازواج سے چالیس دن تک میل جول چھوڑ دیا تھا۔ اور سیدنا ابن عمر رضی اللہ عنہ نے مرنے تک اپنے ایک بیٹے سے مقاطعہ کیے رکھا تھا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: الغرض یہ مقاطعہ اور میل جول چھوڑنا اگر اللہ کے لیے ہو تو اس پر یہ وعیدیں نہیں ہیں۔ جناب عمر بن عبدالعزیز رضی اللہ عنہ نے ایک آدمی سے اپنا چہرہ ڈھانپ لیا تھا۔"}],[4917,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ظن و گمان کے پیچھے پڑنے سے بچو یا بدگمانی سے بچو، اس لیے کہ بدگمانی سب سے بڑا جھوٹ ہے، نہ ٹوہ میں پڑو اور نہ جاسوسی کرو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اپنے آپ کو گمان سے بچاؤ، بلاشبہ گمان سب سے جھوٹی بات ہے، اور نہ ٹوہ لگاؤ اور نہ جاسوسی کرو۔ “","f2":"ظن لا لفظ کئی معنوں میں استعمال ہوتا ہے ظن بمعنی گمان، ظن بمعنی علم و یقین۔ لیکن یہاں طن سےے مراد وہ غلط اور برے گمان ہیں جو کسی سے متعلق دل میں جگہ پا جاتے ہیں اور فی الواقع ان کی کوئی دلیل نہیں ہوتی اور شریعت اس کی تائید نہیں کرتی۔ ظن کی بحث کے لیئے مولانا محمد اسماعیل سلفی رحمہ اللہ کی کتاب حجیت حدیث ایک اہم اور قابلِ مطالعہ کتاب ہے۔"}],[4918,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن مومن کا آئینہ ہے، اور مومن مومن کا بھائی ہے، وہ اس کی جائیداد کی نگرانی کرتا اور اس کی غیر موجودگی میں اس کی حفاظت کرتا ہے\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مومن مومن کا آئینہ ہے، اور مومن مومن کا بھائی ہے، اس کے مال کا (نقصان ہوتا ہو تو) بچاؤ کرتا ہے اور اس کی غیر موجودگی میں اس کی (عزت کی) حفاظت کرتا ہے۔ “","f2":"مسلمان بھائی کے عیوب کی تشہیر کرنا جائز نہیں البتہ خا موشی کے ساتھ مناسب انداز میں فہمائش ضرور کر دے تاکہ وہ اپنی اصلاح کر لے۔ نیز اس کی حاضری یا غیر حاضری میں ہر طرح سے اس کی خیر خواہی کرنا واجب ہے۔"}],[4919,"ابو الدرداء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تمہیں وہ بات نہ بتاؤں جو درجے میں روزے، نماز اور زکاۃ سے بڑھ کر ہے؟\" لوگوں نے کہا: کیوں نہیں، آپ نے فرمایا: \"آپس میں میل جول کرا دینا، اور آپس کی لڑائی اور پھوٹ تو سر مونڈنے والی ہے\"۔","صحیح",{"u2":"سیدنا ابودرداء رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کیا میں تمہیں روزے، نماز اور صدقے سے بڑھ کر افضل درجات کے اعمال نہ بتاؤں؟ “ صحابہ نہ کہا: کیوں نہیں، اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا ” آپس کے میل جول اور روابط کو بہتر بنانا۔ (اور اس کے برعکس) آپس کے میل جول اور روابط میں پھوٹ ڈالنا (دین کو) مونڈا دینے والی خصلت ہے۔ “","f2":"فاضل محقق اس روایت کی تخریج کرتے ہوئے لکھتے ہیں کہ یہ روایت سندَا ضعیف ہے۔ البتہ یہی متن سعید بن مسیب رحمہ اللہ کے قول کے حوالے سے موطا امام مالک میں مروی ہے اور یہ سندَا صحیح ہے جبکہ شیخ البانی رحمہ اللہ مذکورہ روایت ہی کو صحیح قرار دیتے ہیں۔\n2۔ حقوق اللہ میں بنیادہی اہم فرائض کے فضائل و درجات کی حفاظت کے لیئے ضروری ہے کی مسلمان معاشرتی زندگی میں پسندیدہ مسلمان ہو۔ اگر کوئی شخص حقوق اللہ کی ادائیگی میں سرگرم ہو مگر حقوق العباد میں ناکام ہو تو محض حقوق اللہ کی ادائیگی سے کماحقہ مطلوبہ فضائل و درجات حاصل نہیں ہونگے۔ بلکہ اندیشہ ہے کہ کہیں وہ حسنات بھی ضائع نہ ہو جائیں۔"}],[4920,"ام حمید بن عبدالرحمٰن (ام کلثوم) رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس نے جھوٹ نہیں بولا جس نے دو آدمیوں میں صلح کرانے کے لیے کوئی بات خود سے بنا کر کہی۔ احمد بن محمد اور مسدد کی روایت میں ہے، وہ جھوٹا نہیں ہے: \"جس نے لوگوں میں صلح کرائی اور کوئی اچھی بات کہی یا کوئی اچھی بات پہنچائی\"۔\n§وضاحت\n۱؎ : مثلاً یوں کہے کہ آپ کو تو فلاں نے سلام کہا ہے یا فلاں آپ سے محبت رکھتا ہے یا فلاں آپ کی تعریف کرتا ہے۔","صحیح",{"u2":"جناب حمید بن عبدالرحمٰن اپنی والدہ (ام کلثوم بنت عقبہ بن ابی معیط) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس شخص نے دو آدمیوں میں صلح کرانے کی خاطر بات بنا کر کہی ہو، اس نے جھوٹ نہیں بولا۔ “ احمد بن محمد اور مسدد کی روایت کے الفاظ ہیں ” جس نے لوگوں میں صلح کرانے کے لیے بھلی بات کہی یا پہنچائی وہ جھوٹا نہیں ہے۔ “"}],[4921,"ام کلثوم بنت عقبہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کسی بات میں جھوٹ بولنے کی اجازت دیتے نہیں سنا، سوائے تین باتوں کے، رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: میں اسے جھوٹا شمار نہیں کرتا، ایک یہ کہ کوئی لوگوں کے درمیان صلح کرائے اور کوئی بات بنا کر کہے، اور اس کا مقصد اس سے صرف صلح کرانی ہو، دوسرے یہ کہ ایک شخص جنگ میں کوئی بات بنا کر کہے، تیسرے یہ کہ ایک شخص اپنی بیوی سے کوئی بات بنا کر کہے اور بیوی اپنے شوہر سے کوئی بات بنا کر کہے۔","صحیح",{"u2":"سیدہ ام کلثو بنت عقبہ رضی اللہ عنہا ا سے روایت ہے کہتی ہیں: میں نے نہیں سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے جھوٹ کی کہیں اجازت دی ہو مگر تین مواقع پر۔ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے ” میں ایسے آدمی کو جھوٹا شمار نہیں کرتا جو لوگوں میں صلح کرانے کی غرض سے کوئی بات بناتا ہو اور اس کا مقصد سوائے صلح اور اصلاح کے کچھ نہ ہو، اور جو شخص لڑائی میں کوئی بات بنائے اور شوہر جو اپنی بیوی سے یا بیوی اپنے شوہر کے سامنے کوئی بات بنائے۔ “","f2":"1۔ مسلمان بھائیوں میں صلح اور اصلاح کے لیئے کوئی بات بنانی پڑ جائے تو اس سے دریغ نہیں کرنا چاہیئے۔ یہ جھوٹ معیوب نہیں ہوتا۔\n2۔ میاں بیوی اگر کسی ناراضی کو دور کرنے کے لیئے یا لفظی طور پر ایک دوسرے کو محبت جتلانے کے لیئے کوئی بات کہیں تو جائز ہے تاکہ انکی عائلی زندگی مسرت بھری رہے۔\n3۔ دشمن کو دھوکہ دینا بھی جائز ہے۔"}],[4922,"ربیع بنت معوذ بن عفراء رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرے پاس اس صبح آئے، جس رات میرا شب زفاف ہوا تھا تو آپ میرے بستر پر ایسے بیٹھ گئے جیسے تم (خالد بن ذکوان) بیٹھے ہو، پھر (انصار کی) کچھ بچیاں اپنے دف بجانے لگیں اور اپنے غزوہ بدر کی شہید ہونے والے آباء و اجداد کا اوصاف ذکر کرنے لگیں یہاں تک کہ ان میں سے ایک نے کہا: اور ہمارے بیچ ایک ایسا نبی ہے جو کل ہونے والی باتوں کو بھی جانتا ہے، تو آپ نے فرمایا: \"اسے چھوڑ دو اور وہی کہو جو تم پہلے کہہ رہی تھیں\"۔","صحیح",{"u2":"سیدہ ربیع بنت معوذ بن عفراء رضی اللہ عنہ ا بیان کرتی ہیں کہ جب میری رخصتی ہوئی اس صبح رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے اور میرے بستر پر اسی طرح تشریف فر ہوئے تھے جیسے تم (خالد بن ذکوان) میرے پاس بیٹھے ہوئے ہو۔ تو (انصار کی) چھوٹی بچیاں اپنے اپنے دف بجانے لگیں اور میرے ان آباء کا ذکر کرنے لگیں جو بدر میں شہید ہو گئے تھے۔ حتیٰ کہ ان میں سے ایک بچی نے کہا: اور ہم میں ایسا نبی ہے جو کل آئندہ کی بات جانتا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اس بات کو چھوڑ دو اور وہی کہو جو پہلے کہہ رہی تھی۔“","f2":") بچیوں کو انکی خانہ آبادی پر مبارکباد دینے جانا مستحب عمل ہے۔\n2) ایسی خوشیوں کے مواقع پر چھوٹی نابالغ بچیوں کا دف بجانا جائز اور مستحب ہے تا کہ نکاح اور شادی کا اعلان ہو۔\n3) آلاتِ مو سیقی میں سےصرف دف ہی ایک ایسا آلہ ہے جو شریعت میں جائز قرار دیا گیا ہے اور یہ خود ساختہ سادہ سی ڈھولک ہوتی ہے جس کی ایک جانب کھلی ہوتی ہے۔\n4) اسلاف مسلمین کے کارناموں کا ذکر کرنا ممدوح ہے۔\n5) شادمانی کا موقع ہو یا کسی غمی کا ایسی بات کہنا یا کرنا جو شرعی اُصول و قواعد کے خلاف ہو ناجائز ہے۔\n6) رسول اللہ صلی اللہ علیہ وسلم کے متعلق یہ عقیدہ کہ آپ علمِ غیب جانتے تھے غلط عقیدہ ہے نبی صلی اللہ علیہ وسلم نے اس کی تصدیق و تائید نہیں فرمائی۔"}],[4923,"انس رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم مدینے آئے تو حبشی آپ کی آمد پر خوش ہو کر خوب کھیلے اور اپنی برچھیاں لے کر کھیلے۔","صحیح الإسناد",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب مدینہ تشریف لائے تو حبشی لوگوں نے آپ صلی اللہ علیہ وسلم کی آمد کی خوشی میں اپنے نیزوں کے ساتھ (جنگی فن کا) مظاہرہ کیا تھا۔","f2":"عید یا دیگر شادمانی کے مواقع پر جنگی کرتبوں وغیرہ کا اظہار کرنا اور اشعار پڑھنا جائز ہے بشرطیکہ کہ شرعی حدود میں ہوں۔"}],[4924,"نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما نے ایک باجے کی آواز سنی تو اپنی دونوں انگلیاں کانوں میں ڈال لیں اور راستے سے دور ہو گئے اور مجھ سے کہا: اے نافع! کیا تمہیں کچھ سنائی دے رہا ہے میں نے کہا: نہیں، تو آپ نے اپنی انگلیاں کانوں سے نکالیں، اور فرمایا: میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تھا، اس جیسی آواز سنی تو آپ نے بھی اسی طرح کیا۔ ابوعلی لؤلؤی کہتے ہیں: میں نے ابوداؤد کو کہتے سنا: یہ حدیث منکر ہے۔","صحیح",{"u2":"جناب نافع بیان کرتے ہیں کہ سیدنا ابن عمر رضی اللہ عنہ نے بانسری کی آواز سنی تو انہوں نے اپنی انگلیاں اپنے کانوں پر رکھ لیں اور راستے سے دور چلے گئے۔ اور پھر مجھ سے پوچھا: اے نافع! کیا بھلا کچھ سن رہے ہو؟ میں نے کہا: نہیں، تو انہوں نے اپنی انگلیاں اپنے کانوں سے اٹھا لیں اور کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم سے ساتھ تھا تو آپ صلی اللہ علیہ وسلم نے اس طرح کی آواز سنی تو آپ صلی اللہ علیہ وسلم نے ایسے ہی کیا تھا۔ امام ابوداؤد رضی اللہ عنہ نے کہا: یہ حدیث منکر (ضعیف) ہے۔","f2":"امام ابو داؤد کا قول صحیح نہیں ہے یہ روایت حسن اور بقول علامہ البانی رحمہ اللہ صحیح ہے اور دیگر احادیث سے ثابت ہے کہ (لهو الحديث) سے مراد آلاتِ موسیقی ہیں جنکی قطعاََ اجازت نہیں ہے۔ اور بالخصوص اللہ اور اسکے رسول صلی اللہ علیہ وسلم کے نام کو طبلے کی تھاپ پر بجانا انکی انتہائی توہیں ہے اور موسیقی کی تمام لغویات حرام ہیں سوائے دف کے۔"}],[4925,"نافع کہتے ہیں کہ میں ابن عمر رضی اللہ عنہما کے پیچھے سوار تھا، کہ ان کا گزر ایک چرواہے کے پاس سے ہوا جو بانسری بجا رہا تھا، پھر انہوں نے اسی طرح کی روایت ذکر کی۔","حسن صحیح الإسناد",{"u2":"(مذکورہ بالا روایت کے سلسلے میں) جناب نافع رضی اللہ عنہ کہتے ہیں کہ میں سیدنا ابن عمر رضی اللہ عنہ کے ساتھ سواری پر ان کے پیچھے بیٹھا ہوا تھا کہ ان کا گزر ایک چرواہے کے پاس سے ہوا جو بانسری بجا رہا تھا۔ اور مذکورہ بالا حدیث کی مانند ذکر کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں مطعم (مطعم بن مقدام) اور نافع کے درمیان سلیمان بن موسیٰ کا واسطہ بڑھا دیا گیا ہے۔"}],[4926,"نافع کہتے ہیں کہ میں ابن عمر رضی اللہ عنہما کے ساتھ تھا تو آپ نے ایک بانسری بجانے والے کی آواز سنی پھر راوی نے اسی طرح کی حدیث بیان کی۔ ابوداؤد کہتے ہیں: یہ ان احادیث میں سب سے زیادہ منکر ہے ۱؎۔\n§وضاحت\n۱؎ : صاحب \" عون المعبود\" لکھتے ہیں : «ولا یعلم وجہ النکارۃ بل إسنادہ قوی ولیس بمخالف لروایۃ الثقات» یعنی ابوداود نے اسے «أنکر الروایۃ» کیوں کہا اس کی کوئی وجہ معلوم نہیں ہو سکی بلکہ سنداً یہ قوی روایت ہے اور ثقات کی روایت کے بھی مخالف نہیں ہے۔","صحیح الإسناد",{"u2":"جناب میمون بن مہران ‘ نافع سے روایت کرتے ہیں کہہم سیدنا ابن عمر رضی اللہ عنہ کے ساتھ تھے کہ انہوں نے ایک بانسری والے کی آواز سنی۔ اور مذکورہ بالا حدیث کی مانند ذکر کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یہ روایت سب سے زیادہ منکر (ضعیف) ہے۔"}],[4927,"سلام بن مسکین ایک شیخ سے روایت کرتے ہیں جو ابووائل کے ساتھ ایک ولیمہ میں موجود تھے تو لوگ کھیل کود اور گانے بجانے میں لگے گئے، تو ابووائل نے اپنا حبوہ ۱؎ کھولا اور بولے: میں نے عبداللہ بن مسعود کو کہتے سنا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: گانا بجانا دل میں نفاق پیدا کرتا ہے۔\n§وضاحت\n۱؎ : بیٹھنے کی ایک مخصوص ہیئت کا نام ہے جس میں آدمی سرین کے بل پاؤں کھڑا کر کے بیٹھتا اور دونوں ہاتھوں سے اپنے گھٹنے باندھ لیتا ہے۔","ضعیف",{"u2":"سلام بن مسکین ایک شیخ سے روایت کرتے ہیں جو جناب ابووائل رضی اللہ عنہ کے ساتھ ایک ولیمے میں حاضر تھا۔ پس وہ لوگ آپس میں کھیلنے کھلانے اور گانے لگے تو جناب ابووائل رضی اللہ عنہ نے اپنی کمر سے اپنا کپڑا کھولا اور کہا: میں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے سنا ہے وہ فرماتے تھے میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فر رہے تھے ” گانا دل میں نفاق پیدا کرتا ہے۔ “","f2":"یہ روایت مرفو عاَ صحیح نہیں ہے۔ البتہ حضرت عبدُاللہ بن مسعود رضی اللہ عنہ کا قول (موقوف) صحیح ہے۔ اُنھوں نے کہا: گانا دل میں نفاق پیدا کرتا ہے جیسے پانی کھیتی کو اُگاتا ہے۔ (فوائد امام ابن القیم رحمہ اللہ۔ اغاثۃ اللھفان)"}],[4928,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک ہجڑا لایا گیا جس نے اپنے ہاتھوں اور پیروں میں مہندی لگا رکھی تھی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس کا کیا حال ہے؟ عرض کیا گیا: اللہ کے رسول! یہ عورتوں جیسا بنتا ہے، آپ نے حکم دیا تو اسے نقیع کی طرف نکال دیا گیا، لوگوں نے عرض کیا: اللہ کے رسول! ہم اسے قتل نہ کر دیں؟، آپ نے فرمایا: \"مجھے نماز پڑھنے والوں کو قتل کرنے سے منع کیا گیا ہے\" نقیع مدینے کے نواح میں ایک جگہ ہے اس سے مراد بقیع (مدینہ کا قبرستان) نہیں ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم کے پاس ایک ہیجڑا لایا گیا جس نے اپنے ہاتھ پاؤں مہندی سے رنگے ہوئے تھے۔ نبی کریم صلی اللہ علیہ وسلم نے اس کے متعلق دریافت فرمایا ” اسے کیا ہے؟ “ بتایا گیا کہ اے ا اللہ کے رسول! یہ عورتوں کے ساتھ مشابہت کرتا ہے۔ تو آپ صلی اللہ علیہ وسلم نے حکم دیا اور اسے مقام نقیع کی طرف نکال باہر کر دیا گیا۔ صحابہ رضی اللہ عنہم م نے کہا: اے ا اللہ کے رسول! کیا ہم اسے قتل نہ کر دیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” مجھے نمازیوں کو قتل کرنے سے منع کیا گیا ہے۔ “ ابواسامہ کہتے ہیں کہ نقیع (نون کے ساتھ) مدینہ سے ایک جانب ایک جگہ کا نام ہے جو بقیع سے الگ ہے۔","f2":": اس روایت کی صحت و ضعف میں اختلاف ہے۔ عورتوں کی مشابہت اختیار کرنے والا اس قابل نہیں کہ مدینہ منورہ کے اندر رہ سکے۔ صحابہ نے اس وجہ سے اجازت چاہی تھی کہ اسے قتل کر دیا جائے۔ مگر آپ صلی اللہ علیہ وسلم نے اجازت نہیں دی۔ اور مسلمانوں اور مومنوں کو نمازی کے لفظ سے ذکر کیا کہ یہی انکا امتیازی وصف ہے۔ اور ہیجڑے بھی اسلام اور احکامِ اسلام کے کے اسی طرح مکلف ہیں جس طرح دوسرے مرد اور عورتیں۔"}],[4929,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ان کے ہاں تشریف لائے ان کے پاس ایک ہجڑا بیٹھا ہوا تھا اور وہ ان کے بھائی عبداللہ سے کہہ رہا تھا: اگر کل اللہ طائف کو فتح کرا دے تو میں تمہیں ایک عورت بتاؤں گا، کہ جب وہ سامنے سے آتی ہے تو چار سلوٹیں لے کر آتی ہے، اور جب پیٹھ پھیر کر جاتی ہے تو آٹھ سلوٹیں لے کر جاتی ہے، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انہیں اپنے گھروں سے نکال دو ۱؎\"۔ ابوداؤد کہتے ہیں: «تقبل بأربع» کا مطلب ہے عورت کے پیٹ میں چار سلوٹیں ہوتی ہیں یعنی پیٹ میں چربی چھا جانے کی وجہ سے خوب موٹی اور تیار ہے۔\n§وضاحت\n۱؎ : کیوں کہ وہ عورتوں کی خوبی و خرابی کا شعور رکھتے ہیں گو جماع پر قادر نہیں ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم ان کے ہاں تشریف لائے اور دیکھا کہ ان کے ہاں ایک ہیجڑا ہے اور وہ ان (ام سلمہ رضی اللہ عنہا ا) کے بھائی عبداللہ سے کہہ رہا ہے کہ اگر کل ا اللہ تمہیں طائف فتح کرا دے تو میں تمہیں ایک عورت کے متعلق بتاؤں گا جو چار سے آتی اور آٹھ سے لوٹتی ہے۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” انہیں اپنے گھروں سے نکال دو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: اس کا مطلب یہ تھا کہ عورت کے پیٹ پر (فربہ اندام ہونے کی وجہ سے) چار بل پڑتے ہیں۔ (عورت کے پیٹ پر سامنے کی جانب سے چار بل اور جب پشت پھیرے تو پہلوؤں کی جانب سے یہی بل چار چار ہو کر آٹھ بن جاتے ہیں تو عرب میں عورت کا اس انداز سے فربہ اندام ہونا حسن سمجھا جاتا ہے۔)","f2":"فسادی مزاج افراد کو گھروں میں آنے جانے کا موقع دینا معاشرے میں فساد بڑھانے کا ذریعہ ہے۔ اس لیئے اپنے گھروں کو ان سے پاک صاف رکھنا ضروری ہے۔ تو موجودہ دور کے ریڈیو، ٹی وی، وی سی آر، ڈش، کیبل، نیز عریاں تصاویر والے رسالے اخبارات رسالے سبھی اسی ضمن میں آتے ہیں اور فی الواقع ان چیزوں کے نا گفتہ بہ اثرات بھی ہمارے گھروں اور ماحول میں نمایاں ہیں۔ والی اللہ المشتکی۔ ان سے چھُٹکارا حاصل کرنا واجب ہے۔\nباب نمبر 54: گڑیوں سے کھیلنے کا بیان"}],[4930,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے زنانے مردوں اور مردانی عورتوں پر لعنت فرمائی اور فرمایا:\"انہیں اپنے گھروں سے نکال دو اور فلاں فلاں کو نکال دو\" یعنی ہجڑوں کو۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ہیجڑے بننے والے مردوں اور مردانہ انداز اختیار کرنے والوں عورتوں پر لعنت فرمائی ہے۔ اور فرمایا ” انہیں اپنے گھروں سے نکال باہر کرو، اور فلاں فلاں ہیجڑے کو باہر نکال دو۔ “"}],[4931,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں گڑیوں سے کھیلا کرتی تھی، کبھی کبھی رسول اللہ صلی اللہ علیہ وسلم میرے پاس آتے، میرے پاس لڑکیاں ہوتیں، تو جب آپ اندر آتے تو وہ باہر نکل جاتیں اور جب آپ باہر نکل جاتے تو وہ اندر آ جاتیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ میں گڑیوں کے ساتھ کھیلا کرتی تھی۔ تو بسا اوقات رسول اللہ صلی اللہ علیہ وسلم تشریف لے آتے اور میرے ہاں (محلے کی) بچیاں ہوتیں۔ جب آپ صلی اللہ علیہ وسلم تشریف لاتے تو وہ چلی جاتیں اور جب آپ صلی اللہ علیہ وسلم چلے جاتے تو وہ آ جایا کرتی تھیں۔"}],[4932,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم غزوہ تبوک یا خیبر سے آئے، اور ان کے گھر کے طاق پر پردہ پڑا تھا، اچانک ہوا چلی، تو پردے کا ایک کونا ہٹ گیا، اور عائشہ رضی اللہ عنہا کی گڑیاں نظر آنے لگیں، آپ نے فرمایا: \"عائشہ! یہ کیا ہے؟\"میں نے کہا: میری گڑیاں ہیں، آپ نے ان گڑیوں میں ایک گھوڑا دیکھا جس میں کپڑے کے دو پر لگے ہوئے تھے، پوچھا: یہ کیا ہے جسے میں ان کے بیچ میں دیکھ رہا ہوں؟ وہ بولیں: گھوڑا، آپ نے فرمایا: \"اور یہ کیا ہے جو اس پر ہے؟\" وہ بولیں: دو بازو، آپ نے فرمایا:\"گھوڑے کے بھی بازو ہوتے ہیں؟ وہ بولیں: کیا آپ نے نہیں سنا کہ سلیمان علیہ السلام کا ایک گھوڑا تھا جس کے بازو تھے، یہ سن کر آپ ہنس پڑے یہاں تک کہ میں نے آپ کی داڑھیں دیکھ لیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم غزوہ تبوک یا خیبر سے واپس تشریف لائے تو میرے طاقچے کے آگے پردہ پڑا ہوا تھا۔ ہوا چلی تو اس نے پردے کی ایک جانب اٹھا دی تب سامنے میرے کھلونے اور گڑیاں نظر آئے۔ آپ نے پوچھا ” عائشہ یہ کیا ہے؟ “ میں نے کہا: یہ میری گڑیاں ہیں۔ آپ نے ان میں کپڑے کا ایک گھوڑا بھی دیکھا جس کے دو پر تھے۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” میں ان کے درمیان یہ کیا دیکھ رہا ہوں؟ “ میں نے کہا: یہ گھوڑا ہے۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” اور اس کے اوپر کیا ہے؟ “ میں نے کہا: اس کے دو پر ہیں۔ آپ صلی اللہ علیہ وسلم نے کہا ” کیا گھوڑے کے بھی پر ہوتے ہیں؟ “ عائشہ رضی اللہ عنہا ا نے کہا: آپ نے سنا نہیں کہ سیدنا سلیمان علیہ السلام کے گھوڑے کے پر تھے؟ کہتی ہیں: چنانچہ رسول اللہ صلی اللہ علیہ وسلم اس قدر ہنسے کہ میں نے آپ صلی اللہ علیہ وسلم کی ڈاڑھیں دیکھیں۔","f2":") بچوں اور بچیوں کو نا صرف اجازت ہے بلکہ انکا فطری حق ہے کہ انکو کھیلنے کے مواقع فراہم کئے جائیں۔ مگر واجب ہے کہ انکی تفریحات شرعی مزاج سے ہم آہنگ ہوں۔\n2) بچیاں اگر اپنے طور پر ہاتھ سے گڑیاں گڈے وغیرہ بنائیں تو جائز ہے۔ اور یہ ان ممنوعہ تصاویر میں شامل نہیں جنکا بنانا یا رکھنا ناجائز ہو۔ تاہم خیال رہے کہ موجودہ دور میں ان کھلونوں کی جو ترقی یافتہ جدید صورت ہے کہ پلاسٹک کپڑے اور پتھر وغیرہ سے بنے بالکل نقل مطابق اصل ہوتے ہیں۔ ان کے بارے میں راجع یہی ہے کہ یہ جائز نہیں۔ جبکہ کچھ گھروں میں انکو بطور آرائش نمایاں کت کے رکھا جاتا ہے جس کی کسی طرح اجازت نہیں دی جاسکتی۔"}],[4933,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے شادی کی، میں سات سال کی تھی، پھر جب ہم مدینہ آئے، تو کچھ عورتیں آئیں، بشر کی روایت میں ہے: پھر میرے پاس (میری والدہ) ام رومان آئیں، اس وقت میں ایک جھولہ پر تھی، وہ مجھے لے گئیں اور مجھے سنوارا سجایا پھر مجھے رسول اللہ صلی اللہ علیہ وسلم کے پاس لے گئیں، تو آپ نے میرے ساتھ رات گزاری، اس وقت میں نو سال کی تھی وہ مجھے لے کر دروازے پر کھڑی ہوئیں، میں نے کہا: «هيه هيه» ۔ (ابوداؤد کہتے ہیں: «هيه هيه» کا مطلب ہے کہ انہوں نے زور زور سے سانس کھینچی)، عائشہ کہتی ہیں: پھر میں ایک کمرے میں لائی گئی تو کیا دیکھتی ہوں کہ وہاں انصار کی کچھ عورتیں (پہلے سے بیٹھی ہوئی) ہیں، انہوں نے «على الخير والبركة» کہہ کر مجھے دعا دی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے شادی کی تو میری عمر سات سال یا چھ سال تھی۔ جب ہم مدینہ منورہ آئے تو چند عورتوں آئیں۔ بشر بن خالد کے الفاظ ہیں: (میری والدہ) ام رومان آئیں۔ جبکہ میں ایک جھولے پر تھی اور وہ مجھے لے گئیں۔ مجھے تیار کیا، بنایا سنوارا اور رسول اللہ صلی اللہ علیہ وسلم کے ہاں بھیج دیا گیا۔ میری رخصتی ہوئی تو میری عمر نو سال تھی۔ (میری والدہ نے) مجھے دروازے پر کھڑا کر دیا تو میں نے کہا «هيه هيه» یعنی انکار کرنے کی آواز۔ امام ابوداؤد رضی اللہ عنہ اس کی وضاحت میں کہتے ہیں: یعنی میں نے لمبا (ٹھنڈا) سانس لیا اور مجھے ایک گھر میں داخل کر دیا گیا تو وہاں انصار کی کچھ عورتیں تھیں۔ انہوں نے دعائے خیر و برکت کے ساتھ میرا استقبال کیا۔ حماد اور ابو اسامہ کی روایت ایک دوسرے میں مل گئی ہے۔"}],[4934,"ابواسامہ سے اسی کے ہم مثل مروی ہے اس میں ہے (ان عورتوں نے کہا) اچھا نصیبہ ہے پھر میری ماں نے مجھے ان عورتوں کے سپرد کر دیا، انہوں نے میرا سر دھویا اور مجھے سجایا سنوارا (میں جان نہیں پا رہی تھی کہ یہ سب کیا اور کیوں ہو رہا ہے) کہ چاشت کے وقت رسول اللہ صلی اللہ علیہ وسلم نے ہی آ کر مجھے حیرانی میں ڈال دیا تو ان عورتوں نے مجھے آپ کے حوالہ کر دیا۔","صحیح",{"u2":"جناب ابواسامہ نے مذکورہ بالاحدیث کے مثل روایت کیا اور کہا کہ ا اللہ کرے تیری قسمت اچھی ہو۔ اور مجھے ان عورتوں کے حوالے کر دیا۔ انہوں نے میرا سر دھویا اور مجھے بنایا سنوارا۔ اور میں اس وقت ڈر سی گئی جب دن چڑھے رسول اللہ صلی اللہ علیہ وسلم میرے سامنے ہوئے تو انہوں نے مجھے آپ کے حوالے کر دیا۔"}],[4935,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب ہم مدینہ آئے، تو میرے پاس کچھ عورتیں آئیں، اس وقت میں جھولے پر کھیل رہی تھی، اور میرے بال چھوٹے چھوٹے تھے، وہ مجھے لے گئیں، مجھے بنایا سنوارا اور مجھے رسول اللہ صلی اللہ علیہ وسلم کے پاس لے کر آئیں، آپ نے میرے ساتھ رات گزاری کی، اس وقت میں نو سال کی تھی۔","صحیح الإسناد",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ جب ہم مدینے آئے تو میرے پاس کچھ عورتیں آئیں جبکہ میں ایک جھولے پر کھیل رہی تھی۔ اور میرے بال کانوں سے نیچے اتر رہے تھے۔ تو وہ مجھے لے گئیں اور مجھے تیار کیا &lsquo; بنایا سنوارا۔ پھر وہ مجھے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں لے آئیں۔ میری (رسول اللہ صلی اللہ علیہ وسلم کے گھر) رخصتی ہوئی تو میری عمر نو سال تھی۔"}],[4936,"ہشام بن عروہ سے اسی سند سے یہی حدیث مروی ہے اس میں ہے: میں جھولے پر تھی اور میرے ساتھ میری سہیلیاں بھی تھیں، وہ مجھے ایک کوٹھری میں لے گئیں تو کیا دیکھتی ہوں کہ وہاں انصار کی کچھ عورتیں ہیں انہوں نے مجھے خیر و برکت کی دعائیں دیں۔","صحیح",{"u2":"جناب ہشام بن عروہ نے اپنی سند سے اس روایت میں بیان کیا کہ سیدہ عائشہ رضی اللہ عنہا ا نے کہا: میں اپنی سہیلیوں کے ساتھ جھولے پر تھی ‘ تو انہوں نے مجھے ایک گھر میں داخل کر دیا۔ وہاں انصار کی کچھ عورتیں تھیں ‘ تو انہوں نے خیر و برکت کی دعا کے ساتھ میرا استقبال کیا۔"}],[4937,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم مدینہ آئے اور بنی حارث بن خزرج میں اترے، قسم اللہ کی میں دو شاخوں کے درمیان ڈلے ہوئے جھولے پر جھولا جھول رہی تھی کہ میری ماں آئیں اور مجھے جھولے سے اتارا، میرے سر پر چھوٹے چھوٹے بال تھے اور راوی نے پوری حدیث بیان کی۔","حسن صحیح",{"u2":"یحییٰ بن عبدالرحمٰن بن حاطب بیان کرتے ہیں کہ ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے کہا: ہم مدینے آئے اور بنو حارث بن خزرج کے ہاں ہمارا قیام ہوا۔ کہتی ہیں ‘ ا اللہ کی قسم! میں کھجور کی دو لکڑیوں میں لگے ایک جھولے پر تھی کہ میری والدہ آئیں ‘ تو انہوں نے مجھے اس سے اتارا، اور میرے بال چھوٹے چھوٹے تھے۔ اور پوری حدیث بیان کی۔","f2":"آج کل کے بعض جدید مفکرین اور بزعمِ خویش نویس مزاج مجددین کو ان احادیث اور صغر سنی (چھوٹی عمر) کے اس نکاح اور شادی پر بہت اعتراض ہے۔ وہ مختلف انداز سے اسکا انکار کرتے ہیں حالانکہ اس انکار کی کوئی حقیقی وجہ نہیں ہے۔ ان لوگوں کو چاہیئے کہ طبی، معاشرتی، علاقائی، اور جغرافیائی احوال و ظروف کا دقیق نظری سے مطالعہ کریں تو واضح ہوگا کہ بعض احوال اور بعض علاقوں میں اس عمر کی لڑکیوں کا بالغ ہو جانا کوئی اچھنبے کی بات نہیں ہے اور پھر عائلی زندگی کے فطری مراحل سے گزرنا ان کے لیئے کوئی انہونی بات نہیں ہوتی۔ اس واقعے میں بالخصو ص یہ بات پیشِ نظر رہے کہ یہ نکاح حضرت ابو بکر صدیق رضی اللہ عنہ کو رسو ل اللہ صلی اللہ علیہ وسلم کے ہاں مزید قربت و شرف دینے کے لیئے عمل میں لایا گیا تھا۔ تا کہ انہیں رسو ل اللہ صلی اللہ علیہ وسلم کے ہاں وقت بے وقت آنے میں کوئی دشواری پیش نہ آئے۔ اور انکا رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ربط و ضبط مزید گہرا ہو جائے۔ اور پھر اس نکاح کی بنیاد وہ خواب تھے جو تواتر کے ساتھ نبی صلی اللہ علیہ وسلم کو دکھلائے گئے تھے۔ یہ خواب اس بات کی طرف اشارہ تھے کہ سیدہ عائشہ رضی اللہ عنھما کا نکاح نبی صلی اللہ علیہ وسلم کے ساتھ مقدر کر دیا گیا ہے۔ یہ احادیث صحیح اور واقعہ تاریخی شرعی اور فقہی اعتبار سے بالکل صحیح اور عین حق ہے اسکا انکار در حقیقت انکارِ حدیث کا زینہ ہے۔"}],[4938,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے چوسر کھیلا اس نے اللہ اور اس کے رسول کی نافرمانی کی\"۔","حسن",{"u2":"سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص چوسر کھیلا اس نے ا اللہ اور اس کے رسول کی نافرمانی کی۔ “","f2":") (نرد) کا ترجمہ (لُعُبة الطا و لة) کیا گیا ہے یعنی لکڑی کے تختے پر کھیل جس سے چوسر، کیرم بورڈ، اور لڈو وغیرہ کی قسم کے کھیل مراد ہو سکتے ہیں۔\n2) ہمارے فاضل محقق مذکورہ روایت کی تحقیق کرتے ہوئے لکھتے ہیں کہ یہ روایت سندََا ضعیف ہے لیکن صحیح مسلم کی حدیث نمبر 12260 اس روایت سے کفایت کرتی ہے لہذا معلوم ہوا کہ یہ روایت معناََ قابلِ حجت ہے نیز شیخ البانی رحمہ اللہ نے بھی مذکورہ بالا روایت کو حسن قرار دیا ہے۔"}],[4939,"بریدہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے نردشیر (چوسر) کھیلا گویا اس نے اپنا ہاتھ سور کے گوشت اور خون میں ڈبو دیا۔","صحیح",{"u2":"جناب سلیمان بن بریدہ اپنے والد سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شخص نرد شیر (چوسر) کھیلا گویا اس نے اپنا ہاتھ سور کے گوشت اور خون سے آلودہ کیا۔ “","f2":") ایسے کھیل جو وقت اور سرمائے کے ضیاع کا باعث ہوں قطعاََ ناجا ئز ہیں۔ کھیل کا اصل مقصد ذہنی راحت اور جسمانی ورزش ہوتا ہے۔ اگر جائز کھیلوں میں بھی وقت ضائع ہوتا ہو تو وہ ناجائز ہو جائیں گے۔\n2) ان صحیح احادیث اور مذکورہ اصول کی رو سے کرکٹ جیسے کھیل کی قطعاَ کو ئی اجازت نہیں۔ اور شرعا یہ ناجائز کھیل ہے کیونکہ اس کھیل میں جس طرح بے دردی سے بے شمار لوگوں کا وقت ضائع ہوتا اور کیا جاتا ہے اسکی مثال کسی اور کھیل میں نہیں ملتی۔ مزید برآں کرکٹ جیسے کھیل میں نماز روزے کی کو ئی پر واہ ہوتی ہے نہ کسی اور دینی و دنیوی کام کا خیال۔ اس کے ساتھ ساتھ یہ کھیل بین الاقوالی سطح پر جوئے جیسی بد ترین لعنت اور کبیرہ گناہ کا بہت بڑا ذریعہ بن چکا ہے۔ قومی اور ملکی سطح پر ا س کے نقصانات اور مضر اثرات بے پناہ ہیں اور اس کے مقابلے میں فائدہ کچھ بھی نہیں۔ ایسا کھیل کھیلنا اور اس کی حوصلہ افزائی کرنا تو دور کی بات ایک بندہ رحمان کی شان یہ بیان کی گئی ہے کہ وہ ایسے لغو اور بے فائدہ کام کی طرف دیکھنے کا بھی روادار نہیں ہوتا بلکہ وہاں سے شرافت سے گزر جاتا ہے۔ قرآن مقدس میں ارشادِ باری تعالی ہے رحمان کے بندے جب کسی لغو (دینی اور دنیوی اعتبار سے بے فائدہ) چیز سے گزرتے ہیں تو باعزت طور سے گزر جاتے ہیں۔ ایسی خوبصور ت اور حساس شریعت اور ایسا پاکیزہ دین جس میں چوسر کھیلنے کی اجازت نہیں ہے اس دینِ فطرت میں کرکٹ جیسے کھیل کی اجازت کیسے ہو سکتی ہے؟"}],[4940,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا کہ وہ کبوتری کا (اپنی نظروں سے) پیچھا کر رہا ہے(یعنی اڑا رہا ہے) تو آپ نے فرمایا: \"ایک شیطان ایک شیطانہ کا پیچھا کر رہا ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی دونوں شیطان ہیں، کبوتر اڑانے والا اس لئے شیطان ہے کہ وہ اللہ سے غافل اور بے پرواہ ہے، اور کبوتر اس لئے شیطان ہے کہ وہ اڑانے والے کی غفلت کا سبب بنا ہے۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا وہ کبوتری کے پیچھے لگا ہوا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” شیطان ‘ شیطاننی کے پیچھے لگا ہوا ہے۔ “","f2":"کبوتر بازی، بٹیر بازی، مرغ لڑانا وغیرہ سب ناجائز مشاغل ہیں ہاں اگر بطور تجارت یا زینت گھر میں رکھے ہوں ت و جائز ہے۔"}],[4941,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"رحم کرنے والوں پر رحمن رحم فرماتا ہے، تم زمین والوں پر رحم کرو، تو آسمان والا تم پر رحم کرے گا\"۔","",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ ” رحم کرنے والوں پر رحمٰن رحم فرمائے گا۔ تم اہل زمین پر رحم کرو ‘ آسمان والا تم پر رحم کرے گا۔ “ مسدد نے (سند میں وارد ” ابوقابوس “ کے متعلق) یہ نہیں کہا کہ وہ سیدنا عبداللہ بن عمرو رضی اللہ عنہ کا مولیٰ تھا۔ نیز بوضاحت کہا کہ سیدنا عبداللہ بن عمرو رضی اللہ عنہ نے روایت کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ہے۔"}],[4942,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے صادق و مصدوق ابوالقاسم صلی اللہ علیہ وسلم کو جو اس کمرے میں رہتے تھے ۱؎ فرماتے سنا ہے:\"رحمت (مہربانی و شفقت) صرف بدبخت ہی سے چھینی جاتی ہے ۲؎\"۔\n§وضاحت\n۱؎ : اشارہ ہے عائشہ رضی اللہ عنہا کے حجرہ کی جانب جس میں نبی اکرم صلی اللہ علیہ وسلم رہتے تھے۔ ۲؎ : یعنی بدبخت اپنی سخت دلی کے باعث دوسروں پر شفقت و مہربانی نہیں کرتا جب کہ نیک بخت کا حال اس کے برعکس ہوتا ہے یعنی وہ بے رحم نہیں ہوتا۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے اس حجرے والے یعنی سیدنا ابوالقاسم صادق و مصدوق صلی اللہ علیہ وسلم سے سنا ہے ‘ آپ صلی اللہ علیہ وسلم فرماتے تھے ” کسی بدبخت سے ہی رحمت چھینی جاتی ہے۔ “","f2":"رسول اللہ صلی اللہ علیہ وسلم کا وصف صادق و مصدوق یوں ہے کہ آپ صلی اللہ علیہ وسلم اپنے قول و فعل اور خبر میں صادق (سچے) تھے۔ اور اللہ اس کے فرشتوں اور مومنین نے آپ صلی اللہ علیہ وسلم کے نبی ورسول ہونے کی تصدیق کی ہے تو اس اعتبار سے آپ مصدوق ہوئے۔\n2) آپ صلی اللہ علیہ وسلم کے رحم کا دائرہ، اپنے، پرائے، چھوٹے، بڑے زیر دست، ملازمین اور حیوانوں تک کو وسیع ہے۔ صاحبِ ایمان کو کسی بھی موقع پر کسی کے ساتھ ظلم کا معاملہ نہیں کرنا چاہیئے۔"}],[4943,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو ہمارے چھوٹے پر رحم نہ کھائے اور ہمارے بڑے کا حق نہ پہنچانے (اس کا ادب و احترام نہ کرے) تو وہ ہم میں سے نہیں\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو ہمارے چھوٹوں پر شفقت نہ کرے اور ہمارے بڑوں کا حق نہ پہچانے وہ ہم میں سے نہیں۔ “"}],[4944,"تمیم داری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یقیناً دین خیر خواہی کا نام ہے، یقیناً دین خیر خواہی کا نام ہے، یقیناً، دین خیر خواہی کا نام ہے\" لوگوں نے عرض کیا: اللہ کے رسول! کن کے لیے؟ آپ نے فرمایا: \"اللہ کے لیے، اس کی کتاب کے لیے، اس کے رسول کے لیے، مومنوں کے حاکموں کے لیے اور ان کے عام لوگوں کے لیے یا کہا مسلمانوں کے حاکموں کے لیے اور ان کے عام لوگوں کے لیے ۱؎\"۔\n§وضاحت\n۱؎ : اللہ کے لئے خیر خواہی کا مفہوم یہ ہے کہ بندہ اللہ کی وحدانیت کا قائل ہو اور اس کی ہر عبادت خالص اللہ کے لئے ہو، کتاب اللہ کے لئے خیر خواہی یہ ہے کہ اس پر ایمان لائے اور عمل کرے، رسول کے لئے خیر خواہی یہ ہے کہ رسول کی نبوت کی تصدیق کرنے کے ساتھ وہ جن چیزوں کا حکم دیں اسے بجا لائے اور جس چیز سے منع کریں اس سے باز رہے، مسلمانوں کے حاکموں کے لئے خیر خواہی یہ ہے کہ حق بات میں ان کی تابعداری کی جائے اور حقیقی شرعی وجہ کے بغیر ان کے خلاف بغاوت کا راستہ نہ اپنایا جائے، اور عام مسلمانوں کے لئے خیرخواہی یہ ہے کہ ان میں امربالمعروف اور نہی عن المنکر کا فریضہ انجام دیا جائے۔","صحیح",{"u2":"سیدنا تمیم داری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” دین نصیحت (خلوص و خیر خواہی) کا نام ہے۔ دین نصیحت کا نام ہے۔ دین نصیحت کا نام ہے۔ صحابہ نے پوچھا: اے ا اللہ کے رسول! کس کے لیے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ا اللہ کے لیے، اس کی کتاب کے لیے، اس کے رسول کے لیے، اہل ایمان کے ائمہ و حکام اور عام لوگوں کے لیے۔ “","f2":"اللہ کے لیئے نصیحت کا مفہوم یہ ہے کہ انسان اپنے رب کی عبودیت میں سرشار رہے۔ اس کی توحید کا اقرار و اظہار کرے اور شرک سے بیزار اور دور رہے۔ رسول لے لیئ نصیحت یہ ہے کہ اسکی رسالت کا اقرار و اظہار اور بے میل کی اطاعت کرے بدعات سے بیزار اور دور رہے۔ کتاب اللہ کو اپنا دستورِ زندگی بنائے اور تمام مسائل اسکی روشنی میں سر انجام دینے کے لیئے کو شاں رہے۔ حکام ِ وقت کے لئے نصیحت یہ ہے کہ خیر و خوبی کے کاموں میں انکی اطاعت کرے اور نکا معاون بنے۔ لوگوں کے اندر بلا وجہ انکی مخالفت کے جذبات نہ اُبھارے اور عام مسلمانوں میں حسبِ مراتب دین ع دُنیا کے معاملات میں بھلائی سے پیش آئے یہی انکے لیئے نصیحت ہے۔"}],[4945,"جریر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سمع و طاعت پر بیعت کی، اور یہ کہ میں ہر مسلمان کا خیرخواہ ہوں گا، راوی کہتے ہیں: وہ (یعنی جریر) جب کوئی چیز بیچتے یا خریدتے تو فرما دیتے: ہم جو چیز تم سے لے رہے ہیں، وہ ہمیں زیادہ محبوب و پسند ہے اس چیز کے مقابلے میں جو ہم تمہیں دے رہے ہیں، اب تم چاہو بیچو یا نہ بیچو، خریدو یا نہ خریدو۔","صحیح الإسناد",{"u2":"سیدنا جریر (جریر بن عبداللہ بجلی) رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سننے اور اطاعت کرنے اور ہر مسلمان کے لیے خیر خواہی کرنے پر بیعت کر رکھی ہے۔ راوی نے کہا: چنانچہ وہ (سیدنا جریر رضی اللہ عنہ) جب کوئی چیز فروخت کرتے یا خرید کرتے تو کہتے: تحقیق جو چیز ہم نے تم سے لی ہے وہ ہمیں اپنی چیز سے جو ہم نے تمہیں دی ہے، زیادہ پیاری ہے، چنانچہ تمہیں اختیار ہے (اپنی چیز یا مال واپس لینا چاہو تو لے سکتے ہو)۔"}],[4946,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص کسی مسلمان کی دنیاوی تکالیف میں سے کوئی تکلیف دور کر دے، تو اللہ اس کی قیامت کی تکالیف میں سے کوئی تکلیف دور فرمائے گا، اور جس نے کسی نادار و تنگ دست کے ساتھ آسانی و نرمی کا رویہ اپنایا تو اللہ تعالی اس کے ساتھ دنیا و آخرت میں آسانی کا رویہ اپنائے گا، اور جو شخص کسی مسلمان کا عیب چھپائے گا تو اللہ تعالی دنیا و آخرت میں اس کا عیب چھپائے گا، اللہ تعالی اپنے بندے کی مدد میں رہتا ہے، جب تک کہ بندہ اپنے بھائی کی مدد میں رہتا ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے کسی مسلمان سے دنیا کا ایک دکھ دور کیا اللہ عزوجل اس سے قیامت کے روز کا ایک دکھ دور کرے گا۔ اور جس نے کسی مشکل میں پڑے شخص کے لیے آسانی کی ‘ ا اللہ اس کے لیے دنیا اور آخرت میں آسانی کرے گا۔ اور جس نے کسی مسلمان کی پردہ داری کی اللہ عزوجل دنیا اور آخرت میں اس کی پردہ داری کرے گا اور اللہ عزوجل اس وقت تک بندے کی مدد میں رہتا ہے جب تک کہ بندہ اپنے بھائی کی مدد میں رہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ عثمان (عثمان بن ابی شیبہ) نے ابومعاویہ سے یہ جملہ روایت نہیں کیا ” جس نے کسی مشکل میں پڑے شخص کے لیے آسانی کی۔ “","f2":"اس حدیث سے وہ معروف ضابطہ ثابت ہوتا ہے کہ بندئ کو جزا ہمیشہ اس طرح کی ملتی ہے جیسا اس نے عمل کیا ہو جیسا کروگے ویسا بھروگے۔"}],[4947,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ تمہارے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر بھلی بات صدقہ ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی ہر اچھی بات میں ایک صدقہ کا ثواب ہوتا ہے۔","صحیح",{"u2":"سیدنا حذیفہ رضی اللہ عنہ نے بیان کیا کہ تمہارے نبی کریم صلی اللہ علیہ وسلم نے فرمایا ہے ” ہر نیکی صدقہ ہے۔ “","f2":"صدقے کا مفہوم صرف مال ہی سی متعلق نہیں بلکہ ہر چھوٹی بڑی نیکی صدقہ ہے۔"}],[4948,"ابوالدرداء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے دن تم اپنے اور اپنے باپ دادا کے ناموں کے ساتھ پکارے جاؤ گے، تو اپنے نام اچھے رکھا کرو ۱؎\"۔ ابوداؤد کہتے ہیں: ابن ابی زکریا نے ابودرداء کا زمانہ نہیں پایا ہے۔\n§وضاحت\n۱؎ : معلوم ہوا کہ اگر کسی کا نام اچھا نہ ہو تو وہ بدل کر اپنا اچھا نام رکھ لے، اور سب سے بہتر نام اللہ تعالی کے نزدیک عبداللہ اور عبدالرحمن ہیں۔","ضعیف",{"u2":"سیدنا ابودرداء رضی اللہ عنہ سے روایت ہے کہرسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم قیامت کے دن اپنے اور اپنے آباء کے ناموں سے پکارے جاؤ گے۔ چنانچہ اپنے نام اچھے اچھے رکھا کرو۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ابن ابو زکریا نے سیدنا ابودرداء رضی اللہ عنہ کو نہیں پایا۔"}],[4949,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے نزدیک سب سے پسندیدہ نام عبداللہ اور عبدالرحمٰن ہیں\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” سب ناموں میں سے عبداللہ اور عبدالرحمٰن اللہ عزوجل کو بہت ہی پیارے ہیں۔“"}],[4950,"ابو وہب جشمی رضی اللہ عنہ، انہیں شرف صحبت حاصل ہے، کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"انبیاء کے نام رکھا کرو، اللہ تعالی کے نزدیک محبوب و پسندیدہ نام \"عبداللہ\" اور \"عبدالرحمٰن\" ہیں، اور سب سے سچے نام \"حارث\" و \"ہمام\" ہیں ۱؎، اور سب سے نا پسندیدہ و قبیح نام \"حرب\" و \"مرہ\" ہیں ۲؎۔\n§وضاحت\n۱؎ : کیونکہ یہ دونوں اپنے مشتق منہ سے معنوی طور پر مطابقت رکھتے ہیں چنانچہ حارث کے معنی ہیں کمانے والا ، اور ہمام کے معنی قصد و ارادہ رکھنے والے کے ہیں ، اور کوئی شخص ایسا نہیں ہے جو قصد وارادہ سے خالی ہو ، یہی وجہ ہے کہ یہ دونوں نام سچے ہیں۔۲؎ : ان دونوں ناموں میں ان کے ذاتی وصف کے اعتبار سے جو قباحت ہے وہ بالکل واضح ہے۔","صحیح",{"u2":"سیدنا ابو وہب جشمی رضی اللہ عنہ سے روایت ہے اور انہیں صحابی ہونے کا شرف حاصل ہے وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” انبیاء کے نام رکھا کرو اور ا اللہ کو سب ناموں میں زیادہ محبوب عبداللہ اور عبدالرحمٰن ہیں۔ سب سے بڑھ کر واقعیت سے قریب یہ نام ہیں، حارث (کھیتی باڑی کرنے والا) اور ہمام (رنج و فکر میں پڑا ہوا) اور یہ نام سب سے برے ہیں ‘ حرب (لڑاکا) اور مرہ (کڑوا)۔ “","f2":"1) عبداللہ اور عبد الرحمن جیسے ناموں میں اللہ عزوجل کی طرف بندگی کی نسبت اور اسکا اظہار ہے تو سعادت ہے اس بندے کے لیئے جسے اُٹھتے بیٹھتے موقع بے موقع اس عالی نسب سے پکارا جائے۔ اس کے بالمقابل انسانوں میں کون ہوگا جسے اسبابِ رزق کی فکر نہ ہو یا کسی طرح کے رنج و الم سے محفوظ ہو؟ اس لیئے حارث اور حمام ایسے نام ہیں جو حقیقت سے قریب تر ہیں۔ نیز بقول بعض نام کا اپنے مسمی پر کچھ معنوی اثر بھی ہوتا ہے اس لیئے اچھے نام رکھنے چاہیئں۔ حرب (لڑاکا) اور مرہ (کڑوہ) بہت برے نام ہیں لہذا ان سے بچنا چاہیئے۔\n2) مذکورہ روایت کی تحقیق کی بابت ہمارے فاضل محقق لکھتے ہیں کہ یہ روایت سنداَ ضعیف ہے، تاہم اس کے شواہد ہیں۔ لیکن اس شواہد کی تفصیل ذکر نہیں کی وہ شواہد کس درجے کے ہیں۔۔۔۔ مذکورہ بالا روایت کے الفاظ (احب االا اسماء عبدالله و الرحمن) صحیح مسلم (حدیث 2132) اور سنن ابو داؤد (حدیث 4949) میں صحیح سند سے مروی ہیں جنہیں خود اُنھوں نے بھی صحیح قرار دیا ہے۔ نیز روایت کے باقی الفاظ: (تسمو با سماء الا نبياء) کے الفاظ کے سوا صحیح ہے جیسا کہ شیخ البانی رحمہ اللہ نے ذکر کیا ہے۔ تفصیل کے لیئے دیکھئے: (الصحیحة حديث 904)"}],[4951,"انس رضی اللہ عنہ کہتے ہیں کہ عبداللہ بن ابی طلحہ کی پیدائش پر میں ان کو لے کر نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا آپ اس وقت عبا پہنے ہوئے تھے، اور اپنے ایک اونٹ کو دوا لگا رہے تھے، آپ نے پوچھا: کیا تمہارے پاس کھجور ہے؟ میں نے کہا: ہاں، پھر میں نے آپ صلی اللہ علیہ وسلم کو کئی کھجوریں پکڑائیں، آپ نے ان کو اپنے منہ میں ڈالا اور چبا کر بچے کا منہ کھولا اور اس کے منہ میں ڈال دیا تو بچہ منہ چلا کر چوسنے لگا، اس پر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انصار کی پسندیدہ چیز کھجور ہے\" اور آپ نے اس لڑکے کا نام\"عبداللہ\" رکھا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کہتے ہیں کہ جب (میرے سوتیلے بھائی) عبداللہ بن ابوطلحہ کی ولادت ہوئی تو میں اسے نبی کریم صلی اللہ علیہ وسلم کی خدمت میں لے گیا۔ جب کہ نبی کریم صلی اللہ علیہ وسلم ایک عباء پہنے اپنے اونٹ کو گندھک لگا رہے تھے۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا تمہارے پاس کھجور ہے؟ “ میں نے عرض کیا، جی ہاں۔ اور میں نے آپ صلی اللہ علیہ وسلم کو کئی کھجوریں پیش کیں۔ آپ صلی اللہ علیہ وسلم نے انہیں اپنے منہ میں ڈال کر چبایا، پھر بچے کا منہ کھول کر انہیں اس کے منہ میں ڈال دیا تو وہ اپنی زبان چلانے لگا۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” انصاریوں کی کھجور سے محبت! (یعنی دیکھو نومولود بھی کس چاہت سے کھا رہا ہے)۔ اور آپ صلی اللہ علیہ وسلم نے اس کا نام عبداللہ رکھا۔","f2":") نو مولود کو صالح افراد سے گھی دلوانے کا اہتما م کرنا مستحب ہے اور اس کے لیئے کھجور ایک اچھی شے ہے۔\n2) ساتویں دن سے پہلے بھی نام رکھا جاسکتا ہے۔\n3) رسول اللہ صلی اللہ علیہ وسلم اپنا کام کرنے میں کوئی عار محسوس نہیں کرتے تھے۔"}],[4952,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عاصیہ کا نام بدل دیا ۱؎، اور فرمایا: تو جمیلہ ہے ۲؎۔\n§وضاحت\n۱؎ : عاصیہ عمر کی بیٹی تھی جس کے معنی گنہگار و نافرمان کے ہیں۔ ۲؎ :یعنی آج سے تیرا نام جمیلہ (خوبصورت اچھے اخلاق و کردار والی) ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ” عاصیہ “ نام بدل دیا اور فرمایا ” تو جمیلہ (خوبصورت) ہے۔ “","f2":"عرب لوگ عاس اور عاصیہ نام رکھتے تھے۔ ان سے مراد ہوتی تھے ظلم و ذیادتی اور برائی سے انکار کرنے والا کرنے والی۔ مگر اس میں عصیان نافرمانی کا مفہوم بھی ہے۔ اس لیئے اس نام کو بدل دیا گیا۔"}],[4953,"محمد بن عمرو بن عطا سے روایت ہے کہ زینب بنت ابوسلمہ نے ان سے پوچھا: تم نے اپنی بیٹی کا نام کیا رکھا ہے؟ کہا: میں نے اس کا نام\"برہ\" رکھا ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس نام سے منع کیا ہے، میرا نام پہلے \"برہ\" رکھا گیا تھا تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: خود سے پاکباز نہ بنو، اللہ خوب جانتا ہے، تم میں پاکباز کون ہے، پھر (میرے گھر والوں میں سے) کسی نے پوچھا: تو ہم اس کا کیا نام رکھیں؟ آپ نے فرمایا: \"زینب\" رکھ دو۔","حسن صحیح",{"u2":"جناب محمد بن عمرو بن عطاء رضی اللہ عنہ فرماتے ہیں کہ سیدہ زینب بنت ابوسلمہ رضی اللہ عنہ ا نے مجھ سے پوچھا کہ تم نے اپنی بچی کا کیا نام رکھا ہے؟ میں نے بتایا کہ ” برہ “ (نیک، صالحہ) تو انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس نام سے منع فرمایا ہے۔ میرا نام ” برہ “ رکھا گیا تھا تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اپنے آپ کو اپنے منہ سے نیک اور صالح نہ کہلواؤ۔ اللہ تم میں سے نیک اور صالح لوگوں کو خوب جانتا ہے۔ “ پوچھا گیا: ہم اس کا کیا نام رکھیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” زینب نام رکھو۔ “","f2":"اپنے منہ میاں مٹھو بننا یعنی خود ہی اپنی مدح سرائی کرنا بہت برا ہے۔ اور اس میں ایسے نام بھی شامل ہیں جن میں مبالغہ پایا جاتا ہے۔\n2) زینب کے معانی کے معنی میں بیان کیا جاتا ہے کہ موٹے خرگوش یا حسین منظر یا اچھی خوشبو والے درخت کو زینب کہتے ہیں۔ یا بعض نے اے (زین اب) یعنی باپ کے لیئے زینت مر کب بتایا ہے۔(عون المعبود)"}],[4954,"اسامہ بن اخدری تمیمی رضی اللہ عنہ سے روایت ہے کہ ایک آدمی جسے \"اصرم\" (بہت زیادہ کاٹنے والا) کہا جاتا تھا، اس گروہ میں تھا جو رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تھا تو آپ نے اس سے پوچھا: تمہارا نام کیا ہے؟ اس نے کہا: میں \"اصرم\" ہوں، آپ نے فرمایا: \"نہیں تم \"اصرم\" نہیں بلکہ \"زرعہ\" (کھیتی لگانے والے) ہو، (یعنی آج سے تمہارا نام زرعہ ہے) ۔","صحیح",{"u2":"سیدنا اسامہ بن اخدری رضی اللہ عنہ سے روایت ہے کہ ” اصرم “ نامی ایک شخص اس وفد میں شامل تھا جو نبی کریم صلی اللہ علیہ وسلم کے ہاں آیا۔ آپ صلی اللہ علیہ وسلم نے اس سے پوچھا ” تمہارا نام کیا ہے؟ “ اس نے کہا: ” میں اصرم (کانٹے والا) ہوں “ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلکہ تم زرعہ ہو “ (بمعنی بونے اور کاشت کرنے والا)۔"}],[4955,"ابوشریح ہانی کندی رضی اللہ عنہ سے روایت ہے کہ جب وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنی قوم کے ساتھ وفد میں آئے، تو آپ نے ان لوگوں کو سنا کہ وہ انہیں ابوالحکم کی کنیت سے پکار رہے تھے، آپ نے انہیں بلایا، اور فرمایا: \"حکم تو اللہ ہے، اور حکم اسی کا ہے تو تمہاری کنیت ابوالحکم کیوں ہے؟\" انہوں نے کہا: میری قوم کے لوگوں کا جب کسی معاملے میں اختلاف ہوتا ہے تو وہ میرے پاس آتے ہیں اور میں ہی ان کے درمیان فیصلہ کرتا ہوں اور دونوں فریق اس پر راضی ہو جاتے ہیں، آپ نے فرمایا: \"یہ تو اچھی بات ہے، تو کیا تمہارے کچھ لڑکے بھی ہیں؟ انہوں نے کہا: شریح، مسلم اور عبداللہ میرے بیٹے ہیں\" آپ نے پوچھا: ان میں بڑا کون ہے؟ میں نے عرض کیا: \"شریح\" آپ نے فرمایا: تو تم \"ابوشریح ہو\"۔ ابوداؤد کہتے ہیں: شریح ہی وہ شخص ہیں جس نے زنجیر توڑی تھی اور یہ ان لوگوں میں سے تھے جو تستر میں فاتحانہ داخل ہوئے تھے۔ ابوداؤد کہتے ہیں: مجھے یہ خبر پہنچی ہے کی شریح نے ہی تستر کا دروازہ توڑا تھا اور وہی نالے کے راستے سے اس میں داخل ہوئے تھے۔","صحیح",{"u2":"سیدنا ہانی بن یزید رضی اللہ عنہ سے روایت ہے کہ جب وہ اپنی قوم کا وفد لے کر رسول اللہ صلی اللہ علیہ وسلم کے ہاں گئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان لوگوں کو سنا وہ اسے ” ابوالحکم “ کی کنیت سے پکارتے ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے اسے بلایا اور فرمایا ” حکم “ (فیصلہ کرنے والا) اللہ ہی ہے (یہ اسی کا نام ہے) اور تمام فیصلے اسی کی طرف ہیں۔ تمہیں یہ کنیت ” ابوالحکم “ کیونکر دی گئی ہے؟ “ اس نے عرض کیا: بیشک میری قوم والے جب کسی چیز میں اختلاف کرتے ہیں تو میرے پاس آ جاتے ہیں اور میں ان میں فیصلہ کر دیتا ہوں اور پھر دونوں راضی ہو جاتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یہ تو بہت اچھی بات ہے۔ تیرے بیٹے کون ہیں؟ “ میں نے کہا: شریح، مسلم اور عبداللہ۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” ان میں بڑا کون ہے؟ “ میں نے کہا: شریح۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تو تم ” ابوشریح “ ہو۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں یہ شریح وہی ہیں جنہوں نے قلعہ تستر کی زنجیر توڑی اور اس میں داخل ہوئے تھے۔ اور مجھے یہ بات پہنچی ہے کہ انہوں نے تستر کا دروازہ توڑا تھا اور سرنگ میں سے اس کے اندر گھسے تھے۔","f2":") مبالغہ آمیز نام اور کنیتیں رکھنا درست نہیںاور چاہیئے کہ غلط نام بدل دیئے جائیں۔\n2) بہتر یہ ہے کہ انسان اپنت بڑے بیٹے کے نام پر اپنی کنیت رکھے۔\n3) تُسر ایران میں علاقہ خوزستان میں ایک شہر کا نام ہے اسے یاشستر بھی کہتے ہیں۔"}],[4956,"سعید بن مسیب کے دادا (حزن رضی اللہ عنہ) سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان سے پوچھا: تمہارا نام کیا ہے؟ کہا: حزن ۱؎ آپ نے فرمایا: \"تم سہل ہو، انہوں نے کہا: نہیں، سہل روندا جانا اور ذلیل کیا جانا ہے، سعید کہتے ہیں: تو میں نے جانا کہ اس کے بعد ہم لوگوں کو دشواری پیش آئے گی (اس لیے کہ میرے دادا نے رسول اللہ صلی اللہ علیہ وسلم کا بتایا ہوا نام ناپسند کیا تھا) ۔ ابوداؤد کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے عاص (گنہگار) عزیز (اللہ کا نام ہے)، عتلہ (سختی) شیطان، حکم (اللہ کی صفت ہے)، غراب(کوے کو کہتے ہیں اور اس کے معنی دوری اور غربت کے ہیں)، حباب (شیطان کا نام) اور شہاب (شیطان کو بھگانے والا ایک شعلہ ہے)کے نام بدل دیئے اور شہاب کا نام ہشام رکھ دیا، اور حرب (جنگ) کے بدلے سلم (امن) رکھا، مضطجع (لیٹنے والا) کے بدلے منبعث (اٹھنے والا) رکھا، اور جس زمین کا نام عفرۃ (بنجر اور غیر آباد) تھا، اس کا خضرہ (سرسبز و شاداب) رکھا، شعب الضلالۃ (گمراہی کی گھاٹی) کا نام شعب الہدی (ہدایت کی گھاٹی) رکھا، اور بنو زنیہ کا نام بنو رشدہ اور بنو مغویہ کا نام بنو رشدہ رکھ دیا۔ ابوداؤد کہتے ہیں: میں نے اختصار کی غرض سے ان سب کی سندیں چھوڑ دی ہیں۔\n§وضاحت\n۱؎ : حزن کے معنی سخت اور دشوار گزار زمین کے ہیں اور سہل کے معنی : نرم اور عمدہ زمین کے ہیں حزن کی ضد۔","صحیح",{"u2":"جناب سعید بن مسیب اپنے والد سے وہ دادا (حزن) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے پوچھا ” تمہارا کیا نام ہے؟ “ کہا: حزن۔ (بمعنی سخت اور دشوار گزار زمین) آپ صلی اللہ علیہ وسلم نے فرمایا ” تم ” سہل “ ہو۔ (بمعنی نرم اور آسان)۔ “ اس نے کہا: نہیں ” سہل “ کو تو روندا جاتا اور حقیر جانا جاتا ہے۔ سعید کہتے ہیں: مجھے یقین رہا کہ ہمیں ان کے بعد کوئی سختی اور غمی لاحق ہونے والی ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے عاص، عزیز، عتلہ، شیطان، حکم، غراب، حباب اور شہاب کے نام بدلے ہیں۔ اور شہاب کا نام ہشام رکھا۔ اور حرب کا سلم۔ مضطجع کا منبعث۔ ایک علاقے کا نام عفرہ سے بدل کر خضرہ کر دیا شعب الضلالۃ کا شعب الھدی، بنوالزانیہ کا بنوالرشدہ اور بنو مغویہ کا بنورشدہ کر دیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ میں نے ان کی سندیں اختصار کی وجہ سے چھوڑ دی ہیں۔","f2":"مذکورہ بالا ناموں کے معنی یہ ہیں: عاص نافرمانی کرنے والا، قبول نہ کرنے والا۔ عزیز عزت اور غلبے والا یہ اللہ عزوجل کا نام ہے۔ عتله سخت طبيعت۔ حکم عمدہ فیصلے کرنے والا۔ یہ اللہ عزوجل کا نام ہے۔ غراب کوے کو کہتے ہیں اور اس میں دوری اور فراق کے معنی بھی ہیں۔ کوا نجاستیں بھی کھاتا ہے۔ حباب شیطان کا نام ہے یا سانپ کا یا اس کی ایک قسم بھی ہے۔ شھاب آگ کے شعلے کو کہتے ہیں۔ حرب لڑائی یا بہت زیادہ لڑنے والا۔ سلم سلامتی اور صلح والا۔ مضطجع لیٹنے اور سونے والا۔ المُنبعث جاگنے اور اُٹھنے والا۔ عفرہ بنجر زمین۔ خَضِرہ سرسبز و شاداب زمین۔ شَعب الضلاله بھٹکا دینے والی گھاٹی۔ شَعب الھُدی سیدھی راہ والی گھاٹی۔ بنو الذنية بدکاروں کی اولاد۔ بنو الرُشدہ ہدایت یافتہ لوگوں کی اولاد۔ بنو مغویہ گمراہوں کی اولاد۔ امام بخاری رحمہ اللہ کی روایت میں ہے: حزن نے کہا: نہیں میرے باپ نے جو نام رکھ دیا ہے وہ میں نہیں بدلتا۔ ابنِ مسیب رحمہ اللہ کہتے ہیں چناچہ اس وجہ سے (کہ رسول اللہ صلی اللہ علیہ وسلم کی بات قبول نہیں کی گئی) ہم پر غمگینی کے اثرات نمایان رہے ہیں۔ وَ لاَ حولَ وَلاَ قُوَۃ اِالاَباللہ۔۔ دیکھئے: (صحیح بخاری الادب باب اسم الحزن حدیث: 6190)"}],[4957,"مسروق کہتے ہیں کہ میں عمر بن خطاب رضی اللہ عنہ سے ملا تو انہوں نے پوچھا: تم کون ہو؟ میں نے کہا: مسروق بن اجدع، تو آپ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"اجدع تو شیطان ہے\"۔","ضعیف",{"u2":"جناب مسروق سے روایت ہے، وہ کہتے ہیں کہ میں سیدنا عمر بن خطاب رضی اللہ عنہ سے ملا، تو انہوں نے پوچھا تم کون ہو؟ میں نے بتایا کہ مسروق بن اجدع۔ تو عمر نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ صلی اللہ علیہ وسلم فرماتے تھے ” اجدع، شیطان ہے۔ “"}],[4958,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے بچے یا اپنے غلام کا نام یسار، رباح، نجیح اور افلح ہرگز نہ رکھو، اس لیے کہ تم پوچھو گے: کیا وہاں ہے وہ؟ تو جواب دینے والا کہے گا: نہیں (تو تم اسے بدفالی سمجھ کر اچھا نہ سمجھو گے)(سمرہ نے کہا) یہ تو بس چار ہیں اور تم اس سے زیادہ مجھ سے نہ نقل کرنا۔","صحیح",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اپنے بچے یا غلام کا نام یسار ” مبارک، آسان “ رباح ” نفع آور “ نجیح ” کامیاب “ افلح ” کامیاب “ ہرگز نہ رکھنا۔ تم پوچھو گے کیا وہ یہاں ہے؟ تو جواب ملے گا نہیں۔ “ (مقصد یہ ہے کہ اس طرح بدفالی ہو گی) (سیدنا سمرہ رضی اللہ عنہ نے کہا) یہ بس چار نام ہیں، مذید میرے ذمے نہ لگا دینا۔"}],[4959,"سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ ہم افلح، یسار، نافع اور رباح ان چار ناموں میں سے کوئی اپنے غلاموں یا بچوں کا رکھیں۔","صحیح",{"u2":"سیدنا سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ ہم اپنے غلاموں کے نام یہ رکھیں۔ افلح، یسار، نافع اور رباح (نفع والا)۔"}],[4960,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اللہ نے چاہا اور میں زندہ رہا تو میں اپنی امت کو نافع، افلح اور برکت نام رکھنے سے منع کر دوں گا، (اعمش کہتے ہیں: مجھے نہیں معلوم انہوں (سفیان) نے نافع کا ذکر کیا یا نہیں) اس لیے کہ آدمی جب آئے گا تو پوچھے گا: کیا برکت ہے؟ تو لوگ کہیں گے: نہیں، (تو لوگ اسے بدفالی سمجھ کر اچھا نہ سمجھیں گے) ۔ ابوداؤد کہتے ہیں: ابوزبیر نے جابر سے انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی طرح روایت کی ہے البتہ اس میں \"برکت\" کا ذکر نہیں ہے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اگر اللہ نے چاہا میں زندہ رہا تو میں اپنی امت کو اس سے منع کروں گا کہ وہ ” نافع، افلح اور برکت “ نام رکھیں۔ “ اعمش کہتے ہیں: مجھے معلوم نہیں شیخ (ابوسفیان) نے نافع کا ذکر کیا یا نہیں۔ دراصل آدمی جب آتا ہے اور پوچھتا ہے ” کیا برکت ہے؟ “ تو جواب ملتا ہے نہیں۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: ابوزبیر نے بواسطہ سیدنا جابر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے اس حدیث کی مانند روایت کیا ہے مگر اس میں ” برکت “ کا ذکر نہیں کیا۔","f2":"مذکورہ بالا ناموں سے بالخصوس پرہیز کرنا چاہیئے۔ اور صحیح مسلم میں ہے کہ آپ صلی اللہ علیہ وسلم بعد میں اس سے خاموش ہو رہے۔ (صحیح مسلم الادب، باب کراھة التسمية بالااسماء و بنافع ع نحوه حديث 2138)۔"}],[4961,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سب سے ذلیل نام والا اللہ کے نزدیک قیامت کے دن وہ شخص ہو گا جسے لوگ شہنشاہ کہتے ہوں\"۔ ابوداؤد کہتے ہیں: شعیب بن ابی حمزہ نے اسے ابوالزناد سے، اسی سند سے روایت کیا ہے، اور اس میں انہوں نے «أخنع اسم» کے بجائے «أخنى اسم» کہا ہے، (جس کے معنی سب سے فحش اور قبیح نام کے ہیں) ۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” قیامت کے روز سب سے برا نام اس شخص کا ہو گا جس نے اپنا نام ” ملک الاملاک “ (شہنشاہ، مہاراج) رکھا۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: شعیب بن ابوحمزہ نے بواسطہ ابوزناد اس کی سند سے یہ روایت بیان کی تو اس میں «أخنع اسم» کی بجائے «أخنى اسم» (مبغوض ترین نام) کہا۔","f2":"علمائے کرام نے مندرجہ بالا ترکیب سے قاضی القضاۃ کہنے کہلانے کو بھی ناجائز کہا ہے۔"}],[4962,"ابوجبیرہ بن ضحاک کہتے ہیں کہ ہمارے یعنی بنو سلمہ کے سلسلے میں یہ آیت نازل ہوئی «ولا تنابزوا بالألقاب بئس الاسم الفسوق بعد الإيمان» \"ایک دوسرے کو برے ناموں سے نہ پکارو، ایمان کے بعد برے نام سے پکارنا برا ہے\" (الحجرات: ۱۱) ہمارے پاس رسول اللہ صلی اللہ علیہ وسلم آئے اور ہم میں کوئی شخص ایسا نہیں تھا جس کے دو یا تین نام نہ ہوں، تو آپ نے پکارنا شروع کیا:\" اے فلاں، تو لوگ کہتے: اللہ کے رسول! اس نام سے نہ پکاریئے، وہ اس نام سے چڑھتا ہے، تو یہ آیت نازل ہوئی «ولا تنابزوا بالألقاب» ۔","صحیح",{"u2":"جناب ابوجبیرہ بن ضحاک بیان کرتے ہیں کہ آیت کریمہ «ولا تنابزوا بالألقاب بئس الاسم الفسوق بعد الإيمان» ” برے برے ناموں اور لقبوں سے مت پکارو، ایمان لے آنے کے بعد فسق کا نام بہت برا ہے۔ “ یہ ہم، بنو سلمہ کے بارے میں نازل ہوئی تھی۔ انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم ہم میں تشریف لائے تو ہم میں کوئی ایسا نہ تھا کہ اس کے دو یا تین نام نہ ہوں۔ رسول اللہ صلی اللہ علیہ وسلم کسی کو بلاتے ” ارے فلاں! “ تو لوگ کہتے: اے اللہ کے رسول! رکیے۔ تحقیق یہ آدمی اس نام سے ناراض ہوتا ہے۔ چنانچہ آیت «ولا تنابزوا بالألقاب» اتری۔","f2":"معلوم ہوا ہے کہ برے برے لقب یا نام رکھنا حرام اور ناجائز ہے۔"}],[4963,"اسلم کہتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے اپنے ایک بیٹے کو مارا جس نے اپنی کنیت ابوعیسی رکھی تھی اور مغیرہ بن شعبہ رضی اللہ عنہ نے بھی ابوعیسی کنیت رکھی تھی، تو عمر رضی اللہ عنہ نے ان سے کہا: کیا تمہارے لیے یہ کافی نہیں کہ تم ابوعبداللہ کنیت اختیار کرو؟ ۱؎وہ بولے: میری یہ کنیت رسول اللہ صلی اللہ علیہ وسلم نے ہی رکھی ہے، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے تو اگلے پچھلے سب گناہ بخش دئیے گئے تھے، اور ہم تو اپنی ہی طرح کے چند لوگوں میں سے ایک ہیں ۲؎ چنانچہ وہ ہمیشہ ابوعبداللہ کی کنیت سے پکارے جاتے رہے، یہاں تک کہ انتقال فرما گئے۔\n§وضاحت\n۱؎ : عمر رضی اللہ عنہ نے ابوعیسی کنیت رکھنے سے اس وجہ سے منع کیا کہ اس بات کا خدشہ تھا کہ لوگ اس وہم میں نہ مبتلا ہو جائیں کہ عیسی علیہ السلام کا بھی کوئی باپ تھا ، یہی وجہ ہے کہ عمر رضی اللہ عنہ نے کہا کہ یہ کنیت رکھنا آپ صلی اللہ علیہ وسلم کی خصوصیات میں سے ہے۔ ۲؎ : مقصد یہ ہے کہ ہم لوگ عام مسلمان ہیں، اور یہ نہیں معلوم کہ ہمارا انجام کیا ہو گا۔","صحیح",{"u2":"جناب زید بن اسلم اپنے والد سے روایت کرتے ہیں کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے اپنے بیٹے کو، جس نے اپنی کنیت ” ابوعیسیٰ “ رکھ لی تھی، سزا دی سیدنا مغیرہ بن شعبہ رضی اللہ عنہ نے اپنی کنیت ابوعیسیٰ رکھی تو سیدنا عمر رضی اللہ عنہ نے ان سے کہا: کیا تمہیں یہ کافی نہیں کہ اپنی کنیت ” ابوعبداللہ “ رکھ لو۔ انہوں نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم ہی نے میری یہ کنیت رکھی تھی۔ تو سیدنا عمر رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے اگلے پچھلے تمام گناہ اللہ نے بخش دیے ہوئے ہیں اور ہم تو ایک دوسرے جیسے لوگ ہیں۔ (ہم میں کوئی بھی دوسرے سے افضل و اعلیٰ نہیں) چنانچہ سیدنا مغیرہ رضی اللہ عنہ اپنی وفات تک ابوعبداللہ ہی کہلاتے رہے۔","f2":"ابو عیسی ٰ کنیت رکھ لینا جائز ہے تاہم اس سے احتراز کرنا بہتر ہے۔ تاکہ حضرت عیسی علیہ السلام کا شرف لفظی طور پر بھی محفوط رہے اور کسی کو شُبہ نہ ہو کہ حضرت عیسیٰ علیہ السلام کے بھی باپ تھے۔"}],[4964,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اے میرے بیٹے!\"۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کو پکارا، تو فرمایا ” اے میرے بیٹے! “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: میں نے یحییٰ بن معین سے سنا، وہ محمد بن محبوب کی مدح کرتے تھے اور بتاتے تھے کہ یہ بہت زیادہ صاحب حدیث تھے۔","f2":"کسی اور کے بچے کو پیار سے بیٹے یا میرے بیٹے کہ کر پکارلینے میں کوئی حرج نہیں۔ سورۃ احزاب میں جو حکم ہے کہ انہیں انکے باپوں سے پُکارو۔ یہ لے پالک بچوں کے متعلق ہے کہ ان کے اصل نسب کی شہرت ختم نہ کرو۔ ورنہ پیار سے اور مجازََ اس طرح کہنا جائز ہے۔"}],[4965,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے نام پر نام رکھو لیکن میری کنیت نہ رکھو\"۔ ابوداؤد کہتے ہیں: اسے ابوصالح نے ابوہریرہ سے اسی طرح روایت کیا ہے، اور اسی طرح ابوسفیان، سالم بن ابی الجعد، سلیمان یشکری اور ابن منکدر وغیرہ کی روایتیں بھی ہیں جو جابر رضی اللہ عنہ سے مروی ہیں، اور انس بن مالک رضی اللہ عنہ کی روایت بھی اسی طرح ہے (یعنی اس میں بھی یہی ہے کہ میرے نام پر نام رکھو اور میری کنیت پر کنیت نہ رکھو) ۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میرا نام رکھ سکتے ہو مگر میری کنیت پر اپنی کنیت نہ رکھو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابوصالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے ایسے ہی روایت کیا ہے۔ نیز ابوسفیان، سالم بن ابوجعد، سلیمان یشکری اور ابن منکدر، سیدنا جابر رضی اللہ عنہ سے ایسے ہی روایت کرتے ہیں اور سیدنا انس بن مالک رضی اللہ عنہ سے بھی مروی ہے۔","f2":"رسول اللہ صلی اللہ علیہ وسلم کے حین حیات یہ کنیت اختیار کر نا جائز نہیں تھا مگر آپ کے بعد علماء نے اجازت دے دی ہے کہ آپ صلی اللہ علیہ وسلم کانام اور رکنیت دونوں رکھے جاسکتے ہیں۔ زندگی میں ممانعت کی وجہ یہ واقعہ تھا کہ ایک مرتبہ نبی صلی اللہ علیہ وسلم بازار میں تھے کہ ایک شخص نے ابولقاسم کہہ کر آواز دی آپ نے پیچھت مڑکر دیکھا تو آواز دینے والے نے کہا کہ میں نے آپ کو آواز نہیں دی میں نے تو فلاں شخص کو آواز دی ہے۔ اس واقعے کے بعد آپ نے یہ رکنیت رکھنے سے روک دیا۔ (فتح الباری الاداب حدیث٦١٨٨ مزید تفصیل کے لیے فتح الباری ملاخطہ ہو) جواز کے دلائل اگلےابواب میں آرہے ہیں۔"}],[4966,"جابر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو میرا نام رکھے، وہ میری کنیت نہ رکھے، اور جو میری کنیت رکھے، وہ میرا نام نہ رکھے\"۔ ابوداؤد کہتے ہیں: اسی مفہوم کی حدیث ابن عجلان نے اپنے والد سے، اور انہوں نے ابوہریرہ رضی اللہ عنہ سے روایت کی ہے، اور ابوزرعہ کی روایت ابوہریرہ رضی اللہ عنہ سے ان دونوں روایتوں سے مختلف روایت کی گئی ہے، اور اسی طرح عبدالرحمٰن بن ابی عمرہ کی روایت جسے انہوں نے ابوہریرہ رضی اللہ عنہ سے روایت کیا ہے اس میں بھی کچھ اختلاف ہے، اسے ثوری اور ابن جریج نے ابو الزبیر کی طرح روایت کیا ہے، اور اسے معقل بن عبیداللہ نے ابن سیرین کی طرح روایت کیا ہے، اور جسے موسی بن یسار نے ابوہریرہ رضی اللہ عنہ سے روایت کیا ہے اس میں بھی اختلاف کیا گیا ہے، حماد بن خالد اور ابن ابی فدیک کے دو مختلف قول ہیں ۱؎۔\n§وضاحت\n۱؎ : خلاصہ یہ ہے کہ یہ حدیث ابوہریرہ رضی اللہ عنہ سے دونوں لفظوں کے ساتھ آئی ہے: اس طرح بھی جیسے محمد بن سیرین نے ابوہریرہ سے روایت کی ہے، جو یہ ہے «تسموا باسمي ولا تكتنوا بكنيتي» \" میرے نام پر نام رکھو اور میری کنیت پر کنیت نہ رکھو \" اور اس طرح بھی جیسے ابوالزبیر نے جابر رضی اللہ عنہ سے روایت کی ہے، دونوں روایتوں میں فرق یہ ہے کہ بطریق ابوالزبیر عن جابر میں نبی اکرم صلی اللہ علیہ وسلم کا نام اور کنیت الگ الگ رکھنے کا جواز ثابت ہو رہا ہے ، اور بطریق ابن سیرین ابوہریرہ کی روایت سے نام رکھنے کا جواز اور کنیت رکھنے کا عدم جواز ثابت ہو رہا ہے ، صحیح بخاری کی حدیث بطریق سالم بن ابی الجعد عن جابر رضی اللہ عنہ : ابن سیرین کی ابوہریرہ سے حدیث کی طرح ہے۔","منکر",{"u2":"جناب ابوزبیر، سیدنا جابر رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شخص میرا نام رکھے وہ میری کنیت اختیار نہ کرے۔ اور جس نے میری کنیت رکھی ہو وہ میرا نام نہ رکھے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن عجلان نے بواسطہ اپنے والد سیدنا ابوہریرہ رضی اللہ عنہ سے اسی روایت (روایت جابر) کے ہم معنی روایت کیا ہے۔ (نام یا کنیت میں سے ایک چیز جائز ہے۔ دونوں کو جمع کرنا جائز نہیں۔) اور ابوزرعہ سے بواسطہ سیدنا ابوہریرہ رضی اللہ عنہ دونوں روایتیں مروی ہیں (جمع کرنا درست نہیں، اور گزشتہ روایت کی مانند بھی کہ صرف کنیت جائز نہیں)۔ عبدالرحمٰن بن ابو عمرہ کی روایت جو سیدنا ابوہریرہ رضی اللہ عنہ سے ہے اس میں بھی اختلاف ہے۔ ثوری اور ابن جریج نے ابوزبیر کی مانند روایت کیا (جمع کرنا درست نہیں)۔ اور معقل بن عبیداللہ نے ابن سیرین کی طرح کہا (نام رکھنا جائز، مگر کنیت جائز نہیں)۔ موسیٰ بن یسار کی روایت بواسطہ سیدنا ابوہریرہ رضی اللہ عنہ میں بھی دونوں قول ہیں۔ اس میں حماد بن خالد اور ابن ابوفدیک نے اختلاف کیا ہے۔"}],[4967,"محمد بن حنفیہ کہتے ہیں کہ علی رضی اللہ عنہ نے کہا: میں نے عرض کیا: اللہ کے رسول! اگر آپ کے بعد میرے بیٹا پیدا ہو تو میں اس کا نام اور اس کی کنیت آپ کے نام اور آپ کی کنیت پر رکھوں؟ آپ نے فرمایا: \"ہاں\"۔","صحیح",{"u2":"جناب محمد ابن حنفیہ رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا علی رضی اللہ عنہ نے بتایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اے اللہ کے رسول! اگر آپ کے بعد میرے ہاں بچہ پیدا ہو، تو کیا میں اس کا نام اور کنیت آپ کے نام اور کنیت پر رکھ سکتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہاں۔ “ (راوی حدیث) ابوبکر بن ابوشیبہ کے الفاظ میں «قلت» کا لفظ نہیں ہے بلکہ یوں ہے کہ «قال علي عليه السلام للنبي صلى الله عليه وسلم» ” سیدنا علی نے نبی کریم صلی اللہ علیہ وسلم سے پوچھا۔ “","f2":"اس واقعےسے نام اورکنیت دونوں کے رکھنے کاجواز معلوم ہوتا ہے۔ واللہ اعلم"}],[4968,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور کہنے لگی: اللہ کے رسول! میرے ایک لڑکا پیدا ہوا ہے، میں نے اس کا نام محمد اور اس کی کنیت ابوالقاسم رکھ دی ہے، تو مجھے بتایا گیا کہ آپ اسے ناپسند کرتے ہیں، آپ نے فرمایا: \"کیا سبب ہے کہ میرا نام رکھنا درست ہے اور کنیت رکھنا نا درست یا یوں فرمایا: کیا سبب ہے کہ میری کنیت رکھنا نا درست ہے اور نام رکھنا درست؟ ۱؎\"۔\n§وضاحت\n۱؎ : اس سلسلہ میں علماء کا اختلاف ہے، بعض لوگوں نے کہا کہ ممانعت کا تعلق آپ صلی اللہ علیہ وسلم کی حیات مبارکہ تک ہے، اس کے بعد اگر کوئی آپ کا نام مع کنیت رکھتا ہے تو کچھ قباحت نہیں، بعض نے کہا کہ نام اور کنیت ایک ساتھ رکھنا منع ہے، کچھ کا کہنا ہے کہ ممانعت کا تعلق صرف کنیت سے ہے۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ ایک عورت نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آئی اور کہنے لگی: اے اللہ کے رسول! میرے ہاں بچہ پیدا ہوا ہے اور میں نے اس کا نام محمد اور کنیت ابوالقاسم رکھی ہے اور مجھے بتایا گیا ہے کہ آپ اسے ناپسند فرماتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا وجہ ہے کہ میرا نام تو جائز ہو اور کنیت حرام۔ “ یا فرمایا ” کس چیز نے میری کنیت حرام ٹھہرا دی اور نام جائز کر دیا؟ “"}],[4969,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے ہاں آتے تھے، اور میرا ایک چھوٹا بھائی تھا جس کی کنیت ابوعمیر تھی، اس کے پاس ایک چڑیا تھی، وہ اس سے کھیلتا تھا، وہ مر گئی، پھر ایک دن اچانک نبی اکرم صلی اللہ علیہ وسلم اس کے پاس آئے تو اسے رنجیدہ و غمگین دیکھ کر فرمایا: \"کیا بات ہے؟\" لوگوں نے عرض کیا: اس کی چڑیا مر گئی، تو آپ نے فرمایا: \"اے ابوعمیر! کیا ہوا نغیر (چڑیا) کو؟\"۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے ہاں تشریف لایا کرتے تھے اور میرے چھوٹے بھائی نے جس کی کنیت ” ابوعمیر “ تھی، اس نے ایک چڑیا رکھی ہوئی تھی جس سے وہ کھیلا کرتا تھا۔ (اس چڑیا کو عربی میں «نغير» کہتے تھے) تو وہ مر گئی۔ ایک دن نبی کریم صلی اللہ علیہ وسلم اس کے پاس گئے اور اسے غمگین پایا تو پوچھا ” اسے کیا ہوا ہے؟ “ ہم نے بتایا کہ اس کی چڑیا «نغير» مر گئی ہے۔ تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا ” اے ابوعمیر! کیا کر گیا (تیرا) «نغير»؟ “","f2":"محدثین نے اس حدیث سے استنباط کیا ہے کہ مسبحع مقفی کلام جائز ہےاور جائز حدود میں منسی مزاح کی بات میں کو ئی حرج نہیں۔ اور بچوں کے ساتھ ملاطفت حسن اخلاق کا حصہ ہے۔ چھوٹی عمر میں کنیت رکھنا جائز ہے اور جانور پال لینا اس کو پنجرے میں رکھنا اور ان سے کھیلنا بھی مباح ہے۔(امام خطابی رحمۃاللہ)"}],[4970,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے عرض کیا: اللہ کے رسول! میری تمام سہیلیوں کی کنیتیں ہیں، آپ نے فرمایا: \"تو تم اپنے بیٹے یعنی اپنے بھانجے عبداللہ کے ساتھ کنیت رکھ لو\" مسدد کی روایت میں (عبداللہ کے بجائے) عبداللہ بن زبیر ہے، عروہ کہتے ہیں: چنانچہ ان کی کنیت ام عبداللہ تھی۔ ابوداؤد کہتے ہیں: قران بن تمام اور معمر دونوں نے ہشام سے اسی طرح روایت کی ہے، اور ابواسامہ نے ہشام سے اور ہشام نے عباد بن حمزہ سے اسے روایت کیا ہے، اور اسی طرح اسے حماد بن سلمہ اور مسلمہ بن قعنب نے ہشام سے روایت کیا ہے جیسا کہ ابواسامہ نے کہا ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کہتی ہیں کہ میں نے کہا: اے اللہ کے رسول! میری سب سہیلیوں کی کنیتیں ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تو تم اپنے بیٹے عبداللہ کے نام سے کنیت رکھ لو۔ “ مقصد تھا کہ اپنے بھانجے کی نسبت سے۔ مسدد نے وضاحت کی کہ اس سے مراد ” عبداللہ بن زبیر “ ہیں۔ چنانچہ انہوں نے ام عبداللہ کنیت اختیار کر لی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ قران بن تمام اور معمر دونوں نے ہشام سے اسی کے مانند روایت کیا ہے اور ابواسامہ نے ہشام سے، اس نے عباد بن حمزہ سے روایت کیا ہے۔ اور ایسے ہی حماد بن سلمہ اور مسلمہ بن قعنب نے ہشام سے اسی طرح روایت کیا جیسے ابواسامہ نے کہا۔","f2":"عورتوں کے لیےبھی جائز ہےکہ کنیت اختیار کرلیں خواہ اولاد ہویانہ"}],[4971,"سفیان بن اسید حضرمی رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: یہ بہت بڑی خیانت ہے کہ تم اپنے بھائی سے ایسی بات بیان کرو جسے وہ تو سچ جانے اور تم خود اس سے جھوٹ کہو۔\n§وضاحت\n۱؎ : تعریض یا توریہ ایسے لفظ کے اطلاق کا نام ہے جس کا ایک ظاہری معنی ہوا، اور متکلم اس ظاہری معنی کے خلاف ایک دوسرا معنی مراد لے رہا ہو جس کا وہ لفظ محتمل ہو، یہ ایک طرح سے مخاطب کو دھوکہ میں ڈالنا ہے اسی وجہ سے جب تک کوئی شرعی مصلحت یا کوئی ایسی حاجت نہ ہو کہ اس کے بغیر کوئی اور چارہ کار نہ ہو ایسا کرنا صحیح نہیں۔","ضعیف",{"u2":"سیدنا سفیان بن اسید حضرمی رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” بہت بڑی خیانت ہے کہ تو اپنے بھائی سے کوئی بات کرے، وہ تمہیں سچا سمجھ رہا ہو، جبکہ تم اس سے جھوٹ بول رہے ہو۔“","f2":"یہ روایت ضعیف ہے لیکن دیگر صحیح احادیث سے معلوم ہوتا ہے کہ مسلمان بھائی کو دھوکا دینا بہت بڑا قبیح گناہ ہے۔ صحیح مسلم میں ہے(اليمين علی نية المستحلف)۔ قسم میں وہی معنی معتبر ہوں گے جو قسم اٹھوانے والے نے مراد لیے ہوں (نہ کہ قسم اٹھانے والے کے۔)"}],[4972,"ابومسعود رضی اللہ عنہ نے ابوعبداللہ (حذیفہ) رضی اللہ عنہ سے یا ابوعبداللہ نے ابومسعود سے کہا تم نے «زعموا» کے سلسلے میں رسول اللہ صلی اللہ علیہ وسلم کو کیا فرماتے سنا؟ وہ بولے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: «زعموا» (لوگوں نے گمان کیا)آدمی کی بہت بری سواری ہے ۱؎۔\n§وضاحت\n۱؎ : چونکہ «زعموا» کا تعلق ایسے قول اور ایسی بات سے ہے جو غیر یقینی ہے، حقیقت سے اس کا کوئی تعلق نہیں اس لئے آپ صلی اللہ علیہ وسلم نے اس لفظ و اپنے مقصد کے لئے سواری بنانے اور اس کی آڑ لے کر کوئی ایسی بات کہنے سے منع کیا ہے جو غیر محقق ہو اور جو پایہ ثبوت کو نہ پہنچتی ہو۔","صحیح",{"u2":"جناب ابوقلابہ سے روایت ہے کہ سیدنا ابومسعود رضی اللہ عنہ نے ابوعبداللہ (سیدنا حذیفہ رضی اللہ عنہ) سے یا ابوعبداللہ (حذیفہ رضی اللہ عنہ) نے سیدنا ابومسعود رضی اللہ عنہ سے پوچھا کہ آپ نے اس بارے میں کیا سنا ہے جو لوگ «زعموا» کے انداز میں بات کرتے ہیں؟ (لوگوں کا خیال ہے۔ باور کیا جاتا ہے۔ کہا جاتا ہے وغیرہ)۔ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے «زعموا» آدمی کی بہت بری سواری ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: ابوعبداللہ سے مراد سیدنا حزیفہ رضی اللہ عنہ ہیں۔","f2":"لوگوں سے سنی سنائی بے اصل باتوں کو بلا تحقیق وتفتیش آگےنقل کر نا بہت براہے۔ کئی لوگ اپنے وہم شبہے یا جھوٹ کو لاگ لپیٹ سے آگے بڑھانے میں بڑے شاطرہوتے ہیں بالخصوص موجودہ لادینی صحافت کاتویہ طرہ امتیاز ہے۔"}],[4973,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے انہیں خطبہ دیا تو «أما بعد» کہا ۱؎۔\n§وضاحت\n۱؎ : «أما بعد» کا کلمہ حمد و صلاۃ کے بعد کہا جاتا ہے، آپ صلی اللہ علیہ وسلم اس کلمہ کا استعمال کرتے تھے ، اس سے متعلق روایت تقریباً بارہ صحابہ سے مروی ہے۔","صحیح",{"u2":"سیدنا زید بن ارقم رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا اور فرمایا ” «أ بعد»! حمد و صلاۃ کے بعد۔ “","f2":"خطبے میں حمدوصلاۃ کےبعداپناموضوع شروع کرنے سے پہلےیہ کلمہ بولنا شروع ہے۔"}],[4974,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی (انگور اور اس کے باغ کو) «كرم» نہ کہے ۱؎، اس لیے کہ «كرم» مسلمان مرد کو کہتے ہیں ۲؎، بلکہ اسے انگور کے باغ کہو۔\n§وضاحت\n۱؎ : چونکہ «كرم» یعنی انگور سے جو شراب بنائی جاتی ہے اسے لوگ عمدہ اور بہتر سمجھتے ہیں اس لیے انگور کا نام «كرم» رکھنے سے آپ صلی اللہ علیہ وسلم نے منع فرما دیا تاکہ کبھی بھی شراب کی بہتری خیال میں نہ آئے۔ ۲؎ : عرب «رَجُلٌ کَرْمٌ» اور «قَوْمٌ کَرْمٌ»کہتے ہیں «رَجُلٌ کَرِیْمٌ» اور «قَوْمٌ کِرَامٌ» کے معنی میں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی شخص (انگور کے لیے) لفظ ” کرم “ استعمال نہ کرے۔ بیشک ” کرم “ (سخاوت کا منطوق) مسلمان آدمی ہے۔ بلکہ یوں کہا کرو «حدائق الأعناب» ” انگوروں کے باغات۔ “","f2":"شرعی اوردینی غیرت کا تقاضاہے کہ غلط الفاظ مسلمان کی زبان پر جاری نہیں ہونے چاہییں بالخصوص جب رسول اللہ صلی اللہ علیہ وسلم نے ان تفریح فرمادی ہو جیسے درج ذیل باب میں بھی وارد ہے۔"}],[4975,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی (اپنے غلام یا لونڈی کو) «عبدي» (میرا بندہ)اور «أمتي» (میری بندی) نہ کہے اور نہ کوئی غلام یا لونڈی (اپنے آقا کو) «ربي» (میرے مالک) اور «ربتي» (میری مالکن) کہے بلکہ مالک یوں کہے: میرے جوان! یا میری جوان! اور غلام اور لونڈی یوں کہیں: «سيدي» (میرے آقا) اور «سيدتي» (میری مالکن) اس لیے کہ تم سب مملوک ہو اور رب صرف اللہ ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہرسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی شخص اپنے غلام اور لونڈی کو «عبدي» میرے بندے “ یا «أمتي» ” میری بندی “ کے لفظ سے ہرگز نہ پکارے۔ اور نہ کوئی غلام اپنے مالک کو «ربي» اور «ربتي» ” میرے رب “ کہے۔ مالک کو چاہیئے کہ یوں پکارے «فتاى» اے میرے جوان “ «فتاتي» ” اے میری لڑکی “ اور مملوک کو چاہیئے کہ کہے «سيدي، سيدتي» ” اے میرے سردار! “ بلاشبہ تم سب مملوک ہو اور ” رب “ اللہ عزوجل ہی ہے۔ “"}],[4976,"اس سند سے بھی ابوہریرہ رضی اللہ عنہ سے یہی حدیث مروی ہے لیکن اس میں انہوں نے نبی اکرم صلی اللہ علیہ وسلم کا ذکر نہیں کیا ہے اور اس میں یہ ہے فرمایا: اور چاہیئے کہ وہ «سيدي» (میرے آقا) اور «مولاى» (میرے مولی) کہے۔","صحیح",{"u2":"ابویونس (سلیمان بن جبیر) نے سیدنا ابوہریرہ رضی اللہ عنہ سے بیان کیا اور اس روایت میں نبی کریم صلی اللہ علیہ وسلم کا ذکر نہیں کیا۔ (موقوف روایت بیان کی اور «سيدي وسيدتي» کی بجائے کہا) اور چاہیئے کہ «سيدي» اور «مولاى» ” اے میرے سردار! “ کہے۔"}],[4977,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ منافق کو سید نہ کہو اس لیے کہ اگر وہ سید ہے (یعنی قوم کا سردار ہے یا غلام و لونڈی اور مال والا ہے) تو تم نے اپنے رب کو ناراض کیا ۱؎۔\n§وضاحت\n۱؎ : کیونکہ تم نے اسے سید کہہ کر اس کی تعظیم کی حالانکہ وہ تعظیم کا مستحق نہیں اور اگر وہ ان معانی میں سے کسی بھی اعتبار سے سید نہیں ہے تو تمہارا اسے سید کہنا کذب و نفاق ہو گا۔","صحیح",{"u2":"جناب عبداللہ بن بریدہ اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کسی منافق کو ” سید “ (سردار، آقا) کہہ کر مت پکارو۔ اس لیے کہ اگر وہ سردار ہوا تو تم نے اپنے رب عزوجل کو ناراض کر دیا۔ “","f2":"ارشاد باری تعالیٰ ہے: (وللہ العذةولرسوله وللمومنين)(المنا فقون:٨) عزت تو صرف اللہ کے لئے اس رسول صلی اللہ علیہ وسلم کے لیےاور مومنین کے لیے ہے۔ کسی منافق کی اس طرح سےعزت کرنا جائز نہیں۔"}],[4978,"سہل بن حنیف رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی میرا نفس خبیث ہو گیا نہ کہے، بلکہ یوں کہے میرا جی پریشان ہو گیا\"۔","صحیح",{"u2":"سیدنا ابوامامہ اپنے والد (سہل بن حنیف رضی اللہ عنہ) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی شخص ہرگز یوں نہ کہے ” میرا نفس خبیث ہو گیا ہے۔ “ اگر کہنا بھی ہو تو یوں کہے ” میری طبیعت پریشان ہے۔ طبیعت خراب ہے۔ “","f2":"چونکہ لفظ خبث اور خبیث کا اطلاق باطل اعتقادکفر (جھوٹ) اور حرام کاموں پر بھی ہوتا ہے۔ اس لیے ہدایت فرمائی گئی کہ مسلمان کی زبان نامناسب الفاظ سے پاک رہے۔"}],[4979,"ام المؤمنین عائشہ رضی اللہ عنہا نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی یہ نہ کہے: میرے دل نے جوش مارا\" بلکہ یوں کہے: میرا جی پریشان ہو گیا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی شخص ہرگز یوں نہ کہے میرا جی جوش مارتا ہے۔ بلکہ یوں کہے: میرا جی پریشان ہے۔ “","f2":"اسلام نےاپنے ماننے والوں کے عقائدو اعمال میں پاکیزگی پیدا کرنے کے ساتھ ان کی زبان وبیان کے اسلوب و محاورات کو بھی پاکیزہ بنایاہے۔ ارشاد الہی ہے: (بئس الاسم الفسوق بعد الايمان)(الحجرات: ١١) ايمان لے آنے کے بعدفسق کا نام بہت برا ہے۔"}],[4980,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم یوں نہ کہو: جو اللہ چاہے اور فلاں چاہے ۱؎\" بلکہ یوں کہو: جو اللہ چاہے پھر فلاں چاہے۔\n§وضاحت\n۱؎ : کیونکہ اس جملہ میں اللہ کی مشیت کے ساتھ دوسرے کی مشیت شامل ہے جب کہ \" اللہ چاہے پھر فلاں چاہے \" میں ایسی بات نہیں ہے، کیونکہ اللہ کے چاہنے کے بعد پھر دوسرے کے چاہنے میں کوئی قباحت نہیں۔","صحیح",{"u2":"سیدنا حذیفہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” یوں مت کہو: جو ا اللہ چاہے اور فلاں چاہے ‘ بلکہ یوں کہو: جو ا اللہ چاہے پھر فلاں چاہے۔ “","f2":"پہلےجملےمیں اللہ کی مثیت (چاہنے) میں اوروں کو بھی شریک کرنا ہے۔ جو ناجائز اور حرام ہے بلکہوہی ہوتا ہے جو صرف اور صرف اللہ تعالیٰ چاہے، البتہ دوسرے جملے میں فرق کے ساتھ دوسروں کی مثیت کا اظہار کردے، تو جائز ہے۔"}],[4981,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ ایک خطیب نے نبی اکرم صلی اللہ علیہ وسلم کے پاس خطبہ دیا، تو اس نے (خطبہ میں) کہا:«من يطع الله ورسوله فقد رشد ومن يعصهما» جو اللہ اور اس کے رسول کی اطاعت کرتا ہے، وہ راہ راست پر ہے اور جو ان دونوں کی نافرمانی کرتا ہے ... (ابھی اس نے اتنا ہی کہا تھا کہ) آپ نے فرمایا: \"کھڑے ہو جاؤ\" یا یوں فرمایا: چلے جاؤ تم بہت برے خطیب ہو۱؎۔\n§وضاحت\n۱؎ : علماء کا کہنا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اس خطیب کو اس لئے برا کہا کہ اس نے «من يعصهما» کہہ کر اللہ اور رسول دونوں کو ایک ہی ضمیر میں جمع کر دیا تھا، خطبہ میں باتوں کو تفصیل سے کہنے کا موقع ہوتا ہے، اور سامعین میں ہر سطح کے لوگ ہوتے ہیں، مقام کا تقاضا تفصیل کا تھا یعنی : «من یعص اللہ ویعص رسولہ» کہنے کا ، تاکہ کسی طرح کا التباس نہ رہ جاتا۔","صحیح",{"u2":"سیدنا عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ ایک خطیب نے نبی کریم صلی اللہ علیہ وسلم کے سامنے خطبہ دیا تو اس نے کہا «من يطع الله ورسوله فقد رشد ومن يعصهما» ” جس نے ا اللہ اور اس کے رسول کی اطاعت کی بلاشبہ وہ ہدایت یافتہ ہوا اور جس نے ان دونوں کی نافرمانی کی۔ “ آپ صلی اللہ علیہ وسلم نے فرمایا ” چل کھڑا ہو۔ “ یا فرمایا ” چلا جا ‘ تو بہت برا خطیب ہے۔ “","f2":"اللہ اور اس کے رسول اللہ صلی اللہ علیہ وسلم کو ایک ہی کلمہ اور ضمیر تثنیہ میں جمع کرتے ہوئے یوں کہنا: (ومن يعصهما) جس نے ان دونوں کی نافرمانی کی۔ خلاف ادب شمار کیاگیا ہے۔ ان کو جدا جدا کر کے(ورسوله) کہنا چاہئے۔"}],[4982,"ابوالملیح ایک شخص سے روایت کرتے ہیں کہ اس نے کہا: میں نبی اکرم صلی اللہ علیہ وسلم کے پیچھے سوار تھا، کہ آپ کی سواری پھسل گئی، میں نے کہا: شیطان مرے، تو آپ نے فرمایا: \"یوں نہ کہو کہ \"شیطان مرے\" اس لیے کہ جب تم ایسا کہو گے تو وہ پھول کر گھر کے برابر ہو جائے گا، اور کہے گا: میرے زور و قوت کا اس نے اعتراف کر لیا، بلکہ یوں کہو: اللہ کے نام سے اس لیے کہ جب تم یہ کہو گے تو وہ پچک کر اتنا چھوٹا ہو جائے گا جیسے مکھی۔","صحیح",{"u2":"جناب ابوملیح ایک شخص سے روایت کرتے ہیں، اس نے کہا کہ میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ سواری پر ان پیچھے بیٹھا ہوا تھا کہ آپ صلی اللہ علیہ وسلم کی سواری کو ٹھوکر سی لگی تو میری زبان سے نکلا ” ہلاک ہو شیطان۔ “ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ مت کہو ‘ تم جب یہ کہتے ہو تو وہ پھول جاتا ہے یہاں تک کہ ایک گھر کے برابر ہو جاتا ہے اور وہ سمجھتا ہے کہ میری قوت سے ایسے ہوا لیکن کہو «بسم الله» ” اللہ کے نام سے “ تم جب ایسے کہتے ہو تو وہ سکڑ جاتا ہے ‘ حتیٰ کہ مکھی کی مانند ہو جاتا ہے۔ “","f2":"الله كے نام میں بڑی برکت ہے۔ اس سے شیطان ذلیل ورسوا ہوتا ہے، لہذا بندے کو ہرموقع پر مسنون اذکار پڑھنے کا حریص ہونا چاہیے۔"}],[4983,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم سنو! (اور موسی کی روایت میں یوں ہے، کہ جب آدمی کہے) کہ لوگ ہلاک ہو گئے تو وہی ان میں سب سے زیادہ ہلاک ہونے والا ہے ۱؎\"۔ ابوداؤد کہتے ہیں: مالک نے کہا: جب وہ یہ بات دینی معاملات میں لوگوں کی روش دیکھ کر رنج سے کہے تو میں اس میں کوئی مضائقہ نہیں سمجھتا، اور جب یہ بات وہ خود پر ناز کر کے اور لوگوں کو حقیر سمجھ کر کہے تو یہی وہ مکروہ و ناپسندیدہ چیز ہے، جس سے روکا گیا ہے۔\n§وضاحت\n۱؎ : مفہوم یہ ہے کہ جب کوئی شخص لوگوں کی عیب جوئی اور برائیاں برابر بیان کرتا رہے، اور اپنی زبان سے لوگوں کے فساد میں مبتلا ہونے اور ان کی ہلاکت و تباہی کا ذکر کرتا رہے گا تو ایسا شخص بسبب اس گناہ کے جو اسے اپنے اس کرتوت کی وجہ سے لاحق ہو رہا ہے سب سے زیادہ ہلاکت و بربادی کا مستحق ہے، اور بسا اوقات وہ خود پسندی کا بھی شکار ہو سکتا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم سنو، اور بالفاظ موسیٰ (موسیٰ بن اسماعیل) جب کہے۔ بندہ کہ لوگ تباہ ہو گئے۔ تو کہنے والا ہی سب سے زیادہ تباہ حال ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ امام مالک رضی اللہ عنہ نے کہا: جب کوئی لوگوں کو دینی حالت میں کمی اور خرابی کی وجہ سے ایسے کہے تو میں اس میں کوئی حرج نہیں سمجھتا۔ لیکن جب کوئی اپنے آپ کو بڑا اور لوگوں کو حقیر سمجھتے ہوئے ایسے کہے تو ناجائز ہے اور اسی کی ممانعت ہے۔","f2":"بلاشبہ کوئی بندہ اپنے طور پر کتناہی صالح کیوں نہ ہو لیکن اگر شیطانی بھرے میں آکر عجب وتکبر کے پھندے میں پھنس گیا تو وہی سب سے زیادہ ہلاکت میں پڑنے والاہے جیسے گزشتہ حدیث4901 میں گزرا ہے لہذا بڑے اور برے بول بولنے سے ہمیشہ بچنا چاہیے۔"}],[4984,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم پر «أعراب» (دیہاتی لوگ) تمہاری نماز کے نام کے سلسلے میں ہرگز غالب نہ آ جائیں، سنو! اس کا نام عشاء ہے ۱؎ اور وہ لوگ تو اونٹنیوں کے دودھ دوہنے کے لیے تاخیر اور اندھیرا کرتے ہیں۲؎\"۔\n§وضاحت\n۱؎ : کیونکہ اللہ تعالی نے اپنی کتاب میں اسے اپنے قول «ومن بعد صلاة العشاء» میں عشاء سے تعبیر کیا ہے اس لئے اس کا ترک مناسب نہیں۔ ۲؎ : اور اس نماز کو مؤخر کرتے ہیں اسی وجہ سے اسے «صلاة العتمة» کہتے ہیں۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہرگز ایسا نہ ہو کہ یہ بدوی لوگ تمہاری نماز کے نام پر غالب آ جائیں۔ خبردار! بلاشبہ اس کا نام ” عشاء “ ہے۔ لیکن چونکہ وہ لوگ اونٹنیوں کا دودھ دوہنے میں اندھیرا کر دیتے ہیں (تو اسی مناسبت سے اسے عتمہ ‘ یعنی اندھیرے والی نماز کہہ دیتے ہیں)۔ “","f2":"ہمارے ہاں دیہاتوں میں بعض لوگ عشاء کی نماز کو سوتےکی نماز ظہر کو پیشی یا پییش (پہلی) اور عصر کو دیگر(دوسری) کہتے ہیں۔ لیکن اس فرمان کا مطلب یہ ہےکہ ایمانیات سے متعلق شرعی اصطلاحات غالب اور زبان زد عام ہونی چاہییں عرف سے مغلوب نہ ہونے پائیں۔"}],[4985,"سالم بن ابی الجعد کہتے ہیں کہ ایک شخص نے کہا: کاش میں نماز پڑھ لیتا تو مجھے سکون مل جاتا، مسعر کہتے ہیں: میرا خیال ہے یہ بنو خزاعہ کا کوئی آدمی تھا، تو لوگوں نے اس پر نکیر کی کہ یہ نماز کو تکلیف کی چیز سمجھتا ہے تو اس نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا ہے، آپ فرما رہے تھے: \"اے بلال نماز کے لیے اقامت کہو اور ہمیں اس سے آرام و سکون پہنچاؤ\"۔","صحیح",{"u2":"جناب سالم بن ابو جعد سے روایت ہے کہ ایک آدمی نے کہا: مسعر کا خیال ہے کہ وہ قبیلہ خزاعہ سے تھا۔ کاش میں نماز پڑھ لیتا تو سکون پاتا۔ تو دوسرے لوگوں نے گویا اس کے اس انداز پر عیب لگایا۔ تو اس نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے ‘ آپ صلی اللہ علیہ وسلم فرماتے تھے ” بلال! نماز کی اقامت کہو، ہمیں اس سے راحت پہنچاؤ۔ “"}],[4986,"عبداللہ بن محمد بن حنفیہ کہتے ہیں میں اور میرے والد انصار میں سے اپنے ایک سسرالی رشتہ دار کے پاس اس کی (عیادت) بیمار پرسی کرنے کے لیے گئے، تو نماز کا وقت ہو گیا، تو اس نے اپنے گھر کی کسی لڑکی سے کہا: اے لڑکی! میرے لیے وضو کا پانی لے آتا کہ میں نماز پڑھ کر راحت پا لوں تو اس پر ہم نے ان کی نکیر کی، تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے\"اے بلال اٹھو اور ہمیں نماز سے آرام پہنچاؤ\"۔","صحیح",{"u2":"جناب عبداللہ بن محمد ابن حنفیہ رضی اللہ عنہ بیان کرتے ہیں کہ میں اور میرے والد انصاریوں میں ہمارے سسرالیوں کے ہاں عیادت کے لیے گئے تو نماز کا وقت ہو گیا۔ تو اس نے اپنے گھر والوں میں سے کسی کو کہا: اے لڑکی! وضو کے لیے پانی لاؤ ‘ شاید میں نماز پڑھ لوں تو راحت پاؤں۔ تو ہم نے ان کا یہ جملہ پسند نہ کیا۔ تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا ہے ‘ آپ صلی اللہ علیہ وسلم فرماتے تھے ” اے بلال! اٹھو ہمیں نماز کے ساتھ راحت پہنچاؤ۔ “"}],[4987,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دین کے علاوہ کسی اور معاملے کی طرف کسی کی نسبت کرتے نہیں دیکھا ۱؎۔\n§وضاحت\n۱؎ : امام منذری کہتے ہیں کہ شاید ابوداود نے اس باب میں اس حدیث کو اس لیے داخل کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم لوگوں کو صرف دین کی طرف منسوب کرتے تھے، تا کہ اس حدیث کے ذریعہ سے لوگوں کو اس بات کی طرف رہنمائی کریں کہ کتاب وسنت میں وارد الفاظ کا استعمال کرنا چاہئے ، اور لوگوں کو جاہلی الفاظ و عبارات کے استعمال سے روکیں جیسا کہ نبی اکرم صلی اللہ علیہ وسلم نے لفظ «عتمہ» کی جگہ «عشاء» کا استعمال کیا اور یہ حدیث منقطع ہے ، زید بن اسلم نے عائشہ رضی اللہ عنہا سے نہیں سنا ہے۔(عون المعبود ۱۳/۲۲۷)","ضعیف الإسناد",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا ‘ آپ صلی اللہ علیہ وسلم ہر ایک شے میں دین ہی کی نسبت کا خیال فرماتے تھے۔","f2":"مقصد یہ ہےکہ عام گفتگواورامورمیں دینی نسبت کااہتمام کرناچاہئے۔جاہلی نسبتوں سے احتراز کرنا چاہئے جیسےکہ اوپرکی احادیث میں گزرا ہے۔"}],[4988,"انس رضی اللہ عنہ کہتے ہیں کہ مدینہ میں ایک بار (دشمن کا) خوف ہوا، رسول اللہ صلی اللہ علیہ وسلم ابوطلحہ کے گھوڑے پر سوار ہو کر نکلے، (واپس آئے تو) فرمایا: ہم نے تو کوئی چیز نہیں دیکھی، یا ہم نے کوئی خوف نہیں دیکھا اور ہم نے اسے (گھوڑے کو) سمندر (سبک رفتار) پایا ۱؎۔\n§وضاحت\n۱؎ : گویا کسی چیز کو کسی دوسری چیز سے تشبیہ دی جا سکتی ہے، اگرچہ ان دونوں میں کلی طور پر اشتراک نہ ہو صرف جزوی اشتراک ہو، جیسا کہ آپ صلی اللہ علیہ وسلم نے گھوڑے کو محض سبک رفتاری میں اشتراک کی وجہ سے بحر(سمندر) سے تشبیہ دی ،اسی طرح نماز عشاء کو عتمہ سے تشبیہ دی جا سکتی ہے ، کیونکہ یہ عتمہ یعنی تاریکی میں پڑھی جاتی ہے، اس استدلال سے محض تکلف ظاہر ہوتا ہے، اس باب میں زیادہ موزوں اور واضح استدلال ابوہریرہ رضی اللہ عنہ کی وہ روایت ہے جس کی تخریج بخاری، مسلم اور ترمذی نے کی ہے، اور جس میں یہ الفاظ وارد ہیں : «ولو يعلمون ما في العتمة والصبح لأتوهما ولو حبوا» ۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ مدینے میں کوئی افواہ پھیل گئی (شاید کوئی دشمن حملہ آور ہونے والا ہے) تو نبی کریم صلی اللہ علیہ وسلم سیدنا ابوطلحہ رضی اللہ عنہ کے گھوڑے پر سوار ہوئے (اور ادھر ادھر دیکھ بھال کر آئے) اور فرمایا ” ہم نے کچھ نہیں دیکھا ہے۔ “ یا فرمایا ” ہم نے خوف کی کوئی بات نہیں دیکھی۔ اور یہ گھوڑا تو گویا سمندر ہے۔ “","f2":"1) رسول اللہ صلی اللہ علیہ وسلم نے گھوڑے کی سبک رفتاری کو اس کے سمندر ہونے سے تشبیہ دی ہے۔ تو اس سے محدث رحمتہ اللہ کا استد لال یہ ہے کہ اگر اندھیرے کی نسبت سے عشاء کی نماز کو کبھی عتمہ یاسوتے کی نماز کہہ دیا جائے تو جائز ہے۔\n2) صاحب ایمان کو جری اور بہادر ہوناچاہئےاور اپنے معاشرے میں عام اصلاحی کاموں میں سب سے آگے ہونا چاہئےجیسے رسول اللہ صلی اللہ علیہ وسلم تھے۔\n3) کبھی کبھار عام استعمال کی چیزیں عاریتا لے لینےمیں کوئی قباحت نہیں ہےاور مسلمانوں کو اس سلسلے میں بخیل نہیں ہونا چاہئے لیکن عاریتا لینے والے کوبھی چاہئے کہ فراغت کے بعد اس چیز کو پوری ذمے داری کےساتھ واپس کردے۔"}],[4989,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم جھوٹ سے بچو، اس لیے کہ جھوٹ برائی کی طرف لے جاتا ہے، اور برائی جہنم میں لے جاتی ہے، آدمی جھوٹ بولتا ہے اور جھوٹ میں لگا رہتا ہے، یہاں تک کہ وہ اللہ کے نزدیک جھوٹا لکھ دیا جاتا ہے اور سچ بولنے کو لازم کر لو اس لیے کہ سچ بھلائی اور نیکی کی طرف لے جاتا ہے اور نیکی جنت میں لے جاتی ہے، آدمی سچ بولتا ہے اور سچ بولنے ہی میں لگا رہتا ہے یہاں تک کہ وہ اللہ کے نزدیک سچا لکھ دیا جاتا ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ (عبداللہ بن مسعود) رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جھوٹ سے بچو۔ بلاشبہ جھوٹ گناہ کی طرف لے جاتا ہے اور گناہ جہنم میں پہچانے والا ہے۔ بلاشبہ جو انسان جھوٹ بولتا ہو اور جھوٹ ہی کے درپے رہتا ہے تو وہ بالآخر ا اللہ کے ہاں کذاب (انتہائی جھوٹا) لکھ دیا جاتا ہے۔ (ہمیشہ) سچ اپناؤ ‘ سچ (انسان کو) نیکی کی رہنمائی کرتا ہے اور نیکی جنت میں پہنچاتی ہے۔ اور جو شخص سچ بولتا اور سچ کے درپے رہتا ہے تو وہ بالآخر ا اللہ کے ہاں صدیق (انتہائی سچا) لکھ دیا جاتا ہے۔ “","f2":"سچ اور جھوٹ (صدق وکذب) کا تعلق صرف زبان کے الفاظ ہی سےنہیں بلکہ اس کا دائرہ فعل اور نیت تک وسیع ہے۔فکری اعتبار سے انسان صدق کو متلاشی اور اس کےمطابق اپنے اعمال کوسر انجام دینے والاہواور اس کے برخلاف سے بچنےوالا ہوتو یہ بہت بڑی فضیلت ہے۔ ورنہ جلد یا بد دیر فضیحت سے بچ نہیں سکے گا۔"}],[4990,"معاویہ بن حیدہ قشیری رضی اللہ عنہ کہتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: تباہی ہے اس کے لیے جو بولتا ہے تو جھوٹ بولتا ہے تاکہ اس سے لوگوں کو ہنسائے، تباہی ہے اس کے لیے، تباہی ہے اس کے لیے۔","حسن",{"u2":"جناب بہز بن حکیم رضی اللہ عنہ کہتے ہیں کہ مجھے میرے والد (حکیم) نے اپنے والد (سیدنا معاویہ بن حیدہ قشیری رضی اللہ عنہ) سے روایت کیا۔ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا , آپ صلی اللہ علیہ وسلم فرماتے تھے ” ہلاکت ہے اس کے لیے جو اس غرض سے جھوٹ بولے کہ اس سے لوگ ہنسیں۔ ہلاکت ہے اس کے لیے! ہلاکت ہے اس کے لیے! “","f2":"اپنی طرف سے لطیفے بنانا اور خوش طبعی کےلیے جھوٹ بولنا کہ لوگ ہنسیں صاحب ایمان کو قطعازیب میں دیتا ہے، البتہ ایسا مزاح اور خوش طبعی جو مبنی بر حقیقت ہونے کے ساتھ ساتھ اخلاقی اور شرعی حدود قیودکے اندرہو جائز اور مباح ہے۔"}],[4991,"عبداللہ بن عامر رضی اللہ عنہ کہتے ہیں کہ ایک دن میری ماں نے مجھے بلایا اور رسول اللہ صلی اللہ علیہ وسلم ہمارے گھر بیٹھے ہوئے تھے، وہ بولیں: سنو یہاں آؤ، میں تمہیں کچھ دوں گی، رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا: تم نے اسے کیا دینے کا ارادہ کیا ہے؟ وہ بولیں، میں اسے کھجور دوں گی تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: سنو، اگر تم اسے کوئی چیز نہیں دیتی، تو تم پر ایک جھوٹ لکھ دیا جاتا ۱؎۔\n§وضاحت\n۱؎ : معلوم ہوا کہ جب ماں کے لئے بچہ کو اپنی کسی ضرورت کے لئے جھوٹ بول کر پکارنا صحیح نہیں تو بھلا کسی بڑے کے ساتھ جھوٹی بات کیونکر کی جاسکتی ہے، گویا ازراہ ہنسی ہی کیوں نہ ہو وہ حرام ہے۔","حسن",{"u2":"سیدنا عبداللہ بن عامر رضی اللہ عنہ کہتے ہیں کہ ایک دن میری والدہ نے مجھے بلایا۔ ادھر آؤ، چیز دوں گی اور رسول اللہ صلی اللہ علیہ وسلم ہمارے گھر میں تشریف فر تھے۔ آپ صلی اللہ علیہ وسلم نے میری والدہ سے دریافت فرمایا ” تم اسے کیا دینا چاہتی ہو؟ “ انہوں نے بتایا کہ میں اسے کھجور دینا چاہتی ہوں۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے اس سے کہا۔ ” اگر تم اسے کچھ نہ دیتیں تو تم پر ایک جھوٹ لکھ دیا جاتا۔ “","f2":"سچ اور جھوٹ بولنے کا تعلق بڑےآدمیوں ہی سےنہیں،چھوٹے بچوں کے ساتھ بھی ہے بلکہ بعض صالحین نے تو اسے جانوروں تک وسیع کیا ہےکہ آدمی کسی جانور کو ایسی آواز دے یا جھولی بنا کر اسے ہلائےاور اسے تاثر دے کہ اس میں گھاس دانہ وغیرہ ہے، حالانکہ اس میں کچھ نہ ہو تو وہ اسے چھوٹ قرار دیتے ہیں۔ بہرحال جھوٹ ایک قبیح خصلت ہے۔اس سے ہمیشہ بچنا چاہئے۔ سوائے تین مقامات کے جن کا ذکر پیچھے (حدیث:4920-21)گزر چکا ہے۔ بعض محققین نے مذکورہ روایت کو حسن قرار دیا ہے۔"}],[4992,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"آدمی کے گنہگار ہونے کے لیے کافی ہے کہ وہ ہر سنی سنائی بات(بلا تحقیق) بیان کرے\"۔ ابوداؤد کہتے ہیں: حفص نے ابوہریرہ کا ذکر نہیں کیا، ابوداؤد کہتے ہیں: اسے صرف اسی شیخ یعنی علی بن حفص المدائنی نے ہی مسند کیا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کسی آدمی کے گناہ گار ہونے کے لیے یہی بات کافی ہے کہ وہ ہر سنی سنائی بات بیان کرتا رہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ حفص بن عمر کی روایت میں ابوہریرہ کا ذکر نہیں (روایت مرسل ہے)۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: اور اسے صرف علی بن حفص مدائنی نے مسند روایت کیا ہے۔","f2":"مقدمہ صحیح مسلم میں روایت ہے: (كفی بالمرء كذ با ان يحدث بكل ماسمع) آدمی کے جھوٹا ہونا کے لیے یہی کافی ہے کہ وہ ہرسنی سنائی بات بیان کرتاہے (صحیح مسلم المقد ممة حديث)"}],[4993,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حسن ظن حسن عبادت میں سے ہے\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے اور بقول نصر (نصر بن علی) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اچھا گمان رکھنا حسن عبادت میں سے ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: سند میں مذکور مہنا (مہنا بن ابو شبل) ثقہ ہے اور بصری ہے۔","f2":"مسلمان بھائیوں کے متعلق خواہ مخواہ برے گمان رکھنا اور اس پر اپنے معاملات کی بنیاد رکھنا گناہ کی بات ہے۔ (نیز دیکھیے: گزشتہ حدیث 4917) تاہم ضروری ہے کہ انسان ازخود بھی تہمت اور شبہےکےمواقع سےدوررہے اور کسی کو برا گمان کرنے کا موقع نہ دے جیسے اگلی حدیث میں آرہا ہے۔"}],[4994,"ام المؤمنین صفیہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اعتکاف میں تھے، میں ایک رات آپ کے پاس آپ سے ملنے آئی تو میں نے آپ سے گفتگو کی اور اٹھ کر جانے لگی، آپ مجھے پہنچانے کے لیے میرے ساتھ اٹھے اور اس وقت وہ اسامہ بن زید رضی اللہ عنہما کے گھر میں رہتی تھیں، اتنے میں انصار کے دو آدمی گزرے انہوں نے جب نبی اکرم صلی اللہ علیہ وسلم کو دیکھا تو تیزی سے چلنے لگے، آپ نے فرمایا: \"تم دونوں ٹھہرو، یہ صفیہ بنت حیی ہیں\" ان دونوں نے کہا: سبحان اللہ، اللہ کے رسول! (یعنی کیا ہم آپ کے سلسلہ میں بدگمانی کر سکتے ہیں) آپ نے فرمایا: \"شیطان آدمی میں اسی طرح پھرتا ہے، جیسے خون (رگوں میں) پھرتا ہے، تو مجھے اندیشہ ہوا کہ تمہارے دل میں کچھ ڈال نہ دے، یا یوں کہا: کوئی بری بات نہ ڈال دے ۱؎\"۔\n§وضاحت\n۱؎ : نبی اکرم صلی اللہ علیہ وسلم کو یہ خوف لاحق ہوا کہ کہیں میری نسبت سے ان دونوں کے دل میں کوئی بات ایسی پیدا ہو گئی جو ان کے کفر و ارتداد کا سبب بن گئی تو یہ دونوں تباہ و برباد ہو جائیں گے، اس لئے ان پر شفقت کرتے ہوئے آپ نے ظن و شک والے امر کی وضاحت کر دی تاکہ یہ دونوں صحیح و سلامت رہیں کیونکہ آپ کو اپنی ذات کے بارے میں کوئی خوف نہیں تھا۔","صحیح",{"u2":"ام المؤمنین سیدہ صفیہ رضی اللہ عنہا ا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم اعتکاف میں تھے اور میں رات کے وقت آپ صلی اللہ علیہ وسلم کی زیارت کے لیے حاضر ہوئی۔ میں آپ صلی اللہ علیہ وسلم سے باتیں کرتی رہی، پھر اٹھ کر واپس جانے لگی تو آپ صلی اللہ علیہ وسلم بھی میرے ساتھ اٹھے تاکہ مجھے واپس پہنچا آئیں اور میری رہائش سیدنا اسامہ بن زید رضی اللہ عنہ کے احاطہ میں تھی۔ تو انصاریوں کے دو آدمی گزرے۔ انہوں نے جب رسول اللہ صلی اللہ علیہ وسلم کو دیکھا تو ذرا تیزی سے چلنے لگے۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ٹھہر جاؤ! یہ (میرے ساتھ) صفیہ بنت حیی ہے۔ ان دونوں نے کہا: سبحان اللہ (اللہ پاک ہے) اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا ” بالاشبہ شیطان انسان کے جسم میں ایسے گردش کرتا ہے جیسے خون۔ مجھے اندیشہ ہوا کہ کہیں وہ تمہارے دلوں میں کچھ ڈال نہ دے۔ “ یا فرمایا ” کوئی بری بات نہ ڈال دے۔ “","f2":"1) اعتکاف کے دوران میں جائزہے کہ بیوی معتکف کو ملنے کے لئے آئےاور وہ آپس میں گفتگو کریں۔\n2) معتکف اپنی فطری ضروریات کے لئے مسجد سے باہر جاسکتاہے۔ مثلا قضائے حاجت یا ضروری غسل لے لئے جبکہ مسجد میں ان کا معقول انتظام نہ ہو،اسی طرح شدید بیماری کی حالت میں بھی جبکہ مسجد میں طبی امداد پہنچنے کے مواقع نہ ہوں تو اس قسم کے تمام حالات میں مسجد سے باہر جانا جائز ہے۔\n3) انسان کو تہمت اور شبہے کےمقامات سے ہمیشہ بچتے رہنا چاہیئے۔ نبی صلی اللہ علیہ وسلم نے اپنی اہلیہ محترمہ کا تعارف کراکے اس شہبے کازالہ فرمادیا۔\n4) شیطان انسان کے جسم میں ایسے گردش کرتا ہے جیسے خون اس لیے اس کے شر سے محفوظ رہنے کے لئے تعوذ(اعوذ باللہ من الشیطان الرجیم) بہت زیادہ بڑھنا چاہئے۔"}],[4995,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب آدمی اپنے بھائی سے وعدہ کرے اور اس کی نیت یہ ہو کہ وہ اسے پورا کرے گا، پھر وہ اسے پورا نہ کر سکے اور وعدے پر نہ آ سکے تو اس پر کوئی گناہ نہیں\"۔","ضعیف",{"u2":"سیدنا زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بندہ جب اپنے بھائی سے کوئی وعدہ کر لے اور اس کی نیت یہ ہو کہ وہ اپنا وعدہ وفا کرے گا مگر نہ کر سکے اور وعدے پر نہ پہنچ سکا ہو تو اس پر کوئی گناہ نہیں۔ “","f2":"یہ روایت ضعیف ہے۔ لیکشن انسان اگر فطری طور پر نسیان کا شکار ہوگیا ہو تومعاف ہےمگر عمداوعدے کا پاس نہ کرنااور اس کےخلاف کرنا علامات نفاق میں سے ہے۔"}],[4996,"عبداللہ بن ابو حمساء رضی اللہ عنہ کہتے ہیں کہ میں نے بعثت سے پہلے نبی اکرم صلی اللہ علیہ وسلم سے ایک چیز خریدی اور اس کی کچھ قیمت میرے ذمے رہ گئی تو میں نے آپ سے وعدہ کیا کہ میں اسی جگہ اسے لا کر دوں گا، پھر میں بھول گیا، پھر مجھے تین (دن) کے بعد یاد آیا تو میں آیا، دیکھا کہ آپ اسی جگہ موجود ہیں، آپ نے فرمایا: \"اے جوان! تو نے مجھے زحمت میں ڈال دیا، اسی جگہ تین دن سے میں تیرا انتظار کر رہا ہوں\"۔","ضعیف الإسناد",{"u2":"سیدنا عبداللہ بن ابو حمساء رضی اللہ عنہ سے روایت ہے وہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم کے مبعوث ہونے سے پہلے کی بات ہے کہ میں نے آپ صلی اللہ علیہ وسلم سے ایک سودا کیا اور کچھ قیمت باقی رہ گئی، تو میں نے آپ صلی اللہ علیہ وسلم سے وعدہ کر لیا کہ میں یہیں آپ کے پاس لے آتا ہوں۔ مگر مجھے اپنی یہ بات تین دن بعد یاد آئی، پھر میں آیا تو آپ صلی اللہ علیہ وسلم وہیں تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اے جوان! تو نے مجھے بہت اذیت پہنچائی ہے۔ میں تین دن سے یہاں انتظار کر رہا ہوں۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ محمد بن یحییٰ نے کہا: (سند میں مذکور) عبدالکریم ‘ یہ ابن عبداللہ بن شقیق ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: بواسطہ علی بن عبداللہ مجھے یہ روایت اسی طرح پہنچی ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: بشر بن سری نے اسے «عن عبد الكريم بن عبد الله بن شقيق» کی سند سے روایت کیا ہے۔","f2":"یہ روایت بھی ضعیف ہے تاہم حقیقت یہی ہےکہ رسول اللہ صلی اللہ علیہ وسلم وعدے کے انتہائی پکے ہیں۔"}],[4997,"اسماء بنت ابی بکر رضی اللہ عنہما سے روایت ہے کہ ایک عورت نے کہا: اللہ کے رسول! میری ایک پڑوسن یعنی سوکن ہے، تو کیا مجھ پر گناہ ہو گا اگر میں اسے جلانے کے لیے کہوں کہ میرے شوہر نے مجھے یہ یہ چیزیں دی ہیں جو اس نے نہیں دی ہیں، آپ نے فرمایا: \"جلانے کے لیے ایسی چیزوں کا ذکر کرنے والا جو اسے نہیں دی گئیں اسی طرح ہے جیسے کسی نے جھوٹ کے دو لبادے پہن لیے ہوں\"۔","صحیح",{"u2":"سیدہ اسماء بنت ابوبکر رضی اللہ عنہا ا سے روایت ہے کہ ایک عورت نے کہا: اے ا اللہ کے رسول! میری ایک سوکن ہے، اگر میں اس کے سامنے ایسے ظاہر کروں کہ یہ چیز مجھے میرے شوہر نے دی ہے، حالانکہ دی نہ ہو تو کیا مجھ پر گناہ ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” جو کوئی ایسے ظاہر کرے کہ یہ چیز میری ہے، حالانکہ اسے نہ دی گئی ہو تو اس کی مثال اس شخص کی سی ہے جو مکر کے دو کپڑے پہنے ہو۔ “","f2":"کسی مسلمان کو دھوکا دینا یامانگے تانگے کی چیز پر اترنا کسی صاحب ایمان کوزیب نہیں دیتاہے۔اسی طرح سو کنوں کا آپس میں ایسی کیفیت پیدا کرنا کہ دوسری کڑھنے لگے جائز نہیں۔ یاکوئی اپنے آپ کو دکھلاوے کے طور پرزاہد ظاہرکرے،حالانکہ حقیقت اس کے خلاف ہو۔"}],[4998,"انس رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور اس نے عرض کیا: اللہ کے رسول! مجھے سواری عطا فرما دیجئیے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہم تو تمہیں اونٹنی کے بچے پر سوار کرائیں گے\" وہ بولا: میں اونٹنی کے بچے کا کیا کروں گا؟ تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آخر ہر اونٹ اونٹنی ہی کا بچہ تو ہوتا ہے\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے مروی ہے کہ ایک آدمی نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اے ا اللہ کے رسول! مجھے کوئی سواری عنایت فرمائیں۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہم تجھے اونٹنی کا بچہ دے دیتے ہیں۔ “ وہ بولا: میں اونٹنی کے بچے کا کیا کروں گا؟ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اونٹ کو بھی تو اونٹنی ہی جہنم دیتی ہے۔ “","f2":"خوش طبعی اور ہنسی مذاق انسانی طبیعت کا لازمہ ہے اس سے طبیعت میں بشاشت آجاتی ہے۔ اور رسول اللہ صلی اللہ علیہ وسلم بھی اس سے موصوف تھے مگر اس میں حق وصدق کےسوا کچھ نہ ہوتا تھا۔ بخلاف اس کے جو کوئی جھوٹ بول کرہنسے ہنسائے وہ گناہ کبیرہ کا مرتکب ہوتاہے۔"}],[4999,"نعمان بن بشیر رضی اللہ عنہما کہتے ہیں کہ ابوبکر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے اندر آنے کی اجازت طلب کی تو سنا کہ ام المؤمنین عائشہ رضی اللہ عنہا اونچی آواز میں بول رہی ہیں، تو وہ جب اندر آئے تو انہوں نے انہیں طمانچہ مارنے کے لیے پکڑا اور بولے: سنو! میں دیکھ رہا ہوں کہ تم اپنی آواز رسول اللہ صلی اللہ علیہ وسلم پر بلند کرتی ہو، تو نبی اکرم صلی اللہ علیہ وسلم انہیں روکنے لگے اور ابوبکر غصے میں باہر نکل گئے، تو جب ابوبکر باہر چلے گئے تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"دیکھا تو نے میں نے تجھے اس شخص سے کیسے بچایا\" پھر ابوبکر کچھ دنوں تک رکے رہے (یعنی ان کے گھر نہیں گئے) اس کے بعد ایک بار پھر انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اجازت طلب کی تو ان دونوں کو پایا کہ دونوں میں صلح ہو گئی ہے، تو وہ دونوں سے بولے: آپ لوگ مجھے اپنی صلح میں بھی شامل کر لیجئے جس طرح مجھے اپنی لڑائی میں شامل کیا تھا، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہم نے شریک کیا، ہم نے شریک کیا\"۔","ضعیف الإسناد",{"u2":"سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت ہے کہ سیدنا ابوبکر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کے ہاں اندر آنے کی اجازت چاہی ‘ تو انہوں نے سیدہ عائشہ رضی اللہ عنہا ا کی آواز سنی جو قدرے بلند تھی۔ جب وہ اندر آئے تو انہوں نے اسے طمانچہ مارنے کے لیے پکڑا۔ اور بولے: میں تمہیں دیکھتا ہوں کہ تم رسول اللہ صلی اللہ علیہ وسلم کے سامنے اپنی آواز بلند کرتی ہو۔ تو نبی کریم صلی اللہ علیہ وسلم اسے بچانے لگے اور سیدنا ابوبکر رضی اللہ عنہ غصے سے باہر نکل آئے۔ جب ابوبکر رضی اللہ عنہ چلے گئے تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” دیکھا! میں نے تجھے اس آدمی سے کیسے بچایا؟ “ سیدنا ابوبکر رضی اللہ عنہ نے چند دن توقف کیا اور پھر رسول اللہ صلی اللہ علیہ وسلم سے (ملنے کے لیے) اجازت چاہی اور انہیں پایا کہ ان کی صلح ہو چکی ہے ‘ تو ان سے کہا: مجھے بھی اپنی صلح میں شامل کر لو جیسے تم نے مجھے اپنی لڑائی میں شامل کیا تھا۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہم نے کر لیا ‘ ہم نے کر لیا۔ “","f2":"یہ روایت ضعیف ہے تاہم رسول اللہ صلی اللہ علیہ وسلم کی اندرون خانہ زندگی خوش طبعی، مزاھ اوروسعت قلبی کی حامل تھی اس میں تکلیف اور درشتی یا خشکی کا کوئی پہلونہ تھا۔"}],[5000,"عوف بن مالک اشجعی رضی اللہ عنہ کہتے ہیں کہ میں غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ چمڑے کے ایک خیمے میں قیام پذیر تھے، میں نے آپ کو سلام کیا تو آپ نے جواب دیا، اور فرمایا: \"اندر آ جاؤ\" تو میں نے کہا کہ پورے طور سے اللہ کے رسول! آپ نے فرمایا: \"پورے طور سے\" چنانچہ میں اندر چلا گیا۔","صحیح",{"u2":"سیدنا عوف بن مالک اشجعی رضی اللہ عنہ بیان کرتے ہیں کہ غزوہ تبوک کے سفر میں، میں رسول ا اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ آپ صلی اللہ علیہ وسلم چمڑے کے ایک خیمے میں ٹھہرے ہوئے تھے۔ میں نے سلام کہا، تو آپ صلی اللہ علیہ وسلم نے جواب دیا اور فرمایا ” اندر آ جاؤ۔ “ میں نے عرض کیا۔ کیا میں سارا ہی آ جاؤں، اے ا اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا ” سارا ہی آ جاؤ۔ “ اور میں اندر حاضر ہو گیا۔"}],[5001,"عثمان بن ابی العاتکہ کہتے ہیں کہ انہوں نے جو یہ پوچھا کہ کیا پورے طور پر اندر آ جاؤں تو اس وجہ سے کہ خیمہ چھوٹا تھا۔","ضعیف الإسناد",{"u2":"عثمان بن ابوعاتکہ نے بیان کیا کہ (مذکورہ بالا قصے میں) عوف بن مالک نے جو کہا: ” میں سارا ہی اندر آ جاؤں۔ “ یہ اس وجہ سے تھا کہ وہ خیمہ چھوٹا سا تھا۔"}],[5002,"انس رضی اللہ عنہ کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے دو کانوں والے!\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کہتے ہیں کہ (ایک بار) نبی کریم صلی اللہ علیہ وسلم نے مجھے یوں پکارا ” اے دو کانوں والے! “"}],[5003,"یزید بن سعید رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"تم میں سے کوئی اپنے بھائی کا سامان (بلا اجازت) نہ لے نہ ہنسی میں اور نہ ہی حقیقت میں ۱؎\"۔ سلیمان کی روایت میں ( «لاعبا ولا جادا\"» کے بجائے) «لعبا ولا جدا» ہے، اور جو کوئی اپنے بھائی کی لاٹھی لے تو چاہیئے کہ (ضرورت پوری کر کے) اسے لوٹا دے۔ ابن بشار نے صرف عبداللہ بن سائب کہا ہے ابن یزید کا اضافہ نہیں کیا ہے اور (رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا، کہنے کے بجائے) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہا ہے۔\n§وضاحت\n۱؎ : حقیقت میں لینے کی ممانعت کی وجہ تو ظاہر ہے کہ یہ چوری ہے اور ہنسی میں لینے کی ممانعت کی وجہ یہ ہے کہ اس میں کوئی فائدہ نہیں بلکہ کبھی کبھی یہ چیز سامان والے کی ناراضگی اور اس کے لئے تکلیف کا باعث بن جاتی ہے۔","حسن",{"u2":"جناب عبداللہ بن سائب بن یزید اپنے والد سے وہ دادا سے روایت کرتے ہیں کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے سنا ” تم میں سے کوئی شخص اپنے بھائی کی کوئی چیز ہرگز نہ لے، نہ ہنسی مذاق میں اور نہ حقیقت میں سچے طور ہر۔ “ سلیمان (سلیمان بن عبدالرحمٰن) کے لفظ تھے «لعبا ولا جدا» ” اور جس نے اپنے بھائی سے (کوئی) لاٹھی (بھی) لی ہو تو اسے واپس کر دے۔ “ محمد بن بشار نے (عبداللہ بن سائب کے نسب میں) ” ابن یزید “ نہیں کہا۔ اور («سمع النبي صلى الله عليه وسلم يقول» کی بجائے) «قال رسول الله صلى الله عليه وسلم» کہا۔","f2":"مسلمان کی جان ومال اورعزت وآبروانتہائی محترم ومحفوظ چیزیں ہیں۔ ہنسی مزاح میں بھی کسی کی ہتک کردینا یا مال ہڑپ کرلینا حرام ہے۔"}],[5004,"عبدالرحمٰن بن ابی لیلی سے روایت ہے کہ ہم سے صحابہ کرام رضی اللہ عنہم نے بیان کیا کہ وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ جا رہے تھے، ان میں سے ایک صاحب سو گئے، کچھ لوگ اس رسی کے پاس گئے، جو اس کے پاس تھی اور اسے لے لیا تو وہ ڈر گیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان کے لیے درست نہیں کہ وہ کسی مسلمان کو ڈرائے ۱؎\"۔\n§وضاحت\n۱؎ : بطور مذاق بھی ایسا کرنا صحیح نہیں کیونکہ اس میں ایذا رسانی ہے۔","صحیح",{"u2":"جناب عبدالرحمٰن بن ابولیلیٰ روایت کرتے ہیں کہ محمد صلی اللہ علیہ وسلم کے صحابہ نے ہمیں بیان کیا کہ وہ لوگ نبی کریم صلی اللہ علیہ وسلم کے ساتھ سفر میں جا رہے تھے، تو ان میں سے ایک آدمی سو گیا اور دوسرا اس سے ایک رسی لینے لگا جو اس کے پاس تھی، تو وہ ڈر گیا، تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کسی مسلمان کے لیے حلال نہیں کہ دوسرے مسلمان کو ڈرائے۔ “","f2":"ہنسی مذاق میں بھی کسی مسلمان کو ڈرانا جائز نہیں۔"}],[5005,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی دشمنی رکھتا ہے تڑتڑ بولنے والے ایسے لوگوں سے جو اپنی زبان کو ایسے پھراتے ہیں جیسے گائے (گھاس کھانے میں) چپڑ چپڑ کرتی ہے، یعنی بے سوچے سمجھے جو جی میں آتا ہے بکے جاتا ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تحقیق اللہ عزوجل ایسے آدمی سے غصے ہوتا ہے جو (ناحق) زبان آور ہو (بہت باتیں بنائے) اپنی زبان کو ایسے چلائے جیسے گائے چلاتی ہے (اور لپیٹ لپیٹ کر گھاس کھاتی ہے)۔ “","f2":"فصاحت وبلاغت اصحاب علم وفضل میں ایک عمدہ صفت ہےمگراس میں تصنع بناوٹ اوردھاڑنےکی کیفیت کسی طرح بھی اخلاقا یا شرعا پسندیدہ نہیں بالخصوص جب خلاف حقیقت باتیں بنائی جائیں۔"}],[5006,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی باتوں کو گھمانا اس لیے سیکھے کہ اس سے آدمیوں یا لوگوں کے دلوں کو حق بات سے پھیر کر اپنی طرف مائل کر لے، تو اللہ قیامت کے دن اس کی نہ نفل (عبادت) قبول کرے گا اور نہ فرض\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے گفتگو کا ہیر پھیر (باتیں بنانے کا ڈھنگ) اس لیے سیکھا کہ وہ اس کے ذریعے سے لوگوں کے دل موہ لے، تو اللہ عزوجل قیامت کے روز اس کا کوئی نفل اور فرض قبول نہیں کرے گا۔ “"}],[5007,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ دو آدمی ۱؎ پورب سے آئے تو ان دونوں نے خطبہ دیا، لوگ حیرت میں پڑ گئے، یعنی ان کے عمدہ بیان سے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بعض تقریریں جادو ہوتی ہیں ۲؎ یعنی سحر کی سی تاثیر رکھتی ہیں\" راوی کو شک ہے کہ «إن من البيان لسحرا» کہا یا «إن بعض البيان لسحر» کہا۔\n§وضاحت\n۱؎ : ان دونوں آدمیوں کے نام زبرقان بن بدر اور عمرو بن اہتم تھے اور رسول اللہ صلی اللہ علیہ وسلم کے پاس ان کی آمد کا وواقعہ ۹ ھ کا ہے۔ ۲؎ : یہ خوبی اگر حق کی طرف پھیرنے کے لئے ہو تو ممدوح ہوتی ہے اور اگر باطل کی طرف پھیرنے کے لئے ہو تو مذموم۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نے بیان کیا کہ مشرق کی جانب سے دو آدمی آئے اور انہوں نے خطاب کیا تو لوگوں کو ان کے اسلوب خطاب و بیان پر بڑا تعجب ہوا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ بعض بیان جادو ہوتے ہیں۔ “","f2":"یہ حدیث جوامع الکلم کی ایک عمدہ مثال ہے۔ علمائے اسلام کے ایک طبقے نے اسے بیان کی طرح قراردیاہے اور دوسرے نے اس سے مذمت کے معنی سمجھے ہیں جبکہ حقیقت ان دونوں کے بین بین ہے۔ گفتگو خطاب یا تحریر میں بیان اپنے عرفی اوراحطلاحی ہردومعافی میں ایک ساحب علم کے لیے انتہائی اہم عمدہ اور مطلوب صفت ہے۔تمام انبیائے کرام علیہ وسلم اس صف سے موصوف تھے اور یہی وجہ تھی کہ لوگ انہیں ساحر اور ان کےمضامین دعوت کو سحر کہتے تھے کہ اس میں ان کے لئے انکار کو کوئی چارا نہ تھا۔ اور یہی معاملہ وارثین انبیاء علمائے کرام کا ہے کہ وہ اس صف کودعوت دین میں استعمال کریں اور نوآموز اس کی بخوبی مشق بہم پہنچائیں۔ لیکن جہاں معاملہ حد سے بڑھ کر محض مبالغہ آرائی زبان آوری اور حقائق کو مسخ کرنے اور الفاظ سے کھیلنے کا ہو تو، نا جائز اور قابل مذمت ہے جیسے اوپر کی حدیث میں گزرا ہے۔"}],[5008,"ابوظبیہ کا بیان ہے کہ عمرو بن العاص نے ایک دن کہا اور (اس سے پہلے) ایک شخص کھڑے ہو کر بے تحاشہ بولے جا رہا تھا، اس پر عمرو نے کہا: اگر وہ بات میں درمیانی روش اپناتا تو اس کے لیے بہتر ہوتا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: مجھے مناسب معلوم ہوتا ہے یا مجھے حکم ہوا ہے کہ میں گفتگو میں اختصار سے کام یعنی جتنی بات کافی ہو اسی پر اکتفا کروں اس لیے کہ اختصار ہی بہتر روش ہے۔","حسن الإسناد",{"u2":"جناب ابوظبیہ (کلاعی حمصی) سے مروی ہے کہ ایک دن ایک آدمی نے خطاب کیا اور بہت باتیں کیں۔ تو سیدنا عمرو بن العاص رضی اللہ عنہ نے کہا: اگر یہ اپنی گفتگو میں میانہ روی اختیار کرتا تو اس کے لیے بہت بہتر ہوتا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” تحقیق میں نے سمجھا ہے یا (فرمایا کہ) مجھے حکم دیا گیا ہے کہ گفتگو میں میانہ روی اختیار کروں۔ بلاشبہ میانہ روی سراسر خیر ہے۔ ”"}],[5009,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی کے لیے اپنا پیٹ پیپ سے بھر لینا بہتر ہے اس بات سے کہ وہ شعر سے بھرے، ابوعلی کہتے ہیں: مجھے ابو عبید سے یہ بات پہنچی کہ انہوں نے کہا: اس کی شکل (شعر سے پیٹ بھرنے کی) یہ ہے کہ اس کا دل بھر جائے یہاں تک کہ وہ اسے قرآن، اور اللہ کے ذکر سے غافل کر دے اور جب قرآن اور علم اس پر چھایا ہوا ہو تو اس کا پیٹ ہمارے نزدیک شعر سے بھرا ہوا نہیں ہے (اور آپ نے فرمایا) بعض تقریریں جادو ہوتی ہیں یعنی ان میں سحر کی سی تاثیر ہوتی ہے، وہ کہتے ہیں: اس کے معنی گویا یہ ہیں کہ وہ اپنی تقریر میں اس مقام کو پہنچ جائے کہ وہ انسان کی تعریف کرے اور سچی بات (تعریف میں) کہے یہاں تک کہ دلوں کو اپنی بات کی طرف موڑ لے پھر اس کی مذمت کرے اور اس میں بھی سچی بات کہے، یہاں تک کہ دلوں کو اپنی دوسری بات جو پہلی بات کے مخالف ہو کی طرف موڑ دے، تو گویا اس نے سامعین کو اس کے ذریعہ سے مسحور کر دیا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کسی کا پیٹ پیپ سے بھر جائے یہ اس کے لیے بہتر ہے کہ شعروں سے بھرے۔ “ جناب ابوعلی (ابوعلی لؤلؤی) رضی اللہ عنہ نے کہا: اس ارشاد کی توضیح میں جناب ابوعبید کا یہ قول ہمیں پہنچا ہے کہ اس سے مراد یہ ہے کہ کوئی شخص شعر و شاعری میں اس قدر منہمک ہو جائے کہ قرآن کریم اور اللہ کے ذکر ہی سے غافل ہو جائے (تو انتہائی مذموم ہے)۔ لیکن قرآن کریم اور مشغلہ علم غالب رہے تو ایسا آدمی ہمارے خیال میں اس کا مصداق نہیں بنتا کہ اس کا پیٹ شعروں سے بھرا ہو۔ (اور یہ حدیث کہ) ” بلاشبہ کئی بیان جادو ہوتے ہیں۔ “ اس کا مفہوم یہ ہے کہ کوئی انسان کسی کی مدح سرائی پہ آئے تو اس عمدگی سے کرے کہ لوگوں کے دل اس کی طرف مائل ہو جائیں اور پھر جب اس کی مذمت کرنے لگے تو اس انداز سے کرے کہ لوگ اس کی اس دوسری بات کے پیچھے لگ جائیں۔ گویا کہ اس نے سامعین کو اپنی بات سے مسحور کر دیا ہو۔","f2":"شعروشاعری بیان کا ایک فطری اور لازمی حصہ ہے۔ مگر اس حقیقت سےانکار نہیں کیاجاسکتا کہ دینی مزاج شاعری پسند نہیں ہے۔خیرالقرون میں شعر وشعراء سے اشاعت حق اور دفاع اسلام کا کام ضرور لیا گیا ہے مگر بطور فن اس کی حوصلہ افزائی ہرگزنہیں کی گئی۔لہذا کوئی صاحب علم شعروشاعری کو ہی اپنا اوڑھنا بچھونا بنا لے۔اور قرآن اور اللہ کے زکر سے غافل ہورہے تو انتہائی مذموم ہے۔البتہ حد اعتدال میں رہتے ہوئے اپنے اس زوق اور فن سے اشاعت حق اور ابطال باطل کافریضہ سرانجام دے تو بلاشبہ کارخیر ہے۔"}],[5010,"ابی بن کعب رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بعض اشعار دانائی پر مبنی ہوتے ہیں\"۔","صحیح",{"u2":"سیدنا ابی بن کعب رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ کئی شعر حکمت بھرے ہوتے ہیں۔ “"}],[5011,"ابن عباس رضی اللہ عنہما کہتے ہیں کہ ایک اعرابی نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور باتیں کرنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بعض بیان جادو ہوتے ہیں اور بعض اشعار «حكم» ۱؎ (یعنی حکمت) پر مبنی ہوتے ہیں\"۔\n§وضاحت\n۱؎ : یہاں «حُکْم» ، «حِکْمَتْ» کے معنی میں ہے جیسا کہ آیت کریمہ «وآتیناہ الحُکْمَ صبیّاً» میں ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ ایک بدوی نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور اپنے مخصوص انداز میں باتیں کرنے لگا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا &rdquo; بلاشبہ کئی بیان جادو ہوتے ہیں اور بلاشبہ کئی شعر حکمت ہوتے ہیں۔ &ldquo;","f2":"یہ احادیث دلیل ہیں۔کہ خطبائے اسلام مدرسین شریعت اور طلبہ کرام کو چاہیے کہ اپنے دعوتی بیانات کو حکمت بھرے اشعار اور عمدہ اسلوب بیان سے مزین بنانے میں محنت کریں تاکہ ابلاغ حق اور ابطال باطل کافریضہ بحسن وخوبی ادا ہو اور دین اور اہل دین کا علم سر بلند ہو۔بھدے خطیب اور بے ربط وغیرہ مدلل متکلم اور مدرس نہ صرف اپنی بلکہ دین اسلام اور داعیان حق کی تضحیک ومذمت کا باعث بنتے ہیں۔"}],[5012,"بریدہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"بعض بیان یعنی گفتگو، خطبہ اور تقریر جادو ہوتی ہیں(یعنی ان میں جادو جیسی تاثیر ہوتی ہے)، بعض علم جہالت ہوتے ہیں، بعض اشعار حکمت ہوتے ہیں، اور بعض باتیں بوجھ ہوتی ہیں\"۔ تو صعصہ بن صوحان بولے: اللہ کے نبی نے سچ کہا، رہا آپ کا فرمانا بعض بیان جادو ہوتے ہیں، تو وہ یہ کہ آدمی پر دوسرے کا حق ہوتا ہے، لیکن وہ دلائل (پیش کرنے) میں صاحب حق سے زیادہ سمجھ دار ہوتا ہے، چنانچہ وہ اپنی دلیل بہتر طور سے پیش کر کے اس کے حق کو مار لے جاتا ہے۔ اور رہا آپ کا قول \"بعض علم جہل ہوتا ہے\" تو وہ اس طرح کہ عالم بعض ایسی باتیں بھی اپنے علم میں ملانے کی کوشش کرتا ہے، جو اس کے علم میں نہیں چنانچہ یہ چیز اسے جاہل بنا دیتی ہے۔ اور رہا آپ کا قول \"بعض اشعار حکمت ہوتے ہیں\" اس کا مطلب یہ ہے کہ ان میں کچھ ایسی نصیحتیں اور مثالیں ہوتی ہیں، جن سے لوگ نصیحت حاصل کرتے ہیں، رہا آپ کا قول کہ \"بعض باتیں بوجھ ہوتی ہیں\" تو اس کا مطلب یہ ہے کہ تم اپنی بات یا اپنی گفتگو ایسے شخص پر پیش کرو جو اس کا اہل نہ ہو یا وہ اس کا خواہاں نہ ہو۔","ضعیف",{"u2":"سیدنا صخر بن عبداللہ بن بریدہ نے اپنے والد سے انہوں نے دادا سے روایت کیا، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” بلاشبہ بعض بیان جادو ہوتے ہیں اور کئی علم جہالت۔ بیشک کئی شعر حکمت ہوتے ہیں اور بعض اقوال محض بوجھ۔ “ اس پر صعصعہ بن صوحان نے کہا: سچ فرمایا اللہ کے نبی صلی اللہ علیہ وسلم نے۔ آپ صلی اللہ علیہ وسلم کا یہ فرمان ” بعض بیان جادو ہوتے ہیں۔ “ اس کی وضاحت یہ ہے کہ بعض اوقات آدمی کے ذمے کوئی حق ہوتا ہے (کہ وہ حقدار کو ادا کرے) مگر وہ حقدار کے مقابلے میں چرب زبان ہوتا ہے تو لوگوں کو اپنے بیان سے مسحور کر لیتا ہے اور حق مار لیتا ہے۔ اور آپ صلی اللہ علیہ وسلم کا یہ فرمان ” بعض علم جہالت ہوتے ہیں۔ “ یوں ہے کہ بعض اوقات کوئی صاحب علم ان امور میں جن کی اسے کوئی خبر نہیں ہوتی تکلف سے بات کرتا ہے تو جہالت کا ارتکاب کرتا ہے۔ اور آپ صلی اللہ علیہ وسلم کا یہ قول ” کئی شعر حکمت ہوتے ہیں۔ “ تو اس سے مراد وہ اشعار ہیں جن میں وعظ و نصیحت اور عمدہ مثالیں ذکر ہوتی ہیں جن سے لوگ نصیحت پاتے ہیں۔ اور آپ کا یہ کہنا ” کئی اقوال محض بوجھ ہوتے ہیں۔ “ یوں ہے کہ آپ اپنی بات ایسے شخص کے سامنے پیش کرنے لگیں جو اس کے ذوق و مزاج کے مطابق نہ ہو اور نہ وہ اس کا خواہاں ہو۔"}],[5013,"سعید بن المسیب کہتے ہیں کہ عمر رضی اللہ عنہ حسان رضی اللہ عنہ کے پاس سے گزرے، وہ مسجد میں شعر پڑھ رہے تھے تو عمر رضی اللہ عنہ نے انہیں گھور کر دیکھا، تو انہوں نے کہا: میں شعر پڑھتا تھا حالانکہ اس (مسجد) میں آپ سے بہتر شخص (نبی اکرم صلی اللہ علیہ وسلم)موجود ہوتے تھے۔","صحیح",{"u2":"جناب سعید بن مسیب رضی اللہ عنہ نے بیان کیا کہ سیدنا عمر بن خطاب رضی اللہ عنہ، سیدنا حسان رضی اللہ عنہ کے پاس سے گزرے، جبکہ وہ مسجد (مسجد نبوی) میں شعر پڑھ رہے تھے، تو سیدنا عمر رضی اللہ عنہ نے انہیں تیز نظروں سے دیکھا تو انہوں نے جواب دیا۔ بلاشبہ میں اس (مسجد) میں شعر پڑھا کرتا تھا اور اس میں وہ عظیم ہستی موجود ہوتی تھی جو آپ سے کہیں زیادہ افضل تھی۔","f2":"مسجد میں دین اور اخلاقی موضوعات پر مشتمل اشعار کا پڑھنا جائز ہے۔2۔مگر یہ حقیقت بھی برمحل ہے۔ کہ شرعی مزاج شعروشاعری سے کوئی زیادہ مناسبت نہیں رکھتا۔اسی وجہ سے سیدناعمر رضی اللہ تعالیٰ عنہ نے حضرت حسان رضی اللہ تعالیٰ عنہکے شعر پڑھنے کو ناپسنددیدگی کی نظر سے دیکھا۔3۔رسول اللہ صلی اللہ علیہ وسلم کے مقابلے میں کسی بڑے سے بڑے صالح متقی اور مصلح کی کوئی حیثیت نہیں رہ جاتی۔4۔کسی صاحب فضل سے اگر کہیں فکر وعمل میں اختلافی صورت در پیش ہو تو اس کا جواب نہایت ادب واخلاق اوردلیل سے دیا جانا چاہیے۔3۔کوئی ادنیٰ اگر شرعی دلیل وحجت میں قوی ہو تو اس کے قبول کرلینے میں کسی بھی صاحب فضل کو عارنہیں ہونی چاہیے۔"}],[5014,"اس سند سے ابوہریرہ رضی اللہ عنہ سے بھی اسی مفہوم کی حدیث مروی ہے، البتہ اس میں اتنا اضافہ ہے تو وہ (عمر رضی اللہ عنہ) ڈرے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی اجازت کو بطور دلیل پیش نہ کر دیں چنانچہ انہوں نے انہیں (مسجد میں شعر پڑھنے کی) اجازت دے دی۔","صحیح",{"u2":"جناب سعید بن مسیب رضی اللہ عنہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے مذکورہ بالا حدیث کے ہم معنی روایت کیا، اس میں مزید ہے کہ پھر سیدنا عمر رضی اللہ عنہ کو خیال ہوا کہ یہ تو رسول اللہ صلی اللہ علیہ وسلم کی اجازت پیش کر دیں گے۔ چنانچہ انہوں نے ان کو اجازت دے دی (کہ وہ مسجد میں شعر پڑھ سکتے ہیں)۔"}],[5015,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم حسان رضی اللہ عنہ کے لیے مسجد میں منبر رکھتے، وہ اس پر کھڑے ہو کر ان لوگوں کی ہجو کرتے جو رسول اللہ صلی اللہ علیہ وسلم کی شان میں بے ادبی کرتے تھے، تو (ایک بار) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یقیناً روح القدس (جبرائیل) حسان کے ساتھ ہوتے ہیں جب تک وہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے دفاع کرتے ہیں\"۔","حسن",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم سیدنا حسان رضی اللہ عنہ کے لیے مسجد نبوی میں منبر رکھوا دیا کرتے تھے۔ پس وہ اس پر کھڑے ہو کر رسول اللہ صلی اللہ علیہ وسلم کی مذمت کرنے والوں کی ہجو کیا کرتے تھے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” حسان جب تک رسول اللہ صلی اللہ علیہ وسلم کی طرف سے دفاع کریں، روح القدس (جبرائیل امین) اس کے ساتھ ہیں۔ “","f2":"مسجد میں بصورت اشعار رسول مقبول صلی اللہ علیہ وسلم پیش کرنا ایک مباح عمل ہے۔2۔یہ حضرت حسان کا عظیم شرف تھا کہ ایک اعلیٰ مقصد کےلئے رسول اللہ صلی اللہ علیہ وسلم نے اپنا منبر پیش فرمایا۔اور تایئد وجبرئیل کی خوشخبری سنائی۔3۔اس حدیث کا پس منظر پیش نظر رکھنا چاہیے۔کہ حضرت حسان رضی اللہ تعالیٰ عنہ حضرت عائشہ صدیقہ رضی اللہ تعالیٰ عنہا کے واقعہ افک میں ملوث ہوگئے تھے۔اورانہیں حد بھی لگائی گئی تھی۔بعدازاں جب کسی نے ام المومنین سیدہ عائشہ صدیقہ رضی اللہ تعالیٰ عنہا کے سامنے ان کی مذمت کی تو انہوں نے اپنے ذاتی معاملے سے صرف نظر کرتے ہوئے ان کی اسلام او ررسول اللہ صلی اللہ علیہ وسلم کے لئے خدمات کا برملا اظہار فرمایا۔جو اس حدیث میں بیان ہواہے۔"}],[5016,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ آیت کریمہ «والشعراء يتبعهم الغاوون» \"شاعروں کی پیروی وہ کرتے ہیں جو بھٹکے ہوئے ہوں\" (الشعراء: ۲۲۴) میں سے وہ لوگ مخصوص و مستثنی ہیں جن کو اللہ تعالی نے «إلا الذين آمنوا وعملوا الصالحات وذكروا الله كثيرا» \"سوائے ان کے جو ایمان لائے اور نیک عمل کئے اور بکثرت اللہ تعالی کا ذکر کیا\" (الشعراء: ۲۲۷) میں بیان کیا ہے۔","حسن الإسناد",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے آیت کریمہ «والشعراء يتبعهم الغاوون» ” شاعروں کی پیروی گمراہ لوگ کرتے ہیں۔ “ کی تفسیر میں فرمایا کہ اس کے عموم کو منسوخ کر کے اصحاب ایمان کو مستثنیٰ کر دیا گیا ہے اور فرمایا ہے «إلا الذين آمنوا وعملوا الصالحات وذكروا الله كثيرا» ” مگر وہ لوگ جو ایمان لائے نیک عمل کیے اور اللہ کا بہت ذکر کیا۔ “"}],[5017,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب نماز فجر سے (سلام پھیر کر) پلٹتے تو پوچھتے: \"کیا تم میں سے کسی نے آج رات کوئی خواب دیکھا ہے؟ اور فرماتے: میرے بعد نیک خواب کے سوا نبوت کا کوئی حصہ باقی نہیں رہے گا ۱؎\"۔\n§وضاحت\n۱؎ : یعنی میری موت کے بعد وحی کا سلسلہ بند ہو جائے گا اور مستقبل کی جو باتیں وحی سے معلوم ہوتی تھیں اب صرف سچے خواب ہی کے ذریعہ جانی جا سکتی ہیں۔","صحیح الإسناد",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب فجر کی نماز سے فارغ ہوتے تو دریافت فرمایا کرتے ” کیا آج رات تم میں سے کسی نے کوئی خواب دیکھا ہے؟ “ اور فرمایا کرتے تھے ” بیشک میرے بعد نبوت کا کوئی حصہ باقی نہیں۔ سوائے اس کے کہ کسی کو کوئی نیک خواب آ جائے۔“","f2":"قرآن وحدیث سے ثابت ہے کہ خواب ایک حقیقت واقعہ ہے۔یہ سچے اور جھوٹے دونوں طرح کے ہوتے ہیں۔ سچے خواب اللہ عزوجل کی جانب سے اور جھوٹے شیطان کی طرف سے ہوتے ہیں۔بلکہ انبیاء رسل صلی اللہ علیہ وسلم کا تو خاصہ ہے۔ کہ ان کے خواب بالکل سچے اور وحی کی ایک قسم کے ہوتے ہیں۔اوررسول اللہ صلی اللہ علیہ وسلم کی ابتدائے نبوت خواب ہی سے حاصل ہوئی تھی۔ اور عام مسلمانوں کے خواب جو وہ صحت واعتدال کی کیفیت میں دیکھے وہ بھی بالعموم سچے ہوتے ہیں۔اور انہی کو نبوت کا چھیالیسواں حصہ قرار دیا گیا ہے۔البتہ ان کی تعبیر کا معاملہ خفا میں ہوتا ہے۔ کبھی تو کوئی صاحب علم اس کی حقیقت کو سمجھ لیتا ہے۔اور کبھی اس کی تہ تک پہنچنے میں ناکام رہتا ہے۔"}],[5018,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مومن کا خواب نبوت کے چھیالیس حصوں میں سے ایک حصہ ہے ۱؎\"۔\n§وضاحت\n۱؎ : اس کا ایک مفہوم یہ ہے کہ مومن کا خواب صحیح اور سچ ہوتا ہے اور دوسرا مفہوم یہ ہے کہ آپ کی نبوت کی کامل مدت کل تیئس سال ہے اس میں سے شروع کے چھ مہینے جو مکہ کا ابتدائی دور ہے اس میں آپ کے پاس وحی (بحالت خواب نازل ہوتی تھی اور یہ مدت کل نبوی مدت کے چھیالیس حصوں میں سے ایک حصہ ہے گویا سچا خواب نبوت کے چھیالیس حصوں میں سے ایک حصہ ہوتا ہے۔","صحیح",{"u2":"سیدنا عبادہ بن صامت رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” مومن کا خواب نبوت کا چھیالیسواں حصہ ہے۔“","f2":"صاحب ایمان کی یہ فضیلت ہے۔کہ اس کے خواب بالعموم سچے ہوتے ہیں۔مومن کے خواب کو نبوت کا چھیالیسواں حصہ کہنے کی ایک توجیہ یہ بیان کی جاتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کادور نبوت تیئس سال کا ہے اور ان میں پہلے چھ ماہ تک آپ کو محض خواب آیا کرتے تھے۔جو اس قدر سچے اور حقیقت ہوتے تھے جیسے رات کے اندھیرے کے بعد صبح صادق کاطلوع ہونا۔تو یہ چھ ماہ تیئس سال کا چھیالیسواں حصہ ہے۔ تو اسی نسبت سے مومن کے خواب کے متعلق یہ کہا گیا ہے۔واللہ اعلم۔2۔جس شخص کی یہ خواہش ہو کہ اس کے خواب سچے ہواکریں تو اسے چاہیے کہ اپنے ایمان وعمل کو خالص بنانے میں محنت کرے۔اور ہمیشہ سچ بولنے کو اپنا معمول بنائے۔"}],[5019,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب زمانہ قریب ہو جائے گا، تو مومن کا خواب جھوٹا نہ ہو گا، اور ان میں سب سے زیادہ سچا خواب اسی کا ہو گا، جو ان میں گفتگو میں سب سے سچا ہو گا، خواب تین طرح کے ہوتے ہیں: بہتر اور اچھے خواب اللہ کی جانب سے خوشخبری ہوتے ہیں اور کچھ خواب شیطان کی طرف سے تکلیف و رنج کا باعث ہوتے ہیں، اور کچھ خواب آدمی کے دل کے خیالات ہوتے ہیں لہٰذا جب تم میں سے کوئی (خواب میں) ناپسندیدہ بات دیکھے تو چاہیئے کہ اٹھ کر نماز پڑھ لے اور اسے لوگوں سے بیان نہ کرے، فرمایا: میں قید (پیر میں بیڑی پہننے) کو (خواب میں) پسند کرتا ہوں اور غل (گردن میں طوق) کو ناپسند کرتا ہوں ۱؎ اور قید (پیر میں بیڑی ہونے) کا مطلب دین میں ثابت قدم ہونا ہے\"۔ ابوداؤد کہتے ہیں: \"جب زمانہ قریب ہو جائے گا\" کا مطلب یہ ہے کہ جب رات اور دن قریب قریب یعنی برابر ہو جائیں۔\n§وضاحت\n۱؎ : کیونکہ اس میں قرض دار رہنے یا کسی کے مظالم کا شکار بننے اور محکوم علیہ ہونے کی جانب اشارہ ہوتا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب زمانہ قریب آ جائے گا، تو مسلمان کا خواب غالباً جھوٹا نہیں ہو گا، اور سب سے سچا خواب اسی کا ہو گا جو بات چیت میں سب سے زیادہ سچا ہو گا۔ خواب تین طرح کے ہوتے ہیں: اچھا خواب اللہ عزوجل کی جانب سے بشارت ہوتی ہے، اور ایک خواب شیطان کی طرف سے غمگین کرنے والا ہوتا ہے، اور ایک خواب بندے کے اپنے اوہام و خیالات ہوتے ہیں۔ تو جب کوئی خواب میں کوئی ناپسندیدہ چیز دیکھے تو چاہیئے کہ اٹھ کھڑا ہو، نماز پڑھے اور لوگوں سے بیان نہ کرے “ اور سیدنا ابوہریرہ رضی اللہ عنہ نے فرمایا میں خواب میں پاؤں میں بیڑیاں دیکھنا پسند کرتا ہوں جبکہ گلے میں طوق دیکھنا برا جانتا ہوں۔ پاؤں میں بیڑیاں دیکھنا دین میں ثابت قدمی کی علامت ہے۔ امام ابوداؤد رضی اللہ عنہ نے فرمایا ” زمانہ قریب آ جانے “ کا مفہوم یہ ہے کہ جب دن اور رات برابر برابر ہو جائیں (موسم بہار ہو)۔","f2":"کسی پریشان کن اور بُرےخواب دیکھنے کی صورت میں اس کی نحوست سے بچنے کےلئے انسان کو تعوذ پڑھتے ہوئے اپنی بایئں طرف تھوکنا اور پہلو بھی بدل لیناچاہیے۔اورسب سے افضل یہ ہے کہ انسان نماز پڑھے۔اور خواب کسی سے بیان نہ کرے۔"}],[5020,"ابورزین رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خواب پرندے کے پیر پر ہوتا ہے ۱؎ جب تک اس کی تعبیر نہ بیان کر دی جائے، اور جب اس کی تعبیر بیان کر دی جاتی ہے تو وہ واقع ہو جاتا ہے\"۔ میرا خیال ہے آپ نے فرمایا \"اور اسے اپنے دوست یا کسی صاحب عقل کے سوا کسی اور سے بیان نہ کرے\"۔\n§وضاحت\n۱؎ : یعنی تعبیر بیان کئے جانے تک اس خواب کے لئے جائے قرار اور ٹھہراؤ نہیں ہوتا۔","صحیح",{"u2":"سیدنا ابورزیں (لقیط بن صبرہ عقیلی) رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” خواب (گویا) پرندے کے پاؤں پر ہے جب تک کہ اس کی تعبیر نہ بیان کر دی جائے۔ چنانچہ جب تعبیر بیان کر دی جاتی ہے تو (وہ اسی طرح) ہو جاتی ہے۔ “ اور میرا خیال ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” اسے اپنے کسی محبت کرنے والے (مخلص) یا صاحب علم کے علاوہ کسی سے ہرگز بیان نہ کرو۔“","f2":"محبت کرنے والا مخلص ساتھی خوشی کی خبر میں تمہارے ساتھ خوش ہوگا۔اور بُری بات سے خاموش رہے گا۔اور صاحب علم یا تو تعبیر ہی عمدہ کرے گا۔یاکسی بُرائی سے بچائو کاطریقہ بتائے گا۔"}],[5021,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"خواب اللہ کی طرف سے ہوتے ہیں اور برے خیالات شیطان کی طرف سے، لہٰذا جب تم میں سے کوئی (خواب میں) ایسی چیز دیکھے جسے وہ ناپسند کرتا ہے، تو اپنے بائیں جانب تین بار تھوکے، پھر اس کے شر سے پناہ طلب کرے تو یہ اسے نقصان نہیں پہنچائے گا\"۔","صحیح",{"u2":"سیدنا ابوقتادہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ” اچھا خواب اللہ عزوجل کی طرف سے اور برا خواب شیطان کی طرف سے ہوتا ہے۔ چنانچہ جب کوئی شخص کوئی ناپسند چیز دیکھے تو چاہیئے کہ اپنے بائیں جانب تین بار تھوکے، پھر اس کے شر سے اللہ کی پناہ مانگے۔ بلاشبہ وہ (خواب) اسے ضرر نہیں پہنچائے گا۔ “"}],[5022,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی خواب دیکھے جسے وہ ناپسند کرتا ہو تو اپنی بائیں جانب تین بار تھوکے تین بار شیطان سے اللہ کی پناہ طلب کرے، اور اپنے اس پہلو کو بدل دے جس پر وہ تھا\"۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی ایسا خواب دیکھے جو اسے برا لگے تو اسے چاہیئے کہ اپنی بائیں جانب تھوک دے۔ اور تین بار، شیطان کے شر سے اللہ کی پناہ طلب کرے، اور اپنی کروٹ بدل لے۔ “"}],[5023,"ابوہریرہ رضی اللہ عنہ کہتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جس نے مجھے خواب میں دیکھا تو وہ مجھے جاگتے ہوئے بھی عنقریب دیکھے گا، یا یوں کہا کہ گویا اس نے مجھے جاگتے ہوئے دیکھا، اور شیطان میری شکل میں نہیں آ سکتا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” جس نے مجھے خواب میں دیکھا وہ عنقریب مجھے جاگتے میں بھی دیکھے گا، یا فرمایا کہ اس نے گویا مجھے جاگتے میں دیکھا۔ اور شیطان میری صورت اختیار نہیں کر سکتا۔“","f2":"نبی صلی اللہ علیہ وسلم کا یہ خاصہ ہے۔کہ شیطان آپ کی شکل نہیں اختیار کرسکتا۔ البتہ یہ ضرور ہوسکتا ہے کہ کوئی دوسری شکل دیکھا کر ایسا وہم دلائے کہ یہ رسول اللہ صلی اللہ علیہ وسلم ہیں۔تو اس لئے ضروری ہے کہ انسان اس دیکھی ہوئی شکل کا موازنہ ان صفات سے کرے۔جن کا زکر کتب احادیث میں آیا ہے۔ یا کسی صاحب علم سے اس کی تصدیق حاصل کرے۔ والد مرحوم شیخ عبدالعزیز سعیدی رحمۃ اللہ علیہ کو ایک بدعتی شخص نے بزعم خویش بڑے زوق وشوق سے بتایا کہ میں نے نبی کریم صلی اللہ علیہ وسلم کی خواب میں زیارت کی ہے۔والد صاحب نے تفصیل پوچھی تو بولا کہ میں نے ایک نورانی شخصیت دیکھی جس کی سفید براق ڈاڑھی تھی۔والد صاحب نے فورا ً۔لاحول ولا قوہ الا باللہ پڑھا اور واضح کیا کہ تم نے کسی شیطان کو دیکھا ہے۔الغرض خواب میں نبی کریم صلی اللہ علیہ وسلم کودیکھنے والا قیامت میں جاگتے ہوئے آپ صلی اللہ علیہ وسلم کودیکھے گا اور اسے ایک طرح کا خاص قرب حاصل ہوگا۔ورنہ دیگر اصحاب ایمان بھی تو آپ صلی اللہ علیہ وسلم کودیکھیں گے۔"}],[5024,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی تصویر بنائے گا، اس کی وجہ سے اسے(اللہ) قیامت کے دن عذاب دے گا یہاں تک کہ وہ اس میں جان ڈال دے، اور وہ اس میں جان نہیں ڈال سکتا، اور جو جھوٹا خواب بنا کر بیان کرے گا اسے قیامت کے دن مکلف کیا جائے گا کہ وہ جَو میں گرہ لگائے ۱؎ اور جو ایسے لوگوں کی بات سنے گا جو اسے سنانا نہیں چاہتے ہیں، تو اس کے کان میں قیامت کے دن سیسہ پگھلا کر ڈالا جائے گا\"۔\n§وضاحت\n۱؎ : اور وہ یہ نہیں کر سکے گا کیونکہ جَو میں گرہ لگانا ممکن نہیں۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے کوئی تصویر بنائی تو اللہ اسے اس کی وجہ سے قیامت میں عذاب دے گا، حتیٰ کہ وہ اس میں روح پھونکے، مگر وہ نہیں پھونک سکے گا اور جس نے جھوٹے طور پر یہ دعویٰ کیا کہ اس نے یہ خواب دیکھا ہے تو اسے اس بات کا مکلف کیا جائے گا کہ جو کے دانے میں گرہ باندھے (جو کہ ناممکن ہے) اور جس نے کسی قوم کی بات سننے کی کوشش کی جبکہ وہ اپنی بات کرنے کے لیے اس سے دور ہو رہے ہوں تو قیامت کے دن اس کے کان میں سیسہ ڈالا جائے گا۔ “","f2":"تصویر سے مراد کسی جاندار کی تصویربناناہے۔ یا ایسی تصویریں بھی اس میں شمار ہوسکتی ہیں۔جن کی لوگ عبادت کرتے ہیں۔خواہ کسی درخت کی ہو یا پہاڑ وغیرہ کی۔2۔یہ تصویریں ہاتھ سے بنائی جایئں۔یا کیمرے وغیرہ سے سب اسی ضمن میں آتی ہیں۔کیمرے کی تصاویر کوجائز بتانے والی تاویلات بے معنی ہیں۔ صاحب ایمان کو نبی کریم صلی اللہ علیہ وسلم کے ظاہر فرامین پر بے چون وچرا ایمان رکھنا اورعمل کرناچاہیے۔(اللہ عزوجل تصوی کے فتنے سے محفوظ فرمائے۔آمین)3۔اپنی طرف سے بنا بنا کر جھوٹے خواب سنانا۔ اوروں کے نقل کرنا کبیرہ گناہ ہے۔ اور جب اس زریعے سے مقصود لوگوں کے دین وایمان کے ساتھ کھیلنا ہو تو اس کی قباحت اور بھی بڑھ جاتی ہے۔جیسا کہ نام نہاد جاہل صوفیوں اور پیروں کا وتیرہ ہے۔4۔دوسروں کی پوشیدہ اور خاص باتیں سننے کی کوشش کرنا کبیرہ گناہ ہے۔"}],[5025,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے آج رات دیکھا جیسے ہم عقبہ بن رافع کے گھر میں ہوں، اور ہمارے پاس ابن طاب ۱؎ کی رطب تازہ (کھجوریں) لائی گئیں، تو میں نے یہ تعبیر کی کہ دنیا میں بلندی ہمارے واسطے ہے اور آخرت کی عاقبت ۲؎ بھی اور ہمارا دین سب سے عمدہ اور اچھا ہو گیا\"۔\n§وضاحت\n۱؎ : ابن طاب ایک قسم کی کھجور ہے ، اس سے دین کی عمدگی اور پاکی نکلی رافع کے لفظ سے دنیا میں رفعت اور بلندی۔ ۲؎ : اور عقبہ عاقبت کی بھلائی۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میں نے آج رات دیکھا گویا ہم عقبہ بن رافع رضی اللہ عنہ کے گھر میں ہیں اور ہمیں (مدینہ کی معروف عمدہ) تازہ کھجور ابن طاب پیش کی گئی ہے۔ تو میں نے اس کی یہ تعبیر کی ہے کہ ہمیں دنیا میں رفعت و سربلندی حاصل ہو گی اور آخرت میں انجام عمدہ ہو گا اور ہمارا دین بھی خوب (پھل پھول گیا) ہے۔ “","f2":"خواب کی تعبیر میں بعض اوقات الفاظ ومناظرسے بھی معنی اخذ کیے جاتے ہیں۔تو مندرجہ بالا خواب میں لفظ عقبہ سے عاقبت (عمدہ انجام) رافع سے رفعت وسربلندی اور ابن طاب سے طیب اور عمدہ ہونا سمجھا گیا ہے۔جو بحمد للہ ایک تاریخی حققیت ثابت ہوا ہے۔"}],[5026,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی جمائی لے تو اپنے منہ کو بند کر لے، اس لیے کہ شیطان (منہ میں) داخل ہو جاتا ہے\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کسی کو جمائی آئے تو چاہیئے کہ وہ اپنا منہ بند رکھے ‘ بلاشبہ (اس میں) شیطان داخل ہو جاتا ہے۔ “"}],[5027,"سہیل سے بھی اسی طرح مروی ہے اس میں یہ ہے \"(جب جمائی) نماز میں ہو تو جہاں تک ہو سکے منہ بند رکھے\"۔","صحیح",{"u2":"جناب سہیل رضی اللہ عنہ سے مذکورہ بالاحدیث کی مانند مروی ہے (مگر اس میں ہے) ” جمائی اگر نماز میں آئے تو جہاں تک ہو سکے منہ بند رکھنے کی کوشش کرے۔ “"}],[5028,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی چھینک کو پسند کرتا ہے اور جمائی کو ناپسند، لہٰذا جب تم میں سے کسی کو جمائی آئے، تو جہاں تک ہو سکے اسے روکے رہے، اور ہاہ ہاہ نہ کہے، اس لیے کہ یہ شیطان کی طرف سے ہوتی ہے، وہ اس پر ہنستا ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ ا اللہ تعالیٰ چھینک کو پسند اور جمائی کو ناپسند کرتا ہے۔ چنانچہ جب کسی کو جمائی آئے تو جہاں تک ہو سکے اسے روکے اور ہاء ہاء کی آواز نہ نکالے۔ بلاشبہ یہ شیطان کی طرف سے ہوتی ہے اور وہ اس سے ہنستا ہے۔ “","f2":"چھینک آنا طبعیت کے ہلکے ہونے اورصحت مندی کی جبکہ جمائی کسل او ر طبعیت کے بوجھل ہونے کی علامت ہوتی ہے۔ اور شریعت میں ہر بُری کیفیت کی نسبت شیطان کیطرف اور ہر خیر اور بہتری کی نسبت اللہ عزوجل کی طرف کی جاتی ہے۔2۔جمائی کو بند کرنے کی ایک صورت یہ ہے۔کہ انسان جمائی آنے ہی نہ دے۔ یااگر آئے تو منہ پر ہاتھ رکھ لے۔ اور ہاء ہاء کی آواز نہ نکالے۔بالخصو ص نماز کے دوران میں اس کا خاص خیال رکھے۔"}],[5029,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو جب چھینک آتی تھی تو اپنا ہاتھ یا اپنا کپڑا منہ پر رکھ لیتے اور آہستہ آواز سے چھینکتے۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو جب چھینک آتی تو آپ صلی اللہ علیہ وسلم اپنے منہ پر اپنا ہاتھ یا کوئی کپڑا رکھ لیتے اور اپنی آواز کو کم رکھتے۔ یحییٰ کو شک ہے کہ روایت میں لفظ «خفض» تھا یا «غض» (معنی ایک ہی ہیں)۔","f2":"بعض لوگ چھینک آنے پر جان بوجھ کرزور دے کر آواز نکالتے ہیں۔جو خلاف ادب اور غیر مسنون ہے۔اضطراری کیفیت ان شاء اللہ معاف ہے۔"}],[5030,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ چیزیں ہر مسلمان پر اپنے بھائی کے لیے واجب ہیں، سلام کا جواب دینا، چھینکنے والے کا جواب دینا، دعوت قبول کرنا، مریض کی عیادت کرنا اور جنازے کے ساتھ جانا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ایک مسلمان پر دوسرے مسلمان بھائی کے لیے پانچ باتیں واجب ہیں۔ سلام کا جواب دینا ‘ چھینک آنے پر دعا دینا ‘ دعوت قبول کرنا ‘ بیمار پرسی کرنا اور جنازے میں شریک ہونا۔ “"}],[5031,"ہلال بن یساف کہتے ہیں کہ ہم سالم بن عبید کے ساتھ تھے کہ ایک شخص کو چھینک آئی تو اس نے کہا «السلام عليكم» (تم پر سلامتی ہو) تو سالم نے کہا: «عليك وعلى أمك» (تم پر بھی اور تمہاری ماں پر بھی) پھر تھوڑی دیر کے بعد بولے: شاید جو بات میں نے تم سے کہی تمہیں ناگوار لگی، اس نے کہا: میری خواہش تھی کہ آپ میری ماں کا ذکر نہ کرتے، نہ خیر کے ساتھ نہ شر کے ساتھ، وہ بولے، میں نے تم سے اسی طرح کہا جس طرح رسول اللہ صلی اللہ علیہ وسلم نے کہا، اسی دوران کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے اچانک لوگوں میں سے ایک شخص کو چھینک آئی تو اس نے کہا: «السلام عليكم» رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «عليك وعلى أمك» ، پھر آپ نے فرمایا: جب تم میں سے کسی کو چھینک آئے تو «الحمد الله» کہے اللہ کی تعریف کرے پھر آپ نے حمد کے بعض کلمات کا تذکرہ کیا (جو چھینک آنے والا کہے) اور چاہیئے کہ وہ جو اس کے پاس ہو «يرحمك الله» (اللہ تم پر رحم کرے) کہے، اور چاہیئے کہ وہ (چھینکنے والا) ان کو پھر جواب دے، «يغفر الله لنا ولكم» (اللہ ہماری اور آپ کی مغفرت فرمائے) ۔","ضعیف",{"u2":"جناب ہلال بن یساف کہتے ہیں کہ ہم لوگ سیدنا سالم بن عبید رضی اللہ عنہ کے ہاں بیٹھے تھے کہ مجلس میں سے کسی کو چھینک آئی تو اس نے کہا: «السلام عليكم» (تم پر سلامتی ہو) تو سیدنا سالم رضی اللہ عنہ نے کہا: تم پر اور تمہاری ماں پر بھی۔ پھر اس کے بعد فرمایا شاید تمہیں میری بات ناگواری گزری ہے؟ اس نے کہا: آپ میری ماں کا کسی طور خیر یا شر کے ساتھ ذکر نہ کرتے تو اچھا تھا۔ انہوں نے کہا: میں نے تم سے وہی بات کہی ہے جیسے رسول اللہ صلی اللہ علیہ وسلم نے کہی تھی۔ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے کہ قوم میں سے کسی کو چھینک آ گئی تو اس نے کہا: «السلام عليكم» تو رسول اللہ صلی اللہ علیہ وسلم نے جواب دیا ” تم پر اور تمہاری ماں پر بھی۔ “ آپ صلی اللہ علیہ وسلم نے پھر فرمایا ” جب تم میں سے کسی کو چھینک آئے تو چاہیئے کہ «الحمد الله» ” سب تعریفیں ا اللہ کے لیے ہیں “ کہے۔ راوی نے کہا کہ انہوں نے کچھ اور حمدوں کا ذکر بھی کیا۔ اور جو دوسرا اس کے پاس ہو ‘ اسے چاہیئے کہ یوں کہے «يرحمك الله» ” ا اللہ تم پر رحم فرمائے “ اور پھر چھینک مارنے والا ان لوگوں کو جواب دے «يغفر الله لنا ولكم» ” ا اللہ تعالیٰ ہمیں اور تمہیں (سب کو) معاف فر دے۔ “","f2":"یہ روایت ضعیف ہے۔اس کی بابت صحیح روایت (5033) آگے آرہی ہے۔ان شاء اللہ"}],[5032,"اس سند سے سالم بن عبید اشجعی سے یہی حدیث نبی اکرم صلی اللہ علیہ وسلم سے مرفوعاً مروی ہے۔","ضعیف",{"u2":"خالد بن عرفطہ نے سیدنا سالم بن عبید اشجعی رضی اللہ عنہ سے اور انہوں نے نبی کریم صلی اللہ علیہ وسلم سے یہ (مذکورہ بالا) روایت بیان کی۔"}],[5033,"ابوہریرہ رضی اللہ عنہ کہتے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کو چھینک آئے تو چاہیئے کہ وہ کہے: «الحمد لله على كل حال» (ہر حالت میں تمام تعریفیں اللہ کے لیے سزاوار ہیں) اور چاہیئے کہ اس کا بھائی یا اس کا ساتھی کہے: «يرحمك الله»(اللہ تعالی آپ پر رحم فرمائے اب وہ پھر کہے: «يهديكم الله ويصلح بالكم» (اللہ تمہیں ہدایت دے اور تمہیں ٹھیک رکھے، اور تمہاری حالت درست فرما دے)\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کسی کو چھینک آئے تو چاہیئے کہ کہے «الحمد لله على كل حال» ” ہر حال میں ا اللہ کی تعریف ہے۔ “ اور اس کے بھائی یا ساتھی کو چاہیئے کہ کہے «يرحمك الله» ” ا اللہ تم پر رحم فرمائے “ اور پھر وہ جسے چھینک آئی ہو کہے «يهديكم الله ويصلح بالكم» ” ا اللہ تمہیں ہدایت دے اور تمہارے احوال درست کر دے۔ “","f2":"چھینک آنے پر مندرجہ بالا کیفیت میں اللہ کی حمد کرنا۔اور ایک دوسرے کو دعایئں دینا انتہائی تاکیدی سنت ہے۔اور جوشخص خود الحمد للہ نہ کہے۔تو وہ اپنے بھائی سے جواباً دعا کی توقع نہ رکھے۔جیسے اگلی حدیث 5039 میں آرہا ہے۔ایسے ہی زکام وغیرہ کے مریض کو بار بار جواب دینا بھی ضروری نہیں۔"}],[5034,"ابوہریرہ رضی اللہ عنہ کہتے ہیں تین بار اپنے بھائی کی چھینک کا جواب دو اور جو اس سے زیادہ ہو تو وہ زکام ہے۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ اپنے بھائی کو اس کی چھینک آنے پر تین بار جواب دے اور جو اس سے زیادہ ہو ‘ تو پھر وہ زکام زدہ ہے۔","f2":"یہ روایت اگرچہ موقوف ہے۔مگر مرفوع بھی ثابت ہے جیسے اگلی روایت میں ہے۔"}],[5035,"سعید بن ابی سعید ابوہریرہ رضی اللہ عنہ سے اسی مفہوم کی حدیث کو مرفوعاً روایت کرتے ہیں۔ ابوداؤد کہتے ہیں: اسے ابونعیم نے موسی بن قیس سے، موسی نے محمد بن عجلان سے، ابن عجلان نے سعید سے، سعید نے ابوہریرہ سے، ابوہریرہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کیا ہے۔","حسن",{"u2":"جناب سعید بن ابی سعید نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کیا اور کہا کہ مجھے یہی معلوم ہے کہ انہوں نے اس حدیث کو نبی کریم صلی اللہ علیہ وسلم کی طرف نسبت کیا اور مذکورہ بالا روایت کے ہم معنی بیان کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: اس کو ابونعیم نے موسیٰ بن قیس کے واسطے سے محمد بن عجلان سے ‘ انہوں نے سعید سے انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا۔","f2":"بعض محققین نے اس روایت کو حسن قرار دیا ہے۔"}],[5036,"عبید بن رفاعہ زرقی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"چھینکنے والے کا جواب تین بار دو اس کے بعد اگر جواب دینا چاہو تو دو، اور نہ دینا چاہو تو نہ دو\"۔","ضعیف",{"u2":"حمیدہ یا عبیدہ بنت عبید بن رفاعہ زرقی اپنے والد سے بیان کرتی ہیں کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا ” چھینک مارنے والے کو تین بار جواب دو۔ پھر اگر جواب دینا چاہو، تو دو اور اگر چاہو تو، چھوڑ دو۔ “"}],[5037,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ ایک شخص کو نبی اکرم صلی اللہ علیہ وسلم کے پاس چھینک آئی تو آپ نے اس سے فرمایا:«يرحمك الله» \"اللہ تم پر رحم فرمائے\" اسے پھر چھینک آئی تو آپ نے فرمایا: \"آدمی کو زکام ہوا ہے\"۔","صحیح",{"u2":"جناب ایاس بن سلمہ بن اکوع سے روایت ہے وہ اپنے والد سے نقل کرتے ہیں کہ ایک شخص نے نبی کریم صلی اللہ علیہ وسلم کی مجلس میں چھینک ماری، تو آپ صلی اللہ علیہ وسلم نے اسے دعا دی اور فرمایا «يرحمك الله» ” ا اللہ تجھ پر رحم فرمائے۔ “ اس نے پھر چھینک ماری تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اسے زکام ہے۔ “","f2":"پہلی بار چھینک کا جواب دینا لازم ہے۔ اس کے بعد نہیں جیسے صحیح مسلم سے بھی اشارہ ملتا ہے۔دیکھئے (صحیح مسلم الذھد۔حدیث 2993)"}],[5038,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس یہود جان بوجھ کر اس امید میں چھینکا کرتے کہ آپ ان کے لئے «يرحمكم الله» \"تم پر اللہ کی رحمت ہو\" کہہ دیں، لیکن آپ فرماتے: «يهديكم الله ويصلح بالكم» \"اللہ تمہیں ہدایت دے اور تمہارا حال درست کرے\"۔","صحیح",{"u2":"سیدنا ابوبردہ اپنے والد سے روایت کرتے ہیں کہ یہودی لوگ نبی کریم صلی اللہ علیہ وسلم کی مجلس میں عمداً چھینکیں مارا کرتے تھے اور توقع کرتے تھے کہ آپ صلی اللہ علیہ وسلم انہیں دعا دیتے ہوئے «يرحمكم الله» ” ا اللہ تم پر رحم فرمائے “ کہیں گے۔ مگر آپ صلی اللہ علیہ وسلم انہیں یوں جواب دیتے «يهديكم الله ويصلح بالكم» ” ا اللہ تمہیں ہدایت دے اور تمہارے احوال کی اصلاح فرمائے۔ “","f2":"غیر مسلم کو چھینک ک جواب میں (يرحمك الله) كی بجائے۔(يهديكم الله يصلح بالكم)جیسا کہ اسے(السلام و عليكم) کہنے میں ابتداء نہیں کی جاسکتی۔ اور وہ کہے توجواباً صرف علیکم کہاجاتا ہے۔"}],[5039,"انس رضی اللہ عنہ کہتے ہیں کہ دو لوگوں کو نبی اکرم صلی اللہ علیہ وسلم کے پاس چھینک آئی تو آپ نے ان میں سے ایک کی چھینک کا جواب دیا اور دوسرے کو نہ دیا، تو آپ سے پوچھا گیا: اللہ کے رسول! دو لوگوں کو چھینک آئی، تو آپ نے ان میں سے ایک کو جواب دیا؟ ۔ احمد کی روایت میں اس طرح ہے: کیا آپ نے ان دونوں میں سے ایک کو جواب دیا، دوسرے کو نہیں دیا ہے؟ تو آپ نے فرمایا: دراصل اس نے «الحمد الله» کہا تھا اور اس نے «الحمد الله» نہیں کہا تھا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم کی مجلس میں دو آدمیوں کو چھینک آئی تو آپ صلی اللہ علیہ وسلم نے ایک کو جواب دیا اور دوسرے کو نہ دیا۔ تو آپ صلی اللہ علیہ وسلم سے کہا گیا: اے ا اللہ کے رسول! دو آدمیوں نے چھینک ماری ‘ مگر آپ نے ایک جو جواب دیا ہے۔ احمد (احمد بن یونس) نے وضاحت کی کہ یہاں لفظ «فشمت أحدهما» تھے یا «فسمت أحدهما» اور دوسرے کو چھوڑ دیا ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اس نے (جس کو میں نے جواب دیا ہے) ا اللہ کی حمد کی ہے اور اس نے ا اللہ کی حمد نہیں کی۔ “","f2":"جوشخص چھینک آنے پر (الحمد للہ)نہ کہے۔وہ اپنے بھائی کے جواب اور اس کی دعا کا مستحق نہیں رہتا۔"}],[5040,"یعیش بن طخفہ بن قیس غفاری کہتے ہیں کہ میرے والد اصحاب صفہ میں سے تھے تو (ایک بار) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"ہمارے ساتھ عائشہ رضی اللہ عنہا کے گھر چلو\" تو ہم گئے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! ہمیں کھانا کھلاؤ\" وہ دلیا لے کر آئیں تو ہم نے کھایا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! ہمیں کھانا کھلاؤ\" تو وہ تھوڑا سا حیس ۱؎ لے کر آئیں، قطاۃ پرند کے برابر، تو (اسے بھی) ہم نے کھایا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! ہم کو پلاؤ\" تو وہ دودھ کا ایک بڑا پیالہ لے کر آئیں، تو ہم نے پیا، پھر آپ صلی اللہ علیہ وسلم نے (ہم لوگوں سے) فرمایا: \"تم لوگ چاہو (ادھر ہی) سو جاؤ، اور چاہو تو مسجد چلے جاؤ\" وہ کہتے ہیں: تو میں (مسجد میں) صبح کے قریب اوندھا (پیٹ کے بل) لیٹا ہوا تھا کہ یکایک کوئی مجھے اپنے پیر سے ہلا کر جگانے لگا، اس نے کہا: اس طرح لیٹنے کو اللہ ناپسند کرتا ہے، میں نے (آنکھ کھول کر) دیکھا تو وہ رسول اللہ صلی اللہ علیہ وسلم تھے۔\n§وضاحت\n۱؎ : حیس ایک عربی کھانا ہے جو کھجور، ستو، پنیر اور گھی سے بنتا ہے۔","ضعیف",{"u2":"سیدنا یعیش بن طخفہ بن قیس غفاری کا بیان ہے کہ میرے والد (طخفہ رضی اللہ عنہ) اصحاب صفہ میں سے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا ” ہمارے ساتھ سیدہ عائشہ رضی اللہ عنہا ا کے گھر چلو۔ “ تو ہم چل دیے۔ (وہاں پہنچ کر) آپ صلی اللہ علیہ وسلم نے فرمایا ” عائشہ! ہمیں (کچھ) کھلاؤ۔ “ تو وہ جشیشہ لے آئیں جو ہم نے کھایا۔ (جشیشہ اس انداز کا کھانا ہے کہ گندم کو پیس کر آٹا ہنڈیا میں چڑھائیں پھر اس میں گوشت یا کھجور ڈال کر پکائیں۔ اسے ایک طرح کا حلیم بھی کہا جا سکتا ہے۔) پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” عائشہ! ہمیں کچھ اور بھی کھلاؤ۔ “ تو وہ حیس۔ (کھجور ‘ گھی اور پنیر وغیرہ کا مرکب کھانا) لے آئیں جو تھوڑا سا تھا ‘ جیسے کہ چڑیا ہو (یا ممکن ہے کہ سیدہ عائشہ رضی اللہ عنہا ا مراد ہوں کہ وہ صدق و وفا شعاری میں قطاۃ چڑیا کی مانند تھیں) ہم نے وہ حیس کھایا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” عائشہ! ہمیں کچھ پلاؤ۔ “ تو وہ دودھ کا ایک بڑا پیالہ لے آئیں۔ ہم نے وہ پی لیا۔ آپ صلی اللہ علیہ وسلم نے پھر فرمایا ” عائشہ! ہمیں اور بھی پلاؤ۔ “ تو وہ ایک چھوٹا پیالہ لے آئیں ‘ تو ہم نے وہ بھی پیا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر چاہو تو سو جاؤ اور اگر چاہو تو مسجد میں چلے جاؤ۔ “ طخفہ کہتے ہیں: میں مسجد میں اوندھے منہ اپنے پیٹ کے بل لیٹا ہوا تھا کہ میرے پھیپھڑے میں تکلیف تھی۔ تو اچانک میں نے پایا کہ کسی نے مجھے اپنے پاؤں سے حرکت دی ہے اور کہہ رہا ہے۔ ” اس طرح سے سونا ا اللہ تعالیٰ کو ناپسند ہے۔ “ کہتے ہیں: میں نے دیکھا تو وہ رسول اللہ صلی اللہ علیہ وسلم تھے۔","f2":"پیٹ کے بل سونا ناجائز ہے۔افضل یہ ہے کہ دایئں کروٹ سویا جائے۔"}],[5041,"علی بن شیبان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص گھر کی ایسی چھت پر سوئے جس پر پتھر (کی مڈیر) نہ ہو (یعنی کوئی چہار دیواری نہ ہو تو اس سے (حفاظت کا) ذمہ اٹھ گی\" (گرے یا بچے وہ جانے) ۔","صحیح",{"u2":"جناب عبدالرحمٰن اپنے والد علی بن شیبان رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص کسی ایسی چھت پر سوئے جس کے گرد کوئی منڈیر (پردہ وغیرہ) نہ ہو تو اس سے ذمہ اٹھ گیا۔ “","f2":"یعنی ایسی صورت میں اگر وہ گر کر ہلاک ہوجائے۔ یا نقصان اُٹھائے تو اس کا وہ خود زمہ دار ہے۔اور ایسی ننگی چھت پرسونا جائز نہیں۔2۔شریعت کا تعلق صرف نماز روزے حج زکواہٓ یا مسجد ہی سے نہیں بلکہ یہ مسلمان کی پوری زندگی کو محیط ہے۔"}],[5042,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی مسلمان اللہ تعالی کو یاد کرتا ہوا باوضو سوتا ہے پھر رات میں (کسی بھی وقت) چونک کر اٹھتا ہے اور اللہ سے دنیا اور آخرت کی بھلائی کا سوال کرتا ہے تو اللہ تعالی اسے ضرور دیتا ہے\"۔ ثابت بنانی کہتے ہیں: ہمارے پاس ابوظبیہ آئے تو انہوں نے ہم سے معاذ بن جبل کی یہ حدیث بیان کی، جسے وہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ ثابت بنانی کہتے ہیں: فلاں شخص نے کہا ۱؎ کہ میں نے اپنی نیند سے بیدار ہوتے وقت کئی بار اس کلمہ کے ۲؎ادا کرنے کی کوشش کی مگر کہہ نہ سکا ۳؎۔\n§وضاحت\n۱؎ : ثابت بنانی نے کسی وجہ سے کہنے والے کا نام ظاہر نہیں کیا۔ ۲؎ : اس سے مراد دنیا و آخرت میں اللہ تعالی سے خیر کا سوال ہے۔ ۳؎ : شاید ایسا نسیان یا دنیاوی امور میں مشغولیت کے سبب ہوا ہو۔ واللہ اعلم","صحیح",{"u2":"سیدنا معاذ بن جبل رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شخص باوضو ہو کر ا اللہ کا ذکر کرتے ہوئے سو جائے اور پھر رات کو کسی وقت اس کی آنکھ کھلے (اور بستر پر اپنا پہلو وغیرہ بدلے) اور ا اللہ سے دنیا و آخرت کی کوئی خیر مانگ لے ‘ تو وہ اسے عنایت فر دے گا۔ “ ثابت بنانی کہتے ہیں راوی حدیث ابوظبیہ ہمارے ہاں آئے اور انہوں نے ہمیں یہ حدیث بواسطہ سیدنا معاذ بن جبل رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کی۔ ثابت رضی اللہ عنہ نے بیان کیا کہ ایک صاحب نے کہا: میں نے بڑی کوشش کی ہے کہ رات کو اٹھوں اور ایسی کوئی دعا کر لوں مگر میں اس میں کامیاب نہیں ہو سکا۔","f2":"باوضو ہو کرمسنون ازکار پڑھ کر سونے کی بہت برکات ہیں۔ان میں سے ایک یہ ہے کہ اگر انسان رات کو کسی وقت لیٹے لیٹے بھی دعا کرلے تو ان شاء اللہ مقبول ہوتی ہے۔ اور اگر اُٹھ کر نماز پڑھنے میں مشغول ہو تو نور علیٰ نور ہے۔منصوص زکراور دعا حدیث 5060 میں ملاحظہ ہو۔"}],[5043,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات میں بیدار ہوئے پھر اپنی ضرورت سے فارغ ہوئے، پھر اپنا ہاتھ منہ دھویا، پھر سو گئے۔ ابوداؤد کہتے ہیں: اپنی ضرورت سے فارغ ہونے کا مطلب ہے پیشاب کیا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم رات کو اٹھے قضائے حاجت کے لیے گئے۔ پھر اپنا چہرہ اور ہاتھ دھوئے پھر سو گئے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ «قضى حاجته» سے مراد ہے پیشاب کیا۔","f2":"۔ باوضو ہوکرسونے کے معنی یہ ہیں کہ رات کے ابتدائی حصے میں وضو کرکے بستر پر جانے کے علاوہ اگر رات کے کسی حصے میں جاگے اور قضائے حاجت وغیرہ کے لئے جائے تو دوبارہ بھی مسنون وضو کرکے سوئے تو یہ بہت ہی افضل عمل ہے۔"}],[5044,"ام سلمہ کی اولاد میں سے ایک شخص سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا بستر اس طرح بچھایا جاتا جس طرح انسان اپنی قبر میں لٹایا جاتا ہے، اور مسجد (نماز پڑھنے کی جگہ یا مسجد نبوی) آپ کے سرہانے ہوتی۔","ضعیف",{"u2":"جناب ابوقلابہ نے سیدہ ام سلمہ رضی اللہ عنہا ا کے خاندان میں سے کسی فرد سے روایت کیا کہ نبی کریم صلی اللہ علیہ وسلم کا بستر ایسے بچھایا جاتا تھا جیسے انسان قبر میں رکھا جاتا ہے اور مسجد آپ صلی اللہ علیہ وسلم کے سر کی طرف ہوتی تھی۔","f2":"یہ روایت اگرچہ ضعیف ہے۔ لیکن دیگر صحیح احادیث میں یہ ہے کہ نبی کریم صلی اللہ علیہ وسلم قبلہ رو ہوکر دایئں کروٹ پر سوتے تھے۔ جیسے کے اگلی روایت میں آرہا ہے۔اس طرح مسجد نبوی آپ کے سر کی جانب ہوتی تھی۔ بعض نے یہ بھی مفہوم بیان کیا ہے۔کہ آپ صلی اللہ علیہ وسلم کامصلیٰ اور جائے نماز تہجد کےلئے آپ کے سر کے پاس ہی ہوتا تھا۔غرض یہ ہے کہ آپ صلی اللہ علیہ وسلم سوتے وقت بھی زکر اور عبادت کی تیاری سے غافل نہیں رہتے تھے۔"}],[5045,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سونے کا ارادہ فرماتے تو اپنا داہنا ہاتھ اپنے گال کے نیچے رکھتے، پھر تین مرتبہ «اللهم قني عذابك يوم تبعث عبادك» \"اے اللہ جس دن تو اپنے بندوں کو اٹھائے اس دن مجھے اپنے عذاب سے بچا لے\" کہتے۔","صحیح",{"u2":"ام المؤمنین سیدہ حفصہ رضی اللہ عنہا ا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سونا چاہتے تو اپنا دایاں ہاتھ اپنے رخسار کے نیچے رکھ لیتے ‘ پھر یہ دعا پڑھتے «اللهم قني عذابك يوم تبعث عبادك» ” اے ا اللہ! جس دن تو اپنے بندوں کو اٹھائے مجھے اپنے عذاب سے محفوظ رکھنا۔ “ یہ کلمات تین بار دہراتے۔"}],[5046,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"جب تم اپنی خواب گاہ میں آؤ (یعنی سونے چلو) تو وضو کرو جیسے اپنے نماز کے لیے وضو کرتے ہو، پھر اپنی داہنی کروٹ پر لیٹو، اور کہو «اللهم أسلمت وجهي إليك وفوضت أمري إليك وألجأت ظهري إليك رهبة ورغبة إليك لا ملجأ ولا منجى منك إلا إليك آمنت بكتابك الذي أنزلت وبنبيك الذي أرسلت» \"اے اللہ میں نے اپنی ذات کو تیری تابعداری میں دے دیا، میں نے اپنا معاملہ تیرے سپرد کر دیا، میں نے امید وبیم کے ساتھ تیری ذات پر بھروسہ کیا، تجھ سے بھاگ کر تیرے سوا کہیں اور جائے پناہ نہیں، میں ایمان لایا اس کتاب پر جو تو نے نازل فرمائی ہے، اور میں ایمان لایا تیرے اس نبی پر جسے تو نے بھیجا ہے\" آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم (یہ دعا پڑھ کر) انتقال کر گئے تو فطرت (یعنی دین اسلام) پر انتقال ہوا اور اس دعا کو اپنی دیگر دعاؤں کے آخر میں پڑھو\" براء کہتے ہیں: اس پر میں نے کہا کہ میں انہیں یاد کر لوں گا، تو میں نے (یاد کرتے ہوئے) کہا «وبرسولك الذي أرسلت» تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا نہیں بلکہ«وبنبيك الذي أرسلت» (جیسا دعا میں ہے ویسے ہی کہو)\"۔","صحیح",{"u2":"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا ” جب اپنے بستر پر جانے لگو تو وضو کر لیا کرو جیسے نماز کے لیے کرتے ہو ‘ پھر اپنی دائیں کروٹ پر لیٹ جاؤ اور کہو «اللهم أسلمت وجهي إليك وفوضت أمري إليك وألجأت ظهري إليك رهبة ورغبة إليك لا ملجأ ولا منجى منك إلا إليك آمنت بكتابك الذي أنزلت وبنبيك الذي أرسلت» ” اے ا اللہ! میں نے اپنا چہرہ تیرے تابع کر دیا اور اپنا معاملہ تیرے سپرد کر دیا ‘ اپنی کمر تیری طرف لگا لی (تجھے ہی اپنا سہارا بنا لیا) مجھے تیرا ہی ڈر ہے اور شوق بھی تیری طرف ہے۔ تجھ سے بھاگ کر کے میرے لیے تیرے سوا کہیں کوئی جائے پناہ اور جائے نجات نہیں۔ میں تیری اس کتاب پر ایمان لایا جو تو نے نازل کی ہے اور اس نبی کو تسلیم کیا جسے تو نے رسول بنا کر بھیجا ہے۔ “ آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر تو (اس رات میں) مر گیا تو فطرت (دین اسلام) پر مرے گا۔ اور چاہیئے کہ یہ تیری آخری بات ہو (اس کے بعد کوئی اور گفتگو نہ ہو)۔ “ سیدنا براء رضی اللہ عنہ کہتے ہیں میں نے اس دعا کو یاد کرتے ہوئے دہرایا تو لفظ کہہ دیے «وبرسولك الذي أرسلت» ” میں تیرے اس رسول پر ایمان لایا جسے تو نے بھیجا ہے۔ “ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں (بلکہ جو الفاظ میں نے تمہیں پڑھائے ہیں وہی یاد کرو ‘ اور وہ الفاظ ہیں) «وبنبيك الذي أرسلت» ” میں تیرے اس نبی پر ایمان لایا جسے تو نے رسول بنا کر بھیجا ہے۔ “"}],[5047,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"جب تم پاک و صاف (باوضو) ہو کر اپنے بستر پر (سونے کے لیے) آؤ تو اپنے داہنے ہاتھ کا تکیہ بناؤ\" پھر انہوں نے اسی طرح کی حدیث ذکر کی۔","صحیح",{"u2":"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ فرمایا ” جب تم اپنے بستر پر آنے لگو اور باوضو ہو تو اپنی داہنی جانب پر لیٹو۔ “ پھر مذکورہ بالا حدیث کی مانند ذکر کیا۔"}],[5048,"اس سند سے بھی براء رضی اللہ عنہ سے یہی حدیث نبی اکرم صلی اللہ علیہ وسلم سے مرفوعاً مروی ہے، سفیان ثوری کہتے ہیں: ایک راوی نے «إذا أتيت فراشك طاهرا» \"جب تم باوضو اپنے بستر پر آؤ\" کہا اور دوسرے نے «توضأ وضوءك للصلاة» \"تم جب نماز جیسا وضو کر لو\" کہا اور آگے راوی نے معتمر جیسی روایت بیان کی۔","صحیح",{"u2":"سیدنا براء (براء بن عازب) رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے یہی حدیث روایت کی۔ سفیان نے (اپنے اساتذہ اعمش اور منصور کے متعلق) کہا کہ ان میں سے ایک کے الفاظ یہ تھے ” جب تم باوضو ہو کر اپنے بستر پر آؤ۔ “ اور دوسرے نے کہا: ” جب تم اپنے بستر پر آنے کا ارادہ کرو تو وضو کر لو جیسے نماز کے لیے کرتے ہو۔ “ اور معتمر (کی گزشتہ روایت 5046) کے ہم معنی بیان کی۔","f2":"سونے سے پہلے نماز والا وضو کرلینا دایئں کروٹ پر لیٹنا اور مسنون دعایئں یا ان میں سے کسی ایک کا پڑھنااز حد تاکیدی سنتیں ہیں۔2۔افضل یہ ہے کہ دعا کے بعد کوئی گفتگو نہ ہو۔ 3۔شرعی امور بالخصوص عبادت کے اعمال میں اپنی مرضی سے کمی بیشی جائز نہیں۔حتیٰ کہ نبی کریم صلی اللہ علیہ وسلم نے اس دعا کے ایک لفظ کو دوسرے ہم معنی لفظ سے بدلنا بھی قبول نہیں فرمایا۔جبکہ بعض لوگ کہہ دیتے ہیں کہ اس طرح سے کوئی فرق نہیں پڑتا۔حالانکہ اس سے بہت فرق پڑتا ہے۔اور اسے وہی شخص سمجھ سکتا ہے۔جس کے دل میں سنت کی محبت جاگزیں ہو۔4۔والدین اور سرپرستوں پر واجب ہے۔کہ نوخیز بچوں کی عادات کو ابتداء ہی سے سنت کے مطابق ڈھالنے کی کوشش کریں۔"}],[5049,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سونے کے وقت فرماتے: «اللهم باسمك أحيا وأموت» \"اے اللہ میں تیرے ہی نام پر جیتا اور مرتا ہوں\" اور جب بیدار ہوتے تو فرماتے «الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور» \"شکر ہے اللہ کا جس نے ہمیں زندگی بخشی (ایک طرح سے) موت طاری کر دینے کے بعد اور اسی کی طرف اٹھ کر جانا ہے\"۔","صحیح",{"u2":"سیدنا حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب سونے لگتے تو یہ دعا پڑھتے تھے «اللهم باسمك أحيا وأموت» ” اے ا اللہ! تیرے ہی نام سے میں زندہ ہوتا اور مرتا ہوں۔ یعنی سوتا اور جاگتا ہوں۔ “ اور جب جاگتے تو یہ پڑھتے «الحمد لله الذي أحيانا بعد أماتنا وإليه النشور» ” تمام تعریفیں اس ا اللہ کی ہیں جس نے ہمیں مارنے کے بعد زندہ کیا (نیند کے بعد جگایا) اور اسی کی طرف اٹھنا ہے۔ “"}],[5050,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تم میں سے کوئی اپنے بستر پر سونے کے لیے آئے تو اپنے ازار کے کونے سے اسے جھاڑے کیونکہ اسے نہیں معلوم کہ اس کی جگہ اس کی عدم موجودگی میں کون آ بسا ہے، پھر وہ اپنے داہنے پہلو پر لیٹے، پھر کہے «باسمك ربي وضعت جنبي وبك أرفعه إن أمسكت نفسي فارحمها وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين» \"تیرے نام پر میں اپنا پہلو ڈال کر لیٹتا ہوں اور تیرے ہی نام سے اسے اٹھاتا ہوں، اگر تو میری جان کو روک لے تو تو اس پر رحم فرما اور اگر چھوڑ دے تو اس کی اسی طرح حفاظت فرما جس طرح تو اپنے نیک بندوں کی حفاظت فرماتا ہے\" ۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی اپنے بستر پر آنے لگے تو چاہیئے کہ اپنے بستر کو اپنی چادر کے پلو سے جھاڑ لے ‘ کیا خبر اس کے بعد اس پر کوئی چیز آ گئی ہو ‘ پھر اپنی دائیں کروٹ پر لیٹ جائے اور یہ دعا پڑھے «باسمك ربي وضعت جنبي وبك أرفعه إن أمسكت نفسي فارحمها وإن أرسلتها فاحفظها ب تحفظ به عبادك الصالحين» ” تیرے ہی نام سے اے میرے رب! میں نے اپنا پہلو رکھا ہے اور تیرے ہی نام سے اسے اٹھاؤں گا۔ اگر تو میری جان کو روک لے (موت دیدے) تو اس پر رحم فر اور اگر چھوڑ دے تو اس کی حفاظت فر جس طرح تو اپنے نیک بندوں کی حفاظت فرماتا ہے۔ “","f2":"سونے سے پہلے بستر کو جھاڑ لینا سنت ہے۔2۔حدیث میں مذکور دعا کے آخری الفاظ (الصالحين من عبادك) بعض کتب حدیث میں اس طرح بھی ہے۔(عبادك الصالحين)لہذا دعا میں دونوں طرح کے الفاظ درست ہیں۔دیکھئے۔(صحیح البخاری الدعوات حدیث 6320)"}]]);
